\section{Problem formulation} \label{Sect: problem formulation}
%=================================================================

This article considers the approximate output regulation problem for a class of nonlinear systems of the form
\begin{equation} \label{eqn: general nonlinear system dynamics}
    \begin{aligned}
        \dot{z} &= f_z(z,y,w,\sigma) \\
        \dot{y} & =  q(z,y, w,\sigma) + b(w,\sigma) u  
        %e & = y - y_0
    \end{aligned}
\end{equation}
%
where $(z, y) \in \mathds{R}^{n_z} \times \mathds{R}$ are the system states, $u \in \mathds{R}$ is the control input, $y$ is the measured output to be regulated, and $\sigma \in \mathds{R}^{n_\sigma}$ is an uncertain parameter. 
 $w  \in \mathds{R}^{n_w}$ denotes the exogenous signal representing both the reference signal to be tracked and the disturbance signal to be rejected, and it is generated by the exosystem:
\begin{equation} \label{eqn: exosystem system}
   \begin{aligned}
        \dot{w} & = s(w, \sigma), \\
        y_0 & = h(w,\sigma),
    \end{aligned} 
\end{equation}
where $y_0 \in \mathds{R}$ is the exogenous signal's output. Define the regulated error $e \in \mathds{R}$ as 
%
\begin{align}\label{EQN: error system}
    e = y -  h(w,\sigma).
\end{align}
