We formally define the robust practical output regulation problem composed of systems \eqref{eqn: general nonlinear system dynamics}, \eqref{eqn: exosystem system} and \eqref{EQN: error system} as follows:
%
\begin{problem} \label{Prob: Practical Output regulation}
Consider systems \eqref{eqn: general nonlinear system dynamics}, \eqref{eqn: exosystem system}, and \eqref{EQN: error system} and given any compact set $\mathds{W}$ and $\Sigma$ containing the origin, design an output feedback control law such that, for every initial condition $w(0) \in \mathds{W}$, and $\sigma(0) \in \Sigma$ and any states $(z(0), y(0)) \in \mathds{R}^{n_z} \times \mathds{R}$, the solution of the closed-loop system exists and is bounded for all $t \geq 0$, and $$ \lim\limits_{t\rightarrow\infty} |e (t)| \leq \varepsilon, $$
where $\varepsilon$ is a sufficiently small number. 
\end{problem}

We make some standard assumptions required for the solution of the output regulation problem.
%
%\begin{assumption} \label{ASS: compact set}
%    The dynamics of the exosystem \eqref{eqn: exosystem system} are such that $w(t)$ evolves in a compact invariant set $\mathds{W} \subset \mathds {R}^p $. %This implies that the eigenvalues of $n_\eta$ are semi-simple with zero real parts
%\end{assumption}
%
\begin{assumption}\label{ASS: positive and lower bounded b(w,sigma)}
    The function $b(w,\sigma) $ is continuous, $b(w,\sigma)  > 0$, and lower bounded by some positive contant $b^\star$ for all $w \in \mathds{R}^w$ and all $\sigma \in \mathds{R}^{n_\sigma}$
\end{assumption}
\begin{assumption}  \label{ASS: exosystem input satisfies ISS}(Solvability of regulator equation).
    There exists a smooth functions  $\mathbf{z}^\star(w,\sigma)$ with $\mathbf{z}^\star(0,\sigma) = 0$ such that, for all $(w, \sigma) \in \mathds{W}  \times \Sigma $,
    %
    %
    \begin{equation}
         \frac{\partial \mathbf{z}^\star (w,\sigma)}{\partial w} s(w,\sigma) = f(\mathbf{z}^\star(w,\sigma), \mathbf{y}^\star (w,\sigma), w,\sigma)
    \end{equation}
%    and input $x$ satisfies the following: (i) $L_{s(w)}\mathbf{z}(w) = f(w, \mathbf{z}(w), 0) $. (ii) input-to-state stability relative to the compact set $\mathcal{A} = \{(w,z) \in \mathds{W} \times \mathds{R}^{n_z}: z = \mathbf{z}(w) \} $ with respect to the input $x$ with locally Lipschitz asymptotic gain. That is, there exist a $\beta_0 \in \mathcal{K L}$ and a locally Lipschitz $\rho_0 \in \mathcal{K}$ such that every solution pair to \eqref{eqn: ISS assumption} originating in $\mathds{W} \times \mathds{R}^{n_z} $ satisfies 
 %   $|(w(t), z(t)|_\mathcal{A} \leq \max \{\beta_0(|(w(0), z(0)|_\mathcal{A}, t), \rho_0(|x|_t) \} $ for every $t\in \mathds{R}_{\geq 0}$
\end{assumption}
%
Under Assumptions \ref{ASS: positive and lower bounded b(w,sigma)} and \ref{ASS: exosystem input satisfies ISS}, %let $\mathbf{y}(w,\sigma) = h_0(w,\sigma)$, then
the ideal control input required to regulate the error $e$ to zero is given by:
 %
\begin{align}\label{eqn: ideal steady-state control input}
    \begin{split}
        \mathbf{u}^\star( w,\sigma)   = &\ b(w,\sigma)^{-1} 
        \Big( \frac{\partial h (w,m)}{\partial w} s(w,\sigma)  \\& - q(\mathbf{z}^\star (w,\sigma),\mathbf{y}^\star (w,\sigma), w, \sigma) \Big)
    \end{split}
\end{align}
%
The functions $\mathbf{y}^*(w,\sigma)$, $\mathbf{z}^\star (w,\sigma)$, and $\mathbf{u}^\star(w,\sigma)$ constitute a solution to the so-called regulator equations \cite{Isidori-Byrnes1990, HuangJ-2004}.
%
The function $\mathbf{u}^\star(w,\sigma)$ provides the necessary feedforward control action to maintain zero regulation error when the system is at steady state. Any regulator capable of generating the feedforward control action $\mathbf{u}^\star(w,\sigma)$ is said to possess the \emph{``internal model property"} \cite{Isidori-Byrnes1990}. 
%
Although the expression of $\mathbf{u}^\star(w,\sigma)$ can be easily derived, it cannot be used for feedback control design, as it contains the exogenous signal $w$ and the unknown parameter $\sigma$.
%
In practice, an internal model is designed to reproduce $\mathbf{u}^\star(w,\sigma)$ asymptotically. 


