\subsection{Hybrid Dynamical Systems}

This article proposes a regulator described by a hybrid system using the formalism of \cite{goedel2012hybrid}. We consider a hybrid system $\mathcal{H}$ with state $x \in \mathds{X}$ and input $u \in \mathcal{U}$ of the form
%
%$\bm{\mathcal{H}}(f,g, \mathcal{C}, \mathcal{D}) $ of the form
%
\begin{equation} \label{EQN: classic hybrid system}
\mathcal{H}: \quad
    \begin{cases} 
       \quad (x,u) \in \mathcal{C}, \: \:\:\:\:\:\:\: \:\:\:  \dot{x} = f(x,u)  \\
      \quad (x,u) \in \mathcal{D}, \: \:\:\:\:\:\:\: \: \:    x^+ = g(x,u)   
   \end{cases}
 \end{equation}
where $\mathcal{C}$ denotes the \emph{flow set} and  $\mathcal{D}$ denotes the \emph{jump set}. The flow equation describes the continuous evolution of the state $x$. The jump equation describes the discontinuous evolution of the state. The vector fields $f$ and $g$ are assumed to be continuous on $\mathcal{C}$ and $\mathcal{D}$, respectively.  The solutions of system \eqref{EQN: classic hybrid system} are defined on a hybrid time domain. We recall some definitions related to the hybrid formulation from \cite{goedel2012hybrid}.
\begin{definition} (Hybrid time domains)
A subset $E \subset \mathds{R}_{\geq 0} \times \mathds{N}$ is a {\em hybrid time domain} if, for all $(T,J) \in E$, $$E \cap ([0,T] \times \{0,1,\cdots{}, J\}) = \bigcup_{j = 0}^{J-1}([t_j, t_{j+1}], j) $$ for some finite sequence of times $0 = t_0 \leq t_1 \leq \cdots \leq t_J$.   
\end{definition}
%
\begin{definition} (Hybrid arc)
A function $\phi: E \rightarrow \mathds{R}^n$ is a {\em hybrid arc} if $E$ is a hybrid time domain and if, for each $j \in \mathds{N}$, the function $t \mapsto \phi(t,j)$ is locally absolutely continuous on the internal $I^j = \{t: \; (t,j) \in E \}$   
\end{definition}
%
%\begin{definition}\label{Def: Hybrid system ISS definition}(ISS definition \cite{Cai_Teel-2013})
%    System $\mathcal{H} $ is input-to-state stable (ISS)  
%    w.r.t. $\omega, |\cdot|)$ if there exist $\gamma \in \mathcal{KLL}$ and $k \in \mathcal{K}$ such that, for each $\xi \in \mathds{X}$, each pair $(x,u) \in \delta_u(\xi)$ satisfies
%    \begin{equation*}
%        \omega(x(t,j,\xi,u)) \leq \max \{ \gamma(\omega(\xi),t,j), k(\norm{u}_{(t,j)}\},  
%    \end{equation*}
%    $\forall(t,j) \in \mbox{dom} \: x$
%\end{definition}
%
\begin{definition}\label{Definition: Local pre-asymptotic stability}(Local pre-asymptotic stability (LpAS)) Let $\mathcal{H}$ be a hybrid system in $\mathds{R}^n$. A compact set $\mathcal{A} \subset \mathds{R}^n$ is said to be
\begin{itemize}
    \item {\em stable for $\mathcal{H}$} if, for every $\varepsilon > 0$, there exists $\delta > 0$ such that every solution $\phi$ to $\mathcal{H}$  with $|\phi(0,0)|_\mathcal{A} \leq \delta$ satisfies $|\phi(t,j)|_\mathcal{A} \leq \varepsilon$ for all $(t,j) \in \text{dom} \; \phi$;
    \item {\em locally pre-attractive for $\mathcal{H}$} if there exists $\mu > 0$ such that every solution $\phi$ to $\mathcal{H}$ with $|\phi(0,0)|_\mathcal{A} \leq \mu$ is bounded and, if $\phi$ is complete, then also $\lim_{t+j \rightarrow \infty} |\phi(t,j)|_\mathcal{A} = 0$;
    \item {\em locally pre-asymptotically stable for $\mathcal{H}$} if is both stable an locally pre-attractive for $\mathcal{H}$.
\end{itemize}  
\end{definition}

