%\textcolor{red}{The $\mathcal{GP}$ model continuously learns the unknown nonlinear map from the training data $\mathcal{DS}$ and the more the training data the better the model's predictive performance.} 

The $\mathcal{GP}$ model incrementally learns the unknown nonlinear mapping $\upvarpi$ from the training dataset $\mathcal{D}_S$.
Its learning rate is characterized by a learning curve that relates the Bayesian generalization error $\epsilon_D$
  to the size of the training dataset, and it is independent of the test points \cite{Francesco-thesis-1998}. For a noise-free output, the Bayesian generalization error $\epsilon_D$
  at a given test point $\upvarpi(\bm{\eta}^\star)$
  is defined as
\begin{equation}\label{EQN: Bayesian generalization error}
\epsilon_D = \left(\mu(\bm{\eta}^\star) - \upvarpi(\bm{\eta}^\star)\right)^2.
\end{equation}
%where $\mu(\bm{\eta}^\star)$ is the $\mathcal{GP}$ predicted mean at the test point, and $\upvarpi(\bm{\eta}^\star)$ is the true value of the function at the same point. 
For a noise-free output, it can be readily shown that the posterior variance, as given by \eqref{EQN: GP variance}, is equivalent to the expected value of the Bayesian generalization error $\epsilon_D$ for a given a training dataset $\mathcal{D}_S$ \cite{Francesco-thesis-1998}.

%, \eqref{EQN: Bayesian generalization error} at test point assumed to be generated by $\upvarpi(\bm{\eta}^\star)$. The reader should see \cite{Francesco-thesis-1998} for additional information.

\begin{assumption}\label{Ass: Unknown function is a Gaussian Process}
    The unknown function $\upvarpi(\bm{\eta^\star})$ is a sample drawn from the Gaussian process $(\mathcal{GP})$ with zero mean and covariance (kernel) function $K(\bm{\eta}, \bm{(\eta')}$, i.e.,
    $$\upvarpi(\bm{\eta}) \sim \mathcal{GP}(0, K(\bm{\eta}, \bm{\eta'})).$$
\end{assumption}

%We make some standard assumptions relevant to our work. 

\begin{assumption}\label{Ass: Bounded RKHS}
    The unknown function $\upvarpi$ has a bounded norm  under the \textbf{RKHS} generated by the kernel $K(\bm{\eta},\bm{\eta'})$.  
\end{assumption}

\begin{assumption}\label{Ass: Gaussian Process - Lipschitz}
The covariance kernel $K(\bm{\eta},\bm{\eta'})$ is smooth and Lipschitz continuous with a constant $\mathcal{L}_k$. %Furthermore, its {\color{red} Which norm? } norm is bounded by $\mathcal{L}_{\thickbar{k}}$.

\end{assumption}
Assumptions \ref{Ass: Bounded RKHS} and \ref{Ass: Gaussian Process - Lipschitz} are standard in the literature, see \cite{ Lederer-Umlauft-Sandra-2019, Gentilini-Bin-Marconi-2022}. Assumption \ref{Ass: Bounded RKHS} ensures that the unknown function is not discontinuous.  Moreover, Assumption \ref{Ass: Gaussian Process - Lipschitz} is inherently satisfied by most commonly used covariance functions, such as the squared exponential kernel defined in \eqref{EQN: squared exponential kernel function}. 

Next, we present key results from the literature that will serve as the basis for establishing our results.

\begin{lemma} \label{LEMMA: Upper bounds for GP}\cite[Thm.\ 9]{Lederer-Umlauft-Sandra-2019}
    Consider a zero mean Gaussian process defined through the continuous covariance kernel $K(\cdot,\cdot)$ with Lipschitz constant $L_k$ on the compact set $\mathds{X}$. Furthermore, consider a continuous unknown function $f : \mathds{X} \to \mathbb{R}$ with Lipschitz constant $L_f$ and $r \in \mathbb{N}$ observations $y^{(i)}$ satisfying Assumptions \ref{Ass: Unknown function is a Gaussian Process} and \ref{Ass: Bounded RKHS}. Then, the posterior mean $\mu(\cdot)$ and posterior standard deviation $\sigma^2(\cdot)$ of a Gaussian process conditioned on the training data $\{(x^{(i)}, y^{(i)})\}_{i=1}^r$ are continuous with Lipschitz constants $L_{\mu_r}$ and $L_{\sigma^2_r}$ on $\mathds{X}$, respectively, where
\begin{align*}
    L_{\mu_r} &\leq L_k \sqrt{r} \left\| \left( \bm{K}(X_r, X_r) + \sigma_n^2 I_r \right)^{-1} \bm{y}_r \right\|, \\
    L_{\sigma^2_r} &\leq 2\rho L_k \!\left( 1 + r \left\| \left( \bm{K}(X_r, X_r) + \sigma_n^2 I_r \right)^{-1} \right\| \max_{x, x' \in \mathcal{X}} k(x, x') \right)
\end{align*}
Moreover, pick $\delta \in (0,1)$, $\rho \in \mathbb{R}_+$ and set
\begin{align*}
    \beta(\rho) &= 2 \log\!\left( \frac{M(\rho, \mathds{X})}{\delta} \right), \\
    \gamma(\rho) &= (L_{\mu_r} + L_f)\rho + \sqrt{\beta(\rho)} L_{\sigma^2_r} \rho,
\end{align*}
where $M(\rho, \mathcal{X})$ denotes the $\rho$-covering number\footnote{The minimum number satisfying $\min_{x\in \mathds{X}} \max_{x' \in \mathcal{D_S}} \|x - x'\| \leq \rho $} of $\mathds{X}$, i.e., the minimum number such that there exists a set $\mathds{X}_\rho$ satisfying $|\mathds{X}_\rho| = M(\rho, \mathds{X})$ and $\forall x \in \mathds{X}$ there exists $x' \in \mathds{X}_\rho$ with $\|x - x'\| \leq \rho$. Then the bound
%\[
%P\left( \left| f(x) - \nu_r(x) \right| \leq \sqrt{\beta(\rho)} \sigma_r(x) + \gamma(\rho), \ \forall x \in \mathcal{X} \right) \geq 1 - \delta.
%\]
\begin{equation*}
    \left| f(x) - \mu_r(x) \right| \leq \sqrt{\beta(\rho)} \sigma_r(x) + \gamma(\rho), \ \forall x \in \mathds{X} 
\end{equation*}
holds with probability of at least $1 - \delta$
\end{lemma}
