We show that $\sigma_{n+1}^2(\thickbar{\eta}) < \sigma_n^2(\thickbar{\eta})$. We recall the predictive variance given in \eqref{EQN: GP variance} and let the Gram matrix $\thickbarBig{K} = K + \sigma_n^2 I$. The $(n+1) \times 1$ vector $\bm{K}_*$ can be partitioned into a vector $\mathbf{k}_n$ and a scalar $\mathbf{c}$, i.e.,  $$\bm{K}_*(\thickbar{\eta}) = \begin{bmatrix}
    \mathbf{k}_{n}(\thickbar{\eta}) & \mathbf{c}(\thickbar{\eta}) 
\end{bmatrix}^{\top}$$ with $\mathbf{k}_{n}(\thickbar{\eta}) =\col(\bm{K}(\bm{\eta}, \bm{\eta}_1), \cdots{}, \bm{K}(\bm{\eta}, \bm{\eta}_n)) $ and $\mathbf{c}(\thickbar{\eta}) = \bm{K}(\bm{\eta}, \bm{\eta}_{n+1})$.
%
Let the $(n+1){\text{th}}$ element be denoted by $\thickbar{\eta}'$. The $(n+1) \times (n+1)$ Gram matrix can be partitioned into four sub-matrices:
%
%
\begin{align*}
    \thickbarBig{\bm{K}}_{n+1}  & = 
    \begin{bmatrix}
        Q_n &  \mathbf{k}_n(\thickbar{\eta}') \\
       \mathbf{k}_n^{\top}(\thickbar{\eta}') &  \mathbf{c}(\thickbar{\eta}')
    \end{bmatrix},\;\;
    \thickbarBig{\bm{K}}^{-1}_{n+1}  = 
    \begin{bmatrix}
        \tilde{Q}_n &  \tilde{\mathbf{k}}_n(\thickbar{\eta}') \\
       \tilde{\mathbf{k}}_n^{\top}(\thickbar{\eta}') & \tilde{\mathbf{c}}(\thickbar{\eta}').
    \end{bmatrix}
\end{align*}
The matrix $Q_n$ is the $n \times n$ covariance matrix of a $\mathcal{GP}$ trained with $n$ datasets. The inverse of the Gram matrix $\thickbarBig{\bm{K}}^{-1}_{n+1} $ can be obtained by applying the matrix inversion lemma \cite[Section \textbf{A.3}] {Rasmussen_Williams2006}
where
\begin{align*}
    \tilde{Q}_n & =  Q_n^{-1} + Q_n^{-1}\mathbf{k}_n(\thickbar{\eta}')M^{-1} \mathbf{k}^{\top}_n(\thickbar{\eta}') Q_n^{-1}, &\\
    S & =  \tilde{\mathbf{c}}(\thickbar{\eta}') - \mathbf{k}^{\top}_n(\thickbar{\eta}') Q_n^{-1}  \mathbf{k}_n(\thickbar{\eta}'),   &\\
    \tilde{\mathbf{k}}_n(\thickbar{\eta}')  & = - Q_n^{-1}\mathbf{k}_n(\thickbar{\eta}')  M^{-1},  \\
    \tilde{\mathbf{c}}_n(\thickbar{\eta}') & =  S^{-1}.
\end{align*}
%
We now proceed to compute the posterior variance $\sigma_{n+1}^2(\thickbar{\eta})$ using \eqref{EQN: GP variance}, which signifies the uncertainty of the $\mathcal{GP}$ model's predictions at a given test point $\thickbar{\eta}$ after incorporating $n + 1$ training data points:
\begin{align}
\begin{split}
 \sigma_{n+1}^2(\thickbar{\eta}) =  &\ \bm{K}(\eta, \eta) - 
    \begin{bmatrix}
        \mathbf{k}_n(\thickbar{\eta}) \\
        \mathbf{c}(\thickbar{\eta})
      \end{bmatrix}^{\top}
       \thickbarBig{\bm{K}}_{n+1}^{-1}
       \begin{bmatrix}
         \mathbf{k}_n(\thickbar{\eta}) \\
        \mathbf{c}(\thickbar{\eta})
      \end{bmatrix}\\
    = &\ \bm{K}(\eta, \eta) - \mathbf{k}_{n}^{\top}(\thickbar{\eta}) Q^{-1} \mathbf{k}_{n}(\thickbar{\eta})  \\
    &\    - \frac{(\mathbf{k}_{n}^{\top}(\thickbar{\eta})Q^{-1} \mathbf{k}_{n}(\thickbar{\eta}') - \mathbf{c}(\thickbar{\eta}') )^2 }{\sigma_n^2(\thickbar{\eta}')}.
\end{split} \nonumber
\end{align}
The first two terms represent the posterior variance, denoted as $\sigma_n^2(\thickbar{\eta})$, for the $\mathcal{GP}$ model obtained using $n$ training data points. Thus, we obtain:
%
\begin{align*}
   \sigma_{n+1}^2(\thickbar{\eta})  = \sigma_{n}^2(\thickbar{\eta}) - \frac{(\mathbf{k}_{n}^{\top}(\thickbar{\eta})Q^{-1} \mathbf{k}_{n}(\thickbar{\eta}') - \mathbf{c}(\thickbar{\eta}') )^2 }{\sigma_n^2(\thickbar{\eta}')}. 
\end{align*}
%
Define 
 $$\Upgamma(\thickbar{\eta})  \coloneqq \frac{(\mathbf{k}_{n}^{\top}(\thickbar{\eta})Q^{-1} \mathbf{k}_{n}(\eta') - \mathbf{c}(\eta') )^2 }{\sigma_n^2(\eta')},$$ then:
%
\begin{align}
   \sigma_{n+1}^2(\thickbar{\eta})  = \sigma_{n}^2(\thickbar{\eta}) - \Upgamma(\thickbar{\eta}).\end{align}
%
Since $\Upgamma(\thickbar{\eta}) \geq 0$, it follows that 
$$ \sigma_{n+1}^2(\thickbar{\eta}) < \sigma_n^2(\thickbar{\eta}).$$
if $\mathbf{k}_{n}^{\top}(\thickbar{\eta})Q^{-1} \mathbf{k}_{n}(\thickbar{\eta}') > \mathbf{c}(\thickbar{\eta}') $, indicating that the uncertainty in the model predictions decreases as new training data are incorporated. However, if $$\mathbf{k}_{n}^{\top}(\thickbar{\eta})Q^{-1} \mathbf{k}_{n}(\thickbar{\eta}') < \mathbf{c}(\thickbar{\eta}'), $$ then 
$$ \sigma_{n+1}^2(\thickbar{\eta}) \approx \sigma_n^2(\thickbar{\eta})$$ which implies that no further improvement in the $\mathcal{GP}$ model is obtainable. Under these conditions, the Lyapunov function during a jump satisfies
\begin{align} \label{EQN: Jump Lyanpunov analysis for theorem - result - condition 1}
    \begin{split}
        V(g(\chi))  -   V(\chi)  \leq   0
    \end{split}    
    \end{align}
%
Therefore, the solution $\phi$ of the hybrid system $\mathcal{H}_\mu$, is bounded and converges to $\varepsilon_\mu$ as $t\rightarrow \infty$ and $j\rightarrow \infty$. Thus, we prove that $|\phi(t,j)|_{\mathcal{A}} \leq  \varepsilon_\mu $  as (t, j) $\rightarrow \infty \times \infty$, which implies that the error signal enters the set where $|e| \leq \varepsilon_\mu$. This completes the proof. 
\end{Proof}




\begin{remark} \label{Remark: GP prediction inproves with training data}
    The performance of the $\mathcal{GP}$ model progressively improves as more training data are incorporated. As a result, the radius of ball $C_\mu$, centered around zero and representing the uncertainty or error bound, will continue to shrink. This iterative refinement persists until the radius reaches its minimal value.
\end{remark}



