\subsection{Training Data Collection and Algorithm Implementation}
%At the first continuous cycle, there is no historical data to train the $\mathcal{GP}$ model, hence the control law implemented is $u = k_p \rho(e) e$. Then in the jump event, all the data (solution from the ODE solver) obtained  $\bm{\eta} = \{\eta(t_1), \cdots, \eta(t_n)\}$ and $\bm{u} = \{u(t_1), \cdots, u(t_n)\}$ is used to trained the $\mathcal{GP}$ model. The trained $\mathcal{GP}$ model is then used for prediction in the next continuous cycle with control law given in equation \eqref{eqn: control-law regulator equation} using a zero order hold as illustrated in Figure \ref{Fig: Regulator Block diagram}. Subsequently more data are added to the training data set during each jump cycle

In the initial continuous cycle, no historical data are available to train the $\mathcal{GP}$ model. Therefore, the control law \eqref{eqn: control-law regulator equation} is implemented without adaptation i.e., $u = k_p \rho(e) e$. During the jump event, all collected data, comprising the internal model unit trajectory $$\bm{\eta} = \{\eta(t_1), \cdots, \eta(t_n)\}$$ obtained from the ODE solver and the corresponding control inputs $$\bm{u} = \{u(t_1), \cdots{}, u(t_n)\}$$, are utilized to train the $\mathcal{GP}$ model. 
%
In subsequent continuous cycles, the trained $\mathcal{GP}$ model is employed for prediction, and the control law is implemented as defined in \eqref{eqn: control-law regulator equation}.
At each subsequent jump event, new data points are appended to the existing training dataset, continuously enriching the $\mathcal{GP}$ model with more information.

Gaussian Process models typically involve a computational complexity of $\mathcal{O}(R^3)$ during training due to the matrix inversion step, where $R$ is the size of the training dataset. Although, all previous datasets can be utilized to update the $\mathcal{GP}$ model in theory, this approach can become computationally prohibitive, especially for complex systems, due to the significant increase in time and memory requirements as $R$ grows. To address this challenge, the training process can be limited to only the most recent data points, defined by a sliding window of size $P$. This strategy ensures that the computational cost remains efficient and manageable, even as new data are continuously incorporated.


\begin{algorithm}
\caption{Sliding Window Update for GP Model}
\label{alg:sliding_window}
\begin{algorithmic}[1]
\REQUIRE Sliding window size $\mathcal{W_S}$, internal model unit series $\eta$, control input series $u$, current simulation data $(\bm{\eta}_k, \bm{u}_k)$, $\mathcal{GP}$ model, number of simulation $T_k$
\ENSURE Updated $\mathcal{GP}$ model and predictions
\STATE Initialize window data $ \bm{\mathcal{D_S}} \gets \emptyset$

\FOR{$k = 1$ to $T_k$}
    \STATE Add $(\bm{\eta}_k, \bm{u}_k)$ to $\bm{\mathcal{D_S}}_k$
    \IF{$k < \mathcal{P}$}
        \STATE $\bm{\mathcal{D_S}}_{k+1} = \bm{\mathcal{D_S}}_k \cup \{(\bm{\eta}_k, \bm{u}_k)\}$
        \STATE Continue accumulating data until the window size $W$ is reached
    \ELSIF{$k \geq \mathcal{P}$}
        \STATE $\bm{\mathcal{D_S}}_{k+1} = \{ \bm{\mathcal{D_S}}_k \cup \{(\bm{\eta}_k, \bm{u}_k)\} \backslash \{(\bm{\eta}_{k-\mathcal{W_S}}, \bm{u}_{k-\mathcal{W_S}})\} \}$
    \ENDIF
    \STATE Normalize $\bm{\mathcal{D_S}}_{k+1}$ and train the $\mathcal{GP}$ model
\ENDFOR
\end{algorithmic}
\end{algorithm}




