\begin{equation}\label{EQN: Continuous bioreactor model with three state}
    \begin{aligned}
      \dfrac{\mathrm{d} X}{\mathrm{d} t} &= -D X +\mu(S,P) X,\\
      \dfrac{\mathrm{d} S}{\mathrm{d} t} &= D( S_f - S)- \frac{ \mu(S,P) X}{\gamma_{X/S} } \\
    \dfrac{\mathrm{d} P}{\mathrm{d} t} &= -D P + \big[\alpha\mu(S,P)+\beta\big] X  
%     e &= S - S_p
    \end{aligned}
\end{equation}
where $\mu(S,P)$ is the specific growth rate, $\gamma_{X/S} $ is the cell mass yield, and $\alpha$ and $\beta$ are product yield parameters. 
The signal $e$ is the regulated output.
The growth rate function,
\begin{align}
    \mu(S,P) = \frac{\mu_m \Big(1 - \frac{P}{P_m} \Big)S }{K_m + S + \frac{S^2}{K_i}},
\end{align}
accounts for both production and substrate inhibition, 
where $\mu_m$, $P_m$, $K_m$, and $K_i$ are the maximum specific growth rate, production saturation constant, substrate saturation constant, and substrate inhibition constant, respectively. The cell-mass yield $\gamma_{X/S}$ and maximum specific growth rate $\mu_m$ are sensitive to variations in operating conditions and are considered \emph{measurable disturbances} due to their potential for significant time-varying behaviour \cite{wang2024nonparametric,HENSON_Seborg_1992}. 
%
Assume that the disturbance is generated by the signal
\begin{equation}\label{EQN: cell-mass yield disturbance}
    \gamma_{X/S} = \thickbar{\gamma}_{X/S} + a_0 \sin(\omega t).
\end{equation}
