\title{\bf  A second-order and unconditionally stable time filtered scheme for the Cahn-Hilliard-Navier-Stokes system}
\author{
	Xi Li\footnote{School of Mathematical Sciences, Chengdu University of Technology, Chengdu, Sichuan 610059, China (lixi@cdut.edu.cn). The work of this author is supported by the Natural Science Foundation of Sichuan Province(No. 2025ZNSFSC0070).},
