	\captionsetup[figure]{labelfont={bf},labelformat={default},labelsep=period,name={Fig.}}
	\captionsetup[table]{labelfont={bf},labelformat={default},labelsep=period,name={Tab.}}
	\begin{abstract}
		In this work, we propose, analyze, and test a novel computational low-complexity, linear, second-order, and unconditional energy-stable semi-discrete time-stepping scheme for the Cahn–Hilliard–Navier–Stokes (CHNS) system by employing the time filter technique. Firstly, the first-order semi-implicit backward Euler (BE) method is utilized to discretize the CHNS model; Secondly, the time filter, as a post-processing strategy, is incorporated into the BE scheme, requiring only minimal modifications to the existing BE framework to improve its temporal accuracy from first- to second-order. The unconditional energy stability and second-order temporal error estimations are obtained, and several numerical experiments are conducted to verify the theoretical results.
		\\

		\noindent {\bf Keywords: }{Cahn-Hilliard-Navier-Stokes system; Time filter technique; Unconditional energy stability; Optimal error estimates.}\\
	\end{abstract}
	\baselineskip 15pt
	\parskip 10pt
	\setcounter{page}{1}
	\vspace{-0.5cm}
	\section{Introduction}
	In this draft, we shall consider the low computational complexity, linear, second-order in time, and unconditional energy-stable time-stepping numerical approximation for the following matched-density Cahn-Hilliard-Navier-Stokes (CHNS) model \cite{2017_Diegel_Convergence_analysis_and_error_estimates_for_a_second_order_accurate_finite_element_method_for_the_Cahn_Hilliard_Navier_Stokes_system, 2023_CaiWentao_Optimal_L2_error_estimates_of_unconditionally_stable_finite_element_schemes_for_the_Cahn_Hilliard_Navier_Stokes_system}:
	\begin{subequations}\label{eq_chns_equations}
		\begin{align}
			\label{eq_phi_con}
			\frac{\partial \phi }{\partial t}+(\boldsymbol{u}\cdot\nabla)\phi-  \epsilon \nabla \cdot (M(\phi) \nabla \mu)=0,\quad \text{in} \quad\Omega\times (0, T],&\\
			\label{eq_mu_con}
			\mu + \epsilon\Delta \phi- \epsilon^{-1} \left(\phi^3 - \phi\right)=0,\quad \text{in} \quad\Omega\times (0, T],&\\
			\label{eq_ns_con}
			\frac{\partial \boldsymbol{u}}{\partial t}+(\boldsymbol{u}\cdot\nabla)\boldsymbol{u}-\nu\Delta\boldsymbol{u}+\nabla p-\gamma \mu\nabla\phi=0,\quad\text{in} \quad\Omega\times (0, T],&\\
			\label{eq_incompressi}
			\nabla\cdot\boldsymbol{u}=0,\quad\text{in} \quad\Omega\times (0, T],&
		\end{align}
	\end{subequations}
	with the following boundary and initial conditions 
	\begin{subequations}
		\label{eq_boundary_initial_conditions_equations}
		\begin{align}
			\label{eq_boundary_conditions_equation}
			\frac{\partial \phi}{\partial \mathbf{n}}=\frac{\partial\mu}{\partial \mathbf{n}}=0,\quad\boldsymbol{u}=0,&\quad\text{on}\quad \partial\Omega\times (0,T],\\
			\label{eq_initial_conditions_equation}
			\phi(\mathbf{x},0)=\phi^0,\quad\boldsymbol{u}(\mathbf{x},0)=\boldsymbol{u}^0,&\quad\text{in}\quad \Omega.
		\end{align}
	\end{subequations}
	Here $\Omega\subset\mathbb{R}^d,~(d=2,3)$ is a bounded convex polygonal or polyhedral domain, and for $t\in (0,T]$.
	In this model, $\phi$ represents the phase field variable, and $\mu$ denotes the chemical potential, and the $\boldsymbol{u}$ and $p$ are the velocity and pressure fields of the fluid, respectively.
	$\epsilon$ is the interfacial width between the two phases field, and $M(\phi) > 0$ is the mobility, $\nu = 1/Re$ where $Re$ is the Reynolds number, $\gamma = 1/We^*$ and $We^*$ is the modified Weber number that measures the relative strength of kinetic and surface energies.
    We denote $\phi^3 - \phi =: f(\phi) = F^{\prime}(\phi)$, then the following condition  holds\cite{2010_ShenJie_Energy_stable_schemes_for_Cahn_Hilliard_phase_field_model_of_two_phase_incompressible_flows}: there exists a positive constant $L$ such that 
	\begin{equation}\label{eq_phi_condition}
		\max_{\phi\in \mathbb{R}}~|f'(\phi)|\leq L.
	\end{equation}
    \indent In the past few decades, many numerical methods and analyses, regarding the CHNS equations, have been proposed and studied extensively. Those references may be classified, based on the different motivations, as: 
    (\rmnum{1}) energy-stabilization-oriented formulations, including the convex splitting\cite{2017_Diegel_Convergence_analysis_and_error_estimates_for_a_second_order_accurate_finite_element_method_for_the_Cahn_Hilliard_Navier_Stokes_system}, linear stabilization technique\cite{2017_CaiYongyong_Error_estimates_for_time_discretizations_of_Cahn_Hilliard_and_Allen_Cahn_phase_field_models_for_two_phase_incompressible_flows}, auxiliary variable methods\cite{2017_YangXiaofeng_Numerical_approximations_for_the_molecular_beam_epitaxial_growth_model_based_on_the_invariant_energy_quadratization_method,2018_Shenjie_Xujie_SAV,2025_Gao_CAMWA,2025_Gao_NMTMA}; 
    (\rmnum{2}) computational efficiency-enhanced methods, such as decoupled algorithm\cite{2015_ShenJie_Decoupled_energy_stable_schemes_for_phase_field_models_of_two_phase_incompressible_flows,2021_LiMinghui_New_efficient_time_stepping_schemes_for_the_Navier_Stokes_Cahn_Hilliard_equations} and reduced basis methods\cite{2025_Abbaszadeh_A_reduced_order_least_squares_support_vector_regression_and_isogeometric_collocation_method_to_simulate_Cahn_Hilliard_Navier_Stokes_equation}; 
    (\rmnum{3}) physics-consistent formulations, including structure-preserving methods\cite{2025_Acosta_Soba_Property_preserving_numerical_approximation_of_a_Cahn_Hilliard_Navier_Stokes_model_with_variable_density_and_degenerate_mobility,2025_LiXiaoli_On_a_Class_of_Higher_Order_Fully_Decoupled_Schemes_for_the_Cahn_Hilliard_Navier_Stokes_System} and conservative numerical discretization\cite{2025_Goulding_Conservative_bounded_and_nonlinear_discretization_of_the_Cahn_Hilliard_Navier_Stokes_equations,2017_Mass_conservative_and_energy_stable_finite_difference_methods_for_the_quasi_incompressible_Navier_Stokes_Cahn_Hilliard_system_primitive_variable_and_projection_type_schemes}; and 
    (\rmnum{4}) high-order temporal discretizations\cite{2022JieShen_LiXiaoliMSAVCHNStwo_phase_incompressible_flows,2025_LiuXin_CHNSSDC}, and the references therein. Nevertheless, the CHNS system's inherent energy dissipation stability, high nonlinearity, and multiscale characteristics make numerical schemes, featuring low computational complexity, high-order accuracy in time, and unconditional energy stability, deserve further investigation.  \\
	\indent Most recently, a novel time-stepping technique, termed as the time filter (TF) technique, has attracted much attention, due to its capability to improve the time accuracy of simple, low-order methods to second-order, or even higher-order with negligible additional computational cost. Taking the backward Euler (BE) method as an example, the main technique of TF can be expressed
	$$
	\begin{aligned}
		& \text{Backward Euler}  \qquad\qquad\qquad \frac{\tilde{y}^{n+1} - y^n}{\Delta t} = f(t^{n+1}, \tilde{y}^{n+1}),  \\
		& \text{Time Filter}     \qquad\qquad\qquad\qquad y^{n+1} = \tilde{y}^{n+1} - \frac13\left(\tilde{y}^{n+1} - 2y^n + y^{n-1}\right).
	\end{aligned}
	$$
	This approximation $y^{n+1}$ is second-order, A-stable, and is implemented by adding only one line to the existing BE code. Many literature have confirmed that TF technique has the following advantages: (\rmnum{1}) It can improve the temporal accuracy of simple, low-order methods with negligible computational cost; (\rmnum{2}) It can remove the overdamping of BE scheme while remaining unconditionally energy stable (which is crucial for constructing numerical schemes of CHNS model); (\rmnum{3}) When employing the variable step-size technique, it can give a low cost error estimator for adapting the time-step size to ensure the time accuracy. TF technique was first proposed by Kwizak and Robert \cite{1971_ASEMIIMPLICITSCHEMEFORGRIDPOINTATMOSPHERICMODELSOFTHEPRIMITIVEEQUATIONS}, subsequently analyzed by Asselin \cite{1972_FrequencyFilterforTimeIntegrations} and improved by Williams \cite{2009_AProposedModificationtotheRobertAsselinTimeFilter,2010_TheRAWFilterAnImprovementtotheRobertAsselinFilterinSemiImplicitIntegrations}. From then on, TF has been widely employed in many scenarios, such as the Navier-Stokes equations \cite{2020_DeCaria_A_time_accurate_adaptive_discretization_for_fluid_flow_problems,2023_FengXinlong_Filtered_time_stepping_method_for_incompressible_Navier_Stokes_equations_with_variable_density}, Stokes-Darcy model \cite{2023_QinYi_Analysis_of_a_new_adaptive_time_filter_algorithm_for_the_unsteady_Stokes_Darcy_model}, natural convection problems\cite{2023_FengXinlong_Analysis_of_a_filtered_time_stepping_finite_element_method_for_natural_convection_problems,2025_FengXinlong_An_analysis_of_second_order_sav_filtered_time_stepping_finite_element_method_for_unsteady_natural_convection_problems}, etc.  \\
	\indent In this work, we construct, analyze, and verify a low-complexity, linear, second-order in time, and unconditional energy-stable semi-discrete scheme for the CHNS model via the TF technique. We first apply the first-order, linear, and unconditionally stable semi-implicit BE method to discretize the CHNS model, where $f(\phi)$ is handled explicitly with a linear stabilization term; TF technique is then utilized to enhance the temporal accuracy from first- to second-order, without destroying the unconditional stability and the linearity. Unconditional energy stability and second-order temporal error estimations are analyzed and obtained. The main contributions are twofold: First, the newly second-order scheme requires only a single line of code per variable added into the first-order scheme, thus possessing almost the same computational complexity while achieving second-order in time. Second, the incorporation of the TF technique preserves the unconditional stability and linearity, thereby yielding an unconditional energy-stable and linear numerical scheme for the CHNS model.  \\
	\indent The rest of the draft is organized as follows.
	Some notations and preliminaries are given in Section \ref{section-notations-preliminaries}.
	The time filter scheme is presented in  Section \ref{section-3} for the CHNS model and then, the unconditional energy stability is proven. In Section 
	\ref{section_numerical_analysis}, error estimations are analyzed, and finally, 
	in Section \ref{section_numerical_tests}, theoretical analyses of the time filter scheme are confirmed by several numerical experiments.
	\section{Notations and preliminaries}\label{section-notations-preliminaries}
	We introduce some notations and inequalities in this section. Here we use the notation $H^{-1}(\Omega) := (H^1(\Omega))^*$, the dual space of $H^1(\Omega)$, and $\langle\cdot, \cdot\rangle$ is the duality paring between $H^{-1}(\Omega)$ and $H^{1}(\Omega)$. The $\|\cdot\|$ and $\left(\cdot,\cdot\right)$ denote the norm and inner product of $L^2$ space, and denote
	$$
	\mathring{H}^1(\Omega) := H^1(\Omega) \cap L_0^2(\Omega), \quad \mathring{H}^{-1}(\Omega) := \{v \in H^{-1}(\Omega) | \langle v,1 \rangle = 0\},
	$$
	with $L_0^2(\Omega)$ representing those functions in $L^2(\Omega)$ with zero mean. In particular, the phase function and chemical potential space $X$ and velocity space $\boldsymbol{Y}$ and pressure space $Q$ are
	defined 
	$$
	\begin{aligned}
		&X:=H^1(\Omega),~\boldsymbol{Y}:=H_0^1(\Omega)^d, \text{and } Q:=L_0^2(\Omega).
	\end{aligned}
	$$
	We choose the velocity and pressure spaces $\boldsymbol{Y}, Q$ that satisfy the inf-sup condition:
	\begin{equation*}\label{eq_inf_sup_condition}
		\inf _{q\in Q}\sup_{{\boldsymbol{v}}\in \boldsymbol{Y}} \frac{\left(q,\nabla{\boldsymbol{v}}\right)}{\|q\|\|\nabla{\boldsymbol{v}}\|}\geq \beta\geq 0.
	\end{equation*}
	for some constant $\beta$. \\	
	\indent Following \cite{2015_Diegel_Analysis_of_a_mixed_finite_element_method_for_a_Cahn_Hilliard_Darcy_Stokes_system}, we define a linear operator for later analysis. Let a linear operator $\mathcal{T}: \mathring{H}^{-1}(\Omega) \rightarrow \mathring{H}^{1}(\Omega)$ via the following variational problem: given $\zeta \in \mathring{H}^{-1}(\Omega)$ such that
	$$
	(\nabla \mathcal{T}(\zeta), \nabla \chi) = \langle \zeta, \chi \rangle, \quad \forall \chi \in \mathring{H}^{1}(\Omega).
	$$
	$\mathcal{T}$ is well-defined via the Riesz representation theorem, and the following lemma has been established.
	\begin{Lemma}[\cite{2015_Diegel_Analysis_of_a_mixed_finite_element_method_for_a_Cahn_Hilliard_Darcy_Stokes_system}]
		Let \( \zeta, \xi \in \mathring{H}^{-1}(\Omega) \) and, for such functions, set
		\[
		(\zeta, \xi)_{H^{-1}} := (\nabla \mathcal{T}(\zeta), \nabla \mathcal{T}(\xi)) = \langle \zeta, \mathcal{T}(\xi) \rangle = \langle \mathcal{T}(\zeta), \xi \rangle.
		\]
		\((\cdot, \cdot)_{H^{-1}}\) defines an inner product on \(\mathring{H}^{-1}(\Omega)\), and the induced norm is equal to the operator norm:
		\[
		\|\zeta\|_{H^{-1}} := \sqrt{(\zeta, \zeta)_{H^{-1}}} = \sup_{0 \neq \chi \in \mathring{H}^{1}} \frac{\langle \zeta, \chi \rangle}{\|\nabla \chi\|_{L^{2}}}.
		\]
		Consequently, for all \(\chi \in H^{1}(\Omega)\) and all \(\zeta \in \mathring{H}^{-1}(\Omega)\),
		\[
		|\langle \zeta, \chi \rangle| \leq \|\zeta\|_{H^{-1}} \|\nabla \chi\|_{L^{2}}.
		\]
		Furthermore, for all \(\zeta \in L^{2}_{0}(\Omega)\), we have the Poincar\'{e} type inequality
		\[
		\|\zeta\|_{H^{-1}} \leq C \|\zeta\|_{L^{2}},
		\]
		where \( C > 0 \) is the usual Poincar\'{e} constant.
	\end{Lemma}
    For the trilinear term $((\boldsymbol{u} \cdot \nabla )\boldsymbol{v},\boldsymbol{w})$, we have the following estimates.    
	\begin{Lemma}[\cite{2021_lixiaoli_New_SAV_NS}]
		\label{lemma_nonlinear_term_boundness}
		There exists $C>0$ such that
		\begin{flalign}
			\label{eq_ns_nonlinear_inequalities01}
			((\boldsymbol{u} \cdot \nabla )\boldsymbol{v},\boldsymbol{w})\leq\left\{\begin{array}{l}
				C\|\boldsymbol{u}\|_{1}\|\boldsymbol{v}\|_{1}\|\boldsymbol{w}\|_{1},\\
				C\|\boldsymbol{u}\|_{2}\|\boldsymbol{v}\|\|\boldsymbol{w}\|_{1},\\
				C\|\boldsymbol{u}\|_{2}\|\boldsymbol{v}\|_{1}\|\boldsymbol{w}\|,\\
				C\|\boldsymbol{u}\|_{1}\|\boldsymbol{v}\|_{2}\|\boldsymbol{w}\|,\\
				C\|\boldsymbol{u}\|\|\boldsymbol{v}\|_{2}\|\boldsymbol{w}\|_{1}.
			\end{array}\right.
		\end{flalign}
	\end{Lemma}
    Moreover, if we denote $\boldsymbol{W} := \{\boldsymbol{v} \in \boldsymbol{L}^2(\Omega) | \nabla \cdot \boldsymbol{v} = 0, \; \boldsymbol{v} \cdot \boldsymbol{n} = 0\}$, then we have the skew-symmetric property:
    \begin{equation}
    	((\boldsymbol{u} \cdot \nabla )\boldsymbol{v},\boldsymbol{v}) = 0, \quad \boldsymbol{u} \in \boldsymbol{W}, \; \boldsymbol{v} \in \boldsymbol{H}^1_0(\Omega).
    \end{equation}
    \indent We will use the following discrete version of the Gr\"{o}nwall inequality \cite{1990_Heywood_Finite_element_approximation_of_the_nonstationary_Navier_Stokes_problem_IV_Error_analysis_for_second_order_time_discretization} in the later numerical analysis.
	\begin{Lemma}
		\label{lemma_gronwall_inequalities}
		For all $n\geq 0$ and $N\geq 0$, let $\Delta t$, $C$, $a_n$, $b_n$, $c_n$, $d_n$ be non-negative numbers such that
		\begin{equation*}
			\label{eq_gronwall_inequality_0001}
			a_N+\Delta t\sum_{n=0}^{N}b_n\leq \Delta t\sum_{n=0}^{N}d_na_n+\Delta t\sum_{n=0}^{N}c_n+C,
		\end{equation*} 
	and suppose $\Delta td_n \leq 1$, s
	\begin{equation*}
		\label{eq_gronwall_inequality_0002}
		a_N+\Delta t\sum_{n=0}^{N}\leq \exp\left(\Delta t\sum_{n=0}^{N}\frac{1}{1-\Delta td_n}\right)\left(\Delta t\sum_{n=0}^{N}c_n+C\right).
	\end{equation*}
	\end{Lemma}
	Throughout the manuscript, we use $C$ or $c$, with or without a subscript, to denote a positive constant independent of discretization parameters, which could have uncertain values in different places.

	\section{Time filter scheme}\label{section-3}
	Dividing the time domain $[0,T]$ into $n$ interval $[t_n, t_{n+1}]$, $n=0,1,2, \cdots, N-1$ where $t_0 = 0$, $T_N = T$, and defining $\Delta t_n := t_{n+1} - t_n$. Due to space limitations, this study only considers the fixed time-step, i.e., $\Delta t_n = \Delta t$ for $\forall n$, whereas the variable time-step TF numerical schemes for other models can be found in \cite{2022_LiJian_A_variable_time_step_time_filter_algorithm_for_the_geothermal_system, 2025_FengXinlong_An_analysis_of_second_order_sav_filtered_time_stepping_finite_element_method_for_unsteady_natural_convection_problems}, etc., and for the CHNS model will be performed in our future work.  \\
	\indent We first present the classical first-order nonlinear and linear implicit Euler time-stepping scheme, where $f(\phi)$ is handled full-implicitly or semi-implicitly, and explicitly with stabilized term, respectively, that is, 

	\noindent \textbf{Algorithm 1} \emph{(Fully/Linearly-Implicit Backward Euler (BE))}. Given $\phi^{n-1},$ $\phi^{n}$, $\mu^{n-1},$ $\mu^{n}$, $\boldsymbol{u}^{n-1}$, $\boldsymbol{u}^{n}$, $p^n$, find $\left(\phi^{n+1},\mu^{n+1},\boldsymbol{u}^{n+1},p^{n+1}\right) $, with $\phi^{\star} = \phi^{n+1}$, $\boldsymbol{u}^{\star} = \boldsymbol{u}^{n+1}$ (non-linearly full-implicit), or $\phi^{\star} = \phi^{n}$, $\boldsymbol{u}^{\star} = \boldsymbol{u}^{n}$ (linearly semi-implicit), and $f^{\star}(\phi) = \left((\phi^{n+1})^3-\phi^{n+1}\right)$ (non-linearly full-implicit), or $f^{\star}(\phi) = \left((\phi^{n+1})^3-\phi^{n}\right)$ (non-linearly semi-implicit), or $f^{\star}(\phi) = \frac{S}{\epsilon}\left(\phi^{n+1} - \phi^n\right) + \left((\phi^{n})^3-\phi^{n}\right)$ (linearly explicit with stabilized term), 
	\begin{equation}
		\label{eq_BE_scheme0001}
		\left\{\begin{aligned}
			\frac{\phi^{n+1} - \phi^{n}}{\Delta t} + \boldsymbol{u}^{n+1} \cdot \nabla \phi^{\star} - \epsilon M \Delta \mu^{n+1} &= 0 , \\
			- \mu^{n+1} - \epsilon \Delta\phi^{n+1} + \epsilon f^{\star}(\phi) &= 0 , \\
			\frac{\boldsymbol{u}^{n+1} - \boldsymbol{u}^{n}}{\Delta t} - \nu \Delta \boldsymbol{u}^{n+1} + (\boldsymbol{u}^{\star} \cdot \nabla) \boldsymbol{u}^{n+1} + \nabla p^{n+1} - \gamma \mu^{n+1}\nabla\phi^{\star} &= 0 , \\
			\nabla \cdot \boldsymbol{u}^{n+1} &= 0 .
		\end{aligned}\right.
	\end{equation}

    \indent For the efficient computation, we present the classical linear semi-implicit scheme with stabilization, and this scheme will be employed for comparison in the subsequent numerical experiments section to highlight the capability of TF in improving temporal accuracy.

	\noindent \textbf{Algorithm 1 for implementation} \emph{(Linearly-Implicit Backward Euler (BE))}. 
	\begin{equation}
		\label{eq_BE_scheme0002}
		\left\{\begin{aligned}
			\frac{\phi^{n+1} - \phi^{n}}{\Delta t} + \boldsymbol{u}^{n+1} \cdot \nabla \phi^{n} - \epsilon M \Delta \mu^{n+1} &= 0 , \\
			- \mu^{n+1} - \epsilon \Delta\phi^{n+1} + \frac{S}{\epsilon}\left(\phi^{n+1} - \phi^n\right) + \frac{1}{\epsilon}\left((\phi^{n})^3-\phi^{n}\right) &= 0 , \\
			\frac{\boldsymbol{u}^{n+1} - \boldsymbol{u}^{n}}{\Delta t} - \nu \Delta \boldsymbol{u}^{n+1} + (\boldsymbol{u}^{n} \cdot \nabla) \boldsymbol{u}^{n+1} + \nabla p^{n+1} - \gamma \mu^{n+1}\nabla\phi^{\star} &= 0 , \\
			\nabla \cdot \boldsymbol{u}^{n+1} &= 0 .
		\end{aligned}\right.
	\end{equation}

    Then, to clearly demonstrate the simplicity of the TF technique, we incorporate the TF into the fully implicit scheme, thereby deriving the following nonlinear fully implicit Euler TF scheme:

	\noindent \textbf{Algorithm 2} \emph{(Fully-Implicit Backward Euler with Time Filter)}. Given $\phi^{n-1},$ $\phi^{n}$, $\mu^{n-1},$ $\mu^{n}$, $\boldsymbol{u}^{n-1}$, $\boldsymbol{u}^{n}$, $p^n$, find $\left(\phi^{n+1},\mu^{n+1},\boldsymbol{u}^{n+1},p^{n+1}\right) $:

	\noindent \textbf{Step 2.1.} Solve
	\begin{equation}
		\label{eq_FIBETF_scheme0001}
		\left\{\begin{aligned}
			\frac{\tilde{\phi}^{n+1} - \phi^{n}}{\Delta t} + \tilde{\boldsymbol{u}}^{n+1} \cdot \nabla \tilde{\phi}^{n+1} - \epsilon M \Delta \tilde{\mu}^{n+1} &= 0 , \\
			- \tilde{\mu}^{n+1} - \epsilon \Delta\tilde{\phi}^{n+1} + \frac{1}{\epsilon}\left((\tilde{\phi}^{n+1})^3 - \tilde{\phi}^{n+1}\right) &= 0 , \\
			\frac{\tilde{\boldsymbol{u}}^{n+1} - \boldsymbol{u}^{n}}{\Delta t} - \nu \Delta \tilde{\boldsymbol{u}}^{n+1} + (\tilde{\boldsymbol{u}}^{n+1} \cdot \nabla) \tilde{\boldsymbol{u}}^{n+1} + \nabla \tilde{p}^{n+1} - \gamma \tilde{\mu}^{n+1}\nabla\tilde{\phi}^{n+1} &= 0 , \\
			\nabla \cdot \tilde{\boldsymbol{u}}^{n+1} &= 0 .
		\end{aligned}\right.
	\end{equation}
	\textbf{Step 2.2.} Apply time filer
	\begin{equation}
		\label{eq_FIBETF_scheme0002}
		\begin{aligned}
			\phi^{n+1} &= \tilde{\phi}^{n+1} - \frac13\left(\tilde{\phi}^{n+1} - 2\phi^{n} + \phi^{n-1}\right),  \\
			\mu^{n+1}  &= \tilde{\mu}^{n+1} - \frac13\left(\tilde{\mu}^{n+1} - 2\mu^{n} + \mu^{n-1}\right),  \\
			\boldsymbol{u}^{n+1} &= \tilde{\boldsymbol{u}}^{n+1} - \frac13\left(\tilde{\boldsymbol{u}}^{n+1} - 2\boldsymbol{u}^{n} + \boldsymbol{u}^{n-1}\right),  \\
			p^{n+1}    &= \tilde{p}^{n+1} - \frac13\left(\tilde{p}^{n+1} - 2 p^{n} + p^{n-1}\right),   \text{ for Option A},\\
			&\text{or}  \\
			p^{n+1}    &= \tilde{p}^{n+1}, \text{ for Option B}.
		\end{aligned}
	\end{equation}

    Finally, for the purpose of efficient implementation, we employ the extrapolation technique to linearize \textbf{Algorithm 2} to derive the following linear semi-implicit Euler TF scheme, i.e., 

	\noindent \textbf{Algorithm 3}\emph{(Linearly-Implicit Backward Euler with Time Filter)}. Given $\phi^{n-1},$ $\phi^{n}$, $\mu^{n-1},$ $\mu^{n}$, $\boldsymbol{u}^{n-1}$, $\boldsymbol{u}^{n}$, $p^n$, find $\left(\phi^{n+1},\mu^{n+1},\boldsymbol{u}^{n+1},p^{n+1}\right) $:

	\noindent \textbf{Step 3.1.} Solve
	\begin{equation}\label{eq_algorithm3_1}
		\left\{\begin{aligned}
			\frac{\tilde{\phi}^{n+1} - \phi^{n}}{\Delta t} + \tilde{\boldsymbol{u}}^{n+1} \cdot \nabla \bar{\phi}^{n+1} - \epsilon M \Delta \tilde{\mu}^{n+1} &= 0 , \\
			- \tilde{\mu}^{n+1} - \lambda \Delta\tilde{\phi}^{n+1} + \frac{S\Delta t}{\epsilon}\left(\tilde{\phi}^{n+1} - \phi^{n}\right) + \epsilon\left(2f(\phi^n)-f(\phi^{n-1})\right) &= 0 , \\
			\frac{\tilde{\boldsymbol{u}}^{n+1} - \boldsymbol{u}^{n}}{\Delta t} - \nu \Delta \tilde{\boldsymbol{u}}^{n+1} + (\bar{\boldsymbol{u}}^{n+1} \cdot \nabla) \tilde{\boldsymbol{u}}^{n+1} + \nabla \tilde{p}^{n+1} - \gamma \tilde{\mu}^{n+1}\nabla\bar{\phi}^{n+1} &= 0 , \\
			\nabla \cdot \tilde{\boldsymbol{u}}^{n+1} &= 0 .
		\end{aligned}\right.
	\end{equation}
	\textbf{Step 3.2.} Apply time filer
	\begin{equation}\label{eq_algorithm3_2}
		\begin{aligned}
			\phi^{n+1} &= \tilde{\phi}^{n+1} - \frac13\left(\tilde{\phi}^{n+1} - 2\phi^{n+1} + \phi^{n-1}\right),  \\
			\mu^{n+1}  &= \tilde{\mu}^{n+1} - \frac13\left(\tilde{\mu}^{n+1} - 2\mu^{n+1} + \mu^{n-1}\right),  \\
			\boldsymbol{u}^{n+1} &= \tilde{\boldsymbol{u}}^{n+1} - \frac13\left(\tilde{\boldsymbol{u}}^{n+1} - 2\boldsymbol{u}^{n+1} + \boldsymbol{u}^{n-1}\right),  \\
			p^{n+1}    &= \tilde{p}^{n+1} - \frac13\left(\tilde{p}^{n+1} - 2 p^{n+1} + p^{n-1}\right),  \text{ for Option A},\\
			&\text{or}  \\
			p^{n+1}    &= \tilde{p}^{n+1},  \text{ for Option B}.
		\end{aligned}
	\end{equation}
	where $\bar{g}^{n+1} := 2 g^n - g^{n-1}$ for any sequence $\{g^n\}$. \\
	\indent For the two novel CHNS TF time-stepping schemes \eqref{eq_algorithm3_1}-\eqref{eq_algorithm3_2} and \eqref{eq_FIBETF_scheme0001}-\eqref{eq_FIBETF_scheme0002} presented above, we only analyze the linear one since the analysis of the nonlinear one can be derived similarly. However, numerical verifications of both schemes are provided in the numerical experiment section.

	\subsection{Energy stability}
	In the subsection, we will prove unconditional energy stabilization for the time semi-discrete scheme \eqref{eq_algorithm3_1}-\eqref{eq_algorithm3_2}. To analyze, we denote
	\begin{equation*}
		\begin{aligned}
			\mathcal{A}(s^{n+1}) &:= \tilde{s}^{n+1} - s^{n} = \frac32s^{n+1} - 2s^{n} + \frac12s^{n-1}, \\ 
			\mathcal{B}(s^{n+1}) &:= \tilde{s}^{n+1} = \frac32s^{n+1} - s^{n} + \frac12s^{n-1},
		\end{aligned}
	\end{equation*}
	with $s=\phi$, or $\mu$, or $\boldsymbol{u}$, or $p$. 
	Therefore, we can get
	\begin{equation}
		\label{eq_A_B_form}
		\begin{aligned}
			\left(\mathcal{A}(s^{n+1}),\mathcal{B}(s^{n+1}) \right)=&\left(\frac32s^{n+1} - 2s^{n} + \frac12s^{n-1},\frac32s^{n+1} - s^{n} + \frac12s^{n-1}\right)\\
			=&\frac{1}{4}\left(\left(3s^{n+1}-4s^n+s^{n-1},2s^{n+1}\right)+\left(3s^{n+1}-4s^n+s^{n-1},s^{n+1}-2s^{n}+s^{n-1}\right)\right)\\
			=&\frac{1}{4}\left(\|s^{n+1}\|^2+\|2s^{n+1}-s^n\|^2+\|s^{n+1}-s^n\|^2\right)\\
			&-\frac{1}{4}\left(\|s^{n}\|^2+\|2s^{n}-s^{n-1}\|^2+\|s^{n}-s^{n-1}\|^2\right)+\frac{3}{4}\left(\|s^{n+1}-2s^n+s^{n-1}\|^2\right).
		\end{aligned}	
	\end{equation}
	Inserting to get the equivalent form of Algorithm 3.

	\noindent \textbf{Algorithm 4} \emph{(Equivalent form of Algorithm 3)}. Given $\phi^{n-1},$ $\phi^{n}$, $\mu^{n-1},$ $\mu^{n}$, $\boldsymbol{u}^{n-1}$, $\boldsymbol{u}^{n}$, $p^n$, find $\left(\phi^{n+1},\mu^{n+1},\boldsymbol{u}^{n+1}\right.,$ $\left.p^{n+1}\right) $,
	for $n=1,\cdots,N-1$, satisfying
	\begin{equation}
		\left\{\begin{aligned}
			\frac{\mathcal{A}(\phi^{n+1})}{\Delta t} + \mathcal{B}(\boldsymbol{u}^{n+1}) \cdot \nabla \bar{\phi}^{n+1} - \epsilon M \Delta \mathcal{B}(\mu^{n+1}) &= 0 , \\
			- \mathcal{B}(\mu^{n+1}) - \epsilon \Delta \mathcal{B}(\phi^{n+1}) +\frac{S\Delta t}{\epsilon}\left(\tilde{\phi}^{n+1}-{\phi}^{n}\right)+\epsilon \left(2f(\phi^{n})-f(\phi^{n-1}) \right)&= 0 , \\
			\frac{\mathcal{A}(\boldsymbol{u}^{n+1})}{\Delta t} - \nu \Delta \mathcal{B}(\boldsymbol{u}^{n+1}) + (\bar{\boldsymbol{u}}^{n+1} \cdot \nabla) \mathcal{B}(\boldsymbol{u}^{n+1}) + \nabla \mathcal{B}(p^{n+1}) - \gamma \mathcal{B}(\mu^{n+1})\nabla\bar{\phi}^{n+1} &= 0 , \\
			\nabla \cdot \mathcal{B}(\boldsymbol{u}^{n+1}) &= 0 .
		\end{aligned}\right.
	\end{equation}
    Taking mixed variation, we get

	\noindent \textbf{Algorithm 5} \emph{(Equivalent Variational form of Algorithm 3)}. Given $\phi^{n-1},$ $\phi^{n}$, $\mu^{n-1},$ $\mu^{n}$, $\boldsymbol{u}^{n-1}$, $\boldsymbol{u}^{n}$, $p^n$, find $\left(\phi^{n+1},\mu^{n+1},\boldsymbol{u}^{n+1},p^{n+1}\right) $,
	for $n=1,\cdots,N-1$ and $\forall \left(\psi, \omega, \boldsymbol{v}, q\right) \in X \times X \times \boldsymbol{Y} \times Q$, satisfying
	\begin{equation}\label{eq_variational_form_Alg2}
		\left\{\begin{aligned}
			\frac{1}{\Delta t}\left(\mathcal{A}(\phi^{n+1}), \psi\right) + \left(\mathcal{B}(\boldsymbol{u}^{n+1}) \cdot \nabla \bar{\phi}^{n+1}, \psi\right) + \epsilon M\left(\nabla \mathcal{B}(\mu^{n+1}), \nabla\psi\right) &= 0 , \\
			- \left(\mathcal{B}(\mu^{n+1}), \omega\right) + \epsilon\left(\nabla \mathcal{B}(\phi^{n+1}), \nabla \omega\right)+ \frac{S\Delta t}{\epsilon}\left(\tilde{\phi}^{n+1}-{\phi}^{n},\omega\right)+ \epsilon\left(2f\left(\phi^{n}\right)-f(\phi^{n-1}), \omega\right) &= 0 , \\
			\frac{1}{\Delta t}\left(\mathcal{A}(\boldsymbol{u}^{n+1}), \boldsymbol{v}\right) + \nu \left(\nabla \mathcal{B}(\boldsymbol{u}^{n+1}), \nabla \boldsymbol{v}\right) + \left((\bar{\boldsymbol{u}}^{n+1} \cdot \nabla) \mathcal{B}(\boldsymbol{u}^{n+1}), \boldsymbol{v}\right) \\
			- \left(\mathcal{B}(p^{n+1}), \nabla\cdot\boldsymbol{v}\right) - \gamma\left(\mathcal{B}(\mu^{n+1})\nabla\bar{\phi}^{n+1}, \boldsymbol{v}\right) &= 0 , \\
			\left(\nabla \cdot \mathcal{B}(\boldsymbol{u}^{n+1}), q\right) &= 0.
		\end{aligned}\right.
	\end{equation}
	\indent For the convenience of the later analysis, we set the parameters $M(\phi),\gamma,\epsilon,\nu$ to 1, though these parameters may be important in the CHNS model. For relevant literature that considers the effect of parameters, e.g., see \cite{2023_Chen_On_the_superconvergence_of_a_hybridizable_discontinuous_Galerkin_method_for_the_Cahn_Hilliard_equation_SINUM,2024_Ma_Error_analysis_with_polynomial_dependence_on_in_SAV_methods_for_the_Cahn_Hilliard_equation_JSC}.  \\	
	\indent We next give a theorem on the unconditional energy stabilization of the time semi-discrete scheme.
	\begin{Theorem}\label{theorem_unconditional_stability}
		For all $\Delta t>0$, 
		assuming that  the condition \eqref{eq_phi_condition} is satisfied with $ S \geq 3 L/\Delta t $. Then, for given  $\phi^0,$ $\phi^1$, $\mu^0,$ $\mu^1$, $\boldsymbol{u}^0$, $\boldsymbol{u}^1$
		and $p^1$, there exists a positive constant $C_0$ such that  $E^0\leq C_0$, and for all $ 0 \leq n \leq N-1$,
		the scheme \eqref{eq_algorithm3_1}-\eqref{eq_algorithm3_2} satisfies
		\begin{equation}
			E^{n+1}-E^{n}\leq 0,
		\end{equation}
	where $E^{n+1}$ is defined by 
	\begin{equation}
		\label{eq_discrete_energy_definition}
		\begin{aligned}
			E^{n+1}=&~\frac{1}{4}\left(\|\nabla\phi^{n+1}\|^2+\|\nabla(2\phi^{n+1}-\phi^n)\|^2+\|\nabla(\phi^{n+1}-\phi^n)\|^2\right)\\
				&~+\frac{1}{4}\left(\|\boldsymbol{u}^{n+1}\|^2+\|2\boldsymbol{u}^{n+1}-\boldsymbol{u}^n\|^2+\|\boldsymbol{u}^{n+1}-\boldsymbol{u}^n\|^2\right) + \frac{3L}{\epsilon} \|\phi^{n+1}-\phi^n\|^2  \\
				&~+ \left(F(\phi^{n+1}),1\right) + \frac{1}{2}\left(F(\phi^{n+1})-F(\phi^n),1\right).
		\end{aligned}
	\end{equation}
    \begin{Remark}
    	We note that one condition appears above regarding the stabilization parameter $S$. On the one hand, this constraint arises from the incorporation of the stabilization term, rather than being induced by the TF; moreover, this type of requirement is a common scenario in the fully explicit discretization with stabilization for the CHNS model. On the other hand, if one wishes to remove this restriction, one can adopt the semi-implicit discretization or fully explicit with scalar auxiliary variables (SAVs) technique.
    \end{Remark}
	\end{Theorem}
	\begin{proof}
		Setting $\left(\psi,\omega,\boldsymbol{v},q\right)=\left(\mathcal{B}(\mu^{n+1}), \mathcal{A}(\phi^{n+1}),\mathcal{B}(\boldsymbol{u}^{n+1}), \mathcal{B}(p^{n+1})\right)$
		in \eqref{eq_variational_form_Alg2},  we have
		\begin{flalign}
			\label{eq_variational_form_inner_product_phi}
			\frac{1}{\Delta t}\left(\mathcal{A}(\phi^{n+1}),\mathcal{B}(\mu^{n+1})\right)+ \left(\mathcal{B}(\boldsymbol{u}^{n+1}) \cdot \nabla \bar{\phi}^{n+1}, \mathcal{B}(\mu^{n+1})\right) + \left(\nabla \mathcal{B}(\mu^{n+1}), \nabla\mathcal{B}(\mu^{n+1})\right) &= 0,\\
			\label{eq_variational_form_inner_product_mu}
			- \left(\mathcal{B}(\mu^{n+1}), \mathcal{A}(\phi^{n+1})\right) + \left(\nabla \mathcal{B}(\phi^{n+1}), \nabla \mathcal{A}(\phi^{n+1})\right) + S\Delta t\left(\tilde{\phi}^{n+1}-{\phi}^{n},\mathcal{A}(\phi^{n+1})\right)&\notag\\
			+ \left(2f\left(\phi^{n}\right)-f(\phi^{n-1}), \mathcal{A}(\phi^{n+1})\right) &= 0 ,
	\end{flalign}
	and
	\begin{flalign}	
		\label{eq_variational_form_inner_product_ns}
		\frac{1}{\Delta t}\left(\mathcal{A}(\boldsymbol{u}^{n+1}), \mathcal{B}(\boldsymbol{u}^{n+1})\right) + \left(\nabla \mathcal{B}(\boldsymbol{u}^{n+1}), \nabla \mathcal{B}(\boldsymbol{u}^{n+1})\right) + \left((\bar{\boldsymbol{u}}^{n+1} \cdot \nabla) \mathcal{B}(\boldsymbol{u}^{n+1}), \mathcal{B}(\boldsymbol{u}^{n+1})\right)\notag \\
		- \left(\mathcal{B}(p^{n+1}), \nabla\cdot\mathcal{B}(\boldsymbol{u}^{n+1})\right) - \left(\mathcal{B}(\mu^{n+1})\nabla\bar{\phi}^{n+1}, \mathcal{B}(\boldsymbol{u}^{n+1})\right) &= 0 , \\
		\label{eq_variational_form_inner_product_incompressible_condition}
		\left(\nabla \cdot \mathcal{B}(\boldsymbol{u}^{n+1}), \mathcal{B}(p^{n+1})\right) &= 0.
	\end{flalign}
	 Multiplying \eqref{eq_variational_form_inner_product_phi} by $\Delta t$ and adding \eqref{eq_variational_form_inner_product_mu},
	 we obtain
	\begin{equation}
		\label{eq_multiplying_adding_two_forms_phi_mu}
		\begin{aligned}
		 \left(\nabla \mathcal{B}(\phi^{n+1}), \nabla \mathcal{A}(\phi^{n+1})\right) + \Delta t
		 	\|\nabla \mathcal{B}(\mu^{n+1})\|^2+\Delta t \left(\mathcal{B}(\boldsymbol{u}^{n+1}) \cdot \nabla \bar{\phi}^{n+1}, \mathcal{B}(\mu^{n+1})\right)&\\
			 + S\Delta t\left(\tilde{\phi}^{n+1}-{\phi}^{n},\mathcal{A}(\phi^{n+1})\right) + \left(2f(\phi^{n})-f(\phi^{n-1}), \mathcal{A}(\phi^{n+1})\right) &=0.
		\end{aligned}
	\end{equation}
    Adding \eqref{eq_variational_form_inner_product_incompressible_condition} and \eqref{eq_variational_form_inner_product_ns}, multiplying  by $\Delta t$, and using skew-symmetry to get
	\begin{equation}
		\label{eq_multiplying_adding_two_forms_ns_con}
		\begin{aligned}
			\left(\mathcal{A}(\boldsymbol{u}^{n+1}), \mathcal{B}(\boldsymbol{u}^{n+1})\right)+
			\Delta t\|\nabla \mathcal{B}(\boldsymbol{u}^{n+1})\|^2-\Delta t\left(\mathcal{B}(\mu^{n+1})\nabla\bar{\phi}^{n+1}, \mathcal{B}(\boldsymbol{u}^{n+1})\right) =0.
		\end{aligned}
	\end{equation}
	According to \eqref{eq_A_B_form}, combining the \eqref{eq_multiplying_adding_two_forms_phi_mu} with \eqref{eq_multiplying_adding_two_forms_ns_con},
	 we have
	\begin{equation}
		\label{eq_combining_the_two_inequalities}
		\begin{aligned}
			&\Delta t	\|\nabla \mathcal{B}(\mu^{n+1})\|^2+
			\frac{1}{4}\left(\|\nabla\phi^{n+1}\|^2+\|\nabla(2\phi^{n+1}-\phi^n)\|^2+\|\nabla(\phi^{n+1}-\phi^n)\|^2\right)\\
			&\quad-\frac{1}{4}\left(\|\nabla\phi^{n}\|^2+\|\nabla(2\phi^{n}-\phi^{n-1})\|^2+\|\nabla(\phi^{n}-\phi^{n-1})\|^2\right)+
			\frac{3}{4}\|\nabla(\phi^{n+1}-2\phi^n+\phi^{n-1})\|^2\\
			&\quad+\frac{1}{4}\left(\|\boldsymbol{u}^{n+1}\|^2+\|2\boldsymbol{u}^{n+1}-\boldsymbol{u}^n\|^2+\|\boldsymbol{u}^{n+1}-\boldsymbol{u}^n\|^2\right) + \Delta t\|\nabla \mathcal{B}(\boldsymbol{u}^{n+1})\|^2\\
			&\quad-\frac{1}{4}\left(\|\boldsymbol{u}^{n}\|^2+\|2\boldsymbol{u}^{n}-\boldsymbol{u}^{n-1}\|^2+\|\boldsymbol{u}^{n}-\boldsymbol{u}^{n-1}\|^2\right)+\frac{3}{4}\left(\|\boldsymbol{u}^{n+1}-2\boldsymbol{u}^n+\boldsymbol{u}^{n-1}\|^2\right)\\
			&\quad+ S\Delta t\left(\tilde{\phi}^{n+1}-\phi^{n},\mathcal{A}(\phi^{n+1})\right) + \left(2f(\phi^{n})-f(\phi^{n-1}), \mathcal{A}(\phi^{n+1})\right) =0.
		\end{aligned}
	\end{equation}
	For the last two term in \eqref{eq_combining_the_two_inequalities}, we firstly have
	\begin{equation}
		\label{eq_Deltat_S}
		\begin{aligned}
			&S\Delta t \left(\tilde{\phi}^{n+1}-\phi^{n},\mathcal{A}(\phi^{n+1})\right)=S\Delta t\|\mathcal{A}(\phi^{n+1})\|^2\\
			=&~\frac{S\Delta t}{4}\|2\left({\phi}^{n+1}-\phi^{n}\right)+\left((\phi^{n+1}-\phi^n)-(\phi^n-\phi^{n-1})\right)\|^2\\
			=&~S\Delta t\|\phi^{n+1}-\phi^n\|^2+\frac{S\Delta t}{4}\|\phi^{n+1}-2\phi^n+\phi^{n-1}\|^2\\
			&~+S\Delta t\left(\phi^{n+1}-\phi^n,(\phi^{n+1}-\phi^n)-(\phi^n-\phi^{n-1})\right)\\
			=&~S\Delta t\|\phi^{n+1}-\phi^n\|^2+\frac{3S \Delta t}{4}\|\phi^{n+1}-2\phi^n+\phi^{n-1}\|^2\\
			&~+\frac{S\Delta t}{2}\left(\|\phi^{n+1}-\phi^n\|^2-\|\phi^n-\phi^{n-1}\|^2\right).
		\end{aligned}
	\end{equation}
	And then, we use the Taylor expansion to obtain
	\begin{equation}\label{eq_Taylor_expansion}
	F({\phi}^{n+1})-F(\phi^n)=f(\phi^n)\left({\phi}^{n+1}-\phi^n\right)+\frac{f'(\xi)}{2}\left({\phi}^{n+1}-\phi^n\right)^2,
	\end{equation}
	for some $\xi\in (\phi^n, \phi^{n+1})$, then we get
	\begin{equation}
		\label{eq_combining_the_two_inequalities_the_last_two_term_001}
		\begin{aligned}
			\left(f(\phi^{n}), \mathcal{A}(\phi^{n+1})\right) = & \left(f(\phi^{n}), \tilde{\phi}^{n+1}-\phi^n\right) =\frac{1}{2} \left(f(\phi^n),3\phi^{n+1}-4\phi^n+\phi^{n-1}\right)\\
			=&\frac{3}{2}\left(f(\phi^n),\phi^{n+1}-\phi^n\right)-\frac{1}{2}\left(f(\phi^n),\phi^n-\phi^{n-1}\right)\\
			=&\frac{3}{2}\left(F(\phi^{n+1})-F(\phi^n),1\right)-\frac{3}{4}\left(f'(\xi_1)\left(\phi^{n+1}-\phi^n\right),\phi^{n+1}-\phi^n\right)\\
			&-\frac{1}{2}\left(F(\phi^n)-F(\phi^{n-1}),1\right)+\frac{1}{4}\left(f'(\xi_2)\left(\phi^n-\phi^{n-1}\right),\phi^n-\phi^{n-1}\right),\\
		\end{aligned}
	\end{equation}
	for some $\xi_1,\xi_2$. On the other hand,
	\begin{equation}
		\label{eq_combining_the_two_inequalities_the_last_term_001}
		\begin{aligned}
			& \left(f(\phi^{n})-f(\phi^{n-1}), \mathcal{A}(\phi^{n+1})\right) \\
			=&~ \frac{1}{2} \left(f(\phi^{n})-f(\phi^{n-1}), 3\phi^{n+1}-4\phi^n+\phi^{n-1}\right) \\
			=&~ \frac{3}{2} \left(f(\phi^{n})-f(\phi^{n-1}),\phi^{n+1}-\phi^n\right) - \frac{1}{2} \left(f(\phi^{n})-f(\phi^{n-1}),\phi^{n}-\phi^{n-1}\right)\\
			=&~\frac{3}{2}\left(f'(\xi_3)\left(\phi^n-\phi^{n-1}\right),{\phi}^{n+1}-\phi^n\right)-\frac{1}{2}\left(f'(\xi_3)\left(\phi^n-\phi^{n-1}\right),{\phi}^{n}-\phi^{n-1}\right),
		\end{aligned}
	\end{equation}
	for some $\xi_3$. Combining the \eqref{eq_combining_the_two_inequalities_the_last_two_term_001}-\eqref{eq_combining_the_two_inequalities_the_last_term_001}, 	
	we arrive at
	\begin{equation}\label{equality_potential}
		\begin{aligned}
			&\left(2f(\phi^{n})-f(\phi^{n-1}), \mathcal{A}(\phi^{n+1})\right) \\
			=&~ \left(F(\phi^{n+1})-F(\phi^n),1\right)+\frac{1}{2}\left(F(\phi^{n+1})-2F(\phi^n)+F(\phi^{n-1}),1\right)\\
			&-\frac{3}{4}\left(f'(\xi_1)\left(\phi^{n+1}-\phi^n\right),\phi^{n+1}-\phi^n\right)+\frac{3}{2}\left(f'(\xi_3)\left(\phi^n-\phi^{n-1}\right),{\phi}^{n+1}-\phi^n\right)  \\
			& + \frac{1}{4}\left(f'(\xi_2)\left(\phi^n-\phi^{n-1}\right),\phi^n-\phi^{n-1}\right) - \frac{1}{2}\left(f'(\xi_3)\left(\phi^n-\phi^{n-1}\right),\phi^n-\phi^{n-1}\right) .
		\end{aligned}
	\end{equation}
    Inserting \eqref{eq_Deltat_S}, \eqref{equality_potential} into \eqref{eq_combining_the_two_inequalities}, we obtain
    \begin{equation}
    	\label{eq_above_inequalities_three_00010090293}
    	\begin{aligned}
    		\Delta t & \|\nabla \mathcal{B}(\mu^{n+1})\|^2+
    		\frac{1}{4}\left(\|\nabla\phi^{n+1}\|^2+\|\nabla(2\phi^{n+1}-\phi^n)\|^2+\|\nabla(\phi^{n+1}-\phi^n)\|^2\right)\\
    		&-\frac{1}{4}\left(\|\nabla\phi^{n}\|^2+\|\nabla(2\phi^{n}-\phi^{n-1})\|^2+\|\nabla(\phi^{n}-\phi^{n-1})\|^2\right)+
    		\frac{3}{4}\|\nabla(\phi^{n+1}-2\phi^n+\phi^{n-1})\|^2\\
    		&+\frac{1}{4}\left(\|\boldsymbol{u}^{n+1}\|^2+\|2\boldsymbol{u}^{n+1}-\boldsymbol{u}^n\|^2+\|\boldsymbol{u}^{n+1}-\boldsymbol{u}^n\|^2\right)+ \Delta t\|\nabla \mathcal{B}(\boldsymbol{u}^{n+1})\|^2\\
    		&-\frac{1}{4}\left(\|\boldsymbol{u}^{n}\|^2+\|2\boldsymbol{u}^{n}-\boldsymbol{u}^{n-1}\|^2+\|\boldsymbol{u}^{n}-\boldsymbol{u}^{n-1}\|^2\right)+\frac{3}{4}\|\boldsymbol{u}^{n+1}-2\boldsymbol{u}^n+\boldsymbol{u}^{n-1}\|^2\\
    		& + \left(F(\phi^{n+1})-F(\phi^n),1\right)+\frac{1}{2}\left(F(\phi^{n+1})-2F(\phi^n)+F(\phi^{n-1}),1\right)\\
    		&+S\Delta t\|\phi^{n+1}-\phi^n\|^2 + \frac{3S\Delta t}{4}\|\phi^{n+1} - 2\phi^n + \phi^{n-1}\|^2\\
    		&+\frac{S\Delta t}{2}\left(\|\phi^{n+1}-\phi^n\|^2-\|\phi^n-\phi^{n-1}\|^2\right)\\
    		&-\frac{3}{4}\left(f'(\xi_1)\left(\phi^{n+1}-\phi^n\right),\phi^{n+1}-\phi^n\right)+\frac{3}{2}\left(f'(\xi_3)\left(\phi^n-\phi^{n-1}\right),{\phi}^{n+1}-\phi^n\right)  \\
    		& + \frac{1}{4}\left(f'(\xi_2)\left(\phi^n-\phi^{n-1}\right),\phi^n-\phi^{n-1}\right) - \frac{1}{2}\left(f'(\xi_3)\left(\phi^n-\phi^{n-1}\right),\phi^n-\phi^{n-1}\right) = 0.
    	\end{aligned}
    \end{equation}
	Using the \eqref{eq_phi_condition}, we obtain
	\begin{equation}
		\label{eq_above_inequalities_three_000100001}
		\begin{aligned}
			\Delta t & \|\nabla \mathcal{B}(\mu^{n+1})\|^2+
			\frac{1}{4}\left(\|\nabla\phi^{n+1}\|^2+\|\nabla(2\phi^{n+1}-\phi^n)\|^2+\|\nabla(\phi^{n+1}-\phi^n)\|^2\right)\\
			&-\frac{1}{4}\left(\|\nabla\phi^{n}\|^2+\|\nabla(2\phi^{n}-\phi^{n-1})\|^2+\|\nabla(\phi^{n}-\phi^{n-1})\|^2\right)+
			\frac{3}{4}\|\nabla(\phi^{n+1}-2\phi^n+\phi^{n-1})\|^2\\
			&+\frac{1}{4}\left(\|\boldsymbol{u}^{n+1}\|^2+\|2\boldsymbol{u}^{n+1}-\boldsymbol{u}^n\|^2+\|\boldsymbol{u}^{n+1}-\boldsymbol{u}^n\|^2\right)+ \Delta t\|\nabla \mathcal{B}(\boldsymbol{u}^{n+1})\|^2\\
			&-\frac{1}{4}\left(\|\boldsymbol{u}^{n}\|^2+\|2\boldsymbol{u}^{n}-\boldsymbol{u}^{n-1}\|^2+\|\boldsymbol{u}^{n}-\boldsymbol{u}^{n-1}\|^2\right)+\frac{3}{4}\|\boldsymbol{u}^{n+1}-2\boldsymbol{u}^n+\boldsymbol{u}^{n-1}\|^2\\
			&+ \left(F(\phi^{n+1})-F(\phi^n),1\right)+\frac{1}{2}\left(F(\phi^{n+1})-2F(\phi^n)+F(\phi^{n-1}),1\right)\\
			&+S\Delta t\|\phi^{n+1}-\phi^n\|^2 + \frac{3S\Delta t}{4}\|\phi^{n+1} - 2\phi^n + \phi^{n-1}\|^2\\
			&+\frac{S\Delta t}{2}\left(\|\phi^{n+1}-\phi^n\|^2-\|\phi^n-\phi^{n-1}\|^2\right)\\
			\leq & ~\frac{3L}{4} \|\phi^{n+1}-\phi^n\|^2 + \frac{3L}{2}\left({\phi}^{n+1}-\phi^n, \phi^n-\phi^{n-1}\right) + \frac{3L}{4} \|\phi^{n}-\phi^{n-1}\|^2\\
			\leq&~ \frac{3L}{2}\|\phi^{n+1}-\phi^n\|^2+\frac{3L}{2}\|\phi^n-\phi^{n-1}\|^2.
		\end{aligned}
	\end{equation}
	That is, 
	\begin{equation}
		\label{eq_above_inequalities_three_000190091}
		\begin{aligned}
			\Delta t & \|\nabla \mathcal{B}(\mu^{n+1})\|^2+
			\frac{1}{4}\left(\|\nabla\phi^{n+1}\|^2+\|\nabla(2\phi^{n+1}-\phi^n)\|^2+\|\nabla(\phi^{n+1}-\phi^n)\|^2\right)\\
			&-\frac{1}{4}\left(\|\nabla\phi^{n}\|^2+\|\nabla(2\phi^{n}-\phi^{n-1})\|^2+\|\nabla(\phi^{n}-\phi^{n-1})\|^2\right)+
			\frac{3}{4}\|\nabla(\phi^{n+1}-2\phi^n+\phi^{n-1})\|^2\\
			&+\frac{1}{4}\left(\|\boldsymbol{u}^{n+1}\|^2+\|2\boldsymbol{u}^{n+1}-\boldsymbol{u}^n\|^2+\|\boldsymbol{u}^{n+1}-\boldsymbol{u}^n\|^2\right)+ \Delta t\|\nabla \mathcal{B}(\boldsymbol{u}^{n+1})\|^2\\
			&-\frac{1}{4}\left(\|\boldsymbol{u}^{n}\|^2+\|2\boldsymbol{u}^{n}-\boldsymbol{u}^{n-1}\|^2+\|\boldsymbol{u}^{n}-\boldsymbol{u}^{n-1}\|^2\right)+\frac{3}{4}\|\boldsymbol{u}^{n+1}-2\boldsymbol{u}^n+\boldsymbol{u}^{n-1}\|^2\\
			&+ \left(F(\phi^{n+1})-F(\phi^n),1\right)+\frac{1}{2}\left(F(\phi^{n+1})-2F(\phi^n)+F(\phi^{n-1}),1\right)\\
			&+\left(S\Delta t-\frac{3L}{2}\right)\|\phi^{n+1}-\phi^n\|^2-\frac{3L}{2}\|\phi^n-\phi^{n-1}\|^2+\frac{3S\Delta t}{4}\|\phi^{n+1}-2\phi^n+\phi^{n-1}\|^2\\
			&+\frac{S\Delta t}{2}\left(\|\phi^{n+1}-\phi^n\|^2-\|\phi^n-\phi^{n-1}\|^2\right)
			\leq  0.
		\end{aligned}
	\end{equation}
	Then, if assuming 
	\begin{equation}
		S\Delta t-\frac{3L}{2}\geq \frac{3L}{2},
	\end{equation}
	that is, 
	\begin{equation}
		S\Delta t\geq 3L
		\Leftrightarrow S\geq \frac{3L}{\Delta t}.
	\end{equation}
	 We obtain the following inequality
	\begin{equation}
		\label{eq_above_inequalities_three_0001}
		\begin{aligned}
			\Delta t & \|\nabla \mathcal{B}(\mu^{n+1})\|^2+
			\frac{1}{4}\left(\|\nabla\phi^{n+1}\|^2+\|\nabla(2\phi^{n+1}-\phi^n)\|^2+\|\nabla(\phi^{n+1}-\phi^n)\|^2\right)\\
			&-\frac{1}{4}\left(\|\nabla\phi^{n}\|^2+\|\nabla(2\phi^{n}-\phi^{n-1})\|^2+\|\nabla(\phi^{n}-\phi^{n-1})\|^2\right)+
			\frac{3}{4}\|\nabla(\phi^{n+1}-2\phi^n+\phi^{n-1})\|^2\\
			&+\frac{1}{4}\left(\|\boldsymbol{u}^{n+1}\|^2+\|2\boldsymbol{u}^{n+1}-\boldsymbol{u}^n\|^2+\|\boldsymbol{u}^{n+1}-\boldsymbol{u}^n\|^2\right)+ \Delta t\|\nabla \mathcal{B}(\boldsymbol{u}^{n+1})\|^2\\
			&-\frac{1}{4}\left(\|\boldsymbol{u}^{n}\|^2+\|2\boldsymbol{u}^{n}-\boldsymbol{u}^{n-1}\|^2+\|\boldsymbol{u}^{n}-\boldsymbol{u}^{n-1}\|^2\right)+\frac{3}{4}\|\boldsymbol{u}^{n+1}-2\boldsymbol{u}^n+\boldsymbol{u}^{n-1}\|^2\\
			&+ \left(F(\phi^{n+1})-F(\phi^n),1\right)+\frac{1}{2}\left(F(\phi^{n+1})-2F(\phi^n)+F(\phi^{n-1}),1\right)\\
			& + 3L\left(\|\phi^{n+1}-\phi^n\|^2-\|\phi^n-\phi^{n-1}\|^2\right) +\frac{3S\Delta t}{4}\|\phi^{n+1}-2\phi^n+\phi^{n-1}\|^2\\
			\leq & 0.
		\end{aligned}
	\end{equation}
    Inserting the definition of energy $E^{n+1}$, we rewrite the above inequality as
	\begin{equation}
		\label{eq_combining_finally_result}
		\begin{aligned}
			&E^{n+1}-E^n + \Delta t \|\nabla \mathcal{B}(\mu^{n+1})\|^2+ \Delta t \|\nabla \mathcal{B}(\boldsymbol{u}^{n+1})\|^2
			+\frac{3}{4}\|\nabla(\phi^{n+1}-2\phi^n+\phi^{n-1})\|^2\\
			&+\frac{3}{4}\|\boldsymbol{u}^{n+1}-2\boldsymbol{u}^n+\boldsymbol{u}^{n-1}\|^2
			 + \frac{3S\Delta t}{4} \|\phi^{n+1}-2\phi^n+\phi^{n-1}\|^2
			\leq 0,
		\end{aligned}
	\end{equation} 
	where $E^{n+1}$ is defined by \eqref{eq_discrete_energy_definition}. Dropping unneeded terms on the left-hand side, then, we obtain
	\begin{equation}
		\begin{aligned}
			E^{n+1}-E^{n} \leq 0.
		\end{aligned}
	\end{equation}
	Finally, we conclude that the discrete energy is unconditionally stable.
	\end{proof}
    Thus, summing up from $n=1$ to $m$ in \eqref{eq_combining_finally_result} and using the above assumptions, we can obtain the following lemma. 
	\begin{Lemma}\label{lemma_boundness_expression}
		Assuming the initial energy is stable, i.e., $E^0 < C$ for some constant $C$. Then, for all $1<m\leq N-1$, and $S \geq {3L}/{\Delta t}$, and given the initial value of the numerical solutions $\phi^0,$ $\phi^1$, $\mu^0$, $\mu^1$, $\boldsymbol{u}^0$, $\boldsymbol{u}^1$. The solutions $\left(\phi^{n+1},\mu^{n+1},\boldsymbol{u}^{n+1},p^{n+1}\right)$ of scheme \eqref{eq_variational_form_Alg2} satisfly the following bounds
		\begin{flalign}
			\|\nabla\phi^{m+1}\|^2+\|\nabla\left(2\phi^{m+1}-\phi^m\right)\|^2+\|\nabla\left(\phi^{m+1}-\phi^m\right)\|^2\leq&~ C,\\
			\|\boldsymbol{u}^{m+1}\|^2+\|2\boldsymbol{u}^{m+1}-\boldsymbol{u}^m\|^2+\|\boldsymbol{u}^{m+1}-\boldsymbol{u}^m\|^2\leq &~C,\\
			\left(F(\phi^{m+1}),1\right)+\frac{1}{2}\left(F(\phi^{m+1})-F(\phi^m),1\right)\leq &~C,\\
			S\Delta t\sum_{n=1}^{m}\|\phi^{n+1}-2\phi^n+\phi^{n-1}\|^2\leq &~C,\\
			\sum_{n=1}^{m}\left(\|\nabla\left(\phi^{n+1}-2\phi^n+\phi^{n-1}\right)\|^2
			+\|\boldsymbol{u}^{n+1}-2\boldsymbol{u}^n+\boldsymbol{u}^{n-1}\|^2\right)\leq &~C,\\
			\Delta t\sum_{n=1}^{m}\left(\|\nabla \mathcal{B}(\mu^{n+1})\|^2+ \|\nabla \mathcal{B}(\boldsymbol{u}^{n+1})\|^2\right)\leq &~C,
		\end{flalign}
		where $C$ is the positive constant which depend on the initial values.
	\end{Lemma}
	\section{Error Estimates}\label{section_numerical_analysis}
	In the section, we analyze the error estimates for time semi-discrete scheme \eqref{eq_variational_form_Alg2}. 
	Let $\phi(t^{n+1})$, $\mu(t^{n+1})$, $\boldsymbol{u}(t^{n+1})$ and $p(t^{n+1})$
	be the exact solution of the CHNS equation at $t^{n+1}$.
	We denote the errors as follows:
	\begin{equation*}
		\label{eq_error_definitions}
		\begin{aligned}
			e^{n+1}_{\phi} &:= \phi(t^{n+1}) - \phi^{n+1}, \quad e^{n+1}_{\mu} := \mu(t^{n+1}) - \mu^{n+1}, \\
			\boldsymbol{e}^{n+1}_{\boldsymbol{u}} &:= \boldsymbol{u}(t^{n+1}) - \boldsymbol{u}^{n+1}, \quad e^{n+1}_{p} := p(t^{n+1}) - p^{n+1}.
		\end{aligned}
	\end{equation*}
	 For the optimal error estimation, we assume that  the the exact solution of \eqref{eq_variational_form_Alg2} satisfies the following regularity assumptions:
	 \begin{equation}
	 	\label{eq_regularity_001}
	 		\begin{aligned}
	 		&\phi\in L^{\infty}\left(0,T;H^{2}(\Omega)\cap W^{1,\infty}(\Omega)\right),  \phi_{tt}\in L^{\infty}\left(0,T;L^2(\Omega)\right) \cap L^{2}\left(0,T;H^2(\Omega)\right),  \\
	 		& \phi_{ttt}\in L^2\left(0,T;L^2(\Omega)\right),\\
	 		&\mu\in L^{\infty}\left(0,T;H^{1}(\Omega)\right), \mu_{tt}\in L^{2}\left(0,T;H^{2}(\Omega)\right),  \\
	 		&\boldsymbol{u}\in L^{\infty}\left(0,T;\boldsymbol{H}^{2}(\Omega)\right), ~ \boldsymbol{u}_{tt}\in L^{2}\left(0,T;\boldsymbol{H}^{2}(\Omega)\right) \cap L^{\infty}\left(0,T;\boldsymbol{H}^{1}(\Omega)\right),  \\
	 		& \boldsymbol{u}_{ttt}\in L^{2}\left(0,T;\boldsymbol{L}^{2}(\Omega)\right),  \\
	 		& p_{tt}\in L^{2}\left(0,T;L^{2}(\Omega)\right), ~ p_t\in L^2\left(0,T;H^1(\Omega)\right).
	 	\end{aligned}
	 \end{equation}
	The continuous variational form at moment $t^{n+1}$ is shown below: for $\forall \left(\psi, \omega, \boldsymbol{v}, q\right) \in X \times X \times \boldsymbol{Y} \times Q$, 
	\begin{equation}
		\label{eq_continuous_variational_forms}
		\begin{aligned}
			\left(\phi_t(t^{n+1}), \psi\right) + \left(\boldsymbol{u}(t^{n+1}) \cdot \nabla \phi(t^{n+1}), \psi\right) + \left(\nabla \mu(t^{n+1}), \nabla\psi\right) & =   0, \\
			- \left(\mu(t^{n+1}), \omega\right) + \left(\nabla \phi(t^{n+1}), \nabla \omega\right)  + \left(f(\phi(t^{n+1})), \omega\right)  & =   0, \\
			\left(\partial_t \boldsymbol{u}(t^{n+1}), \boldsymbol{v}\right) + \left(\nabla \boldsymbol{u}(t^{n+1}), \nabla \boldsymbol{v}\right) + \left(\boldsymbol{u}(t^{n+1}) \cdot \nabla \boldsymbol{u}(t^{n+1}), \boldsymbol{v}\right) \\
			- \left(p(t^{n+1}), \nabla\cdot \boldsymbol{v}\right) - \left(\mu(t^{n+1}) \nabla \phi(t^{n+1}), \boldsymbol{v}\right)  & =   0, \\
			\left(\nabla \cdot \boldsymbol{u}(t^{n+1}), q\right) & =  0. \\
		\end{aligned}
	\end{equation}
	The equivalent form of \eqref{eq_continuous_variational_forms} is as follows:
	\begin{equation}\label{eq_equivalent_continuous_variational_forms}
		\left\{
		\begin{aligned}
			\frac{1}{\Delta t}\left(\mathcal{A}\left(\phi(t^{n+1})\right), \psi\right) + \left(\mathcal{B}\left(\boldsymbol{u}(t^{n+1})\right) \cdot \nabla \mathcal{B}\left(\phi(t^{n+1})\right), \psi\right) +  \left(\nabla \mathcal{B}(\mu\left(t^{n+1}\right)), \nabla\psi\right) & =  \left(R_1,\psi\right),  \\
			- \left(\mathcal{B}\left(\mu(t^{n+1})\right), \omega\right) + \left(\nabla \mathcal{B}\left(\phi(t^{n+1})\right), \nabla \omega\right)  + \left(2f(\phi(t^{n}))-f(\phi(t^{n-1})), \omega\right)  & = \left(R_2,\omega\right), \\
			\frac{1}{\Delta t}\left(\mathcal{A}\left(\boldsymbol{u}(t^{n+1})\right), \boldsymbol{v}\right) + \left(\nabla \mathcal{B}\left(\boldsymbol{u}(t^{n+1})\right), \nabla \boldsymbol{v}\right) + \left(\mathcal{B}\left(\boldsymbol{u}(t^{n+1})\right) \cdot \nabla \mathcal{B}\left(\boldsymbol{u}(t^{n+1})\right), \boldsymbol{v}\right) \\
			- \left(\mathcal{B}\left(p(t^{n+1})\right), \nabla\cdot \boldsymbol{v}\right) - \left(\mathcal{B}\left(\mu(t^{n+1})\right) \nabla \mathcal{B}\left(\phi(t^{n+1})\right), \boldsymbol{v}\right)  & =  \left(R_3, \boldsymbol{v}\right),\\
			\left(\nabla \cdot \mathcal{B}\left(\boldsymbol{u}(t^{n+1})\right), q\right) & = \left(R_4,q\right), \\
		\end{aligned}\right.
	\end{equation}
	where $R_1$, $R_2$, $R_3$ and $R_4$ is defined by 
	\begin{equation}\label{eq_truncation_error}
		\left\{
		\begin{aligned}
			R_1 &:= \frac{1}{\Delta t}\mathcal{A}\left(\phi(t^{n+1})\right)- \phi_t(t^{n+1})- \Delta \left(\mathcal{B}\left(\mu\left(t^{n+1}\right)\right) - \mu(t^{n+1})\right)\\
			& \quad + \mathcal{B}\left(\boldsymbol{u}(t^{n+1})\right) \cdot \nabla \mathcal{B}\left(\phi(t^{n+1})\right) - \boldsymbol{u}(t^{n+1}) \cdot \nabla \phi(t^{n+1}),  \\
			R_2 &:= - \mathcal{B}\left(\mu(t^{n+1})\right) + \mu(t^{n+1}) -\Delta \left(\mathcal{B}\left(\phi(t^{n+1})\right) - \phi(t^{n+1})\right)\\
			& \quad + 2f(\phi(t^{n}))-f(\phi(t^{n-1}))- f(\phi(t^{n+1})),\\
			R_3 &:= \frac{1}{\Delta t}\mathcal{A}\left(\boldsymbol{u}(t^{n+1})\right) - \boldsymbol{u}_t(t^{n+1})-\Delta\left( \mathcal{B}\left(\boldsymbol{u}(t^{n+1})\right) - \boldsymbol{u}(t^{n+1})\right) \\
			& \quad + \mathcal{B}\left(\boldsymbol{u}(t^{n+1})\right) \cdot \nabla \mathcal{B}\left(\boldsymbol{u}(t^{n+1})\right) - \boldsymbol{u}(t^{n+1}) \cdot \nabla \boldsymbol{u}(t^{n+1})
			 +\nabla \left(\mathcal{B}\left(p(t^{n+1})\right) -  p(t^{n+1})\right)\\
			& \quad -\mathcal{B}\left(\mu(t^{n+1})\right) \nabla \mathcal{B}\left(\phi(t^{n+1})\right) + \mu(t^{n+1}) \nabla \phi(t^{n+1}), \\
			R_4 &:= \nabla \cdot \left(\mathcal{B}\left(\boldsymbol{u}(t^{n+1})\right) - \boldsymbol{u}(t^{n+1})\right).
		\end{aligned}\right.
	\end{equation}
	Then, by subtracting the continuous equation \eqref{eq_equivalent_continuous_variational_forms} from the discrete equation \eqref{eq_variational_form_Alg2} after setting all physical parameters to one, we obtain the following error equation, for $\forall \left(\psi, \omega, \boldsymbol{v}, q\right) \in X \times X \times \boldsymbol{Y} \times Q$,
	\begin{subequations}
		\begin{align}
		\label{eq_error_phi}
		\frac{1}{\Delta t}\left(\mathcal{A}(e^{n+1}_{\phi}), \psi\right) + \left([\mathcal{B}\left(\boldsymbol{u}(t^{n+1})\right) \cdot \nabla \mathcal{B}\left(\phi(t^{n+1})\right) - \mathcal{B}(\boldsymbol{u}^{n+1}) \cdot \nabla \bar{\phi}^{n+1}], \psi\right) \notag\\
		+  \left(\nabla \mathcal{B}(e^{n+1}_{\mu}), \nabla\psi\right) & =  \left(R_1,\psi\right),  \\
		\label{eq_error_mu}
		- \left(\mathcal{B}\left(e^{n+1}_{\mu}\right), \omega\right) + \left(\nabla \mathcal{B}\left(e^{n+1}_{\phi}\right), \nabla \omega\right) - S\Delta t\left(\tilde{\phi}^{n+1}-{\phi}^{n},\omega\right)\notag\\
		+ \left([2f(\phi(t^{n})-f(\phi(t^{n-1}))- 2f(\phi^{n})+f(\phi^{n-1})], \omega\right)  & =\left( R_2, \omega\right),\\
		\label{eq_error_ns}
		\frac{1}{\Delta t}\left(\mathcal{A}\left(e^{n+1}_{\boldsymbol{u}}\right), \boldsymbol{v}\right) + \left(\mathcal{B}\left(\boldsymbol{u}(t^{n+1})\right) \cdot \nabla \mathcal{B}\left(\boldsymbol{u}(t^{n+1})\right) - \bar{\boldsymbol{u}}^{n+1} \cdot \nabla \mathcal{B}\left(\boldsymbol{u}^{n+1}\right), \boldsymbol{v}\right) \notag\\
		+ \left(\nabla \mathcal{B}\left(e^{n+1}_{\boldsymbol{u}}\right), \nabla \boldsymbol{v}\right) - \left(\mathcal{B}\left(\mu(t^{n+1})\right) \nabla \mathcal{B}\left(\phi(t^{n+1})\right) - \mathcal{B}\left(\mu^{n+1}\right) \nabla \bar{\phi}^{n+1}, \boldsymbol{v}\right)  \notag\\
		- \left(\mathcal{B}\left(e^{n+1}_{p}\right), \nabla\cdot \boldsymbol{v}\right) & =  \left(R_3,\boldsymbol{v}\right), \\
		\label{eq_error_incompressible}
		\left(\nabla \cdot \mathcal{B}\left(e^{n+1}_{\boldsymbol{u}}\right), q\right) & = \left(R_4,q\right).
	\end{align}
	\end{subequations}
	We firstly need the following lemmas which will be used in the later analysis.
	\begin{Lemma}[\cite{2020_Aytekin_Cibik_Analysis_of_second_order_time_filtered_backward_Euler_method_for_MHD_equations}]
		\label{lemma_consistency_error}
		Let $w, w_t, w_{t t}, w_{t t t} \in L^2\left(0, T; L^2(\Omega)\right)$, then there exists $C>0$ such that
		\begin{equation*}
			\begin{aligned}
				\Delta t \sum_{n=0}^{N-1}\left\|\mathcal{B}\left(w(t^{n+1})\right) - w(t^{n+1})\right\|^2 &\leq C \left(\Delta t\right)^4\left\|w_{t t}\right\|_{L^2\left(0, T ; L^2(\Omega)\right)}^2, \\
				\Delta t \sum_{n=0}^{N-1}\left\|\frac{1}{\Delta t}\mathcal{A}\left(w(t^{n+1})\right) - w_t(t^{n+1})\right\|^2 &\leq C \left(\Delta t\right)^4\left\|w_{t t t}\right\|_{L^2\left(0, T ; L^2(\Omega)\right)}^2.
			\end{aligned}
		\end{equation*}
	\end{Lemma}
    \noindent The following two lemmas' proofs can be found in the Appendix \ref{Appendix-Lemma-4.2} and Appendix \ref{Appendix-Lemma-4.3}.
    \begin{Lemma}\label{Lemma_Estimation_Truncation_error}
    	For the truncation errors defined in \eqref{eq_truncation_error}, we have
    	\begin{equation*}
    		\begin{aligned}
    			\| R_1 \| &\leq C  \left\|\frac{1}{\Delta t}\mathcal{A}\left(\phi(t^{n+1})\right)- \phi_t(t^{n+1})\right\| + C \|\Delta \left(\mathcal{B}\left(\mu\left(t^{n+1}\right) \right)- \mu(t^{n+1})\right)\|   \\
    			& \quad + C \|\mathcal{B}\left(\boldsymbol{u}(t^{n+1})\right) - \boldsymbol{u}(t^{n+1})\|_1 \cdot \|\mathcal{B}\left(\phi(t^{n+1})\right)\|_2  \\
    			& \quad + C \|\boldsymbol{u}(t^{n+1})\|_1 \cdot \|\phi(t^{n+1}) - \mathcal{B}\left(\phi(t^{n+1})\right)\|_2.  \\
    			\| \nabla R_2 \| &\leq C \|\nabla \left(\mathcal{B}(\mu(t^{n+1}))-\mu(t^{n+1})\right)\| + C \|\nabla \Delta \left(\mathcal{B}(\phi(t^{n+1}))-\phi(t^{n+1})\right)\| \\
    			& \quad  + CL\left(\Delta t\right)^2 \|\phi_{tt}\|_{L^{\infty}(0,T;H^1)}.  \\
    			\| R_3 \| &\leq C\left\|\frac{1}{\Delta t}\mathcal{A}(\boldsymbol{u}(t^{n+1}))-\boldsymbol{u}_t(t^{n+1})\right\| + C\left\|\Delta\left(\mathcal{B}(\boldsymbol{u}(t^{n+1}))-\boldsymbol{u}(t^{n+1})\right)\right\|  \\
    			& \quad + C\|\mathcal{B}\left(\boldsymbol{u}(t^{n+1})\right)\|_1 \cdot \left\|\mathcal{B}\left(\boldsymbol{u}(t^{n+1})\right) - \boldsymbol{u}(t^{n+1})\right\|_2  \\
    			& \quad + C\|\boldsymbol{u}(t^{n+1})\|_2 \cdot \left\|\mathcal{B}\left(\boldsymbol{u}(t^{n+1})\right) - \boldsymbol{u}(t^{n+1})\right\|_1  \\
    			& \quad + C\|\mathcal{B}\left(\mu(t^{n+1})\right)\|_1 \cdot \left\|\mathcal{B}\left(\phi(t^{n+1})\right) - \phi(t^{n+1}) \right\|_2  \\
    			& \quad + C\|\phi(t^{n+1})\|_2 \cdot \left\|\mathcal{B}\left(\mu(t^{n+1})\right) - \mu(t^{n+1})\right\|_1  \\
    			& \quad + C \|\nabla\mathcal{B}(p(t^{n+1}))-p(t^{n+1}))\|.
    		\end{aligned}
    	\end{equation*}
    \end{Lemma}
    \begin{Lemma}\label{Lemma_A_e_phi_dt}
    	We can bound as
    	\begin{equation}\label{eq_A_e_phi_dt}
    		\begin{aligned}
    			\left\|\frac{\mathcal{A}(e_{\phi}^{n+1})}{\Delta t}\right\|_{-1} &\leq C\Bigg\|\mathcal{B}(\phi(t^{n+1}))\Bigg\|_2 \cdot \Bigg\|\mathcal{B}(e_{\boldsymbol{u}}^{n+1})\Bigg\| + C\Bigg\|\nabla\mathcal{B}(\boldsymbol{u}^{n+1})\Bigg\| \cdot  \Bigg\|\nabla\left(2e_{\phi}^n-e_{\phi}^{n-1}\right)\Bigg\|  \\
    			& \quad + C\left(\Delta t\right)^2 \Bigg\|\nabla \mathcal{B}(\boldsymbol{u}^{n+1})\Bigg\| \cdot\Bigg\|\phi_{tt}\Bigg\|_{L^{\infty}(0,T;H^1)} + \Bigg\|\nabla \mathcal{B}(e^{n+1}_{\mu})\Bigg\| + C\Bigg\|R_1\Bigg\|.
    		\end{aligned}
    	\end{equation}
    \end{Lemma}
	Next, we can obtain the following lemma.
	\begin{Lemma}\label{lemma_main_results}
		We can obtain
		\begin{equation}\label{eq_main_results}
			\begin{aligned}
				\frac{1}{4 \Delta t}&\bigg(\|\nabla e_{\phi}^{n+1}\|^2+\|\nabla \left(2e_{\phi}^{n+1}-e_{\phi}^n\right)\|^2
				+\|\nabla \left(e_{\phi}^{n+1}-e_{\phi}^n\right)\|^2  \\ 
				& \qquad  +\|e_{\boldsymbol{u}}^{n+1}\|^2+\|2e_{\boldsymbol{u}}^{n+1}-e_{\boldsymbol{u}}^n\|^2
				+\|e_{\boldsymbol{u}}^{n+1}-e_{\boldsymbol{u}}^n\|^2\bigg)\\
				&-\frac{1}{4 \Delta t}\bigg(\|\nabla e_{\phi}^{n}\|^2+\|\nabla \left(2e_{\phi}^{n}-e_{\phi}^{n-1}\right)\|^2
				+\|\nabla \left(e_{\phi}^{n}-e_{\phi}^{n-1}\right)\|^2  \\  
				& \qquad +\|e_{\boldsymbol{u}}^{n}\|^2+\|2e_{\boldsymbol{u}}^{n}-e_{\boldsymbol{u}}^{n-1}\|^2
				+\|e_{\boldsymbol{u}}^{n}-e_{\boldsymbol{u}}^{n-1}\|^2\bigg)\\
				& + \frac12\|\nabla\mathcal{B}(e_{\mu}^{n+1})\|^2 + \frac12\|\nabla\mathcal{B}(e_{\boldsymbol{u}}^{n+1})\|^2 + S \|\mathcal{A}(e_{\phi}^{n+1})\|^2\\
				& +\frac{3}{4 \Delta t}\left(\|\nabla \left(e_{\phi}^{n+1}-2e_{\phi}^n+e_{\phi}^{n-1}\right)\|^2
				+\| e_{\boldsymbol{u}}^{n+1}-2e_{\boldsymbol{u}}^n+e_{\boldsymbol{u}}^{n-1}\|^2\right)\\
				\leq ~ & C \|R_1\|^2 + C \|\nabla R_2\|^2 + C \|R_3\|^2 + \epsilon_{\phi}\left\| \frac{\mathcal{A}(e_{\phi}^{n+1})}{\Delta t} \right\|^2_{-1} + C_{1} (\Delta t)^4 \\
				& + C_u \left(\|\mathcal{B}(e^{n+1}_{\boldsymbol{u}})\|^2 + \|2e^{n}_{\boldsymbol{u}} - e^{n-1}_{\boldsymbol{u}} \|^2\right) \\
				& + C_{\phi}\left(\|\nabla e_{\phi}^{n}\|^2+\|\nabla\left(2e_{\phi}^{n}-e_{\phi}^{n-1}\right)\|^2+\|\nabla\left(e_{\phi}^{n}-e_{\phi}^{m-1}\right)\|^2\right),
			\end{aligned}
		\end{equation}
	    where $\epsilon_{\phi}$ is some positive constant, and 
	    \begin{equation}\label{eq_three_symobols}
	    	\begin{aligned}
	    		C_{1} &:= C\left(\|\nabla \mathcal{B}(\boldsymbol{u}^{n+1})\|^2 \cdot\|\phi_{tt}\|^2_{L^{\infty}(0,T;H^1)} + S^2 \|\phi_t\|_{L^{\infty}(0,T;H^1)} \right.  \\
	    		& \left. \quad + \|\nabla\mathcal{B}(\boldsymbol{u}^{n+1})\|^2\cdot \left\|\boldsymbol{u}_{tt} \right\|^2_{L^{\infty}(0,T;H^1)} + \|\nabla\mathcal{B}(\mu^{n+1})\|^2\cdot\|\phi_{tt}\|_{L^{\infty}(0,T;H^1)}^2 \right)  \\
	    		C_u &:= C \max\left\{\|\mathcal{B}(\phi(t^{n+1}))\|^2_2, \; \| \mathcal{B}(\boldsymbol{u}(t^{n+1}))\|^2_2\right\}  \\
	    		C_{\phi} &:= C \max\left\{\frac{36L^2}{\epsilon_{\phi}}, \; \frac{12L^2}{\epsilon_{\phi}} + \|\nabla \mathcal{B}(\boldsymbol{u}^{n+1})\|^2 + \|\nabla \mathcal{B}(\mu^{n+1})\|^2\right\}.
	    	\end{aligned}
	    \end{equation}
	\end{Lemma}
	\begin{proof}
		Setting $\psi=\mathcal{B}(e_{\mu}^{n+1})$ in \eqref{eq_error_phi}, $\omega=\mathcal{A}(e_{\phi}^{n+1})/\Delta t$ in \eqref{eq_error_mu},
		$\boldsymbol{v}=\mathcal{B}(e_{\boldsymbol{u}}^{n+1})$ in \eqref{eq_error_ns}, $q=\mathcal{B}(e_p^{n+1})$ in \eqref{eq_error_incompressible}, and using the fact that $\nabla\cdot\boldsymbol{u}(t)=0$ for $t = t_{n+1}, t_n, t_{n-1}$ to get the vanishing $R_4$, then using \eqref{eq_A_B_form}, we have
		\begin{equation}\label{eq_error_phi_inner_product_e_phi}
			\begin{aligned}
				\frac{1}{4 \Delta t}&\bigg(\|\nabla e_{\phi}^{n+1}\|^2+\|\nabla \left(2e_{\phi}^{n+1}-e_{\phi}^n\right)\|^2
				+\|\nabla \left(e_{\phi}^{n+1}-e_{\phi}^n\right)\|^2  \\ 
				& \qquad  +\|e_{\boldsymbol{u}}^{n+1}\|^2+\|2e_{\boldsymbol{u}}^{n+1}-e_{\boldsymbol{u}}^n\|^2
				+\|e_{\boldsymbol{u}}^{n+1}-e_{\boldsymbol{u}}^n\|^2\bigg)\\
				&-\frac{1}{4 \Delta t}\bigg(\|\nabla e_{\phi}^{n}\|^2+\|\nabla \left(2e_{\phi}^{n}-e_{\phi}^{n-1}\right)\|^2
				+\|\nabla \left(e_{\phi}^{n}-e_{\phi}^{n-1}\right)\|^2  \\  
				& \qquad +\|e_{\boldsymbol{u}}^{n}\|^2+\|2e_{\boldsymbol{u}}^{n}-e_{\boldsymbol{u}}^{n-1}\|^2
				+\|e_{\boldsymbol{u}}^{n}-e_{\boldsymbol{u}}^{n-1}\|^2\bigg)\\
				& + \|\nabla\mathcal{B}(e_{\mu}^{n+1})\|^2 + \|\nabla\mathcal{B}(e_{\boldsymbol{u}}^{n+1})\|^2 \\
				& +\frac{3}{4 \Delta t}\left(\|\nabla \left(e_{\phi}^{n+1}-2e_{\phi}^n+e_{\phi}^{n-1}\right)\|^2
				+\| e_{\boldsymbol{u}}^{n+1}-2e_{\boldsymbol{u}}^n+e_{\boldsymbol{u}}^{n-1}\|^2\right)\\
				=& \left(R_1,\mathcal{B}(e_{\mu}^{n+1})\right) - \left(\mathcal{B}(\boldsymbol{u}(t^{n+1})) \cdot \nabla \mathcal{B}\left(\phi(t^{n+1})\right) - \mathcal{B}(\boldsymbol{u}^{n+1}) \cdot \nabla \bar{\phi}^{n+1}, \mathcal{B}(e_{\mu}^{n+1})\right)\\
				& - \left(2f\left(\phi(t^{n+1})\right)-f(\phi(t^{n}))-\left(2f(\phi^{n})-f(\phi^{n-1})\right), \frac{\mathcal{A}(e_{\phi}^{n+1})}{\Delta t}\right)  \\
				& + S\Delta t \left(\tilde{\phi}^{n+1}-{\phi}^{n},\frac{\mathcal{A}(e_{\phi}^{n+1})}{\Delta t}\right)  + \left(R_2,\frac{\mathcal{A}(e_{\phi}^{n+1})}{\Delta t}\right) + \left(R_3,\mathcal{B}(e_{\boldsymbol{u}}^{n+1})\right)\\
				& - \left(\mathcal{B}(\boldsymbol{u}(t^{n+1}))\cdot\nabla\mathcal{B}(\boldsymbol{u}(t^{n+1}))-\bar{\boldsymbol{u}}^{n+1}\cdot\nabla\mathcal{B}(\boldsymbol{u}^{n+1}),\mathcal{B}(e_{\boldsymbol{u}}^{n+1})\right)\\
				& + \left(\mathcal{B}(\mu(t^{n+1}))\nabla\mathcal{B}(\phi(t^{n+1}))-\mathcal{B}(\mu^{n+1})\nabla\bar{\phi}^{n+1},\mathcal{B}(e_{\boldsymbol{u}}^{n+1})\right).
			\end{aligned}
		\end{equation}
	We bound the terms on the RHS of \eqref{eq_error_phi_inner_product_e_phi}, term by term as follows. Using the definition of $R_1$ in \eqref{eq_truncation_error},  we have 
	\begin{equation}
		\label{eq_first_terms_bound}
		\begin{aligned}
			\bigg|\left(R_1,\mathcal{B}(e_{\mu}^{n+1})\right)\bigg| \leq C \|R_1\|^2 + \frac{\epsilon_{\mu}}{3}  \|\nabla \mathcal{B}(e_{\mu}^{n+1})\|^2 .
		\end{aligned}
	\end{equation}
	The second term on the right-hand side of \eqref{eq_error_phi_inner_product_e_phi} can be estimated by
	\begin{equation}\label{eq_second_term_bound}
		\begin{aligned}
			&~\bigg|\left(\mathcal{B}(\boldsymbol{u}(t^{n+1})) \cdot \nabla \mathcal{B}\left(\phi(t^{n+1})\right) - \mathcal{B}(\boldsymbol{u}^{n+1}) \cdot \nabla \bar{\phi}^{n+1}, \mathcal{B}(e_{\mu}^{n+1})\right)\bigg|\\
			= &~ \bigg|\left(\mathcal{B}(e_{\boldsymbol{u}}^{n+1})\nabla\mathcal{B}(\phi(t^{n+1}))+\mathcal{B}(\boldsymbol{u}^{n+1})\nabla\left(\mathcal{B}(\phi(t^{n+1}))-2\phi(t^{n})+\phi(t^{n-1})\right), \mathcal{B}(e_{\mu}^{n+1})\right)\\
			&~+\left(\mathcal{B}(\boldsymbol{u}^{n+1})\nabla\left(2e_{\phi}^n-e_{\phi}^{n-1}\right),\mathcal{B}(e_{\mu}^{n+1})\right)\bigg|\\
			\leq & ~ C \|\mathcal{B}(\phi(t^{n+1}))\|_2 \|\mathcal{B}(e_{\boldsymbol{u}}^{n+1})\| \|\nabla\mathcal{B}(e_{\mu}^{n+1})\| + C \|\nabla\mathcal{B}(\boldsymbol{u}^{n+1})\| \|\nabla\left(2e_{\phi}^n-e_{\phi}^{n-1}\right)\| \|\nabla \mathcal{B}(e_{\mu}^{n+1})\| \\
			& + C \|\nabla\mathcal{B}(\boldsymbol{u}^{n+1})\| \|\nabla\left(\mathcal{B}(\phi(t^{n+1}))-2\phi(t^{n})+\phi(t^{n-1})\right)\| \|\nabla\mathcal{B}(e_{\mu}^{n+1})\|  \\
			\leq & ~ \frac{\epsilon_{\mu}}{3} \|\nabla\mathcal{B}(e_{\mu}^{n+1})\|^2 + C \|\mathcal{B}(\phi(t^{n+1}))\|^2_2 \cdot\|\mathcal{B}(e_{\boldsymbol{u}}^{n+1})\|^2 + C \left(\Delta t\right)^4 \|\nabla \mathcal{B}(\boldsymbol{u}^{n+1})\|^2 \cdot\|\phi_{tt}\|^2_{L^{\infty}(0,T;H^1)} \\
			& + C \|\nabla \mathcal{B}(\boldsymbol{u}^{n+1})\|^2 \cdot \|\nabla \left(2e_{\phi}^n-e_{\phi}^{n-1}\right)\|^2. %  \quad {\color{red}\text{( here we need the stability: } \|\nabla \mathcal{B}(\boldsymbol{u}^{n+1})\|^2 \leq C) }
		\end{aligned}
	\end{equation}
	Using the \eqref{eq_phi_condition}, the third term on the right-hand side of \eqref{eq_error_phi_inner_product_e_phi} can be estimated by
	\begin{equation}
		\label{eq_third_term_bound}
		\begin{aligned}
			&\bigg|\left(2f\left(\phi(t^{n})\right)-f(\phi(t^{n-1}))-\left(2f(\phi^{n})-f(\phi^{n-1})\right), \frac{\mathcal{A}(e_{\phi}^{n+1})}{\Delta t}\right)\bigg|\\
			\leq & \left\|\nabla \left(2f\left(\phi(t^{n})\right)-f(\phi(t^{n-1}))-\left(2f(\phi^{n})-f(\phi^{n-1})\right)\right) \right\|\cdot \left\| \frac{\mathcal{A}(e_{\phi}^{n+1})}{\Delta t} \right\|_{-1}  \\
			\leq & \frac{\epsilon_{\phi}}{3} \left\| \frac{\mathcal{A}(e_{\phi}^{n+1})}{\Delta t} \right\|^2_{-1} + \frac{3}{\epsilon_{\phi}} \|2f^{\prime}\left(\xi_1\right) \nabla e^n_{\phi} - f^{\prime}\left(\xi_2\right) \nabla e^{n-1}_{\phi}\|^2 \\
			\leq & \frac{\epsilon_{\phi}}{3} \left\| \frac{\mathcal{A}(e_{\phi}^{n+1})}{\Delta t} \right\|^2_{-1} + \frac{6L^2}{\epsilon_{\phi}} \left(\|2\nabla e^n_{\phi}\|^2 + \|\nabla e^{n-1}_{\phi}\|^2\right) \\
			\leq & \frac{\epsilon_{\phi}}{3} \left\| \frac{\mathcal{A}(e_{\phi}^{n+1})}{\Delta t} \right\|^2_{-1} + \frac{6L^2}{\epsilon_{\phi}} \left(2\left\|\nabla \left(2e^n_{\phi} - e^{n-1}_{\phi}\right)\right\|^2 + 6\left\|\nabla \left(e^n_{\phi} - e^{n-1}_{\phi}\right)\right\|^2 + 6\left\|\nabla e^n_{\phi}\right\|^2\right)
		\end{aligned}
	\end{equation}
	The fourth and fifth terms on the right-hand side of \eqref{eq_error_phi_inner_product_e_phi} can be bounded by
	\begin{equation}
		\label{eq_fourth_term_bound}
		\begin{aligned}
			&S\Delta t\left(\tilde{\phi}^{n+1}-{\phi}^{n}, \frac{\mathcal{A}(e_{\phi}^{n+1})}{\Delta t}\right) = S\Delta t\left(\mathcal{A}(\phi^{n+1}), \frac{\mathcal{A}(e_{\phi}^{n+1})}{\Delta t}\right) \\
			=~ & S\Delta t\left(\mathcal{A}(\phi(t^{n+1})) - \mathcal{A}(e_{\phi}^{n+1}), \frac{\mathcal{A}(e_{\phi}^{n+1})}{\Delta t}\right)  \\
			=~ & - S \|\mathcal{A}(e_{\phi}^{n+1})\|^2 + S\Delta t\left(\mathcal{A}(\phi(t^{n+1})), \frac{\mathcal{A}(e_{\phi}^{n+1})}{\Delta t}\right)  \\
			\leq & ~ - S \|\mathcal{A}(e_{\phi}^{n+1})\|^2 + S\Delta t \|\nabla \mathcal{A}(\phi(t^{n+1}))\| \cdot \left\|\frac{\mathcal{A}(e_{\phi}^{n+1})}{\Delta t}\right\|_{-1}  \\
			\leq & ~ - S \|\mathcal{A}(e_{\phi}^{n+1})\|^2 + \frac{\epsilon_{\phi}}{3} \left\| \frac{\mathcal{A}(e_{\phi}^{n+1})}{\Delta t} \right\|^2_{-1} + CS^2(\Delta t)^4 \|\phi_t\|^2_{L^{\infty}(0,T;H^1)}.
		\end{aligned}
	\end{equation}
	and 
	\begin{equation}
		\label{eq_fifth_term_bound}
		\begin{aligned}
			\bigg|\left(R_2, \frac{\mathcal{A}(e_{\phi}^{n+1})}{\Delta t}\right)\bigg| \leq C\| \nabla R_2\|^2 + \frac{\epsilon_{\phi}}{3} \left\| \frac{\mathcal{A}(e_{\phi}^{n+1})}{\Delta t} \right\|^2_{-1}.
		\end{aligned}
	\end{equation}
	The sixth term on the right-hand side of \eqref{eq_error_phi_inner_product_e_phi} can be bounded by
	\begin{equation}
		\label{eq_sixth_term_bound}
		\begin{aligned}
			\left|\left(R_3,\mathcal{B}(e_{\boldsymbol{u}}^{n+1})\right)\right| \leq C\|R_3\|^2 + \frac{\epsilon_{\boldsymbol{u}}}{3} \|\nabla\mathcal{B}(e_{\boldsymbol{u}}^{n+1})\|^2.
		\end{aligned}
	\end{equation}
	The seventh term on the right-hand side of \eqref{eq_error_phi_inner_product_e_phi} can be bounded by
	\begin{equation}
		\label{eq_seventh_term_bound}
		\begin{aligned}
			& \bigg|-\left(\mathcal{B}(\boldsymbol{u}(t^{n+1}))\cdot\nabla\mathcal{B}(\boldsymbol{u}(t^{n+1}))-\bar{\boldsymbol{u}}^{n+1}\cdot\nabla\mathcal{B}(\boldsymbol{u}^{n+1}),\mathcal{B}(e_{\boldsymbol{u}}^{n+1})\right)\bigg|\\
			= & \bigg|\left(\mathcal{B}(\boldsymbol{u}(t^{n+1}))\cdot\nabla\mathcal{B}(\boldsymbol{u}(t^{n+1})-\boldsymbol{u}^{n+1})+\left(\mathcal{B}(\boldsymbol{u}(t^{n+1}))-\bar{\boldsymbol{u}}^{n+1}\right)\cdot\nabla\mathcal{B}(\boldsymbol{u}^{n+1}),\mathcal{B}(e_{\boldsymbol{u}}^{n+1})\right)\bigg|\\
			\leq& \bigg|\left(\mathcal{B}(\boldsymbol{u}(t^{n+1}))\cdot\nabla\mathcal{B}(e_{\boldsymbol{u}}^{n+1}),\mathcal{B}(e_{\boldsymbol{u}}^{n+1})\right)\bigg| + \bigg|\left(\left(2e_{\boldsymbol{u}}^{n}-e_{\boldsymbol{u}}^{n-1}\right)\cdot\nabla\mathcal{B}(\boldsymbol{u}(t^{n+1})),\mathcal{B}(e_{\boldsymbol{u}}^{n+1})\right)\bigg|\\
			&   +  \bigg|\left(\left(\mathcal{B}(\boldsymbol{u}(t^{n+1}))-2\boldsymbol{u}(t^{n})+\boldsymbol{u}(t^{n-1})\right)\cdot\nabla\mathcal{B}(\boldsymbol{u}^{n+1}),\mathcal{B}(e_{\boldsymbol{u}}^{n+1})\right)\bigg|  \\
			\leq &  C\|\mathcal{B}(\boldsymbol{u}(t^{n+1}))\|^2_2 \cdot\|2e_{\boldsymbol{u}}^{n}-e_{\boldsymbol{u}}^{n-1}\|^2   
			+ \frac{\epsilon_{\boldsymbol{u}}}{3} \|\nabla\mathcal{B}(e_{\boldsymbol{u}}^{n+1})\|^2   \\ 
			&   + C  \|\nabla\mathcal{B}(\boldsymbol{u}^{n+1})\|^2 \cdot \left\|\nabla \left(\mathcal{B}(\boldsymbol{u}(t^{n+1}))-2\boldsymbol{u}(t^{n})+\boldsymbol{u}(t^{n-1})\right) \right\|^2   \\
			\leq & C  \| \mathcal{B}(\boldsymbol{u}(t^{n+1}))\|^2_2 \cdot\|2e_{\boldsymbol{u}}^{n}-e_{\boldsymbol{u}}^{n-1}\|^2 + \frac{\epsilon_{\boldsymbol{u}}}{3}  \|\nabla\mathcal{B}(e_{\boldsymbol{u}}^{n+1})\|^2 \\
			& +  C\left(\Delta t\right)^4 \|\nabla\mathcal{B}(\boldsymbol{u}^{n+1})\|^2\cdot \left\|\boldsymbol{u}_{tt} \right\|^2_{L^{\infty}(0,T;H^1)}. 
		\end{aligned}
	\end{equation}
	The eighth term on the right-hand side of \eqref{eq_error_phi_inner_product_e_phi} can be bounded by
	\begin{equation}
		\label{eq_eighth_term_bound}
		\begin{aligned}
			&\bigg|\left(\mathcal{B}(\mu(t^{n+1}))\nabla\mathcal{B}(\phi(t^{n+1}))-\mathcal{B}(\mu^{n+1})\nabla\bar{\phi}^{n+1},\mathcal{B}(e_{\boldsymbol{u}}^{n+1})\right)\bigg|\\
			=& \bigg| \left(\mathcal{B}(\mu(t^{n+1})-\mu^{n+1})\nabla \mathcal{B}(\phi(t^{n+1})),\mathcal{B}(e_{\boldsymbol{u}}^{n+1})\right)  \\
			&  +\left(\mathcal{B}(\mu^{n+1})\nabla\left(2e_{\phi}^n-e_{\phi}^{n-1}\right),\mathcal{B}(e_{\boldsymbol{u}}^{n+1})\right) \\
			& + \left(\mathcal{B}(\mu^{n+1})\nabla\left(\mathcal{B}(\phi(t^{n+1}))-2\phi(t^{n})+\phi(t^{n-1})\right),\mathcal{B}(e_{\boldsymbol{u}}^{n+1})\right) \bigg|  \\
			\leq&~  C\|\nabla \mathcal{B}(e_{\mu}^{n+1})\|\cdot\|\mathcal{B}(\phi(t^{n+1}))\|_{2} \cdot\| \mathcal{B}(e_{\boldsymbol{u}}^{n+1})\| \\
			& + C\|\nabla \mathcal{B}(\mu^{n+1})\|\cdot \left\|\nabla \left(2e_{\phi}^{n}-e_{\phi}^{n-1}\right)\right\|\cdot\|\nabla \mathcal{B}(e_{\boldsymbol{u}}^{n+1})\|  \\
			& +  C \|\nabla \mathcal{B}(\mu^{n+1})\|\cdot\|\nabla\left(\phi(t^{n+1})-2\phi(t^n)+\phi(t^{n-1})\right)\|\cdot\|\nabla \mathcal{B}(e_{\boldsymbol{u}}^{n+1})\| \\
			\leq&~  C \|\mathcal{B}(\phi(t^{n+1}))\|^2_{2}\cdot\|\mathcal{B}(e_{\boldsymbol{u}}^{n+1})\|^2 + \frac{\epsilon_{\mu}}{3} \|\nabla \mathcal{B}(e_{\mu}^{n+1})\|^2 \\
			& + C \|\nabla \mathcal{B}(\mu^{n+1})\|^2\cdot \left\|\nabla \left(2e_{\phi}^{n}-e_{\phi}^{n-1}\right)\right\|^2 \\
			&  + \frac{\epsilon_{\boldsymbol{u}}}{3} \|\nabla\mathcal{B}(e_{\boldsymbol{u}}^{n+1})\|^2 
			+ C\left(\Delta t\right)^4\|\nabla\mathcal{B}(\mu^{n+1})\|^2\cdot\|\phi_{tt}\|_{L^{\infty}(0,T;H^1)}^2.
		\end{aligned}
	\end{equation}
    Combining the above inequalities \eqref{eq_first_terms_bound}-\eqref{eq_eighth_term_bound} with \eqref{eq_error_phi_inner_product_e_phi}, and choosing $\epsilon_{\mu} = \epsilon_{\boldsymbol{u}} = 1/2$ can complete this proof.
	\end{proof}

    Finally, we obtain the error estimation of scheme \eqref{eq_variational_form_Alg2} in the following theorem.
    \begin{Theorem}\label{theorem_main_results}
    	Supposing the regularity assumptions \eqref{eq_regularity_001} hold, and assuming $\Delta t$ small enough such that $C^*\Delta t \leq 1$, where 
    	$$
    	\begin{aligned}
    		C^* :=& \max\left\{C \max\left\{\|\mathcal{B}(\phi(t^{n+1}))\|^2_2, \; \|\mathcal{B}(\boldsymbol{u}(t^{n+1}))\|^2_2\right\}, \right. \\
    		& \qquad\; \left. C \max\left\{3L^2, \; L^2 + \|\nabla \mathcal{B}(\boldsymbol{u}^{n+1})\|^2 + \|\nabla \mathcal{B}(\mu^{n+1})\|^2\right\}\right\}.
    	\end{aligned}
    	$$
    	Then, for all $1\leq m\leq N-1$, there exists a positive constant $C$ such that the solution of scheme \eqref{eq_variational_form_Alg2} fulfills error estimations
    	\begin{equation}
    		\begin{aligned}
    			\|\nabla e_{\phi}^{m+1}\|^2&+\|\nabla\left(2e_{\phi}^{m+1}-e_{\phi}^n\right)\|^2+\|\nabla\left(e_{\phi}^{m+1}-e_{\phi}^{m}\right)\|^2  \\
    			& \quad 
    			+\|e_{\boldsymbol{u}}^{m+1}\|^2+\|2e_{\boldsymbol{u}}^{m+1}-e_{\boldsymbol{u}}^m\|^2+\|e_{\boldsymbol{u}}^{m+1}-e_{\boldsymbol{u}}^{m}\|^2\\
    			&+\Delta t\sum_{n=1}^{m}\|\nabla\mathcal{B}(e_{\mu}^{n+1})\|^2 + \Delta t\sum_{n=1}^{m}\|\nabla\mathcal{B}(e_{\boldsymbol{u}}^{n+1})\|^2 + \Delta t\sum_{n=1}^{m}\|\nabla\mathcal{B}(e_{\phi}^{n+1})\|^2  \\
    			\leq & C\Big(\left(\Delta t\right)^4 + \|\nabla e_{\phi}^{1}\|^2 + \|\nabla (2e_{\phi}^{1}-e_{\phi}^{0})\|^2
    			+\|\nabla (e_{\phi}^{n}-e_{\phi}^{0})\|^2  \\
    			& + \|e_{\boldsymbol{u}}^{1}\|^2+\|2e_{\boldsymbol{u}}^{1}-e_{\boldsymbol{u}}^{0}\|^2
    			+\|e_{\boldsymbol{u}}^{1}-e_{\boldsymbol{u}}^{0}\|^2\Big).
    		\end{aligned}
    	\end{equation}
    \end{Theorem}
    \begin{proof}
    	Inserting \eqref{eq_A_e_phi_dt} in the Lemma \ref{Lemma_A_e_phi_dt} into the \eqref{eq_main_results}  in the Lemma \ref{lemma_main_results} to get
    	\begin{equation}
    		\begin{aligned}
    			\frac{1}{4 \Delta t}&\bigg(\|\nabla e_{\phi}^{n+1}\|^2+\|\nabla \left(2e_{\phi}^{n+1}-e_{\phi}^n\right)\|^2
    			+\|\nabla \left(e_{\phi}^{n+1}-e_{\phi}^n\right)\|^2  \\ 
    			& \qquad  +\|e_{\boldsymbol{u}}^{n+1}\|^2+\|2e_{\boldsymbol{u}}^{n+1}-e_{\boldsymbol{u}}^n\|^2
    			+\|e_{\boldsymbol{u}}^{n+1}-e_{\boldsymbol{u}}^n\|^2\bigg)\\
    			&-\frac{1}{4 \Delta t}\bigg(\|\nabla e_{\phi}^{n}\|^2+\|\nabla \left(2e_{\phi}^{n}-e_{\phi}^{n-1}\right)\|^2
    			+\|\nabla \left(e_{\phi}^{n}-e_{\phi}^{n-1}\right)\|^2  \\  
    			& \qquad +\|e_{\boldsymbol{u}}^{n}\|^2+\|2e_{\boldsymbol{u}}^{n}-e_{\boldsymbol{u}}^{n-1}\|^2
    			+\|e_{\boldsymbol{u}}^{n}-e_{\boldsymbol{u}}^{n-1}\|^2\bigg)\\
    			& + \frac12\|\nabla\mathcal{B}(e_{\mu}^{n+1})\|^2 + \frac12\|\nabla\mathcal{B}(e_{\boldsymbol{u}}^{n+1})\|^2 + S \|\mathcal{A}(e_{\phi}^{n+1})\|^2\\
    			& +\frac{3}{4 \Delta t}\left(\|\nabla \left(e_{\phi}^{n+1}-2e_{\phi}^n+e_{\phi}^{n-1}\right)\|^2
    			+\| e_{\boldsymbol{u}}^{n+1}-2e_{\boldsymbol{u}}^n+e_{\boldsymbol{u}}^{n-1}\|^2\right)\\
    			\leq ~ & C \|R_1\|^2 + C \|\nabla R_2\|^2 + C \|R_3\|^2 + \epsilon_{\phi}\left\|\nabla \mathcal{B}(e^{n+1}_{\mu})\right\| ^2 + C_{1} (\Delta t)^4 \\
    			& + \tilde{C}_u \left(\|\mathcal{B}(e^{n+1}_{\boldsymbol{u}})\|^2 + \|2e^{n}_{\boldsymbol{u}} - e^{n-1}_{\boldsymbol{u}} \|^2\right) \\
    			& + \tilde{C}_{\phi}\left(\|\nabla e_{\phi}^{n}\|^2+\|\nabla\left(2e_{\phi}^{n}-e_{\phi}^{n-1}\right)\|^2+\|\nabla\left(e_{\phi}^{n}-e_{\phi}^{m-1}\right)\|^2\right),
    		\end{aligned}
    	\end{equation}
    	where $C_{1}$ is defined in \eqref{eq_three_symobols}, $\epsilon_{\phi}$ is some positive constant, and 
    	\begin{equation}
    		\begin{aligned}
    			\tilde{C}_u &:= C \max\left\{2\|\mathcal{B}(\phi(t^{n+1}))\|^2_2, \; \|\mathcal{B}(\boldsymbol{u}(t^{n+1}))\|^2_2\right\}  \\
    			\tilde{C}_{\phi} &:= C \max\left\{\frac{36L^2}{\epsilon_{\phi}}, \; \frac{12L^2}{\epsilon_{\phi}} + 2\|\nabla \mathcal{B}(\boldsymbol{u}^{n+1})\|^2 + \|\nabla \mathcal{B}(\mu^{n+1})\|^2\right\}.
    		\end{aligned}
    	\end{equation}
    	Using the definition of $\mathcal{B}(s^{n+1})$ to obtain, for some $s$, 
    	\begin{equation}
    		\begin{aligned}
    			\|\mathcal{B}(s^{n+1})\|^2 
    			&= \left\|\frac32s^{n+1} - s^{n} + \frac12s^{n-1}\right\|^2  \\
    			&= \frac14 \left\|s^{n+1} + 2s^{n+1} - s^{n} - (s^{n} - s^{n-1})\right\|^2 \\
    			&\leq \frac34 \left(\left\|s^{n+1}\right\|^2 + \left\|2s^{n+1} - s^{n}\right\|^2 + \left\|s^{n} - s^{n-1}\right\|^2\right) \\
    			& \leq \frac34 \left(\left\|s^{n+1}\right\|^2 + \left\|2s^{n+1} - s^{n}\right\|^2 + \left\|s^{n+1} - s^{n}\right\|^2\right) \\
    			& \quad + \frac34 \left(\left\|s^{n}\right\|^2 + \left\|2s^{n} - s^{n-1}\right\|^2 + \left\|s^{n} - s^{n-1}\right\|^2\right),
    		\end{aligned}
    	\end{equation}
        and then, using Lemma \ref{Lemma_Estimation_Truncation_error}, setting $\epsilon_{\phi} = 1/4$, multiplying $4\Delta t$ on both sides and adding from $n=1$ to $n=m(\leq N-1)$ in \eqref{lemma_main_results}, the above inequality becomes
        \begin{equation}
        	\begin{aligned}
        		&\|\nabla e_{\phi}^{m+1}\|^2+\|\nabla \left(2e_{\phi}^{m+1}-e_{\phi}^m\right)\|^2
        		+\|\nabla \left(e_{\phi}^{m+1}-e_{\phi}^m\right)\|^2  \\ 
        		& \qquad  +\|e_{\boldsymbol{u}}^{m+1}\|^2+\|2e_{\boldsymbol{u}}^{m+1}-e_{\boldsymbol{u}}^m\|^2
        		+\|e_{\boldsymbol{u}}^{m+1}-e_{\boldsymbol{u}}^m\|^2 \\
        		& \qquad + 3\Delta t\sum_{n=1}^{m}\left(\|\nabla \left(e_{\phi}^{n+1}-2e_{\phi}^n+e_{\phi}^{n-1}\right)\|^2
        		+\| e_{\boldsymbol{u}}^{n+1}-2e_{\boldsymbol{u}}^n+e_{\boldsymbol{u}}^{n-1}\|^2\right) \\
        		& \qquad + \Delta t\sum_{n=1}^{m}\|\nabla\mathcal{B}(e_{\mu}^{n+1})\|^2 + 2\Delta t\sum_{n=1}^{m}\|\nabla\mathcal{B}(e_{\boldsymbol{u}}^{n+1})\|^2 + 4S\Delta t\sum_{n=1}^{m}\|\mathcal{A}(e_{\phi}^{n+1})\|^2  \\
        		& \leq \|\nabla e_{\phi}^{1}\|^2+\|\nabla \left(2e_{\phi}^{1}-e_{\phi}^0\right)\|^2
        		+ \|\nabla \left(e_{\phi}^{1}-e_{\phi}^0\right)\|^2   + \|e_{\boldsymbol{u}}^{1}\|^2+\|2e_{\boldsymbol{u}}^{1}-e_{\boldsymbol{u}}^0\|^2 + \|e_{\boldsymbol{u}}^{1}-e_{\boldsymbol{u}}^0\|^2  \\
        		& \qquad + C \Delta t\sum_{n=1}^{m} \hat{C}_{\Delta t} + C_{2} \Delta t\sum_{n=1}^{m} (\Delta t)^4 + \Delta t\sum_{n=0}^{m} C^* \bigg(\|e_{\boldsymbol{u}}^{n+1}\|^2+\|2e_{\boldsymbol{u}}^{n+1}-e_{\boldsymbol{u}}^n\|^2 +\|e_{\boldsymbol{u}}^{n+1}-e_{\boldsymbol{u}}^n\|^2  \\ 
        		& \qquad  + \|\nabla e_{\phi}^{n+1}\|^2+\|\nabla \left(2e_{\phi}^{n+1}-e_{\phi}^n\right)\|^2 + \|\nabla \left(e_{\phi}^{n+1}-e_{\phi}^n\right)\|^2\bigg)
        	\end{aligned}
        \end{equation}
        where 
        \begin{equation}
        	\begin{aligned}
        		\hat{C}_{\Delta t} :=& C  \left\|\frac{1}{\Delta t}\mathcal{A}\left(\phi(t^{n+1})\right)- \phi_t(t^{n+1})\right\| + C \|\Delta \left(\mathcal{B}\left(\mu\left(t^{n+1}\right) \right)- \mu(t^{n+1})\right)\|   \\
        		& \quad + C \|\mathcal{B}\left(\boldsymbol{u}(t^{n+1})\right) - \boldsymbol{u}(t^{n+1})\|_1 \cdot \|\mathcal{B}\left(\phi(t^{n+1})\right)\|_2  \\
        		& \quad + C \|\boldsymbol{u}(t^{n+1})\|_1 \cdot \|\phi(t^{n+1}) - \mathcal{B}\left(\phi(t^{n+1})\right)\|_2  \\
        		& \quad + C \|\nabla \left(\mathcal{B}(\mu(t^{n+1}))-\mu(t^{n+1})\right)\| + C \|\nabla \Delta \left(\mathcal{B}(\phi(t^{n+1}))-\phi(t^{n+1})\right)\| \\
        		& \quad + C\left\|\frac{1}{\Delta t}\mathcal{A}(\boldsymbol{u}(t^{n+1}))-\boldsymbol{u}_t(t^{n+1})\right\| + C\left\|\Delta\left(\mathcal{B}(\boldsymbol{u}(t^{n+1}))-\boldsymbol{u}(t^{n+1})\right)\right\|  \\
        		& \quad + C\|\mathcal{B}\left(\boldsymbol{u}(t^{n+1})\right)\|_1 \cdot \left\|\mathcal{B}\left(\boldsymbol{u}(t^{n+1})\right) - \boldsymbol{u}(t^{n+1})\right\|_2  \\
        		& \quad + C\|\boldsymbol{u}(t^{n+1})\|_2 \cdot \left\|\mathcal{B}\left(\boldsymbol{u}(t^{n+1})\right) - \boldsymbol{u}(t^{n+1})\right\|_1  \\
        		& \quad + C\|\mathcal{B}\left(\mu(t^{n+1})\right)\|_1 \cdot \left\|\mathcal{B}\left(\phi(t^{n+1})\right) - \phi(t^{n+1}) \right\|_2  \\
        		& \quad + C\|\phi(t^{n+1})\|_2 \cdot \left\|\mathcal{B}\left(\mu(t^{n+1})\right) - \mu(t^{n+1})\right\|_1  \\
        		& \quad + C \|\nabla\mathcal{B}(p(t^{n+1}))-p(t^{n+1}))\|  \\
        		C_{2} :=& C_{1} + CL^2\left(\Delta t\right)^4 \|\phi_{tt}\|^2_{L^{\infty}(0,T;H^1)}  \\
        		C^* :=& \max\left\{\frac{10}{4}\tilde{C}_u, \tilde{C}_{\phi}\right\}.
        	\end{aligned}
        \end{equation}
    	Finally, using Lemma \ref{lemma_consistency_error}, regularity assumptions \ref{eq_regularity_001}, and stability in \ref{lemma_boundness_expression}, and assuming $\Delta t$ small enough such that $C^*\Delta t \leq 1$, where $C^*$ is defined above, and then applying the discrete Gr\"{o}nwall lemma \ref{lemma_gronwall_inequalities}, we can obtain the results of Theorem \ref{theorem_main_results}.
    \end{proof}




