	\section{Appendix A: Proof of Lemma \ref{Lemma_Estimation_Truncation_error}}\label{Appendix-Lemma-4.2}
	\begin{proof}
		For the first term, by the definition of $R_1,R_2,R_3$, we have
		\begin{equation*}
			\begin{aligned}
				\left\|R_1\right\|
				\leq & \left\|\frac{1}{\Delta t}\mathcal{A}\left(\phi(t^{n+1})\right)- \phi_t(t^{n+1})\right\| + \left\|\Delta\left(\mathcal{B}\left(\mu\left(t^{n+1}\right) \right)- \mu(t^{n+1})\right)\right\| \\
				& \quad + \left\|\left(\mathcal{B}\left(\boldsymbol{u}(t^{n+1})\right) - \boldsymbol{u}(t^{n+1})\right) \cdot \nabla \mathcal{B}\left(\phi(t^{n+1})\right)\right\| \\
				& \quad + \left\|\boldsymbol{u}(t^{n+1}) \cdot \nabla \left(\mathcal{B}\left(\phi(t^{n+1})\right) - \phi(t^{n+1})\right)\right\|  \\
				\leq & C\left\|\frac{1}{\Delta t}\mathcal{A}\left(\phi(t^{n+1})\right)- \phi_t(t^{n+1})\right\| + C\left\|\Delta\left(\mathcal{B}\left(\mu\left(t^{n+1}\right) \right)- \mu(t^{n+1})\right)\right\| \\
				& \quad + C\|\mathcal{B}\left(\boldsymbol{u}(t^{n+1})\right) - \boldsymbol{u}(t^{n+1})\|_1 \cdot \left\|\mathcal{B}\left(\phi(t^{n+1})\right)\right\|_2 \\
				& \quad + C\|\boldsymbol{u}(t^{n+1})\|_1 \cdot \left\|\mathcal{B}\left(\phi(t^{n+1})\right) - \phi(t^{n+1})\right\|_2
			\end{aligned}
		\end{equation*}
	    and 
	    \begin{equation*}
	    	\begin{aligned}
	    		\| \nabla R_2 \| &\leq \|\nabla \left(\mathcal{B}(\mu(t^{n+1}))-\mu(t^{n+1})\right)\| + \|\nabla \Delta \left(\mathcal{B}(\phi(t^{n+1}))-\phi(t^{n+1})\right)\| \\
	    		& \quad + \|\nabla \left(f(\phi(t^{n+1}))-2f(\phi(t^n))+f(\phi(t^{n-1}))\right)\|  \\
	    		& \leq  \|\nabla \left(\mathcal{B}(\mu(t^{n+1}))-\mu(t^{n+1})\right)\| + \|\nabla \Delta \left(\mathcal{B}(\phi(t^{n+1}))-\phi(t^{n+1})\right)\| \\
	    		& \quad + \|f^{\prime}(\xi_1)\nabla \left(\phi(t^{n+1})-2\phi(t^n)+\phi(t^{n-1})\right)\|  \\
	    		& \leq C \|\nabla \left(\mathcal{B}(\mu(t^{n+1}))-\mu(t^{n+1})\right)\| + C \|\nabla \Delta \left(\mathcal{B}(\phi(t^{n+1}))-\phi(t^{n+1})\right)\| \\
	    		& \quad + CL\left(\Delta t\right)^2 \|\phi_{tt}\|_{L^{\infty}(0,T;H^1)}.
	    	\end{aligned}
	    \end{equation*}
        Finally, 
	    \begin{equation*}
	    	\begin{aligned}
	    		\|R_3\| &\leq \left\|\frac{1}{\Delta t}\mathcal{A}(\boldsymbol{u}(t^{n+1}))-\boldsymbol{u}_t(t^{n+1})\right\| + \left\|\Delta\left(\mathcal{B}(\boldsymbol{u}(t^{n+1}))-\boldsymbol{u}(t^{n+1})\right)\right\|  \\
	    		& \quad + \left\| \mathcal{B}\left(\boldsymbol{u}(t^{n+1})\right) \cdot \nabla\left(\mathcal{B}\left(\boldsymbol{u}(t^{n+1})\right) - \boldsymbol{u}(t^{n+1})\right)\right\|  \\
	    		& \quad + \left\|\left(\mathcal{B}\left(\boldsymbol{u}(t^{n+1})\right) - \boldsymbol{u}(t^{n+1})\right) \cdot \nabla\boldsymbol{u}(t^{n+1})\right\|  \\
	    		& \quad + \left\| \mathcal{B}\left(\mu(t^{n+1})\right) \cdot \nabla \left(\mathcal{B}\left(\phi(t^{n+1})\right) - \phi(t^{n+1})\right) \right\|  \\
	    		& \quad + \left\|\left(\mathcal{B}\left(\mu(t^{n+1})\right) - \mu(t^{n+1})\right) \cdot \nabla\phi(t^{n+1})\right\|  \\
	    		& \quad +  \|\nabla\mathcal{B}(p(t^{n+1}))-p(t^{n+1}))\|  \\
	    		& \leq C\left\|\frac{1}{\Delta t}\mathcal{A}(\boldsymbol{u}(t^{n+1}))-\boldsymbol{u}_t(t^{n+1})\right\| + C\left\|\Delta\left(\mathcal{B}(\boldsymbol{u}(t^{n+1}))-\boldsymbol{u}(t^{n+1})\right)\right\|  \\
	    		& \quad + C\|\mathcal{B}\left(\boldsymbol{u}(t^{n+1})\right)\|_1 \cdot \left\|\mathcal{B}\left(\boldsymbol{u}(t^{n+1})\right) - \boldsymbol{u}(t^{n+1})\right\|_2  \\
	    		& \quad + C\|\boldsymbol{u}(t^{n+1})\|_2 \cdot \left\|\mathcal{B}\left(\boldsymbol{u}(t^{n+1})\right) - \boldsymbol{u}(t^{n+1})\right\|_1  \\
	    		& \quad + C\|\mathcal{B}\left(\mu(t^{n+1})\right)\|_1 \cdot \left\|\mathcal{B}\left(\phi(t^{n+1})\right) - \phi(t^{n+1}) \right\|_2  \\
	    		& \quad + C\|\phi(t^{n+1})\|_2 \cdot \left\|\mathcal{B}\left(\mu(t^{n+1})\right) - \mu(t^{n+1})\right\|_1  \\
	    		& \quad + C \|\nabla\mathcal{B}(p(t^{n+1}))-p(t^{n+1}))\|.
	    	\end{aligned}
	    \end{equation*}
	\end{proof}
    \section{Appendix B: Proof of Lemma \ref{Lemma_A_e_phi_dt}}\label{Appendix-Lemma-4.3}
    \begin{proof}
    	Setting $\psi=\mathcal{A}(e_{\phi}^{n+1})/\Delta t$ in \eqref{eq_error_phi} and using the definition of $\mathcal{T}$ to get
    	$$
    	\begin{aligned}
    		\left\|\frac{\mathcal{A}(e^{n+1}_{\phi})}{\Delta t}\right\|^2_{-1}  
    		= &- \left([\mathcal{B}\left(\boldsymbol{u}(t^{n+1})\right) \cdot \nabla \mathcal{B}\left(\phi(t^{n+1})\right) - \mathcal{B}(\boldsymbol{u}^{n+1}) \cdot \nabla \bar{\phi}^{n+1}], \mathcal{T}\left(\frac{\mathcal{A}(e^{n+1}_{\phi})}{\Delta t}\right)\right) \\
    		&- \left(\nabla \mathcal{B}(e^{n+1}_{\mu}), \nabla\mathcal{T}\left(\frac{\mathcal{A}(e^{n+1}_{\phi})}{\Delta t}\right)\right) + \left(R_1,\mathcal{T}\left(\frac{\mathcal{A}(e^{n+1}_{\phi})}{\Delta t}\right)\right).
    	\end{aligned}
    	$$
    	For the first term on the RHS, 
    	\begin{equation}
    		\begin{aligned}
    			& \left|\left([\mathcal{B}\left(\boldsymbol{u}(t^{n+1})\right) \cdot \nabla \mathcal{B}\left(\phi(t^{n+1})\right) - \mathcal{B}(\boldsymbol{u}^{n+1}) \cdot \nabla \bar{\phi}^{n+1}], \mathcal{T}\left(\frac{\mathcal{A}(e^{n+1}_{\phi})}{\Delta t}\right)\right)\right|  \\
    			= &~ \bigg|\left(\mathcal{B}(e_{\boldsymbol{u}}^{n+1})\nabla\mathcal{B}(\phi(t^{n+1}))+\mathcal{B}(\boldsymbol{u}^{n+1})\nabla\left(\mathcal{B}(\phi(t^{n+1}))-2\phi(t^{n})+\phi(t^{n-1})\right), \mathcal{B}(e_{\mu}^{n+1})\right)\\
    			&~+\left(\mathcal{B}(\boldsymbol{u}^{n+1})\nabla\left(2e_{\phi}^n-e_{\phi}^{n-1}\right),\mathcal{T}\left(\frac{\mathcal{A}(e^{n+1}_{\phi})}{\Delta t}\right)\right)\bigg|\\
    			\leq & \left(C\|\mathcal{B}(\phi(t^{n+1}))\|_2 \|\mathcal{B}(e_{\boldsymbol{u}}^{n+1})\| + C\|\nabla\mathcal{B}(\boldsymbol{u}^{n+1})\| \|\nabla\left(2e_{\phi}^n-e_{\phi}^{n-1}\right)\| \right. \\
    			& \quad \left.+ C\|\nabla\mathcal{B}(\boldsymbol{u}^{n+1})\| \|\nabla\left(\mathcal{B}(\phi(t^{n+1}))-2\phi(t^{n})+\phi(t^{n-1})\right)\|\right)\cdot \left\|\nabla \mathcal{T}\left(\frac{\mathcal{A}(e^{n+1}_{\phi})}{\Delta t}\right)\right\|  \\
    			\leq & \left(C\|\mathcal{B}(\phi(t^{n+1}))\|_2 \|\mathcal{B}(e_{\boldsymbol{u}}^{n+1})\| + C\|\nabla\mathcal{B}(\boldsymbol{u}^{n+1})\| \|\nabla\left(2e_{\phi}^n-e_{\phi}^{n-1}\right)\| \right. \\
    			& \quad \left.+ C\left(\Delta t\right)^2 \|\nabla \mathcal{B}(\boldsymbol{u}^{n+1})\| \cdot\|\phi_{tt}\|_{L^{\infty}(0,T;H^1)}\right)\cdot \left\|\frac{\mathcal{A}(e^{n+1}_{\phi})}{\Delta t}\right\|_{-1}
    		\end{aligned}
    	\end{equation}
    	For the second term on the RHS, 
    	\begin{equation}
    		\begin{aligned}
    			\left|\left(\nabla \mathcal{B}(e^{n+1}_{\mu}), \nabla\mathcal{T}\left(\frac{\mathcal{A}(e^{n+1}_{\phi})}{\Delta t}\right)\right)\right| 
    			\leq  \Bigg\|\nabla \mathcal{B}(e^{n+1}_{\mu})\Bigg\| \cdot \left\| \nabla \mathcal{T}\left(\frac{\mathcal{A}(e^{n+1}_{\phi})}{\Delta t}\right)\right\| 
    			= \Bigg\|\nabla \mathcal{B}(e^{n+1}_{\mu})\Bigg\| \cdot \left\| \frac{\mathcal{A}(e^{n+1}_{\phi})}{\Delta t}\right\|_{-1}
    		\end{aligned}
    	\end{equation}
    	For the third term on the RHS, 
    	\begin{equation}
    		\begin{aligned}
    			\left|\left(R_1,\mathcal{T}\left(\frac{\mathcal{A}(e^{n+1}_{\phi})}{\Delta t}\right)\right)\right|
    			\leq \Bigg\|R_1\Bigg\| \cdot \left\| \nabla \mathcal{T}\left(\frac{\mathcal{A}(e^{n+1}_{\phi})}{\Delta t}\right)\right\| 
    			\leq C \Bigg\|R_1\Bigg\| \cdot \left\| \frac{\mathcal{A}(e^{n+1}_{\phi})}{\Delta t}\right\|_{-1}
    		\end{aligned}
    	\end{equation}
    	Combining the above estimates to complete this proof.
    \end{proof}

