 |Q(s)|A_1^4 A_2^2  A_3 R_{1,1,s} R_{2,1,s}&\sim\sum_{B_{s}\in \mathfrak{B}_s} \int_{P\cap B_s} \Big(\sum_{T_{1}\in \mathcal{T}_1^*} \chi_{T_{1}}\Big)\Big(\sum_{T_{2}\in \mathcal{T}_2^*} \chi_{T_{2}}\Big)\\\nonumber
&\sim 2^{-j}A_2^2 A_3\beta_{1,1,s} \beta_{2,1,s}  \int_{P}  \Big(\sum_{T_{1}\in \mathcal{T}_1^*} \chi_{T_{1}}\Big)\Big(\sum_{T_{2}\in \mathcal{T}_2^*} \chi_{T_{2}}\Big)\\
&\lesssim  |Q(s)|A_2^2 A_3 \beta_{1,1,s} \beta_{2,1,s} R_{1,2,s} R_{2,2,s}.
\end{align}
Combining \eqref{eq1}, \eqref{eq2} and \eqref{eq3},
\begin{align*}
A_1^4 A_2^{\frac{4}{3}} \Big(\prod_{n=1}^3 R_{n,1,s}^{\frac{2}{3}} \Big)\lesssim  \overline{\pmb{\beta}}_{1,s}^{\frac{2}{3}}\Big(\prod_{n=1}^3R_{n,2,s}^{\frac{2}{3}}\Big) .
\end{align*}
The result follows by raising both sides to the power $\frac{3}{4}$.
\begin{flushright}
$\blacksquare$
\end{flushright}



Using the previous lemma, we conclude
\begin{align*}
&A_1^3 A_2  \Big(\prod_{n=1}^3 R_{n,1,s}^{\frac{1}{2}}\Big)A_1 A_2 \Big(\prod_{n=1}^3 R_{n,2,s}^{-\frac{1}{2}}\Big)  |Q(s)| \prod_{n=1}^3|\mathcal{T}_n^*|^{\frac{1}{2}}\\& \lesssim  2^{\frac{1}{2}r}  \overline{\pmb{\beta}}_{1,s}^{\frac{1}{2}}A_1 A_2  |Q(s)| \prod_{n=1}^3|\mathcal{T}_n^*|^{\frac{1}{2}},
\end{align*}
as desired.




\begin{flushright}
$\blacksquare$
\end{flushright}


\begin{Remark}\label{noKak}
We observe that if $s'=s$, then \eqref{nok}, together with Lemma \ref{cord}, implies Lemma \ref{L2}. In particular, the proof of Lemma \ref{L2} for the case $s'=s$ does not rely on the trilinear Kakeya estimate \eqref{GK1}.
\end{Remark}

\subsection{An alternative proof of the trilinear Kakeya estimate with sharp dependence on transversality}
In this section, we reprove Guth's trilinear Kakeya estimate with sharp dependence on transversality. 
\begin{Theorem}\label{MKe}
Fix $r,j,t,w,m$ and let $\mathcal{T}=\{\mathcal{T}_n\}_n$ be a collection of tubes of $(r,j,t,w,m) $-type. Then given any $\epsilon>0$ there exist a constants $C_\epsilon<\infty$ such that
\begin{align*}
\int_{Q_R} \prod_{n=1}^3 \Big( \sum_{T_{n}\in \mathcal{T}_n } \chi_{T_{n}}\Big)^{\frac{1}{2}}\leq C_\epsilon R^{\epsilon} 2^{\frac{1}{2}(j+t+r)}  \prod_{n=1}^3 |\mathcal{T}_n|^{\frac{1}{2}},
\end{align*}
for all $R>0$.
\end{Theorem}

Our proof is slightly weaker than Guth's \cite{G}, as it requires the factor $R^{\epsilon}$, but it is simpler and follows a philosophy similar to that of \cite{gu2} and the arguments from the previous section. We define:

\begin{Definition}
Fix $s,r, j,t,w,m$ and let $\mathcal{T}=\{\mathcal{T}_n\}_n$ be a collection of tubes of $(r,j,t,w,m) $-type. We denote by $\mathcal{M}(s)$ the smallest constant $C$ such that 
\begin{align*}
\int_{P_s} \prod_{n=1}^3 \Big( \sum_{T_{n}\in \mathcal{T}_n } \chi_{T_{n}}\Big)^{\frac{1}{2}}\leq C 2^{\frac{1}{2}(j+t+r)} \prod_{n=1}^3 |\mathcal{T}_n(P_{s})|^{\frac{1}{2}},
\end{align*}
for every $P_{s}\in  \mathcal{A}(Q_R, \mathcal{P}(j,t)[s])$. % \mathfrak{P}(j,t)[M_s,N_s](b)
\end{Definition}

As in \cite{gu2}, we can use the Loomis-Whitney inequality \cite{lw} to obtain, after an affine transformation, the following:
\begin{Lemma}\label{WLK} (Loomis-Whitney)
For any three directions $v_1, v_2, v_3$ such that $|v_1\wedge v_2\wedge v_3|=\theta>0$, and collections of tubes $\{\mathcal{T}_n\}_{n=1}^3$ such that each tube $T_n\in\mathcal{T}_n$ satisfies $d(T_n)=v_n$, we have
\begin{align}\label{LW}
\int_{\R^d}\prod_{n=1}^3 \Big( \sum_{T_{n}\in \mathcal{T}_n } \chi_{T_{n}}\Big)^{\frac{1}{2}}\lesssim \theta^{-\frac{1}{2}}  \prod_{n=1}^3 |\mathcal{T}_n|^{\frac{1}{2}}.
\end{align}
 \end{Lemma}

Let $\{\mathcal{T}_n\}_{n=1}^3$ be $3$ families of tubes of $(r,j,t,w,m) $-type. Let  $S_1, S_2, S_3$ be the subsets of the paraboloid $\{(\xi,\frac{1}{2}|\xi|^2): \; |\xi|\leq 2\}$ such that for every $T_n\in \mathcal{T}_n$, we have $d(T_n)=n(\xi_n)$ for some $\xi_n\in S_n$. We can decompose 
$$\mathcal{T}_n=\bigcup_{i=1}^N \mathcal{T}_{n,i} $$
where $N\sim 2^{2\lambda}$, and if $T_n\in \mathcal{T}_{n,i} $, then $d(T_n)=n(\xi_n)$, for some $\xi_n\in S_{n,i}$, with
\begin{align*}%\label{indx}\nonumber
&S_{1,i}\subset \{(\xi,\tfrac{1}{2}|\xi|^2):\;\xi\in\tau^{j+\lambda}_{k_i} \cap \mathfrak{t}^{j+t+\lambda}_{w,m_i}\},\\%\nonumber
&S_{2,i}\subset \{(\xi,\tfrac{1}{2}|\xi|^2):\;\xi\in\tau^{j+\lambda}_{k_i'} \cap \mathfrak{t}^{j+t+\lambda}_{w,m_i}\},\\
&S_{3,i}\subset\{(\xi,\tfrac{1}{2}|\xi|^2):\;\xi\in\tau^{r+\lambda}_{k_i''} \cap \mathfrak{t}^{r+t+\lambda}_{w',m_i},\},
\end{align*}
for some indices $k_i,k_i',k_i'',m_i$. 

Taking a parameter $\lambda$ such that $\lambda\sim \frac{1}{\epsilon} \log_2 C$, for some constant $C$ independent on $R$ and $\theta$, it suffices to prove Theorem \ref{MKe} for each collection of tubes $\{\mathcal{T}_{n,i}\}_n$.


\begin{Remark}\label{re} Let $P_{s+\lambda}\in  \mathcal{A}(Q_R, \mathcal{P}(j,t)[s+\lambda])$. We can see that for every $P_s\in \mathcal{A}(Q_R, \mathcal{P}(j,t)[s])\cap P_{s+\lambda}$, $T_n[s], T_{n}[s]'\in \mathcal{T}_{n,i}[s](P_s)$, we have \begin{align*} \mathcal{T}_{n,i}[s](T_{n}[s],P_s)\cap P_{s+\lambda}\subset \bigcup_{a\in A}\big(\mathcal{T}_{n,i}[s](T_{n}[s]',P_s)+a\big)\cap P_{s+\lambda},\end{align*}
for some set of points $A$ such that $|A|\lesssim 1$.

%and every $T_n[s], T_{n}[s]'\in\mathcal{T}_{n,i}[s]()$, we have $T_n[s-1]\cap P_{s+\lambda}\subset(T_n[s+1]'+a)\cap P_{s+\lambda}$ for some $a\in \R^3$. 
\end{Remark}


Theorem \ref{MKe} follows from the following lemmas:

\begin{Lemma}\label{LK1}For every $s\geq 0$, $$M(s+\lambda)\lesssim M(s).$$\end{Lemma}\label{L2C}\begin{Lemma}\label{LK2}$$M(0)\lesssim 1.$$\end{Lemma}


\textbf{Proof of Theorem \ref{MKe}.}

It is enough to prove that $\mathcal{M}(\log_2 R)\leq C_\epsilon R^\epsilon$. By Lemma \ref{LK1} applied $\frac{\log_2 R}{\lambda}$ times:
\begin{align*}
\mathcal{M}(\log_2 R)&\leq C \mathcal{M}(\log_2 R-\lambda)\\
&\leq C^2 \mathcal{M}(\log_2 R-2\lambda)\\
&\leq \cdots \leq C^{\frac{\log_2 R}{\lambda}} \mathcal{M}(0)\\
&= R^{\frac{\log_2 C}{\lambda}} \mathcal{M}(0)\\
\end{align*}
Using Lemma \ref{LK2} and that $\lambda\sim \frac{1}{\epsilon} \log_2 C$, we conclude the result.
\begin{flushright}
$\blacksquare$
\end{flushright}

\textbf{Proof of Lemma \ref{LK1}.}
Let $P_{s+\lambda}\in  \mathcal{A}(Q_R, \mathcal{P}(j,t)[s+\lambda])$, we have by definition,
\begin{align*}
\int_{P_{s+\lambda}} \prod_{n=1}^3 \Big( \sum_{T_{n}\in \mathcal{T}_n } \chi_{T_{n}}\Big)^{\frac{1}{2}}&\leq \sum_{P_s\in  \mathcal{A}(Q_R, \mathcal{P}(j,t)[s])}\int_{P_{s+\lambda}\cap P_{s}} \prod_{n=1}^3 \Big( \sum_{T_{n}\in \mathcal{T}_n } \chi_{T_{n}}\Big)^{\frac{1}{2}}\\
&\lesssim \sum_{P_s\in  \mathcal{A}(Q_R, \mathcal{P}(j,t)[s])} M(s) 2^{\frac{1}{2}(t+j+r)}  \prod_{n=1}^3 |\mathcal{T}_n(P_{s}\cap P_{s+\lambda})|^{\frac{1}{2}}.
\end{align*}
%We set $$\mathcal{T}_n^*(P_{s+\lambda}):=\big\{T_n[s]\in \mathcal{T}_n[s](T_n[s]',P_s):\; T_n[s]'\in \mathcal{T}_n(P_s),\; P_s\in \mathcal{A}(Q_R, \mathcal{P}(j,t)[s])\cap P_{s+\lambda}\big\}.$$
As in the previous section, we observe that  \begin{align}\label{Tubr}\prod_{n=1}^3 |\mathcal{T}_n[s](\mathcal{A}(Q_R, \mathcal{P}(j,t)[s]),P_{s+\lambda})|^{\frac{1}{2}}\sim 2^{\frac{1}{2}j-\frac{1}{2}r+\frac{3}{2}t}\prod_{n=1}^3 |\mathcal{T}_n(P_{s+\lambda})|^{\frac{1}{2}}.\end{align}
Thanks to the equation
\begin{align*}
|\mathcal{T}_n(P_{s}\cap P_{s+\lambda})|^{\frac{1}{2}}\sim \fint_{P_s}\prod_{n=1}^3 \Big(\sum_{T_n\in \mathcal{T}_n[s](\mathcal{A}(Q_R, \mathcal{P}(j,t)[s]),P_{s+\lambda})} \chi_{\mathcal{T}_n}\Big)^{\frac{1}{2}},
\end{align*}
we can rewrite the previous inequality as
\begin{align*}
\int_{P_{s+\lambda}} &\prod_{n=1}^3 \Big( \sum_{T_{n}\in \mathcal{T}_n } \chi_{T_{n}}\Big)^{\frac{1}{2}}\\
&\lesssim \sum_{P_s\in\mathcal{A}(Q_R, \mathcal{P}(j,t)[s])}M(s) 2^{\frac{1}{2}(t+j+r)}  \fint_{P_s}\prod_{n=1}^3 \Big(\sum_{T_n\in\mathcal{T}_n[s](\mathcal{A}(Q_R, \mathcal{P}(j,t)[s]),P_{s+\lambda})} \chi_{\mathcal{T}_n}\Big)^{\frac{1}{2}}\\
&\sim M(s)  2^{\frac{1}{2}(t+j+r)}|P_s|^{-1}  \int_{P_{s+\lambda}}\prod_{n=1}^3 \Big(\sum_{T_n\in\mathcal{T}_n[s](\mathcal{A}(Q_R, \mathcal{P}(j,t)[s]),P_{s+\lambda})} \chi_{\mathcal{T}_n}\Big)^{\frac{1}{2}}.
\end{align*}
By Remark \ref{re}, we can apply Lemma \ref{WLK}, which together with \eqref{Tubr} yields
\begin{align*}
\int_{P_{s+\lambda}} &\prod_{n=1}^3 \Big( \sum_{T_{n}\in \mathcal{T}_n } \chi_{T_{n}}\Big)^{\frac{1}{2}}\\
&\lesssim  M(s) 2^{\frac{1}{2}(t+j+r)}|P_s|^{-1}  2^{3s}2^{\frac{1}{2}(t+j+r)} \prod_{n=1}^3 |\mathcal{T}_n[s](\mathcal{A}(Q_R, \mathcal{P}(j,t)[s]),P_{s+\lambda})|^{\frac{1}{2}}\\
&\lesssim M(s)2^{\frac{1}{2}(t+j+r)}|P_s|^{-1} 2^{3s} 2^{\frac{1}{2}(t+j+r)}2^{\frac{1}{2}j-\frac{1}{2}r+\frac{3}{2}t}\prod_{n=1}^3 |\mathcal{T}_n(P_{s+\lambda})|^{\frac{1}{2}}.
\end{align*}
As we have $|P_s|\sim 2^{3s} 2^{2t+j}$, we conclude that
\begin{align*}
\int_{P_{s+\lambda}} \prod_{n=1}^3 \Big( \sum_{T_{n}\in \mathcal{T}_n } \chi_{T_{n}}\Big)^{\frac{1}{2}}\lesssim M(s) 2^{\frac{1}{2}(t+j+r)} \prod_{n=1}^3 |\mathcal{T}_n(P_{s+\lambda})|^{\frac{1}{2}},
\end{align*}
as desired.

\begin{flushright}
$\blacksquare$
\end{flushright}


\textbf{Proof of Lemma \ref{LK2}.}
It follows directly from Lemma \ref{L1} and Remark \ref{noKak}.
\begin{flushright}
$\blacksquare$
\end{flushright}

