\begin{proposition}
\label{2to1}
The boundary operator $\partial_2: C_2 \to C_1$ of the mod 2 cellular complex of the CW-complex $\overline{TD}_2(S^1)$ is defined by following formulas:
\begin{eqnarray*}
\partial (Y_1)  & = & \nabla + \bar Y_1 + \bar Y_2 \\
\partial (Y_2) & = & \nabla + \bar Y_2 + \bar Y_1 \\
\partial (U_1) & = & \nabla + \bar U_1 + \bar U_2 \\
\partial (U_2) & = & \nabla + \bar U_2 + \bar U_1 \\
\partial (Z) & = & \nabla \\
\partial (\Theta) & = & 0 \\
\partial(\bar L_{123}) & = & \bar U_1 + \bar Z + \bar Y_2 \\
\partial(\bar L_{231}) & = & \bar Y_1 + \bar U_2 + \bar Z \\
\partial(\bar L_{312}) & = & \bar Z + \bar Y_2 + \bar U_2 \\
\partial(\bar L_{132}) & = & \bar Y_1 + \bar Z + \bar U_2 \\
\partial(\bar L_{213}) & = & \bar U_1 + \bar Y_2 + \bar Z \\
\partial(\bar L_{321}) & = & \bar Z + \bar U_2 + \bar Y_2 \\
\partial(\bar M_1) & = & \bar U_1 + \bar Y_1 + \bar U_2 \\
\partial(\bar M_2) & = & \bar U_1 + \bar U_2 + \bar Y_1 \\
\partial(\bar M_3) & = & \bar Y_2  \\
\partial (\bar N_1) & = & \bar Y_1 + \bar U_2 + \bar Y_2 \\
\partial (\bar N_2) & = & \bar Y_1 + \bar Y_2  + \bar U_2 \\
\partial (\bar N_3) & = & \bar U_1  \\
\partial(\bar P_1) & = & 0 \\
\partial (\bar P_2) & = & 0 \\
\partial (\bar S_1) & = & 0 \\
\partial(\bar S_2) & = & 0 \\
\partial(\bar X^+) & = & \bar Y_1 + \bar Y_2  \\
\partial (\bar X^-) & = & \bar Y_1 + \bar Y_2 \\
\partial(\bar V_1^+) & = & \bar Y_1 + \bar U_1 \\
\partial(\bar V_2^+) & = & \bar Y_2 + \bar U_2 \\
\partial(\bar V_1^-) & = & \bar Y_1 + \bar U_1 \\
\partial(\bar V_2^-) & = & \bar Y_2 + \bar U_2 \\
\partial(\bar \Omega) & = & 0
\end{eqnarray*}
and also by the matrix on page \pageref{page2to1}.
\end{proposition}

\begin{corollary}
The group $H_1(\overline{TD}_2, \Z_2)$ is isomorphic to $\Z_2$ and is generated by the class of cell $\bar \Theta$.
\end{corollary}

\begin{corollary}
The kernel of the operator $\partial_2 : C_2 \to C_1$ is generated by the following cycles:
\begin{eqnarray}
& &
Y_1+Y_2 \label{ker01} \\ & & 
Y_1+\bar X^+ +Z \label{ker02} \\ & & 
U_1+U_2 \label{ker03} \\ & & 
U_1+Z + \bar M_1 +\bar N_1 + \bar V_2^+ \label{ker04} \\ & & 
\Theta \label{ker05} \\ & & 
\bar L_{123} + \bar L_{213} \label{ker06} \\ & & 
\bar L_{231} + \bar L_{132} \label{ker07} \\ & & 
\bar L_{321}+\bar L_{312} \label{ker08} \\ & & 
\bar L_{231}+\bar L_{312}+\bar X^+ \label{ker09} \\ & & 
\bar L_{123}+\bar L_{312}+\bar M_1 + \bar N_1 + \bar V_2^+ \label{ker10} \\ & & 
\bar M_1+\bar M_2 \label{ker11} \\ & & 
\bar N_1+\bar N_2 \label{ker12} \\ & & 
\bar M_1+\bar N_1 + \bar M_3 + \bar N_3 \label{ker13} \\ & & 
\bar M_3 + \bar N_1 + \bar V_2^+ + \bar X^+ \label{ker14} \\ & & 
\bar M_3+\bar N_3 + \bar X^+ + \bar V_1^+ \label{ker15} \\ & & 
\bar P_1 \label{ker16} \\ & & 
\bar P_2 \label{ker17} \\ & & 
