The next result is not assumed to be new, but we prove it for sake of completeness. 
\begin{proposition} \label{prop:shiftproperty}
The map 
\[
\begin{tabular}{l c c c }
$\omega_{\alpha}:$ & $\fqn[x;\sigma]$ & $\longrightarrow$ &  $\fqn[x;\sigma]$  \\
& $f(x)$ & $\longmapsto$ & $f_{\alpha}(x)$,
\end{tabular}
\]
is a ring isomorphism. In particular, 
\begin{equation} \label{eq:shiftomomorphism}
(f(x)g(x))_{\alpha}=f_{\alpha}(x)g_{\alpha}(x), \end{equation}
for any $f(x),g(x) \in \fqn[x;\sigma]$ and if $h(x)=\gcrd(f(x),g(x))$ then
\begin{equation}
    h_{\alpha}(x)=\gcrd(f_{\alpha}(x),g_{\alpha}(x))
\end{equation}
\end{proposition}

\begin{proof}
    Clearly $\omega_{\alpha}(f(x)+g(x))=\omega_{\alpha}(f(x))+\omega_{\alpha}(g(x))$. Now, if $f(x)=\sum_{i}f_ix^i$ and $g(x)=\sum_{j}g_jx^j$ then 
    \[
    (f(x)g(x))_{\alpha}=\sum_j\sum_i f_i \sigma^i(g_j)N^{i+j}(\alpha)x^{i+j},
    \]
    while
    \[
    f_{\alpha}(x)g_{\alpha}(x)=\sum_j\sum_i f_i \sigma^i(g_j)N^{i}(\alpha)\sigma^i(N^{j}(\alpha))x^{i+j}.
    \]
    Since $N^{i+j}(\alpha)x^{i+j}=N^{i}(\alpha)\sigma^i(N^{j}(\alpha))$, for each $i$ and $j$, we have that 
    \[
    (f(x)g(x))_{\alpha}=f_{\alpha}(x)g_{\alpha}(x).
    \]
    It is easy to show that $\omega_{\alpha}$ is clearly a bijection that proves the first part. Finally, since $h(x) \mid_r f(x),g(x)$, then by \eqref{eq:shiftomomorphism}, $h_{\alpha}(x) \mid_r f_{\alpha}(x),g_{\alpha}(x)$. Moreover, if $h'(x) \mid_r f_{\alpha}(x),g_{\alpha}(x)$, then again by \eqref{eq:shiftomomorphism}, $h'_{\alpha^{-1}}(x) \mid_r f(x),g(x)$ and so $ h'_{\alpha^{-1}}(x)  \mid_r h(x) $ from which $ h'(x) \mid_r h_{\alpha}(x)$, that proves our assertion.
\end{proof}


