\section{Isotonic Projections} \phantomsection\label{appendix:b}

Here, we prove some properties of the isotonic projection and show the max-min formulation of  isotonic projections, which is essential to prove \Cref{prop:iso_ordering}. The max-min formulation and its proof for the isotonic regression case can be found in \citet{barlow2}. 

\begin{proposition}[Properties] \label{prop:iso_properties}
Let $l\in\L^2((0,1)), \ k\geq 0$ and $c\in\R$. Then, all of the following hold:
\begin{enumerate} [label = $\roman*)$]
\item $\iso{(kl)}=k\iso{(l)}$,
\item $\iso{(l+c)}=\iso{l}+c$,
\item $\iso{l}(s)=l(s)+\sum_{i\in \I}(\theta_i-l(s))\Id_{s\in I_i}$,
where $\I$ is a countable index set, $I_i$ are mutually disjoint sub-intervals of $(0,1)$ with endpoints $a_i,b_i\in\R$ and $\theta_i\in\R$. Moreover, for any $i\in\I$,
\begin{equation} \label{eq:theta} 
\theta_i=\frac{1}{\abs{I_i}}\int_{a_i}^{b_i}l(s)ds,
\end{equation} 
where $\abs{I_i}:= b_i-a_i$ is the length of the interval $I_i$.
\end{enumerate}
\end{proposition}

{\parindent0pt
\textbf{Proof:} 
Case $i)$ follows by Theorem 2.6 in \citet{brunk} since $\K$, the set of left-continuous and non-decreasing functions, is a closed convex cone.

Case $ii)$ follows by noting that
\begin{align*}
\iso{(l+c)} &= \argmin_{j\in\K}\int_{0}^{1}\big(j(s)-(l(s)+c)\big)^2ds 
=
\argmin_{j\in\K}\int_{0}^{1}\big((j(s)-c)-l(s)\big)^2ds\,.
\end{align*}
By definition of $\iso{l}$, the argmin of the rhs $j^*$ satisfies $j^*-c=\iso{l}$, thus $\iso{(l+c)}=\iso{l}+c$. 

Case $iii)$, for a function $f$ we denote by $f^{*}$ its concave envelope. Then, as $\iso{l}(s)=\frac{d}{ds}\big(\int_{0}^{s}l(u)du\big)^{*}$, it holds that $\iso{l}(s)=l(s)+\sum_{i\in \I}(\theta_i-l(s))\Id_{s\in I_i}$ by Lemma 5.1 in \citet{brighi}. To prove \Cref{eq:theta}, recall that the intervals $I_i$ are disjoint, thus we have $\theta_i=\argmin_{\theta\in\R}\int_{I_i}(\theta-l(s))^2ds$. Calculating the argmin yields \eqref{eq:theta}.
$\hfill\blacksquare$
}

Before stating the max-min formulation for isotonic projections, we require additional definitions. 

\begin{definition} [Average Value of a Function] \label{definition:average} 
Let $S$ be a non-empty sub-interval of $(0,1)$ and $l\colon (0,1) \to \R$ be an integrable function. Then the average value of $l$ on $S$, is given by $\Av_l(S):= \frac{1}{\abs{S}}\int_Sl(s)ds$.
\end{definition}

For a set with only one element, i.e. $S=\{x\}$, it holds that $\Av_l(S)=l(x)$. Additionally, we drop the subscript $l$ of $\Av_l(\cdot)$, whenever it is clear from the context. 

\begin{definition} [Upper and Lower Sets - \citet{barlow2}, Def. 1.4.1] \label{definition:ul_sets} 
We define the following two notions of sets.
\begin{enumerate}[label = $\roman*)$]
    \item A set $L\subseteq (0,1)$ is a lower set wrt the quasi-order $\leq$, if for any $y\in L$ and any $x\in (0,1)$, the inequality $x\leq y$ implies that $x\in L$. 

    \item A set $U\subseteq (0,1)$ is an upper set wrt the quasi-order $\leq$, if for any $y\in U$ and any $x\in (0,1)$, the inequality $x\geq y$ implies that $x\in U$. 
\end{enumerate}
We denote the class of all lower sets by $S_{\L}$ and the class of all upper sets by $S_{\U}$.
\end{definition}

From the definition of a lower set, $S_{\L}$ is the set of all sub-intervals of $(0,1)$ with left endpoint $0$. Similarly, $S_{\U}$ is the set of all sub-intervals on $(0,1)$ with right endpoint $1$.

Moreover, for any $l\in \K$ and $a\in\R$, the set $\{l\geq a\}:= \{s\in (0,1):l(s)\geq a\}$ is an upper set and $\{l\leq a\}:=\{s\in (0,1):l(s)\leq a\}$ is a lower set. This also holds when the inequalities in the sets are replaced with strict inequalities. 

We use the following lemma to prove the max-min formulation for isotonic projections. The citation for each part of the lemma references the corresponding result in \citet{barlow2} for isotonic regression. Note that cases $ii)$ and $iii)$ are proven in Proposition A.3. of \citet{bernard}, but we include a short proof for completeness. 

\begin{lemma} \label{lemma:iso} 
Let $l\in\L^2((0,1))$. Then, all of the following hold:
\begin{enumerate}[label = $\roman*)$]
    \item (Theorem 1.3.6) For any function $\psi:\R\to\R$, $\int_{0}^{1}(l(s)-\iso{l}(s))\psi(\iso{l}(s))\, ds=0$. 
    \item (Equation 1.3.3) For any $f\in \K$, we have $\int_{0}^{1}(l(s)-\iso{l}(s))(\iso{l}(s)-f(s))\, ds\geq 0$.
    \item (Equation 1.3.8) For any $f\in \K$, we have $\int_{0}^{1}(l(s)-\iso{l}(s))f(s)\, ds\leq 0$.
    \item (Theorem 1.4.3) Let $a\in\R$, $L\in S_{\L}$ and $U\in S_{\U}$. Then, 
    \begin{enumerate} [label=$\alph*)$]
        \item $\Av(L\cap \{\iso{l}\geq a\})\geq a$,
        \item $\Av(L\cap \{\iso{l}> a\})> a$,
        \item $\Av(U\cap \{\iso{l}\leq a\})\leq a$,
        \item $\Av(U\cap \{\iso{l}< a\})< a$,
    \end{enumerate}
    whenever the sets are non-empty. 
\end{enumerate} 
\end{lemma}
{\parindent0pt
\textbf{Proof:} \citet{barlow2} shows the above results for the isotonic regression, here we provide a proof for the isotonic projection. 

For case $i)$, let $l\in\L^2((0,1))$. Then, it holds that
\begin{align*}
\int_{0}^{1}\big(l(s)-\iso{l}(s)\big)\psi(\iso{l}(s))\,ds 
&= \sum_{i\in\I}\int_{I_i}(l(s)-\theta_i)\psi(\theta_i)\,ds 
= \sum_{i\in \I}\psi(\theta_i)\left(\int_{I_i}l(s)\, ds-|I_i|\theta_i\right) 
= 0,
\end{align*}
where the first and last equalities follow from \Cref{prop:iso_properties}, $iii)$. 

\smallskip

Proof of $ii)$ let $f\in \K$ and  $\alpha\in [0,1]$, then it holds that $(1-\alpha)\iso{l}+\alpha f \in \K$. 
By definition of the isotonic projection, the function $g(\alpha)=\int_{0}^{1}\big(l(s)-[(1-\alpha)\iso{l}(s)+\alpha f(s)]\big)^2\,ds$ attains its minimum on $[0,1]$ at $\alpha=0$. Moreover, $g'(0)=2\int_{0}^{1}\big(l(s)-\iso{l}(s)\big)\big(\iso{l}(s)-f(s)\big)\,ds$. Finally, since $g$ is quadratic in $\alpha$ and attains its minimum at $\alpha=0$, it follows that $g'(0)\geq 0$ and the desired result holds. 

\smallskip

For case $iii)$ we apply the first part of this lemma to the identity function and obtain $\int_{0}^{1}\big(l(s)-\iso{l}(s)\big)\iso{l}(s)\, ds=0$. Combining this fact with the second part of this lemma yields the inequality. 

\smallskip 

For case $iv)$, we only prove $b)$ as the remaining cases follow by similar arguments.
Let $a, a_1, a_2\in \R$ with $a_2>a_1$, and $\psi:\R\to\{0,1\}$ such that $\psi(x)=\Id_{a_1<x<a_2}$. By \Cref{lemma:iso}, $i)$, we have
\begin{equation} \label{eq:iso_4.1}
\int_{0}^{1}\big(l(s)-\iso{l}(s)\big)\psi(\iso{l}(s))\,ds=\int_0^1\big(l(s)-\iso{l}(s)\big)\Id_{a_1<\iso{l}(s)<a_2}\,ds=0\, .
\end{equation}

Since for any $U\in S_{\U}$, the function $\Id_{x\in U}$ is non-decreasing, we have \Cref{lemma:iso}, $iii)$, that
\begin{equation} \label{eq:iso_4.2}
\int_{0}^{1}\big(l(s)-\iso{l}(s)\big)\Id_{s\in U}\,ds\leq 0.
\end{equation} 
Therefore, for any $L\in S_{\L}$,
\begin{align}
\int_{L\cap\{\iso{l}>a\}}(l(s)-a)\,ds &> \int_{L\cap\{\iso{l}>a\}}\big(l(s)-\iso{l}(s)\big)\,ds 
\nonumber
\\
&= \int_{\{\iso{l}>a\}}\big(l(s)-\iso{l}(s)\big)\,ds - \int_{L^\complement\cap\{\iso{l}>a\}}\big(l(s)-\iso{l}(s)\big)\,ds\,,
\label{eq:iso_4-2-ineq}
\end{align}
where $L^\complement$ is the compliment of $L$, and the equality follows since for any two sets $A$ and $B$, $A\cap B=B\setminus (A^\complement\cap B)$. 

The first integral in \eqref{eq:iso_4-2-ineq} is zero by \Cref{eq:iso_4.1}. Furthermore, since $\iso{l}$ is non-decreasing, the set $L^\complement\cap\{\iso{l}>a\}$ is an upper set. Therefore, the second integral in \eqref{eq:iso_4-2-ineq} is non-positive by \Cref{eq:iso_4.2}. Combining these two facts yields, $\int_{L\cap\{\iso{l}>a\}}(l(s)-a)\,ds>0$. Rearranging the terms in the inequality gives 
\begin{equation*}
 a\,   < \, 
 \frac{1}{\abs{L\cap\{\iso{l}>a\}}}\int_{L\cap\{\iso{l}>a\}}l(s)\,ds   
 =
 \Av(L\cap\{\iso{l}>a\})\,,
\end{equation*}
provided $L\cap\{\iso{l}>a\}$ is non-empty. 
$\hfill\blacksquare$
}

We finally prove the max-min formulation of isotonic projections. 

\begin{lemma} (Max-Min Formulation)\label{lemma:max_min} Let $l\in\L^2((0,1))$ and fix $x\in (0,1)$. Then, 
\begin{enumerate}[label = $\roman*)$]
    \item $\displaystyle\max_{\{U\in S_{\U}|x\in U\}}\min_{\{L\in S_{\L}|x\in L\}}\Av(L\cap U)=\iso{l}(x)$, and
    \item $\displaystyle\max_{\{U\in S_{\U}|x\in U\}}\min_{\{L\in S_{\L}|L\cap U\neq\emptyset\}}\Av(L\cap U)=\iso{l}(x)$.
\end{enumerate} 
\end{lemma}
{\parindent0pt
\textbf{Proof:} We only prove the second case, as the first case follows using similar arguments.

For $x\in (0,1)$, define $a:=\iso{l}(x)$ and $U_a:=\{\iso{l}\geq a\}$. For any $L \in S_{\L}$, we have that by \Cref{lemma:iso}, $iv)$ $a)$, $\Av(L\cap U_a\})\geq a$ whenever $L\cap U_a\neq \emptyset$. Therefore, 
$$\min_{\{L\in S_{\L}|L\cap U_a\neq\emptyset\}}\Av(L\cap U_a)\geq a.$$

Additionally, as $x\in U_a$ it follows that 
\begin{equation} \label{eq:iso_2.1}
\max_{\{U\in S_{\U}|x\in U\}}\min_{\{L\in S_{\L}|L\cap U\neq\emptyset\}}\Av(L\cap U)\geq a.
\end{equation}

Next, let $U\in S_{\U}$ such that $x\in U$. Then, $\{\iso{l}\leq a\}\cap U$ is non-empty and $\Av(\{\iso{l}\leq a\}\cap U)\leq a$ by \Cref{lemma:iso}, $iv)$ $c)$. Therefore, 
\begin{equation} \label{eq:iso_2.2}
\max_{\{U\in S_{\U}|x\in U\}}\min_{\{L\in S_{\L}|L\cap U\neq\emptyset\}}\Av(L\cap U)\leq a
\end{equation}

Combining Equations \eqref{eq:iso_2.1} and \eqref{eq:iso_2.2} completes the proof. 
$\hfill\blacksquare$
}
\smallskip 

{\parindent0pt
\textbf{Proof of \Cref{prop:iso_ordering}:}
Let $l_1, l_2\in\L^2((0,1))$ satisfying $l_2(s)\leq l_1(s)$, for any non-empty interval $S\subseteq (0,1)$. Then, for any non-empty interval $S\subseteq (0,1)$ it holds 
\begin{equation} \label{eq:ordering_1}
\frac{1}{\abs{S}}\int_Sl_2(s)\,ds=\Av_{l_2}(S)
\leq
\Av_{l_1}(S)=\frac{1}{\abs{S}}\int_Sl_1(s)\,ds.
\end{equation}
Thus, by \Cref{lemma:max_min}, $i)$ we have for any fixed $s\in (0,1)$, that
\begin{equation} \label{eq:ordering_2}
\iso{l}_2(s)=\max_{\{U\in S_{\U}|x\in U\}}\min_{\{L\in S_{\L}|x\in L\}}\Av_{l_2}(L\cap U)\leq \max_{\{U\in S_{\U}|x\in U\}}\min_{\{L\in S_{\L}|x\in L\}}\Av_{l_1}(L\cap U)=\iso{l}_1(s).
\end{equation}

If $l_2(s)<l_1(s)$, the inequalities in \eqref{eq:ordering_1} and \eqref{eq:ordering_2} hold with strict inequality. 
$\hfill\blacksquare$
}

