Now let $\{\xi_n\}_{n\geq 0}$ and $\{\eta_n\}_{n\geq 0}$ be sequences of independent copies of the random variables $\xi$ and $\eta$, respectively. For any initial point $x \in \mathbb{N}_0^2$, the random walk $\{S_n^x\}_{n\geq 0}$ is defined as follows:
\begin{equation*}
S_0^x = x, \quad S_{n+1}^x = S_{n}^x + \xi_{n+1}\cdot \mathbf{1}_{\{S_n^x\in\mathbb{N}^2\}} + \eta_{n+1}\cdot \mathbf{1}_{\{S_n^x\in\mathbb{N}_0^2\setminus \mathbb{N}^2\}},\quad n\geq 0.
\end{equation*}
Several important properties of the model follow from Assumptions~\ref{asm: A1}--\ref{asm: A6}. First, these assumptions guarantee that the reflected random walk is irreducible on its state space $\mathbb{N}_0^2$. Inside $\mathbb{N}^2$, the walk has a positive drift, so for a starting point sufficiently far from the axes, the probability of remaining forever within the quadrant $\mathbb{N}^2$ lies in the interval $(0,1)$. Another key feature is that on the boundary $\mathbb{N}_0^2 \setminus \mathbb{N}^2$, the transition probabilities are identical along the horizontal and vertical axes. Moreover, the positive drift along the boundary ensures that the walk almost surely reflects back into the interior after some time.

\subsection{Numbers of contacts}

Our aim is to study the time (interpreted as the number of visits, or more precisely, the local time)\ that the walk spends on the boundary before drifting to infinity. This quantity is represented by a random variable $Z_x$, which admits the following representation:
\begin{equation}
\label{eq: definition Z_x}
	Z_x = \sum_{n\geq 0} \mathbf{1}_{\{S_n^x\in\mathbb{N}_0^2\setminus \mathbb{N}^2   \}},\quad x\in\mathbb{N}_0^2.
\end{equation}
For brevity, we will also refer to $Z_x$ as the number of boundary contacts. An alternative way to define $Z_x$ is via a sequence of hitting times. Specifically, for any $n \geq 1$, let $\tau^x_n$ denote the time at which the random walk $\{S_n^x\}_{n \geq 0}$ hits the boundary for the $n$\textsuperscript{th} time, that is,
	\begin{equation}
	\label{eq: definition tau_n^x}
    \left\{\begin{array}{rcll}
	\tau^x_1 &=& \displaystyle \inf \{ k\geq 0: S_k^x\in\mathbb{N}_0^2\setminus \mathbb{N}^2   \},&\smallskip\\ 
    \tau^x_{n+1} &=& \displaystyle\tau_n^x + \inf \{ k\geq 1: S^x_{\tau^x_n+k} \in \mathbb{N}_0^2\setminus \mathbb{N}^2  \}, &\quad n\geq 1.
    \end{array}\right.
\end{equation}
The random variable $Z_x$ can then be characterized in terms of the sequence $\{\tau_n^x\}_{n \geq 1}$ as follows:
\begin{equation}
\label{eq: definition alternative Z_x}
	Z_x = \sum_{n\geq 1} \mathbf{1}_{\{ \tau_n^x<\infty \}}.
\end{equation}
According to definitions \eqref{eq: definition tau_n^x} and \eqref{eq: definition alternative Z_x}, if the walk starts at a point $x$ on the boundary, this initial position is counted as a first contact.

The formulation \eqref{eq: definition alternative Z_x} offers a more convenient framework than the initial definition~\eqref{eq: definition Z_x} for analyzing the probability of events involving $Z_x$. Before moving forward, we first establish that $Z_x$ is finite through the following lemma.

\begin{lemma}
\label{lem: Z_x finite}
	Under Assumptions~\ref{asm: A1}--\ref{asm: A6}, for any $x \in \mathbb{N}_0^2$, we have $Z_x < \infty$ a.s.
\end{lemma}

\begin{proof}
To prove the lemma, it suffices to show that $\lim_{n\to\infty} \mathbf{P} ( Z_x \geq n )=0$ for any point $x \in \mathbb{N}_0^2$. Using the stopping times introduced in \eqref{eq: definition tau_n^x}, we reformulate
\begin{equation*}
    \mathbf{P} ( Z_x \geq n )  = \mathbf{P} (\tau_1^x < \infty, \ldots,\tau_n^x<\infty).
\end{equation*}
To prove that the above probability goes to $0$ as $n\to\infty$, we first consider a starting point $x \in \mathbb{N}_0^2$ located sufficiently far from the origin $(0,0)$ (for instance, with $\vert x \vert_1 \geq 3$), so that there exist paths from $x$ that avoid the boundary axes, since by Assumption~\ref{asm: A4}, the random walk has a drift toward the interior of the quadrant. As a result, if $x \in \mathbb{N}^2$, then $\mathbf{P}(\tau_1^x = \infty) > 0$, and if $x \in \mathbb{N}_0^2 \setminus \mathbb{N}^2$, then $\mathbf{P}(\tau_2^x = \infty) > 0$.

By a monotonicity argument, one can further assert that
\begin{equation*}
\min_{x\in\mathbb{N}^2, \vert x \vert_1 \geq 3} \mathbf{P} (\tau_1^x = \infty )>0\quad \text{and}\quad \min_{x\in\mathbb{N}_0^2\setminus\mathbb{N}^2 ,\vert x \vert_1 \geq 3} \mathbf{P} (\tau_2^x = \infty )>0,
\end{equation*}
and these minima should be reached within a finite neighborhood of the origin.

On the other hand, any state $x\in \mathbb{N}_0^2$ located near the origin (e.g., $ \vert x\vert_1  < 3$) is non-absorbing due to irreducibility, so that there is a non-zero probability that the walk exits this neighborhood within at most four contacts with the boundary. Once outside this region, the walk has a positive probability of escaping to infinity while avoiding further boundary interactions. This leads to the conclusion that $\min_{x\in\mathbb{N}_0^2}  \mathbf{P} (\tau_{4}^x = \infty ) > 0$. As a consequence, we have
	 \begin{equation*}
	\max_{x\in\mathbb{N}_0^2}\mathbf{P} ( \tau_1^x<\infty,\ldots,\tau_{4}^x<\infty ) < 1- \min_{x\in\mathbb{N}_0^2}\mathbf{P} ( \tau_{4}^x = \infty)  < 1.
\end{equation*}
We can now conclude:
	\begin{align*}
	\mathbf{P} (\tau_1^x < \infty, \ldots,\tau_n^x<\infty) &  \leq   \prod_{k=0}^{\lfloor n/4 \rfloor-1}\mathbf{P}(\tau_{4k+1}^x<\infty,\ldots,\tau_{4k+4}< \infty | \tau_{4k}^x<\infty )  \\
	&  \leq \left( \max_{x\in\mathbb{N}_0^2} \mathbf{P} ( \tau_1^x<\infty,\ldots,\tau_{4}^x<\infty )\right)^{\lfloor n/4\rfloor} \to 0,
\end{align*}
as $n\to \infty$, where we conventionally set $\tau_0^x=0$, a.s. 
\end{proof}

\subsection{A recursion satisfied by the numbers of contacts}

We now focus on studying the pmfs of the number of contacts, denoted by
\begin{equation}
\label{eq:def_f_n}
	f_n(x) = \mathbf{P}(Z_{x}=n),\quad n\in\mathbb{N}_0,\quad x\in\mathbb{N}_0^2.
\end{equation} 
As shown in the following theorem, $f_n$ satisfies a first-order recursive relation in $n$, enabling the computation of any term $f_{n+1}$ from the previous term $f_{n}$.


% \begin{theorem}
% \label{thm: f_n(i,j) recurrence relation}
% 	Under Assumptions~\ref{asm: A1}--\ref{asm: A6}, the pmf $f_n(i,j)$ satisfies the recurrence relation
% 	\begin{align}
% 	& \label{eq: f_1(i,j) recurrence relation}
% 	f_1 (i,j) = \sum_{k,\ell} q_{k,\ell} f_0 (i+k,j+\ell) - f_0 (i,j),\quad i,j\geq 0, \\
% 	& \label{eq: f_n(i,j) recurrence relation}
% 	f_{n+1} (i,j) = \sum_{k,\ell} q_{k,\ell} f_n (i+k,j+\ell),\quad n\geq 1,\quad i,j\geq 0.
% \end{align}
