\begin{theorem}
\label{thm: f_n(x) recurrence relation}
	Under Assumptions~\ref{asm: A1}--\ref{asm: A6} and for all $x\in\mathbb{N}_0^2$, the sequence of pmfs $\{f_n\}_{n\geq 0}$ satisfies the recurrence relation
	\begin{equation}
	\label{eq: f_n(x) recurrence relation}
	\left\{\begin{array}{rcll}
    f_1 (x) &=& \displaystyle \mathbf{E} f_0 (x+\eta) - f_0 (x), &\smallskip\\
	f_{n+1} (x) &=& \displaystyle \mathbf{E} f_n (x+\eta),&\quad n\geq 1,
    \end{array}\right.
\end{equation}
where $\eta$ is defined in \eqref{eq: xi, eta pms}. As a consequence, the cumulative distribution function of $Z_x$ admits the representation below, with $\{\eta_k\}_{k\geq 1}$ being independent copies of $\eta$,
\begin{equation}
\label{eq: f_n(x) exp}
	\mathbf{P}(Z_x\leq n)=\sum_{k=0}^n f_k(x) = \mathbf{E} f_0 \left( x + \sum_{k=1}^n \eta_k \right),\quad n\geq 1,\quad x\in\mathbb{N}_0^2.
\end{equation}
\end{theorem}


Before proceeding with the proof, let us first discuss some aspects of Theorem~\ref{thm: f_n(x) recurrence relation}. This is a fairly general result, yet it can be derived using elementary arguments based on a coupling technique. It shows that, once the initial values $f_0$ are known, all subsequent values $f_n$ for $n \geq 1$ follow naturally. From a technical standpoint, the result does not rely on any assumptions regarding higher-order moments (other than \ref{asm: A3} and \ref{asm: A6}). This will be contrasted in Section~\ref{sec:model-2}, where a second model will be considered and similar results derived, this time under higher moment assumptions.

However, the result given in Theorem~\ref{thm: f_n(x) recurrence relation} no longer holds if the transition probabilities along the horizontal and vertical axes differ. Moreover, additional techniques are required to derive an explicit expression for $f_0$. The problem of survival probability has been extensively studied, and in several cases, explicit formulas for $f_0$ have been obtained; see \cite[Cor.~8]{KuRa-11}, \cite[Thm~C]{GaRa-14}, and \cite[Cor.~20]{HoRaTa-23}. In such cases, Theorem~\ref{thm: f_n(x) recurrence relation} can then be used to derive explicit expressions for $f_n$ for any $n \geq 1$.

\begin{proof}[Proof of Theorem~\ref{thm: f_n(x) recurrence relation}]
Our arguments to prove Theorem~\ref{thm: f_n(x) recurrence relation} are based on a coupling technique. For any starting points $x,y\in\mathbb{N}_0^2$, let us consider the coupled process 
\begin{equation*}
\bigl( S_n^{x} , S_n^{x+y} \bigr)_{n\geq 0}.
\end{equation*}
It is readily seen that for any $n\leq \tau_1^{x}$, we have $S_n^{x} + y = S_n^{x+y}$ a.s. We further have $S_{\tau_1^{x} + 1}^{x} = S_{\tau_1^{x} }^{x+y}$ a.s.\ under the conditional measure $\mathbf{P}(\cdot | \tau_1^{x}<\infty, \eta_{\tau_1^{x} + 1} = y )$. As a consequence, 
\begin{equation*}
	\mathbf{P} ( S_{\tau_1^{x}+1+n}^{x} \in \cdot | \tau_1^{x}<\infty, \eta_{\tau_1^{x} + 1} = y )  = \mathbf{P} (  S_{\tau_1^{x}+n}^{x+y} \in \cdot | \tau_1^{x}<\infty  )
\end{equation*}
for any $n\geq 1$, and thus for any $n\geq 1$,
\begin{equation*}
	\mathbf{P} ( \tau_{n+1}^{x} \in \cdot | \tau_1^{x}<\infty, \eta_{\tau_1^{x} + 1} = y )  = \mathbf{P} ( \tau_n^{x+y} + 1 \in \cdot | \tau_1^{x}<\infty  ).
\end{equation*}

The above assertion enables us to estimate the number of contacts of a random walk starting at $x$ by comparing it with that of a coupled random walk started at a different point. This comparison can be used to express $f_{n+1}$ in terms of $f_n$. We start by proving the first identify in \eqref{eq: f_n(x) recurrence relation}. For any $x\in\mathbb{N}_0^2$, we have:
\begin{align*}
	f_1 (x) 
	 &= \mathbf{P} ( \tau_1^{x}<\infty, \tau_2^{x}=\infty ) \\
	 &= \sum_{y\in\mathbb{N}_0^2} q_{y} \mathbf{P} (  \tau_2^{x}=\infty | \tau_1^{x}<\infty, \eta_{\tau_1^{x} + 1} = y ) \mathbf{P} ( \tau_1^{x}<\infty ) \\
	 &= \sum_{y\in\mathbb{N}_0^2} q_{y}  \mathbf{P} (  \tau_1^{x+y}+1 =\infty | \tau_1^{x}<\infty )  \mathbf{P} ( \tau_1^{x}<\infty ) \\
	 &= \sum_{y\in\mathbb{N}_0^2} q_{y} \mathbf{P} ( \tau_1^{x}<\infty,   \tau_1^{x+y}=\infty ) \\
	 &= \sum_{y\in\mathbb{N}_0^2} q_{y}  \left(  \mathbf{P} (   \tau_1^{x+y}=\infty )  -  \mathbf{P} ( \tau_1^{x}=\infty,   \tau_1^{x+y}=\infty )\right) \\
	 &= \sum_{y\in\mathbb{N}_0^2} q_{y}  \left(  \mathbf{P} (   \tau_1^{x+y}=\infty )  -  \mathbf{P} ( \tau_1^{x}=\infty )\right) \\
	 &= \sum_{y\in\mathbb{N}_0^2} q_{y}  f_0(x+y ) - f_0(x).
\end{align*}
%For any We now have:
%\begin{align*}
%	f_2 (i,j)  ={}& \mathbf{P} ( \tau_1^{(i,j)} < \infty , \tau_2^{(i,j)} < \infty , \tau_3^{(i,j)} = \infty ) \\
%	={}& \sum_{k,\ell} q_{k,\ell} \mathbf{P} ( \tau_2^{(i,j)} < \infty , \tau_3^{(i,j)} = \infty |  \tau_1^{(i,j)} < \infty , \eta_{\tau_1^{(i,j)}+1} = (k,\ell) ) \mathbf{P} (  \tau_1^{(i,j)} < \infty ) \\
%	={}& \sum_{k,\ell} q_{k,\ell} \mathbf{P} ( \tau_1^{(i+k,j+\ell)}+1 < \infty , \tau_2^{(i+k,j+\ell)}+1 = \infty |  \tau_1^{(i,j)} < \infty  ) \mathbf{P} (  \tau_1^{(i,j)} < \infty ) \\
%	={}& \sum_{k,\ell} q_{k,\ell} \mathbf{P} (  \tau_1^{(i,j)} < \infty, \tau_1^{(i+k,j+\ell)} < \infty , \tau_2^{(i+k,j+\ell)} = \infty )  \\
%	={}& \sum_{k,\ell} q_{k,\ell} \mathbf{P} (  \tau_1^{(i+k,j+\ell)} < \infty , \tau_2^{(i+k,j+\ell)} = \infty )
%\end{align*}
Similarly, we show the second identity in \eqref{eq: f_n(x) recurrence relation}. For any $n\geq 1$ and $x\in\mathbb{N}_0^2$, we have:
\begin{align*}
	f_{n+1} (x)  &= \mathbf{P} ( \tau_1^{x} < \infty ,\ldots, \tau_{n+1}^{x} < \infty , \tau_{n+2}^{x} = \infty ) \\
	&= \sum_{y\in\mathbb{N}_0^2} q_{y} \mathbf{P} (  \tau_2^{x} < \infty ,\ldots, \tau_{n+1}^{x} < \infty , \tau_{n+2}^{x} = \infty |  \tau_1^{x} < \infty , \eta_{\tau_1^{x}+1} = y ) \mathbf{P} (  \tau_1^{x} < \infty ) \\
	&= \sum_{y\in\mathbb{N}_0^2} q_{y} \mathbf{P} ( \tau_1^{x+y}+1 < \infty ,\ldots , \tau_{n}^{x+y}+1 < \infty, \tau_{n+1}^{x+y}+1 = \infty |  \tau_1^{y} < \infty  ) \mathbf{P} (  \tau_1^{y} < \infty ) \\
	&= \sum_{y\in\mathbb{N}_0^2} q_{y} \mathbf{P} (  \tau_1^{x} < \infty, \tau_1^{x+y} < \infty , \ldots, \tau_{n}^{x+y} < \infty, \tau_{n+1}^{x+y} = \infty )  \\
	&= \sum_{y\in\mathbb{N}_0^2} q_{y} \mathbf{P} (  \tau_1^{x+y} < \infty , \ldots, \tau_{n}^{x+y} < \infty, \tau_{n+1}^{x+y} = \infty ) \\
	&= \sum_{y\in\mathbb{N}_0^2} q_{y} f_n (x+y).
\end{align*}
To conclude, we prove \eqref{eq: f_n(x) exp}. Noting that $\{\eta_n\}_{n\geq 1}$ are independent copies of 
$\eta$, a simple induction yields
\begin{align*}
    &f_1 (x) = \mathbf{E} f_0 (x+\eta_1) - f_0 (x),\\
    &f_n (x) = \mathbf{E} f_{n-1} (x+\eta_n) = \mathbf{E} f_0 \left(x+\sum_{k=1}^n \eta_k \right) - \mathbf{E} f_0 \left(x+ \sum_{k=2}^n \eta_k\right),\quad n\geq 2,\quad x\in\mathbb{N}_0^2.
\end{align*}
The proof is complete.
\end{proof}



\subsection{Upper and lower bounds for the tail probability}
Rather than pursuing results on explicit expressions at this stage, we proceed to an independent consequence of Theorem~\ref{thm: f_n(x) recurrence relation}: deriving upper and lower bounds for the tail probability $\mathbf{P}(Z_x>n)$. 

Let us introduce some notation before stating our result. Given two real sequences $\{a_n\}_{n\geq 0}$ and $\{b_n\}_{n\geq 0}$, we write $a_n \asymp b_n$ as $n \to \infty$ if there exist constants $c_1, c_2 > 0$ such that $c_1 \leq a_n / b_n \leq c_2$ for all sufficiently large $n$. We also denote the maximum and minimum of any two real numbers $a$ and $b$ by
\begin{equation*}
a \vee b = \max\{a,b\}\quad\text{and}\quad
a \wedge b = \min\{a,b\}.
\end{equation*}
The following proposition is a consequence of Theorem~\ref{thm: f_n(x) recurrence relation}, describing the asymptotic behavior of the tail probability $\mathbf{P}(Z_x > n)$. Denote by $\alpha_1$ and $\beta_{-1}$ the unique solutions in $(0,1)$ of the equations
    \begin{equation}\label{eq: alpha_1, beta_-1 equations}
		\alpha = \sum_{k,\ell} p_{k,\ell} \alpha^{k+1}\quad \text{and}\quad 
		\beta = \sum_{k,\ell} p_{k,\ell} \beta^{\ell+1}.
\end{equation}
Let us further denote by $\Pi_1$ and $\Pi_2$ the projections of any point in $\mathbb{R}^2$ onto the first and second coordinates, respectively.
\begin{proposition}
\label{prop:lower_upper}
	Under Assumptions \ref{asm: A1}--\ref{asm: A6}, for any $x=(i,j)\in\mathbb{N}_0^2$, we have as $n\to\infty$
	\begin{equation*}
		\mathbf{P} (Z_{x} >n ) \asymp \alpha_1^i \left(\mathbf{E}\alpha_1^{ \Pi_1 (\eta) } \right)^n  +\beta_{-1}^j \left( \mathbf{E} \beta_{-1}^{ \Pi_2 (\eta) } \right)^n,
\end{equation*}
where $\alpha_1,\beta_{-1}$ are introduced in \eqref{eq: alpha_1, beta_-1 equations}, and $\eta$ is defined in \eqref{eq: xi, eta pms}.
\end{proposition}




These bounds follow from corresponding upper and lower estimates of $f_0(x)$, the probability of not touching the boundary (see \eqref{eq:def_f_n}), combined with a one-dimensional argument based on the boundary contacts of the projections of the random walk onto the axes. More specifically, we analyze the first hitting times of the random walk to each axis, in the absence of reflected jumps on the axes. We begin by defining a new random walk, without reflection jumps. Let
\begin{equation}\label{eq: walk S'_n}
    S'_0 = (0,0),\quad S'_n = \sum_{k=1}^n \xi_k,\quad n\geq 1,
\end{equation}
where $\{\xi_n\}_{n\geq 1}$, as above, are independent copies of $\xi$, whose pmf is given by \eqref{eq: xi, eta pms}. Then the first hitting times of the random walk $\{x+S'_n\}_{n\geq 0}$ to the vertical and horizontal axes, respectively, are defined as follows, for any $x\in\mathbb{N}_0^2$:
\begin{equation*}
    \widehat{\tau}^x = \inf\bigl\{n\geq 0: \Pi_1 \bigl( x+ S_n' \bigr) =0\bigr\}\quad\text{and}\quad 
    \widetilde{\tau}^x = \inf\bigl\{n\geq 0: \Pi_2 \bigl( x+ S_n' \bigr) =0\bigr\}.
\end{equation*}

\begin{lemma}
\label{lem: formula hitting axes}
    Given any $x = (i,j) \in \mathbb{N}_0^2$, and with $\alpha_1$ and $\beta_{-1}$ as defined in \eqref{eq: alpha_1, beta_-1 equations}, we have
    \begin{equation*}
        \mathbf{P} (\widehat{\tau}^x<\infty) = \alpha_1^i\quad \text{and}\quad
        \mathbf{P} (\widetilde{\tau}^x<\infty) = \beta_{-1}^j.
    \end{equation*}
\end{lemma}
Our notation $\alpha_1$ and $\beta_{-1}$ will become clearer in the following section, where we demonstrate that they are elements of a sequence $\{(\alpha_n,\beta_n)\}_{n\in\mathbb{Z}}$ naturally attached to the model, to be introduced in \eqref{eq: alpha_m beta_m definition}.


\begin{proof}
Lemma~\ref{lem: formula hitting axes} is a classical result in the theory of random walks. Indeed, the problem effectively reduces to a one-dimensional random walk, since only one coordinate plays a role. For completeness, we briefly sketch the proof, as it provides a useful connection with the methods employed in this paper.

Let us first fix $x=(i,j)\in\mathbb{N}_0^2$. We will only prove the result for $\widehat{\tau}^{x}$, as the argument for $\widetilde{\tau}^{x}$ is analogous. For clarity, we omit the value of $j$, indicating it with a dot. Define $\alpha_1=\mathbf{P} (\widehat{\tau}^{1,\cdot}<\infty)$, which implies that $\mathbf{P} (\widehat{\tau}^{i,\cdot}_1<\infty)= \alpha_1^i$ for any $i\geq 1$, since under Assumption \ref{asm: A2}, the corresponding walk is skip-free (or left-continuous). Applying the Markov property yields
\begin{equation*}
\mathbf{P} (\widehat{\tau}^{1,\cdot}<\infty) = \sum_{k,\ell} p_{k,\ell} \mathbf{P} (\widehat{\tau}^{1+k,\cdot}<\infty),
\end{equation*}
which corresponds to the first equation of \eqref{eq: alpha_1, beta_-1 equations}, once we replace $\mathbf{P} (\widehat{\tau}^{k,\cdot}<\infty)$ by $\alpha_1^k$. 

The remaining step is to establish the uniqueness of $\alpha_1$ as a solution to the first equation in \eqref{eq: alpha_1, beta_-1 equations} within the interval $(0,1)$. Define
\begin{equation*}
\widehat{K} (\alpha) = \alpha - \sum_{k,\ell} p_{k,\ell} \alpha^{k+1},\quad \alpha\in [0,1].
\end{equation*}
Since $\widehat{K}''(\alpha) < 0$ for all $\alpha\in (0,1)$, and noting that $\widehat{K}'(0)>0$, $\widehat{K}'(1)<0$, $\widehat{K}(0)<0$, and $\widehat{K}(1)=0$, we conclude that $\widehat{K}(\alpha)$ is strictly concave and attains a maximum at a unique point in $(0,1)$. This ensures that $\alpha_1$ is the only root of $\widehat{K}(\alpha)$ in $(0,1)$. The proof is thus complete.\end{proof}




\begin{proof}[Proof of Proposition~\ref{prop:lower_upper}]
Let us first fix $x=(i,j)\in\mathbb{N}_0^2$. Since $\tau_1^x = \widehat{\tau}^x \wedge \widetilde{\tau}^x$ a.s., then
 \begin{equation*}
     \mathbf{P} \bigl(\widehat{\tau}^{x} < \infty \bigr) \vee \mathbf{P} \bigl(\widetilde{\tau}^{x} < \infty \bigr)  \leq \mathbf{P} \bigl(\tau_{1}^{x} < \infty \bigr)   \leq \mathbf{P} \bigl(\widehat{\tau}^{x} < \infty \bigr) + \mathbf{P} \bigl(\widetilde{\tau}^{x} < \infty \bigr),
 \end{equation*}
 or equivalently, using Lemma~\ref{lem: formula hitting axes},
 \begin{equation}\label{eq: f_0 upper lower}
    \alpha_1^i \vee \beta_{-1}^j \leq 1- f_0(i,j) \leq \alpha_1^i + \beta_{-1}^j.
 \end{equation}
This immediately yields
  \begin{equation*}
     \frac{1}{2} \bigl( \alpha_1^i + \beta_{-1}^j \bigr)  \leq 1- f_0 (i,j) \leq \alpha_1^i + \beta_{-1}^j.
 \end{equation*}
Applying the above inequality to the expectation of the sum $(i,j) + \sum_{k=1}^n\eta_k$ with $n\geq 1$, we have
\begin{align*}
	\frac{1}{2} \left ( \mathbf{E}\alpha_1^{i+\sum_{k=1}^n \Pi_1 (\eta_k) }  + \mathbf{E}\beta_{-1}^{j+\sum_{k=1}^n \Pi_2(\eta_k)  } \right) &\leq 1-\mathbf{E}	f_0\left( (i,j)+ \sum_{k=1}^n\eta_k  \right) \\
    &\leq  \mathbf{E}\alpha_1^{i+\sum_{k=1}^n \Pi_1 (\eta_k) }  + \mathbf{E}\beta_{-1}^{j+\sum_{k=1}^n \Pi_2(\eta_k)  },
\end{align*}
or equivalently with \eqref{eq: f_n(x) exp} and thanks to the independence of $\{\eta_k\}_{1\leq k\leq n}$,
\begin{align*}
	\frac{1}{2} \left( \alpha_1^i \left(\mathbf{E}\alpha_1^{ \Pi_1 (\eta) } \right)^n  +\beta_{-1}^j \left( \mathbf{E} \beta_{-1}^{ \Pi_2 (\eta) } \right)^n \right) &\leq 1- \sum_{k=0}^n f_k(i,j) \\
    &\leq \alpha_1^i \left(\mathbf{E}\alpha_1^{ \Pi_1 (\eta) } \right)^n  +\beta_{-1}^j \left( \mathbf{E} \beta_{-1}^{ \Pi_2 (\eta) } \right)^n.\qedhere
\end{align*}
\end{proof}









\section{A second model: singular random walks with arbitrary boundary reflections}
\label{sec:model-2}

\subsection{The model}

In this section, we investigate a class of reflected random walks in which the transition probabilities along the horizontal and vertical axes may differ. An additional constraint is imposed in the interior of the quadrant: the walk is not allowed to jump closer to the origin. Such processes are known as singular random walks. We now give a precise definition of this class. To maintain notational consistency throughout the paper, we largely retain the symbols introduced in the previous section, adapting them as needed to the present setting.

Let $\xi$, $\eta^\mathbf{h}$, $\eta^\mathbf{v}$ and $\eta^\mathbf{o}$ be random variables in $\mathbb{Z}^2$ characterized by their pmfs (the letters ``$\mathbf{h}$'', ``$\mathbf{v}$'', and ``$\mathbf{o}$'' standing for horizontal, vertical, and origin respectively): for all $( k,\ell) \in\mathbb{Z}^2$,
\begin{equation*}
    \mathbf{P} (\xi = (k,\ell) ) = p_{k,\ell},\
    \mathbf{P}(\eta^\mathbf{h} = (k,\ell) ) = h_{k,\ell},
    \
    \mathbf{P}(\eta^\mathbf{v} = (k,\ell) ) = v_{k,\ell},
    \
    \mathbf{P}(\eta^\mathbf{o} = (k,\ell) ) = q_{k,\ell}
   .
\end{equation*}
The set of weights $\{p_{k,\ell}\}_{k,\ell}$, $\{h_{k,\ell}\}_{k,\ell}$, $\{v_{k,\ell}\}_{k,\ell}$, and $\{q_{k,\ell}\}_{k,\ell}$ are non-negative and satisfy the following conditions:

\bigskip

\noindent\begin{minipage}{0.62\textwidth}
\begin{enumerate}[label=(B\arabic{*}),ref={\rm (B\arabic{*})}]
	\item\label{asm: B1}  $\sum p_{k,\ell} = \sum h_{k,\ell} =\sum v_{k,\ell}=\sum q_{k,\ell} = 1$ \\ (\textit{normalization})
	\item\label{asm: B2} $p_{k,\ell}=0$ for all $k,\ell \leq -2$  (\textit{small $<0$ jumps})
	\item\label{asm: B3} $p_{-1,-1} = p_{-1,0} = p_{0,-1}= 0$  (\textit{singular walks})
    \item\label{asm: B4} $p_{-1,1}p_{1,-1}\not=0$ (\textit{non-degeneracy})
    \item\label{asm: B5} $p_{k,\ell}>0$ for some $(k,\ell)$ with $k+\ell>0$
    \item\label{asm: B6} $\sum_{k,\ell}p_{k,\ell}e^{kx+\ell y}$ is finite in a neighborhood of any point of the curve \eqref{eq: level set L} (\textit{moment assumption})
    \item\label{asm: B7} $h_{k,\ell}=v_{k,\ell}=q_{k,\ell}=0$ if $k\leq 0$ and $\ell \leq 0$ 

    (\textit{$\geq 0$ jumps})
    \item\label{asm: B8} $0<\sum_{k,\ell}\ell h_{k,\ell}< \infty$ and $\sum_{k,\ell}k h_{k,\ell}< \infty$; \\$0<\sum_{k,\ell}k v_{k,\ell}< \infty$ and $ \sum_{k,\ell} \ell v_{k,\ell}< \infty$;\\ $0<\sum_{k,\ell}k q_{k,\ell}< \infty$ and $0<\sum_{k,\ell}\ell q_{k,\ell}< \infty$ 

    (\textit{boundary first moments and drifts})
\end{enumerate}
