Let $\{\xi_n\}_{n\geq 0}$, $\{\eta_n^\mathbf{h}\}_{n\geq 0}$, $\{\eta_n^\mathbf{v}\}_{n\geq 0}$, and $\{\eta_n^\mathbf{o}\}_{n\geq 0}$ be sequences of independent copies of $\xi$, $\eta^\mathbf{h}$, $\eta^\mathbf{v}$, and $\eta^\mathbf{o}$, respectively. For an arbitrary $x\in \mathbb{N}_0^2$, the random walk $\{S_n^x\}_{n\geq 0}$ is now defined by $S_0^x = x$ and
\begin{multline*}
    S_{n+1}^x ={} S_{n}^x + \xi_{n+1}\cdot \mathbf{1}_{\bigl\{ S_n^x \in \mathbb{N}^2 \bigr\}} + \eta_{n+1}^\mathbf{h}\cdot \mathbf{1}_{\bigl\{ S_n^x \in \mathbb{N} \times \{0\} \bigr\}} \\
     + \eta_{n+1}^\mathbf{v}\cdot \mathbf{1}_{\bigl\{ S_n^x \in \{0\}\times\mathbb{N} \bigr\}} + \eta_{n+1}^\mathbf{o}\cdot \mathbf{1}_{\bigl\{ S_n^x =(0,0) \bigr\}},\quad n\geq 0.
\end{multline*}
Since the random walk $\{S_n^x\}_{n\geq 0}$ with $x\neq (0,0)$ is singular and thus cannot reach the origin, the final term $\eta_{n+1}^\mathbf{o}\cdot \mathbf{1}_{\left\{ S_n^x =(0,0) \right\}}$ in the definition of $S_n^x$ can be omitted as soon as $x\not=0$. As a result, the analysis of the number of boundary contacts $Z_x$ for starting points $x \neq (0,0)$ does not depend on the specific assumptions made on the weight set $\{q_{k,\ell}\}_{k,\ell}$. Consequently, in this section, we will restrict our attention to random walks starting at $x \neq (0,0)$. The corresponding results for the initial point $x = (0,0)$ will then follow directly from these.

%the distribution of $Z_{(i,j)}$ is unaffected by the transition probabilities at $(0,0)$. In contrast, the distribution of $Z_{(0,0)}$ is entirely determined by the transition probabilities at the origin together with the distributions of the other $Z_{(i,j)}$. For this reason, we do not impose any assumptions on the transition probabilities at $(0,0)$, other than there is a positive probability to escape the origin.



The model presented above can be viewed as a variation of the singular models originally studied in the queueing systems literature \cite{Ad-91,AdWaZi-90,AdWeZi-93,AdBoRe-01}. In these works, the focus lies on the stationary distribution of such models; to render the model stationary, it is necessary to reverse the random walk, that is, to replace the $p_{k,\ell}$ with $p_{-k,-\ell}$. Singular models have also been studied from a combinatorial perspective in \cite{AvVLRa-13,DrHaRoSi-20}. Closer to the present work, harmonic functions associated with singular walks killed at the boundary are analysed in \cite{HoRaTa-23}. In particular, the escape (or survival) probability is computed in closed form. This is closely related to our setting, as the escape probability corresponds to the probability of avoiding the boundary—that is, the probability of having no contact.

As in the previous section, we define the number of boundary contacts $Z_x$ according to \eqref{eq: definition Z_x}, and the sequence of hitting times $\{\tau_n^x\}_{n\geq 1}$ as given in \eqref{eq: definition tau_n^x}. Since the assertion on the almost sure finiteness of $Z_x$ in Lemma~\ref{lem: Z_x finite} does not rely on the identical boundary reflection assumption, it remains valid under the Assumptions~\ref{asm: B1}--\ref{asm: B8}. As in the first model, our goal is to study the pmf $f_n(i,j)$ of the boundary contacts $Z_{(i,j)}$; see \eqref{eq:def_f_n}. However, the coupling technique used previously is no longer applicable, due to the added complexity arising from arbitrary boundary reflections. Instead, we adopt the compensation approach, which will enable us to express the solution through series expansions. In this second model, we thus focus on analysing the generating function of $Z_{(i,j)}$, defined by
\begin{equation}
\label{eq:def_F}
	F(i,j,z)  = \sum_{n\geq 0} f_n(i,j) z^n,\quad (i,j)\in\mathbb{N}_0^2,\quad \vert z\vert\leq 1.
\end{equation}


\subsection{Main result}


For any $i,j\geq 0$, introduce
    \begin{equation}
    \label{eq:def_function_G}
	G(i,j,z) = \sum_{m\in  \mathbb	{Z} }  \bigl( c_m(z) \alpha_m^i \beta_m^j + d_{m+1}(z) \alpha_{m+1}^i \beta_m^j \bigr),
\end{equation} 
where $\left\{ (\alpha_m,\beta_m )\right\}_{m\in\mathbb{Z}}$ is defined in \eqref{eq: alpha_m beta_m definition}, and for any $m\in\mathbb Z$
\begin{equation}\label{eq: c_m d_m definition}
    \left\{\begin{array}{rcl}
        c_0 (z)&=& 1, \\
        d_{m+1}(z) &=& \displaystyle - c_m(z) \frac{1-   z \sum_{k,\ell} v_{k,\ell} \alpha_m^{k} \beta_m^{\ell}}{1 -   z \sum_{k,\ell} v_{k,\ell} \alpha_{m+1}^{k} \beta_m^{\ell}},\smallskip\\
        c_m (z) &=& \displaystyle - d_m (z) \frac{1 -  z \sum_{k,\ell} h_{k,\ell} \alpha_m^{k} \beta_{m-1}^{\ell} }{1 -  z \sum_{k,\ell} h_{k,\ell} \alpha_m^{k} \beta_{m}^{\ell} }.\end{array}\right.
\end{equation}
\begin{theorem}\label{thm: G(i,j,z) generating function}
Under Assumptions~\ref{asm: B1}--\ref{asm: B8}, for any $(i,j)\in\mathbb N_0^2\setminus\{(0,0)\}$, the generating function of $Z_{(i,j)}$ in \eqref{eq:def_F} is equal to $G(i,j,z)$ in \eqref{eq:def_function_G}; in other words, $F(i,j,z) = G(i,j,z)$.
\end{theorem}

For the case $(i,j)=(0,0)$, the generating function $F(0,0,z)$ of $Z_{(0,0)}$ is determined from the expression of other $F(i,j,z)$ via Eq.~\eqref{eq: condition at origin F(i,j,z)}. A large part of the remainder of Section~\ref{sec:model-2} is devoted to the proof of Theorem~\ref{thm: G(i,j,z) generating function}.

\subsection{A bivariate recursion for the boundary contacts generating function}
This subsection aims to formulate a recursion for $F(i,j,z)$, which we will solve using the compensation approach. In Lemma~\ref{lem: recurrence relation f_n(i,j)}, we first establish a bivariate recursion for the pmf $f_n(i,j)$. Building on this, we derive in Proposition~\ref{prop: recurrence relation F(i,j,z)} the corresponding recursive expressions for $F(i,j,z)$.


\begin{lemma}
\label{lem: recurrence relation f_n(i,j)}
	Under Assumption~\ref{asm: B1}--\ref{asm: B8}, the function $f_n:\mathbb{N}_0^2\to [0,1]$ in \eqref{eq:def_f_n} satisfies the recurrence relation
	\begin{equation}\label{eq: recurrence relation f_n(i,j)}
		f_n(i,j) = \sum_{k,\ell} p_{k,\ell}f_n(i+k,j+\ell) , \quad (i,j)\in\mathbb{N}^2,\quad n\geq 0,
\end{equation}
with the horizontal (boundary)\ condition
\begin{equation}
\label{eq: horizontal condition f_n(i,j)}
	f_n (i,0) =\left\{ \begin{array}{ll}
	0 & \text{if } n=0 \\
	\sum_{k,\ell} h_{k,\ell} f_{n-1} ( i+k, \ell)&  \text{if } n\geq 1\end{array}\right\},
\quad i\in\mathbb N,
\end{equation}
the vertical (boundary)\ condition
\begin{equation}
\label{eq: vertical condition f_n(i,j)}
	f_n (0,j) = \left\{\begin{array}{ll}
	0 & \text{if }  n=0 \\
	\sum_{k,\ell} v_{k,\ell} f_{n-1} ( k, j+ \ell) & \text{if }  n\geq 1
\end{array}\right\},
\quad j\in\mathbb N,
\end{equation}
and the condition at the origin
\begin{equation}
\label{eq: condition at origin f_n(i,j)}
	f_n (0,0) = \left\{\begin{array}{ll}
	0 & \text{if }  n=0 \\
	\sum_{k,\ell} q_{k,\ell} f_{n-1} ( k, \ell) & \text{if }  n\geq 1
\end{array}\right\}.
\end{equation}
\end{lemma}


\begin{proof}
Our reasoning is straightforward and relies on decomposing the random walk according to its first step. Observe that for any $(i,j)\in \mathbb{N}^2$ and all $k,\ell\geq -1$, we have $\mathbf{P} ( Z_{(i,j)}\in\cdot | S_1^{(i,j)}=(i+k,j+\ell)) = \mathbf{P} ( Z_{(i+k,j+\ell)}\in\cdot ) $. As a consequence, for any $n\geq 0$,
\begin{align*}
	f_n(i,j) &=  \sum_{k,\ell} p_{k,\ell}  \mathbf{P} \left(Z_{(i,j)} =n \left| S_1^{(i,j)} =(i+k,j+\ell)\right. \right) \\
    &= \sum_{k,\ell} p_{k,\ell}  \mathbf{P} \left(Z_{(i+k,j+\ell)} =n \right)=   \sum_{k,\ell} p_{k,\ell} f_n (i+k,j+\ell),
\end{align*}
which establishes \eqref{eq: recurrence relation f_n(i,j)}.
Now, given that for any $i>0$, $\mathbf{P} ( Z_{(i,0)}\in\cdot | S_1^{(i,0)}=(i+k,\ell)) = \mathbf{P} ( 1+ Z_{(i+k,\ell)}\in\cdot ) $, we have
\begin{equation*}
	f_n(i,0) =  \sum_{k,\ell} h_{k,\ell}  \mathbf{P} \left(Z_{(i,0)} =n \left| S_1^{(i,0)} =(i+k,\ell)\right. \right) = \sum_{k,\ell} h_{k,\ell}  \mathbf{P} \left(1+Z_{(i+k,\ell)} =n \right),
\end{equation*}
which is $0$ if $n=0$, and otherwise equals $\sum_{k,\ell} h_{k,\ell} f_n(i+k,\ell)$, thereby establishing the horizontal condition \eqref{eq: horizontal condition f_n(i,j)}. The vertical condition \eqref{eq: vertical condition f_n(i,j)} and the condition \eqref{eq: condition at origin f_n(i,j)} at the origin follow by analogous arguments.
