It entails that the line $\{t(1,1):t\in\mathbb{R}\}$ divides the curve $\mathcal{L}$ into two parts, which can be parametrized as follows. Let us define
\begin{itemize}
    \item $\gamma:(-\infty,0]\rightarrow \mathbb{R}$ such that $\gamma(0)=0$, $L(x,\gamma(x)) =0$ and $\gamma(x) > x$ for any $x< 0$;
    \item $\zeta:(-\infty,0]\rightarrow \mathbb{R}$ such that $\zeta(0)=0$, $L(\zeta(y),y) =0$ and $\zeta(y)> y$ for any $y< 0$.
\end{itemize}
Both $\gamma$ and $\zeta$ are well-defined functions on $(-\infty,0]$, as will be shown in Lemma~\ref{lem: parametrization level set L} below. The curve $\mathcal{L}$ in \eqref{eq: level set L} can then be described as
\begin{equation*}
	\mathcal{L}= \{(x,\gamma(x)):x\leq 0\} \cup \{(\zeta(y),y):y\leq 0\}. 
\end{equation*}
The following result, which can be found as Lemma~2 in \cite{HoRaTa-23}, gives some key properties of $\gamma$ and $\zeta$.
\begin{lemma}[\!\!{\cite{HoRaTa-23}}]
\label{lem: parametrization level set L}
The following assertions hold:
\begin{enumerate}[label=(\roman*)]
    \item\label{item: gamma zeta well defined} On $(-\infty,0]$, the functions $\gamma$ and $\zeta$ are well defined, concave and infinitely differentiable. 
    \item\label{item: gamma monotonic} The function $\gamma$ has a unique maximizer $\widehat{x}<0$, with corresponding value 
    \begin{equation*}
    \widehat{y}=\max_{x\leq 0} \gamma (x) = \gamma (\widehat x)>0.
    \end{equation*} Moreover, $\gamma$ is strictly increasing on $(-\infty,\widehat{x}]$, with $\lim_{x\to -\infty}\gamma(x)=-\infty$, and strictly decreasing on $[\widehat{x},0]$.
    \item\label{item: zeta monotonic} Similarly, $\zeta$ has a unique maximizer $\widetilde{y}<0$, with corresponding value 
    \begin{equation*}
    \widetilde{x}=\max_{y\leq 0} \zeta (y) =\zeta(\widetilde{y})>0.
    \end{equation*}
    Moreover, $\zeta$ is strictly increasing on $(-\infty,\widetilde{y}]$ with $\lim_{y\to -\infty}\zeta(y)=-\infty$, and strictly decreasing on $[\widetilde{y},0]$.
\end{enumerate}
\end{lemma}

