With the help of the functions $\gamma$ and $\zeta$ introduced above, we are now ready to parametrize the curve $\mathcal{K}$ defined in \eqref{eq:level_set_K} and to examine some of its properties. For $\alpha, \beta \in [0,1]$, we define the functions
\begin{equation}
\label{eq: u(alpha) v(beta) definition}
u(\alpha) = \log \gamma ( \log \alpha) \quad \text{and} \quad v(\beta) = \log \zeta ( \log \beta).
\end{equation}
These functions provide a parametrization of the curve $\mathcal{K}$, which can be expressed as
\begin{equation*}
\mathcal{K}= \{(\alpha,u(\alpha)):\alpha\in [0,1]\} \cup \{(v(\beta),\beta):\beta\in [0,1]\}.
\end{equation*}
The following lemma outlines some key properties of the functions $u$ and $v$ in \eqref{eq: u(alpha) v(beta) definition}.

\begin{lemma}\label{lem: parametrization level set K}
	The following assertions hold:
	\begin{enumerate}[label=(\roman*)]
	\item $u(1)=v(1)=1$, $u(0)=v(0)=0$, $u(\alpha)> \alpha$ and $v(\beta)> \beta$ for any $\alpha,\beta \in (0,1)$; 
\item $u(\alpha)$ and $v(\beta)$ are infinitely differentiable on $(0,1)$;
\item $u$ has a unique maximizer $\widehat{\alpha}\in (0,1)$, with corresponding value 
\begin{equation*}
 \widehat{\beta}=\max_{\alpha\in [0,1]} u (\alpha) = u(\widehat{\alpha}) >0  . 
\end{equation*}
Moreover, $u$ is strictly increasing on $[0,\widehat{\alpha}]$ and strictly decreasing on $[\widehat{\alpha},1]$;
\item $v$ has a unique maximizer $\widetilde{\beta} \in (0,1)$, with corresponding value 
\begin{equation*}
\widetilde{\alpha}=\max_{\beta\in [0,1]} v (\beta) = v(\widetilde{\beta}) >0.    
\end{equation*}
Moreover, $v$ is strictly increasing on $[0,\widetilde{\beta}]$ and strictly decreasing on $[\widetilde{\beta},1]$.
\end{enumerate}
\end{lemma}
The properties of $u$ and $v$ stated in Lemma~\ref{lem: parametrization level set K} follow directly from their definitions in \eqref{eq: u(alpha) v(beta) definition} and from the properties of $\gamma$ and $\zeta$ established in Lemma~\ref{lem: parametrization level set L}. We therefore omit the proof.

We may now construct the sequence $\{(\alpha_m,\beta_m)\}_{m\in\mathbb{Z}}$ introduced at the beginning of the section, in \eqref{eq:evocation_sequence}. Denoting the inverses of $u$ and $v$ restricted to the intervals $[0,\widehat{\alpha}]$ and $[0,\widetilde{\beta}]$ by
\begin{equation}
\label{eq:def_ustar_vstar}
u^* = \bigl( u\big|{[0,\widehat{\alpha}]} \bigr)^{-1} \quad \text{and} \quad
v^* = \bigl( v\big|{[0,\widetilde{\beta}]} \bigr)^{-1},
\end{equation}
we define the sequence $\{(\alpha_m,\beta_m)\}_{m\in\mathbb{Z}}$ on the curve $\mathcal{K}$ recursively as follows:
\begin{equation}\label{eq: alpha_m beta_m definition}
    \begin{cases}
        \alpha_0=\beta_0 = 1,\\
        \alpha_m = u^*(\beta_{m-1}),\quad \beta_m = v^*(\alpha_m),\quad m\geq 1,\\
        \beta_m = v^*(\alpha_{m+1}),\quad \alpha_m = u^*(\beta_m),\quad m\leq -1.
    \end{cases}
\end{equation}


