In the following lemma, we compute the decay of $\alpha_m$ and $\beta_m$ as $m\to\pm\infty$.
\begin{lemma}\label{lem: alpha_m beta_m decay}
	The sequences $\{\alpha_m\}_{m\geq 0}$, $\{\alpha_{-m}\}_{m\geq 0}$, $\{\beta_m\}_{m\geq 0}$, and $\{\beta_{-m}\}_{m\geq 0}$, defined in \eqref{eq: alpha_m beta_m definition}, are strictly decreasing and exhibit exponential decay as $m\to\infty$:
\begin{equation*}
\alpha_{\pm m}, \beta_{\pm m} = O\left( \left( \frac{\widehat{\alpha}}{\widehat{\beta}} \cdot \frac{\widetilde{\beta}}{\widetilde{\alpha}} \right)^{|m|} \right),
\end{equation*}
where $\frac{\widehat{\alpha}}{\widehat{\beta}} \cdot \frac{\widetilde{\beta}}{\widetilde{\alpha}} < 1$, and the constants $\widehat{\alpha}, \widehat{\beta}, \widetilde{\beta}, \widetilde{\alpha}$ are as defined in Lemma~\ref{lem: parametrization level set K}.
\end{lemma}

\begin{proof}
	Since for all $m\geq 1$,
    \begin{equation*}
        \beta_0 = \alpha_0 > \widehat{\alpha} > \alpha_1 \quad\text{and}\quad
        \alpha_m > v^*(\alpha_m) = \beta_m > u^*(\beta_m) = \alpha_{m+1},
    \end{equation*}
then $\{\alpha_m\}_{m\geq 0}$ and $\{\beta_m\}_{m\geq 0}$ are strictly decreasing. An analogous reasoning yields the same result for $\{\alpha_{-m}\}_{m\geq 0}$ and $\{\beta_{-m}\}_{m\geq 0}$.

We move to analyzing the decay of $\alpha_m$ and $\beta_m$ as $m\to\pm\infty$. The idea is to compare them to an alternative sequence $\{ (\alpha'_m, \beta'_m) \}_{m\in\mathbb{Z}}$, which is defined recursively by
\begin{equation*}
    \begin{cases}
        \alpha'_0 = \beta'_0 = 1,\\
        \displaystyle \alpha'_m = \frac{\widehat{\alpha}}{\widehat{\beta}} \beta'_{m-1},\quad \beta'_m = \frac{\widetilde{\beta}}{\widetilde{\alpha}} \alpha'_m, &m\geq 1,\\
        \displaystyle\beta'_m = \frac{\widetilde{\beta}}{\widetilde{\alpha}} \alpha'_{m+1} ,\quad \alpha'_m = \frac{\widehat{\alpha}}{\widehat{\beta}} \beta'_m, &m\leq -1.
    \end{cases}
\end{equation*}

% \begin{align*}
% 	& ( \widehat{\alpha}_0, \widehat{\beta}_0 ) = ( \alpha_0,\beta_0 ) = (1,1), \\
% 	& ( \widehat{\alpha}_m, \widehat{\beta}_m ) = \left( \left( \frac{\widehat{\alpha}}{\widehat{\beta}}  \right)^m  \left(  \frac{\widetilde{\beta}}{\widetilde{\alpha}} \right)^{m-1} , \left( \frac{\widehat{\alpha}}{\widehat{\beta}}  \right)^m  \left(  \frac{\widetilde{\beta}}{\widetilde{\alpha}} \right)^{m} \right), \quad m\geq 1,\\
% 	& ( \widehat{\alpha}_{-m}, \widehat{\beta}_{-m} ) = \left( \left( \frac{\widehat{\alpha}}{\widehat{\beta}}  \right)^{m}  \left(  \frac{\widetilde{\beta}}{\widetilde{\alpha}} \right)^{m} , \left( \frac{\widehat{\alpha}}{\widehat{\beta}}  \right)^{m-1}  \left(  \frac{\widetilde{\beta}}{\widetilde{\alpha}} \right)^{m} \right), \quad m\geq 1.
% \end{align*}
Since the sublevel set $\mathcal{L}^-$ is convex and contains the ray $\{t(1,1):t<0\}$ (Lemma~\ref{lem: level set L}), it must also contain the rays $\{(\widehat{x},\widehat{y})+t(1,1):t<0\}$ and $\{(\widetilde{x},\widetilde{y})+t(1,1):t<0\}$, where $\widehat{x}$ and $ \widehat{y}$ are respectively the maximizer and maximal value of $\gamma$, while $\widetilde{y}$ and $ \widetilde{x}$ are respectively the maximizer and maximal value of $\zeta$, as defined in Lemma~\ref{lem: parametrization level set L}. Consequently, the sublevel set $\mathcal{K}^-=\{(\alpha,\beta)\in[0,\infty)^2:K(\alpha,\beta)<0\}$ contains the segments $\{t(\widehat{\alpha},\widehat{\beta}):t\in(0,1)\}$ and $\{t(\widetilde{\alpha},\widetilde{\beta}):t\in(0,1)\}$. As a result, we have:
\begin{equation*}
	u(\alpha) \geq \frac{\widehat{\beta}}{\widehat{\alpha}} \alpha,\quad \alpha \in [0,\widehat{\alpha}],\quad \text{or equivalently,}\quad 
	u^* (\beta) \leq \frac{\widehat{\alpha}}{\widehat{\beta}} \beta,\quad \beta\in[0,\widehat{\beta}],
\end{equation*}
and
\begin{equation*}
	v(\beta) \geq \frac{\widetilde{\alpha}}{\widetilde{\beta}} \beta,\quad \beta \in [0,\widetilde{\beta}],\quad \text{or equivalently,}\quad 
	v^* (\alpha) \leq \frac{\widetilde{\beta}}{\widetilde{\alpha}} \alpha,\quad \alpha\in[0,\widetilde{\alpha}].
\end{equation*}
These inequalities enable us to compare $\alpha_m$ to $\alpha'_m$, and $\beta_m$ to $\beta'_m$. We first have:
\begin{equation*}
	\alpha_1 = u^* (\beta_0) \leq \frac{\widehat{\alpha}}{\widehat{\beta}}= \alpha'_1\quad
	\text{and}
	\quad
	\beta_1 = v^* (\alpha_1) \leq v^* (\alpha'_1) \leq \frac{\widetilde{\beta}}{\widetilde{\alpha}} \alpha'_1 = \beta'_1.
\end{equation*}
By an induction argument, we then have for any $m\geq 2$:
\begin{align*}
	&\alpha_m = u^*(\beta_{m-1}) \leq u^*(\beta'_{m-1}) \leq \frac{\widehat{\alpha}}{\widehat{\beta}}\beta'_{m-1} = \alpha'_{m},\\
	&\beta_m = v^* (\alpha_m) \leq v^* (\alpha'_m) \leq \frac{\widetilde{\beta}}{\widetilde{\alpha}}\alpha'_m= \beta'_m.
\end{align*}
Similar arguments imply for any $m\leq -1$.
\begin{equation*}
	\alpha_{m} \leq \widehat{\alpha}_{m}\quad
	\text{and}\quad
	\beta_{m} \leq \widehat{\beta}_{m}.
\end{equation*}
Now since the sequence $\{(\alpha'_m,\beta'_m)\}_{m\in\mathbb{Z}}$ can be explicitly expressed by
\begin{equation*}
    \begin{cases}
        \alpha'_0 = \beta'_0 =1,\\
        \displaystyle\frac{\widetilde{\beta}}{\widetilde{\alpha}} \alpha'_m = \beta'_m = \left( \frac{\widehat{\alpha}}{\widehat{\beta}} \cdot\frac{\widetilde{\beta}}{\widetilde{\alpha}} \right)^m , &m\geq 1,\\ \displaystyle
         \alpha'_m = \frac{\widehat{\alpha}}{\widehat{\beta}} \beta'_m = \left( \frac{\widehat{\alpha}}{\widehat{\beta}} \cdot\frac{\widetilde{\beta}}{\widetilde{\alpha}} \right)^{-m} , &m\leq -1,
    \end{cases}
\end{equation*}
it suffices to derive the decay of $\alpha_m$ and $\beta_m$ as $m\to\pm \infty$. The proof is then complete.
\end{proof}






















\begin{lemma}\label{lem: G(i,j,z) convergence}
	For any $(i,j)\in\mathbb{N}_0^2\setminus\{(0,0)\}$, the series of functions $G(i,j,z)$ in \eqref{eq:def_function_G} is analytic on the open unit disk, and satisfies Equations~\eqref{eq: recurrence relation F(i,j,z)}--\eqref{eq: terminal condition F(i,j,1)}.
\end{lemma}


\begin{proof}
For clarity, we denote, for any $m \in \mathbb{Z}$,
\begin{equation}
\label{eq:def_v_h_tilde_hat}
    \left\{\begin{array}{rclrcl}
        \widehat{v}_m &=& \sum_{k,\ell} v_{k,\ell} \alpha_m^k \beta_{m}^\ell,\qquad 
	\widetilde{v}_m &=& \sum_{k,\ell} v_{k,\ell} \alpha_m^k \beta_{m-1}^\ell, \smallskip\\
    \widehat{h}_m &=& \sum_{k,\ell} h_{k,\ell} \alpha_m^k \beta_{m}^\ell ,\qquad 
	\widetilde{h}_m &=& \sum_{k,\ell} h_{k,\ell} \alpha_m^k \beta_{m-1}^\ell.
    \end{array}\right.
\end{equation}
Then, the recursive formula \eqref{eq: c_m d_m definition} for the coefficients $c_m(z)$ and $d_m(z)$ becomes:
\begin{equation}
\label{eq:recursive_bis_cd}
	c_0(z) = 1,\quad d_{m+1} (z) = - c_m(z) \frac{1-\widehat{v}_m z}{1-\widetilde{v}_{m+1} z},\quad c_m(z) = -d_m(z) \frac{1-\widetilde{h}_m z}{1-\widehat{h}_m z}.
\end{equation}

We begin by showing that $\sum_{m\geq 1} c_m(z)\alpha_m^i\beta_m^j$ is analytic on the open unit disk.
By direct induction, the coefficients $\{c_m(z)\}_{m\geq 1}$ satisfy the product formula
\begin{equation*}
    c_m(z) = \prod_{k=1}^m \frac{1-\widetilde{h}_kz}{1-\widehat{h}_kz}\frac{1-\widehat{v}_{k-1}z}{1-\widetilde{v}_kz}.
\end{equation*}
If $k$ is large enough, then $\widetilde{h}_k, \widehat{h}_k,\widetilde{v}_k, \widehat{v}_k$ are all in $(0,\varepsilon)$ (recall that $\alpha_m$ and $\beta_m$ decay exponentially as $m \to \pm\infty$, see Lemma~\ref{lem: alpha_m beta_m decay}, and recall our hypothesis \ref{asm: B7}). Hence there exists a constant $C$ such that for all $\vert z\vert \leq 1$ and all $m\geq 1$, 
\begin{equation*}
    c_m(z) \leq C \left(\frac{1+\varepsilon}{1-\varepsilon}\right)^m.
\end{equation*}
Therefore, for any $(i,j)\in\mathbb{N}_0^2\setminus\{(0,0)\}$, the series
$\sum_{m\geq 1} c_m(z)\alpha_m^i\beta_m^j$ is analytic on the disk centered at $0$ with radius $\frac{1 - \varepsilon}{1 + \varepsilon}$.
Since $\varepsilon$ is arbitrary, we conclude that the series is analytic on the open unit disk.

By similar arguments, the series $\sum_{m\leq 0} c_m(z)\alpha_m^i\beta_m^j$ and $\sum_{m\in \mathbb{Z}} d_{m+1}(z)\alpha_{m+1}^i\beta_m^j$ are also analytic on the open unit disk.

We now show that $G(i,j,z)$ satisfies Eqs.~\eqref{eq: recurrence relation F(i,j,z)}--\eqref{eq: terminal condition F(i,j,1)}. Fix $(i,j)\in \mathbb{N}_0^2\setminus\{(0,0)\}$ and $z \in [0,1]$. For any $m \in \mathbb{Z}$, since both $(\alpha_m, \beta_m)$ and $(\alpha_{m+1}, \beta_m)$ belong to $\mathcal{K}$, the terms $\alpha_m^i \beta_m^j$ and $\alpha_{m+1}^i \beta_m^j$ satisfy Eq.~\eqref{eq: recurrence relation F(i,j,z)}. By linearity, it follows that $G(i,j,z)$ satisfies the same equation. Moreover, we set, for any $m \in \mathbb{Z}$
\begin{align*}
	H_m(i,j) &= d_{m}(z) \alpha_{m}^i \beta_{m-1}^j +  c_m(z) \alpha_m^i \beta_m^j ,\\
     V_m(i,j) &= c_m(z) \alpha_m^i \beta_m^j + d_{m+1}(z) \alpha_{m+1}^i \beta_m^j.
\end{align*}
Therefore, the function $G(i,j,z)$ can be written as
\begin{equation*}
	G(i,j,z) = \sum_{m\in\mathbb{Z}} H_m(i,j) = \sum_{m\in\mathbb{Z}} V_m(i,j).
\end{equation*}
It is easily seen that $H_m(i,0)$ and $V_m(0,j)$ satisfy Eq.~\eqref{eq: horizontal condition F(i,j,z)} and Eq.~\eqref{eq: vertical condition F(i,j,z)}, respectively. As a result, $G(i,0) = \sum_{m\in\mathbb{Z}} H_m (i,0)$ and $G(0,j) = \sum_{m\in\mathbb{Z}} V_m (0,j)$ also satisfy Eq.~\eqref{eq: horizontal condition F(i,j,z)} and Eq.~\eqref{eq: vertical condition F(i,j,z)}, respectively. Finally, observe that when $z=1$, all coefficients $c_m(1)$ and $d_m(1)$ vanish except for $c_0(1)\alpha_0^i\beta_0^j=1$, which yields $G(i,j,1) =1$.
\end{proof}

\subsection{Proof of Theorem~\ref{thm: G(i,j,z) generating function}}
In this subsection, we prove that $G(i,j,z)$ is indeed the generating function of the number of contacts $Z_{(i,j)}$, as stated in Theorem~\ref{thm: G(i,j,z) generating function}.

\paragraph{A remark on non-uniqueness of the solutions.}

We should first emphasize that the system of equations \eqref{eq: recurrence relation F(i,j,z)}--\eqref{eq: terminal condition F(i,j,1)} admits infinitely many solutions, among which the series $G(i,j,z)$ in \eqref{eq:def_function_G} is one particular instance. Indeed, alternative solutions can be obtained by altering the initial value $(\alpha_0,\beta_0)$ or the base coefficient $c_0(z)$, while keeping the same recursive structure \eqref{eq: c_m d_m definition} for the remaining $(\alpha_m,\beta_m)$, $c_m(z)$, and $d_m(z)$. More precisely, one can choose any pair $(\alpha_0,\beta_0)$ lying on the curve
\begin{equation*}
\{(\alpha,u(\alpha)):\alpha\in[\widehat{\alpha},1]\} \cup \{(v(\beta),\beta):\beta\in[\widetilde{\beta},1]\},
\end{equation*}
along with any function $c_0(z)$ that is bounded on $[0,1]$. The series $G(i,j,z)$ constructed from these alternative initial values then satisfies Eqs.~\eqref{eq: recurrence relation F(i,j,z)}--\eqref{eq: vertical condition F(i,j,z)}, though it may fail to satisfy the terminal condition \eqref{eq: terminal condition F(i,j,1)}. Conversely, if the initial values are fixed to $\alpha_0 = \beta_0 = 1$, then for any bounded function $c_0(z)$ on $[0,1]$ with $c_0(1) = 1$, the resulting series $G(i,j,z)$ gives another solution to the full system \eqref{eq: recurrence relation F(i,j,z)}--\eqref{eq: terminal condition F(i,j,1)}.


This non-uniqueness leads to difficulties, as the system of equations \eqref{eq: recurrence relation F(i,j,z)}--\eqref{eq: terminal condition F(i,j,1)} alone does not suffice to characterize the solutions, and we will need to invoke certain probabilistic properties of the solution.














