% 	\label{eq: g_0  asymptotic behavior}
% 	g_0 (i,j) =1- \alpha_1^i - \beta_{-1}^j + o(1),\\
% 	&
% 	\label{eq: g_n  asymptotic behavior}
% 	g_n(i,j) = \left( 1- \widetilde{v}_1 \right)    \widetilde{v}_1^{n-1}\alpha_1^i +   \left( 1- \widetilde{h}_0 \right)    \widetilde{h}_0 ^{n-1}\beta_{-1}^j + o(1),\quad n\geq 1,
% \end{align}



\paragraph{Asymptotics of $f_n(i,j)$.}
We now focus on the asymptotic behavior of $f_n(i,j)$ as defined in \eqref{eq:def_f_n}. Our analysis relies on estimating hitting probabilities when the walk starts far from the origin. The following lemma provides the asymptotic probabilities of three complementary events: avoiding the boundary, hitting the vertical axis, and hitting the horizontal axis.

We introduce the functions $f_{[\mathbf{v}]}$ and $f_{[\mathbf{h}]}$, defined for all $(i,j) \in \mathbb{N}_0^2$ by
\begin{equation*}
    f_{[\mathbf{v}]} (i,j) = \mathbf{P} \Bigl( \tau_1^{i,j} < \infty , \Pi_1\bigl(S^{i,j}_{ \tau_1^{i,j} }\bigr) =0\Bigr)\quad \text{and}\quad 
    f_{[\mathbf{h}]} (i,j) = \mathbf{P} \Bigl( \tau_1^{i,j} < \infty , \Pi_2\bigl(S^{i,j}_{ \tau_1^{i,j} }\bigr) =0\Bigr).
\end{equation*}
Here, the subscripts $[\mathbf{v}]$ and $[\mathbf{h}]$ are used to indicate “vertical” and “horizontal,” respectively. The square brackets are included to clearly distinguish these notations from the functions $f_n$.

\begin{lemma}\label{lem: f_0 asymptotic}
With $f_0$ as introduced in \eqref{eq:def_f_n}, and $f_{[\mathbf{v}]}$ and $f_{[\mathbf{h}]}$ as defined above, we have, as $i + j \to \infty$,
	\begin{gather}
	\label{eq: f_0, f hat, f tilde asymptotic behavior}
	f_0(i,j)= 1- \alpha_1^i - \beta_{-1}^j + O\bigl( (\alpha_1\vee \beta_{-1} )^{\tfrac{1}{2}(i+j)} \bigr),\\
	f_{[\mathbf{v}]} (i,j) = \alpha_1^i + O\bigl( (\alpha_1\vee \beta_{-1} )^{\tfrac{1}{2}(i+j)} \bigr),\quad
	f_{[\mathbf{h}]} (i,j)= \beta_{-1}^j +O\bigl( (\alpha_1\vee \beta_{-1} )^{\tfrac{1}{2}(i+j)} \bigr).\notag
\end{gather}
\end{lemma}


Intuitively, Lemma~\ref{lem: f_0 asymptotic} suggests the following: when the walk starts far from both axes, it is most likely to avoid them both; conversely, if it starts far from one axis but close to the other, it rarely hits the distant boundary and behaves, with respect to the nearby axis, much like a one-dimensional random walk.



\begin{proof}
 Recall from \eqref{eq: f_0 upper lower} that we have for all $(i,j)\in\mathbb N_0^2$
	 \begin{equation*}
       \alpha_1^i + \beta_{-1}^j -  \alpha_1^i  \wedge \beta_{-1}^j \leq 1- f_0(i,j) \leq \alpha_1^i + \beta_{-1}^j.
 \end{equation*}
Together with the fact that $\alpha_1^i  \wedge \beta_{-1}^j=O\bigl( (\alpha_1\vee \beta_{-1} )^{\tfrac{1}{2}(i+j)} \bigr)$ as $ i+j\to\infty$, we can deduce the asymptotic behavior of $f_0(i,j)$. Now observe that
\begin{equation}
\label{eq:nobt}
	f_{[\mathbf{v}]}(i,j) + f_{[\mathbf{h}]}(i,j) = 1- f_0(i,j) = \alpha_1^i + \beta_{-1}^j + O\bigl( (\alpha_1\vee \beta_{-1} )^{\tfrac{1}{2}(i+j)} \bigr),
\end{equation}
as $i+j\to\infty$, and based on Lemma~\ref{lem: formula hitting axes},
\begin{equation*}
		f_{[\mathbf{v}]} (i,j) \leq  \mathbf{P} ( \widehat{\tau}^{i,j} < \infty) = \alpha_1^i\quad \text{and}\quad
		f_{[\mathbf{h}]} (i,j) \leq  \mathbf{P} ( \widetilde{\tau}^{i,j} < \infty) = \beta_{-1}^j.
\end{equation*}
Substituting these upper bounds into \eqref{eq:nobt}, we obtain the asymptotic behavior of $f_{[\mathbf{v}]}(i,j)$ and $f_{[\mathbf{h}]}(i,j)$. This concludes the proof.
\end{proof}



We now build on Lemma~\ref{lem: f_0 asymptotic} to analyze the probabilities of subsequent boundary contacts for a random walk starting far from the origin and conditioned on having hit the boundary multiple times before. By the strong Markov property, the walk's behavior under this conditioning depends only on its most recent boundary contact. Consequently, we first introduce the following conditioned probability measures:
\begin{equation*}
        \mathbf{P}_n^{\mathbf{v}} =\mathbf{P}\left(\cdot \left| \tau_n^{i,j} < \infty , \Pi_1 \bigl(S^{i,j}_{\tau_n^{i,j} } \bigr)= 0 \right. \right) 
        \quad\text{and}\quad
        \mathbf{P}_n^{\mathbf{h}} =\mathbf{P}\left(\cdot \left| \tau_n^{i,j} < \infty , \Pi_2 \bigl(S^{i,j}_{\tau_n^{i,j} } \bigr)= 0 \right. \right),
\end{equation*}
for any $(i,j)\in\mathbb N_0^2$ and $n\geq 1$. The following result describes the asymptotic behavior of having one additional boundary contact under these conditioned measures.

\begin{lemma}
\label{lem: probability from axis to axis}
	For any $n\geq 1$, we have as $i+j\to\infty$ 
    % By denoting $\widehat{\mathbf{P}}_n =\mathbf{P}(\cdot | \tau_n^{(i,j)} < \infty , P_1 (S^{(i,j)}_{\tau_n^{(i,j)} } )= 0  )$ for any $i,j\geq 0,n\geq 1$, we have:
	\begin{align}
		& \label{eq: asymptotic 2nd contact conditioned 1st contact at vertical line}
        \mathbf{P}_n^{\mathbf{v}} \left(  \tau_{n+1}^{i,j} < \infty \right) = \mathbf{P}_n^{\mathbf{v}} \left(  \tau_{n+1}^{i,j} < \infty, \Pi_1 \bigl(S^{i,j}_{\tau_{n+1}^{i,j} } \bigr)= 0  \right)  + o(1) =   \widetilde{v}_1 + o(1), \\
        & \label{eq: asymptotic 2nd contact conditioned 1st contact at horizontal line}
        \mathbf{P}_n^{\mathbf{h}} \left(  \tau_{n+1}^{i,j} < \infty \right) = \mathbf{P}_n^{\mathbf{v}} \left(  \tau_{n+1}^{i,j} < \infty, \Pi_2 \bigl(S^{i,j}_{\tau_{n+1}^{i,j} } \bigr)= 0  \right)  + o(1) =   \widetilde{h}_0 + o(1).
\end{align}
%Similarly, by denoting $\widetilde{\mathbf{P}}_n =\mathbf{P}(\cdot | \tau_n^{(i,j)} < \infty , P_2 (S^{(i,j)}_{\tau_n^{(i,j)} } )= 0  )$ for any $i,j\geq 0$, we have:
% 	\begin{equation}\label{eq: asymptotic 2nd contact conditioned 1st contact at horizontal line}
% 		\widetilde{\mathbf{P}}_n \left(  \tau_{n+1}^{(i,j)} < \infty \right) = \widetilde{\mathbf{P}}_n \left(  \tau_{n+1}^{(i,j)} < \infty, P_2 (S^{(i,j)}_{\tau_{n+1}^{(i,j)} } )= 0  \right)  + o(1) =   \sum_{k,\ell} h_{k,\ell} \beta_{-1}^\ell + o(1),
% \end{equation}
% as $(i+j)\to\infty$.
\end{lemma}
The lemma above conveys a straightforward idea: when a random walk starts far from the origin and reaches one axis, it is unlikely to hit the other axis afterward. Instead, the walk is more likely to either return to the same axis or avoid both axes altogether.

\begin{proof}
We evaluate the probability that the random walk hits the vertical (resp.\ horizontal) axis for the $(n+1)$\textsuperscript{th} time with $n\geq 1$, given that it has previously hit the vertical axis at the $n$\textsuperscript{th} time, as follows:
\begin{align*}
&\mathbf{P}_n^{\mathbf{v}} \left(  \tau_{n+1}^{i,j} < \infty,  \Pi_1 \bigl(S^{i,j}_{\tau_{n+1}^{i,j} } \bigr)= 0 \right) \\
& = \sum_{j'\geq i+j} \mathbf{P}_n^{\mathbf{v}} \left( \Pi_2 \bigl(S^{i,j}_{\tau_n^{i,j} } \bigr)= j'  \right) \mathbf{P}_n^{\mathbf{v}} \left( \tau_{n+1}^{i,j} < \infty,  \Pi_1 \bigl(S^{i,j}_{\tau_{n+1}^{i,j} } \bigr)= 0 \left| \Pi_2 \bigl(S^{i,j}_{\tau_n^{i,j} } \bigr)= j'  \right.\right) \\
&=\sum_{j'\geq i+j} \mathbf{P}_n^{\mathbf{v}} \left( \Pi_2 \bigl(S^{i,j}_{\tau_n^{i,j} } \bigr)= j'  \right) \sum_{k,\ell} v_{k,\ell} f_{[\mathbf{v}]} (k, j'+\ell) \\
&=\sum_{j'\geq i+j} \mathbf{P}_n^{\mathbf{v}} \left( \Pi_2 \bigl(S^{i,j}_{\tau_n^{i,j} } \bigr)= j'  \right) \sum_{k,\ell} v_{k,\ell} \left(\alpha_1^k  + O\bigl( (\alpha_1\vee \beta_{-1} )^{\tfrac{1}{2}(j'+k+\ell)} \bigr) \right) \\
&=  \sum_{k,\ell} v_{k,\ell} \alpha_1^k  + o(1)\\
&= \widetilde{v}_1 + o(1),
\end{align*}
and
\begin{align*}
	&\mathbf{P}_n^{\mathbf{v}}  \left(  \tau_{n+1}^{i,j} < \infty, \Pi_2 \bigl(S^{i,j}_{\tau_{n+1}^{i,j} } \bigr) = 0 \right) \\
    &= \sum_{j'\geq i+j} \mathbf{P}_n^{\mathbf{v}} \left( \Pi_2 \bigl(S^{i,j}_{\tau_n^{i,j} } \bigr)= j'  \right) \mathbf{P}_n^{\mathbf{v}} \left( \tau_{n+1}^{i,j} < \infty, \Pi_2 \bigl(S^{i,j}_{\tau_{n+1}^{i,j} } \bigr)= 0 \left| \Pi_2 \bigl(S^{i,j}_{\tau_n^{i,j} } \bigr)= j' \right. \right) \\
	 & = \sum_{j'\geq i+j} \mathbf{P}_n^{\mathbf{v}} \left( \Pi_2 \bigl(S^{i,j}_{\tau_n^{i,j} } \bigr)= j'  \right) \sum_{k,\ell} v_{k,\ell} f_{[\mathbf{h}]} (k,j'+\ell) \\
	 &=  \sum_{j'\geq i+j} \mathbf{P}_n^{\mathbf{v}} \left( \Pi_2 \bigl(S^{i,j}_{\tau_n^{i,j} } \bigr)= j'  \right) \sum_{k,\ell} v_{k,\ell} \left(\beta_{-1}^{j'+\ell} + O\bigl( (\alpha_1\vee \beta_{-1} )^{\tfrac{1}{2}(j'+k+\ell)} \bigr) \right)\\
	 &= o(1),
\end{align*}
as $i+j\to\infty$. Summing the above two equalities, we deduce \eqref{eq: asymptotic 2nd contact conditioned 1st contact at vertical line}. The proof for \eqref{eq: asymptotic 2nd contact conditioned 1st contact at horizontal line} follows similarly.
\end{proof}


Lemma~\ref{lem: probability from axis to axis} enables us to evaluate the asymptotic probability of $n$ boundary contacts, namely, $f_n (i,j)$, by carefully decomposing the event into a sequence of distinct sub-events corresponding to the first, second, third, and subsequent boundary contacts.

\begin{lemma}
For any $n\geq 1$, we have as $i+j\to\infty$,
\begin{equation}
\label{eq: f_n asymptotic behavior}
    f_n (i,j) =  \bigl( 1- \widetilde{v}_1 \bigr)    \widetilde{v}_1^{n-1}\alpha_1^i +   \bigl( 1- \widetilde{h}_0 \bigr)    \widetilde{h}_0 ^{n-1}\beta_{-1}^j + o(1).
	%f_n( i,j) = \left( 1- \sum_{k,\ell} v_{k,\ell} \alpha_1^k \right)   \left( \sum_{k,\ell} v_{k,\ell} \alpha_1^k \right)^{n-1}\alpha_1^i +   \left( 1- \sum_{k,\ell} h_{k,\ell} \beta_{-1}^\ell \right)   \left( \sum_{k,\ell} h_{k,\ell} \beta_{-1}^\ell \right)^{n-1}\beta_{-1}^j + o(1),
\end{equation}
\end{lemma}

\begin{proof}
By iteratively decomposing the event $\{\tau_1^{i,j}<\infty,\ldots,\tau_n^{i,j}<\infty, \tau_{n+1}^{i,j}=\infty\}$ using the strong Markov property, together with the estimates from Lemma~\ref{lem: probability from axis to axis}, we obtain the following asymptotic evaluation for any $n \geq 1$ as $i + j \to \infty$:
\begin{align*}
	f_n(i,j) &= \mathbf{P} \Bigl(\tau_1^{i,j}<\infty,\ldots,\tau_n^{i,j}<\infty, \tau_{n+1}^{i,j}=\infty,  \Pi_1 \bigl(S^{i,j}_{\tau_1^{i,j} } \bigr)= 0 \Bigr) \\
    &\quad+ \mathbf{P} \Bigl(\tau_1^{i,j}<\infty,\ldots,\tau_n^{i,j}<\infty, \tau_{n+1}^{i,j}=\infty,  \Pi_2 \bigl(S^{i,j}_{\tau_1^{i,j} } \bigr)= 0 \Bigr)  \\
	&= \mathbf{P}_{n}^{\mathbf{v}} \bigl(\tau^{i,j}_{n+1} = \infty \bigr) \mathbf{P}_{n-1}^{\mathbf{v}} \bigl(\tau^{i,j}_{n} < \infty \bigr) \cdots \mathbf{P}_{1}^{\mathbf{v}} \bigl(\tau^{i,j}_{2} < \infty \bigr) \mathbf{P}\Bigl(\tau_1^{i,j}<\infty,  \Pi_1 \bigl(S^{i,j}_{\tau_1^{i,j} } \bigr)= 0 \Bigr) \\
	&\quad +  \mathbf{P}_{n}^{\mathbf{h}} \bigl(\tau^{i,j}_{n+1} = \infty \bigr) \mathbf{P}_{n-1}^{\mathbf{h}} \bigl(\tau^{i,j}_{n} < \infty \bigr)\cdots \mathbf{P}_{1}^{\mathbf{h}} \bigl(\tau^{i,j}_{2} < \infty \bigr) \mathbf{P}\Bigl(\tau_1^{i,j}<\infty,  \Pi_2 \bigl(S^{i,j}_{\tau_1^{i,j} } \bigr)= 0 \Bigr) \\
    &\quad+ o(1)\\
	&= \bigl( 1- \widetilde{v}_1 \bigr)    \widetilde{v}_1^{n-1}\alpha_1^i +   \bigl( 1- \widetilde{h}_0 \bigr)    \widetilde{h}_0 ^{n-1}\beta_{-1}^j + o(1).\qedhere
\end{align*}
\end{proof}

\paragraph{Conclusion of the proof.}
Having established the asymptotic behavior of $f_n(i,j)$, we are now prepared to prove Theorem~\ref{thm: G(i,j,z) generating function}.

\begin{proof}[Proof of Theorem~\ref{thm: G(i,j,z) generating function}]
We prove the identity between $f_n$ and $g_n$ by induction on $n\geq 0$. Starting with the base case $n=0$, note that both $f_0$ and $g_0$ are harmonic on $\mathbb{N}^2$, vanish on the boundary axes (as they satisfy Eqs.~\eqref{eq: recurrence relation f_n(i,j)}--\eqref{eq: vertical condition f_n(i,j)} by construction), and exhibit the same asymptotic behavior as $i+j \to \infty$ (see \eqref{eq: g_n asymptotic} and \eqref{eq: f_0, f hat, f tilde asymptotic behavior}). It follows that their difference $f_0 - g_0$ is also harmonic, vanishes on the boundary, and tends to zero at infinity. By the maximum principle for harmonic functions, we deduce that $f_0 - g_0 = 0$ on $\mathbb{N}_0^2\setminus\{(0,0)\}$, thus establishing the base case.

We now assume that $f_n = g_n$ for some $n \geq 0$, and aim to show that the same equality holds for $n+1$. By construction, both $f_{n+1}$ and $g_{n+1}$ are harmonic on $\mathbb{N}^2$, and they inherit the same boundary values from the equality $f_n = g_n$ established at the previous step. In addition, $f_{n+1}$ and $g_{n+1}$ share the same asymptotic behavior as $i + j \to \infty$ (see \eqref{eq: g_n asymptotic} and \eqref{eq: f_n asymptotic behavior}).
It follows that the difference $f_{n+1} - g_{n+1}$ is harmonic on $\mathbb{N}^2$, vanishes on the boundary, and tends to zero at infinity. Applying the same maximum principle argument as in the base case, we conclude that $f_{n+1} - g_{n+1} = 0$ on $\mathbb{N}_0^2\setminus\{(0,0)\}$. This completes the induction step and establishes that $f_n = g_n$ for all $n \geq 0$.
\end{proof}

\subsection{Asymptotic analytics}
In this subsection, we examine the asymptotic decay of the probability $f_n(i,j)$ as $n\to\infty$. 
\begin{proposition}\label{prop: f_n asymptotic}
    Under Assumptions~\ref{asm: B1}--\ref{asm: B8}, for any $(i,j)\in\mathbb N_0^2\setminus\{(0,0)\}$, the number of contacts $f_n(i,j)$ has the asymptotic behavior as $n\to \infty$:
      \begin{equation}\label{eq: f_n asymptotic in n}
        f_n(i,j) \sim C_{i,j} \left(  \widetilde{v}_1 \vee \widetilde{h}_0 \right)^{n}, 
    \end{equation}
      where
    \begin{equation*}
        C_{i,j} = 
        \begin{cases}
            (1/\widetilde{v}_1-1)S_1(1/\widetilde{v}_1),\quad &\widetilde{v}_1 > \widetilde{h}_0, \\
            (1/\widetilde{v}_1-1)\left[S_1(1/\widetilde{v}_1) + S_0(1/\widetilde{v}_1) \right],\quad &\widetilde{v}_1 = \widetilde{h}_0, \\
            (1/\widetilde{h}_0-1)S_0(1/\widetilde{h}_0),\quad &\widetilde{v}_1 < \widetilde{h}_0,
        \end{cases}  
    \end{equation*}
the functions $S_0(z)$ and $S_1(z)$ being defined by \eqref{eq: S_1(z) S_0(z)}.
\end{proposition}

\begin{proof}
We will show in Lemma~\ref{lem: dominant pole} that the generating function $G(i,j,z)$ has a simple dominant pole.
Proposition~\ref{prop: f_n asymptotic} then follows directly by applying singularity analysis for meromorphic functions; see, for instance, \cite[Thm~IV.10]{FlSe-09}.
The constant $C_{i,j}$ corresponds to the residue of $G(i,j,z)$ at its smallest pole, namely $1/(\widetilde{v}_1 \vee \widetilde{h}_0)$.
\end{proof}


