\begin{lemma}\label{lem: dominant pole}
There exists $\varepsilon > 0$ sufficiently small such that, for any $(i,j) \in \mathbb{N}_0^2\setminus\{(0,0)\}$, the function $G(i,j,z)$ is meromorphic in the open disk 
\begin{equation*}
    \mathcal{B}_\varepsilon = \{ z \in \mathbb{C} : |z| < 1/(\widetilde{v}_1 \vee \widetilde{h}_0) + \varepsilon \},
\end{equation*}
and has a unique pole in this domain, located at $1/(\widetilde{v}_1 \vee \widetilde{h}_0)$. This pole is simple.
\end{lemma}


\begin{proof}
Fix $(i,j)\in\mathbb N_0^2\setminus\{(0,0)\}$ for the rest of the proof and, without loss of generality, assume $\widetilde{v}_1 \geq \widetilde{h}_0$. Choose $\varepsilon>0$ so small that $(1/\widetilde{v}_1+\varepsilon)^{-1}$ exceeds all the values $\widehat{v}_m$, $\widehat{h}_m$, $\widetilde{v}_m$, and $\widetilde{h}_m$ cited in \eqref{eq:inequalities_vh_0} and \eqref{eq:inequalities_vh}.

We begin with the case $\widetilde{v}_1 > \widetilde{h}_0$. Since $1/\widetilde{v}_1$ is the unique pole of $d_1(z)=-\frac{1-z}{1-\widetilde{v}_1 z}$, we can use \eqref{eq:def_function_G} together with \eqref{eq: c_m d_m definition} to rewrite $G(i,j,z)$ as
\begin{equation*}
	G(i,j,z) = S_1(z) d_1 (z) + R_1(z),
\end{equation*}
where
\begin{equation*}
	\left\{\begin{array}{rcl}
    S_1(z) &=& \displaystyle \sum_{m\geq 1} \left( \frac{d_m(z)}{d_1 (z)}\alpha_m^i\beta_{m-1}^j +\frac{c_m(z)}{d_1 (z)}\alpha_m^i\beta_{m}^j  \right), \\
     R_1 (z) &=& \displaystyle \sum_{m\leq 0} \left( d_m(z)\alpha_m^i\beta_{m-1}^j + c_m(z)\alpha_m^i\beta_{m}^j  \right).
     \end{array}\right.
\end{equation*}
It suffices to show that $S_1(z)$ and $R_1(z)$ are analytic on $\mathcal{B}_\varepsilon$, and $S_1(1/\widetilde{v}_1)\not=0$. Observe  with \eqref{eq:recursive_bis_cd} that for $m\geq 2$, $d_m(z)/d_1(z)$ can be written as 
\begin{equation*}
    \frac{d_m(z)}{d_1(z)} = \prod_{k=1}^{m-1}
    \frac{1-\widetilde{h}_k z}{1-\widehat{h}_k z}
    \frac{1-\widehat{v}_k z}{1-\widetilde{v}_{k+1}z},
\end{equation*}
of which all the poles are greater than $1/\widetilde{v}_1$. Hence, any $d_m(z)/d_1(z)$ with $m\geq 1$ is analytic on the disk $\mathcal{B}_\varepsilon$. By the same reasoning as in the proof of Lemma~\ref{lem: G(i,j,z) convergence}, we deduce that the series $\sum_{m\geq 1}\frac{d_m(z)}{d_1 (z)}\alpha_m^i\beta_{m-1}^j$ is analytic on $\mathcal{B}_\varepsilon$. Similarly, we conclude that the series $\sum_{m\geq 1}\frac{c_m(z)}{d_1 (z)}\alpha_m^i\beta_{m}^j$, $\sum_{m\leq 0}d_m(z)\alpha_m^i\beta_{m-1}^j$, and $\sum_{m\leq 0}c_m(z)\alpha_m^i\beta_{m}^j$ are all analytic on $\mathcal{B}_\varepsilon$, and hence, so are $S_1(z)$ and $R_1(z)$.


We now show that $S_1(1/\widetilde{v}_1) \not=0$. In the subcase $\widetilde{v}_1 > \widetilde{h}_1$, let us reformulate $S_1(z)$ as
\begin{equation*}
    S_1(z) = \sum_{m\geq 1}  \frac{d_m(z)}{d_1 (z)}\alpha_m^i  \left( \beta_{m-1}^j +\frac{c_m(z)}{d_m(z)}\beta_{m}^j \right) = \sum_{m\geq 1}  \frac{d_m(z)}{d_1 (z)}\alpha_m^i  \left( \beta_{m-1}^j - \frac{1-\widetilde{h}_m z}{1-\widehat{h}_m z}\beta_{m}^j \right).
\end{equation*}
Since
\begin{equation*}
    %\frac{d_1(1/\widetilde{v}_1)}{d_1(1/\widetilde{v}_1)}=1 > 0, \quad 
    \frac{d_m(1/\widetilde{v}_1)}{d_1(1/\widetilde{v}_1)} \geq 0,\quad m\geq 2,
\end{equation*}
where the equality happens if $\widetilde{v}_1 = \widehat{v}_1$, and
\begin{equation*}
    \alpha_m^i  \left( \beta_{m-1}^j - \frac{1-\widetilde{h}_m /\widetilde{v}_1}{1-\widehat{h}_m /\widetilde{v}_1}\beta_{m}^j \right) > 0,\quad m\geq 1,
\end{equation*}
then $S_1(1/\widetilde{v}_1) >0$. Now in the subcase $\widetilde{v}_1 \leq \widetilde{h}_1$, we reformulate $S_1(z)$ as
\begin{align*}
    S_1(z)&=\alpha_1^i +\sum_{m\geq 1} \left( \frac{c_m(z)}{d_1(z)}  \alpha_m^i \beta_m^j + \frac{d_{m+1}(z)}{d_1(z)}  \alpha_{m+1}^i \beta_m^j \right) \\
    &= \alpha_1^i +\sum_{m\geq 1} \frac{c_m(z)}{d_1(z)} \beta_m^j \left(  \alpha_m^i  - \frac{1-\widehat{v}_m z}{1-\widetilde{v}_{m+1}z}  \alpha_{m+1}^i  \right).
\end{align*}
Since
\begin{equation*}
    \frac{c_1(\widetilde{v}_1)}{d_1(\widetilde{v}_1)} = -\frac{1-\widetilde{h}_1/\widetilde{v}_1}{1-\widehat{h}_1/\widetilde{v}_1} \geq 0,
\end{equation*}
then
\begin{equation*}
    \frac{c_m(1/\widetilde{v}_1)}{d_1(1/\widetilde{v}_1)} = \frac{c_1(1/\widetilde{v}_1)}{d_1(1/\widetilde{v}_1)} \prod_{k=2}^m \frac{1 - \widehat{v}_{k-1}/\widetilde{v}_1}{1-\widetilde{v}_k /\widetilde{v}_1} \frac{1-\widetilde{h}_k /\widetilde{v}_1 }{1 - \widehat{h}_k /\widetilde{v}_1} \geq 0,\quad m\geq 2.
\end{equation*}
Together with the fact that
\begin{equation*}
    \beta_m^j \left(  \alpha_m^i  - \frac{1-\widehat{v}_m /\widetilde{v}_1}{1-\widetilde{v}_{m+1}/\widetilde{v}_1}  \alpha_{m+1}^i  \right) > 0,\quad m\geq 1,
\end{equation*}
we deduce that $S_1(1/\widetilde{v}_1) >0$, which concludes the case $\widetilde{v}_1 > \widetilde{h}_0$.


We now move to the case $\widetilde{v}_1 = \widetilde{h}_0$. Noting that $1/\widetilde{v}_1$ is the unique simple pole of $d_0(z)=d_1(z)=-\frac{1-z}{1-\widetilde{v}_1z}$, we rewrite $G(i,j,z)$ as
\begin{equation*}
	G(i,j,z)=1 + S_1(z)d_1(z) + S_0(z)d_0(z),
\end{equation*}
where
\begin{equation}\label{eq: S_1(z) S_0(z)}
    \begin{cases}\displaystyle
    S_1(z) = \sum_{m\geq 1} \left( \frac{d_m(z)}{d_1 (z)}\alpha_m^i\beta_{m-1}^j +\frac{c_m(z)}{d_1 (z)}\alpha_m^i\beta_{m}^j  \right),\\ \displaystyle
	S_0(z) = \sum_{m\leq 0 } \left( \frac{d_m(z)}{d_0 (z)}\alpha_m^i\beta_{m-1}^j +\frac{c_{m-1}(z)}{d_0 (z)}\alpha_{m-1}^i\beta_{m-1}^j  \right).
    \end{cases}
\end{equation}
By similar arguments as the preceding case, $S_1(z)$ and $S_0(z)$ are analytic on $\mathcal{B}_\varepsilon$, and $S_1(1/\widetilde{v}_1) > 0$, $S_0(1/\widetilde{h}_0) > 0$. Therefore, the lemma holds in this case as well, which completes the proof.
\end{proof}



We observe that if $1/\widetilde{v}_1$ and $1/\widetilde{h}_0$ are indeed the two smallest simple poles of $G(i,j,z)$ (more precisely, if $\widetilde{v}_1\wedge\widetilde{h}_0 > \widehat{h}_1\vee\widehat{v}_{-1}$), then the asymptotics~\eqref{eq: f_n asymptotic in n} can be rewritten as
\begin{equation*}
f_n(i,j) = (1-\widetilde{v}_1)S_1\left(\frac{1}{\widetilde{v}_1}\right)\widetilde{v}_1^{n-1} + (1-\widetilde{h}_0)S_0\left(\frac{1}{\widetilde{h}_0}\right)\widetilde{h}_0^{n-1} + o\left( ( \widetilde{v}_1 \wedge \widetilde{h}_0 )^{n}\right) ,
\end{equation*}
as $n\to\infty$, for any $(i,j)\in\mathbb{N}_0^2\setminus\{(0,0)\}$. This form closely resembles the asymptotic behavior given in~\eqref{eq: f_n asymptotic behavior} for $f_n(i,j)$ as $i+j\to \infty$. On the other hand, in situations where the drift of the walk (both in the interior and on the boundary of the quadrant) is strongly asymmetric, the ordering of the first few smallest poles may differ significantly across various regimes of transition probabilities. In principle, more refined analyses could yield sharper asymptotic estimates.


\section{Various examples}
\label{sec:examples}

In this section, we explore several examples, particularly those that lie at the intersection of the two models studied in this work (Section~\ref{sec:model-1} and Section~\ref{sec:model-2}). These examples demonstrate the versatility of the compensation approach for both singular and non-singular random walks.


 %There are various examples which are at the intersection of the two models considered in this work. As a consequence, one can apply either Theorem~\ref{thm: f_n(x) recurrence relation} to deliver recursive expression for the pmf, or Theorem~\ref{thm: G(i,j,z) generating function} to deliver closed-form expression for the generating function. We will walk through some examples to emphasize the applicability of each approach.

 \subsection{Singular walks with same horizontal and vertical reflections}

We begin with the top-left model in Figure~\ref{fig: model examples}.
\begin{proposition}\label{prop: f_n closed form}
    Assume~\ref{asm: B1}--\ref{asm: B8} and $v_{k,\ell} = h_{k,\ell} =q_{k,\ell} $ for any $k,\ell$. Then, for any $(i,j)\in\mathbb N_0^2$, the generating function $F(i,j,z)$ of $Z_{(i,j)}$ has the expression
    \begin{equation}\label{eq: G(i,j,z) reduced case}
        F(i,j,z) = \sum_{m\in\mathbb{Z}} \left(\frac{1-z}{1-z \sum_{k,\ell}q_{k,\ell}\alpha_m^k \beta_m^\ell} \alpha_m^i\beta_m^j - \frac{1-z}{1- z\sum_{k,\ell}q_{k,\ell}\alpha_{m+1}^k \beta_m^\ell} \alpha_{m+1}^i\beta_m^j\right).
    \end{equation}
    As a consequence, the functions $f_n$ admit the closed-form expressions
    \begin{align*}
        f_0 (i,j) ={}& \sum_{m\in\mathbb{Z}} \left( \alpha_m^i\beta_m^j - \alpha_{m+1}^i\beta_m^j\right), \\
        f_n (i,j) ={}& \sum_{m\in\mathbb{Z}} \left[-\bigl(1 - \sum_{k,\ell}q_{k,\ell}\alpha_m^k \beta_m^\ell\bigr) \bigl(\sum_{k,\ell}q_{k,\ell}\alpha_m^k \beta_m^\ell \bigr)^{n-1}\alpha_m^i\beta_m^j \right.\\
        & \quad\quad\quad\quad\left.+ \bigl(1 - \sum_{k,\ell}q_{k,\ell}\alpha_{m+1}^k \beta_m^\ell\bigr) \bigl(\sum_{k,\ell}q_{k,\ell}\alpha_{m+1}^k \beta_m^\ell \bigr)^{n-1} \alpha_{m+1}^i\beta_m^j \right],\quad n\geq 1.
    \end{align*}
\end{proposition}

Since Assumptions~\ref{asm: A1}--\ref{asm: A6} hold for the model, it is straightforward to verify that the above expressions for $f_n$ satisfy the recurrence relation stated in Theorem~\ref{thm: f_n(x) recurrence relation}.

\begin{proof}
    Since $v_{k,\ell} = h_{k,\ell} =q_{k,\ell} $ for any $k,\ell$, then for any $m\in\mathbb{Z}$,
    \begin{equation*}
        \widehat{v}_m = \widehat{h}_m = \sum_{k,\ell} q_{k,\ell}\alpha_m^k\beta_m^\ell\quad\text{and}\quad
        \widetilde{v}_m = \widetilde{h}_m = \sum_{k,\ell} q_{k,\ell}\alpha_m^k\beta_{m-1}^\ell.
    \end{equation*}
    Accordingly, the coefficients $c_m(z)$ and $d_m(z)$, defined through cumulative products in \eqref{eq: c_m d_m definition}, simplify to the expressions
    \begin{equation*}
        c_m(z) = \frac{1-z}{1-z \sum_{k,\ell}q_{k,\ell}\alpha_m^k \beta_m^\ell}\quad \text{and}\quad
        d_m(z) = - \frac{1-z}{1-z \sum_{k,\ell}q_{k,\ell}\alpha_m^k \beta_{m-1}^\ell},
    \end{equation*}
    which yields the simplified form \eqref{eq: G(i,j,z) reduced case} for the generating function introduced in \eqref{eq:def_function_G}. The closed-form expressions for $f_n$ then follow directly from the Taylor expansion of $F(i,j,z)$ in $z$.
\end{proof}

