\section{Proof of lemmas and theorems}

\subsection{Proof of \Cref{lem: Gateaux differentiability of g}}
\label{pf-lem: Gateaux differentiability of g}

Write $\Delta = q - p$ for the sake of brevity. It follows from \cref{eq: lambda functional :eq} that
\begin{align*}
0 & = \int_{ \mathbb{R} \times \mathbb{R} } \bigg( \Big( \lambda ( p + \varepsilon \Delta ) - x - \frac{z}{\theta } \Big)_{+} - \Big( \lambda (p) - x -\frac{z}{\theta } \Big)_{+} \bigg) p ( dx, dz ) \\
  & \quad + \varepsilon \int_{ \mathbb{R} \times \mathbb{R} } \bigg( \frac{z}{\theta } + \Big( \lambda ( p + \varepsilon \Delta ) - x -\frac{z}{\theta } \Big)_{+} \bigg) \Delta ( dx, dz ) \\
  & = \int_{ \lambda (p) }^{ \lambda ( p + \varepsilon \Delta ) } ds \int_{\{ x + z / \theta \le s \}} p ( dx, dz ) 
    + \varepsilon \int_{ \mathbb{R} \times \mathbb{R} } \bigg( \frac{z}{\theta } + \Big( \lambda ( p + \varepsilon \Delta ) - x -\frac{z}{\theta } \Big)_{+} \bigg) \Delta ( dx, dz ),
\end{align*}
which implies that $\lambda ( p + \varepsilon \Delta ) \to \lambda (p)$ as $\varepsilon \to 0$.
Moreover, $\int_{\{ x + z / \theta \le s \}} p ( dx, dz )$ as a cumulative distribution function is c\'adl\'ag, 
and hence, for sufficiently small $\varepsilon > 0$, we have
\begin{align*}
D ( p, \varepsilon, \Delta ) := \frac{1}{ \lambda ( p + \varepsilon \Delta ) - \lambda (p) } \int_{ \lambda (p) }^{ \lambda ( p + \varepsilon \Delta ) } ds \int_{\{ x + z / \theta \le s \}} p ( dx, dz ) \in ( 0,1 ],
\end{align*}
and 
\begin{equation*}
0 < \int_{\{ x + z / \theta < \lambda (p) \}} p ( dx, dz ) 
  \le \liminf_{ \varepsilon \downarrow 0 } D ( p, \varepsilon, \Delta )
  \le \limsup_{ \varepsilon \downarrow 0 } D ( p, \varepsilon, \Delta )
  \le 1.
\end{equation*}
Consequently, for sufficiently small $\varepsilon > 0$
\begin{equation*}
  | \lambda ( p + \varepsilon \Delta ) - \lambda (p) | 
= \frac{\varepsilon }{ D ( p, \varepsilon, \Delta ) }
  \bigg| \int_{ \mathbb{R} \times \mathbb{R} } \bigg( \frac{z}{\theta } + \Big( \lambda (p) - x -\frac{z}{\theta } \Big)_{+} \bigg) \Delta ( dx, dz ) \bigg|
+ o ( \varepsilon )
\end{equation*}
On the other hand, for \cref{eq: non-linear objective functional :eq} we have
\begin{align*}
& g ( p + \varepsilon \Delta ) - g (p) \\
& = \big( \lambda ( p + \varepsilon \Delta ) - \lambda (p) \big) \int_{ \mathbb{R} \times \mathbb{R} } ( 1- z ) d p ( dx, dz ) \\
& \quad - \frac{\theta }{2} \int_{ \mathbb{R} \times \mathbb{R} } \Big| \Big( \lambda ( p + \varepsilon \Delta ) - x - \frac{z}{\theta } \Big)_{+} \Big|^{2} p ( dx, dz )
        + \frac{\theta }{2} \int_{ \mathbb{R} \times \mathbb{R} } \Big| \Big( \lambda (p) - x - \frac{z}{\theta } \Big)_{+} \Big|^{2} p ( dx, dz ) \\
& \quad + \varepsilon \int_{ \mathbb{R} \times \mathbb{R} } \bigg( \lambda ( p + \varepsilon \Delta ) ( 1 - z ) 
                                                                 - \frac{\theta }{2} \Big| \Big( \lambda ( p + \varepsilon \Delta ) - x - \frac{z}{\theta } \Big)_{+} \Big|^{2} 
                                                                 + x z + \frac{1}{ 2 \theta } ( {z}^{2} - 1 ) \bigg) \Delta ( dx, dz ) \\
& = \big( \lambda ( p + \varepsilon \Delta ) - \lambda (p) \big) \int_{ \mathbb{R} \times \mathbb{R} } ( 1- z ) d p ( dx, dz ) \\
& \quad - \theta \int_{ - \infty }^{ \lambda (p) } \big( \lambda ( p + \varepsilon \Delta ) - \lambda (p) \big) ds \int_{\{ x + z / \theta \le s \}} p ( dx, dz ) \\
& \quad - \theta \int_{ \lambda (p) }^{ \lambda ( p + \varepsilon \Delta ) } \big( \lambda ( p + \varepsilon \Delta ) - s \big) ds \int_{\{ x + z / \theta \le s \}} p ( dx, dz ) \\
& \quad + \varepsilon \int_{ \mathbb{R} \times \mathbb{R} } \nabla g ( p,x,z ) \Delta ( dx, dz )
        + o ( \varepsilon ). 
\end{align*}
Plugging \cref{eq: lambda functional equivalent expression :eq} with the asymptotic estimation
\begin{align*}
    \bigg| \int_{ \lambda (p) }^{ \lambda ( p + \varepsilon \Delta ) } \big( \lambda ( p + \varepsilon \Delta ) - s \big) ds \int_{\{ x + z / \theta \le s \}} p ( dx, dz ) \bigg|
& \le \bigg| \int_{ \lambda (p) }^{ \lambda ( p + \varepsilon \Delta ) } | \lambda ( p + \varepsilon \Delta ) - s | ds \bigg| \\
&   = \frac{1}{2} | \lambda ( p + \varepsilon \Delta ) - \lambda (p) |^{2},
\end{align*}
into the above statement yields $g ( p + \varepsilon \Delta ) - g (p) = \varepsilon \int_{ \mathbb{R} \times \mathbb{R} } \nabla g ( p,x,z ) \Delta ( dx, dz ) + o ( \varepsilon )$.
Then, the desired result immediately arises.


\subsection{Proof of \Cref{lem: boundedness of gap}}
\label{pf-lem: boundedness of gap}

Similar to the proof of \Cref{lem: Gateaux differentiability of g}, we have
\begin{align*}
&   g(q) - g(p) \\
& = d g ( p, q-p )
  + \big( \lambda (q) - \lambda (p) \big) \int_{ \mathbb{R} \times \mathbb{R} } ( 1- z ) d q ( dx, dz ) \\
& \quad - \frac{\theta }{2} \int_{ \mathbb{R} \times \mathbb{R} } \Big| \Big( \lambda (q) - x - \frac{z}{\theta } \Big)_{+} \Big|^{2} q ( dx, dz )
        + \frac{\theta }{2} \int_{ \mathbb{R} \times \mathbb{R} } \Big| \Big( \lambda (p) - x - \frac{z}{\theta } \Big)_{+} \Big|^{2} q ( dx, dz ) \\
& = d g ( p, q-p ) + \int_{ \lambda (q) }^{ \lambda (p) } \big( \lambda (p) - s \big) ds \int_{\{ x + z / \theta \le s \}} q ( dx, dz ) \\
& \quad + \big( \lambda (q) - \lambda (p) \big) \int_{ \mathbb{R} \times \mathbb{R} } ( 1- z ) d q ( dx, dz ) 
        - \theta \int_{ - \infty }^{ \lambda (q) } \big( \lambda (q) - \lambda (p) \big) ds \int_{\{ x + z / \theta \le s \}} q ( dx, dz ),
\end{align*}
where the last line vanishes, with
\begin{equation*}
    \bigg| \int_{ \lambda (q) }^{ \lambda (p) } \big( \lambda (p) - s \big) ds \int_{\{ x + z / \theta \le s \}} q ( dx, dz ) \bigg| 
\le \bigg| \int_{ \lambda (q) }^{ \lambda (p) } | \lambda (p) - s | ds \bigg|
  = \frac{1}{2} | \lambda (q) - \lambda (p) |^{2}.
\end{equation*}
So the proof is completed.

\subsection{Proof of \Cref{lem: estimate for gap}}
\label{pf-lem: estimate for gap}

It follows from \cref{eq: lambda functional :eq} that
\begin{align*}
&   \lambda ( \mathbb{P}^{t}_{ {X}_{T} + \chi, \zeta } ) - \lambda ( \mathbb{P}^{t}_{ {X}_{T}, \zeta } ) \\
& = \mathbb{E}_{t} \Big[ \lambda ( \mathbb{P}^{t}_{ {X}_{T} + \chi, \zeta } ) \wedge \Big( {X}_{T} + \chi + \frac{\zeta }{\theta } \Big)  
                       - \lambda ( \mathbb{P}^{t}_{ {X}_{T}, \zeta } ) \wedge \Big( {X}_{T} + \frac{\zeta }{\theta } \Big) \Big] \\
& = \mathbb{E}_{t} \Big[ \Big( \lambda ( \mathbb{P}^{t}_{ {X}_{T} + \chi, \zeta } ) - {X}_{T} - \frac{\zeta }{\theta } \Big) {1}_{ {R}_{0} \cap ( \Omega \setminus {R}_{1} ) }
                       + \Big( {X}_{T} + \chi + \frac{\zeta }{\theta } - \lambda ( \mathbb{P}^{t}_{ {X}_{T}, \zeta } ) \Big) {1}_{ ( \Omega \setminus {R}_{0} ) \cap {R}_{1} } \Big] \\
& \quad + \mathbb{E}_{t} [ \chi {1}_{ {R}_{0} \cap {R}_{1} }  ]
        + \big( \lambda ( \mathbb{P}^{t}_{ {X}_{T} + \chi, \zeta } ) - \lambda ( \mathbb{P}^{t}_{ {X}_{T}, \zeta } ) \big) \mathbb{E}_{t} [ {1}_{ ( \Omega \setminus {R}_{0} ) \cap ( \Omega \setminus {R}_{1} ) } ] \\
& \le \mathbb{E}_{t} [ \chi {1}_{ {R}_{0} } ] + \big( \lambda ( \mathbb{P}^{t}_{ {X}_{T} + \chi, \zeta } ) - \lambda ( \mathbb{P}^{t}_{ {X}_{T}, \zeta } ) \big) \mathbb{E}_{t} [ {1}_{ \Omega \setminus {R}_{0} } ].
\end{align*}
Consequently, $\lambda ( \mathbb{P}^{t}_{ {X}_{T} + \chi, \zeta } ) - \lambda ( \mathbb{P}^{t}_{ {X}_{T}, \zeta } ) \le \mathbb{E}_{t} [ \chi {1}_{ {R}_{0} } ] / \mathbb{E}_{t} [ {1}_{ {R}_{0} } ]$,
as ${R}_{0}$ is not a $\mathbb{P}^{t}_{ {X}_{T}, \zeta }$-null set.
In the same manner, we can show that $\lambda ( \mathbb{P}^{t}_{ {X}_{T} + \chi, \zeta } ) - \lambda ( \mathbb{P}^{t}_{ {X}_{T}, \zeta } ) \ge \mathbb{E}_{t} [ \chi {1}_{ {R}_{1} } ] / \mathbb{E}_{t} [ {1}_{ {R}_{1} } ]$.
Thus, the proof is completed.

\subsection{Proof of \Cref{thm: verification theorem for ONEC}}
\label{pf-thm: verification theorem for ONEC}

Fix $t \in [ 0,T )$ and $\xi \in \mathbb{L}^{2}_{ \mathcal{F}_{t} } ( \Omega; \mathbb{R} )$ such that $\bar{\pi }^{ t, \varepsilon, \xi } \in \mathbb{L}^{2}_{\mathbb{F}} ( 0,T ; \mathbb{L}^{2} ( \Omega; \mathbb{R} ) )$.
Applying \Cref{lem: estimate for gap} to ${X}_{T} = {X}^{ \bar{\pi } }_{T}$ and 
$\chi = \xi \int_{t}^{ t + \varepsilon } \exp ( \int_{s}^{T} {r}_{v} dv ) {\sigma }_{s} ( d {W}_{s} + {\vartheta }_{s} ds ) = \bar{X}^{\varepsilon }_{T} - {X}^{ \bar{\pi } }_{T}$,
where $\bar{X}^{\varepsilon } := {X}^{ \bar{\pi }^{ t, \varepsilon, \xi } }$ for short, yields
\begin{equation*}
    | \lambda ( \mathbb{P}^{t}_{ \bar{X}^{\varepsilon }_{T}, \zeta } ) - \lambda ( \mathbb{P}^{t}_{ {X}^{ \bar{\pi } }_{T}, \zeta } ) | 
\le \frac{ | \mathbb{E}_{t} [ \chi {1}_{ {R}_{0} } ] | }{ \mathbb{E}_{t} [ {1}_{ {R}_{0} } ] }
  + \bigg| \frac{ \mathbb{E}_{t} [ \chi {1}_{ {R}_{0} } ] }{ \mathbb{E}_{t} [ {1}_{ {R}_{0} } ] } - \frac{ \mathbb{E}_{t} [ \chi {1}_{ {R}_{1} } ] }{ \mathbb{E}_{t} [ {1}_{ {R}_{1} } ] } \bigg|.
\end{equation*}
As $\varepsilon \downarrow 0$, we have $\chi \to 0$, $\mathbb{P}$-a.s., and hence, ${1}_{ {R}_{1} } \to {1}_{ {R}_{0} }$, $\mathbb{P}$-a.s.
By dominated convergence theorem, $\mathbb{E}_{t} [ {1}_{ {R}_{1} } ] \to \mathbb{E}_{t} [ {1}_{ {R}_{0} } ]$, $\mathbb{P}$-a.s.
Consequently, by Cauchy-Schwarz inequality, 
\begin{equation*}
\bigg| \frac{ \mathbb{E}_{t} [ \chi {1}_{ {R}_{0} } ] }{ \mathbb{E}_{t} [ {1}_{ {R}_{0} } ] } - \frac{ \mathbb{E}_{t} [ \chi {1}_{ {R}_{1} } ] }{ \mathbb{E}_{t} [ {1}_{ {R}_{1} } ] } \bigg|^{2}
\le \frac{ \mathbb{E}_{t} [ {\chi }^{2} ] }{ | \mathbb{E}_{t} [ {1}_{ {R}_{0} } ] \mathbb{E}_{t} [ {1}_{ {R}_{1} } ] |^{2} } 
    \mathbb{E}_{t} \big[ | {1}_{ {R}_{0} } \mathbb{E}_{t} [ {1}_{ {R}_{1} } ] - {1}_{ {R}_{1} } \mathbb{E}_{t} [ {1}_{ {R}_{0} } ] |^{2} \big]
  = o ( \varepsilon ).
\end{equation*}
Since ${R}_{0}$ is independent of $( \varepsilon, \xi )$, mirroring the proof of \cite[Lemma 4.1]{Wang-Liu-Bensoussan-Yiu-Wei-2025}, one can obtain $| \mathbb{E}_{t} [ \chi {1}_{ {R}_{0} } ] |^{2} = o ( \varepsilon )$.
Therefore, $| \lambda ( \mathbb{P}^{t}_{ \bar{X}^{\varepsilon }_{T}, \zeta } ) - \lambda ( \mathbb{P}^{t}_{ {X}^{ \bar{\pi } }_{T}, \zeta } ) |^{2} = o ( \varepsilon )$.
Furthermore, from \Cref{lem: boundedness of gap}, together with applying Taylor expansion to $\nabla g ( p, \cdot, z )$ 
that is continuously differentiable on $\mathbb{R}$ and twice continuously differentiable on $( - \infty, \lambda (p) - z / \theta )$ and on $( \lambda (p) - z / \theta, + \infty )$, 
we obtain
\begin{align*}
    g ( \mathbb{P}^{t}_{ \bar{X}^{\varepsilon }_{T}, \zeta } ) - g ( \mathbb{P}^{t}_{ {X}^{ \bar{\pi } }_{T}, \zeta } )
& = \int_{ \mathbb{R} \times \mathbb{R} } \nabla g ( \mathbb{P}^{t}_{ {X}^{ \bar{\pi } }_{T}, \zeta }, x,z ) 
                                          \big( \mathbb{P}^{t}_{ \bar{X}^{\varepsilon }_{T}, \zeta } ( dx, dz ) - \mathbb{P}^{t}_{ {X}^{ \bar{\pi } }_{T}, \zeta } ( dx, dz ) \big) + o ( {\varepsilon } ) \\
& = \mathbb{E}_{t} [ \nabla g ( \mathbb{P}^{t}_{ {X}^{ \bar{\pi } }_{T}, \zeta }, \bar{X}^{\varepsilon }_{T}, \zeta ) - \nabla g ( \mathbb{P}^{t}_{ {X}^{ \bar{\pi } }_{T}, \zeta }, {X}^{ \bar{\pi } }_{T}, \zeta ) ] 
  + o ( \varepsilon ) \\
& = \mathbb{E}_{t} \bigg[ \bigg( \zeta + \theta \Big( \lambda ( \mathbb{P}^{t}_{ {X}^{ \bar{\pi } }_{T}, \zeta } ) - {X}^{ \bar{\pi } }_{T} - \frac{\zeta }{\theta } \Big)_{+} \bigg) 
                          ( \bar{X}^{\varepsilon }_{T} - {X}^{ \bar{\pi } }_{T} ) \bigg] \\
& \quad 
  - \mathbb{E}_{t} \bigg[ \theta ( \bar{X}^{\varepsilon }_{T} - {X}^{ \bar{\pi } }_{T} )^{2} 
                          \int_{0}^{1} \rho {1}_{\{ \rho {X}^{ \bar{\pi } }_{T} + ( 1 - \rho ) \bar{X}^{\varepsilon }_{T} + \frac{\zeta }{\theta } \le \lambda ( \mathbb{P}^{t}_{ {X}^{ \bar{\pi } }_{T}, \zeta } ) \}} d \rho \bigg]
  + o ( \varepsilon ) \\
& = \xi \mathbb{E}_{t} \bigg[ {Y}^{t}_{T} \int_{t}^{ t + \varepsilon } {e}^{ \int_{s}^{T} {r}_{v} dv } {\sigma }_{s} ( d {W}_{s} + {\vartheta }_{s} ds ) \bigg] \\
& \quad
  - \frac{\theta }{2} {\xi }^{2} \mathbb{E}_{t} \bigg[ \bigg( \int_{t}^{ t + \varepsilon } {e}^{ \int_{s}^{T} {r}_{v} dv } {\sigma }_{s} d {W}_{s} \bigg)^{2} 
                                                       {1}_{\{ {X}^{ \bar{\pi } }_{T} + \frac{\zeta }{\theta } \le \lambda ( \mathbb{P}^{t}_{ {X}^{ \bar{\pi } }_{T}, \zeta } ) \}} \bigg]
  + o ( \varepsilon ),
\end{align*}
where the last equality arises from the following estimate due to Burkholder inequality:
\begin{align*}
    \mathbb{E}_{t} [ | \bar{X}^{\varepsilon }_{T} - {X}^{ \bar{\pi } }_{T} |^{2k} ]
& \le {2}^{2k-1} {\xi }^{2k} {e}^{ 2 k T \mathop{esssup}\limits_{ [ 0,T ] \times \Omega } |r| }
      \mathbb{E}_{t} \bigg[ \Big| \int_{t}^{ t + \varepsilon } {e}^{ - \int_{t}^{s} {r}_{v} dv } {\sigma }_{s} d {W}_{s} \Big|^{2k} \bigg] \\
& \quad + {2}^{2k-1} {\xi }^{2k} \mathbb{E}_{t} \bigg[ \Big| \int_{t}^{ t + \varepsilon } {e}^{ \int_{s}^{T} {r}_{v} dv } {\sigma }_{s} {\vartheta }_{s} ds \Big|^{2k} \bigg] \\
& \le {2}^{2k-1} {\xi }^{2k} {e}^{ 2 k T \mathop{esssup}\limits_{ [ 0,T ] \times \Omega } |r| } \frac{ {2}^{ 2 {k}^{2} } {k}^{ 2 {k}^{2} + k } }{ (2k-1)^{ 2 {k}^{2} - k } }
      \mathbb{E}_{t} \bigg[ \Big| \int_{t}^{ t + \varepsilon } {e}^{ - 2 \int_{t}^{s} {r}_{v} dv } | {\sigma }_{s} |^{2} ds \Big|^{k} \bigg] \\
& \quad + {2}^{2k-1} {\xi }^{2k} \mathbb{E}_{t} \bigg[ \Big| \int_{t}^{ t + \varepsilon } {e}^{ \int_{s}^{T} {r}_{v} dv } {\sigma }_{s} {\vartheta }_{s} ds \Big|^{2k} \bigg] \\
& \le {2}^{2k-1} {\xi }^{2k} {e}^{ 2 k T \mathop{esssup}\limits_{ [ 0,T ] \times \Omega } |r| } \bigg( \mathop{esssup}_{ [ 0,T ] \times \Omega } | \sigma | \bigg)^{k} \\
& \quad \times \Bigg( \frac{ {2}^{ 2 {k}^{2} } {k}^{ 2 {k}^{2} + k } }{ (2k-1)^{ 2 {k}^{2} - k } } {e}^{ 2 k T \mathop{esssup}\limits_{ [ 0,T ] \times \Omega } |r| } 
                    + \bigg( \mathop{esssup}_{ [ 0,T ] \times \Omega } | \vartheta | \bigg)^{k} {\varepsilon }^{k} \Bigg) {\varepsilon }^{k},
\quad \forall k \ge 1.
\end{align*}
By It\^o's rule with using \cref{eq: BSDE :eq}, 
\begin{align}
  g ( \mathbb{P}^{t}_{ \bar{X}^{\varepsilon }_{T}, \zeta } ) - g ( \mathbb{P}^{t}_{ {X}^{ \bar{\pi } }_{T}, \zeta } )
& = \xi \int_{t}^{ t + \varepsilon } \mathbb{E}_{t} [ ( {Y}^{t}_{s} {\vartheta }_{s} + \mathcal{Y}^{t}_{s} ) {\sigma }_{s} ] ds \nonumber \\
& \quad 
  - \frac{\theta }{2} {\xi }^{2} \mathbb{E}_{t} \bigg[ \bigg( \int_{t}^{ t + \varepsilon } {e}^{ \int_{s}^{T} {r}_{v} dv } {\sigma }_{s} d {W}_{s} \bigg)^{2} 
                                                       {1}_{\{ {X}^{ \bar{\pi } }_{T} + \frac{\zeta }{\theta } \le \lambda ( \mathbb{P}^{t}_{ {X}^{ \bar{\pi } }_{T}, \zeta } ) \}} \bigg] 
  + o ( \varepsilon ).
\label{eq: gap for open-loop spike deviation :eq}
\end{align}
In view of the arbitrariness of $\xi $, $\limsup_{ \varepsilon \downarrow 0 } ( g ( \mathbb{P}^{t}_{ \bar{X}^{\varepsilon }_{T}, \zeta } ) - g ( \mathbb{P}^{t}_{ {X}^{ \bar{\pi } }_{T}, \zeta } ) ) / \varepsilon \le 0$ if and only if
\cref{eq: equilibrium condition for ONEC :eq} holds.

It is clear that the first claim for the sufficient conditions follows from
\begin{equation*}
\limsup_{ \varepsilon \downarrow 0 } \frac{1}{\varepsilon } \big( g ( \mathbb{P}^{t}_{ \bar{X}^{\varepsilon }_{T}, \zeta } ) - g ( \mathbb{P}^{t}_{ {X}^{ \bar{\pi } }_{T}, \zeta } ) \big) 
\le \xi \lim_{ \varepsilon \downarrow 0 } \frac{1}{\varepsilon } \int_{t}^{ t + \varepsilon } \mathbb{E}_{t} [ ( {Y}^{t}_{s} {\vartheta }_{s} + \mathcal{Y}^{t}_{s} ) {\sigma }_{s} ] ds = 0.
\end{equation*}
When $\mathcal{Y}^{t}$ is right-continuous, the second claim for the sufficient conditions follows from 
\begin{align*}
      \limsup_{ \varepsilon \downarrow 0 } \frac{1}{\varepsilon } \big( g ( \mathbb{P}^{t}_{ \bar{X}^{\varepsilon }_{T}, \zeta } ) - g ( \mathbb{P}^{t}_{ {X}^{ \bar{\pi } }_{T}, \zeta } ) \big)
& \le \limsup_{ \varepsilon \downarrow 0 } \mathbb{E}_{t} \bigg[ \frac{1}{\varepsilon } \int_{t}^{ t + \varepsilon } | \xi ( {Y}^{t}_{s} {\vartheta }_{s} + \mathcal{Y}^{t}_{s} ) {\sigma }_{s} | ds \bigg] \\
& \le \mathbb{E}_{t} [ | \xi ( {Y}^{t}_{t} {\vartheta }_{t} + \mathcal{Y}^{t}_{t} ) {\sigma }_{t} |] = 0.
\end{align*}

\subsection{Proof of \Cref{thm: path-independent ONEC}}
\label{pf-thm: path-independent ONEC}

Instead of applying Picard's theorem to prove the existence and uniqueness of solution for \cref{eq: beta equation :eq}, we adopt a more detailed and insightful approach. 
This method not only provides additional information about $\beta_t$, but also demonstrates an alternative way -- the Picard iteration algorithm -- that can be utilized for numerical simulations.

At first, we show the existence of solution for \cref{eq: beta equation :eq}, or equivalently, for
\begin{equation}
\int_{ - \infty }^{ Q ( \frac{1}{ {\beta }_{t} } ) } \Phi (x) dx = \frac{ 1 - \zeta }{ ( \int_{t}^{T} | {\beta }_{s} {\vartheta }_{s} |^{2} ds )^{ \frac{1}{2} } }.
\label{eq: beta equation for proof :eq}
\end{equation}
where $Q (p) := \inf \{ x: \Phi (x) \ge p \}$ is the quantile function of standard normal distribution.
Let us investigate the following Picard iteration:
\begin{equation*}
\frac{ 1 - \zeta }{ ( \int_{t}^{T} | {\beta }^{(n)}_{s} {\vartheta }_{s} |^{2} ds )^{ \frac{1}{2} } } = \int_{ - \infty }^{ Q ( \frac{1}{ {\beta }^{(n+1)}_{t} } ) } \Phi (x) dx,
\quad {\beta }^{(0)} \equiv 1,
\end{equation*}
which implies that each of $\{ {\beta }^{(n)} \}_{ n \in \mathbb{N}_{+} }$ is continuous and strictly decreasing with ${\beta }^{(n)}_{T-} = 1$.
Notably, it is more convenient for numerical computations to use the following identity: 
\begin{equation*}
  \int_{ - \infty }^{q} \Phi (x) dx
= \int_{ - \infty }^{q} dx \int_{ - \infty }^{x} \Phi' (z) dz
= \int_{ - \infty }^{q} (q-z) \Phi' (z) dz 
= q \Phi (q) + \Phi' (q), \quad \forall q \in \mathbb{R}.
\end{equation*}
Denote ${\Theta }_{t} := ( 1 - \zeta ) / ( \int_{t}^{T} | {\vartheta }_{s} |^{2} ds )^{1/2}$, 
so that $( 1 - \zeta ) ( \int_{t}^{T} | {\beta }^{(n)}_{s} {\vartheta }_{s} |^{2} ds )^{-1/2} \in [ {\Theta }_{t} / {\beta }^{(n)}_{t}, {\Theta }_{t} ]$.
For the auxiliary function ${g}_{t} (z) := \int_{ - \infty }^{Q(z)} \Phi (x) dx - {\Theta }_{t} z$,
since ${g}_{t}' ( \Phi (x) ) = \Phi (x) / \Phi'(x) - {\Theta }_{t}$ is strictly increasing with a unique zero, together with ${g}_{t} (0+) = 0$ and ${g}_{t} (1-) = + \infty $,
we conclude that ${g}_{t} (z)$ has a unique zero (denoted by ${m}_{t}$), which is also the unique zero of $Q(z) - \Psi ( {\Theta }_{t} z )$ and is increasing in $t$.
As a result, ${g}_{t} (x) \ge 0$ if and only if $x \ge {m}_{t}$.
On the one hand, if $1 / {\beta }^{(n)}_{t} \ge {m}_{t}$, then \cref{eq: beta equation for proof :eq} gives
\begin{equation*}
  \int_{ - \infty }^{ Q ( \frac{1}{ {\beta }^{(n+1)}_{t} } ) } \Phi (x) dx 
\ge \frac{ 1 - \zeta }{ ( \int_{t}^{T} | {\beta }^{(n)}_{t} {\vartheta }_{s} |^{2} ds )^{ \frac{1}{2} } } 
\ge \frac{ {\Theta }_{t} }{ {\beta }^{(n)}_{t} }
\ge {\Theta }_{t} {m}_{t}
= \int_{ - \infty }^{ Q ( {m}_{t} ) } \Phi (x) dx,
\end{equation*}
and hence $1 / {\beta }^{(n+1)}_{t} \ge {m}_{t}$.
As $1 / {\beta }^{(0)}_{t} = 1 > {m}_{t}$, by induction we obtain $1 / {\beta }^{(n)}_{t} \ge {m}_{t}$ for every $n$.
On the other hand, if ${\beta }^{(n)}_{t} \ge {\beta }^{(n-1)}_{t}$ for all $t \in [ 0,T ]$, then \cref{eq: beta equation for proof :eq} gives
\begin{equation*}
  \int_{ Q ( \frac{1}{ {\beta }^{(n)}_{t} } ) }^{ Q ( \frac{1}{ {\beta }^{(n+1)}_{t} } ) } \Phi (x) dx 
= \frac{ 1 - \zeta }{ ( \int_{t}^{T} | {\beta }^{(n)}_{s} {\vartheta }_{s} |^{2} ds )^{ \frac{1}{2} } } 
- \frac{ 1 - \zeta }{ ( \int_{t}^{T} | {\beta }^{(n-1)}_{s} {\vartheta }_{s} |^{2} ds )^{ \frac{1}{2} } }
\le 0,
\end{equation*}
and hence ${\beta }^{(n+1)}_{t} \ge {\beta }^{(n)}_{t}$ for all $t \in [ 0,T ]$.
As ${\beta }^{(1)}_{t} \ge 1 = {\beta }^{(0)}_{t}$, by induction we obtain $\{ {\beta }^{(n)}_{t} \}_{n}$ is an increasing sequence.
Due to monotone convergence theorem, ${\beta }^{(\infty )}_{t}$ must exist.
Furthermore, differentiating the both side of \cref{eq: beta equation for proof :eq} w.r.t. $t$, with rearranging the terms, yields
\begin{equation*}
  \bigg| \frac{ d {\beta }^{(n+1)}_{t} }{dt} \bigg|
= \frac{ ( 1 - \zeta ) | {\beta }^{(n)}_{t} {\vartheta }_{t} |^{2} | {\beta }^{(n+1)}_{t} |^{3} }{ 2 ( \int_{t}^{T} | {\beta }^{(n)}_{s} {\vartheta }_{s} |^{2} ds )^{ \frac{3}{2} } } \Phi' \bigg( Q \Big( \frac{1}{ {\beta }^{(n+1)}_{t} } \Big) \bigg)
\le \frac{ | {\Theta }_{0} |^{3} }{ 2 ( 1 - \zeta )^{2} | {m}_{0} |^{5} } \bigg( \max_{ t \in [ 0,T ] } | {\vartheta }_{t} |^{2} \bigg) =: M.
\end{equation*}
For an arbitrarily fixed $\varepsilon > 0$ and $\tau \in [ 0,T ]$, 
there exists a sufficiently large ${N}_{ \varepsilon, \tau } \in \mathbb{N}_{+}$ such that $| {\beta }^{(m)}_{\tau } - {\beta }^{(n)}_{\tau } | < \varepsilon / 2$ for all $m > n > {N}_{ \varepsilon, \tau }$.
Consequently, if $| t - \tau | < \varepsilon / ( 4M )$, then
\begin{equation*}
    | {\beta }^{(m)}_{t} - {\beta }^{(n)}_{t} | 
\le \bigg| \int_{\tau }^{t} d ( {\beta }^{(m)}_{s} - {\beta }^{(n)}_{s} ) \bigg| + | {\beta }^{(m)}_{\tau } - {\beta }^{(n)}_{\tau } |
\le 2M | t - \tau | + \frac{\varepsilon }{2} < \varepsilon.
\end{equation*}
By Heine-Borel theorem, there exists a finite set $\{ {\tau }_{k} \}_{k=1,2,\ldots,K}$ such that $\cup_{k=1}^{K} ( {\tau }_{k} - \varepsilon / ( 4M ), {\tau }_{k} + \varepsilon / ( 4M ) ) \supseteq [ 0,T ]$.
Therefore, $| {\beta }^{(m)}_{t} - {\beta }^{(n)}_{t} | < \varepsilon $ for $m > n \ge \max_{k} {N}_{ \varepsilon, {\tau }_{k} }$ and $t \in [ 0,T ]$.
This implies that ${\beta }^{(n)} \rightrightarrows {\beta }^{(\infty )}$ as $n \to \infty $, so that ${\beta }^{(\infty )}$ is continuous and fulfills \cref{eq: beta equation :eq}, and hence the existence of $\beta $ follows.

As a solution of \cref{eq: beta equation :eq}, $\beta $ must be continuously differentiable due to the smoothness of $\Phi \circ \Psi $.
In particular, sending $t$ to $T$ in \cref{eq: beta equation :eq} immediately provides ${\beta }_{T-} = 1$.
And then, differentiating the both sides of \cref{eq: beta equation :eq} w.r.t. $t$, with rearranging the terms, yields
\begin{equation*}
  {\beta }_{t}' 
= - \frac{ | {\beta }_{t} |^{5} | {\vartheta }_{t} |^{2} | {y}_{t} |^{3} }{ 2 ( 1 - \zeta )^{2} } \Phi' \big( \Psi ( {y}_{t} ) \big) < 0, \qquad
  {\beta }_{T-}' 
= - \frac{ | {\vartheta }_{T} |^{2} }{ 2 ( 1 - \zeta )^{2} }
      \bigg( \lim_{ z \to + \infty } \frac{ \int_{ - \infty }^{z} \Phi (y) dy }{ | \Phi' (z) |^{ - \frac{1}{3} } } \bigg)^{3} = 0,
\end{equation*}
where ${y}_{t} := ( 1 - \zeta ) ( \int_{t}^{T} | {\beta }_{s} {\vartheta }_{s} |^{2} ds )^{-1/2}$ for ease of expression.
Thus, $\beta $ is strictly decreasing.

Now we show the uniqueness of solution for \cref{eq: beta equation :eq}. 
Suppose that $\beta $ and ${\beta }^{*}$ are two solutions of \cref{eq: beta equation :eq}.
By Weierstrass Theorem, $\max_{ t \in [ 0,T ] } {\beta }_{t} \vee {\beta }^{*}_{t} \le {M}_{*}$ for some ${M}_{*} > 1$. 
Consequently, for any $t \in [ 0,T )$ with some sufficiently large constant $K$, 
\begin{align*}
      | {\beta }_{t} - {\beta }^{*}_{t} |
&   = {\beta }_{t} {\beta }^{*}_{t}
      \bigg| \int_{ ( 1 - \zeta ) ( \int_{t}^{T} | {\beta }_{s} {\vartheta }_{s} |^{2} ds )^{ - \frac{1}{2} } }^{ ( 1 - \zeta ) ( \int_{t}^{T} | {\beta }^{*}_{s} {\vartheta }_{s} |^{2} ds )^{ - \frac{1}{2} } }
             \Phi' \big( \Psi (z) \big) \Psi' (z) dz \bigg| \\
& \le {M}_{*}^{2} \frac{ \Phi' \big( \Psi ( {M}_{*}^{-1} {\Theta}_{t} ) \big) }{ \Phi \big( \Psi ( {M}_{*}^{-1} {\Theta}_{t} ) \big) }
      \frac{ ( 1 - \zeta ) \int_{t}^{T} | {\vartheta }_{s} |^{2} ( {\beta }_{s} + {\beta }^{*}_{s} ) | {\beta }_{s} - {\beta }^{*}_{s} | ds }
           { ( \int_{t}^{T} | {\beta }_{s} {\vartheta }_{s} |^{2} ds )^{ \frac{1}{2} } + ( \int_{t}^{T} | {\beta }^{*}_{s} {\vartheta }_{s} |^{2} ds )^{ \frac{1}{2} } } \\
& \le {M}_{*}^{3} \frac{ \Phi' \big( \Psi ( {M}_{*}^{-1} {\Theta}_{t} ) \big) }{ \Phi \big( \Psi ( {M}_{*}^{-1} {\Theta}_{t} ) \big) } {\Theta }_{t} 
      \bigg( \max_{ t \in [ 0,T ] } | {\vartheta }_{t} |^{2} \bigg) \int_{t}^{T} | {\beta }_{s} - {\beta }^{*}_{s} | ds \\
& \le K \int_{t}^{T} | {\beta }_{s} - {\beta }^{*}_{s} | ds,
\end{align*}
where the last inequality is due to the uniform boundedness of $\Phi'(x) \int_{-\infty }^{x} \Phi (z) dz$ on $x \in \mathbb{R}$.
Therefore, by Gr\"onwall's inequality, $| {\beta }_{t} - {\beta }^{*}_{t} | \le 0$, and hence $| {\beta }_{t} - {\beta }^{*}_{t} | = 0$.

To show that ${\beta }_{t}$ is strictly increasing in $\zeta $ for every $t$, 
we differentiate the both sides of \cref{eq: beta equation for proof :eq} w.r.t. $\zeta $, with a slight abuse of notation and rearrangement, to arrive at
\begin{equation*}
  \frac{\partial {\beta }_{t} }{\partial \zeta }
= \frac{ {y}_{t} | {\beta }_{t} |^{3} }{ 1 - \zeta } \Phi' \bigg( Q \Big( \frac{1}{ {\beta }_{t} } \Big) \bigg)
  \bigg( 1 + \frac{ | {y}_{t} |^{2} }{ 1 - \zeta } \int_{t}^{T} | {\vartheta }_{s} |^{2} {\beta }_{s} \frac{\partial {\beta }_{s} }{\partial \zeta } ds \bigg).
\end{equation*}
By inverse Gr\"onwall inequality, 
\begin{equation*}
\frac{\partial {\beta }_{t} }{\partial \zeta } \ge \frac{ {y}_{t} | {\beta }_{t} |^{3} }{ 1 - \zeta } \Phi' \bigg( Q \Big( \frac{1}{ {\beta }_{t} } \Big) \bigg) > 0, \quad \forall t \in [ 0,T ).
\end{equation*}

Finally, we show that \cref{eq: ONEC :eq} gives an ONEC.
As $( r, \sigma, \vartheta, \zeta )$ are deterministic, the BSDE \cref{eq: BSDE :eq} with the identity \cref{eq: lambda functional :eq} gives
\begin{equation*}
  {e}^{ - \int_{s}^{T} {r}_{v} dv } {Y}^{t}_{s} 
= \zeta + \theta \mathbb{E}_{s} \Big[ \Big( \lambda ( \mathbb{P}^{t}_{ {X}^{ \bar{\pi } }_{T}, \zeta } ) - {X}^{ \bar{\pi } }_{T} - \frac{\zeta }{\theta } \Big)_{+} \Big]
= 1 + \int_{t}^{s} {e}^{ - \int_{u}^{T} {r}_{v} dv } \mathcal{Y}^{t}_{u} d {W}_{u};
\end{equation*}
see also \Cref{rem: corollary of verification theorem}.
Corresponding to $\bar{\pi }$ given by \cref{eq: ONEC :eq}, 
\begin{equation*}
{X}^{ \bar{\pi } }_{T} = {X}^{ \bar{\pi } }_{t} {e}^{ \int_{t}^{T} {r}_{v} dv } + \frac{1}{\theta } \int_{t}^{T} {\beta }_{s} | {\vartheta }_{s} |^{2} ds + \frac{1}{\theta } \int_{t}^{T} {\beta }_{s} {\vartheta }_{s} d {W}_{s}.
\end{equation*}
Thus, ${X}^{ \bar{\pi } }_{T}$ is normally distributed with mean ${\mu }_{t} := {X}^{ \bar{\pi } }_{t} \exp ( \int_{t}^{T} {r}_{v} dv ) + {\theta }^{-1} \int_{t}^{T} {\beta }_{s} | {\vartheta }_{s} |^{2} ds$
and standard deviation ${S}_{t} := {\theta }^{-1} ( \int_{t}^{T} | {\beta }_{s} {\vartheta }_{s} |^{2} ds )^{1/2}$ conditioned on $\mathcal{F}_{t}$.
Notably, \Cref{rem: corollary of verification theorem} implies that ${S}_{t} > 0$; 
otherwise, the pair $( {X}^{ \bar{\pi } }_{T}, \zeta )$ makes ${X}^{ \bar{\pi } }_{T} + \zeta / \theta \le \lambda ( \mathbb{P}^{t}_{ {X}^{ \bar{\pi } }_{T}, \zeta } )$ and results in a contradiction.
Since
\begin{equation*}
  \frac{ 1 - \zeta }{\theta } 
= \mathbb{E}_{t} \Big[ \Big( \lambda ( \mathbb{P}^{t}_{ {X}^{ \bar{\pi } }_{T}, \zeta } ) - {X}^{\pi }_{T} - \frac{\zeta }{\theta } \Big)_{+} \Big]
= {S}_{t} \int_{ - \infty }^{ \frac{1}{ {S}_{t} } \big( \lambda ( \mathbb{P}^{t}_{ {X}^{ \bar{\pi } }_{T}, \zeta } ) - \frac{\zeta }{\theta } - {\mu }_{t} \big) } \Phi (z) dz,
\end{equation*}
we have $\lambda ( \mathbb{P}^{t}_{ {X}^{ \bar{\pi } }_{T}, \zeta } ) = \zeta / \theta + {\mu }_{t} + \Psi ( ( 1 - \zeta ) / ( \theta {S}_{t} ) ) {S}_{t}$.
Consequently, by straightforward calculation,
\begin{equation*}
  {e}^{ - \int_{s}^{T} {r}_{v} dv } {Y}^{t}_{s} 
= \zeta + \theta \mathbb{E}_{s} \Big[ \Big( \lambda ( \mathbb{P}^{t}_{ {X}^{ \bar{\pi } }_{T}, \zeta } ) - {X}^{ \bar{\pi } }_{T} - \frac{\zeta }{\theta } \Big)_{+} \Big]
= \zeta + \theta {S}_{s} \int_{ - \infty }^{ \frac{1}{ {S}_{s} } \big( \lambda ( \mathbb{P}^{t}_{ {X}^{ \bar{\pi } }_{T}, \zeta } ) - \frac{\zeta }{\theta } - {\mu }_{s} \big) } \Phi (z) dz,
\end{equation*}
which by It\^o's rule and the chain rule gives
\begin{equation*}
{e}^{ - \int_{s}^{T} {r}_{v} dv } \mathcal{Y}^{t}_{s} = - \Phi \Big( \frac{1}{ {S}_{s} } \big( \lambda ( \mathbb{P}^{t}_{ {X}^{ \bar{\pi } }_{T}, \zeta } ) - \frac{\zeta }{\theta } - {\mu }_{s} \big) \Big) {\beta }_{s} {\vartheta }_{s}.
\end{equation*}
Since \cref{eq: beta equation :eq} implies that $\beta $ is continuous, $\mathcal{Y}^{t}$ has continuous sample path.
As
\begin{equation*}
  {e}^{ - \int_{t}^{T} {r}_{v} dv } ( {Y}^{t}_{t} {\vartheta }_{t} + \mathcal{Y}^{t}_{t} ) 
= {\vartheta }_{t} - \Phi \circ \Psi \Big( \frac{ 1 - \zeta }{ \theta {S}_{t} } \Big) {\beta }_{t} {\vartheta }_{t}
= 0,
\end{equation*}
\cref{eq: ONEC :eq} gives an ONEC according to the last claim in \Cref{thm: verification theorem for ONEC}.

\subsection{Proof of \Cref{thm: verification theorem for CNEC}}
\label{pf-thm: verification theorem for CNEC}

Applying the It\^o-Kunita-Ventzel formula (see \cite[Theorem 1.5.3.2]{Jeanblanc-Yor-Chesney-2009}) to $\{ \mathcal{V} ( s, {X}^{ t,x, \Pi }_{s}, \lambda ) \}_{ s \in [ t,T ] }$
with the semi-martingale decomposition of $\mathcal{V} ( \cdot, x, \lambda )$ given by \cref{eq: BSPDE :eq}, yields
\begin{equation*}
d \mathcal{V} ( s, {X}^{ t,x, \Pi }_{s}, \lambda ) = \big( \psi ( s, {X}^{ t,x, \Pi }_{s}, \lambda ) + \mathcal{V}_{x} ( s, {X}^{ t,x, \Pi }_{s}, \lambda ) \bar{\Pi } ( s, {X}^{ t,x, \Pi }_{s} ) {\sigma }_{s} \big) d {W}_{s},
\end{equation*}
which implies that $\mathcal{V} ( t,x, \lambda ) = \mathbb{E}_{t} [ \mathcal{V} ( T, {X}^{ t,x, \Pi }_{T}, \lambda ) ] = \tilde{J} ( t,x, \bar{\Pi }, \lambda )$.
In the same manner, 
\begin{equation*}
\mathcal{M} ( t,x, \lambda ) = \mathbb{E}_{t} [ \mathcal{M} ( T, {X}^{ t,x, \bar{\Pi } }_{T}, \lambda ) ] = \mathbb{E}_{t} \Big[ \zeta + \theta \Big( \lambda - {X}^{ t,x, \bar{\Pi } }_{T} - \frac{\zeta }{\theta } \Big)_{+} \Big],
\end{equation*}
and hence $\Lambda ( t,x ) = \lambda ( \mathbb{P}^{t}_{ {X}^{ t,x, \bar{\Pi } }_{T}, \zeta } )$.
Next, we proceed with the perturbation argument for an arbitrarily fixed $( t,x )$.
By applying iterated conditioning to \cref{eq: extended preference with closed-loop control :eq}, with ${X}^{ t,x, \bar{\Pi }^{ t, \varepsilon, \xi } }_{T} = {X}^{ t + \varepsilon, {X}^{ t,x, \xi }_{ t + \varepsilon }, \bar{\Pi } }_{T}$, we have
\begin{equation*}
  \bar{J} ( t,x, \bar{\Pi }^{ t, \varepsilon, \xi } ) 
= \tilde{J} ( t, x, \bar{\Pi }^{ t, \varepsilon, \xi }, {\lambda }_{\varepsilon } )
= \mathbb{E}_{t} [ \tilde{J} ( t + \varepsilon, {X}^{ t,x, \xi }_{ t + \varepsilon }, \bar{\Pi }, {\lambda }_{\varepsilon } ) ]
= \mathbb{E}_{t} [ \mathcal{V} ( t + \varepsilon, {X}^{ t,x, \xi }_{ t + \varepsilon }, {\lambda }_{\varepsilon } ) ],
\end{equation*}
where ${\lambda }_{\varepsilon } := \lambda ( \mathbb{P}^{t}_{ {X}^{ t,x, \bar{\Pi }^{ t, \varepsilon, \xi } }_{T}, \zeta } )$.
So it is supposed to make an asymptotic estimation for ${\lambda }_{\varepsilon } - {\lambda }_{0}$.
By iterated conditioning,
\begin{equation*}
  \mathbb{E}_{t} [ \mathcal{M} ( t + \varepsilon, {X}^{ t,x, \xi }_{ t + \varepsilon }, {\lambda }_{\varepsilon } ) ]
= \mathbb{E}_{t} \Big[ \zeta + \theta \Big( {\lambda }_{\varepsilon } - {X}^{ t,x, \bar{\Pi }^{ t, \varepsilon, \xi } }_{T} - \frac{\zeta }{\theta } \Big)_{+} \Big] 
= 1
= \mathcal{M} ( t,x, {\lambda }_{0} ),
\end{equation*}
which implies that ${\lambda }_{\varepsilon } \to {\lambda }_{0}$ as $\varepsilon \downarrow 0$.
Furthermore, by It\^o-Kunita-Ventzel formula,
\begin{align*}
&   \mathcal{M} ( t,x, {\lambda }_{0} ) - \mathcal{M} ( t,x, {\lambda }_{\varepsilon } ) \\
& = \mathbb{E}_{t} [ \mathcal{M} ( t + \varepsilon, {X}^{ t,x, \xi }_{ t + \varepsilon }, {\lambda }_{\varepsilon } ) - \mathcal{M} ( t,x, {\lambda }_{\varepsilon } ) ] \\
& = \mathbb{E}_{t} \bigg[ \int_{t}^{ t + \varepsilon } \bigg( \frac{1}{2} \mathcal{M}_{xx} ( s, {X}^{ t,x, \xi }_{s}, {\lambda }_{\varepsilon } ) \big( {\xi }^{2} - | \bar{\Pi } ( s, {X}^{ t,x, \xi }_{s} ) |^{2} \big) | {\sigma }_{s} |^{2} \\
& \qquad \qquad \qquad                                      + \big( \mathcal{M}_{x} ( s, {X}^{ t,x, \xi }_{s}, {\lambda }_{s} ) {\vartheta }_{s} + {\phi }_{x} ( s, {X}^{ t,x, \xi }_{s}, {\lambda }_{\varepsilon } ) \big) 
                                                              \big( \xi - \bar{\Pi } ( s, {X}^{ t,x, \xi }_{s} ) \big) {\sigma }_{s} \bigg) ds \bigg] \\
& = \bigg( \frac{1}{2} \mathcal{M}_{xx} ( t,x, {\lambda }_{0} ) \big( {\xi }^{2} - | \bar{\Pi } ( t,x ) |^{2} \big) | {\sigma }_{t} |^{2} \\
& \qquad + \big( \mathcal{M}_{x} ( t,x, {\lambda }_{0} ) {\vartheta }_{t} + {\phi }_{x} ( t,x, {\lambda }_{0} ) \big) 
           \big( \xi - \bar{\Pi } ( t,x ) \big) {\sigma }_{t} \bigg) \varepsilon + o ( \varepsilon ).
\end{align*}
Notably, due to the convexity of $\mathcal{M} ( t,x, \cdot )$,
\begin{align*}
    ( {\lambda }_{\varepsilon } - {\lambda }_{0} ) \int_{\{ y + z / \theta < {\lambda }_{0} \}} \mathbb{P}^{t}_{ {X}^{ t,x, \bar{\Pi } }_{T}, \zeta } ( dy, dz )
& \le \mathcal{M} ( t,x, {\lambda }_{\varepsilon } ) - \mathcal{M} ( t,x, {\lambda }_{0} ) \\
& \le ( {\lambda }_{\varepsilon } - {\lambda }_{0} ) \int_{\{ y + z / \theta < {\lambda }_{\varepsilon } \}} \mathbb{P}^{t}_{ {X}^{ t,x, \bar{\Pi } }_{T}, \zeta } ( dy, dz ).
\end{align*}
Summing up, we obtain ${\lambda }_{\varepsilon } - {\lambda }_{0} = O ( \varepsilon )$.
Then, by It\^o-Kunita-Ventzel formula and Taylor expansion,
\begin{align*}
&   \bar{J} ( t,x, \bar{\Pi }^{ t, \varepsilon, \xi } ) - \bar{J} ( t,x, \bar{\Pi } ) \\
& = \mathbb{E}_{t} [ \mathcal{V} ( t + \varepsilon, {X}^{ t,x, \xi }_{ t + \varepsilon }, {\lambda }_{\varepsilon } ) ] - \mathcal{V} ( t,x, {\lambda }_{0} ) \\
& = \mathbb{E}_{t} [ \mathcal{V} ( t + \varepsilon, {X}^{ t,x, \xi }_{ t + \varepsilon }, {\lambda }_{\varepsilon } ) - \mathcal{V} ( t,x, {\lambda }_{\varepsilon } ) ] 
  + \big( \mathcal{V} ( t,x, {\lambda }_{\varepsilon } ) - \mathcal{V} ( t,x, {\lambda }_{0} ) \big) \\
& = \mathbb{E}_{t} \bigg[ \int_{t}^{ t + \varepsilon } \bigg( \frac{1}{2} \mathcal{V}_{xx} ( s, {X}^{ t,x, \xi }_{s}, {\lambda }_{\varepsilon } ) \big( | {\xi }^{2} - \bar{\Pi } ( s, {X}^{ t,x, \xi }_{s} ) |^{2} \big) | {\sigma }_{s} |^{2} \\
& \qquad \qquad \qquad                                      + \big( \mathcal{V}_{x} ( s, {X}^{ t,x, \xi }_{s}, {\lambda }_{\varepsilon } ) {\vartheta }_{s} + {\psi }_{x} ( s, {X}^{ t,x, \xi }_{s}, {\lambda }_{\varepsilon } ) \big) 
                                                              \big( \xi - \bar{\Pi } ( s, {X}^{ t,x, \xi }_{s} ) \big) {\sigma }_{s} \bigg) ds \bigg] \\
& \quad + \mathcal{V}_{\lambda } ( t,x, {\lambda }_{0} ) ( {\lambda }_{\varepsilon } - {\lambda }_{0} ) + o ( \varepsilon ) \\
& = \mathbb{E}_{t} \bigg[ \int_{t}^{ t + \varepsilon } \bigg( \frac{1}{2} \mathcal{V}_{xx} ( s, {X}^{ t,x, \xi }_{s}, {\lambda }_{0} ) \big( | {\xi }^{2} - \bar{\Pi } ( s, {X}^{ t,x, \xi }_{s} ) |^{2} \big) | {\sigma }_{s} |^{2} \\
& \qquad \qquad \qquad                                      + \big( \mathcal{V}_{x} ( s, {X}^{ t,x, \xi }_{s}, {\lambda }_{0} ) {\vartheta }_{s} + {\psi }_{x} ( s, {X}^{ t,x, \xi }_{s}, {\lambda }_{0} ) \big) 
                                                              \big( \xi - \bar{\Pi } ( s, {X}^{ t,x, \xi }_{s} ) \big) {\sigma }_{s} \bigg) ds \bigg]
  + o ( \varepsilon ), 
\end{align*}
where the last equality follows from 
\begin{equation*}
\mathcal{V}_{\lambda } ( t,x, {\lambda }_{0} ) = 1 - \mathbb{E}_{t} [ \zeta ] - \theta \mathbb{E}_{t} \Big[ \Big( {\lambda }_{0} - {X}^{ t,x, \bar{\Pi } }_{T} - \frac{\zeta }{\theta } \Big)_{+} \Big] = 0.
\end{equation*}
Therefore, \cref{eq: equilibrium condition for CNEC :eq} gives $\bar{J} ( t,x, \bar{\Pi }^{ t, \varepsilon, \xi } ) - \bar{J} ( t,x, \bar{\Pi } ) \le o ( \varepsilon )$,
and hence $\bar{\Pi }$ is a CNEC.

\subsection{Proof of \Cref{thm: state-independent CNEC}}
\label{pf-thm: state-independent CNEC}

We have shown in \Cref{pf-thm: path-independent ONEC} that corresponding to \cref{eq: CNEC :eq},
\begin{equation*}
{X}^{ t,x, \bar{\Pi } }_{T} = x {e}^{ \int_{t}^{T} {r}_{v} dv } + \frac{1}{\theta } \int_{t}^{T} {\beta }_{s} | {\vartheta }_{s} |^{2} ds + \frac{1}{\theta } \int_{t}^{T} {\beta }_{s} {\vartheta }_{s} d {W}_{s}
\end{equation*}
is normally distributed with mean ${\mu }_{t} = x \exp ( \int_{t}^{T} {r}_{v} dv ) + {\theta }^{-1} \int_{t}^{T} {\beta }_{s} | {\vartheta }_{s} |^{2} ds$
and standard deviation ${S}_{t} = {\theta }^{-1} ( \int_{t}^{T} | {\beta }_{s} {\vartheta }_{s} |^{2} ds )^{1/2}$.
According to \Cref{pf-thm: verification theorem for CNEC}, 
\begin{align*}
    \Lambda ( t,x ) 
& = \lambda ( \mathbb{P}^{t}_{ {X}^{ t,x, \bar{\Pi } }_{T}, \zeta } ) 
  = \frac{\zeta }{\theta } + {\mu }_{t} + \Psi \Big( \frac{ 1 - \zeta }{ \theta {S}_{t} } \Big) {S}_{t}, \\
    \mathcal{V} ( t,x, \lambda )
& = \lambda ( 1 - \zeta )
  - \frac{\theta }{2} \mathbb{E}_{t} \bigg[ \Big| \Big( \lambda - {X}^{ t,x, \bar{\Pi } }_{T} - \frac{\zeta }{\theta } \Big)_{+} \Big|^{2} \bigg]
  + \zeta \mathbb{E}_{t} [ {X}^{ t,x, \bar{\Pi } }_{T} ] + \frac{1}{ 2 \theta } {\zeta }^{2} - \frac{1}{ 2 \theta },
\end{align*}
and hence $\psi \equiv 0$.
In the same manner, $\phi \equiv 0$ follows from
\begin{equation*}
\mathcal{M} ( t,x, \lambda ) = \zeta + \theta \mathbb{E}_{t} \Big[ \Big( \lambda - {X}^{ t,x, \bar{\Pi } }_{T} - \frac{\zeta }{\theta } \Big)_{+} \Big].
\end{equation*}
By the equilibrium condition \cref{eq: equilibrium condition for CNEC :eq}, to verify that \cref{eq: CNEC :eq} provides a CNEC, it suffices to show 
\begin{equation}
  \mathcal{V}_{xx} \big( t,x, \lambda ( \mathbb{P}^{t}_{ {X}^{ t,x, \bar{\Pi } }_{T}, \zeta } ) \big) \frac{ {\beta }_{t} }{\theta } {e}^{ \int_{t}^{T} {r}_{v} dv } 
+ \mathcal{V}_{x} \big( t,x, \lambda ( \mathbb{P}^{t}_{ {X}^{ t,x, \bar{\Pi } }_{T}, \zeta } ) \big) = 0
\label{eq: equilibrium condition for CNEC with deterministic parameters :eq}
\end{equation}
and $\mathcal{V}_{xx} < 0$.
In fact, by straightforward calculation, 
\begin{align*}
  \mathcal{V}_{x} ( t,x, \lambda ) 
& = {e}^{ \int_{t}^{T} {r}_{v} dv } \bigg( \theta \mathbb{E}_{t} \Big[ \Big( \lambda - {X}^{ t,x, \bar{\Pi } }_{T} - \frac{\zeta }{\theta } \Big)_{+} \Big] + \zeta \bigg), \\
  \mathcal{V}_{xx} ( t,x, \lambda ) 
& = - {e}^{ 2 \int_{t}^{T} {r}_{v} dv } \theta \mathbb{P} \Big( \lambda - {X}^{ t,x, \bar{\Pi } }_{T} - \frac{\zeta }{\theta } \ge 0 \Big)
  = - {e}^{ 2 \int_{t}^{T} {r}_{v} dv } \theta \Phi \bigg( \frac{ \lambda - \frac{\zeta }{\theta } - {\mu }_{t} }{ {S}_{t} } \bigg) < 0.
\end{align*}
Plugging $\lambda = \lambda ( \mathbb{P}^{t}_{ {X}^{ t,x, \bar{\Pi } }_{T}, \zeta } ) = \zeta / \theta + {\mu }_{t} + \Psi ( ( 1 - \zeta ) / ( \theta {S}_{t} ) ) {S}_{t}$ into the above results yields
\begin{equation*}
  \mathcal{V}_{x} \big( t,x, \lambda ( \mathbb{P}^{t}_{ {X}^{ t,x, \bar{\Pi } }_{T}, \zeta } ) \big) 
= {e}^{ \int_{t}^{T} {r}_{v} dv }, \quad 
  \mathcal{V}_{xx} \big( t,x, \lambda ( \mathbb{P}^{t}_{ {X}^{ t,x, \bar{\Pi } }_{T}, \zeta } ) \big) 
= - {e}^{ 2 \int_{t}^{T} {r}_{v} dv } \theta \Phi \circ \Psi \Big( \frac{ 1 - \zeta }{ \theta {S}_{t} } \Big).
\end{equation*}
As $\beta $ satisfies \cref{eq: beta equation :eq}, \cref{eq: equilibrium condition for CNEC with deterministic parameters :eq} holds,
and hence $\bar{\Pi }$ given by \cref{eq: CNEC :eq} and \cref{eq: beta equation :eq} is a CENC.

Furthermore, by straightforward calculation with a slight abuse of notation,
for any $\Pi $ given by \cref{eq: CNEC :eq} with any fixed piecewise continuous function $\beta $ and $\lambda ( \mathbb{P}^{t}_{ {X}^{ t,x, \Pi }_{T}, \zeta } ) = \zeta / \theta + {\mu }_{t} + \Psi ( ( 1 - \zeta ) / ( \theta {S}_{t} ) ) {S}_{t}$, we have
\begin{align*}
    \bar{J} ( t,x, \Pi )
& = \mathcal{V} \big( t,x, \lambda ( \mathbb{P}^{t}_{ {X}^{ t,x, \Pi }_{T}, \zeta } ) \big) \\
& = {\mu }_{t} + ( 1 - \zeta ) \Psi \Big( \frac{ 1 - \zeta }{ \theta {S}_{t} } \Big) {S}_{t} \\
& \quad - \frac{\theta }{2} | {S}_{t} |^{2} \mathbb{E} \bigg[ \Big| \Big( \Psi \Big( \frac{ 1 - \zeta }{ \theta {S}_{t} } \Big) - \frac{1}{\theta {S}_{t} } \int_{t}^{T} {\beta }_{s} {\vartheta }_{s} d {W}_{s} \Big)_{+} \Big|^{2} \bigg]
  - \frac{ ( 1 - \zeta )^{2} }{ 2 \theta } \\
& = {\mu }_{t} + ( 1 - \zeta ) \Psi \Big( \frac{ 1 - \zeta }{ \theta {S}_{t} } \Big) {S}_{t} \\
& \quad - \theta | {S}_{t} |^{2} \int_{ - \infty }^{ \Psi ( \frac{ 1 - \zeta }{ \theta {S}_{t} } ) } d \Phi (x) \int_{x}^{ \Psi ( \frac{ 1 - \zeta }{ \theta {S}_{t} } ) } \bigg( \Psi \Big( \frac{ 1 - \zeta }{ \theta {S}_{t} } \Big) - y \bigg) dy
        - \frac{ ( 1 - \zeta )^{2} }{ 2 \theta } \\
& = {\mu }_{t} + ( 1 - \zeta ) \Psi \Big( \frac{ 1 - \zeta }{ \theta {S}_{t} } \Big) {S}_{t}
  - \theta | {S}_{t} |^{2} \int_{ - \infty }^{ \Psi ( \frac{ 1 - \zeta }{ \theta {S}_{t} } ) } \bigg( \Psi \Big( \frac{ 1 - \zeta }{ \theta {S}_{t} } \Big) - y \bigg) \Phi (y) dy
  - \frac{ ( 1 - \zeta )^{2} }{ 2 \theta } \\
& = {\mu }_{t} + \theta | {S}_{t} |^{2} \int_{ - \infty }^{ \Psi ( \frac{ 1 - \zeta }{ \theta {S}_{t} } ) } y \Phi (y) dy - \frac{ ( 1 - \zeta )^{2} }{ 2 \theta } \\
& = {\mu }_{t} + \theta | {S}_{t} |^{2} \int_{0}^{ \frac{ 1 - \zeta }{ \theta {S}_{t} } } \Psi (z) dz - \frac{ ( 1 - \zeta )^{2} }{ 2 \theta },
\end{align*}
where the last line arises from $dz = \Phi \circ \Psi (z) d \Psi (z)$.
As a result, the second claim of \Cref{thm: state-independent CNEC} follows.


\subsection{Proof of \Cref{thm: identical trivial NECs}}
\label{pf-thm: identical trivial NECs}

Mirroring the proof of \Cref{thm: verification theorem for CNEC}, one can obtain that $\bar{\Pi }$ is a CNEC.
To show that $\bar{\pi }$ is a CNEC, we differentiate the both sides of each equation in \cref{eq: BSPDE :eq} w.r.t. $x$, together with $\bar{\Pi } ( t,x ) \equiv \bar{\pi }_{t}$, to arrive at the following BSPDE:
\begin{equation*}
\left\{ \begin{aligned}
  - d \mathcal{V}_{x} ( t,x, \lambda )
& = \bigg( \frac{1}{2} \mathcal{V}_{xxx} ( t,x, \lambda ) | \bar{\pi }_{t} {\sigma }_{t} |^{2} 
         + {\psi }_{xx} ( t,x, \lambda ) \bar{\pi }_{t} {\sigma }_{t} \\
& \qquad + \mathcal{V}_{xx} ( t,x, \lambda ) ( {r}_{t} x + \bar{\pi }_{t} {\sigma }_{t} {\vartheta }_{t} )
         + \mathcal{V}_{x} ( t,x, \lambda ) {r}_{t} \bigg) dt
  - {\psi }_{x} ( t,x, \lambda ) d {W}_{t}, \\
  \mathcal{V}_{x} ( T,x, \lambda ) 
& = \zeta + \theta \Big( \lambda - x - \frac{\zeta }{\theta } \Big)_{+},
\end{aligned} \right.
\end{equation*}
for $( \mathcal{V}_{x}, {\psi }_{x} ) \in {C}_{\mathbb{F}} ( 0,T; \mathbb{L}^{2} ( \Omega; {C}^{2,1} ( \mathbb{R} \times \mathbb{R}; \mathbb{R} ) ) ) 
                                   \times {C}_{\mathbb{F}} ( 0,T; \mathbb{L}^{2} ( \Omega; {C}^{2,1} ( \mathbb{R} \times \mathbb{R}; \mathbb{R} ) ) )$.
Applying the It\^o-Kunita-Ventzel formula to $\{ \mathcal{V}_{x} ( s, {X}^{ \bar{\pi } }_{s}, \lambda ) \}_{ s \in [ 0,T ] }$, we obtain
\begin{equation*}
\left\{ \begin{aligned}
  - d \mathcal{V}_{x} ( s, {X}^{ \bar{\pi } }_{s}, \lambda )
& = \mathcal{V}_{x} ( s, {X}^{ \bar{\pi } }_{s}, \lambda ) {r}_{s} ds
  - \big( {\psi }_{x} ( s, {X}^{ \bar{\pi } }_{s}, \lambda ) + \mathcal{V}_{xx} ( s, {X}^{ \bar{\pi } }_{s}, \lambda ) \bar{\pi }_{s} {\sigma }_{s} \big) d {W}_{s}, \\
    \mathcal{V}_{x} ( T, {X}^{ \bar{\pi } }_{T}, \lambda ) 
& = \zeta + \theta \Big( \lambda - {X}^{ \bar{\pi } }_{T} - \frac{\zeta }{\theta } \Big)_{+}.
\end{aligned} \right.
\end{equation*}
Thus, $( Y ( \lambda ), \mathcal{Y} ( \lambda ) ) \in {C}_{\mathbb{F}} ( 0,T; \mathbb{L}^{2} ( \Omega; \mathbb{R} ) ) \times {C}_{\mathbb{F}} ( 0,T; \mathbb{L}^{2} ( \Omega; \mathbb{R} ) )$ given by
\begin{equation*}
{Y}_{s} ( \lambda ) = \mathcal{V}_{x} ( s, {X}^{ \bar{\pi } }_{s}, \lambda ), \quad 
\mathcal{Y}_{s} ( \lambda ) = \mathcal{V}_{xx} ( s, {X}^{ \bar{\pi } }_{s}, \lambda ) \bar{\pi }_{s} {\sigma }_{s} + {\psi }_{x} ( s, {X}^{ \bar{\pi } }_{s}, \lambda )
\end{equation*}
solves the BSDE ${Y}_{s} ( \lambda ) = \zeta + \theta ( \lambda - {X}^{ \bar{\pi } }_{T} - \zeta / \theta )_{+} + \int_{s}^{T} {Y}_{v} ( \lambda ) {r}_{v} dv - \int_{s}^{T} \mathcal{Y}_{v} ( \lambda ) d {W}_{v}$.
In comparison with \cref{eq: BSDE :eq}, $( {Y}^{t}, \mathcal{Y}^{t} ) = ( Y ( \lambda ( \mathbb{P}^{t}_{ {X}^{ \bar{\pi } }_{T}, \zeta } ) ), \mathcal{Y} ( \lambda ( \mathbb{P}^{t}_{ {X}^{ \bar{\pi } }_{T}, \zeta } ) ) )$ on $[ t,T ] \times \Omega $ follows. 
Consequently, $\mathcal{Y}^{t}$ is sample continuous, and plugging $x = {X}^{ \bar{\pi } }_{t}$ into \cref{eq: equilibrium condition for trivial NEC :eq} yields ${Y}^{t}_{t} {\vartheta }_{t} + \mathcal{Y}^{t}_{t} = 0$.
Therefore, $\bar{\pi }$ is an ONEC according to \Cref{thm: verification theorem for ONEC}.


\subsection{Proof of \Cref{thm: equilibrium value function and strong equilibria}}
\label{pf-thm: equilibrium value function and strong equilibria}

For the first claim, it suffices to show $\bar{J} ( t,x, \bar{\Pi } ) > \bar{J} ( t,x, \bar{\Pi }^{ t, \varepsilon, \bar{\Pi } ( t,x ) } )$ for any sufficiently small $\varepsilon $,
since \Cref{pf-thm: verification theorem for CNEC,pf-thm: state-independent CNEC} have provided $\mathcal{V}_{xx} < 0$ and
\begin{align*}
& \bar{J} ( t,x, \bar{\Pi }^{ t, \varepsilon, \xi } ) - \bar{J} ( t,x, \bar{\Pi } ) \\
& = \bigg( \frac{1}{2} \mathcal{V}_{xx} ( t,x, {\lambda }_{0} ) \big( {\xi }^{2} - | \bar{\Pi } ( t,x ) |^{2} \big) | \sigma |^{2} 
         + \mathcal{V}_{x} ( t,x, {\lambda }_{0} ) \vartheta \big( \xi - \bar{\Pi } ( t,x ) \big) \sigma \bigg) \varepsilon 
  + o ( \varepsilon ),
\end{align*}
which by \cref{eq: equilibrium condition for CNEC :eq}, it implies that
\begin{equation*}
\lim_{ \varepsilon \downarrow 0 } \frac{1}{\varepsilon } \big( \bar{J} ( t,x, \bar{\Pi }^{ t, \varepsilon, \xi } ) - \bar{J} ( t,x, \bar{\Pi } ) \big) < 0, \quad \forall \xi \ne \bar{\Pi } ( t,x ).
\end{equation*}
Due to the proof of the second claim of \Cref{thm: state-independent CNEC} and
\begin{equation*}
\bar{\Pi }^{ t, \varepsilon, \bar{\Pi } ( t,x ) } ( s,y ) = \Big( {1}_{\{ s \notin [ t, t + \varepsilon ) \}} {\beta }_{t} {e}^{ - r (s-t) } + {1}_{\{ s \notin [ t, t + \varepsilon ) \}} {\beta }_{s} \Big) \frac{\vartheta }{ \theta \sigma } {e}^{ - r (T-s) },
\end{equation*} 
we obtain
\begin{align*}
& \theta | \vartheta |^{-2} \big( \bar{J} ( t,x, \bar{\Pi } ) - \bar{J} ( t,x, \bar{\Pi }^{ t, \varepsilon, \bar{\Pi } ( t,x ) } ) \big) \\
& = \int_{t}^{ t + \varepsilon } {\beta }_{s} ds - {\beta }_{t} \int_{0}^{\varepsilon } {e}^{ - r s } ds
  + \int_{t}^{T} | {\beta }_{s} |^{2} ds \int_{0}^{ \frac{ 1 - \zeta }{\vartheta } ( \int_{t}^{T} | {\beta }_{s} |^{2} ds )^{ - \frac{1}{2} } } \Psi(y) dy \\
& \quad - \bigg( \int_{ t + \varepsilon }^{T} | {\beta }_{s} |^{2} ds + | {\beta }_{t} |^{2} \int_{0}^{\varepsilon } {e}^{ - 2 r s } ds \bigg)
          \int_{0}^{ \frac{ 1 - \zeta }{\vartheta } ( \int_{ t + \varepsilon }^{T} | {\beta }_{s} |^{2} ds + | {\beta }_{t} |^{2} \int_{0}^{\varepsilon } {e}^{ - 2 r s } ds )^{ - \frac{1}{2} } } \Psi(y) dy. 
\end{align*}
By Taylor expansion, 
\begin{align*}
  \int_{t}^{ t + \varepsilon } {\beta }_{s} ds - {\beta }_{t} \int_{0}^{\varepsilon } {e}^{ - r s } ds
& = \frac{1}{2} ( {\beta }_{t}' + r {\beta }_{t} ) {\varepsilon }^{2} 
  + \frac{1}{6} ( {\beta }_{t}'' - {r}^{2} {\beta }_{t} ) {\varepsilon }^{3} 
  + O ( {\varepsilon }^{4} ), \\
  \int_{t}^{ t + \varepsilon } | {\beta }_{s} |^{2} ds - | {\beta }_{t} |^{2} \int_{0}^{\varepsilon } {e}^{ - 2 r s } ds 
& = ( {\beta }_{t}' {\beta }_{t} + r | {\beta }_{t} |^{2} ) {\varepsilon }^{2} 
  + \frac{1}{3} ( {\beta }_{t}'' {\beta }_{t} + | {\beta }_{t}' |^{2} - 2 {r}^{2} | {\beta }_{t} |^{2} ) {\varepsilon }^{3} 
  + O ( {\varepsilon }^{4} ),
\end{align*}
the latter of which implies that
\begin{align*}
& \bigg( \int_{ t + \varepsilon }^{T} | {\beta }_{s} |^{2} ds + | {\beta }_{t} |^{2} \int_{0}^{\varepsilon } {e}^{ - 2 r s } ds \bigg)
         \int_{0}^{ \frac{ 1 - \zeta }{\vartheta } ( \int_{ t + \varepsilon }^{T} | {\beta }_{s} |^{2} ds + | {\beta }_{t} |^{2} \int_{0}^{\varepsilon } {e}^{ - 2 r s } ds )^{ - \frac{1}{2} } } \Psi(y) dy \\
& = \int_{t}^{T} | {\beta }_{s} |^{2} ds \int_{0}^{ \frac{ 1 - \zeta }{\vartheta ( \int_{t}^{T} | {\beta }_{s} |^{2} ds )^{ \frac{1}{2} } } } \Psi(y) dy \\
& \quad - \Big( ( {\beta }_{t}' {\beta }_{t} + r | {\beta }_{t} |^{2} ) {\varepsilon }^{2} 
              + \frac{1}{3} ( {\beta }_{t}'' {\beta }_{t} + | {\beta }_{t}' |^{2} - 2 {r}^{2} | {\beta }_{t} |^{2} ) {\varepsilon }^{3} \Big) \\
& \qquad  \times \Bigg( \int_{0}^{ \frac{ 1 - \zeta }{ \vartheta ( \int_{t}^{T} | {\beta }_{s} |^{2} ds )^{ \frac{1}{2} } } } \Psi(y) dy
                      - \frac{ 1 - \zeta }{ 2 \vartheta ( \int_{t}^{T} | {\beta }_{s} |^{2} ds )^{ \frac{1}{2} } } 
                        \Psi \bigg( \frac{ 1 - \zeta }{ \vartheta ( \int_{t}^{T} | {\beta }_{s} |^{2} ds )^{ \frac{1}{2} } } \bigg) \Bigg)
        + O ( {\varepsilon }^{4} ).
\end{align*}
Hence, with ${B}_{t} := ( \int_{t}^{T} | {\beta }_{s} |^{2} ds )^{-1/2} ( 1 - \zeta ) / \vartheta $ for the sake of brevity, we obtain
\begin{align}
& \theta | \vartheta |^{-2} \big( \bar{J} ( t,x, \bar{\Pi } ) - \bar{J} ( t,x, \bar{\Pi }^{ t, \varepsilon, \bar{\Pi } ( t,x ) } ) \big) \notag \\
& = \Big( \frac{1}{2} ( {\beta }_{t}' + r {\beta }_{t} ) {\varepsilon }^{2} + \frac{1}{6} ( {\beta }_{t}'' - {r}^{2} {\beta }_{t} ) {\varepsilon }^{3} \Big)
    \bigg( 1 + {\beta }_{t} \Big( 2 \int_{0}^{ {B}_{t} } \Psi(y) dy - {B}_{t} \Psi ( {B}_{t} ) \Big) \bigg) \notag \\
& \quad
  - \frac{1}{6} ( | r {\beta }_{t} |^{2} - | {\beta }_{t}' |^{2} ) 
                \bigg( 2 \int_{0}^{ {B}_{t} } \Psi(y) dy - {B}_{t} \Psi ( {B}_{t} ) \bigg) {\varepsilon }^{3}
  + O ( {\varepsilon }^{4} ).
\label{eq: asymptotic estimation for strong CNEC}
\end{align}
Now we show that $\chi (x) := \Phi (x) + 2 \int_{ - \infty }^{x} y \Phi (y) dy - x \int_{ - \infty }^{x} \Phi (y) dy \equiv 0$,
so that plugging $x = \Psi ( {B}_{t} )$ with \cref{eq: beta equation :eq} and $dy = \Phi \circ \Psi (y) d \Psi (y)$ into $\chi (x)$ 
immediately yields the fact that the first term on the right-hand side of \cref{eq: asymptotic estimation for strong CNEC} vanishes.
In fact, by $\chi'(x) = \Phi' (x) + x \Phi (x) - \int_{ - \infty }^{x} \Phi (y) dy = \Phi' (x) + \int_{ - \infty }^{x} y \Phi' (y) dy = 0$ and $\chi ( - \infty ) = 0$, we obtain $\chi \equiv 0$.
Consequently, 
\begin{equation*}
  \bar{J} ( t,x, \bar{\Pi } ) - \bar{J} ( t,x, \bar{\Pi }^{ t, \varepsilon, \bar{\Pi } ( t,x ) } ) 
= \frac{ | \vartheta |^{2} }{ 6 \theta {\beta }_{t} } ( r {\beta }_{t} - {\beta }_{t}' ) ( r {\beta }_{t} + {\beta }_{t}' ) {\varepsilon }^{3} + O ( {\varepsilon }^{4} ).
\end{equation*}
As $\beta $ is strictly decreasing with ${\beta }_{T} = 1$ (see \Cref{thm: path-independent ONEC}), under the condition $r > | {\beta }_{t}' | / {\beta }_{t}$ we have
\begin{equation*}
\lim_{ \varepsilon \downarrow 0 } \frac{1}{ {\varepsilon }^{3} } \big( \bar{J} ( t,x, \bar{\Pi }^{ t, \varepsilon, \bar{\Pi } ( t,x ) } ) - \bar{J} ( t,x, \bar{\Pi } ) \big) < 0.
\end{equation*}
Hence, the first claim follows.

In terms of the second claim, we proceed with the following general result:
\begin{align*}
& \mathbb{E}_{t} \bigg[ {1}_{A} \bigg| \Big( \int_{t}^{ t + \varepsilon } {\gamma }_{s} {\rho }_{s} d {W}_{s} \Big)^{2} - \Big( \int_{t}^{ t + \varepsilon } {\gamma }_{s} d {W}_{s} \Big)^{2} \bigg| \bigg] \\
& \le \bigg( \int_{t}^{ t + \varepsilon } \mathbb{E}_{t} [ | {\gamma }_{s} ( {\rho }_{s} + 1 ) |^{2} ] ds \bigg)^{ \frac{1}{2} }
      \bigg( \int_{t}^{ t + \varepsilon } \mathbb{E} [ | {\gamma }_{s} ( {\rho }_{s} - 1 ) |^{2} ] ds \bigg)^{ \frac{1}{2} } \\
& \le \varepsilon \bigg( \mathop{esssup}_{ [ t,T ] \times \Omega } | \gamma | \bigg)^{2} \bigg( 1 + \mathop{esssup}_{ [ t,T ] \times \Omega } | \rho | \bigg)^{2}
      \bigg( \frac{1}{\varepsilon } \int_{t}^{ t + \varepsilon } \mathbb{E} [ ( {\rho }_{s} - 1 )^{2} ] ds \bigg)^{ \frac{1}{2} } \\
&   = o ( \varepsilon )
\end{align*}
for any $A \in \mathcal{F}_{T}$ and $\gamma, \rho \in {C}_{\mathbb{F}} ( t,T ; \mathbb{L}^{\infty } ( \Omega; \mathcal{R} ) )$ with ${\rho }_{t} = 1$.
Therefore, plugging \cref{eq: equilibrium condition for ONEC :eq} with
\begin{align*}
& \lim_{\varepsilon \downarrow 0} \frac{1}{\varepsilon }
  \mathbb{E}_{t} \bigg[ \bigg( \int_{t}^{ t + \varepsilon } {e}^{ (T-s) r } \sigma d {W}_{s} \bigg)^{2} 
                                                            {1}_{\{ {X}^{ \bar{\pi } }_{T} + \frac{\zeta }{\theta } \le \lambda ( \mathbb{P}^{t}_{ {X}^{ \bar{\pi } }_{T}, \zeta } ) \}} \bigg] \\
& = {e}^{ 2 (T-t) r } {\sigma }^{2}
    \lim_{\varepsilon \downarrow 0} \frac{1}{\varepsilon }
    \mathbb{E}_{t} \bigg[ \Big( \int_{t}^{ t + \varepsilon } \frac{ {\beta }_{s} }{ {\beta }_{t} } d {W}_{s} \Big)^{2} 
                          \mathbb{E}_{ t + \varepsilon } \Big[ {1}_{\big\{ \frac{ \int_{t}^{T} {\beta }_{s} d {W}_{s} }{ ( \int_{t}^{T} | {\beta }_{s} |^{2} ds )^{ \frac{1}{2} } }
                                                                           \le \Psi \big( \frac{ 1 - \zeta }{ \vartheta ( \int_{t}^{T} | {\beta }_{s} |^{2} ds )^{ \frac{1}{2} } } \big) \big\}} \Big] \bigg] \\
& = {e}^{ 2 (T-t) r } \frac{ {\sigma }^{2} }{ | {\beta }_{t} |^{2} }
    \lim_{\varepsilon \downarrow 0} \frac{ \int_{t}^{ t + \varepsilon } | {\beta }_{s} |^{2} ds }{\varepsilon } \\
& \quad \times \lim_{\varepsilon \downarrow 0}
    \int_{ - \infty }^{ + \infty } {z}^{2} \Phi \bigg( \Psi \Big( \frac{ 1 - \zeta }{ \vartheta ( \int_{t}^{T} | {\beta }_{s} |^{2} ds )^{ \frac{1}{2} } } \Big) 
                                                       \frac{ ( \int_{t}^{T} | {\beta }_{s} |^{2} ds )^{ \frac{1}{2} } }{ ( \int_{ t + \varepsilon }^{T} | {\beta }_{s} |^{2} ds )^{ \frac{1}{2} } }
                                                     - z \frac{ ( \int_{t}^{ t + \varepsilon } | {\beta }_{s} |^{2} ds )^{ \frac{1}{2} } }
                                                              { ( \int_{ t + \varepsilon }^{T} | {\beta }_{s} |^{2} ds )^{ \frac{1}{2} } } \bigg) d \Phi (z) \\
& = {e}^{ 2 (T-t) r } {\sigma }^{2} \Phi \circ \Psi \bigg( \frac{ 1 - \zeta }{ \vartheta ( \int_{t}^{T} | {\beta }_{s} |^{2} ds )^{ \frac{1}{2} } } \bigg)
\end{align*} 
into \cref{eq: gap for open-loop spike deviation :eq} yields 
\begin{equation*}
  \lim_{\varepsilon \downarrow 0} \frac{1}{\varepsilon } \big( J ( t, \bar{\pi }^{ t, \varepsilon, \xi } ) - J ( t, \bar{\pi } ) \big)
= \lim_{ \varepsilon \downarrow 0 } \frac{1}{\varepsilon } \big( g ( \mathbb{P}^{t}_{ \bar{X}^{\varepsilon }_{T}, \zeta } ) - g ( \mathbb{P}^{t}_{ {X}^{ \bar{\pi } }_{T}, \zeta } ) \big) < 0,
\quad \forall \xi \ne 0.
\end{equation*} 
So the proof is completed.

