Let $Q_\alpha$ and $Q_\beta$ denote the following polynomial spaces:
\begin{align*}
	Q_\alpha&=\Big\{ a_1(x^2+y^2) + a_2x + a_3y + a_4 \;\Big|\; a_1,\dots,a_4\in \mathbb{R}\Big\}, \\
	Q_\beta&=\Big\{ a_1x^2+a_2xy+a_3y^2 + a_4x + a_5y + a_6 \;\Big|\; a_1,\dots,a_6\in \mathbb{R}\Big\}.
\end{align*}
Note that both $Q_\alpha$ and $Q_\beta$ are invariant under constant shifts and rotations,
and thus, they are independent of the choice of the coordinates.
Let $\tau$ be the given triangle, and we define two kinds of second-order interpolation, 
$\Pi^{(\alpha)}_\tau\varphi$ for $\varphi\in H^1(\tau)$ and
$\Pi^{(\beta)}_\tau\varphi$ for $\varphi\in H^2(\tau)$, on triangle $\tau$ as follows:
\begin{align*}
	&\left\{\begin{aligned}
		\Pi^{(\alpha)}_\tau&\varphi\in Q_\alpha, \\
		\int_{\gamma_k}\Pi^{(\alpha)}_\tau&\varphi\,ds=\int_{\gamma_k}\varphi\,ds,\qquad k=1,2,3, \\
		\iint_\tau \Pi^{(\alpha)}_\tau&\varphi\,dxdy=\iint_\tau\varphi\,dxdy,
	\end{aligned}\right. \\
	&\left\{\begin{aligned}
		\Pi^{(\beta)}_\tau&\varphi\in Q_\beta, \\
		\Pi^{(\beta)}_\tau&\varphi(p_k) = \varphi(p_k),\qquad k=1,2,3, \\
		\int_{\gamma_k}\nabla \Pi^{(\beta)}_\tau&\varphi\cdot n\,ds=\int_{\gamma_k}\nabla\varphi\cdot n\,ds,\qquad k=1,2,3. \\
	\end{aligned}\right. 
\end{align*}
Since the number of constraints and degrees of freedom are equal, these two interpolations are uniquely determined.

Non-conforming finite elements with bases of the same form as $\Pi^{(\alpha)}_\tau\varphi$
 and $\Pi^{(\beta)}_\tau\varphi$ are known as the enriched Crouzeix–Raviart element\cite{Hu}
and Morley element\cite{Morley}, respectively.

In the rest of this section, we prepare some preliminary lemmas.
\begin{lemma} \label{C2-gradient}
If $\varphi\in V^2(\tau)$ satisfies
$$
	\int_{\gamma_k}\nabla\varphi\cdot n\,ds=0,\quad k=1,2,3,
$$
then
$$
	\varphi_x,\;\varphi_y\in V^{1,2}(\tau)
$$
holds.
\end{lemma}
\begin{proof}
From $\varphi(p_1)=\varphi(p_2)=\varphi(p_3)=0$, we have
$$
	\int_{\gamma_k}\nabla\varphi\cdot\nu\,ds=0,\qquad k=1,2,3.
$$
Then, together with the assumption,
$$
	\int_{\gamma_k}\nabla\varphi\cdot w\,ds=0,\qquad k=1,2,3,
$$
holds for any fixed vector $w$, which proves the lemma.
\end{proof}

On the interpolations $\Pi^{(\alpha)}_\tau$ and $\Pi^{(\beta)}_\tau$, the following orthogonal properties hold:
\begin{lemma} \label{projection1}
For $\varphi\in H^1(\tau)$, it holds that
$$
	\|\nabla \Pi^{(\alpha)}_\tau\varphi\|_{L^2(\tau)}^2+\|\nabla(\varphi-\Pi^{(\alpha)}_\tau\varphi)\|_{L^2(\tau)}^2=\|\nabla\varphi\|_{L^2(\tau)}^2.
$$
\end{lemma}
\begin{lemma} \label{projection2}
For $\varphi\in H^2(\tau)$, it holds that
$$
	|\Pi^{(\beta)}_\tau\varphi|_{H^2(\tau)}^2+|\varphi-\Pi^{(\beta)}_\tau\varphi|_{H^2(\tau)}^2=|\varphi|_{H^2(\tau)}^2.
$$
\end{lemma}

\begin{proof}[Proof of Lemma~\ref{projection1}]
Let
$$
	\Pi^{(\alpha)}_\tau\varphi=a_1(x^2+y^2) + a_2x + a_3y + a_4,
$$
then, the divergence theorem yields
\begin{align*}
	\|\nabla\varphi\|_{L^2(\tau)}^2&-\|\nabla \Pi^{(\alpha)}_\tau\varphi\|_{L^2(\tau)}^2-\|\nabla(\varphi-\Pi^{(\alpha)}_\tau\varphi)\|_{L^2(\tau)}^2 \\
	&=2\iint_\tau \nabla(\varphi-\Pi^{(\alpha)}_\tau\varphi)\cdot\nabla \Pi^{(\alpha)}_\tau\varphi\,dxdy \\
	&=2\iint_\tau \text{div}\Big( (\varphi-\Pi^{(\alpha)}_\tau\varphi)\nabla \Pi^{(\alpha)}_\tau\varphi\Big)dxdy
		- 2\iint_\tau (\varphi-\Pi^{(\alpha)}_\tau\varphi)\Delta \Pi^{(\alpha)}_\tau\varphi\,dxdy \\
	&=2\oint_{\partial \tau}(\varphi-\Pi^{(\alpha)}_\tau\varphi)\nabla \Pi^{(\alpha)}_\tau\varphi\cdot n\,ds
		- 8a_1\iint_\tau (\varphi-\Pi^{(\alpha)}_\tau\varphi)\,dxdy \\
	&=2\oint_{\partial \tau}(\varphi-\Pi^{(\alpha)}_\tau\varphi)\binom{2a_1x+a_2}{2a_1y+a_3}\cdot n\,ds \\
	&=4a_1\oint_{\partial \tau}(\varphi-\Pi^{(\alpha)}_\tau\varphi)\binom{x}{y}\cdot n\,ds \\
	&=4a_1\int_{\gamma_1}(\varphi-\Pi^{(\alpha)}_\tau\varphi)
	\left(\binom{x}{y} - p_2\right) \cdot n\,ds \\
	& \qquad \qquad	+4a_1\int_{\gamma_2}(\varphi-\Pi^{(\alpha)}_\tau\varphi)
		  \left(\binom{x}{y} - p_3\right)\cdot n\,ds \\
	&\qquad\qquad\qquad\qquad +4a_1\int_{\gamma_3}(\varphi-\Pi^{(\alpha)}_\tau\varphi)\left(\binom{x}{y} - p_1\right)\cdot n\,ds \\
	&	=0.
\end{align*}
\end{proof}

\begin{proof}[Proof of Lemma~\ref{projection2}]
Let
$$
	\Pi^{(\beta)}_\tau\varphi=a_1x^2+a_2xy+a_3y^2 + a_4x + a_5y + a_6,
$$
then, the divergence theorem yields
\begin{align*}
	|\varphi|_{H^2(\tau)}^2&-|\Pi^{(\beta)}_\tau\varphi|_{H^2(\tau)}^2-|\varphi-\Pi^{(\beta)}_\tau\varphi|_{H^2(\tau)}^2 \\
	&=2\iint_\tau\Big((\varphi-\Pi^{(\beta)}_\tau\varphi)_{xx}(\Pi^{(\beta)}_\tau\varphi)_{xx}
		+2(\varphi-\Pi^{(\beta)}_\tau\varphi)_{xy}(\Pi^{(\beta)}_\tau\varphi)_{xy} \\
	&\qquad\qquad\qquad\qquad\qquad\qquad\qquad
		+(\varphi-\Pi^{(\beta)}_\tau\varphi)_{yy}(\Pi^{(\beta)}_\tau\varphi)_{yy}\Big)dxdy \\
	&=2\iint_\tau \text{div}\binom{\nabla(\varphi-\Pi^{(\beta)}_\tau\varphi)\cdot \nabla(\Pi^{(\beta)}_\tau\varphi)_x}
		{\nabla(\varphi-\Pi^{(\beta)}_\tau\varphi)\cdot \nabla(\Pi^{(\beta)}_\tau\varphi)_y}dxdy \\
	&=2\oint_{\partial \tau}\binom{\nabla(\varphi-\Pi^{(\beta)}_\tau\varphi)\cdot \nabla(\Pi^{(\beta)}_\tau\varphi)_x}
		{\nabla(\varphi-\Pi^{(\beta)}_\tau\varphi)\cdot \nabla(\Pi^{(\beta)}_\tau\varphi)_y}\cdot n\,ds \\
	&=2\oint_{\partial \tau}\nabla(\varphi-\Pi^{(\beta)}_\tau\varphi)\cdot \nabla(\nabla \Pi^{(\beta)}_\tau\varphi\cdot n)\,ds \\
	&=2\oint_{\partial \tau}\nabla(\varphi-\Pi^{(\beta)}_\tau\varphi)\cdot \binom{2a_1 \;\; a_2}{a_2\;\;2a_3}n\,ds.
\end{align*}
Here, Lemma~\ref{C2-gradient} yields
$$
	\int_{\gamma_k}(\varphi-\Pi^{(\beta)}_\tau\varphi)_x\,ds
	=\int_{\gamma_k}(\varphi-\Pi^{(\beta)}_\tau\varphi)_y\,ds
	=0,\qquad k=1,2,3,
$$
which leads us to the conclusion.
\end{proof}

\section{Relation to the finite dimensional eigenvalue problem} \label{RelationFDEP}
In this section, we will explain the way to bound $C_j(T)$ by the solutions of the finite-dimensional problem.  Let $n \ge 2$ be an integer.
We divide triangle $T$ into $n^2$ congruent small triangles with a similarity ratio of $1/n$ (Fig.~\ref{Fig2}). 

