We assume that each $\tau_k$ is an open set, namely, does not contain its boundary. Furthermore, we define
$$
	T'=\bigcup_{k=1}^{n^2}\tau_k.
$$
Now, we define $\Pi^{(\alpha)}u$ for $u\in H^1(T)$ and $\Pi^{(\beta)}u$ for $u\in H^2(T)$ as follows:
$$
	\Pi^{(\alpha)}u|_{\tau_k} = \Pi^{(\alpha)}_{\tau_k}u, \qquad
	\Pi^{(\beta)}u|_{\tau_k} = \Pi^{(\beta)}_{\tau_k}u.
$$
Note that, in general, $\Pi^{(\alpha)}u$ and $\Pi^{(\beta)}u$ can not be extended as continuous functions on $T$.

We assume that the following values exist:
\begin{align*}
	C_1^{(n)}(T)&=\sup_{u\in V^{1,1}(T)\setminus 0}\frac{\|\Pi^{(\alpha)}u\|_{L^2(T')}}{\|\nabla \Pi^{(\alpha)}u\|_{L^2(T')}}, &
	C_2^{(n)}(T)&=\sup_{u\in V^{1,2}(T)\setminus 0}\frac{\|\Pi^{(\alpha)}u\|_{L^2(T')}}{\|\nabla \Pi^{(\alpha)}u\|_{L^2(T')}}, \\
	C_3^{(n)}(T)&=\sup_{u\in V^2(T)\setminus 0}\frac{\|\Pi^{(\beta)}u\|_{L^2(T')}}{|\Pi^{(\beta)}u|_{H^2(T')}}, &
	C_4^{(n)}(T)&=\sup_{u\in V^2(T)\setminus 0}\frac{\|\nabla \Pi^{(\beta)}u\|_{L^2(T')}}{|\Pi^{(\beta)}u|_{H^2(T')}}.
\end{align*} 
Since $\Pi^{(\alpha)}u$ and $\Pi^{(\beta)}u$ are piecewise polynomials on $T'$,
we can obtain these values by solving finite-dimensional generalized eigenvalue problems, namely,
the upper bound of Rayleigh quotient.

Concerning these constants, we have the following theorem:
\begin{theorem} \label{BoundbyFiniteResult}
\begin{align*}
	C_1(T)&\le\sqrt{\frac{n^2}{n^2-1}}\;C_1^{(n)}(T), &
	C_2(T)&\le\sqrt{\frac{n^2}{n^2-1}}\;C_2^{(n)}(T), \\
	C_3(T)&\le\sqrt{\frac{n^4}{n^4-1}}\;C_3^{(n)}(T), &
	C_4(T)&\le\sqrt{C_4^{(n)}(T)^2+\frac{C_2(T)^2}{n^2}}.
\end{align*}
\end{theorem}

\begin{proof}
We first note that the scaling properties $C_j(\tau_k)=C_j(T)/n,\;j= 1, 2,4$ and
$C_3(\tau_k)=C_3(T)/n^2$ hold. This property can be easily shown by a change of variables.

From Lemma~\ref{projection1}, for $u\in V^{1,j}(T),\;\; j=1,2$, we have
\begin{align*}
	\|u\|_{L^2(T)}&\le \|\Pi^{(\alpha)}u\|_{L^2(T')}+\|u-\Pi^{(\alpha)}u\|_{L^2(T')} \\
	&=\|\Pi^{(\alpha)}u\|_{L^2(T')}
		+\sqrt{\sum_{k=1}^{n^2}\|u-\Pi^{(\alpha)}_{\tau_k}u\|_{L^2(\tau_k)}^2} \\
	&\le C_j^{(n)}(T)\;\|\nabla \Pi^{(\alpha)}u\|_{L^2(T')}
		+\frac{C_j(T)}{n}\sqrt{\sum_{k=1}^{n^2}\|\nabla(u-\Pi^{(\alpha)}_{\tau_k}u)\|_{L^2(\tau_k)}^2} \\
	&\le \sqrt{C_j^{(n)}(T)^2+\frac{C_j(T)^2}{n^2}}
		\sqrt{\sum_{k=1}^{n^2}\left(\|\nabla \Pi^{(\alpha)}_{\tau_k}u\|_{L^2(\tau_k)}^2
		+\|\nabla(u-\Pi^{(\alpha)}_{\tau_k}u)\|_{L^2(\tau_k)}^2\right)} \\
	&= \sqrt{C_j^{(n)}(T)^2+\frac{C_j(T)^2}{n^2}}
		\sqrt{\sum_{k=1}^{n^2}\|\nabla u\|_{L^2(\tau_k)}^2} \\
	&= \sqrt{C_j^{(n)}(T)^2+\frac{C_j(T)^2}{n^2}}\;\|\nabla u\|_{L^2(T)}.
\end{align*}
Furthermore, from Lemma~\ref{projection2}, for $u\in V^2(T)$,
\begin{align*}
	\|u\|_{L^2(T)}&\le \|\Pi^{(\beta)}u\|_{L^2(T')}+\|u-\Pi^{(\beta)}u\|_{L^2(T')} \\
	&= \|\Pi^{(\beta)}u\|_{L^2(T')}
		+\sqrt{\sum_{k=1}^{n^2}\|u-\Pi^{(\beta)}_{\tau_k}u\|_{L^2(\tau_k)}^2} \\
	&\le C_3^{(n)}(T)\;|\Pi^{(\beta)}u|_{H^2(T')}
		+\frac{C_3(T)}{n^2}\sqrt{\sum_{k=1}^{n^2}|u-\Pi^{(\beta)}_{\tau_k}u|_{H^2(\tau_k)}^2} \\
	&\le \sqrt{C_3^{(n)}(T)^2+\frac{C_3(T)^2}{n^4}}
		\sqrt{\sum_{k=1}^{n^2}\left(|\Pi^{(\beta)}_{\tau_k}u|_{H^2(\tau_k)}^2
		+|u-\Pi^{(\beta)}_{\tau_k}u|_{H^2(\tau_k)}^2\right)} \\
	&= \sqrt{C_3^{(n)}(T)^2+\frac{C_3(T)^2}{n^4}}
		\sqrt{\sum_{k=1}^{n^2}|u|_{H^2(\tau_k)}^2} \\
	&= \sqrt{C_3^{(n)}(T)^2+\frac{C_3(T)^2}{n^4}}\;|u|_{H^2(T)}
\end{align*}
and from Lemma~\ref{C2-gradient} and Lemma~\ref{projection2},
\begin{align*}
	\|\nabla u\|_{L^2(T)}&\le \|\nabla \Pi^{(\beta)}u\|_{L^2(T')}+\|\nabla(u-\Pi^{(\beta)}u)\|_{L^2(T')} \\
	&= \|\nabla \Pi^{(\beta)}u\|_{L^2(T')}
		+\sqrt{\sum_{k=1}^{n^2}\left(\|(u-\Pi^{(\beta)}_{\tau_k}u)_x\|_{L^2(\tau_k)}^2 + \|(u-\Pi^{(\beta)}_{\tau_k}u)_y\|_{L^2(\tau_k)}^2\right)} \\
	&\le C_4^{(n)}(T)\;|\Pi^{(\beta)}u|_{H^2(T')}  \\
	&\qquad\qquad +\frac{C_2(T)}{n}\sqrt{\sum_{k=1}^{n^2}\left(\|\nabla(u-\Pi^{(\beta)}_{\tau_k}u)_x\|_{L^2(\tau_k)}^2 + \|\nabla(u-\Pi^{(\beta)}_{\tau_k}u)_y\|_{L^2(\tau_k)}^2\right)} \\
	&=C_4^{(n)}(T)\;|\Pi^{(\beta)}u|_{H^2(T')}+\frac{C_2(T)}{n}\sqrt{\sum_{k=1}^{n^2}|u-\Pi^{(\beta)}_{\tau_k}u|_{H^2(\tau_k)}^2} \\
	&\le \sqrt{C_4^{(n)}(T)^2+\frac{C_2(T)^2}{n^2}}
		\sqrt{\sum_{k=1}^{n^2}\left(|\Pi^{(\beta)}_{\tau_k}u|_{H^2(\tau_k)}^2
		+|u-\Pi^{(\beta)}_{\tau_k}u|_{H^2(\tau_k)}^2\right)} \\
	&= \sqrt{C_4^{(n)}(T)^2+\frac{C_2(T)^2}{n^2}}
		\sqrt{\sum_{k=1}^{n^2}|u|_{H^2(\tau_k)}^2} \\
	&= \sqrt{C_4^{(n)}(T)^2+\frac{C_2(T)^2}{n^2}}\;|u|_{H^2(T)}
\end{align*}
holds. 
From above evaluations, we have the following:
\begin{align*}
	C_1(T)&\le \sqrt{C_1^{(n)}(T)^2+\frac{C_1(T)^2}{n^2}}, &
	C_2(T)&\le \sqrt{C_2^{(n)}(T)^2+\frac{C_2(T)^2}{n^2}}, \\
	C_3(T)&\le \sqrt{C_3^{(n)}(T)^2+\frac{C_3(T)^2}{n^4}}, &
	C_4(T)&\le \sqrt{C_4^{(n)}(T)^2+\frac{C_2(T)^2}{n^2}},
\end{align*}
which leads us to the conclusion.
\end{proof}

This result shows that we can bound the constants $C_j(T)$ using $C_j^{(n)}(T)$.
For specific $T$ and $n$, we can compute upper bounds of $C_j^{(n)}(T)$ numerically
and obtain guaranteed results via the numerical verification method.

\section{Construction of the finite-dimensional generalized eigenvalue problems} \label{Construction_FDGEP}
The results of the previous section show that $C_j^{(n)}(T)$ can be evaluated
 by bounding the eigenvalues of the corresponding finite-dimensional generalized eigenvalue problem.

First, we describe how to construct the corresponding finite-dimensional generalized eigenvalue problem
 for a particular fixed triangle.

Lets $s$ be the area of the triangle $\tau$ and
$$
	c_1 = \frac{|\gamma_1|^2}{s},
	\qquad c_2 = \frac{|\gamma_2|^2}{s},
	\qquad c_3 = \frac{|\gamma_3|^2}{s}.
$$
Then the following two lemmas hold:
\begin{lemma} \label{F1}
Let
\begin{align}
	w_k &= \frac{1}{|\gamma_k|}\int_{\gamma_k}\Pi^{(\alpha)}_\tau u\,ds,\qquad k=1,2,3, \label{F1-1} \\
	u_0 &= \frac{1}{s}\iint_\tau \Pi^{(\alpha)}_\tau u\,dxdy, \label{F1-2}
\end{align}
then it holds that
\begin{align}
	\|\Pi^{(\alpha)}_\tau u\|_{L^2(\tau)}^2&=F^{(\alpha)}_0(s,w_1,w_2,w_3,u_0), \label{F1-3} \\
	\|\nabla \Pi^{(\alpha)}_\tau u\|_{L^2(\tau)}^2&=F^{(\alpha)}_1(s,w_1,w_2,w_3,u_0), \label{F1-4}
\end{align}
where 
\begin{align*}
	F^{(\alpha)}_0(s,w_1,&w_2,w_3,u_0) \\
	&=\frac{s}{15}\left\{\frac{8(c_1^2+c_2^2+c_3^2)(w_1+w_2+w_3-3u_0)^2}{(c_1+c_2+c_3)^2}\right. \\
	&\qquad\quad
		\left.\phantom{\left(\frac{c_1^2}{c_1^2}\right)}
		-\frac{2(w_1+w_2+w_3-3u_0)v_0}{c_1+c_2+c_3}+ 5\big(w_1^2+w_2^2+w_3^2\big) \right\}, \\
	v_0&=\big(3c_2+3c_3-c_1\big)w_1+\big(3c_3+3c_1-c_2\big)w_2+\big(3c_1+3c_2-c_3\big)w_3, \\
	F^{(\alpha)}_1(s,w_1,&w_2,w_3,u_0) \\
	&=\frac{1}{2}\left\{\frac{32(w_1+w_2+w_3-3u_0)^2}{c_1+c_2+c_3}+\big(c_1+c_2-c_3\big)\big(w_1-w_2\big)^2\right. \\
	&\quad \left.\phantom{\frac{32(w_3)^2}{c_1}}
		+\big(c_2+c_3-c_1\big)\big(w_2-w_3\big)^2+\big(c_3+c_1-c_2\big)\big(w_3-w_1\big)^2\right\}.
\end{align*}
\end{lemma}
\begin{proof}
Since $Q_\alpha$ is invariant under constant shifts and rotations,
we take $p_1=(0,0),\;p_2=(h,0),\;p_3=(ah,bh)$. Then, it holds that
$$
	s = \frac{bh^2}{2},
	\qquad c_1 = \frac{2((1-a)^2+b^2)}{b},
	\qquad c_2 = \frac{2(a^2+b^2)}{b},
	\qquad c_3 = \frac{2}{b}
$$
and $\Pi^{(\alpha)}_\tau u$ satisfying \eqref{F1-1} and \eqref{F1-2} is obtained as follows:
\begin{align*}
	\Pi^{(\alpha)}_\tau u= \frac{1}{bh}&\left\{
		\Big( b(2x-h)+2(1-a)y \Big)w_1 - \Big( b(2x-h)-2ay\Big)w_2 - (2y-bh)w_3\right\} \\
	& + \frac{2(3(x^2+y^2) - 2(1+a)hx - 2bhy + ah^2)}{(1-a+a^2+b^2)h^2}\Big(w_1+w_2+w_3-3u_0\Big).
\end{align*}
Then the proof is shown from the uniqueness of $\Pi^{(\alpha)}_\tau u$ and the fact that $\Pi^{(\alpha)}_\tau u$
satisfies \eqref{F1-3} and \eqref{F1-4}.
\end{proof}

\begin{lemma} \label{F2}
Let
\begin{align}
	u_k&=\Pi^{(\beta)}_\tau u(p_k),\qquad k=1,2,3, \label{F2-1} \\
	w_k&=\int_{\gamma_k}\nabla \Pi^{(\beta)}_\tau u\cdot n\,ds,\qquad k=1,2,3, \label{F2-2}
\end{align}
then it holds that
\begin{align}
	\|\Pi^{(\beta)}_\tau u\|_{L^2(\tau)}^2&=F^{(\beta)}_0(s,u_1,u_2,u_3,w_1,w_2,w_3), \label{F2-3} \\
	\|\nabla \Pi^{(\beta)}_\tau u\|_{L^2(\tau)}^2&=F^{(\beta)}_1(s,u_1,u_2,u_3,w_1,w_2,w_3), \label{F2-4} \\
	|\Pi^{(\beta)}_\tau u|_{H^2(\tau)}^2&=F^{(\beta)}_2(s,u_1,u_2,u_3,w_1,w_2,w_3), \label{F2-5}
\end{align}
where
\begin{align*}
	F^{(\beta)}_0(s,u_1,u_2,&u_3,w_1,w_2,w_3)
		=\frac{s}{720}\Big\{
		21\big(u_1^2+u_2^2+u_3^2\big)
		-6\big(u_1u_2+u_2u_3+u_3u_1\big) \\
	&\qquad\qquad
		+6\big({v_1}^2+{v_2}^2+{v_3}^2\big)
		+10\big(v_1v_2+v_2v_3+v_3v_1\big)\Big\}, \\
	v_1&=\frac{13u_1+u_2+u_3}{4}-\frac{4w_1-(c_2-c_3)(u_2-u_3)}{c_1}, \\
	v_2&=\frac{13u_2+u_3+u_1}{4}-\frac{4w_2-(c_3-c_1)(u_3-u_1)}{c_2}, \\
	v_3&=\frac{13u_3+u_1+u_2}{4}-\frac{4w_3-(c_1-c_2)(u_1-u_2)}{c_3}, \\
	F^{(\beta)}_1(s,u_1,u_2,&u_3,w_1,w_2,w_3) \\
		&=\frac{1}{3}\left(
		\frac{(u_2-u_3)^2+w_1^2}{c_1}
		+\frac{(u_3-u_1)^2+w_2^2}{c_2}
		+\frac{(u_1-u_2)^2+w_3^2}{c_3}
	\right), \\
	F^{(\beta)}_2(s,u_1,u_2,&u_3,w_1,w_2,w_3)
		=\frac{1}{16s}\Big\{\big(c_1v_4+c_2v_5+c_3v_6\big)^2
		-8\big(v_4v_5+v_5v_6+v_6v_4\big)\Big\}, \\
	v_4&=2u_1-u_2-u_3+\frac{4w_1-(c_2-c_3)(u_2-u_3)}{c_1}, \\
	v_5&=2u_2-u_3-u_1+\frac{4w_2-(c_3-c_1)(u_3-u_1)}{c_2}, \\
	v_6&=2u_3-u_1-u_2+\frac{4w_3-(c_1-c_2)(u_1-u_2)}{c_3}.
\end{align*}            
\end{lemma}
\begin{proof}
Since $Q_\beta$ is invariant under constant shifts and rotations, same as previous lemma,
we take $p_1=(0,0),\;p_2=(h,0),\;p_3=(ah,bh)$. Then, it holds that
$$
	s = \frac{bh^2}{2},
	\qquad c_1 = \frac{2((1-a)^2+b^2)}{b},
	\qquad c_2 = \frac{2(a^2+b^2)}{b},
	\qquad c_3 = \frac{2}{b}
$$
and $\Pi^{(\beta)}_\tau u$ satisfying \eqref{F2-1} and \eqref{F2-2} is obtained as follows:
\begin{align*}
	\Pi^{(\beta)}_\tau u= &\frac{1}{bh}\left\{-\Big(b(x-h)+(1-a)y\Big)u_1 + (bx-ay)u_2 + yu_3 \right\} \\
	&+ \frac{(b(x-h)+(1-a)y)(bx+(1-a)y)}{((1-a)^2+b^2)b^2h^2} \\
	&\qquad\qquad\qquad \times\Big( bw_1 + ((1-a)^2+b^2)u_1 + (a(1-a)-b^2)u_2 - (1-a)u_3 \Big) \\
	&+ \frac{(b(x-h)-ay)(bx-ay)}{(a^2+b^2)b^2h^2}\Big( bw_2 + (a(1-a)-b^2)u_1 + (a^2+b^2)u_2 - au_3 \Big) \\
	&+ \frac{(y-bh)y}{h^2b^2}\Big( bw_3 - (1-a)u_1 - au_2 + u_3 \Big).
\end{align*}
Then the proof is shown from the uniqueness of $\Pi^{(\beta)}_\tau u$ and the fact that $\Pi^{(\beta)}_\tau u$
 satisfies \eqref{F2-3}, \eqref{F2-4} and \eqref{F2-5}.
\end{proof}
The proofs of Lemma~\ref{F1} and Lemma~\ref{F2} can be checked by hand calculation in principle.
However, it is more realistic to verify them using a formula manipulation system.
Code~\ref{Lemma5-1} and Code~\ref{Lemma5-2} in Appendix 2 show the verification codes using
MATLAB with Symbolic Math Toolbox.

We will now explain the practical construction of the finite-dimensional eigenvalue problem.
Divide the given triangle $T$ into $n^2$ similar small triangles $\tau_1,\tau_2,\dots,\tau_{n^2}$
as shown in Fig.~\ref{Fig2}, and let $S$ be the area of triangle $T$.
Under the constraints, for $u\in V^{1,j},\;j=1,2$, the problem of finding $C_1^{(n)}(T)$ is a generalized eigenvalue problem
in $(n+1)(5n-2)/2$ dimensions, and the problem of finding $C_2^{(n)}(T)$ is a generalized eigenvalue problem in
$(5n^2+3n-6)/2$ dimensions.

