	\|\nabla\Pi^{(\alpha)}&u\|_{L^2(T')}^2=F^{(\alpha)}_1(S/4, w_7, w_5, w_3, u_1)
		+ F^{(\alpha)}_1(S/4, w_1, w_8, w_6, u_2) \\
	&\qquad\qquad + F^{(\alpha)}_1(S/4, w_4, w_2, w_9, u_3)
     + F^{(\alpha)}_1(S/4, w_7, w_8, w_9, -u_1-u_2-u_3).
\end{align*}
For $u\in V^{1,2}$, the constraints
$$
	w_1+w_4=w_2+w_5=w_3+w_6=0
$$
are taken into account, we obtain
\begin{align*}
	\|\Pi^{(\alpha)}u\|_{L^2(T')}^2&=F^{(\alpha)}_0(S/4, w_7, -w_2, w_3, u_1)
		+ F^{(\alpha)}_0(S/4, w_1, w_8, -w_3, u_2) \\
	&\qquad\qquad + F^{(\alpha)}_0(S/4, -w_1, w_2, w_9, u_3)
     + F^{(\alpha)}_0(S/4, w_7, w_8, w_9, u_4), \\
	\|\nabla\Pi^{(\alpha)}u\|_{L^2(T')}^2&=F^{(\alpha)}_1(S/4, w_7, -w_2, w_3, u_1)
		+ F^{(\alpha)}_1(S/4, w_1, w_8, -w_3, u_2) \\
	&\qquad\qquad + F^{(\alpha)}_1(S/4, -w_1, w_2, w_9, u_3)
     + F^{(\alpha)}_1(S/4, w_7, w_8, w_9, u_4).
\end{align*}

Furthermore, for $u\in V^2$, the problem of finding $C_3^{(n)}(T)$ and $C_4^{(n)}(T)$ become generalized eigenvalue problems
 in $(n+2)(2n-1)$ dimensions.

