$$
is taken into account, we obtain
\begin{align*}
	\|\Pi^{(\beta)}u&\|_{L^2(T')}^2=F^{(\beta)}_0(S/4, 0, u_3, u_2, w_7, w_5, w_3)
		+ F^{(\beta)}_0(S/4, u_3, 0, u_1, w_1, w_8, w_6) \\
	&\qquad + F^{(\beta)}_0(S/4, u_2, u_1, 0, w_4, w_2, w_9)
		+ F^{(\beta)}_0(S/4, u_1, u_2, u_3, -w_7, -w_8, -w_9), \\
	\|\nabla \Pi^{(\beta)}&u\|_{L^2(T')}^2=F^{(\beta)}_1(S/4, 0, u_3, u_2, w_7, w_5, w_3)
		+ F^{(\beta)}_1(S/4, u_3, 0, u_1, w_1, w_8, w_6) \\
	&\qquad + F^{(\beta)}_1(S/4, u_2, u_1, 0, w_4, w_2, w_9)
		+ F^{(\beta)}_1(S/4, u_1, u_2, u_3, -w_7, -w_8, -w_9), \\
	|\Pi^{(\beta)}u&|_{H^2(T')}^2=F^{(\beta)}_2(S/4, 0, u_3, u_2, w_7, w_5, w_3)
		+ F^{(\beta)}_2(S/4, u_3, 0, u_1, w_1, w_8, w_6) \\
	&\qquad + F^{(\beta)}_2(S/4, u_2, u_1, 0, w_4, w_2, w_9)
		+ F^{(\beta)}_2(S/4, u_1, u_2, u_3, -w_7, -w_8, -w_9).
\end{align*}
For example, if we take
\begin{align*}
	G_1&=F^{(\beta)}_1(S/4, 0, u_3, u_2, w_7, w_5, w_3)
		+ F^{(\beta)}_1(S/4, u_3, 0, u_1, w_1, w_8, w_6) \\
	&\qquad\qquad + F^{(\beta)}_1(S/4, u_2, u_1, 0, w_4, w_2, w_9)
		+ F^{(\beta)}_1(S/4, u_1, u_2, u_3, -w_7, -w_8, -w_9), \\
	G_2&=F^{(\beta)}_2(S/4, 0, u_3, u_2, w_7, w_5, w_3)
		+ F^{(\beta)}_2(S/4, u_3, 0, u_1, w_1, w_8, w_6) \\
	&\qquad\qquad + F^{(\beta)}_2(S/4, u_2, u_1, 0, w_4, w_2, w_9)
		+ F^{(\beta)}_2(S/4, u_1, u_2, u_3, -w_7, -w_8, -w_9),
\end{align*}
we have
\begin{equation}
	C_4^{(2)}(T)^2=\sup_{\substack{x\in\mathbb{R}^{12} \\ x\not=0\;\;\;}}\frac{G_1}{G_2},
	\quad x=(u_1,u_2,u_3,w_1,w_2,w_3,w_4,w_5,w_6,w_7,w_8,w_9). \label{C_4uw}
\end{equation}
Similarly, every $C_j^{(n)}(T)$ can be expressed as a solution to a finite-dimensional eigenvalue problem.

From a mathematical point of view, we are interested in whether $C_j^{(n)}(T)$ converge to
 $C_j(T)$, respectively, as $n$ is increases, but we cannot provide a proof yet.
However, from the numerical results of Section~\ref{Numerical_Results}, it seems to converge.

\section{Numerical verification by INTLAB} \label{Positive_Definiteness}
By using the results of Lemma~\ref{F1} and Lemma~\ref{F2} in the previous section,
 we were able to construct a concrete finite-dimensional generalized eigenvalue problem,
 and now we would like to evaluate these eigenvalues from above.

For this purpose, it is sufficient to know how to evaluate the upper bound of
$$
	\lambda=\sup_{x\not=0}\frac{x^T Ax}{x^T Bx}
$$
strictly for the real symmetric matrix $A$ and the real symmetric positive definite matrix $B$.

Now, since
\begin{equation}
	\lambda'>\lambda \qquad \Longleftrightarrow \qquad \lambda'B-A \quad \text{is positive definite}, \label{positive_definite}
\end{equation}
to show that a given real number $\lambda'$ is an upper bound on the eigenvalues of a finite-dimensional
 generalized eigenvalue problem, it is sufficient to show the positive definiteness of the real symmetric matrix $\lambda'B-A$.

There are various ways to perform the numerical verification method on a computer;
however, for portability and ease of programming, we utilized INTLAB, which Professor Rump developed at the Technical University of Hamburg.
INTLAB is developed as a toolbox for MATLAB and can be installed in addition to MATLAB.
For more information on INTLAB, see \cite{Rump2,MooreKearfottCloud}.

In the numerical verification method, variables are given as intervals.
In INTLAB, the function {\tt isspd()} is used to verify the positive definiteness of a symmetric matrix
whose components are given as intervals.

For the set of symmetric matrices stated by intervals as
$$
	A=\left(\left[\overline{a_{ij}},\;\underline{a_{ij}}\right]\right)
		=\left\{Y=(y_{ij})\;\Big|\;y_{ij}\in\left[\overline{a_{ij}},\;\underline{a_{ij}}\right],\; y_{ij}\in\mathbb{R}\right\},
$$
if the returned value of {\tt isspd(A)} is 1, then all real symmetric matrices contained in $A$ are strictly verified to be positive definite.
If they cannot be verified to be positive definite, then {\tt isspd(A)} returns 0.
See {\cite{Rump1} for the algorithm used inside the function {\tt isspd()}.

Using the method described above, we can obtain mathematically rigorous proofs of the following two theorems:
\begin{theorem} \label{Verified_Result1}
Define $\{x_k\}$ and $\{y_k\}$ as follows:
$$
	y_1=1000, \qquad y_{k+1}=\left\lfloor \frac{51}{50}y_k \right\rfloor,
	\qquad x_{k}= \left\lceil \frac{y_k}{40} \right\rceil
$$
where $\lfloor\cdot\rfloor$ is the floor function and $\lceil\cdot\rceil$ is the ceiling function.
Then, for
$$
	n=20, \qquad b_k = \frac{1000}{y_k},\qquad a_{kl} = \frac{l}{2x_k},
$$
the following inequality holds for all $k=1,2,\dots,119,\quad l=0,1,\dots,x_k$:
\begin{align*}
	\frac{n^2}{n^2-1}C_j^{(n)}(T_{a_{kl},b_k})^2&\left(1+5\cdot\frac{1}{50^2}\right)\left(1+3\cdot\frac{1}{50^2}\right)< L_j(a_{kl},b_k), \qquad j=1,2, \\
	\frac{n^4}{n^4-1}C_3^{(n)}(T_{a_{kl},b_k})^2&\left(1+6\cdot\frac{1}{50^2}\right)\left(1+8\cdot\frac{1}{50^2}\right)< L_3(a_{kl},b_k), \\
	\left(C_4^{(n)}(T_{a_{kl},b_k})^2+\frac{L_2(a_{kl},b_k)}{n^2}\right)&\left(1+9\cdot\frac{1}{50^2}\right)\left(1+9\cdot\frac{1}{50^2}\right)< L_4(a_{kl},b_k).
\end{align*}
\end{theorem}
Fig.~\ref{Points} shows the distribution of $(a_{kl}, b_k)$.

