Note that $a_1,a_2,b_1,b_2$ are different from $a_k$ and $b_k$ used in Theorem~\ref{Verified_Result1}
and Theorem~\ref{Verified_Result2}.

In the following, we show that when evaluations of $C_j(T_{a,b})$
have been obtained for two triangles of slightly different shapes, we can also obtain a slightly milder evaluation
for triangles of intermediate shapes between.

Specifically, the purpose of this section is to prove the following two theorems:
\begin{theorem} \label{a-interpolation}
It holds that
\begin{align*}
	\frac{C_j(T_{a,b})^2}{L_j(a,b)}&\le (1+5h_a^2)\max_{k=1,2}\frac{C_j(T_{a_k,b})^2}{L_j(a_k,b)}, \qquad j=1,2, \\
	\frac{C_3(T_{a,b})^2}{L_3(a,b)}&\le (1+6h_a^2)\max_{k=1,2}\frac{C_3(T_{a_k,b})^2}{L_3(a_k,b)}, \\
	\frac{C_4(T_{a,b})^2}{L_4(a,b)}&\le (1+9h_a^2)\max_{k=1,2}\frac{C_4(T_{a_k,b})^2}{L_4(a_k,b)}.
\end{align*}
\end{theorem}

\begin{theorem} \label{b-interpolation}
It holds that
\begin{align*}
	\frac{C_j(T_{a,b})^2}{L_j(a,b)}&\le (1+3h_b^2)\max_{k=1,2}\frac{C_j(T_{a,b_k})^2}{L_j(a,b_k)}, \qquad j=1,2, \\
	\frac{C_3(T_{a,b})^2}{L_3(a,b)}&\le (1+8h_b^2)\max_{k=1,2}\frac{C_3(T_{a,b_k})^2}{L_3(a,b_k)}, \\
	\frac{C_4(T_{a,b})^2}{L_4(a,b)}&\le (1+9h_b^2)\max_{k=1,2}\frac{C_4(T_{a,b_k})^2}{L_4(a,b_k)}.
\end{align*}
\end{theorem}
These two theorems enable us to extend the results presented for a finite number of triangles to continuously distributed triangles.

The following lemma is used to prove Theorem~\ref{a-interpolation} and Theorem~\ref{b-interpolation}.
\begin{lemma} \label{BoundConstants}
For $j=1,2,3,4$, it holds that
\begin{align*}
	\left|\frac{\partial L_j}{\partial a}(a,b)\right|&< \frac{\alpha_{j1}}{b}L_j(a,b),
		& \frac{\partial^2 L_j}{\partial a^2}(\widetilde{a},b)&<\frac{\alpha_{j2}}{b^2}L_j(a,b), \\
	\left|\frac{\partial L_j}{\partial b}(a,b)\right|&< \frac{\beta_{j1}}{b}L_j(a,b),
		& \frac{\partial^2 L_j}{\partial b^2}(a,\widetilde{b})&<\frac{\beta_{j2}}{b^2}L_j(a,b),
\end{align*}
where
$$
	|\widetilde{a}-a|\le \frac{b}{50},\qquad |\widetilde{b}-b|\le \frac{b}{50}
$$
and
\begin{align*}
	\alpha_{j1}&=2, & \alpha_{j2}&=5,  & \beta_{j1}&=2, & \beta_{j2}&=4,  & j=1,2, \\
	\alpha_{31}&=2, & \alpha_{32}&=4, & \beta_{31}&=3, & \beta_{32}&=8, \\
	\alpha_{41}&=3, & \alpha_{42}&=9, & \beta_{41}&=3, & \beta_{42}&=9.
\end{align*}
\end{lemma}
The proof of this Lemma comes down to showing the positivity of the multivariate polynomials;
since there is no intrinsic difficulty, we have proved it in the Appendix 1 (Section~\ref{Appendix1}) separately for
 Lemma~\ref{L1-bound} to Lemma~\ref{L4-bound}.

\begin{proof}[Proof of Theorem~\ref{a-interpolation}]
In this proof, for $k=1,2$, we take
$$
	u^{(k)}(x,y)=u\left(x+\frac{a-a_k}{b}y,y\right).
$$

For $u\in L^2(T_{a,b})$, from
$$
	\|u^{(k)}\|_{L^2(T_{a_k,b})}^2=\|u\|_{L^2(T_{a,b})}^2,
$$
we have
\begin{equation}
\frac{a_2-a}{a_2-a_1}\|u^{(1)}\|_{L^2(T_{a_1,b})}^2+\frac{a-a_1}{a_2-a_1}\|u^{(2)}\|_{L^2(T_{a_2,b})}^2
		=\|u\|_{L^2(T_{a,b})}^2 \label{a-L2-1}
\end{equation}
and for $u\in H^1(T_{a,b})$, from
\begin{align*}
	\|\nabla u^{(k)}\|_{L^2(T_{a_k,b})}^2&=\|u_x\|_{L^2(T_{a,b})}^2+\left\|\frac{a-a_k}{b}u_x+u_y\right\|_{L^2(T_{a,b})}^2 \\
	&=\|\nabla u\|_{L^2(T_{a,b})}^2+\frac{2(a-a_k)}{b}(u_x,u_y)_{L^2(T_{a,b})} + \frac{(a-a_k)^2}{b^2}\|u_x\|_{L^2(T_{a,b})}^2,
\end{align*}
we have
\begin{align}
	&\frac{a_2-a}{a_2-a_1}\|\nabla u^{(1)}\|_{L^2(T_{a_1,b})}^2+\frac{a-a_1}{a_2-a_1}\|\nabla u^{(2)}\|_{L^2(T_{a_2,b})}^2 \label{a-H1-1}\\
	&\qquad =\|\nabla u\|_{L^2(T_{a,b})}^2+\frac{(a-a_1)(a_2-a)}{b^2}\|u_x\|_{L^2(T_{a,b})}^2 \notag\\
	&\qquad \ge\|\nabla u\|_{L^2(T_{a,b})}^2. \notag
\end{align}

For $u\in H^1(T_{a,b})$,
\begin{align}
	\|\nabla u^{(k)}\|_{L^2(T_{a_k,b})}^2&=\|u_x\|_{L^2(T_{a,b})}^2+\left\|\frac{a-a_k}{b}u_x+u_y\right\|_{L^2(T_{a,b})}^2 \label{a-H1-2}\\
		&=\|\nabla u\|_{L^2(T_{a,b})}^2+\frac{2(a-a_k)}{b}(u_x,u_y)_{L^2(T_{a,b})} + \frac{(a-a_k)^2}{b^2}\|u_x\|_{L^2(T_{a,b})}^2 \notag\\
		&\le\|\nabla u\|_{L^2(T_{a,b})}^2+\frac{2(a-a_k)}{b}(u_x,u_y)_{L^2(T_{a,b})} + \frac{(a-a_k)^2}{b^2}\|\nabla u\|_{L^2(T_{a,b})}^2 \notag\\
		&\le(1+h_a^2)\|\nabla u\|_{L^2(T_{a,b})}^2+\frac{2(a-a_k)}{b}(u_x,u_y)_{L^2(T_{a,b})}, \notag
\end{align}
and for $u\in H^2(T_{a,b})$,
\begin{align}
	|u^{(k)}|_{H^2(T_{a_k,b})}^2&=\|u_{xx}\|_{L^2(T_{a,b})}^2+2\left\|\frac{a-a_k}{b}u_{xx}+u_{xy}\right\|_{L^2(T_{a,b})}^2 \label{a-H2-2}\\
			&\qquad\qquad\qquad\qquad + \left\|\frac{(a-a_k)^2}{b^2}u_{xx}+\frac{2(a-a_k)}{b}u_{xy}+u_{yy}\right\|_{L^2(T_{a,b})}^2 \notag\\
		&=|u|_{H^2(T_{a,b})}^2+\frac{4(a-a_k)}{b}(\Delta u,u_{xy})_{L^2(T_{a,b})} \notag\\
			&\qquad + \frac{2(a-a_k)^2}{b^2}\Big(\|u_{xx}\|_{L^2(T_{a,b})}^2 + 2\|u_{xy}\|_{L^2(T_{a,b})}^2 + (u_{xx},u_{yy})_{L^2(T_{a,b})}\Big) \notag\\
			&\qquad + \frac{4(a-a_k)^3}{b^3}(u_{xx},u_{xy})_{L^2(T_{a,b})} + \frac{(a-a_k)^4}{b^4}\|u_{xx}\|_{L^2(T_{a,b})}^2 \notag\\
		&\le |u|_{H^2(T_{a,b})}^2+\frac{4(a-a_k)}{b}(\Delta u,u_{xy})_{L^2(T_{a,b})} \notag\\
			&\qquad + \frac{2(a-a_k)^2}{b^2}\left(\frac{6}{5}\|u_{xx}\|_{L^2(T_{a,b})}^2 + 2\|u_{xy}\|_{L^2(T_{a,b})}^2 + \frac{5}{4}\|u_{yy}\|_{L^2(T_{a,b})}^2\right) \notag\\
			&\qquad + \frac{4|a-a_k|^3}{b^3}\left(\frac{1}{4}\|u_{xx}\|_{L^2(T_{a,b})}^2 + \|u_{xy}\|_{L^2(T_{a,b})}^2\right) \notag\\
			&\qquad + \frac{(a-a_k)^4}{b^4}\|u_{xx}\|_{L^2(T_{a,b})}^2 \notag\\
		&\le |u|_{H^2(T_{a,b})}^2+\frac{4(a-a_k)}{b}(\Delta u,u_{xy})_{L^2(T_{a,b})} \notag\\
			&\qquad + \frac{2(a-a_k)^2}{b^2}\left(\frac{6}{5}\|u_{xx}\|_{L^2(T_{a,b})}^2 + 2\|u_{xy}\|_{L^2(T_{a,b})}^2 + \frac{5}{4}\|u_{yy}\|_{L^2(T_{a,b})}^2\right) \notag\\
			&\qquad + \frac{4(a-a_k)^2}{50b^2}\left(\frac{1}{4}\|u_{xx}\|_{L^2(T_{a,b})}^2 + \|u_{xy}\|_{L^2(T_{a,b})}^2\right) \notag\\
			&\qquad + \frac{(a-a_k)^2}{50^2b^2}\|u_{xx}\|_{L^2(T_{a,b})}^2 \notag\\
		&=|u|_{H^2(T_{a,b})}^2+\frac{4(a-a_k)}{b}(\Delta u,u_{xy})_{L^2(T_{a,b})} \notag\\
			&\qquad + \frac{(a-a_k)^2}{b^2}\left(\frac{6051}{2500}\|u_{xx}\|_{L^2(T_{a,b})}^2 + \frac{102}{25}\|u_{xy}\|_{L^2(T_{a,b})}^2 + \frac{5}{2}\|u_{yy}\|_{L^2(T_{a,b})}^2\right) \notag\\
		&\le |u|_{H^2(T_{a,b})}^2+\frac{4(a-a_k)}{b}(\Delta u,u_{xy})_{L^2(T_{a,b})} + \frac{5(a-a_k)^2}{2b^2}|u|_{H^2(T_{a,b})}^2 \notag\\
		&\le \left(1+\frac{5}{2}h_a^2\right)|u|_{H^2(T_{a,b})}^2+\frac{4(a-a_k)}{b}(\Delta u,u_{xy})_{L^2(T_{a,b})}. \notag
\end{align}

Here, by Taylor's theorem, for each $j=1,2,3,4$ and $k=1,2$, there exist $a_1\le \widetilde{a}\le a_2$ such that
$$
	L_j(a_k,b)=L_j(a,b)+(a_k-a)\frac{\partial L_j}{\partial a}(a,b)+\frac{(a_k-a)^2}{2}\cdot\frac{\partial^2 L_j}{\partial a^2}(\widetilde{a},b)
$$
holds.

Then using
$$
	|\widetilde{a}-a|\le|a_2-a_1|\le\frac{b}{50}
$$
and Lemma~\ref{BoundConstants}, we have
\begin{align}
	L_j(a_k,b)&\le L_j(a,b)+(a_k-a)\frac{\partial L_j}{\partial a}(a,b)+\frac{\alpha_{j2}(a_k-a)^2}{2b^2}L_j(a,b) \label{a-Lj}\\
	&\le \left(1+\frac{\alpha_{j2}}{2}h_a^2\right)L_j(a,b)-(a-a_k)\frac{\partial L_j}{\partial a}(a,b). \notag
\end{align}

For $u\in V^{1,j},\;j=1,2$, \eqref{a-H1-2}, \eqref{a-Lj} and Lemma~\ref{BoundConstants} yields
\begin{align*}
	&\frac{a_2-a}{a_2-a_1}L_j(a_1,b)\|\nabla u^{(1)}\|_{L^2(T_{a_1,b})}^2
		+\frac{a-a_1}{a_2-a_1}L_j(a_2,b)\|\nabla u^{(2)}\|_{L^2(T_{a_2,b})}^2 \\
	&\le\frac{a_2-a}{a_2-a_1}\left\{\left(1+\frac{\alpha_{j2}}{2}h_a^2\right)L_j(a,b)-(a-a_1)\frac{\partial L_j}{\partial a}(a,b)\right\} \\
		&\qquad\qquad\qquad \times\left((1+h_a^2)\|\nabla u\|_{L^2(T_{a,b})}^2+\frac{2(a-a_1)}{b}(u_x,u_y)_{L^2(T_{a,b})}\right) \\
		&\qquad +\frac{a-a_1}{a_2-a_1}\left\{\left(1+\frac{\alpha_{j2}}{2}h_a^2\right)L_j(a,b)-(a-a_2)\frac{\partial L_j}{\partial a}(a,b)\right\}\ \\
		&\qquad\qquad\qquad \times\left((1+h_a^2)\|\nabla u\|_{L^2(T_{a,b})}^2+\frac{2(a-a_2)}{b}(u_x,u_y)_{L^2(T_{a,b})}\right) \\
	&=(1+h_a^2)\left(1+\frac{\alpha_{j2}}{2}h_a^2\right)L_j(a,b)\|\nabla u\|_{L^2(T_{a,b})}^2 \\
		&\qquad\qquad - \frac{2(a-a_1)(a_2-a)}{b}\cdot\frac{\partial L_j}{\partial a}(a,b)\cdot(u_x,u_y)_{L^2(T_{a,b})} \\
	&\le(1+h_a^2)\left(1+\frac{\alpha_{j2}}{2}h_a^2\right)L_j(a,b)\|\nabla u\|_{L^2(T_{a,b})}^2 \\
		&\qquad\qquad + \frac{(a_2-a_1)^2}{2b^2}\cdot\alpha_{j1}L_j(a,b)\cdot\frac{\|\nabla u\|_{L^2(T_{a,b})}^2}{2} \\
	&\le(1+h_a^2)\left(1+\frac{\alpha_{j2}}{2}h_a^2\right)L_j(a,b)\|\nabla u\|_{L^2(T_{a,b})}^2
		+ \frac{\alpha_{j1}h_a^2}{4}L_j(a,b)\|\nabla u\|_{L^2(T_{a,b})}^2 \\
	&=\left\{1+\frac{h_a^2}{4}\Big(4+\alpha_{j1}+2\alpha_{j2}(1+h_a^2)\Big)\right\}L_j(a,b)\|\nabla u\|_{L^2(T_{a,b})}^2 \\
	&\le\left\{1+\frac{h_a^2}{4}\left(4+2+2\cdot5\left(1+\frac{1}{50^2}\right)\right)\right\}L_j(a,b)\|\nabla u\|_{L^2(T_{a,b})}^2 \\
	&=\left(1+\frac{4001}{1000}h_a^2\right)L_j(a,b)\|\nabla u\|_{L^2(T_{a,b})}^2 \\
	&\le(1+5h_a^2)L_j(a,b)\|\nabla u\|_{L^2(T_{a,b})}^2
\end{align*}

By this result and \eqref{a-L2-1}, we have
\begin{align*}
	\|u\|_{L^2(T_{a,b})}^2&=\frac{a_2-a}{a_2-a_1}\|u^{(1)}\|_{L^2(T_{a_1,b})}^2+\frac{a-a_1}{a_2-a_1}\|u^{(2)}\|_{L^2(T_{a_2,b})}^2 \\
	&\le\frac{a_2-a}{a_2-a_1}C_j(T_{a_1,b})^2\|\nabla u^{(1)}\|_{L^2(T_{a_1,b})}^2+\frac{a-a_1}{a_2-a_1}C_j(T_{a_2,b})^2\|\nabla u^{(2)}\|_{L^2(T_{a_2,b})}^2 \\
	&\le\max_{k=1,2}\frac{C_j(T_{a_k,b})^2}{L_j(a_k,b)}\left(\frac{a_2-a}{a_2-a_1}L_j(a_1,b)\|\nabla u^{(1)}\|_{L^2(T_{a_1,b})}^2+\frac{a-a_1}{a_2-a_1}L_j(a_2,b)\|\nabla u^{(2)}\|_{L^2(T_{a_2,b})}^2\right) \\
	&\le\max_{k=1,2}\frac{C_j(T_{a_k,b})^2}{L_j(a_k,b)}(1+5h_a^2)L_j(a,b)\|\nabla u\|_{L^2(T_{a,b})}^2.
\end{align*}
Then, considering the definitions of $C_j(T),\; j=1,2$, we have
$$
	\frac{C_j(T_{a,b})^2}{L_j(a,b)}\le(1+5h_a^2)\max_{k=1,2}\frac{C_j(T_{a_k,b})^2}{L_j(a_k,b)}.
$$

For $u\in V^2,\;j=3,4$, \eqref{a-H2-2}, \eqref{a-Lj} and Lemma~\ref{BoundConstants} yields
\begin{align*}
	&\frac{a_2-a}{a_2-a_1}L_j(a_1,b)|u^{(1)}|_{H^2(T_{a_1,b})}^2
		+\frac{a-a_1}{a_2-a_1}L_j(a_2,b)|u^{(2)}|_{H^2(T_{a_2,b})}^2 \\
	&\le\frac{a_2-a}{a_2-a_1}\left\{\left(1+\frac{\alpha_{j2}}{2}h_a^2\right)L_j(a,b)-(a-a_1)\frac{\partial L_j}{\partial a}(a,b)\right\} \\
		&\qquad\qquad\qquad \times\left\{\left(1+\frac{5}{2}h_a^2\right)|u|_{H^2(T_{a,b})}^2+\frac{4(a-a_1)}{b}(\Delta u,u_{xy})_{L^2(T_{a,b})}\right\} \\
		&\qquad +\frac{a-a_1}{a_2-a_1}\left\{\left(1+\frac{\alpha_{j2}}{2}h_a^2\right)L_j(a,b)-(a-a_2)\frac{\partial L_j}{\partial a}(a,b)\right\}\ \\
		&\qquad\qquad\qquad \times\left\{\left(1+\frac{5}{2}h_a^2\right)|u|_{H^2(T_{a,b})}^2+\frac{4(a-a_2)}{b}(\Delta u,u_{xy})_{L^2(T_{a,b})}\right\} \\
	&=\left(1+\frac{5}{2}h_a^2\right)\left(1+\frac{\alpha_{j2}}{2}h_a^2\right)L_j(a,b)|u|_{H^2(T_{a,b})}^2 \\
		&\qquad\qquad - \frac{4(a-a_1)(a_2-a)}{b}\cdot\frac{\partial L_j}{\partial a}(a,b)\cdot(\Delta u,u_{xy})_{L^2(T_{a,b})} \\
	&\le\left(1+\frac{5}{2}h_a^2\right)\left(1+\frac{\alpha_{j2}}{2}h_a^2\right)L_j(a,b)|u|_{H^2(T_{a,b})}^2
		+ \frac{(a_2-a_1)^2}{b^2}\alpha_{j1}L_j(a,b)\cdot\frac{|u|_{H^2(T_{a,b})}^2}{2} \\
	&\le\left(1+\frac{5}{2}h_a^2\right)\left(1+\frac{\alpha_{j2}}{2}h_a^2\right)L_j(a,b)|u|_{H^2(T_{a,b})}^2
		+ \frac{\alpha_{j1}h_a^2}{2}L_j(a,b)|u|_{H^2(T_{a,b})}^2 \\
	&=\left\{1+\frac{h_a^2}{4}\Big(10+2\alpha_{j1}+\alpha_{j2}(2+5h_a^2)\Big)\right\}L_j(a,b)|u|_{H^2(T_{a,b})}^2.
\end{align*}
Then, for $j=3$, we have
\begin{align*}
	&\frac{a_2-a}{a_2-a_1}L_3(a_1,b)|u^{(1)}|_{H^2(T_{a_1,b})}^2
		+\frac{a-a_1}{a_2-a_1}L_3(a_2,b)|u^{(2)}|_{H^2(T_{a_2,b})}^2 \\
	&\le\left\{1+\frac{h_a^2}{4}\left(10+2\cdot2+4\left(2+\frac{5}{50^2}\right)\right)\right\}L_3(a,b)|u|_{H^2(T_{a,b})}^2 \\
	&= \left(1+\frac{2751}{500}h_a^2\right)L_3(a,b)|u|_{H^2(T_{a,b})}^2 \\
	&\le(1+6h_a^2)L_3(a,b)|u|_{H^2(T_{a,b})}^2,
\end{align*}
and consequently, by \eqref{a-L2-1},
\begin{align*}
	\|u\|_{L^2(T_{a,b})}^2&=\frac{a_2-a}{a_2-a_1}\|u^{(1)}\|_{L^2(T_{a_1,b})}^2+\frac{a-a_1}{a_2-a_1}\|u^{(2)}\|_{L^2(T_{a_2,b})}^2 \\
	&\le\frac{a_2-a}{a_2-a_1}C_3(T_{a_1,b})^2|u^{(1)}|_{H^2(T_{a_1,b})}^2+\frac{a-a_1}{a_2-a_1}C_3(T_{a_2,b})^2|u^{(2)}|_{H^2(T_{a_2,b})}^2 \\
	&\le\max_{k=1,2}\frac{C_3(T_{a_k,b})^2}{L_3(a_k,b)}\left(\frac{a_2-a}{a_2-a_1}L_3(a_1,b)|u^{(1)}|_{H^2(T_{a_1,b})}^2+\frac{a-a_1}{a_2-a_1}L_3(a_2,b)|u^{(2)}|_{H^2(T_{a_2,b})}^2\right) \\
	&\le\max_{k=1,2}\frac{C_3(T_{a_k,b})^2}{L_3(a_k,b)}(1+6h_a^2)L_3(a,b)|u|_{H^2(T_{a,b})}^2
\end{align*}
holds.
Then, considering the definitions of $C_3(T)$, we have
$$
	\frac{C_3(T_{a,b})^2}{L_3(a,b)}\le (1+8h_b^2)\max_{k=1,2}\frac{C_3(T_{a,b_k})^2}{L_3(a,b_k)}.
$$

For $j=4$, we have
\begin{align*}
	&\frac{a_2-a}{a_2-a_1}L_4(a_1,b)|u^{(1)}|_{H^2(T_{a_1,b})}^2
		+\frac{a-a_1}{a_2-a_1}L_4(a_2,b)|u^{(2)}|_{H^2(T_{a_2,b})}^2 \\
	&\le \left\{1+\frac{h_a^2}{4}\left(10+2\cdot3+9\left(2+\frac{5}{50^2}\right)\right)\right\}L_4(a,b)|u|_{H^2(T_{a,b})}^2 \\
	&\le \left(1+\frac{17009}{2000}h_a^2\right)L_4(a,b)|u|_{H^2(T_{a,b})}^2 \\
	&\le(1+9h_a^2)L_4(a,b)|u|_{H^2(T_{a,b})}^2,
\end{align*}
and consequently, by \eqref{a-H1-1},
\begin{align*}
	\|\nabla u\|_{L^2(T_{a,b})}^2&\le\frac{a_2-a}{a_2-a_1}\|\nabla u^{(1)}\|_{L^2(T_{a_1,b})}^2+\frac{a-a_1}{a_2-a_1}\|\nabla u^{(2)}\|_{L^2(T_{a_2,b})}^2 \\
	&\le\frac{a_2-a}{a_2-a_1}C_4(T_{a_1,b})^2|u^{(1)}|_{H^2(T_{a_1,b})}^2+\frac{a-a_1}{a_2-a_1}C_4(T_{a_2,b})^2|u^{(2)}|_{H^2(T_{a_2,b})}^2 \\
	&\le\max_{k=1,2}\frac{C_4(T_{a_k,b})^2}{L_4(a_k,b)}\left(\frac{a_2-a}{a_2-a_1}L_4(a_1,b)|u^{(1)}|_{H^2(T_{a_1,b})}^2+\frac{a-a_1}{a_2-a_1}L_4(a_2,b)|u^{(2)}|_{H^2(T_{a_2,b})}^2\right) \\
	&\le\max_{k=1,2}\frac{C_4(T_{a_k,b})^2}{L_4(a_k,b)}(1+9h_a^2)L_4(a,b)|u|_{H^2(T_{a,b})}^2
\end{align*}
holds.
Then, considering the definitions of $C_4(T)$, we have
$$
	\frac{C_4(T_{a,b})^2}{L_4(a,b)}\le (1+9h_b^2)\max_{k=1,2}\frac{C_4(T_{a,b_k})^2}{L_4(a,b_k)}.
$$
\end{proof}


\begin{proof}[Proof of theorem~\ref{b-interpolation}]
In this proof, for $k=1,2$, we take
$$
	u^{(k)}(x,y)=u\left(x,\frac{b}{b_k}y\right).
$$

For $u\in L^2(T_{a,b})$, from
$$
	\|u^{(k)}\|_{L^2(T_{a,b_k})}^2=\frac{b_k}{b}\|u\|_{L^2(T_{a,b})}^2
$$
we have
\begin{equation}
	\frac{b_2-b}{b_2-b_1}\|u^{(1)}\|_{L^2(T_{a,b_1})}^2+\frac{b-b_1}{b_2-b_1}\|u^{(2)}\|_{L^2(T_{a,b_2})}^2
		=\|u\|_{L^2(T_{a,b})}^2 \label{b-L2-1}
\end{equation}
and for $u\in H^1(T_{a,b})$, from
\begin{equation}
	\|\nabla u^{(k)}\|_{L^2(T_{a,b_k})}^2=\frac{b_k}{b}\|u_x\|_{L^2(T_{a,b})}^2+\frac{b}{b_k}\|u_y\|_{L^2(T_{a,b})}^2 \label{b-H1-2}
\end{equation}
we have
\begin{align}
	&\frac{b_2-b}{b_2-b_1}\|\nabla u^{(1)}\|_{L^2(T_{a,b_1})}^2+\frac{b-b_1}{b_2-b_1}\|\nabla u^{(2)}\|_{L^2(T_{a,b_2})}^2 \label{b-H1-1}\\
	&\qquad =\|\nabla u\|_{L^2(T_{a,b})}^2+\frac{(b-b_1)(b_2-b)}{b_1b_2}\|u_y\|_{L^2(T_{a,b})}^2 \notag\\
	&\qquad \ge\|\nabla u\|_{L^2(T_{a,b})}^2. \notag
\end{align}

For $u\in H^2(T_{a,b})$, we have
\begin{equation}
	|u^{(k)}|_{H^2(T_{a,b_k})}^2=\frac{b_k}{b}\|u_{xx}\|_{L^2(T_{a,b})}^2
		+ \frac{2b}{b_k}\|u_{xy}\|_{L^2(T_{a,b})}^2 + \frac{b^3}{b_k^3}\|u_{yy}\|_{L^2(T_{a,b})}^2. \label{b-H2-2}
\end{equation}

Here, by Taylor's theorem, for each $j=1,2,3,4$ and $k=1,2$, there exist $b_1\le \widetilde{b}\le b_2$ such that
$$
	L_j(a,b_k)=L_j(a,b)+(b_k-b)\frac{\partial L_j}{\partial b}(a,b)+\frac{(b_k-b)^2}{2}\cdot\frac{\partial^2 L_j}{\partial b^2}(a,\widetilde{b})
$$
holds.
Then using
$$
	|\widetilde{b}-b|\le|b_2-b_1|\le\frac{b_1}{50}\le\frac{b}{50}
$$
and Lemma~\ref{BoundConstants}, we have
\begin{align}
	L_j(a,b_k)&\le L_j(a,b)+(b_k-b)\frac{\partial L_j}{\partial b}(a,b)+\frac{\beta_{j2}(b_k-b)^2}{2b^2}L_j(a,b) \label{b-Lj}\\
	&\le \left(1+\frac{\beta_{j2}}{2}h_b^2\right)L_j(a,b)+(b_k-b)\frac{\partial L_j}{\partial b}(a,b). \notag
\end{align}

For $u\in V^{1,j},\;j=1,2$, \eqref{b-H1-2}, \eqref{b-Lj} and Lemma~\ref{BoundConstants} yields
\begin{align*}
	&\frac{b_2-b}{b_2-b_1}L_j(a,b_1)\|\nabla u^{(1)}\|_{L^2(T_{a,b_1})}^2
		+\frac{b-b_1}{b_2-b_1}L_j(a,b_2)\|\nabla u^{(2)}\|_{L^2(T_{a,b_2})}^2 \\
	&\le\frac{b_2-b}{b_2-b_1}\left\{\left(1+\frac{\beta_{j2}}{2}h_b^2\right)L_j(a,b)+(b_1-b)\frac{\partial L_j}{\partial b}(a,b)\right\} \\
		&\qquad\qquad\qquad\qquad \times\left(\frac{b_1}{b}\|u_x\|_{L^2(T_{a,b})}^2+\frac{b}{b_1}\|u_y\|_{L^2(T_{a,b})}^2\right) \\
		&\qquad +\frac{b-b_1}{b_2-b_1}\left\{\left(1+\frac{\beta_{j2}}{2}h_b^2\right)L_j(a,b)+(b_2-b)\frac{\partial L_j}{\partial b}(a,b)\right\} \\
		&\qquad\qquad\qquad\qquad \times\left(\frac{b_2}{b}\|u_x\|_{L^2(T_{a,b})}^2+\frac{b}{b_2}\|u_y\|_{L^2(T_{a,b})}^2\right) \\
	&=\left(1+\frac{\beta_{j2}}{2}h_b^2\right)L_j(a,b)\|\nabla u\|_{L^2(T_{a,b})}^2
		+ (b-b_1)(b_2-b)\left\{\frac{2+\beta_{j2}h_b^2}{2b_1b_2}L_j(a,b)\|u_y\|_{L^2(T_{a,b})}^2\right. \\
		&\qquad\qquad\left. +b\cdot\frac{\partial L_j}{\partial b}(a,b)\left(	\frac{1}{b^2}\|u_x\|_{L^2(T_{a,b})}^2
		-\frac{1}{b_1b_2}\|u_y\|_{L^2(T_{a,b})}^2\right) \right\} \\
	&\le\left(1+\frac{\beta_{j2}}{2}h_b^2\right)L_j(a,b)\|\nabla u\|_{L^2(T_{a,b})}^2 \\
		&\qquad\qquad +\frac{(b_2-b_1)^2}{4}L_j(a,b)\left\{\frac{\beta_{j1}}{b_1^2}\|u_x\|_{L^2(T_{a,b})}^2
		+\frac{2+2\beta_{j1}+\beta_{j2}h_b^2}{2b_1^2}\|u_y\|_{L^2(T_{a,b})}^2 \right\} \\
	&\le\left(1+\frac{\beta_{j2}}{2}h_b^2\right)L_j(a,b)\|\nabla u\|_{L^2(T_{a,b})}^2
		+\frac{h_b^2}{8}\Big(2+2\beta_{j1}+\beta_{j2}h_b^2\Big)L_j(a,b)\|\nabla u\|_{L^2(T_{a,b})}^2 \\
	&\le\left\{1+\frac{h_b^2}{8}\Big(2+2\beta_{j1}+\beta_{j2}(4+h_b^2)\Big)\right\}L_j(a,b)\|\nabla u\|_{L^2(T_{a,b})}^2 \\
	&\le \left\{1+\frac{h_b^2}{8}\left(2+2\cdot2+4\left(4+\frac{1}{50^2}\right)\right)\right\}L_j(a,b)\|\nabla u\|_{L^2(T_{a,b})}^2 \\
	&=\left(1+\frac{13751}{5000}h_b^2\right)L_j(a,b)\|\nabla u\|_{L^2(T_{a,b})}^2 \\
	&\le(1+3h_b^2)L_j(a,b)\|\nabla u\|_{L^2(T_{a,b})}^2
\end{align*}

By this result and \eqref{b-L2-1}, we have
\begin{align*}
	\|u\|_{L^2(T_{a,b})}^2&=\frac{b_2-b}{b_2-b_1}\|u^{(1)}\|_{L^2(T_{a,b_1})}^2+\frac{b-b_1}{b_2-b_1}\|u^{(2)}\|_{L^2(T_{a,b_2})}^2 \\
	&\le\frac{b_2-b}{b_2-b_1}C_j(T_{a,b_1})^2\|\nabla u^{(1)}\|_{L^2(T_{a,b_1})}^2+\frac{b-b_1}{b_2-b_1}C_j(T_{a,b_2})^2\|\nabla u^{(2)}\|_{L^2(T_{a,b_2})}^2 \\
	&\le\max_{k=1,2}\frac{C_j(T_{a,b_k})^2}{L_j(a,b_k)}\left(\frac{b_2-b}{b_2-b_1}L_j(a,b_1)\|\nabla u^{(1)}\|_{L^2(T_{a,b_1})}^2+\frac{b-b_1}{b_2-b_1}L_j(a,b_2)\|\nabla u^{(2)}\|_{L^2(T_{a,b_2})}^2\right) \\
	&\le\max_{k=1,2}\frac{C_j(T_{a,b_k})^2}{L_j(a,b_k)}(1+3h_b^2)L_j(a,b)\|\nabla u\|_{L^2(T_{a,b})}^2
\end{align*}
Then, considering the definitions of $C_j(T),\; j=1,2$, we have
$$
	\frac{C_j(T_{a,b})^2}{L_j(a,b)}\le(1+3h_b^2)\max_{k=1,2}\frac{C_j(T_{a,b_k})^2}{L_j(a,b_k)}.
$$

For $u\in V^2,\;j=3,4$, \eqref{b-H2-2}, \eqref{b-Lj} and Lemma~\ref{BoundConstants} yields
\begin{align*}
	&\frac{b_2-b}{b_2-b_1}L_j(a,b_1)|u^{(1)}|_{H^2(T_{a,b_1})}^2
		+\frac{b-b_1}{b_2-b_1}L_j(a,b_2)|u^{(2)}|_{H^2(T_{a,b_2})}^2 \\
	&\le\frac{b_2-b}{b_2-b_1}\left\{\left(1+\frac{\beta_{j2}}{2}h_b^2\right)L_j(a,b)+(b_1-b)\frac{\partial L_j}{\partial b}(a,b)\right\} \\
		&\qquad\qquad\qquad\qquad \times\left(\frac{b_1}{b}\|u_{xx}\|_{L^2(T_{a,b})}^2 + \frac{2b}{b_1}\|u_{xy}\|_{L^2(T_{a,b})}^2 + \frac{b^3}{b_1^3}\|u_{yy}\|_{L^2(T_{a,b})}^2\right) \\
		&\qquad +\frac{b-b_1}{b_2-b_1}\left\{\left(1+\frac{\beta_{j2}}{2}h_b^2\right)L_j(a,b)+(b_2-b)\frac{\partial L_j}{\partial b}(a,b)\right\} \\
		&\qquad\qquad\qquad\qquad \times\left(\frac{b_2}{b}\|u_{xx}\|_{L^2(T_{a,b})}^2 + \frac{2b}{b_2}\|u_{xy}\|_{L^2(T_{a,b})}^2 + \frac{b^3}{b_2^3}\|u_{yy}\|_{L^2(T_{a,b})}^2\right) \\
	&=\left(1+\frac{\beta_{j2}}{2}h_b^2\right)L_j(a,b)|u|_{H^2(T_{a,b})}^2 + (b-b_1)(b_2-b)\left\{\phantom{\left(\frac{1}{b^2}\right)}\right. \\
		&\qquad (2+\beta_{j2}h_b^2)L_j(a,b)\left(\frac{1}{b_1b_2}\|u_{xy}\|_{L^2(T_{a,b})}^2 \right. \\
		&\qquad\qquad\qquad\left. +\frac{b_1^2b_2^2 + b_1b_2(b_1+b_2)b + (b_1^2+b_1b_2+b_2^2)b^2}{2b_1^3b_2^3}\|u_{yy}\|_{L^2(T_{a,b})}^2\right) \\
		&\qquad\left. +b\cdot\frac{\partial L_j}{\partial b}(a,b)\left(\frac{1}{b^2}\|u_{xx}\|_{L^2(T_{a,b})}^2 - \frac{2}{b_1b_2}\|u_{xy}\|_{L^2(T_{a,b})}^2 - \frac{(b_1^2+b_1b_2+b_2^2)b^2}{b_1^3b_2^3}\|u_{yy}\|_{L^2(T_{a,b})}^2 \right)\right\} \\
	&\le \left(1+\frac{\beta_{j2}}{2}h_b^2\right)L_j(a,b)|u|_{H^2(T_{a,b})}^2 + \frac{(b_2-b_1)^2}{4}\left\{\phantom{\left(\frac{1}{b^2}\right)}\right. \\
		&\qquad (2+\beta_{j2}h_b^2)L_j(a,b)\left(\frac{1}{b_1^2}\|u_{xy}\|_{L^2(T_{a,b})}^2
		+\frac{3b_2}{b_1^3}\|u_{yy}\|_{L^2(T_{a,b})}^2\right) \\
		&\qquad\left. +\beta_{j1}L_j(a,b)\left(\frac{1}{b_1^2}\|u_{xx}\|_{L^2(T_{a,b})}^2 + \frac{2}{b_1^2}\|u_{xy}\|_{L^2(T_{a,b})}^2
		+ \frac{3b_2}{b_1^3}\|u_{yy}\|_{L^2(T_{a,b})}^2 \right)\right\} \\
	&\le \left(1+\frac{\beta_{j2}}{2}h_b^2\right)L_j(a,b)|u|_{H^2(T_{a,b})}^2 \\
	&\qquad\qquad + \frac{h_b^2}{4}\left\{
		(2+\beta_{j2}h_b^2)L_j(a,b)\left(\|u_{xy}\|_{L^2(T_{a,b})}^2+3(1+h_b)\|u_{yy}\|_{L^2(T_{a,b})}^2\right)\right. \\
		&\qquad\left. +\beta_{j1}L_j(a,b)\left(\|u_{xx}\|_{L^2(T_{a,b})}^2 + 2\|u_{xy}\|_{L^2(T_{a,b})}^2 + 3(1+h_b)\|u_{yy}\|_{L^2(T_{a,b})}^2 \right)\right\} \\
	&\le \left(1+\frac{\beta_{j2}}{2}h_b^2\right)L_j(a,b)|u|_{H^2(T_{a,b})}^2 + \frac{3h_b^2}{4} 
		(1+h_b)\Big(2+\beta_{j1}+\beta_{j2}h_b^2\Big)L_j(a,b)|u|_{H^2(T_{a,b})}^2 \\
	&=\left\{1+\frac{h_b^2}{4}\Big(3(2+\beta_{j1})(1+h_b)+\beta_{j2}(2+3h_b^2+3h_b^3)\Big)\right\}
		L_j(a,b)|u|_{H^2(T_{a,b})}^2
\end{align*}
Then, for $j=3$, we have
\begin{align*}
	&\frac{b_2-b}{b_2-b_1}L_3(a,b_1)|u^{(1)}|_{H^2(T_{a,b_1})}^2
		+\frac{b-b_1}{b_2-b_1}L_3(a,b_2)|u^{(2)}|_{H^2(T_{a,b_2})}^2 \\
	&\le \left\{1+\frac{h_b^2}{4}\left(3(2+3)\left(1+\frac{1}{50}\right)+8\left(2+\frac{3}{50^2}+\frac{3}{50^3}\right)\right)\right\}L_3(a,b)|u|_{H^2(T_{a,b})}^2 \\
	&=\left(1+\frac{978431}{125000}h_b^2\right)L_3(a,b)|u|_{H^2(T_{a,b})}^2 \\
	&\le(1+8h_b^2)L_3(a,b)|u|_{H^2(T_{a,b})}^2,
\end{align*}
and consequently, by \eqref{b-L2-1},
\begin{align*}
	\|u\|_{L^2(T_{a,b})}^2&=\frac{b_2-b}{b_2-b_1}\|u^{(1)}\|_{L^2(T_{a,b_1})}^2+\frac{b-b_1}{b_2-b_1}\|u^{(2)}\|_{L^2(T_{a,b_2})}^2 \\
	&\le\frac{b_2-b}{b_2-b_1}C_3(T_{a,b_1})^2|u^{(1)}|_{H^2(T_{a,b_1})}^2+\frac{b-b_1}{b_2-b_1}C_3(T_{a,b_2})^2|u^{(2)}|_{H^2(T_{a,b_2})}^2 \\
	&\le\max_{k=1,2}\frac{C_3(T_{a,b_k})^2}{L_3(a,b_k)}\left(\frac{b_2-b}{b_2-b_1}L_3(a,b_1)|u^{(1)}|_{H^2(T_{a,b_1})}^2+\frac{b-b_1}{b_2-b_1}L_3(a,b_2)|u^{(2)}|_{H^2(T_{a,b_2})}^2\right) \\
	&\le\max_{k=1,2}\frac{C_3(T_{a,b_k})^2}{L_3(a,b_k)}(1+8h_b^2)L_3(a,b)|u|_{H^2(T_{a,b})}^2
\end{align*}
holds.
Then, considering the definitions of $C_3(T)$, we have
$$
	\frac{C_3(T_{a,b})^2}{L_3(a,b)}\le (1+8h_b^2)\max_{k=1,2}\frac{C_3(T_{a,b_k})^2}{L_3(a,b_k)}.
$$

For $j=4$, we have
\begin{align*}
	&\frac{b_2-b}{b_2-b_1}L_4(a,b_1)|u^{(1)}|_{H^2(T_{a,b_1})}^2
		+\frac{b-b_1}{b_2-b_1}L_4(a,b_2)|u^{(2)}|_{H^2(T_{a,b_2})}^2 \\
	&\le \left\{1+\frac{h_b^2}{4}\left(3(2+3)\left(1+\frac{1}{50}\right)+9\left(2+\frac{3}{50^2}+\frac{3}{50^3}\right)\right)\right\}L_3(a,b)|u|_{H^2(T_{a,b})}^2 \\
	&=\left(1+\frac{4163877}{500000}h_b^2\right)L_4(a,b)|u|_{H^2(T_{a,b})}^2 \\
	&\le(1+9h_b^2)L_4(a,b)|u|_{H^2(T_{a,b})}^2
\end{align*}
and consequently, by \eqref{b-H1-1},
\begin{align*}
	\|\nabla u\|_{L^2(T_{a,b})}^2&\le\frac{b_2-b}{b_2-b_1}\|\nabla u^{(1)}\|_{L^2(T_{a,b_1})}^2+\frac{b-b_1}{b_2-b_1}\|\nabla u^{(2)}\|_{L^2(T_{a,b_2})}^2 \\
	&\le\frac{b_2-b}{b_2-b_1}C_4(T_{a,b_1})^2|u^{(1)}|_{H^2(T_{a,b_1})}^2+\frac{b-b_1}{b_2-b_1}C_4(T_{a,b_2})^2|u^{(2)}|_{H^2(T_{a,b_2})}^2 \\
	&\le\max_{k=1,2}\frac{C_4(T_{a,b_k})^2}{L_4(a,b_k)}\left(\frac{b_2-b}{b_2-b_1}L_4(a,b_1)|u^{(1)}|_{H^2(T_{a,b_1})}^2+\frac{b-b_1}{b_2-b_1}L_4(a,b_2)|u^{(2)}|_{H^2(T_{a,b_2})}^2\right) \\
	&\le\max_{k=1,2}\frac{C_4(T_{a,b_k})^2}{L_4(a,b_k)}(1+9h_b^2)L_4(a,b)|u|_{H^2(T_{a,b})}^2
\end{align*}
holds.
Then, considering the definitions of $C_4(T)$, we have
$$
	\frac{C_4(T_{a,b})^2}{L_4(a,b)}\le (1+9h_b^2)\max_{k=1,2}\frac{C_4(T_{a,b_k})^2}{L_4(a,b_k)}.
$$
\end{proof}

\section{Proof if the triangle is not significantly degenerate} \label{Non_Degenerate}
In this section, we will discuss the proof of Theorem~\ref{formula} when the triangle is not significantly degenerate,
namely, the following theorem holds.

\begin{theorem}
For $0\le a\le\dfrac{1}{2},\;\dfrac{1}{10}\le b\le 1$, it holds that
$$
	C_j(T_{a,b}) < K_j(T_{a,b}), \qquad j=1,2,3,4.
$$
\end{theorem}
\begin{proof}
From the fact that
$$
	0\le\frac{a_{k\;l+1}-a_{kl}}{b_k}=\frac{1}{2x_kb_k}\le\frac{20}{y_kb_k}=\frac{1}{50}
$$
holds for $\{x_k\},\{y_k\},\{b_k\},\{a_{kl}\}$ that appeared in Theorem~\ref{Verified_Result1}
and from Theorem~\ref{BoundbyFiniteResult} and Theorem~\ref{Verified_Result1},
\begin{align*}
	C_j(T_{a_{kl},b_k})^2&\left(1+5\cdot\frac{1}{50^2}\right)\left(1+3\cdot\frac{1}{50^2}\right)< L_j(a_{kl},b_k), \qquad j=1,2, \\
	C_3(T_{a_{kl},b_k})^2&\left(1+6\cdot\frac{1}{50^2}\right)\left(1+8\cdot\frac{1}{50^2}\right)< L_3(a_{kl},b_k)
\end{align*}
holds for $k=1,2,\dots,119,\; l=0,1,\dots x_k$.
Using this result and Theorem~\ref{a-interpolation},
\begin{align*}
	C_j(T_{a,b_k})^2&\left(1+3\cdot\frac{1}{50^2}\right)< L_j(a,b_k), \qquad j=1,2, \\
	C_3(T_{a,b_k})^2&\left(1+8\cdot\frac{1}{50^2}\right)< L_3(a,b_k)
\end{align*}
holds for $k=1,2,\dots,119,\; 0\le a\le\dfrac{1}{2}$.
Furthermore, from
$$
	0\le\frac{b_k-b_{k+1}}{b_{k+1}}=\frac{y_{k+1}}{y_k}-1\le\frac{51}{50}-1=\frac{1}{50},\qquad b_{119}=\frac{1000}{10133}<\frac{1}{10}
$$
and Theorem~\ref{b-interpolation},
$$
	C_j(T_{a,b})^2 < L_j(a,b), \qquad j=1,2,3
$$
holds for $0\le a\le\dfrac{1}{2},\; \dfrac{1}{10}\le b\le 1$.

From the results above, especially for $C_2(T_{a,b})$, and Theorem~\ref{BoundbyFiniteResult} and Theorem~\ref{Verified_Result1},
 it follows that 
$$
	C_4(T_{a_{kl},b_k})^2\left(1+9\cdot\frac{1}{50^2}\right)\left(1+9\cdot\frac{1}{50^2}\right)\le L_4(a_{kl},b_k)
$$
holds for $k=1,2,\dots,119,\; l=0,1,\dots x_k$, and similarly using Theorem~\ref{a-interpolation} and Theorem~\ref{b-interpolation},
$$
	C_4(T_{a,b})^2 < L_4(a,b)
$$
holds for $0\le a\le\dfrac{1}{2},\; \dfrac{1}{10}\le b\le 1$.
\end{proof}

Fig.~\ref{PointsLines} shows the flow of the proof.
The inequalities, which are shown at discrete points on the $(a,b)$ plane (left), are extended to lines
 by Theorem~\ref{a-interpolation} (middle) and then to a rectangle domain by Theorem~\ref{b-interpolation} (right).

