\section{Proof for $C_j(T),\ j=1,2,3$ when the triangle is degenerate} \label{Degenerate}
The purpose of this section is to prove Theorem~\ref{formula} for $C_j(T),\; j=1,2,3$ when the triangle is degenerate.
That is, we show that the following theorem holds.

\begin{theorem} \label{small_b}
For $0\le a\le\dfrac{1}{2},\; 0<b\le\dfrac{1}{10}$,
$$
	C_j(T_{a,b}) < K_j(T_{a,b}), \qquad j=1,2,3
$$
holds.
\end{theorem}

To show this Theorem, we use the following two Lemmas concerning the monotonicity of $C_j(T)$ and $L_j(a,b)$.
\begin{lemma} \label{Cj-monotonicity}
Assme that $0<\eta\le 1$. Then
$$
	C_j(T_{a,\eta b})\le C_j(T_{a,b}), \qquad j=1,2,3
$$
holds.
\end{lemma}
\begin{proof}
For $u(x,y)\in V^{1,j}(T_{a,\eta b}),\; j=1,2$, let $v(x,y)=u(x,\eta y)\in V^{1,j}(T_{a,b})$.
Then, it holds that
\begin{align*}
	\|v\|_{L^2(T_{a,b})}^2&=\frac{1}{\eta}\|u\|_{L^2(T_{a,\eta b})}^2 \\
	\|v_x\|_{L^2(T_{a,b})}^2&=\frac{1}{\eta}\|u_x\|_{L^2(T_{a,\eta b})}^2 \\
	\|v_y\|_{L^2(T_{a,b})}^2&=\eta\|u_y\|_{L^2(T_{a,\eta h})}^2
\end{align*}
and
\begin{align*}
	\|u\|_{L^2(T_{a,\eta b})}^2&=\eta\|v\|_{L^2(T_{a,b})}^2 \\
	&\le \eta C_j(T_{a,b})^2\|\nabla v\|_{L^2(T_{a,b})}^2=C_j(T_{a,b})^2\left(\|u_x\|_{L^2(T_{a,\eta b})}^2+\eta^2\|u_y\|_{L^2(T_{a,\eta b})}^2\right) \\
	&\le C_j(T_{a,b})^2\|\nabla u\|_{L^2(T_{a,\eta b})}^2.
\end{align*}
From this, we have
$$
	C_j(T_{a,\eta b}) \le C_j(T_{a,b}).
$$
Next, we examine the relation between $C_3(T_{a,\eta b})$ and $C_3(T_{a,b})$.
For $u(x,y)\in V^2(T_{a,\eta b}),\; j=1,2$, let $v(x,y)=u(x,\eta y)\in V^2(T_{a,b})$.
Then, it holds that
\begin{align*}
	\|v\|_{L^2(T_{a,b})}^2&=\frac{1}{\eta}\|u\|_{L^2(T_{a,\eta b})}^2 \\
	\|v_{xx}\|_{L^2(T_{a,b})}^2&=\frac{1}{\eta}\|u_{xx}\|_{L^2(T_{a,\eta b})}^2 \\
	\|v_{xy}\|_{L^2(T_{a,b})}^2&=\eta\|u_{xy}\|_{L^2(T_{a,\eta b})}^2 \\
	\|v_{yy}\|_{L^2(T_{a,b})}^2&=\eta^3\|u_{yy}\|_{L^2(T_{a,\eta b})}^2
\end{align*}
and
\begin{align*}
	\|u\|_{L^2(T_{a,\eta b})}^2&=\eta\|v\|_{L^2(T_{a,b})}^2 \\
	&\le \eta C_3(T_{a,b})^2|v|_{H^2(T_{a,b})}^2 \\
	&=C_3(T_{a,b})^2
		\left(\|u_{xx}\|_{L^2(T_{a,\eta b})}^2+2\eta^2\|u_{xy}\|_{L^2(T_{a,\eta b})}^2+\eta^4\|u_{yy}\|_{L^2(T_{a,\eta b})}^2\right) \\
	&\le C_3(T_{a,b})^2|u|_{H^2(T_{a,\eta b})}^2.
\end{align*}
From this, we have
$$
	C_3(T_{a,\eta b}) \le C_3(T_{a,b}).
$$
\end{proof}

\begin{lemma} \label{Lj-monotonicity}
For $0\le a\le1/2,\;0<b$, it hold that
$$
	\lim_{y\downarrow0}L_j(a,y) < L_j(a,b), \qquad j=1,2,3.
$$
\end{lemma}
The proof of this Lemma comes down to showing the positivity of the multivariate polynomials;
since there is no intrinsic difficulty, it is presented in Lemma~\ref{Lj-limit} of the Appendix 1 (Section~\ref{Appendix1}).

\begin{proof}[Proof of Theorem~\ref{small_b}]
From Theorem~\ref{BoundbyFiniteResult} and Theorem~\ref{Verified_Result2},
\begin{align*}
	C_j(T_{a_l,\frac{1}{10}})^2&\left(1+5\cdot\frac{1}{50^2}\right) < \lim_{y\downarrow0}L_j(a_l,y), \qquad j=1,2, \\
	C_3(T_{a_l,\frac{1}{10}})^2&\left(1+6\cdot\frac{1}{50^2}\right) < \lim_{y\downarrow0}L_3(a_l,y)
\end{align*}
holds for $a_l = \dfrac{l}{500},\; l=0,1,\dots, 250$.
Therefore, Lemma~\ref{Cj-monotonicity} and Lemma~\ref{Lj-monotonicity} implies
\begin{align*}
	C_j(T_{a_l,b})^2&\left(1+5\cdot\frac{1}{50^2}\right) <  L_j(a_l,b), \qquad j=1,2, \\
	C_3(T_{a_l,b})^2&\left(1+6\cdot\frac{1}{50^2}\right) < L_3(a_l,b)
\end{align*}
for $0<b\le\dfrac{1}{10}$ and $l=0,1,\dots, 250$.

Here, using the result of Theorem~\ref{a-interpolation}, we have
$$
	C_j(T_{a,b})^2 < L_j(a,b), \qquad j=1,2,3
$$
for $0\le a\le\dfrac{1}{2},\;0<b\le\dfrac{1}{10}$.
\end{proof}

\section{Asymptotic analysis for $C_4(T)$} \label{Asymptotic_Analysis}
In this section, we deal with $C_4(T_{a,b})$ for $0\le a\le\dfrac{1}{2},\; 0<b\le\dfrac{1}{10}$.
Namely, we prove the following Theorem.

\begin{theorem} \label{C4-asymptotic}
For $0\le a\le\dfrac{1}{2},\; 0<b\le\dfrac{1}{10}$,
$$
	C_4(T_{a,b}) < K_4(T_{a,b})
$$
holds.
\end{theorem}
\begin{proof}
Consider Theorem~\ref{BoundbyFiniteResult}, in particular the case $n=2$,
$$
	C_4(T_{a,b})\le\sqrt{C_4^{(2)}(T_{a,b})^2+\frac{C_2(T_{a,b})^2}{4}}
$$
holds.
Therefore, from Theorem~\ref{small_b},
$$
	C_4(T_{a,b})^2<C_4^{(2)}(T_{a,b})^2+\frac{L_2(a,b)}{4}.
$$
holds. Consequently, it holds that
\begin{equation}
	C_4^{(2)}(T_{a,b})^2\le L_4(a,b)-\frac{L_2(a,b)}{4}\quad \Longrightarrow\quad C_4(T_{a,b})<K_4(T_{a,b}).\label{C4K4}
\end{equation}

Now, let
$$
	c_1 = \frac{2((1-a)^2+b^2)}{b},
	\qquad c_2 = \frac{2(a^2+b^2)}{b},
	\qquad c_3 = \frac{2}{b},
	\qquad S=\frac{b}{2}
$$
then we have
\begin{align*}
	L_2(a,b)&=S\left(\frac{c_1+c_2+c_3}{54}-\frac{1}{2c_1c_2c_3}\right),\\
	L_4(a,b)&=S\left(\frac{c_1c_2c_3}{16}-\frac{c_1+c_2+c_3}{30}-\frac{1}{5}\left(\frac{1}{c_1}+\frac{1}{c_2}+\frac{1}{c_3}\right)\right).
\end{align*}
Therefore, it holds that
\begin{align}
	L_4(a,b)-\frac{L_2(a,b)}{4}&=S\left(\frac{c_1c_2c_3}{16}-\frac{41(c_1+c_2+c_3)}{1080}-\frac{1}{5}\left(\frac{1}{c_1}+\frac{1}{c_2}+\frac{1}{c_3}\right)+\frac{1}{2c_1c_2c_3}\right) \label{L4L2} \\
	&>S\left(\frac{c_1c_2c_3}{16}-\frac{41(c_1+c_2+c_3)}{1080}-\frac{1}{5}\left(\frac{1}{c_1}+\frac{1}{c_2}+\frac{1}{c_3}\right)\right). \notag
\end{align}
Here, let
\begin{align*}
	G_1&=F^{(\beta)}_1(S/4, 0, u_3, u_2, w_7, w_5, w_3)
		+ F^{(\beta)}_1(S/4, u_3, 0, u_1, w_1, w_8, w_6) \\
	&\qquad\qquad + F^{(\beta)}_1(S/4, u_2, u_1, 0, w_4, w_2, w_9)
		+ F^{(\beta)}_1(S/4, u_1, u_2, u_3, -w_7, -w_8, -w_9), \\
	G_2&=F^{(\beta)}_2(S/4, 0, u_3, u_2, w_7, w_5, w_3)
		+ F^{(\beta)}_2(S/4, u_3, 0, u_1, w_1, w_8, w_6) \\
	&\qquad\qquad + F^{(\beta)}_2(S/4, u_2, u_1, 0, w_4, w_2, w_9)
		+ F^{(\beta)}_2(S/4, u_1, u_2, u_3, -w_7, -w_8, -w_9),
\end{align*}
(see Lemma~\ref{F2} for the definition of $F^{(\beta)}_1$ and $F^{(\beta)}_2$),
then from \eqref{C_4uw},\;\eqref{positive_definite},\;\eqref{C4K4} and \eqref{L4L2}, if we can prove that the following
inequality holds,
$$
	S\left(\frac{c_1c_2c_3}{16}-\frac{41(c_1+c_2+c_3)}{1080}-\frac{1}{5}\left(\frac{1}{c_1}+\frac{1}{c_2}+\frac{1}{c_3}\right)\right)G_2 - G_1
		\ge 0
$$
then $C_4(T_{a,b})<K_4(T_{a,b})$ will be shown.

The problem comes down to the problem of showing the non-negativeness of a multivariate polynomial in 14 variables,
which is not intrinsically difficult, but the formula transformation is so complicated that it is presented
in Lemma~\ref{quodoratic-form} of the Appendix 1 (Section~\ref{Appendix1}).
This allows us to prove the theorem.
\end{proof}


\section{Numerical Results} \label{Numerical_Results}
In this section, we present numerical results to show the validity of the formula $K_j(T)$.
We note that the values obtained in this section are the results of approximate calculations and have not been explicitly verified,
as the goal here is to indicate that our formulas fit well.
We show the values of the upper bounds for $C_j(T)$ obtained by Theorem~\ref{BoundbyFiniteResult},
that of $K_j(T)$ in Theorem~\ref{formula}, and that of $C_j(T)$ themselves.
The upper bounds for $C_j(T)$ are obtained as follows: 
\begin{align*}
	\overline{C}_1^{(n)}(T)&=\sqrt{\frac{n^2}{n^2-1}}\;C_1^{(n)}(T), &
	\overline{C}_2^{(n)}(T)&=\sqrt{\frac{n^2}{n^2-1}}\;C_2^{(n)}(T), \\
	\overline{C}_3^{(n)}(T)&=\sqrt{\frac{n^4}{n^4-1}}\;C_3^{(n)}(T), &
	\overline{C}_4^{(n)}(T)&=\sqrt{C_4^{(n)}(T)^2+\frac{\overline{C}_2^{(n)}(T)^2}{n^2}}.
\end{align*}
We compute $C^{(n)}_j(T),\;j=1,2,3,4,\; n=10, 20$ via MATLAB R2024b.
As for $C_j(T)$ themselves, we cannot determine their values analytically.
Therefore, we compute the following values:
\begin{align*}
	\widetilde{C}_1(T)&=\sup_{u\in V^{1,1}(T)\cap\mathcal{P}_{10}\setminus 0}\frac{\|u\|_{L^2(T)}}{\|\nabla u\|_{L^2(T)}}, &
	\widetilde{C}_2(T)&=\sup_{u\in V^{1,2}(T)\cap\mathcal{P}_{10}\setminus 0}\frac{\|u\|_{L^2(T)}}{\|\nabla u\|_{L^2(T)}}, \\
	\widetilde{C}_3(T)&=\sup_{u\in V^2(T)\cap\mathcal{P}_{10}\setminus 0}\frac{\|u\|_{L^2(T)}}{|u|_{H^2(T)}}, &
	\widetilde{C}_4(T)&=\sup_{u\in V^2(T)\cap\mathcal{P}_{10}\setminus 0}\frac{\|\nabla u\|_{L^2(T)}}{|u|_{H^2(T)}},
\end{align*}
where $\mathcal{P}_{10}$ denote the space of polynomials with degree less than or equal to $10$.

We present the numerical results in Table~\ref{Table:C_1} to Table~\ref{Table:C_4};
all numerical results are rounded up to seven decimal places.
Note that $T_{a,b},\;0\le a\le\dfrac{1}{2},\;0<b\le1$ provides all shapes of triangles and, due to the scaling property,
the relative error between the upper bound
and the optimal value depends only on the shape of the triangle.
We also show the graph of $\widetilde{C}_j(T_{a,b})$ and $K_j(T_{a,b})-\widetilde{C}_j(T_{a,b})$
in Fig.~\ref{FigC1} to Fig.~\ref{FigK4}.

These numerical results indicate that the sharp and explicit upper bounds are obtained
by the formulas introduced in Theorem~\ref{formula}.

\section{Circumradius and $C_4(T)$} \label{Circumradius_Condition}
Theorem~\ref{formula} claims that the following estimate holds
for the interpolation constant $C_4(T)$: 
$$
	C_4(T)<K_4(T)=\sqrt{\frac{A^2B^2C^2}{16S^2}-\frac{A^2+B^2+C^2}{30}-\frac{S^2}{5}\left(\frac{1}{A^2}+\frac{1}{B^2}+\frac{1}{C^2}\right)},
$$
where $A,B,C$ are the edge lengths of triangle $T$ and $S$ is the area of $T$.
Since the circumradius of $T$ is given by
$$
	R(T)=\frac{ABC}{4S},
$$
we have the estimation
$$
	C_4(T)<R(T).
$$
This fact has plenty of interesting implications for the error analysis of the Finite Element Method.
 See \cite{KobayashiTsuchiya,KobayashiTsuchiya2} for the details.

