\section{Appendix 1: Lemmas} \label{Appendix1}
Here again, we remark for $d_k=1-ka$. Note also that $d_1\ge0$ when $0\le a\le1$ and $d_2\ge0$
when $0\le a\le\dfrac{1}{2}$.

For subsequent Lemmas, except for Lemma~\ref{positive-definiteness}, we provide
codes by MATLAB with Symbolic Math Toolbox to check the correctness of the formula transformations.
See Code~\ref{Lemma14-1} to Code~\ref{Lemma14-11} in Appendix 2.

Hereafter, let
$$
	\varphi(a,b)=\frac{b^2}{a^2+b^2},\qquad
	\psi(a,b)=\frac{b^2(1+2a)}{1+4b^2}\cdot\varphi(a,b),\qquad
	\omega(a,b)=\frac{a(1-a)}{1-a+a^2+b^2}.
$$

In advance, we will prove a number of Lemmas.
\begin{lemma} \label{appendix-phi}
For $0\le a,\; 0<b$, it holds that
\begin{align*}
	0&\le\varphi(a,b)\le 1, \\
	-\frac{2}{3b}&\le\varphi_a(a,b)\le 0, & -\frac{2}{b^2}&\le\varphi_{aa}(a,b), \\
	0&\le\varphi_b(a,b)\le\frac{1}{2b}, &	-\frac{7}{9b^2}&\le\varphi_{bb}(a,b).
\end{align*}
\end{lemma}

\begin{proof}
$0\le\varphi(a,b)\le1$ is obvious.
\begin{align*}
% phi_a Upper Bound
	\varphi_a(a,b)\; &= \frac{-2ab^2}{(a^2+b^2)^2}
		\le 0, \\
% phi_a Lower Bound
	\varphi_a(a,b)\; &= \frac{-2ab^2}{(a^2+b^2)^2}= -\frac{2}{3b}+\frac{2(a-b)^4+2ab(2a-b)^2}{3b(a^2+b^2)^2}
		\ge -\frac{2}{3b}, \\
% phi_aa Lower Bound
	\varphi_{aa}(a,b) &= \frac{2b^2(3a^2-b^2)}{(a^2 + b^2)^3}
		\ge \frac{-2b^4}{b^6}=-\frac{2}{b^2}, \\
% phi_b Upper Bound
	\varphi_b(a,b)\; &= \frac{2a^2b}{(a^2+b^2)^2}
		\le \frac{2a^2b}{4a^2b^2}=\frac{1}{2b}, \\
% phi_b Lower Bound
	\varphi_b(a,b)\; &= \frac{2a^2b}{(a^2+b^2)^2}
		\ge 0, \\
% phi_bb Lower Bound
	\varphi_{bb}(a,b) &= \frac{2a^2(a^2-3b^2)}{(a^2 + b^2)^3} \\
		&= -\frac{7}{9b^2}+\frac{3a^2b^2(a^2+b^2)+(7a^2+3b^2)(2a^2-b^2)^2+b^2(13a^2-5b^2)^2}{36b^2(a^2 + b^2)^3} \\
		&\ge -\frac{7}{9b^2}.
\end{align*}
\end{proof}

\begin{lemma} \label{appendix-psi}
For $0\le a,\; 0<b$, it holds that
\begin{align*}
	0&\le\psi(a,b)\le\frac{b^2(1+2a)}{1+4b^2}, \\
	-\frac{2b(1+2a)}{3(1+4b^2)}&\le\psi_a(a,b)\le\frac{2b^2}{1+4b^2},
		& -\frac{2(3+6a+4b)}{3(1+4b^2)}&\le\psi_{aa}(a,b), \\
	0&\le\psi_b(a,b)\le\frac{(1+2a)(2+16b-9b^2)}{10(1+4b^2)},
		& -\frac{21(1+2a)}{11(1+4b^2)}&\le\psi_{bb}(a,b).
\end{align*}
\end{lemma}

\begin{proof}
From Lemma~\ref{appendix-phi}, we can immediately obtain
$$
	0\le\psi(a,b)\le\frac{b^2(1+2a)}{1+4b^2}.
$$
Furthermore, we have
\begin{align*}
% psi_a Upper Bound
	\psi_a(a,b)\; &= \frac{2b^2}{1+4b^2}\cdot\varphi(a,b)+\frac{b^2(1+2a)}{1+4b^2}\cdot\varphi_a(a,b)
		\le \frac{2b^2}{1+4b^2}, \\
% psi_a Lower Bound
	\psi_a(a,b)\; &= \frac{2b^2}{1+4b^2}\cdot\varphi(a,b)+\frac{b^2(1+2a)}{1+4b^2}\cdot\varphi_a(a,b)
		\ge \frac{b^2(1+2a)}{1+4b^2}\cdot\frac{-2}{3b}
		= -\frac{2b(1+2a)}{3(1+4b^2)}, \\
% psi_aa Lower Bound
	\psi_{aa}(a,b) &= \frac{4b^2}{1+4b^2}\cdot\varphi_a(a,b)+\frac{b^2(1+2a)}{1+4b^2}\cdot\varphi_{aa}(a,b)\\
		&\ge \frac{4b^2}{1+4b^2}\cdot\frac{-2}{3b}+\frac{b^2(1+2a)}{1+4b^2}\cdot\frac{-2}{b^2}
		=-\frac{2(3+6a+4b)}{3(1+4b^2)}, \\
% psi_b Upper Bound
	\psi_b(a,b)\;&=\frac{2b(1+2a)}{(1+4b^2)^2}\cdot\varphi(a,b)+\frac{b^2(1+2a)}{1+4b^2}\cdot\varphi_b(a,b)\le \frac{2b(1+2a)}{(1+4b^2)^2}+\frac{b^2(1+2a)}{1+4b^2}\cdot\frac{1}{2b} \\
		&= \frac{(1+2a)(2+16b-9b^2)}{10(1+4b^2)} \\
			&\qquad\qquad - \frac{(1+2a)(1-b)}{50(1+4b^2)^2}\Big(11b^3+10(1-3b)^2+b(5-13b)^2\Big) \\
		&\le \frac{(1+2a)(2+16b-9b^2)}{10(1+4b^2)}, \\
% psi_b Lower Bound
	\psi_b(a,b)\;&=\frac{2b(1+2a)}{(1+4b^2)^2}\cdot\varphi(a,b)+\frac{b^2(1+2a)}{1+4b^2}\cdot\varphi_b(a,b)
		\ge 0, \\
% psi_bb Lower Bound
	\psi_{bb}(a,b)&=\frac{2(1+2a)(1-12b^2)}{(1+4b^2)^3}\cdot\varphi(a,b)
			+\frac{4b(1+2a)}{(1+4b^2)^2}\cdot\varphi_b(a,b) \\
			&\qquad\qquad +\frac{b^2(1+2a)}{1+4b^2}\cdot\varphi_{bb}(a,b) \\
		&\ge\frac{2(1+2a)(1-12b^2-(5/4-3b^2)^2)}{(1+4b^2)^3}\cdot\varphi(a,b)
			-\frac{b^2(1+2a)}{1+4b^2}\cdot\frac{7}{9b^2} \\
		&=-\frac{9(1+2a)}{8(1+4b^2)}\cdot\varphi(a,b)-\frac{7(1+2a)}{9(1+4b^2)} \\
		&\ge -\frac{9(1+2a)}{8(1+4b^2)}-\frac{7(1+2a)}{9(1+4b^2)}
			=-\frac{137(1+2a)}{72(1+4b^2)} \\
		&\ge -\frac{21(1+2a)}{11(1+4b^2)}.
\end{align*}
\end{proof}

\begin{lemma} \label{appendix-omega}
For $0\le a\le\dfrac{1}{2},\; 0<b\le 1$, it holds that
\begin{align*}
	&\omega(a,b)\le\frac{4a(1-a)(7-4b^2)}{21}, \\
	\frac{1-2a}{2}\le\;&\omega_a(a,b)\le\frac{4(1-2a)(2-b^2+5a(1-a))}{7}, \\
	-\frac{2(11a(1-a)+2b^2)}{7b^2}\le\;&\omega_{aa}(a,b), \\
	-\frac{1}{6b}\le\;&\omega_b(a,b)\le-\frac{a(1-a)b}{2}, \\
	-\frac{24-64a(1-a)-17b^2}{44b^2}\le\;&\omega_{bb}(a,b).
\end{align*}
\end{lemma}

\begin{proof}
These are obtained as follows.
\begin{align*}
% omega Upper Bound
	\omega(a,b)\;\;&=\frac{4a(1-a)(7-4b^2)}{21}-\frac{ad_1}{21(1-ad_1+b^2)}\Big(3d_2^2+4(1-b^2)(d_2^2+4b^2)\Big) \\
		&\le\frac{4a(1-a)(7-4b^2)}{21}, \\
% omega_a Upper Bound
	\omega_a(a,b)\;&= \frac{4(1-2a)(2-b^2+5a(1-a))}{7} \\
			&\qquad\qquad -\frac{d_2}{7(1-ad_1+b^2)^2}\Big(d_2^2+ ad_1(8d_2^2(1+4b^2)+28b^4)  \\
			&\qquad\qquad  + 4a^2d_1^2(5ad_1+21b^2) + b^2(5-4b^4)\Big) \\
		&\le \frac{4(1-2a)(2-b^2+5a(1-a))}{7}, \\
% omega_a Lower Bound
	\omega_a(a,b)\;&= \frac{(1-2a)(1+b^2)}{(1-ad_1+b^2)^2}
		\ge\frac{(1-2a)(1+b^2)}{(1+b^2)^2}
		=\frac{1-2a}{1+b^2}
		\ge\frac{1-2a}{2}, \\
% omega_aa Lower Bound
	\omega_{aa}(a,b) &=-\frac{2(11a(1-a)+2b^2)}{7b^2}+\frac{2(1+b^2)}{7b^2(1-ad_1+b^2)^3}\Big\{ \\
			&\qquad\qquad \frac{a^3d_1^3(ad_1 + 3d_2^2 + b^2)}{1+b^2}
				+ a^2d_1^2(10ad_1 + 19d_2^2 + b^2) \\
			&\qquad\qquad + ad_1d_2^2(1 + 6d_2^2 + 7b^2) + ad_1(2-3b^2)^2 + d_2^2b^4 + 2b^2(1-b^2)^2\Big\} \\
		&\ge-\frac{2(11a(1-a)+2b^2)}{7b^2}, \\
% omega_b Upper Bound
	\omega_b(a,b)\;&=-\frac{2a(1-a)b}{(1-ad_1+b^2)^2}
		\le-\frac{2a(1-a)b}{(1+1)^2}
		=-\frac{a(1-a)b}{2}, \\
% omega_b Lower Bound
	\omega_b(a,b)\;&=-\frac{1}{6b}\left(1-\frac{(1-7ad_1+b^2)^2+12ad_1d_2^2}{(1-ad_1+b^2)^2}\right)
		\ge-\frac{1}{6b}, \\
% omega_bb Lower Bound
	\omega_{bb}(a,b) &=-\frac{24-64a(1-a)-17b^2}{44b^2}
			+\frac{1}{44b^2(1-ad_1+b^2)^3}\Big\{ \\
			&\qquad\qquad 13d_2^2b^2 + a^3d_1^3(8+17b^2) + d_2^4\Big(1+6b^2 + (3-2ad_1+3b^2)^2\Big) \\
			&\qquad\qquad + a^2d_1^2\Big(4+10b^2 + 3b^2(1-b^2)\Big) + 2(6ad_1+7d_2^2)(1-b^2)(1-3b^2)^2 \\
			&\qquad\qquad + b^2(1-b^2)\Big(34d_2^2+3ad_1(13+27b^2)+82d_2^2(1-b^2)+17b^4\Big)\Big\} \\
		&\ge-\frac{24-64a(1-a)-17b^2}{44b^2}.
\end{align*}
\end{proof}

In the following Lemma~\ref{L1-bound} to Lemma~\ref{L4-bound},
\begin{align*}
	0\le &a\le\frac{1}{2},&\quad 0\le&\widetilde{a}\le\frac{1}{2},&\quad |\widetilde{a}-a|&\le \frac{b}{50}, \\
	0<&b\le 1, &\quad 0<&\widetilde{b}\le 1, &\quad |\widetilde{b}-b|&\le \frac{b}{50},
\end{align*}
is assumed. Note that in this case,
$$
	\frac{49}{50}b\le\widetilde{b}\le\frac{51}{50}b
$$
holds.

\begin{lemma} \label{L1-bound}
It holds that
\begin{align*}
	\left|\frac{\partial L_1}{\partial a}(a,b)\right|&< \frac{2}{b}L_1(a,b),
		& \frac{\partial^2 L_1}{\partial a^2}(\widetilde{a},b)&< \frac{5}{b^2}L_1(a,b), \\
	\left|\frac{\partial L_1}{\partial b}(a,b)\right|&< \frac{2}{b}L_1(a,b),
		& \frac{\partial^2 L_1}{\partial b^2}(a,\widetilde{b})&< \frac{4}{b^2}L_1(a,b).
\end{align*}
\end{lemma}

\begin{proof}
From the defifnition of $L_1(a,b)$ and Lemma~\ref{appendix-psi}, we have
\begin{align*}
% L1 Lower Bound
	L_1(a,b)\;\; &= \frac{1+a^2+(1-a)^2+2b^2}{28}
			- \frac{b^4}{16(a^2+b^2)((1-a)^2+b^2)} \\
		&= \frac{1-a+a^2+b^2}{14} - \frac{b^4(1+2a)}{16(a^2+b^2)(1+4b^2)} - \frac{b^4(3-2a)}{16((1-a)^2+b^2)(1+4b^2)} \\
		&= \frac{1-a+a^2+b^2}{14} - \frac{\psi(a,b)+\psi(1-a,b)}{16} \\
		&\ge \frac{1-a+a^2+b^2}{14} - \frac{1}{16}\left(\frac{b^2(1+2a)}{1+4b^2}+\frac{b^2(1+2(1-a))}{1+4b^2}\right) \\
		&=\frac{1-a+a^2+b^2}{14} - \frac{b^2}{4(1+4b^2)}, \\
% L1_a Lower Bound
	\frac{\partial L_1}{\partial a}(a,b)\; &= -\frac{1-2a}{14} - \frac{\psi_a(a,b)-\psi_a(1-a,b)}{16} \\
		&\ge -\frac{1-2a}{14} - \frac{1}{16}\left(\frac{2b^2}{1+4b^2}+\frac{2b(1+2(1-a))}{3(1+4b^2)}\right) \\
		&= -\frac{1-2a}{14} - \frac{b(3-2a+3b)}{24(1+4b^2)}, \\
% L1_a Upper Bound
	\frac{\partial L_1}{\partial a}(a,b)\; &= -\frac{1-2a}{14} - \frac{\psi_a(a,b)-\psi_a(1-a,b)}{16} \\
		&\le -\frac{1-2a}{14} - \frac{1}{16}\left(-\frac{2b(1+2a)}{3(1+4b^2)}-\frac{2b^2}{1+4b^2}\right) \\
		&= -\frac{1-2a}{14} + \frac{b(1+2a+3b)}{24(1+4b^2)}, \\
% L1_aa Upper Bound
	\frac{\partial^2 L_1}{\partial a^2}(\widetilde{a},b) &= \frac{1}{7} - \frac{\psi_{aa}(\widetilde{a},b)+\psi_{aa}(1-\widetilde{a},b)}{16} \\
		&\le \frac{1}{7} - \frac{1}{16}\left(-\frac{2(3+6\widetilde{a}+4b)}{3(1+4b^2)}-\frac{2(3+6(1-\widetilde{a})+4b)}{3(1+4b^2)}\right) \\
		&= \frac{1}{7} + \frac{3+2b}{6(1+4b^2)}, \\
% L1_b Lower Bound
	\frac{\partial L_1}{\partial b}(a,b)\; &= \frac{b}{7} - \frac{\psi_b(a,b)+\psi_b(1-a,b)}{16} \\
		&\ge\frac{b}{7} - \frac{1}{16}\left(\frac{(1+2a)(2+16b-9b^2)}{10(1+4b^2)}+\frac{(1+2(1-a))(2+16b-9b^2)}{10(1+4b^2)}\right) \\
		&= \frac{b}{7}-\frac{2+16b-9b^2}{40(1+4b^2)}, \\
% L1_b Upper Bound
	\frac{\partial L_1}{\partial b}(a,b)\; &= \frac{b}{7} - \frac{\psi_b(a,b)+\psi_b(1-a,b)}{16}
		\le\frac{b}{7}, \\
% L1_bb Upper Bound
	\frac{\partial^2 L_1}{\partial b^2}(a,\widetilde{b}) &= \frac{1}{7} - \frac{\psi_{bb}(a,\widetilde{b})+\psi_{bb}(1-a,\widetilde{b})}{16} \\
		&\le\frac{1}{7} - \frac{1}{16}\left(-\frac{21(1+2a)}{11(1+4\widetilde{b}^2)}-\frac{21(1+2(1-a))}{11(1+4\widetilde{b}^2)}\right) \\
		&= \frac{1}{7}+\frac{21}{44(1+4\widetilde{b}^2)}
		\le\frac{1}{7}+\frac{21}{44(49/50)^2(1+4b^2)} \\
		&\le\frac{1}{7}+\frac{1}{2(1+4b^2)}.
\end{align*}
Then,
\begin{align*}
% 2*L1 + b*L1_a > 0
	168(1+4b^2)&\left(2L_1(a,b)+b\cdot\frac{\partial L_1}{\partial a}(a,b)\right) \\
		&\ge 168(1+4b^2)\left\{2\left(\frac{1-a+a^2+b^2}{14} - \frac{b^2}{4(1+4b^2)}\right)\right. \\
			&\qquad\qquad\qquad\qquad\qquad\qquad\qquad
			\left. +b\left(-\frac{1-2a}{14} - \frac{b(3-2a+3b)}{24(1+4b^2)}\right)\right\} \\
		&= 6(d_2^2+4ab)(1+4b^2) + b^2\Big(3+14a+3b+46(1-b)^2\Big) + 2(3-b-5b^2)^2 \\
		&> 0, \\
% 2*L1 - b*L1_a > 0
	168(1+4b^2)&\left(2L_1(a,b)-b\cdot\frac{\partial L_1}{\partial a}(a,b)\right) \\
		&\ge 168(1+4b^2)\left\{2\left(\frac{1-a+a^2+b^2}{14} - \frac{b^2}{4(1+4b^2)}\right)\right. \\
			&\qquad\qquad\qquad\qquad\qquad\qquad\qquad
			\left. -b\left(-\frac{1-2a}{14} + \frac{b(1+2a+3b)}{24(1+4b^2)}\right)\right\} \\
		&= 6(d_2^2+4d_1b)(1+4b^2) + b^2\Big(3+14d_1+3b+46(1-b)^2\Big) + 2(3-b-5b^2)^2 \\
		&> 0, \\
% 5*L1 - b^2*L1_aa > 0
	84(1+4b^2)&\left(5L_1(a,b)-b^2\cdot\frac{\partial^2 L_1}{\partial a^2}(\widetilde{a},b)\right) \\
		&\ge 84(1+4b^2)\left\{5\left(\frac{1-a+a^2+b^2}{14} - \frac{b^2}{4(1+4b^2)}\right)
			- b^2\left(\frac{1}{7} + \frac{3+2b}{6(1+4b^2)}\right)\right\} \\
		&= 2ad_1 + 2d_2^2(4+15b^2) + 22(1+2b)(1-b)^2 + 9b^2\Big(1+2(1-2b)^2\Big) \\
		&> 0, \\
% 2*L1 + b*L1_b > 0
	280(1+4b^2)&\left(2L_1(a,b)+b\cdot\frac{\partial L_1}{\partial b}(a,b)\right) \\
		&\ge 280(1+4b^2)\left\{2\left(\frac{1-a+a^2+b^2}{14} - \frac{b^2}{4(1+4b^2)}\right)\right. \\
			&\qquad\qquad\qquad\qquad\qquad\qquad\qquad
			\left. +b\left(\frac{b}{7}-\frac{2+16b-9b^2}{40(1+4b^2)}\right)\right\} \\
		&= 64ad_1b(1-2b)^2 + 2\Big(2ad_1(30+b^2) + d_2^2(20+13b)\Big)(1-b) \\
			&\qquad\qquad + b^2(11 + 3d_2^2 + 320b^2 + 63d_2^2b) \\
		&> 0, \\
% 2*L1 - b*L1_b > 0
	28(1+4b^2)&\left(2L_1(a,b)-b\cdot\frac{\partial L_1}{\partial b}(a,b)\right) \\
		&\ge 28(1+4b^2)\left\{2\left(\frac{1-a+a^2+b^2}{14} - \frac{b^2}{4(1+4b^2)}\right)-b\cdot\frac{b}{7}\right\} \\
		&=1+2(1-b^2) + d_2^2(1+4b^2) \\
		&> 0, \\
% 4*L1 - b^2*L1_bb > 0
	14(1+4b^2)&\left(4L_1(a,b)-b^2\cdot\frac{\partial^2 L_1}{\partial b^2}(a,\widetilde{b})\right) \\
		&\ge 14(1+4b^2)\left\{4\left(\frac{1-a+a^2+b^2}{14} - \frac{b^2}{4(1+4b^2)}\right)
			-b^2\left(\frac{1}{7}+\frac{1}{2(1+4b^2)}\right)\right\} \\
		&=1 + b^2 + d_2^2(1+4b^2) + 2(1-2b^2)^2 \\
		&> 0,
\end{align*}
hold and the desired inequalities are shown.
\end{proof}

\begin{lemma} \label{L2-bound}
It holds that
\begin{align*}
	\left|\frac{\partial L_2}{\partial a}(a,b)\right|&< \frac{2}{b}L_2(a,b),
		& \frac{\partial^2 L_2}{\partial a^2}(\widetilde{a},b)&<\frac{5}{b^2}L_2(a,b), \\
	\left|\frac{\partial L_2}{\partial b}(a,b)\right|&< \frac{2}{b}L_2(a,b),
		& \frac{\partial^2 L_2}{\partial b^2}(a,\widetilde{b})&<\frac{4}{b^2}L_2(a,b).
\end{align*}
\end{lemma}

\begin{proof}
From the defifnition of $L_2(a,b)$ and Lemma~\ref{appendix-psi}, we have
\begin{align*}
% L2 Lower Bound
	L_2(a,b)\;\; &= \frac{1+a^2+(1-a)^2+2b^2}{54}
			- \frac{b^4}{32(a^2+b^2)((1-a)^2+b^2)} \\
		&= \frac{1-a+a^2+b^2}{27} - \frac{b^4(1+2a)}{32(a^2+b^2)(1+4b^2)} - \frac{b^4(3-2a)}{32((1-a)^2+b^2)(1+4b^2)} \\
		&= \frac{1-a+a^2+b^2}{27} - \frac{\psi(a,b)+\psi(1-a,b)}{32} \\
		&\ge \frac{1-a+a^2+b^2}{27} - \frac{1}{32}\left(\frac{b^2(1+2a)}{1+4b^2}+\frac{b^2(1+2(1-a))}{1+4b^2}\right) \\
		&=\frac{1-a+a^2+b^2}{27} - \frac{b^2}{8(1+4b^2)}, \\
% L2_a Lower Bound
	\frac{\partial L_2}{\partial a}(a,b)\; &= -\frac{1-2a}{27} - \frac{\psi_a(a,b)-\psi_a(1-a,b)}{32} \\
		&\ge -\frac{1-2a}{27} - \frac{1}{32}\left(\frac{2b^2}{1+4b^2}+\frac{2b(1+2(1-a))}{3(1+4b^2)}\right) \\
		&= -\frac{1-2a}{27} - \frac{b(3-2a+3b)}{48(1+4b^2)}, \\
% L2_a Upper Bound
	\frac{\partial L_2}{\partial a}(a,b)\; &= -\frac{1-2a}{27} - \frac{\psi_a(a,b)-\psi_a(1-a,b)}{32} \\
		&\le -\frac{1-2a}{27} - \frac{1}{32}\left(-\frac{2b(1+2a)}{3(1+4b^2)}-\frac{2b^2}{1+4b^2}\right) \\
		&= -\frac{1-2a}{27} + \frac{b(1+2a+3b)}{48(1+4b^2)}, \\
% L2_aa Upper Bound
	\frac{\partial^2 L_2}{\partial a^2}(\widetilde{a},b) &= \frac{2}{27} - \frac{\psi_{aa}(\widetilde{a},b)+\psi_{aa}(1-\widetilde{a},b)}{32} \\
		&\le \frac{2}{27} - \frac{1}{32}\left(-\frac{2(3+6\widetilde{a}+4b)}{3(1+4b^2)}-\frac{2(3+6(1-\widetilde{a})+4b)}{3(1+4b^2)}\right) \\
		&= \frac{2}{27} + \frac{3+2b}{12(1+4b^2)}, \\
% L2_b Lower Bound
	\frac{\partial L_2}{\partial b}(a,b)\; &= \frac{2b}{27} - \frac{\psi_b(a,b)+\psi_b(1-a,b)}{32} \\
		&\ge\frac{2b}{27} - \frac{1}{32}\left(\frac{(1+2a)(2+16b-9b^2)}{10(1+4b^2)}+\frac{(1+2(1-a))(2+16b-9b^2)}{10(1+4b^2)}\right) \\
		&= \frac{2b}{27}-\frac{2+16b-9b^2}{80(1+4b^2)}, \\
% L2_b Upper Bound
	\frac{\partial L_2}{\partial b}(a,b)\; &= \frac{2b}{27} - \frac{\psi_b(a,b)+\psi_b(1-a,b)}{32}
		\le\frac{2b}{27}, \\
% L2_bb Upper Bound
	\frac{\partial^2 L_2}{\partial b^2}(a,\widetilde{b}) &= \frac{2}{27} - \frac{\psi_{bb}(a,\widetilde{b})+\psi_{bb}(1-a,\widetilde{b})}{32} \\
		&\le\frac{2}{27} - \frac{1}{32}\left(-\frac{21(1+2a)}{11(1+4\widetilde{b}^2)}-\frac{21(1+2(1-a))}{11(1+4\widetilde{b}^2)}\right) \\
		&= \frac{2}{27}+\frac{21}{88(1+4\widetilde{b}^2)} \le\frac{2}{27}+\frac{21}{88(49/50)^2(1+4b^2)} \\
		&\le\frac{2}{27}+\frac{1}{4(1+4b^2)}.
\end{align*}
Then,
\begin{align*}
% 2*L2 + b*L2_a > 0
	432(1+4b^2)&\left(2L_2(a,b)+b\cdot\frac{\partial L_2}{\partial a}(a,b)\right) \\
		&\ge 432(1+4b^2)\left\{2\left(\frac{1-a+a^2+b^2}{27} - \frac{b^2}{8(1+4b^2)}\right)\right. \\
			&\qquad\qquad\qquad\qquad\qquad\qquad\qquad
			\left. +b\left(-\frac{1-2a}{27} - \frac{b(3-2a+3b)}{48(1+4b^2)}\right)\right\} \\
		&=8 + 8d_2^2 + 16(1-b) + b^2(18a+128a^2+9b+28b^2) \\
			&\qquad\qquad + b(32a+25b)(1-2b)^2 \\
		&> 0, \\
% 2*L2 - b*L2_a > 0
	432(1+4b^2)&\left(2L_2(a,b)-b\cdot\frac{\partial L_2}{\partial a}(a,b)\right) \\
		&\ge 432(1+4b^2)\left\{2\left(\frac{1-a+a^2+b^2}{27} - \frac{b^2}{8(1+4b^2)}\right)\right. \\
			&\qquad\qquad\qquad\qquad\qquad\qquad\qquad
			\left. -b\left(-\frac{1-2a}{27} + \frac{b(1+2a+3b)}{48(1+4b^2)}\right)\right\} \\
		&=8 + 8d_2^2 + 16(1-b) + b^2(18d_1+128d_1^2+9b+28b^2) \\
			&\qquad\qquad + b(32d_1+25b)(1-2b)^2 \\
		&> 0, \\
% 5*L2 - b^2*L2_aa > 0
	216(1+4b^2)&\left(5L_2(a,b)-b^2\cdot\frac{\partial^2 L_2}{\partial a^2}(\widetilde{a},b)\right) \\
		&\ge 216(1+4b^2)\left\{5\left(\frac{1-a+a^2+b^2}{27} - \frac{b^2}{8(1+4b^2)}\right)
			- b^2\left(\frac{2}{27} + \frac{3+2b}{12(1+4b^2)}\right)\right\} \\
		&= 9b(1-b) + 15(2+b)(1-2b)^2 + 10d_2^2(1+4b^2) + 96b(1+b)(1-b)^2 \\
		&> 0, \\
% 2*L2 + b*L2_b > 0
	2160(1+4b^2)&\left(2L_2(a,b)+b\cdot\frac{\partial L_2}{\partial b}(a,b)\right) \\
		&\ge 2160(1+4b^2)\left\{2\left(\frac{1-a+a^2+b^2}{27} - \frac{b^2}{8(1+4b^2)}\right)\right. \\
			&\qquad\qquad\qquad\qquad\qquad\qquad\qquad
			\left. +b\left(\frac{2b}{27}-\frac{2+16b-9b^2}{80(1+4b^2)}\right)\right\} \\
		&= 337b^3 + 40d_2^2(1+4b^2) + 30(2-b-7b^2)^2 + 2b(1-b)(33+352b+95b^2) \\
		&> 0, \\
% 2*L2 - b*L2_b > 0
	108(1+4b^2)&\left(2L_2(a,b)-b\cdot\frac{\partial L_2}{\partial b}(a,b)\right) \\
		&\ge 108(1+4b^2)\left\{2\left(\frac{1-a+a^2+b^2}{27} - \frac{b^2}{8(1+4b^2)}\right)-b\cdot\frac{2b}{27}\right\} \\
		&= 3 + 3(1-b^2) + 2d_2^2(1+4b^2) \\
		&> 0, \\
% 4*L2 - b^2*L2_bb >= 0
	108(1+4b^2)&\left(4L_2(a,b)-b^2\cdot\frac{\partial^2 L_2}{\partial b^2}(a,\widetilde{b})\right) \\
		&\ge 108(1+4b^2)\left\{4\left(\frac{1-a+a^2+b^2}{27} - \frac{b^2}{8(1+4b^2)}\right)
			-b^2\left(\frac{2}{27}+\frac{1}{4(1+4b^2)}\right)\right\} \\
		&= 4 + 7b^2 + 4d_2^2(1+4b^2) + 8(1-2b^2)^2 \\
		&> 0,
\end{align*}
hold and the desired inequalities are shown.
\end{proof}

\begin{lemma} \label{L3-bound}
It holds that
\begin{align*}
	\left|\frac{\partial L_3}{\partial a}(a,b)\right|&< \frac{2}{b}L_3(a,b),
		& \frac{\partial^2 L_3}{\partial a^2}(\widetilde{a},b)&<\frac{4}{b^2}L_3(a,b), \\
	\left|\frac{\partial L_3}{\partial b}(a,b)\right|&< \frac{3}{b}L_3(a,b),
		& \frac{\partial^2 L_3}{\partial b^2}(a,\widetilde{b})&<\frac{8}{b^2}L_3(a,b).
\end{align*}
\end{lemma}

\begin{proof}
From the defifnition of $L_3(a,b)$ and Lemma~\ref{appendix-omega}, we have
\begin{align*}
% L3 Lower Bound
	L_3(a,b)\;\;&=\frac{b^2+(1-a+a^2+b^2)^2}{83} + \frac{2a(1-a)-3b^2}{96}-\frac{\omega(a,b)}{48} \\
		&\ge\frac{b^2+(1-a+a^2+b^2)^2}{84} + \frac{2a(1-a)-3b^2}{96}-\frac{a(1-a)(7-4b^2)}{252} \\
		&= \frac{24(1-a+a^2+b^2)^2 - 39b^2 - 2a(1-a)(7-16b^2)}{2016}, \\
% L3_a Lower Bound
	\frac{\partial L_3}{\partial a}(a,b)\;&=-\frac{2(1-2a)(1-a+a^2+b^2)}{83}+\frac{1-2a}{48}-\frac{\omega_a(a,b)}{48} \\
		&\ge-\frac{25(1-2a)(1-a+a^2+b^2)}{1008}+\frac{1-2a}{48} \\
			&\qquad\qquad -\frac{(1-2a)(2-b^2+5a(1-a))}{84}  \\
		&=-\frac{(1-2a)(28+13b^2+35a(1-a))}{1008}, \\
% L3_a Upper Bound
	\frac{\partial L_3}{\partial a}(a,b)\;&=-\frac{2(1-2a)(1-a+a^2+b^2)}{83}+\frac{1-2a}{48}-\frac{\omega_a(a,b)}{48} \\
		&\le-\frac{2(1-2a)(1-a+a^2+b^2)}{144}+\frac{1-2a}{48}-\frac{1-2a}{96} \\
		&=-\frac{d_2(d_2^2+4b^2)}{288}
		\le0, \\
% L3_aa Upper Bound
	\frac{\partial^2L_3}{\partial a^2}(\widetilde{a},b)
		&=\frac{3+3(1-2\widetilde{a})^2+4b^2}{83}-\frac{1}{24}-\frac{\omega_{aa}(\widetilde{a},b)}{48} \\
		&\le\frac{25(3+3(1-2\widetilde{a})^2+4b^2)}{2016}-\frac{1}{24}+\frac{11\widetilde{a}(1-\widetilde{a})+2b^2}{168b^2} \\
		&=\frac{(11-25b^2)(\widetilde{a}-a)(1-\widetilde{a}-a)}{168b^2} \\
			&\qquad\qquad +\frac{2a(1-a)(33-75b^2) + 5b^2(9+10b^2)}{1008b^2} \\
		&\le\frac{14(b/50)}{168b^2}+\frac{2a(1-a)(33-75b^2) + 5b^2(9+10b^2)}{1008b^2} \\
		&\le\frac{1}{504b^2}+\frac{2a(1-a)(33-75b^2) + 5b^2(9+10b^2)}{1008b^2} \\
		&=\frac{2 + 2a(1-a)(33-75b^2) + 5b^2(9+10b^2)}{1008b^2}, \\
% L3_b Lower Bound
	\frac{\partial L_3}{\partial b}(a,b)\;&=\frac{b(5+(1-2a)^2+4b^2)}{83}-\frac{b}{16}-\frac{\omega_b(a,b)}{48} \\
		&\ge\frac{23b(5+(1-2a)^2+4b^2)}{1920}-\frac{b}{16}+\frac{a(1-a)b}{96} \\
		&=\frac{b(9d_2^2+46b^2)}{960}
		\ge0, \\
% L3_b Upper Bound
	\frac{\partial L_3}{\partial b}(a,b)\;&=\frac{b(5+(1-2a)^2+4b^2)}{83}-\frac{b}{16}-\frac{\omega_b(a,b)}{48} \\
		&\le\frac{b(5+(1-2a)^2+4b^2)}{83}-\frac{b}{16}+\frac{1}{288b} \\
		&\le\frac{17b(5+(1-2a)^2+4b^2)}{1344}-\frac{b}{16}+\frac{1}{168b} \\
		&=\frac{4+9b^2-34a(1-a)b^2+34b^4}{672b}, \\
% L3_bb Upper Bound
	\frac{\partial^2L_3}{\partial b^2}(a,\widetilde{b})
		&=\frac{5+(1-2a)^2+12\widetilde{b}^2}{83}-\frac{1}{16}-\frac{\omega_{bb}(a,\widetilde{b})}{48} \\
		&\le\frac{5+(1-2a)^2+12\widetilde{b}^2}{83}-\frac{1}{16}+\frac{24-64a(1-a)-17\widetilde{b}^2}{2112\widetilde{b}^2} \\
		&=\frac{(1-2a)^2+12\widetilde{b}^2}{83}+\frac{4a(1-a)+3(1-2a)^2}{264\widetilde{b}^2} -\frac{1807}{175296} \\
		&\le\frac{(1-2a)^2+12(51/50)^2b^2}{83}+\frac{4a(1-a)+3(1-2a)^2}{264(49/50)^2b^2}-\frac{1807}{175296} \\
		&\le\frac{2(1-2a)^2+19b^2}{126}+\frac{4a(1-a)+3(1-2a)^2}{252b^2}-\frac{1}{126} \\
		&=\frac{3+2b^2+38b^4 -8a(1-a)(1+2b^2)}{252b^2}.
\end{align*}
Then,
\begin{align*}
% 2*L3 + b*L3_a > 0
	1008&\left(2L_3(a,b)+b\cdot\frac{\partial L_3}{\partial a}(a,b)\right) \\
		&\ge 1008\left\{2\left(\frac{24(1-a+a^2+b^2)^2 - 39b^2 - 2a(1-a)(7-16b^2)}{2016}\right)\right. \\
			&\qquad\qquad\qquad\qquad
			\left. +b\left(-\frac{(1-2a)(28+13b^2+35a(1-a))}{1008}\right)\right\} \\
		&= 6d_2^4 + 6ad_1(4-b^2) + d_2b(ad_1+b^2) + 4(1-2b^2)^2 + b^2(4+b^2) \\
			&\qquad\qquad  + (d_2-b)^2(14+18ad_1+7b^2) \\
		&> 0, \\
% 2*L3 - b*L3_a > 0
	1008&\left(2L_3(a,b)-b\cdot\frac{\partial L_3}{\partial a}(a,b)\right) \\
		&\ge 1008\left\{2\left(\frac{24(1-a+a^2+b^2)^2 - 39b^2 - 2a(1-a)(7-16b^2)}{2016}\right) - b\cdot 0\right\} \\
		&= 34ad_1 + 5b^2 + 24a^2d_1^2 + 4d_2^2(6+b^2) + 24b^4 \\
		&> 0, \\
% 4*L3 - b^2*L3_aa > 0
	1008&\left(4L_3(a,b)-b^2\cdot\frac{\partial^2 L_3}{\partial a^2}(\widetilde{a},b)\right) \\
		&\ge 1008\left\{4\left(\frac{24(1-a+a^2+b^2)^2 - 39b^2 - 2a(1-a)(7-16b^2)}{2016}\right)\right. \\
			&\qquad\qquad\qquad\qquad\qquad
			\left. -b^2\left(\frac{2 + 2a(1-a)(33-75b^2) + 5b^2(9+10b^2)}{1008b^2}\right)\right\} \\
		&=17d_2^4 + 2ad_1(12ad_1+31d_2^2+b^2) + (1-b^2)(29d_2^2+2b^2) \\
		&> 0, \\
% 3*L3 + b*L3_b > 0
	672&\left(3L_3(a,b)+b\cdot\frac{\partial L_3}{\partial b}(a,b)\right) \\
		&\ge 672\left\{3\left(\frac{24(1-a+a^2+b^2)^2 - 39b^2 - 2a(1-a)(7-16b^2)}{2016}\right) + b\cdot0\right\} \\
		&= 34ad_1 + 5b^2 + 24a^2d_1^2 + 4d_2^2(6+b^2) + 24b^4 \\
		&> 0, \\
% 3*L3 - b*L3_b > 0
	336&\left(3L_3(a,b)-b\cdot\frac{\partial L_3}{\partial b}(a,b)\right) \\
		&\ge 336\left\{3\left(\frac{24(1-a+a^2+b^2)^2 - 39b^2 - 2a(1-a)(7-16b^2)}{2016}\right)\right. \\
			&\qquad\qquad\qquad\qquad
			\left. -b\left(\frac{4+9b^2-34a(1-a)b^2+34b^4}{672b}\right)\right\} \\
		&=ad_1(1+17d_2^2) + 5d_2^4 + (1-b^2)(11ad_1+5d_2^2+5b^2) \\
		&> 0, \\
% 8*L3 - b^2*L3_bb >= 0
	252&\left(8L_3(a,b)-b^2\cdot\frac{\partial^2 L_3}{\partial b^2}(a,\widetilde{b})\right) \\
		&\ge 252\left\{8\left(\frac{24(1-a+a^2+b^2)^2 - 39b^2 - 2a(1-a)(7-16b^2)}{2016}\right)\right. \\
			&\qquad\qquad\qquad\qquad\qquad\qquad
			\left. -b^2\left(\frac{3+2b^2+38b^4 -8a(1-a)(1+2b^2)}{252b^2}\right)\right\} \\
		&= 14d_2^2 + 2ad_1(1+12ad_1) + 7(1-b^2)(1+2b^2) \\
		&> 0,
\end{align*}
hold and the desired inequalities are shown.
\end{proof}

\begin{lemma} \label{L4-bound}
It holds that
\begin{align*}
	\left|\frac{\partial L_4}{\partial a}(a,b)\right|&< \frac{3}{b}L_4(a,b),
		& \frac{\partial^2 L_4}{\partial a^2}(\widetilde{a},b)&<\frac{9}{b^2}L_4(a,b), \\
	\left|\frac{\partial L_4}{\partial b}(a,b)\right|&< \frac{3}{b}L_4(a,b),
		& \frac{\partial^2 L_4}{\partial b^2}(a,\widetilde{b})&<\frac{9}{b^2}L_4(a,b).
\end{align*}
\end{lemma}

\begin{proof}
From the defifnition of $L_4(a,b)$ and Lemma~\ref{appendix-phi}, we have
\begin{align*}
% L4 Lower Bound
	L_4(a,b)\;\;&= \frac{(a^2+b^2)((1-a)^2+b^2)}{4b^2}-\frac{1+a^2+(1-a)^2+2b^2}{30} \\
			&\qquad\qquad -\frac{b^2}{20}\left(1+\frac{1}{a^2+b^2}+\frac{1}{(1-a)^2+b^2}\right) \\
		&= \frac{a^2(1-a)^2}{4b^2} + \frac{11-26a(1-a)}{60} + \frac{2b^2}{15}
			-\frac{\varphi(a,b)+\varphi(1-a,b)}{20} \\
		&\ge \frac{a^2(1-a)^2}{4b^2} + \frac{11-26a(1-a)}{60} + \frac{2b^2}{15}-\frac{1+1}{20} \\
		&=\frac{a^2(1-a)^2}{4b^2} + \frac{5 - 26a(1-a)+8b^2}{60}, \\
% L4_a Lower Bound
	\frac{\partial L_4}{\partial a}(a,b)\; &= (1-2a)\left(\frac{a(1-a)}{2b^2}-\frac{13}{30}\right)
			-\frac{\varphi_a(a,b)-\varphi_a(1-a,b)}{20} \\
		&\ge (1-2a)\left(\frac{a(1-a)}{2b^2}-\frac{13}{30}\right)
			-\frac{1}{20}\cdot\frac{2}{3b} \\
		&=(1-2a)\left(\frac{a(1-a)}{2b^2}-\frac{13}{30}\right)-\frac{1}{30b}, \\
% L4_a Upper Bound
	\frac{\partial L_4}{\partial a}(a,b)\; &= (1-2a)\left(\frac{a(1-a)}{2b^2}-\frac{13}{30}\right)
			-\frac{\varphi_a(a,b)-\varphi_a(1-a,b)}{20} \\
		&\le (1-2a)\left(\frac{a(1-a)}{2b^2}-\frac{13}{30}\right)+\frac{1}{20}\cdot\frac{2}{3b} \\
		&=(1-2a)\left(\frac{a(1-a)}{2b^2}-\frac{13}{30}\right)+\frac{1}{30b}, \\
% L4_aa Upper Bound
	\frac{\partial^2 L_4}{\partial a^2}(\widetilde{a},b) &= \frac{1-6\widetilde{a}(1-\widetilde{a})}{2b^2} + \frac{13}{15}
			-\frac{\varphi_{aa}(\widetilde{a},b)+\varphi_{aa}(1-\widetilde{a},b)}{20} \\
		&\le \frac{1-6\widetilde{a}(1-\widetilde{a})}{2b^2} + \frac{13}{15}
			+ \frac{1}{20}\left( \frac{2}{b^2} + \frac{2}{b^2} \right) \\
		&=\frac{7-30a(1-a)-30(\widetilde{a}-a)(1-\widetilde{a}-a)}{10b^2}+\frac{13}{15} \\
		&\le\frac{7-30a(1-a)+30(b/45)}{10b^2}+\frac{13}{15} \\
		&=\frac{21-90a(1-a)+2b}{30b^2}+\frac{13}{15}, \\
% L4_b Lower Bound
	\frac{\partial L_4}{\partial b}(a,b)\; &= - \frac{a^2(1-a)^2}{2b^3} + \frac{4b}{15} 
			-\frac{\varphi_b(a,b)+\varphi_b(1-a,b)}{20} \\
		&\ge - \frac{a^2(1-a)^2}{2b^3} + \frac{4b}{15} 
			- \frac{1}{20}\left(\frac{1}{2b}+\frac{1}{2b}\right) \\
		&= - \frac{a^2(1-a)^2}{2b^3} - \frac{1}{20b} + \frac{4b}{15}, \\
% L4_b Upper Bound
	\frac{\partial L_4}{\partial b}(a,b)\; &= - \frac{a^2(1-a)^2}{2b^3} + \frac{4b}{15} 
			-\frac{\varphi_b(a,b)+\varphi_b(1-a,b)}{20} \\
		&\le - \frac{a^2(1-a)^2}{2b^3} + \frac{4b}{15}, \\
% L4_bb Upper Bound
	\frac{\partial^2 L_4}{\partial b^2}(a,\widetilde{b})&= \frac{3a^2(1-a)^2}{2\widetilde{b}^4} + \frac{4}{15}
			-\frac{\varphi_{bb}(a,\widetilde{b})+\varphi_{bb}(1-a,\widetilde{b})}{20} \\
		&\le \frac{3a^2(1-a)^2}{2\widetilde{b}^4} + \frac{4}{15}
			+ \frac{1}{20}\left(\frac{7}{9\widetilde{b}^2}+\frac{7}{9\widetilde{b}^2} \right) \\
		&= \frac{3a^2(1-a)^2}{2\widetilde{b}^4} + \frac{7}{90\widetilde{b}^2} + \frac{4}{15} \\
		&\le \frac{3a^2(1-a)^2}{2(49/50)^4b^4} + \frac{7}{90(49/50)^2b^2} + \frac{4}{15} \\
		&\le \frac{49a^2(1-a)^2}{30b^4} + \frac{1}{12b^2} + \frac{4}{15}.
\end{align*}
Then,
\begin{align*}
% 3*L4 + b*L4_a > 0
	60b^2&\left(3L_4(a,b)+b\cdot\frac{\partial L_4}{\partial a}(a,b)\right) \ge 60b^2\left\{3\left(\frac{a^2(1-a)^2}{4b^2} + \frac{5 - 26a(1-a)}{60} + \frac{2b^2}{15}\right)\right. \\
			&\qquad\qquad\qquad\qquad\qquad\qquad\qquad
			\left. +b\left((1-2a)\left(\frac{a(1-a)}{2b^2}-\frac{13}{30}\right)-\frac{1}{30b}\right)\right\} \\
		&= 11ad_1^2b + 5(3ad_1-b)^2 + ab(7d_1-5b)^2 \\
			&\qquad\qquad + b^2\Big(2(1-b) + a(4+2a+3b) + 6(d_1-2b)^2\Big) \\
		&> 0, \\
% 3*L4 - b*L4_a > 0
	60b^2&\left(3L_4(a,b)-b\cdot\frac{\partial L_4}{\partial a}(a,b)\right) \ge 60b^2\left\{3\left(\frac{a^2(1-a)^2}{4b^2} + \frac{5 - 26a(1-a)}{60} + \frac{2b^2}{15}\right)\right. \\
			&\qquad\qquad\qquad\qquad\qquad\qquad\qquad
			\left. -b\left((1-2a)\left(\frac{a(1-a)}{2b^2}-\frac{13}{30}\right)+\frac{1}{30b}\right)\right\} \\
		&= 11a^2d_1b + 5(3ad_1-b)^2 + d_1b(7a-5b)^2 \\
			&\qquad\qquad + b^2\Big(2(1-b) + d_1(4+2d_1+3b) + 6(a-2b)^2\Big) \\
		&> 0, \\
% 9*L4 - b^2*L4_aa > 0
	60b^2&\left(9L_4(a,b)-b^2\cdot\frac{\partial^2 L_4}{\partial a^2}(\widetilde{a},b)\right) \\
		&\ge 60b^2\left\{9\left(\frac{a^2(1-a)^2}{4b^2} + \frac{5 - 26a(1-a)}{60} + \frac{2b^2}{15}\right)\right. \\
			&\qquad\qquad\qquad\qquad\qquad\qquad\qquad
			\left. -b^2\left(\frac{21-90a(1-a)+2b}{30b^2}+\frac{13}{15}\right)\right\} \\
 		&= 86a^2d_1^2 + (7ad_1-4b^2)^2 + b^2\Big(2 + 2ad_1 + (1-2b)^2\Big) \\
		&> 0, \\
% 3*L4 + b*L4_b > 0
	60b^2&\left(3L_4(a,b)+b\cdot\frac{\partial L_4}{\partial b}(a,b)\right) \ge 60b^2\left\{3\left(\frac{a^2(1-a)^2}{4b^2} + \frac{5 - 26a(1-a)}{60} + \frac{2b^2}{15}\right)\right. \\
			&\qquad\qquad\qquad\qquad\qquad\qquad\qquad
			\left. +b\left(- \frac{a^2(1-a)^2}{2b^3} - \frac{1}{20b} + \frac{4b}{15}\right)\right\} \\
		&=b^2(12d_2^2 + 25b^2) + 15(ad_1-b^2)^2 \\
		&> 0, \\
% 3*L4 - b*L4_b > 0
	60b^2&\left(3L_4(a,b)-b\cdot\frac{\partial L_4}{\partial b}(a,b)\right)
		\ge 60b^2\left\{3\left(\frac{a^2(1-a)^2}{4b^2} + \frac{5 - 26a(1-a)}{60} + \frac{2b^2}{15}\right)\right. \\
			&\qquad\qquad\qquad\qquad\qquad\qquad\qquad
			\left. -b\left(- \frac{a^2(1-a)^2}{2b^3} + \frac{4b}{15}\right)\right\} \\
		&=b^2(3+12d_2^2+5b^2) + 3(5ad_1-b^2)^2  \\
		&> 0, \\
% L4 - L4_bb > 0
	60b^2&\left(9L_4(a,b)-b^2\cdot\frac{\partial^2}{\partial b^2}L_4(a,\widetilde{b})\right) \\
		&\ge 60b^2\left\{9\left(\frac{a^2(1-a)^2}{4b^2} + \frac{5 - 26a(1-a)}{60} + \frac{2b^2}{15}\right)\right. \\
			&\qquad\qquad\qquad\qquad\qquad\qquad
			\left. -b^2\left(\frac{49a^2(1-a)^2}{30b^4} + \frac{1}{12b^2} + \frac{4}{15}\right)\right\} \\
		&=b^2(40d_2^2+19b^2) + 37(ad_1-b^2)^2 \\
		&> 0,
\end{align*}
hold and the desired inequalities are shown.
\end{proof}

\begin{lemma} \label{Lj-limit}
For $0\le a\le1,\; 0<b$, it hold thats
$$
	\lim_{y\downarrow0} L_j(a,y) < L_j(a,b), \qquad j=1,2,3.
$$
\end{lemma}
\begin{proof}
Although we cannot substitute $a=0$ and $b=0$ to $L_j(a,b),\; j=1,2$ simultaneously,
we can easily confirm that $\lim_{y\downarrow0}L_j(a,y), \; j=1,2,3$ coincide with the expression
obtained by formally substituting $b=0$ to $L_j(a,b)$.
And then, we have
\begin{align*}
	&\frac{112(a^2 + b^2)(d_1^2+b^2)}{b^2}\left(L_1(a,b)-\lim_{y\downarrow0} L_1(a,y)\right)
		= 8(ad_1-b^2)^2 + b^2 > 0, \\
	&\frac{864(a^2 + b^2)(d_1^2+b^2)}{b^2}\left(L_2(a,b)-\lim_{y\downarrow0} L_2(a,y)\right)
		= 32(ad_1-b^2)^2 + 5b^2 > 0, \\
	&\frac{7968(d_1+a^2+b^2)(d_1+a^2)}{b^2}\left(L_3(a,b)-\lim_{y\downarrow0} L_3(a,y)\right) \\
	&\qquad = 52ad_1 + 39d_2^2 + 3a^2d_1^2(125 + 16d_2^2) + 3b^2(d_1 + a^2)(21 + 32b^2 + 24d_2^2) \\
	&\qquad > 0.
\end{align*}
\end{proof}


\begin{lemma} \label{quodoratic-form}
Assume $0\le a\le \dfrac{1}{2},\; 0<b\le \dfrac{1}{10}$ and let
$c_1, c_2, c_3, S, G_1, G_2$ be the notation that appeared in Theorem~\ref{C4-asymptotic}. Then
$$
	S\left(\frac{c_1c_2c_3}{16}-\frac{41(c_1+c_2+c_3)}{1080}-\frac{1}{5}\left(\frac{1}{c_1}+\frac{1}{c_2}+\frac{1}{c_3}\right)\right)G_2 - G_1
		\ge 0
$$
holds true.
\end{lemma}

\begin{proof}
Let
$$
	D = \frac{c_1c_2c_3}{16}-\frac{41(c_1+c_2+c_3)}{1080}-\frac{1}{5}\left(\frac{1}{c_1}+\frac{1}{c_2}+\frac{1}{c_3}\right)
$$
and
$$
	H=48c_1^2c_2^2c_3^2(SDG_2 - G_1).
$$
Moreover, let
\begin{align*}
	E &= 48D-c_1-c_2-c_3, \\
	q_1&=2E + 2c_1 + c_2 + c_3, \\
	q_2&=2E + 2c_2 + c_3 + c_1, \\
	q_3&=2E + 2c_3 + c_1 + c_2, \\
	r_1&=\frac{c_1(12D(E+c_1) + 1)}{(2E + c_1 + 2c_2 + 2c_3)^2}, \\
	r_2&=\frac{c_2(12D(E+c_2) + 1)}{(2E + c_2 + 2c_3 + 2c_1)^2}, \\
	r_3&=\frac{c_3(12D(E+c_3) + 1)}{(2E + c_3 + 2c_1 + 2c_2)^2}, \\
	v_1&=c_2c_3(w_1+w_4), \\
	v_2&=c_3c_1(w_2+w_5), \\
	v_3&=c_1c_2(w_3+w_6), \\
	v_4&=w_1+w_2-w_3+w_4-w_5+w_6+2(w_8+w_9), \\
	v_5&=w_2+w_3-w_1+w_5-w_6+w_4+2(w_9+w_7), \\
	v_6&=w_3+w_1-w_2+w_6-w_4+w_5+2(w_7+w_8), \\
	v_7&=c_1c_2c_3(4q_1(w_4-w_8+w_9)-q_1(v_5-v_6)-(c_2-c_3)v_4), \\
	v_8&=c_1c_2c_3(4q_2(w_5-w_9+w_7)-q_2(v_6-v_4)-(c_3-c_1)v_5), \\
	v_9&=c_1c_2c_3(4q_3(w_6-w_7+w_8)-q_3(v_4-v_5)-(c_1-c_2)v_6).
\end{align*}
Then, from
\begin{align*}
	\frac{45b^3E}{4}&=\frac{108(ad_1-b^2)^2(1 + d_2^2 + 4b^2)}{c_1c_2} \\
	&\qquad + 270a^2d_1^2 + b^2\Big(47ad_1 + 88d_2^2 + (1-100b^2)\Big) + 81b^4 \\
	&>0,
\end{align*}
$D,E,q_1,q_2,q_3,r_1,r_2,r_3$ are all positive and the following equality holds:
\begin{align*}
	H=& 16\left\{
		\frac{1}{c_2c_3q_1}\Big( c_1c_2c_3\Big( q_1(u_1-u_2-u_3) - 6D(c_1-c_2-c_3)v_4 \Big) - 96Dv_1 \Big)^2 \right. \\
	&\qquad\qquad + \frac{1}{c_3c_1q_2}\Big( c_1c_2c_3\Big( q_2(u_2-u_3-u_1) - 6D(c_2-c_3-c_1)v_5 \Big) - 96Dv_2 \Big)^2 \\
	&\qquad\qquad\qquad\left. + \frac{1}{c_1c_2q_3}\Big( c_1c_2c_3\Big( q_3(u_3-u_1-u_2) - 6D(c_3-c_1-c_2)v_6 \Big) - 96Dv_3 \Big)^2 \right\} \\
	& + \left\{
		\frac{1}{c_2c_3q_1}\Big( q_1(2c_1v_1 - c_2v_2 + c_3v_3) + (c_2-c_3)(96D-c_1)v_1 - v_7 \Big)^2 \right. \\
	&\qquad\qquad + \frac{1}{c_3c_1q_2}\Big( q_2(2c_2v_2 - c_3v_3 + c_1v_1) + (c_3-c_1)(96D-c_2)v_2 - v_8 \Big)^2 \\
	&\qquad\qquad\qquad\left. + \frac{1}{c_1c_2q_3}\Big( q_3(2c_3v_3 - c_1v_1 + c_2v_2) + (c_1-c_2)(96D-c_3)v_3 - v_9 \Big)^2 \right\} \\
	& + 4\left\{
		\frac{c_1}{q_1r_1}\Big( v_1 + r_1c_2c_3(96D-c_1)v_4 \Big)^2
		+ \frac{c_2}{q_2r_2}\Big( v_2 + r_2c_3c_1(96D-c_2)v_5 \Big)^2 \right. \\
	&\qquad\qquad\qquad\qquad\qquad\qquad\qquad\qquad\qquad
		\left. + \frac{c_3}{q_3r_3}\Big( v_3 + r_3c_1c_2(96D-c_3)v_6 \Big)^2 \right\} \\
	&+ 8\left\{
		\frac{q_1c_1 + 3D(c_2+c_3)(c_2-c_3)^2}{q_1(12D(E+c_1)+1)}v_1^2
			+ \frac{q_2c_2 + 3D(c_3+c_1)(c_3-c_1)^2}{q_2(12D(E+c_2)+1)}v_2^2 \right. \\
	&\qquad\qquad\qquad\left. + \frac{q_3c_3 + 3D(c_1+c_2)(c_1-c_2)^2}{q_3(12D(E+c_3)+1)}v_3^2 \right\} \\
	&+ \frac{2}{E}\left\{\frac{(c_2-c_3)^2 + 32}{E+c_1}\left(c_1 + \frac{E}{12D(E+c_1)+1}\right)v_1^2 \right. \\
	&\qquad+ \frac{(c_3-c_1)^2 + 32}{E+c_2}\left(c_2 + \frac{E}{12D(E+c_2)+1}\right)v_2^2 \\
	&\qquad\qquad \left. + \frac{(c_1-c_2)^2 + 32}{E+c_3}\left(c_3 + \frac{E}{12D(E+c_3)+1}\right)v_3^2\right\} \\
	&+ \frac{2}{E}\left\{\Big( 8E(3Dc_1-1)c_1 - (c_2-c_3)^2 - 32 \Big)v_1^2 \right. \\
	&\qquad\qquad + \Big( 8E(3Dc_2-1)c_2 - (c_3-c_1)^2 - 32 \Big)v_2^2 \\
	&\qquad\qquad\qquad + \Big( 8E(3Dc_3-1)c_3 - (c_1-c_2)^2 - 32 \Big)v_3^2 \\
	&\qquad\qquad \left. + 48DE\Big( (c_1c_2-4)v_1v_2 + (c_2c_3-4)v_2v_3 + (c_3c_1-4)v_3v_1 \Big)\right\}.
\end{align*}
Therefore,
\begin{align*}
	\frac{EH}{2}&\ge\Big( 8E(3Dc_1-1)c_1 - (c_2-c_3)^2 - 32 \Big)v_1^2 \\
	&\qquad + \Big( 8E(3Dc_2-1)c_2 - (c_3-c_1)^2 - 32 \Big)v_2^2 \\
	&\qquad\qquad + \Big( 8E(3Dc_3-1)c_3 - (c_1-c_2)^2 - 32 \Big)v_3^2 \\
	&\qquad\qquad\qquad+ 48DE\Big( (c_1c_2-4)v_1v_2 + (c_2c_3-4)v_2v_3 + (c_3c_1-4)v_3v_1 \Big)
\end{align*}
holds, and by Lemma~\ref{positive-definiteness2}, which will be discussed later,
we can confirm that this quadratic form regarding $v_1,v_2,v_3$ is positive definite, and $H\ge0$ is shown.
\end{proof}

Here, as a preliminary step, we present a Lemma on the positive definiteness of quadratic forms.
\begin{lemma} \label{positive-definiteness}
Assume that $A_1,A_2,A_3,B_1,B_2,B_3\in\mathbb{R}$ satisfy
$$
	\left\{\begin{aligned}
		&B_1B_2B_3 \ge 0 \\
		&A_3 > 0 \\
		&A_1B_1^2+A_2B_2^2-2B_1B_2B_3 > 0 \\
		&A_1A_2A_3 - A_1B_1^2 - A_2B_2^2 - A_3B_3^2 + 2B_1B_2B_3 > 0.
	\end{aligned}\right.
$$
Then, for arbitrary $v_1,v_2,v_3\in\mathbb{R}$,
$$
	A_1v_1^2 + A_2v_2^2 + A_3v_3^2 + 2B_1v_2v_3 + 2B_2v_3v_1 + 2B_3v_1v_2\ge0
$$
holds.
\end{lemma}
\begin{proof}
Under the assumptions, it holds that
\begin{align*}
	A_1B_1^2+A_2B_2^2&\ge A_1B_1^2+A_2B_2^2-2B_1B_2B_3 \\
	&> 0, \\
	A_1A_2-B_3^2&=\frac{1}{A_3}\Big((A_1B_1^2+A_2B_2^2-2B_1B_2B_3) \\
	&\qquad\qquad + (A_1A_2A_3 - A_1B_1^2 - A_2B_2^2 - A_3B_3^2 + 2B_1B_2B_3)\Big) \\
	&> \frac{1}{A_3}(A_1B_1^2+A_2B_2^2-2B_1B_2B_3) \\
	&> 0.
\end{align*}
When $B_2=0$, we have $A_1>0$ by
$$
	A_1B_1^2 = A_1B_1^2+A_2B_2^2 > 0
$$
and when $B_2\not=0$, we have also $A_1>0$ by
\begin{align*}
	A_1&=\frac{(A_1A_2 - B_3^2)B_2^2 + A_1^2B_1^2 + B_2^2B_3^2}{A_1B_1^2 + A_2B_2^2} \\
	&\ge\frac{ (A_1A_2 - B_3^2)B_2^2}{A_1B_1^2 + A_2B_2^2} \\
	&> 0.
\end{align*}
Therefore,
\begin{align*}
	&A_1>0,\qquad \begin{vmatrix} A_1 & B_3 \\ B_3 & A_2 \end{vmatrix}=A_1A_2-B_3^2>0, \\
	&\begin{vmatrix} A_1 & B_3 & B_2 \\ B_3 & A_2 & B_1 \\ B_2 & B_1 & A_3\\\end{vmatrix}
		=A_1A_2A_3 + 2B_1B_2B_3 - A_1B_1^2 - A_2B_2^2 - A_3B_3^2 > 0
\end{align*}
holds. Then, the general theory of quadratic forms and its positive definiteness (see \cite{HornJohnson})
leads us to the conclusion.
\end{proof}

\begin{lemma} \label{positive-definiteness2}
Assume $0\le a\le \dfrac{1}{2},\; 0<b\le \dfrac{1}{10}$ and let
$c_1, c_2, c_3, D, E$ be the notation that appeared in Theorem~\ref{C4-asymptotic} and Lemma~\ref{quodoratic-form}.
Furthermore, let
\begin{align*}
	A_1&=8E(3Dc_1-1)c_1 - (c_2-c_3)^2 - 32, \\
	A_2&=8E(3Dc_2-1)c_2 - (c_3-c_1)^2 - 32, \\
	A_3&=8E(3Dc_3-1)c_3 - (c_1-c_2)^2 - 32, \\
	B_1&=24DE(c_2c_3-4), \\
	B_2&=24DE(c_3c_1-4), \\
	B_3&=24DE(c_1c_2-4).
\end{align*}
Then, for arbitrary $v_1,v_2,v_3\in\mathbb{R}$,
$$
	A_1v_1^2 + A_2v_2^2 + A_3v_3^2 + 2B_1v_2v_3 + 2B_2v_3v_1 + 2B_3v_1v_2\ge0
$$
holds true.
\end{lemma}
