    M1a0 = lambda * B1 - A1;
    M2a0 = lambda * B2 - A2;

    disp('Step 3: Verify the inequality for 1/10 <= b <= 1');

    h = 1 / intval(n);

    yk = 1000;
    for k = 1:119
        b = 1000 / intval(yk);
        xk = ceil(yk/40);
        for l = 0:xk
            a = l / intval(2*xk);
	        M1 = eval(M1ab);
    	    M2 = eval(M2ab);
            verify();
        end
        yk = floor(yk*51/50);
    end

    disp('Step 4: Verify the inequality for 0 < b <= 1/10');

    b = 1 / intval(10);
    for l = 0:250
        a = l / intval(500);
        M1 = eval(M1a0);
   	    M2 = eval(M2a0);
  	    verify();
    end

    disp('Verificaion complited');

    %%  Nested function for the verification  %%
    function verify()
        disp(['a=', num2str(mid(a)), ', b=', num2str(mid(b))]);
        CM = intval(zeros(max_index));
        for i = 1:n^2
            c = triangle(i, :);
            if orientation(i) == 1
                CM(c, c) = CM(c, c) + M1;
            else
                CM(c, c) = CM(c, c) + M2;
            end
        end

        %%  Impose constraints  %%
        CM(constraints, :) = [];
        CM(:, constraints) = [];

        if isspd(CM) == 1
            disp('Verified');
        else
            error('Verification failed.');
        end
