The functions {\tt F\_alpha\_0} and {\tt F\_alpha\_1} compute
$F^{(\alpha)}_0(s,w_1,w_2,w_3,u_0)$ and $F^{(\alpha)}_1(s,w_1,w_2,w_3,u_0)$
that appear in Lemma~\ref{F1}.

\begin{lstlisting}[caption=F\_alpha\_0.m, label=Fa0]
function z = F_alpha_0(s, c1, c2, c3, w1, w2, w3, u0)
    v0 =  (3*c2 + 3*c3 - c1) * w1 ...
        + (3*c3 + 3*c1 - c2) * w2 ...
        + (3*c1 + 3*c2 - c3) * w3;
    z = s / 15 * ( ...
        8 * (c1^2 + c2^2 + c3^2) * (w1 + w2 + w3 - 3*u0)^2 ...
                / (c1 + c2 + c3)^2 ...
        - 2 * (w1 + w2 + w3 - 3*u0) * v0 / (c1 + c2 + c3) ...
        + 5 * (w1^2 + w2^2 + w3^2) ...
    );
end
\end{lstlisting}

\begin{lstlisting}[caption=F\_alpha\_1.m, label=Fa1]
function z = F_alpha_1(s, c1, c2, c3, w1, w2, w3, u0)
    z = ( ...
        32 * (w1 + w2 + w3 - 3*u0)^2 / (c1 + c2 + c3) ...
        + (c1 + c2 - c3) * (w1 - w2)^2 ...
        + (c2 + c3 - c1) * (w2 - w3)^2 ...
        + (c3 + c1 - c2) * (w3 - w1)^2 ...
    ) / 2;
end
\end{lstlisting}

\bigskip

The functions {\tt F\_beta\_0}, {\tt F\_beta\_1}, and {\tt F\_beta\_2} compute
$F^{(\beta)}_0(s,u_1,u_2,u_3,w_1,w_2,w_3)$, $F^{(\beta)}_1(s,u_1,u_2,u_3,w_1,w_2,w_3)$
and $F^{(\beta)}_2(s,u_1,u_2,u_3,w_1,w_2,w_3)$
that appear in Lemma~\ref{F2}.

\begin{lstlisting}[caption=F\_beta\_0.m, label=Fb0]
function z = F_beta_0(s, c1, c2, c3, u1, u2, u3, w1, w2, w3)
    v1 = (13*u1 + u2 + u3) / 4 - (4*w1 - (c2 - c3)*(u2 - u3)) / c1;
    v2 = (13*u2 + u3 + u1) / 4 - (4*w2 - (c3 - c1)*(u3 - u1)) / c2;
    v3 = (13*u3 + u1 + u2) / 4 - (4*w3 - (c1 - c2)*(u1 - u2)) / c3;
    z = s / 720 * ( ...
        21 * (u1^2 + u2^2 + u3^2) - 6 * (u1*u2 + u2*u3 + u3*u1) ...
        + 6 * (v1^2 + v2^2 + v3^2) + 10 * (v1*v2 + v2*v3 + v3*v1) ...
    );
end
\end{lstlisting}

\begin{lstlisting}[caption=F\_beta\_1.m, label=Fb1]
function z = F_beta_1(s, c1, c2, c3, u1, u2, u3, w1, w2, w3)
    z = ( ...
          ((u2 - u3)^2 + w1^2) / c1 ...
        + ((u3 - u1)^2 + w2^2) / c2 ...
        + ((u1 - u2)^2 + w3^2) / c3 ...
    ) / 3;
end
\end{lstlisting}

\begin{lstlisting}[caption=F\_beta\_2.m, label=Fb2]
function z = F_beta_2(s, c1, c2, c3, u1, u2, u3, w1, w2, w3)
    v4 = 2*u1 - u2 - u3 + (4*w1 - (c2 - c3)*(u2 - u3)) / c1;
    v5 = 2*u2 - u3 - u1 + (4*w2 - (c3 - c1)*(u3 - u1)) / c2;
    v6 = 2*u3 - u1 - u2 + (4*w3 - (c1 - c2)*(u1 - u2)) / c3;
    z = ( ...
        (c1*v4 + c2*v5 + c3*v6)^2 - 8*(v4*v5 + v5*v6 + v6*v4) ...
    ) / s / 16;
end
\end{lstlisting}

\bigskip

{\tt create\_coefficient\_matrix} is a function that computes the representation matrix
from the corresponding polynomial of quadratic form.

\begin{lstlisting}[caption=create\_coefficient\_matrix.m, label=CreateCoefficientMatrix]
function A = create_coefficient_matrix(quadratic_form, variables)
    m = length(variables);
    A = sym(zeros(m));
    for p = 1:m
        df = diff(quadratic_form, variables(p));
        for q = 1:p
            A(p, q) = simplifyFraction(diff(df, variables(q)) / 2);
            if q<p
                A(q, p) = A(p, q);
            end
        end
    end
end
\end{lstlisting}

\bigskip

The function {\tt L1ab(a,b)}, {\tt L2ab(a,b)}, {\tt L3ab(a,b)} and {\tt L4ab(a,b)} compute
$L_j(a,b),\;j=1,2,3,4$ defined by \eqref{Ljab}.

\begin{lstlisting}[caption=L1ab.m, label=L1ab]
function z = L1ab(a, b)
    AA = (1-a)^2 + b^2;
    BB = a^2 + b^2;
    CC = 1;
    SS = b^2 / 4;
    z = (AA + BB + CC) / 28 - SS^2 / (AA * BB * CC);
end
\end{lstlisting}

\begin{lstlisting}[caption=L2ab.m, label=L2ab]
function z = L2ab(a, b)
    AA = (1-a)^2 + b^2;
    BB = a^2 + b^2;
    CC = 1;
    SS = b^2 / 4;
    z = (AA + BB + CC) / 54 - SS^2 / 2 / (AA * BB * CC);
end
\end{lstlisting}

\begin{lstlisting}[caption=L3ab.m, label=L3ab]
function z = L3ab(a, b)
    AA = (1-a)^2 + b^2;
    BB = a^2 + b^2;
    CC = 1;
    SS = b^2 / 4;
    z = (AA*BB + BB*CC + CC*AA) / 83 ...
        - (AA*BB*CC / (AA + BB + CC) + SS) / 24;
end
\end{lstlisting}


\begin{lstlisting}[caption=L4ab.m, label=L4ab]
function z = L4ab(a, b)
    AA = (1-a)^2 + b^2;
    BB = a^2 + b^2;
    CC = 1;
    SS = b^2 / 4;
    z = AA*BB*CC / 16 / SS - (AA + BB + CC) / 30 ...
        - SS / 5 * (1/AA + 1/BB + 1/CC);
end
\end{lstlisting}

\bigskip

Hereafter, functions of the form {\tt Lemma*\_*} in {\tt Lemma*\_*.m} are codes to check the correctness of the corresponding
Lemma *.*.
In these codes, operations such as {\tt 2/3} are written as {\tt 2/sym(3)} to avoid the result being a floating-point number.
In addition, large integers that cannot be expressed in the range of double-precision floating-point numbers
are not accurately converted to symbolic integers if written as is, so just to be safe,
integers with 10 or more digits are defined using strings such as {\tt sym('1234567890')}.

