% ===========================================
\paragraph{Model---} We focus on a relatively simple example of double helical states related by TRS; see FIG.~\ref{fig:01}. The two pairs of counterflowing modes can be represented by the fermion fields as: 
\begin{equation}\label{eq:01}
\psi_\mu(r) = R_{\mu\uparrow}(r)e^{i\xi_\mu k_\mu r} + L_{\mu\downarrow}(r)e^{-i\xi_\mu k_\mu r},
\end{equation}
where the index $\mu$ labels the sector of time-reversal partner, with $\xi_1=1$ and $\xi_2=-1$. We assume that the Fermi level is far from the Dirac point of the edge spectrum such that $|k_1-k_2| L \gg 1 $ with the edge length $L$. Due to the helical nature of the edge states, below we suppress the spin indices for the slow oscillating modes, $R_\mu , L_\mu$. The Hamiltonian of the low-energy states can be expressed as $H=H_0+ H_\text{int}$, with the kinetic energy term,
\begin{equation}\label{eq:02}
    H_0 = -i\hbar v\int dr \,\sum_{\mu=1,2} \big[ R^\dagger_\mu(r)\partial_r R_\mu(r) - L^\dagger_\mu(r)\partial_r L_\mu(r) \big],
\end{equation}
with the Fermi velocity $v$. 
Here, we assume a negligible difference in Fermi velocities \cite{Dziawa2012, Tanaka2012, Liu2014, Liu2015, PhysRevB.109.155143, Wang_2024, PhysRevB.110.L161104, PhysRevB.110.035161, PhysRevB.94.235111} and a uniform chemical potential for the two time-reversal sectors \cite{PhysRevB.110.035125}. 
Moreover, we consider general density-density and current-current interactions between electrons:
\begin{equation}\label{eq:03}
    H_\text{int} = \frac{1}{2}\int drdr' \big[ V(r-r')\rho(r)\rho(r') + \tilde{V}(r-r')J(r)J(r') \big],    
\end{equation}
with the charge ($\rho$) and current ($J$) densities and their corresponding short-range strengths, $V$ and $\tilde{V}$.

\par Following a standard procedure \cite{book:Giamarchi}, we bosonize Eqs.~\eqref{eq:02}--\eqref{eq:03} to obtain a two-channel LL, $H_{\text{LL}}$, and a sine-Gordon-like mass term, $H_{\text{m}}$, 
\begin{align}
    H_{\text{LL}} = & \sum_{\mu=c,\tau} \int \frac{\hbar\, dr }{2\pi} u_\mu[K_\mu^{-1}(\partial_r\varphi_\mu(r))^2 + K_\mu(\partial_r\vartheta_\mu(r))^2],  \label{eq:05}
    \\ 
    H_{\text{m}} = & \int dr\,\frac{m}{2(\pi a)^2}\cos[2\sqrt{2}\vartheta_\tau(r)] \label{eq:06},
\end{align}
with the LL parameters, $K_c,K_\tau$, and the renormalized velocities, $u_c,u_\tau$. 
The indices $c$ and $\tau$ are associated with the charge and pseudospin sectors, respectively. These names reflect the nature of the collective excitations, which maintain helical characteristics within each sector,   see Supplemental Materials (SM) and FIG.~S3 for details \cite{SM}\nocite{PhysRevB.61.13410, PhysRevB.102.165147, PhysRevLett.103.166403, PhysRevB.109.155119, PhysRevB.99.045125, PhysRevB.98.115146, PhysRevB.86.165121, PhysRevB.97.045415, J_M_Kosterlitz_1974, RevModPhys.87.457, annurev_PDW, PhysRevB.79.064515, PhysRevB.91.195102, PhysRevB.101.165133}. 
The mass  $m\equiv V_{2k_0}-\tilde{V}_{2k_0}$ above is determined by the Fourier components, $V_{2k_0}$ and $\tilde{V}_{2k_0}$, of the potential $V$ and $\tilde{V}$, respectively, corresponding to the transferred momentum $\delta k = 2k_0$ in the forward-scattering process depicted in FIG.~\ref{fig:01}. Below, we show how the mass term induces a SDW or an SC phase within the edge. 

% ===========================================
\paragraph{Phase diagram---} We derive the renormalization-group (RG) flow equations and get the following condition for a relevant mass term \cite{SM}, 
 \begin{align}
\label{eq:rel_m}
K_\tau(l=0) > f(\tilde{m}(l=0)) \text{ with } \tilde{m}(l=0)\neq0,
\end{align}
with $\tilde{m}\equiv m/\hbar v$, $l\equiv\ln [ a(l)/a(0) ]$, the cutoff $a$, and 
$f(x)$ satisfying $x^2 = 2 [f(x) - \ln f(x) ]-2$ and $f(x)\leq1$.
The corresponding RG flow is depicted in FIG.~\ref{fig:03}.
Given that in practice $K_\tau(l=0) = 1$~\cite{SM}, the mass term remains relevant as long as there is a finite mass in Eq.~\eqref{eq:06}. Below we will focus on this case.

\par In the strong-coupling limit, a relevant $\tilde{m}$ term in Eq.~\eqref{eq:06} can pin the $\vartheta_\tau $ field at a certain value depending on the sign of $m$. In this limit, we examine the following operators characterizing the SDW and SC instabilities, 
\begin{equation}
\begin{split}
    \Delta_{2q}^{(x)} (r) \pm i\Delta_{2q}^{(y)} (r) 
    & \sim \mp e^{\pm i[\sqrt{2}\varphi_c(r)]}\cos[\sqrt{2}\vartheta_\tau(r)],
    \\ 
    \Delta_{\text{SC}} (r)
    & \sim e^{- i[\sqrt{2}\vartheta_c(r)]}\cos[\sqrt{2}\vartheta_\tau(r)] ,
\end{split}
\end{equation}
respectively. Here, the superscript and subscript of the SDW operators denote the components and their nesting vector (see FIG.~\ref{fig:01}), respectively. Interestingly, the double helical states allow for a generalization of the SDW and SC phases to include a $\pi$ phase difference between the two time-reversal sectors. In analogy to the $\pi$-junction setting~\cite{PhysRevLett.115.237001, Hsu_2021, PhysRevLett.100.096407, PhysRevLett.111.116402, PhysRevLett.122.126402, PhysRevLett.120.267002, PhysRevLett.129.227002, PhysRevB.97.014507, PhysRevB.89.220504}, we refer to these as the $\pi$-SDW and $\pi$-SC orderings, with the following operators, 
\begin{equation}
\begin{split}
    \Delta_{2q,\pi}^{(x)} (r) \pm i\Delta_{2q,\pi}^{(y)} (r) 
    & \sim ie^{\pm i[\sqrt{2}\varphi_c(r)]}\sin[\sqrt{2}\vartheta_\tau(r)],
    \\ 
    \Delta_{{\rm SC},\pi} (r)
    & \sim ie^{- i[\sqrt{2}\vartheta_c(r)]}\sin[\sqrt{2}\vartheta_\tau(r)],
\end{split}
\end{equation}
respectively. Note that $\pi$-SDW respects the TRS, see SM and FIG.~S1 for details \cite{SM}. When \(m<0\), \(\vartheta_\tau \) is pinned at \(n\pi / \sqrt{2}\) with \(n\in\mathbb{Z}\), resulting in \(\langle \cos(\sqrt{2}\vartheta_\tau) \rangle \neq 0\) and \(\langle \sin(\sqrt{2}\vartheta_\tau) \rangle = 0\), suppressing the $\pi$-SDW and $\pi$-SC phases. On the other hand, when \(m>0\), \(\vartheta_\tau \to (n+\frac{1}{2}) \pi / \sqrt{2}\), and the SDW and SC phases are suppressed instead.

\par Since the $\vartheta_\tau$ field is pinned to its classical value, the correlation functions of these operators exhibit power-law decay, modulated by the remaining $\varphi_c$ and $\vartheta_c$ fields, allowing us to investigate the instabilities in the edge. Remarkably, LL becomes unstable towards the SDW (or $\pi$-SDW) and SC (or $\pi$-SC) phases for $K_c < 1$ and $K_c > 1$, respectively, see SM and FIG.~S2 for details \cite{SM}. Under these conditions, either $\varphi_c$ or  $\vartheta_c$ field will also be ordered, further gapping out the charge sector. In mesoscopic systems, this leads to the establishment of quasi-long-range orders~\cite{book:Giamarchi, PhysRevB.92.035139}.

