\section{S1. Effects of interactions and bosonization}
\par Bosonic representations of the right and left moving modes in Eq.~(1) of the main text are:
\begin{equation}\label{eq:S1}
\begin{split}
    R_\mu(r) & = \frac{\kappa_R}{\sqrt{2\pi a}}e^{i[\vartheta_{\mu}(r)-\varphi_{\mu}(r)]}, \\
    L_\mu(r) & = \frac{\kappa_L}{\sqrt{2\pi a}}e^{i[\vartheta_{\mu}(r)+\varphi_{\mu}(r)]},
\end{split}
\end{equation}
where \(a\to 0\) is the length cutoff of the low-energy theory, \(\mu=1,2\) denotes the time-reversal sector, \(\kappa_{R(L)}\) is the Klein factor \cite{PhysRevLett.121.196801}, and the bosonic fields satisfy the commutation relation $[\varphi_i(r),\vartheta_j(r')]=-i\frac{\pi}{2}\text{sgn}(r-r')\delta_{ij}$ for $i,j=1,2$ \cite{book:Giamarchi}. Since all the right (left)-moving modes carry up (down) spin, we suppress the spin index in Eq.~\eqref{eq:S1} for simplicity. Using standard technique \cite{book:Giamarchi}, we then bosonize the Hamiltonian in Eq.~(2) of the main text to obtain: 
\begin{align}
    H_0 = & \int dr\,\frac{\hbar v}{2\pi} \sum_{\mu=1,2} (\partial_r\varphi_\mu(r))^2 + (\partial_r\vartheta_\mu(r))^2 .
\end{align}

\par In the following, we consider general short-range density-density and current-current interactions, described by
\begin{equation}\label{eq:S2}
    H_\text{int} = \frac{1}{2}\int drdr' V(r-r')\rho(r)\rho(r') . 
\end{equation}
Here, $\rho(r)$ denotes charge density, and $V(r-r')$ is the potential related to the short-range density-density interactions:
\begin{align*}
    \rho(r) = & \sum_{\mu=1,2} R^\dagger_\mu(r) R_\mu(r) + L^\dagger_\mu(r) L_\mu(r)+ [ R^\dagger_1(r) R_2(r) e^{-i2k_0r} +  L^\dagger_1(r) L_2(r) e^{i2k_0r} + \text{H.c.} ],
\end{align*}
where $k_0\equiv(k_1+k_2)/2$. The density-density interaction can thus be separated into two terms, $H_\text{int}=H_\text{int}^{(1)}+ H_\text{int}^{(2)}$, where $H_\text{int}^{(1)}$ involves the zero-momentum Fourier component $V_0$ of the interaction:
\begin{equation}\label{eq:S3}
\begin{split}
    H_\text{int}^{(1)} & = \frac{1}{2}\int drdr' \sum_{\mu,\nu=1,2}V(r-r')[R^\dagger_\mu(r) R_\mu(r) + L^\dagger_\mu(r) L_\mu(r)][R^\dagger_\nu(r') R_\nu(r') + L^\dagger_\nu(r') L_\nu(r')]
    \\ & = \frac{1}{2}\int dRdl \sum_{\mu,\nu=1,2}V(l)[R^\dagger_\mu(R+\frac{l}{2}) R_\mu(R+\frac{l}{2}) + L^\dagger_\mu(R+\frac{l}{2}) L_\mu(R+\frac{l}{2})][R^\dagger_\nu(R-\frac{l}{2}) R_\nu(R-\frac{l}{2}) + L^\dagger_\nu(R-\frac{l}{2}) L_\nu(R-\frac{l}{2})]
    \\ & \cong \frac{V_0}{2}\int dR\sum_{\mu,\nu=1,2}[:R^\dagger_\mu(R) R_\mu(R): + :L^\dagger_\mu(R) L_\mu(R):][:R^\dagger_\nu(R) R_\nu(R): + :L^\dagger_\nu(R) L_\nu(R):],
\end{split}
\end{equation}
and $H_\text{int}^{(2)}$ involves the finite-momentum component $V_{2k_0}$: 
\begin{equation}\label{eq:S4}
\begin{split}
    H_\text{int}^{(2)} & \cong \frac{1}{2}\int drdr' V(r-r')\{ e^{-i2k_0(r-r')}[R^\dagger_1(r) R_2(r) + L^\dagger_2(r) L_1(r)][R^\dagger_2(r') R_1(r') + L^\dagger_1(r') L_2(r')] + \text{H.c.} \}
    \\ & = \frac{1}{2}\int drdr' V(r-r')\{ e^{-i2k_0(r-r')}[R^\dagger_1(r) R_2(r)R^\dagger_2(r') R_1(r') + L^\dagger_2(r) L_1(r)L^\dagger_1(r') L_2(r')] + \text{H.c.} \}
    \\ & \quad + \frac{1}{2}\int drdr' V(r-r')\{ e^{-i2k_0(r-r')}[R^\dagger_1(r) R_2(r)L^\dagger_1(r') L_2(r') + L^\dagger_2(r) L_1(r)R^\dagger_2(r') R_1(r')] + \text{H.c.} \}
    \\ & = \frac{1}{2}\int drdr' V(r-r')\{ e^{-i2k_0(r-r')}[:R^\dagger_1(r)R_1(r'): + \langle R^\dagger_1(r)R_1(r')\rangle_0][-:R^\dagger_2(r)R_2(r'): - \langle R^\dagger_2(r)R_2(r')\rangle_0] + \text{H.c.} \}
    \\ & \quad + \frac{1}{2}\int drdr' V(r-r')\{ e^{-i2k_0(r-r')}[:L^\dagger_1(r)L_1(r'): + \langle L^\dagger_1(r)L_1(r')\rangle_0][-:L^\dagger_2(r)L_2(r'): - \langle L^\dagger_2(r)L_2(r')\rangle_0] + \text{H.c.} \}
    \\ & \quad + \frac{1}{2}\int drdr' V(r-r')\{ e^{-i2k_0(r-r')}[:R^\dagger_1(r) R_2(r)::L^\dagger_1(r') L_2(r'): + :L^\dagger_2(r) L_1(r)::R^\dagger_2(r') R_1(r'):] + \text{H.c.} \}
    \\ & = \frac{1}{2}\int dRdl V(l)\{ e^{-i2k_0(l)}[:R^\dagger_1(R+\frac{l}{2})R_1(R-\frac{l}{2}): + \frac{1}{\pi l}][-:R^\dagger_2(R+\frac{l}{2})R_2(R-\frac{l}{2}): - \frac{1}{\pi l}] + \text{H.c.} \}
    \\ & \quad + \frac{1}{2}\int dRdl V(l)\{ e^{-i2k_0(l)}[:L^\dagger_1(R+\frac{l}{2})L_1(R-\frac{l}{2}): + \frac{1}{\pi l}][-:L^\dagger_2(R+\frac{l}{2})L_2(R-\frac{l}{2}): - \frac{1}{\pi l}] + \text{H.c.} \}
    \\ & \quad + \frac{1}{2}\int dRdl V(l)\{ e^{-i2k_0(l)}[:R^\dagger_1(R+\frac{l}{2}) R_2(R+\frac{l}{2})::L^\dagger_1(R-\frac{l}{2}) L_2(R-\frac{l}{2}): 
    \\ & \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad + :L^\dagger_2(R+\frac{l}{2}) L_1(R+\frac{l}{2})::R^\dagger_2(R-\frac{l}{2}) R_1(R-\frac{l}{2}):] + \text{H.c.} \}
    \\ & \cong \frac{1}{2}\int dRdl V(l)\{ e^{-i2k_0(l)}[-:R^\dagger_1(R)R_1(R)::R^\dagger_2(R)R_2(R):] + \text{H.c.} \} 
    \\ & \quad - \frac{1}{2}\int dRdl V(l)\{\frac{e^{-i2k_0(l)}}{2\pi}\sum_{\mu=1,2}[(\partial_RR^\dagger_\mu(R))R_\mu(R) - R^\dagger_\mu(R)(\partial_RR_\mu(R))] + \text{H.c.} \}
    \\ & \quad + \frac{1}{2}\int dRdl V(l)\{ e^{-i2k_0(l)}[-:L^\dagger_1(R)L_1(R)::L^\dagger_2(R)L_2(R):] + \text{H.c.} \} 
    \\ &  \quad - \frac{1}{2}\int dRdl V(l)\{\frac{e^{-i2k_0(l)}}{2\pi}\sum_{\mu=1,2}[(\partial_RL^\dagger_\mu(R))L_\mu(R) - L^\dagger_\mu(R)(\partial_RL_\mu(R))] + \text{H.c.} \}
    \\ & \quad + \frac{1}{2}\int dRdl V(l)\{ e^{-i2k_0(l)}[:R^\dagger_1(R) R_2(R)::L^\dagger_1(R) L_2(R): + :L^\dagger_2(R) L_1(R)::R^\dagger_2(R) R_1(R):] + \text{H.c.} \}
    \\ & = V_{2k_0}\int dR [-:R^\dagger_1(R)R_1(R)::R^\dagger_2(R)R_2(R):-:L^\dagger_1(R)L_1(R)::L^\dagger_2(R)L_2(R):]
    \\ & \quad + V_{2k_0}\int dR [:R^\dagger_1(R) R_2(R)::L^\dagger_1(R) L_2(R): + \text{H.c.} ],
\end{split}
\end{equation}
Here, we neglect the fast-oscillating terms ($\propto e^{i2k_0(r+r')}$), the constant terms, the terms renormalizing the chemical potential, and all the irrelevant terms from dimensional analysis. We also apply Wick's theorem, and keep terms only up to $\mathcal{O}(l)$ throughout the derivation in view of the assumption of slow-varying fields \cite{PhysRevB.61.13410, PhysRevB.102.165147}, where we assume $R\equiv(r+r')/2$ and $l\equiv r-r'$, and $R\gg l$. Then, $H_\text{int}^{(1)}$ and $ H_\text{int}^{(2)}$ can be further bosonized into:
\begin{equation}\label{eq:S5}
\begin{split}
    H_\text{int}^{(1)} & = \frac{V_0}{2\pi^2}\int dr\sum_{\mu,\nu=1,2}[\partial_r\varphi_\mu(r)][\partial_r\varphi_\nu(r)] 
    \\ & = \frac{V_0}{4\pi^2}\int dr\sum_{\xi,\zeta=\pm1}[\partial_r(\varphi_c(r)+\xi\varphi_\tau(r))][\partial_r(\varphi_c(r)+\zeta\varphi_\tau(r))]
    \\ & = \frac{V_0}{\pi^2}\int dr [\partial_r\varphi_c(r)]^2,
\end{split}
\end{equation}
and
\begin{equation}\label{eq:S5.5}
\begin{split}
    H_\text{int}^{(2)} & = \frac{-V_{2k_0}}{4\pi^2}\int dr \partial_r[\vartheta_1(r)-\varphi_1(r)]\partial_r[\vartheta_2(r)-\varphi_2(r)] + \partial_r[\vartheta_1(r)+\varphi_1(r)]\partial_r[\vartheta_2(r)+\varphi_2(r)]
    \\ & \quad + \frac{V_{2k_0}}{4\pi^2a^2}\int dre^{i[\varphi_1(r)-\vartheta_1(r)+\vartheta_2(r)-\varphi_2(r)]}e^{i[-\varphi_1(r)-\vartheta_1(r)+\vartheta_2(r)+\varphi_2(r)]} + \text{H.c.}
    \\ & = \frac{-V_{2k_0}}{2\pi^2}\int dr \partial_r[\vartheta_1(r)]\partial_r[\vartheta_2(r)] + \partial_r[\varphi_1(r)]\partial_r[\varphi_2(r)]
    \\ & \quad + \frac{V_{2k_0}}{2\pi^2a^2}\int dr\cos[2\vartheta_1(r)-2\vartheta_2(r)]
    \\ & = \frac{-V_{2k_0}}{4\pi^2}\int dr \partial_r[\vartheta_c(r)+\vartheta_\tau(r)]\partial_r[\vartheta_c(r)-\vartheta_\tau(r)] + \partial_r[\varphi_c(r)+\varphi_\tau(r)]\partial_r[\varphi_c(r)-\varphi_\tau(r)]
    \\ & \quad + \frac{V_{2k_0}}{2\pi^2a^2}\int dr\cos[2\sqrt{2}\vartheta_\tau(r)]
    \\ & = \frac{V_{2k_0}}{4\pi^2}\int dr -[\partial_r\varphi_c(r)]^2 + [\partial_r\varphi_\tau(r)]^2 - [\partial_r\vartheta_c(r)]^2 + [\partial_r\vartheta_\tau(r)]^2
    \\ & \quad + \frac{V_{2k_0}}{2\pi^2a^2}\int dr\cos[2\sqrt{2}\vartheta_\tau(r)].
\end{split}
\end{equation}
Here, we define the charge and pseudospin degree of freedom labeled by the indices $c$ and $\tau$, respectively:
\begin{equation}\label{eq:S6}
    \begin{pmatrix}\varphi_c(r) \\ \varphi_\tau(r) \end{pmatrix} \equiv \frac{1}{\sqrt{2}}\begin{pmatrix} 1 & 1 \\ 1 & -1 \end{pmatrix}\begin{pmatrix}\varphi_1(r) \\ \varphi_2(r) \end{pmatrix},\quad \begin{pmatrix}\vartheta_c(r) \\ \vartheta_\tau(r) \end{pmatrix} \equiv \frac{1}{\sqrt{2}}\begin{pmatrix} 1 & 1 \\ 1 & -1 \end{pmatrix}\begin{pmatrix}\vartheta_1(r) \\ \vartheta_2(r) \end{pmatrix},
\end{equation}
which satisfies the commutation relation $[\varphi_\mu(r),\vartheta_\nu(r')]=-i\frac{\pi}{2}\text{sgn}(r-r')\delta_{\mu\nu}$ for $\mu,\nu=c,\tau$. To prove this commutation relation, note that Eq.~\eqref{eq:S6} can be expressed as $\varphi_\mu(r) = (U)_{\mu i}\varphi_i(r)$ and $\vartheta_\mu(r) = (U)_{\mu i}\vartheta_i(r)$ for $\mu=c,\tau$ and $i=1,2$, where $U=\frac{1}{\sqrt{2}}\begin{pmatrix} 1 & 1 \\ 1 & -1 \end{pmatrix}$. Then, since $U$ is orthogonal, one obtains 
\begin{equation}
\begin{split}
[\varphi_\mu(r),\vartheta_\nu(r')] & = (U)_{\mu i}(U)_{\nu j}[\varphi_i(r),\vartheta_j(r')] 
\\ & = -i\frac{\pi}{2}\text{sgn}(r-r')(U)_{\mu i}(U)_{\nu j}\delta_{ij}
\\ & = -i\frac{\pi}{2}\text{sgn}(r-r')(U)_{\mu i}(U^T)_{i\nu}
\\ & = -i\frac{\pi}{2}\text{sgn}(r-r')(UU^T)_{\mu\nu}
\\ & = -i\frac{\pi}{2}\text{sgn}(r-r')\delta_{\mu\nu}.
\end{split}
\end{equation}
The charge and pseudospin sectors represent the symmetric and anti-symmetric sectors, respectively, as described in the literature~\cite{PhysRevLett.103.166403, PhysRevB.109.155119, PhysRevB.99.045125, PhysRevB.98.115146, PhysRevB.93.235436, PhysRevB.86.165121}. The nomenclature here reflects the nature of the collective excitations present within these sectors, a point to which we will return below.

\par The Hamiltonian for a general short-range current-current interaction can be expressed as:
\begin{equation}\label{eq:S7}
    \tilde{H}_\text{int} = \frac{1}{2}\int drdr' \tilde{V}(r-r')J(r)J(r') .
\end{equation}
Here, $J(r)$ is the current density and $\tilde{V}(r-r')$ is the potential for the short-range current-current interaction. Due to the helical nature of the edge states, the current density, $J(r)$, is equivalent to the spin density, $\rho_s(r)$, up to a proportionality constant, see equations above. Therefore, the current-current interaction can be regarded as the spin-density-spin-density interaction in helical systems. More specifically:
\begin{align*}
    J(r) = & \sum_{\mu=1,2} R^\dagger_\mu(r) R_\mu(r) - L^\dagger_\mu(r) L_\mu(r)+ [ R^\dagger_1(r) R_2(r) e^{-i2k_0r} -  L^\dagger_1(r) L_2(r) e^{i2k_0r} + \text{H.c.} ].
\end{align*}
The current-current interaction can be separated into two terms like the density-density interaction, $\tilde{H}_\text{int}=\tilde{H}_\text{int}^{(1)} + \tilde{H}_\text{int}^{(2)}$, where $\tilde{H}_\text{int}^{(1)}$ involves the zero-momentum Fourier component $\tilde{V}_0$ of the interaction:
\begin{equation}\label{eq:S9}
\begin{split}
    \tilde{H}_\text{int}^{(1)} & = \frac{1}{2}\int drdr' \sum_{\mu,\nu=1,2}\tilde{V}(r-r')[R^\dagger_\mu(r) R_\mu(r) - L^\dagger_\mu(r) L_\mu(r)][R^\dagger_\nu(r') R_\nu(r') - L^\dagger_\nu(r') L_\nu(r')]
    \\ & \cong \frac{\tilde{V}_0}{2}\int dR\sum_{\mu,\nu=1,2}[:R^\dagger_\mu(R) R_\mu(R): - :L^\dagger_\mu(R) L_\mu(R):][:R^\dagger_\nu(R) R_\nu(R): - :L^\dagger_\nu(R) L_\nu(R):],
\end{split}
\end{equation}
and $\tilde{H}_\text{int}^{(2)}$ involves the zero-momentum Fourier component $\tilde{V}_{2k_0}$ of the interaction:
\begin{equation}\label{eq:S10}
\begin{split}
    \tilde{H}_\text{int}^{(2)} & = \frac{1}{2}\int drdr' \tilde{V}(r-r')\{ e^{-i2k_0(r-r')}[R^\dagger_1(r) R_2(r) - L^\dagger_2(r) L_1(r)][R^\dagger_2(r') R_1(r') - L^\dagger_1(r') L_2(r')] + \text{H.c.} \}
    \\ & = \frac{1}{2}\int drdr' \tilde{V}(r-r')\{ e^{-i2k_0(r-r')}[R^\dagger_1(r) R_2(r)R^\dagger_2(r') R_1(r') + L^\dagger_2(r) L_1(r)L^\dagger_1(r') L_2(r')] + \text{H.c.} \}
    \\ & \quad - \frac{1}{2}\int drdr' \tilde{V}(r-r')\{ e^{-i2k_0(r-r')}[R^\dagger_1(r) R_2(r)L^\dagger_1(r') L_2(r') + L^\dagger_2(r) L_1(r)R^\dagger_2(r') R_1(r')] + \text{H.c.} \}
    \\ & \cong \tilde{V}_{2k_0}\int dR [-:R^\dagger_1(R)R_1(R)::R^\dagger_2(R)R_2(R):-:L^\dagger_1(R)L_1(R)::L^\dagger_2(R)L_2(R):] 
    \\ & \quad - \tilde{V}_{2k_0}\int dR [:R^\dagger_1(R) R_2(R)::L^\dagger_1(R) L_2(R): + \text{H.c.} ].
\end{split}
\end{equation}
Then, $\tilde{H}_\text{int}^{(1)}$ and $\tilde{H}_\text{int}^{(2)}$ can be further bosonized into:
\begin{align}
    \tilde{H}_\text{int}^{(1)} & = \frac{\tilde{V}_0}{\pi^2}\int dr [\partial_r\vartheta_c(r)]^2,
    \\ \tilde{H}_\text{int}^{(2)} & = \frac{\tilde{V}_{2k_0}}{4\pi^2}\int dr \{ -[\partial_r\varphi_c(r)]^2 + [\partial_r\varphi_\tau(r)]^2 - [\partial_r\vartheta_c(r)]^2 + [\partial_r\vartheta_\tau(r)]^2 \} - \frac{\tilde{V}_{2k_0}}{2\pi^2a^2}\int dr\cos[2\sqrt{2}\vartheta_\tau(r)].
\end{align}

\par By incorporating the density-density and current-current interactions into the bosonized Hamiltonian, $H_0$, we obtain the Hamiltonian of a two-channel Luttinger liquid, $H_{\text{LL}}$ and a sine-Gordon-like mass term, $H_{\text{m}}$:
\begin{equation}\label{eq:S11}
\begin{split}
    H_{\text{LL}} & = \int dr\,\frac{\hbar}{2\pi}\sum_{\mu=c,\tau} u_\mu[K_\mu^{-1}(\partial_r\varphi_\mu(r))^2 + K_\mu(\partial_r\vartheta_\mu(r))^2],
    \\ H_{\text{m}} & =  \int dr\,\frac{V_{2k_0}-\tilde{V}_{2k_0}}{2(\pi a)^2}\cos[2\sqrt{2}\vartheta_\tau(r)].
\end{split}
\end{equation} 
Here, the corresponding Luttinger liquid parameters are:
\begin{equation}\label{eq:S12}
    K_c = \sqrt{\frac{1+\frac{1}{\pi\hbar v}[2\tilde{V}_0 - \frac{1}{2}(V_{2k_0} + \tilde{V}_{2k_0})]}{1+\frac{1}{\pi\hbar v}[2V_0 - \frac{1}{2}(V_{2k_0} + \tilde{V}_{2k_0})]}}\text{ and }K_\tau = 1,
\end{equation}
and the renormalized velocities are:
\begin{equation}\label{eq:S12.5}
    u_c = \frac{v}{K_c}\{1+\frac{1}{\pi\hbar v}[2\tilde{V}_0 - \frac{1}{2}(V_{2k_0} + \tilde{V}_{2k_0})]\} \text{ and }u_\tau=\frac{v}{K_\tau}[1+\frac{1}{2\pi\hbar v}(V_{2k_0} + \tilde{V}_{2k_0})].
\end{equation}

% =========================================
\section{S2. Renormalization-group (RG) flow equations}
\par  According to Eq.~\eqref{eq:S11}, the perturbative RG flow equations to the leading order contribution can be derived through a standard procedure \cite{book:Giamarchi, PhysRevB.97.045415}:
\begin{align}
    \frac{dK_\tau}{dl} = &  2\tilde{m}^2,         \label{eq:S13}
    \\ \frac{d\tilde{m}}{dl} = & 2(1-K_\tau^{-1})\tilde{m},  \label{eq:S14}
\end{align}
where $\tilde{m}\equiv m/\hbar v$ and $m\equiv V_{2k_0}-\tilde{V}_{2k_0}$. The flow trajectories are described by:
\begin{equation}\label{eq:S15}
    \tilde{m}^2 = 2[K_\tau - \ln(K_\tau)] + \text{constant}. 
\end{equation}
Note that around the non-interacting point, $K_\tau=1$, the RG flow equations restore the celebrated Kosterlitz RG flow equations \cite{J_M_Kosterlitz_1974}, which can be understood better if we define $\delta K_\tau\equiv2(1-K_\tau)$ and $y\equiv2\tilde{m}$. Then, to order $\mathcal{O}(\delta K_\tau)$, equations~\eqref{eq:S13} and \eqref{eq:S14} become:
\begin{align}
    \frac{d\delta K_\tau}{dl} = &  -y^2,        
    \\ \frac{dy}{dl} = & -\delta K_\tau y.  
\end{align}
Since $K_{\tau}$ monotonically increases under the RG flow according to Eq.~\eqref{eq:S13}, $\tilde{m}$ is relevant only if:
\begin{align}\label{eq:SRG1}
[\tilde{m}(l=0)]^2 - 2\{K_\tau(l=0) - \ln[K_\tau(l=0)]\} > -2, \, \text{ or } \, K_\tau(l=0) \geq 1 \text{ with } \tilde{m}(l=0)\neq0,
\end{align}
based on the solutions shown in Eq.~\eqref{eq:S15}. Otherwise, $\tilde{m}$ is irrelevant. The critical line for $\tilde{m}$ to be relevant corresponds to:
\begin{equation}\label{eq:SRG2}
[\tilde{m}(l=0)]^2 - 2\{K_\tau(l=0) - \ln[K_\tau(l=0)]\} = -2 \text{ with } K_\tau(l=0) \leq 1.
\end{equation}
Note that Eqs.~\eqref{eq:SRG1} and \eqref{eq:SRG2} are equivalent to Eq.~(6) of the main text.

\par As FIG.~2 of the main text shows, the RG flow equations described byEqs.~\eqref{eq:S13} and \eqref{eq:S14} have drain-like (source-like) fixed points $(K_\tau,\tilde{m})=(K_\tau^*,0)$ for some $K_\tau^*<1\,(K_\tau^*>1)$ and a saddle-point-like fixed point $(K_\tau,\tilde{m})=(1,0)$. Furthermore, since $K_\tau(l=0)=1$ according to Eq.~\eqref{eq:S12}, the mass term remains relevant as long as $\tilde{m}(l=0)\neq0$ in view of Eq.~\eqref{eq:SRG1}.

Importantly, since the RG flows that lead to a relevant mass term with $K_\tau(l=0)=1$ always pass through $K_\tau=2$ without closing the energy gap, see FIG. 2 of the main text), the interacting Hamiltonian density of the pseudospin sector with $m\neq0$ can always be adiabatically connected to the non-interacting Hamiltonian density in Eq.~9 of the main text, providing a solid basis for the emergence of the MKP in the strongly interacting region in practice. 

