\section{S3. Quasi-long-range orders}
\par Here, we derive the bosonized expression of the operators that may lead to quasi-long-range orders discussed in the main text. The operator characterizing the instability of the $x$ component of the spin-density wave (SDW), $\Delta_{2q}^{(x)}$, is:
\begin{equation}
\begin{split}
    \Delta_{2q}^{(x)} & = \sum_{\substack{\mu=1,2 \\ \nu\neq\mu}} L_\mu^\dagger(r) R_\nu(r) + \text{H.c.}
    \\ & \sim \frac{1}{2\pi a}[ e^{-i[\varphi_1(r)+\vartheta_1(r)+\varphi_2(r)-\vartheta_2(r)]} + e^{-i[\varphi_2(r)+\vartheta_2(r)+\varphi_1(r)-\vartheta_1(r)]} - \text{H.c.} ]
     \\ & = \frac{1}{2\pi a}[ e^{-i\sqrt{2}[\varphi_c(r)+\vartheta_\tau(r)]} + e^{-i\sqrt{2}[\varphi_c(r)-\vartheta_\tau(r)]} - \text{H.c.} ]
     \\ & = \frac{1}{\pi a}[ e^{-i\sqrt{2}\varphi_c(r)}\cos[\sqrt{2}\vartheta_\tau(r)] - \text{H.c.} ]
    \\ & = \frac{-2i}{\pi a}\sin[\sqrt{2}\varphi_c(r)]\cos[\sqrt{2}\vartheta_\tau(r)],
\end{split}
\end{equation}
where the subscript denotes the nesting vector $2q$; that is, the momentum difference between $L_\mu$ and $ R_\nu$ as shown in FIG. 1 of the main text.
Similarly, the operator characterizing the instability of the y component of the SDW, $\Delta_{2q}^{(y)}$, is:
\begin{equation}
\begin{split}
    \Delta_{2q}^{(y)} & = \sum_{\substack{\mu=1,2 \\ \nu\neq\mu}} iL_\mu^\dagger(r) R_\nu(r) + \text{H.c.}
    \\ & \sim \frac{1}{2\pi a}\{ ie^{-i[\varphi_1(r)+\vartheta_1(r)+\varphi_2(r)-\vartheta_2(r)]} + ie^{-i[\varphi_2(r)+\vartheta_2(r)+\varphi_1(r)-\vartheta_1(r)]} - \text{H.c.} \}
    \\ &  = \frac{1}{2\pi a}\{ ie^{-i\sqrt{2}[\varphi_c(r)+\vartheta_\tau(r)]} + ie^{-i\sqrt{2}[\varphi_c(r)-\vartheta_\tau(r)]} - \text{H.c.} \}
    \\ &  = \frac{1}{\pi a}\{ ie^{-i\sqrt{2}\varphi_c(r)}\cos[\sqrt{2}\vartheta_\tau(r)] - \text{H.c.} \}
    \\ & = \frac{2i}{\pi a}\cos[\sqrt{2}\varphi_c(r)]\cos[\sqrt{2}\vartheta_\tau(r)].
\end{split}
\end{equation}
In addition to the in-plane components of the SDW, the out-of-plane component of the SDW has a nesting vector $2k_0$. The corresponding operator, $\Delta_{2k_0}^{(\text{z})}$, can be expressed as:
\begin{equation}
\begin{split}
    \Delta_{2k_0}^{(\text{z})} & =  R^\dagger_1(r) R_2(r) - L^\dagger_1(r) L_2(r) + \text{H.c.}
    \\ & \sim \frac{1}{2\pi a}\{ e^{i[-\varphi_1(r)+\vartheta_1(r)+\varphi_2(r)-\vartheta_2(r)]} 
     - e^{i[\varphi_1(r)+\vartheta_1(r)-\varphi_2(r)-\vartheta_2(r)]}\} + \text{H.c.}
    \\ & = \frac{1}{\pi a}\{ \cos[-\sqrt{2}\varphi_\tau(r) + \sqrt{2}\vartheta_\tau(r)] 
     - \cos[\sqrt{2}\varphi_\tau(r) + \sqrt{2}\vartheta_\tau(r)]  \}
    \\ & = \frac{2}{\pi a}\sin[\sqrt{2}\varphi_\tau(r)]\sin[\sqrt{2}\vartheta_\tau(r)].
\end{split}
\end{equation}

Besides the regular SDWs, we define the $\pi$-SDW orders, which are SDWs with a $\pi$-phase difference for nesting between different pairs of fermi points, resulting in a sign change upon interchanging the time-reversal sectors. The operator characterizing the instability of its $x$-component, $\Delta_{2q,\pi}^{(x)}$, is:
\begin{equation}
\begin{split}
    \Delta_{2q,\pi}^{(x)} & = L_1^\dagger(r) R_2(r) + \text{H.c.} - (1\leftrightarrow2)
    \\ & \sim \frac{1}{2\pi a}[ e^{-i[\varphi_1(r)+\vartheta_1(r)+\varphi_2(r)-\vartheta_2(r)]} - e^{-i[\varphi_2(r)+\vartheta_2(r)+\varphi_1(r)-\vartheta_1(r)]} - \text{H.c.} ]
     \\ & = \frac{1}{2\pi a}[ e^{-i\sqrt{2}[\varphi_c(r)+\vartheta_\tau(r)]} - e^{-i\sqrt{2}[\varphi_c(r)-\vartheta_\tau(r)]} - \text{H.c.} ]
     \\ & = \frac{1}{\pi a}[ -ie^{-i\sqrt{2}\varphi_c(r)}\sin[\sqrt{2}\vartheta_\tau(r)] - \text{H.c.} ]
    \\ & = \frac{-2i}{\pi a}\cos[\sqrt{2}\varphi_c(r)]\sin[\sqrt{2}\vartheta_\tau(r)].
\end{split}
\end{equation}
Similarly, the operator characterizing the instability of the $y$-component of $\pi$-SDW, $\Delta_{2q,\pi}^{(y)}$, is:
\begin{equation}
\begin{split}
    \Delta_{2q,\pi}^{(y)} & = iL_1^\dagger(r) R_2(r) + \text{H.c.} - (1\leftrightarrow2)
    \\ & \sim \frac{1}{2\pi a}\{ ie^{-i[\varphi_1(r)+\vartheta_1(r)+\varphi_2(r)-\vartheta_2(r)]} - ie^{-i[\varphi_2(r)+\vartheta_2(r)+\varphi_1(r)-\vartheta_1(r)]} - \text{H.c.} \}
    \\ &  = \frac{1}{2\pi a}\{ ie^{-i\sqrt{2}[\varphi_c(r)+\vartheta_\tau(r)]} - ie^{-i\sqrt{2}[\varphi_c(r)-\vartheta_\tau(r)]} - \text{H.c.} \}
    \\ &  = \frac{1}{\pi a}\{ e^{-i\sqrt{2}\varphi_c(r)}\sin[\sqrt{2}\vartheta_\tau(r)] - \text{H.c.} \}
    \\ & = \frac{-2i}{\pi a}\sin[\sqrt{2}\varphi_c(r)]\sin[\sqrt{2}\vartheta_\tau(r)].
\end{split}
\end{equation}
Given that $R_\mu\to L_\mu$, $L_\mu\to -R_\mu$, and $i\to-i$ through TRS, the $\pi$-SDWs undergo the transformation $\Delta_{2q,\pi}^{(x/y)}\to\Delta_{2q,\pi}^{(x/y)}$ under TRS, thus maintaining TRS. As an alternative, TRS of $\pi$-SDWs can be verified using bosonic fields, where under TRS, $\varphi_\mu\to\varphi_\mu$ and $\vartheta_\mu\to-\vartheta_\mu+\pi$, according to Eq.~\eqref{eq:S1}. This results in transformations: $\varphi_{c(\tau)}\to\varphi_{c(\tau)}$, $\vartheta_c\to-\vartheta_c+\sqrt{2}\pi$, and $\vartheta_\tau\to-\vartheta_\tau$, according to Eq.~\eqref{eq:S6}. Consequently, together with $i\to-i$ through TRS, the $\pi$-SDWs preserve TRS according to their bosonized expressions.


\par The  operator characterizing the instability of the superconductivity (SC), $\Delta_{\text{SC}}$, is:
\begin{equation}
\begin{split}
    \Delta_{\text{SC}} & = \sum_{\mu=1,2} R_\mu^\dagger(r) L_\mu^\dagger(r) - L_\mu^\dagger(r) R_\mu^\dagger(r)
     \\ & \sim \frac{1}{\pi a}\{e^{i[\varphi_1(r)-\vartheta_1(r)-\vartheta_1(r)-\varphi_1(r)]}+(1\leftrightarrow2)\}
     \\ & = \frac{1}{\pi a}\{e^{-i2\vartheta_1(r)}+e^{-i2\vartheta_2(r)} \}
    \\ & = \frac{1}{\pi a}\{e^{-i\sqrt{2}[\vartheta_c(r)+\vartheta_\tau(r)]}+e^{-i\sqrt{2}[\vartheta_c(r)-\vartheta_\tau(r)]} \}
    \\ & = \frac{2}{\pi a}e^{-i\sqrt{2}\vartheta_c(r)}\cos[\sqrt{2}\vartheta_\tau(r)].
\end{split}
\end{equation}
We can also define the $\pi$-SC order, which is SC with out-of-phase pairing between different time-reversal sectors, analogous to the $\pi$-junction settings \cite{PhysRevLett.115.237001, Hsu_2021, PhysRevLett.100.096407, PhysRevLett.111.116402, PhysRevLett.122.126402, PhysRevLett.120.267002, PhysRevLett.129.227002, PhysRevB.97.014507, PhysRevB.89.220504}. The operator characterizing its instability, $\Delta_{\text{SC},\pi}$, is:
\begin{equation}
\begin{split}
    \Delta_{\text{SC},\pi} & = R_1^\dagger(r) L_1^\dagger(r) - L_1^\dagger(r) R_1^\dagger(r) - (1\leftrightarrow2)
     \\ & \sim \frac{1}{\pi a}\{e^{i[\varphi_1(r)-\vartheta_1(r)-\vartheta_1(r)-\varphi_1(r)]}-(1\leftrightarrow2)\}
     \\ & = \frac{1}{\pi a}\{e^{-i2\vartheta_1(r)}-e^{-i2\vartheta_2(r)} \}
    \\ & = \frac{1}{\pi a}\{e^{-i\sqrt{2}[\vartheta_c(r)+\vartheta_\tau(r)]}-e^{-i\sqrt{2}[\vartheta_c(r)-\vartheta_\tau(r)]} \}
    \\ & = \frac{-2i}{\pi a}e^{-i\sqrt{2}\vartheta_c(r)}\sin[\sqrt{2}\vartheta_\tau(r)].
\end{split}
\end{equation}
FIG.~\ref{fig:S1} schematically shows differences between SDW and $\pi$-SDW as well as  SC and $\pi$-SC.

