  \centering
    \includegraphics[width=0.75\linewidth]{figS1.pdf}
  \caption{ Phase differences for (a) nesting between two pairs of fermi points in the SDW (green) and the $\pi$-SDW (orange), and (b) for paring between different time-reversal sectors in the SC (green) and the $\pi$-SC (orange) phases.  }
  \label{fig:S1}
\end{figure}

We also consider several variations of the pair destiny wave (PDW) \cite{RevModPhys.87.457, annurev_PDW, PhysRevB.79.064515, PhysRevB.91.195102, PhysRevB.101.165133, PhysRevLett.113.256405}.   The operator characterizing the instability of the singlet pair density wave (PDW), $\Delta_{2q}^{(\text{sPDW})}$, is:
\begin{equation}
\begin{split}
\Delta_{2q}^{(\text{sPDW})} & = \sum_{\substack{\mu=1,2 \\ \nu\neq\mu}} R_\mu^\dagger(r) L_\nu^\dagger(r) - L_\nu^\dagger(r) R_\mu^\dagger(r)
\\ & \sim \frac{1}{\pi a}\{e^{i[\varphi_1(r)-\vartheta_1(r)-\vartheta_2(r)-\varphi_2(r)]}+ e^{i[\varphi_2(r)-\vartheta_2(r)-\vartheta_1(r)-\varphi_1(r)]}\}
\\ & = \frac{1}{\pi a}\{e^{i\sqrt{2}[\varphi_\tau(r)-\vartheta_c(r)]}+ e^{i\sqrt{2}[-\varphi_\tau(r)-\vartheta_c(r)]}\}
\\ & = \frac{2}{\pi a}e^{-i\sqrt{2}\vartheta_c(r)}\cos[\sqrt{2}\varphi_\tau(r)].
\end{split}
\end{equation}
Like the $\pi$-SDW, the operator characterizing the instability, $\Delta_{2q,\pi}^{(\text{sPDW})}$, for the $\pi$-singlet PDW is:
\begin{equation}
\begin{split}
\Delta_{2q,\pi}^{(\text{sPDW})} & = R_1^\dagger(r) L_2^\dagger(r) - L_2^\dagger(r) R_1^\dagger(r) - (1\leftrightarrow2)
\\ & \sim \frac{1}{\pi a}\{e^{i[\varphi_1(r)-\vartheta_1(r)-\vartheta_2(r)-\varphi_2(r)]} - e^{i[\varphi_2(r)-\vartheta_2(r)-\vartheta_1(r)-\varphi_1(r)]}\}
\\ & = \frac{1}{\pi a}\{e^{i\sqrt{2}[\varphi_\tau(r)-\vartheta_c(r)]} - e^{i\sqrt{2}[-\varphi_\tau(r)-\vartheta_c(r)]}\}
\\ & = \frac{2i}{\pi a}e^{-i\sqrt{2}\vartheta_c(r)}\sin[\sqrt{2}\varphi_\tau(r)].
\end{split}
\end{equation}
The operator characterizing the instability of the $x$-component of the triplet PDW, $\Delta_{2q}^{(\text{tPDW;x})}$, is:
\begin{equation}
\begin{split}
\Delta_{2q}^{(\text{tPDW;x})} & = \sum_{\substack{\mu=1,2 \\ \nu\neq\mu}} R_\mu^\dagger(r) R_\nu^\dagger(r) - L_\mu^\dagger(r) L_\nu^\dagger(r)
\\ & \sim \frac{1}{\pi a}\{e^{i[\varphi_1(r)-\vartheta_1(r)+\varphi_2(r)-\vartheta_2(r)]}- e^{-i[\varphi_1(r)+\vartheta_1(r)+\varphi_2(r)+\vartheta_2(r)]}\}
\\ & = \frac{1}{\pi a}\{e^{i\sqrt{2}[\varphi_c(r)-\vartheta_c(r)]}- e^{i\sqrt{2}[-\varphi_c(r)-\vartheta_c(r)]}\}
\\ & = \frac{2i}{\pi a}e^{-i\sqrt{2}\vartheta_c(r)}\sin[\sqrt{2}\varphi_c(r)],
\end{split}
\end{equation}
and the operator characterizing the instability of the $y$-component of the triplet PDW, $\Delta_{2q}^{(\text{tPDW;y})}$, is:
\begin{equation}
\begin{split}
\Delta_{2q}^{(\text{tPDW;y})} & = -i\sum_{\substack{\mu=1,2 \\ \nu\neq\mu}} R_\mu^\dagger(r) R_\nu^\dagger(r) + L_\mu^\dagger(r) L_\nu^\dagger(r)
\\ & \sim \frac{-i}{\pi a}\{e^{i[\varphi_1(r)-\vartheta_1(r)+\varphi_2(r)-\vartheta_2(r)]}+e^{-i[\varphi_1(r)+\vartheta_1(r)+\varphi_2(r)+\vartheta_2(r)]}\}
\\ & = \frac{-i}{\pi a}\{e^{i\sqrt{2}[\varphi_c(r)-\vartheta_c(r)]}+ e^{i\sqrt{2}[-\varphi_c(r)-\vartheta_c(r)]}\}
\\ & = \frac{-2i}{\pi a}e^{-i\sqrt{2}\vartheta_c(r)}\cos[\sqrt{2}\varphi_c(r)].
\end{split}
\end{equation}
And the operator characterizing the instability of the charge density wave (CDW), $\Delta_{2k_0}^{(\text{CDW})}$, is:
\begin{equation}
\begin{split}
\Delta_{2k_0}^{(\text{CDW})} & = R^\dagger_1(r) R_2(r) + L^\dagger_1(r) L_2(r) + \text{H.c.}
\\ & \sim \frac{1}{2\pi a}\{e^{i[\varphi_1(r)-\vartheta_1(r)+\vartheta_2(r)-\varphi_2(r)]} + e^{i[-\varphi_1(r)-\vartheta_1(r)+\vartheta_2(r)+\varphi_2(r)]} + \text{H.c.} \}
\\ & = \frac{1}{2\pi a}\{e^{i\sqrt{2}[\varphi_\tau(r)-\vartheta_\tau(r)]} + e^{i[-\varphi_\tau(r)-\vartheta_\tau(r)]} + \text{H.c.} \}
\\ & = \frac{1}{\pi a}\{e^{-i\sqrt{2}\vartheta_\tau(r)}\cos[\sqrt{2}\varphi_\tau(r)] + \text{H.c.} \}
\\ & = \frac{2}{\pi a}\cos[\sqrt{2}\vartheta_\tau(r)]\cos[\sqrt{2}\varphi_\tau(r)].
\end{split}
\end{equation}

\par As pointed out in the main text, the in-plane components of the SDWs and SCs develop quasi-long-range orders, which can host power-law-decaying correlation functions. When $\vartheta_\tau(r)$ is pinned due to $H_{\text{m}}$ in Eq.~\eqref{eq:S11}, thes correlations can be shown to scale as \cite{book:Giamarchi}:
\begin{align}
 \langle \Delta_{2q}^{(\pm)}(\mathfrak{r})\Delta_{2q}^{(\mp)}(0) \rangle & \sim |\mathfrak{r}|^{-K_c}
\\  \langle \Delta_{\text{SC}(,\pi)}(\mathfrak{r})\Delta_{\text{SC}(,\pi)}(0) \rangle & \sim |\mathfrak{r}|^{-K_c^{-1}}.
\end{align} 
Here, $\mathfrak{r}=(r,v\tau)$ with the imaginary time $\tau$ and $\Delta_{2q}^{(\pm)}\equiv\Delta_{2q(,\pi)}^{(x)}\pm i\Delta_{2q(,\pi)}^{(y)}$. The corresponding susceptibilities are:
\begin{align}
    \chi_{\text{SDW}} & \sim \omega^{K_c-2}         \label{eq:S16}
    \\ \chi_{\text{SC}} & \sim \omega^{K_c^{-1}-2},  \label{eq:S17}
\end{align}
suggesting that the quasi-long-range in-plane components of the SDW and SC orders are likely to form when $K_c<2$ and $K_c>\frac{1}{2}$, respectively, as a consequence of the divergent susceptibilities \cite{book:Giamarchi}. This will further gap out the charge sector. 

Within the region $\frac{1}{2}<K_c<2$, both the in-plane components of the SDWs and the SCs can develop a quasi-long-range ordering. However, with distinct scaling dimensions for $K_c \neq 1$, their susceptibilities in Eqs.~\eqref{eq:S16} and \eqref{eq:S17} have different singularities.  For $K_c<1$, the SDW susceptibility is more singular than in the SC case, whereas the situation is the opposite for $K_c>1$. A schematic diagram showing the corresponding phase diagram is shown in FIG.~\ref{fig:S2}.

