\section{S5. Zero-energy domain-wall states}
\par Here, we solve for the bound-state wave function at the domain wall between the $\Delta_m>0$ and $\Delta_m<0$ regions. To be concrete, we assume $\Delta_m=\Delta_1$ for $r>0$ and $\Delta_m=-\Delta_2$ for $r<0$, with $\Delta_1,\Delta_2>0$, and solve for the localized states with energy $E$ at $r=0$. By using the ansatz $e^{-\kappa_1 r}$ for $r>0$ and $e^{\kappa_2 r}$ for $r<0$, it can be shown from Eq.~(9) of the main text that:
\begin{equation}
    \hbar v\kappa_i = \sqrt{\Delta_i^2-E^2} \text{ for }i=1,2,
\end{equation}
and the corresponding bound state, $\Phi(r) = \theta(r)\Phi_+(r)e^{-\kappa_1 r} + \theta(-r)\Phi_-(r)e^{\kappa_2 r}$, is:
\begin{equation}\label{eq:35}
\begin{split}
    \Phi_+(r) & = \begin{pmatrix} \frac{\Delta_1}{E-i\hbar v\kappa_1} & 0 & 0 & 1 \end{pmatrix}^T
    \\ \Phi_-(r) & = \begin{pmatrix} \frac{-\Delta_2}{E+i\hbar v\kappa_2} & 0 & 0 & 1 \end{pmatrix}^T.
\end{split}
\end{equation}
Here, $\theta(r)$ is the Heaviside step function and the basis $\begin{pmatrix} \mathcal{R}_{\tau}(r) & \mathcal{L}_{\tau}(r) & \mathcal{R}_{\tau}^\dagger(r) & \mathcal{L}_{\tau}^\dagger(r)\end{pmatrix}^T$ is used. Only one solution in shown in Eq.~\eqref{eq:35}. A second solution can be obtained by using time-reversal symmetry ($\Theta\Phi(r)$). The matching of  the wave functions in Eq.~\eqref{eq:35} at $r=0$ yields:
\begin{equation}\label{eq:36}
\begin{split}
     & \Delta_1(E+i\sqrt{\Delta_2^2-E^2}) = -\Delta_2(E-i\sqrt{\Delta_2^2-E^2})
     \\ & \to i[\Delta_1\sqrt{\Delta_2^2-E^2}-\Delta_2\sqrt{\Delta_1^2-E^2}] = -(\Delta_1+\Delta_2)E
     \\ & \to -2\Delta_1^2\Delta_2^2+2\Delta_1\Delta_2\sqrt{(\Delta_2^2-E^2)(\Delta_1^2-E^2)} = 2\Delta_1\Delta_2E^2
     \\ & \to \Delta_1^2\Delta_2^2 - (\Delta_1^2+\Delta_2^2)E^2 + E^4 = E^4 + 2\Delta_1\Delta_2E^2 + \Delta_1^2\Delta_2^2
     \\ & \to  0 = (\Delta_1+\Delta_2)^2E^2.
\end{split}
\end{equation}
Since $\Delta_1,\Delta_2>0$, $E=0$ according to Eq.~\eqref{eq:36}. Therefore, $\kappa_i=\Delta_i/\hbar v$ and the zero-energy bound states, $\Phi(r)$ and $\Theta\Phi(r)$, are:
\begin{equation}\label{eq:37}
\begin{split}
    \Phi(r) = & [\theta(r)e^{-\frac{\Delta_1}{\hbar v} r} + \theta(-r)e^{\frac{\Delta_2}{\hbar v} r}]\begin{pmatrix} i & 0 & 0 & 1 \end{pmatrix}^T,
    \\ \Theta\Phi(r) = & [\theta(r)e^{-\frac{\Delta_1}{\hbar v} r} + \theta(-r)e^{\frac{\Delta_2}{\hbar v} r}]\begin{pmatrix} 0 & i & 1 & 0 \end{pmatrix}^T,
\end{split}
\end{equation}
up to a normalization constant.

\par It is interesting to explore the robustness of the bound states under a wider range of conditions. Given their topological nature, we anticipate that these bound states will occur not only at sharp interfaces but also at smoother interfaces. To be concrete, we consider the following spatially dependent $\Delta_m$:
\begin{equation}
    \Delta_m(r) = 
    \begin{cases}
        \Delta\text{sgn}(r) & \text{for } |r|\geq r_0
        \\ \Delta\frac{r}{r_0} & \text{for } |r|< r_0
    \end{cases}.
\end{equation}

Here, $\Delta>0$ and $r_0>0$ are constants, with $r_0$ controlling the smoothness of the interface. Then, we use the ansatz $\Phi(r) = \theta(-r_0-r)\Phi_-(r)e^{\kappa r} +\frac{\text{sgn}(r_0-r)+\text{sgn}(r_0+r)}{2}\Phi_0(r)  + \theta(r-r_0)\Phi_+(r)e^{-\kappa r}$, where:
\begin{equation}\label{eq:35_new}
\begin{split}
    \Phi_-(r) & = \begin{pmatrix} \frac{-\Delta}{E+i\hbar v\kappa} & 0 & 0 & 1 \end{pmatrix}^T,
    \\ \Phi_0(r) & = \begin{pmatrix} \phi_1(r) & 0 & 0 & \phi_2(r) \end{pmatrix}^T,
    \\ \Phi_+(r) & = \begin{pmatrix} \frac{\Delta}{E-i\hbar v\kappa} & 0 & 0 & 1 \end{pmatrix}^T,
\end{split}
\end{equation}
where the functions $\phi_1(r),\phi_2(r)$ are to be determined. Equation~\eqref{eq:35_new} shows one of the solutions, while the second solution can be found through time-reversal symmetry ($\Theta\Phi(r)$). We can now obtain:
\begin{equation}\label{eq:36_new}
    \hbar v\kappa = \sqrt{\Delta^2-E^2} \text{ for }|r|\geq r_0,
\end{equation}
and:
\begin{equation}\label{eq:37_new}
    \begin{pmatrix} -i\hbar v\partial_r & \frac{\Delta}{r_0}r \\ \frac{\Delta}{r_0}r & i\hbar v\partial_r \end{pmatrix}\begin{pmatrix} \phi_1(r) \\ \phi_2(r) \end{pmatrix} = E\begin{pmatrix} \phi_1(r) \\ \phi_2(r) \end{pmatrix} \text{ for }|r|< r_0
\end{equation}
Application of the Gaussian ansatz, $\phi_i(r)=\alpha_ie^{-\frac{r^2}{2\xi_\text{loc}^2}}$ for $i=1,2$, to Eq.~\eqref{eq:37_new} yields:
\begin{equation}\label{eq:38_new}
\begin{split}
    \alpha_1(i\frac{\hbar v}{\xi_\text{loc}^2}r-E)+\frac{\Delta}{r_0}r\alpha_2 & = 0,
    \\ \frac{\Delta}{r_0}r\alpha_1 + \alpha_2(-i\frac{\hbar v}{\xi_\text{loc}^2}r-E) & = 0.
\end{split}
\end{equation}
According to Eq.~\eqref{eq:38_new}, $E=0$ and:
\begin{equation}\label{eq:39_new}
    \begin{pmatrix} i\frac{\hbar v}{\xi_\text{loc}^2} & \frac{\Delta}{r_0} \\ \frac{\Delta}{r_0} & -i\frac{\hbar v}{\xi_\text{loc}^2} \end{pmatrix}\begin{pmatrix} \alpha_1 \\ \alpha_2 \end{pmatrix} = 0.
\end{equation}
Matching solutions at $r=\pm r_0$ results in:
\begin{equation}
    \alpha_1 = i\alpha_2 = ie^{-\frac{\Delta}{2\hbar v}r_0},
\end{equation}
and: 
\begin{equation}\label{eq:40_new}
    \xi_\text{loc}^2 = \frac{\hbar v}{\Delta}r_0.
\end{equation}
Combining Eqs.~\eqref{eq:35_new} and \eqref{eq:40_new}, we obtain the zero-energy bound state wave function as:
\begin{equation}\label{eq:41_new}
\begin{split}
    \Phi(r) = & [\theta(-r_0-r)e^{\frac{\Delta}{\hbar v} r} + \frac{\text{sgn}(r_0-r)+\text{sgn}(r_0+r)}{2}e^{-\frac{\Delta }{2\hbar v r_0}(r_0^2+r^2)} + \theta(r-r_0)e^{-\frac{\Delta}{\hbar v} r}]\begin{pmatrix} i & 0 & 0 & 1 \end{pmatrix}^T,
    \\ \Theta\Phi(r) = & [\theta(-r_0-r)e^{\frac{\Delta}{\hbar v} r} + \frac{\text{sgn}(r_0-r)+\text{sgn}(r_0+r)}{2}e^{-\frac{\Delta }{2\hbar v r_0}(r_0^2+r^2)} + \theta(r-r_0)e^{-\frac{\Delta}{\hbar v} r}]\begin{pmatrix} 0 & i & 1 & 0 \end{pmatrix}^T,
\end{split}
\end{equation}
up to a normalization constant. Equation~\eqref{eq:41_new} indicates that the bound states possess a Gaussian profile for $|r|< r_0$ and evolve into exponential decay for $|r|\geq r_0$. For checking consistency, note that Eq.~\eqref{eq:41_new} reduces to Eq.~\eqref{eq:37} for $r_0 \to 0$. Then, the local density of states of the MKP, $\rho(r,E)$, derived from Eq.~\eqref{eq:41_new} is:
\begin{equation}
\begin{split}
    \rho(r,E) & = \text{tr}[\Phi(r)\Phi(r)^\dagger + \Phi_\Theta(r)\Phi_\Theta(r)^\dagger]\delta(E)
    \\ & =  \lim_{\Gamma\to0} \big[ \theta(-r_0-r)e^{\frac{2\Delta}{\hbar v} r} + \frac{\text{sgn}(r_0-r)+\text{sgn}(r_0+r)}{2}e^{-\frac{\Delta }{\hbar v r_0}(r_0^2+r^2)} + \theta(r-r_0)e^{-\frac{2\Delta}{\hbar v} r} \big]\frac{2\Gamma}{\pi(E^2+\Gamma^2)}, 
\end{split}
\end{equation}
up to a normalization constant, where $\Phi_\Theta(r)=\Theta\Phi(r)$ and $\Gamma$ is the spectral line broadening.

