\subsection{Rotated differential equations}
The theory of rotated differential equations provides an effective way to trace the limit cycles of one-parameter families as the parameter varies (see e.g. \cite{Han, YHL,rotated2,rotated3}).  It was initially introduced by Duff for planar vector fields \cite{rotated1}. Here we mainly recall an adaptation drawn from \cite{Han} for one-dimensional non-autonomous differential equations.

\begin{definition}[\cite{Han}]\label{definition of rotated}
    Consider a family of differential equations
    \begin{equation}\label{nah}
        \frac{dx}{dt}=S(t,x;\alpha),\indent\ t\in [0,T],\ x\in I,\ \alpha\in J,
    \end{equation}
    where $I, J$ are intervals in $\mathbb R$.
Then, we say that \eqref{nah} defines a family of rotated equations on $[0,T]\times I$ with respect to $\alpha$,
if $\frac{\partial S}{\partial \alpha}\big|_{[0,T]\times I\times J}\geq 0$ (or $\leq 0$) and does not identically vanish along any solution of \eqref{nah}.
\end{definition}
%旋转向量场的极限环随旋转参数变化的行为
\begin{proposition}[\cite{Han}]\label{property of rotated}
    Suppose that equation \eqref{nah} defines a family of rotated equations with respect to $\alpha$.
    \begin{itemize}
    \item[(i)] If $x=\varphi(t)$ is a stable (resp. unstable) limit cycle of equation \eqref{nah}$|_{\alpha=\alpha_0}$, then there exists $\delta>0$ such that for $\alpha\in J\cap(\alpha_0-\delta,\alpha_0+\delta)$, equation \eqref{nah} has a stable (resp. unstable) limit cycle $x= x(t;\alpha)$ with $x(t;\alpha_0)=\varphi(t)$.
    Furthermore, the monotonicity of $x= x(t;\alpha)$ with respect to $\alpha$ is characterized in Table \ref{Table4}.
    \item[(ii)] If $x=\varphi(t)$ is a semi-stable limit cycle of equation \eqref{nah}$|_{\alpha=\alpha_0}$, then there exists $\delta>0$ such that for $\alpha\in J\cap(\alpha_0-\delta,\alpha_0+\delta)\backslash\{\alpha_0\}$, equation \eqref{nah} has either two limit cycles located on distinct sides of $x=\varphi(t)$, or no limit cycles located near $x=\varphi(t)$.
    Furthermore, the existence and non-existence of these limit cycles as $\alpha$ varies from $\alpha_0$ are characterized in Table \ref{Table4}.
    \end{itemize}
