\section{Multiplicity and stability of limit cycles of equation \eqref{eq0}}
The aim of this section is to study the multiplicity and stability of limit cycles of equation \eqref{eq0} under the assumption of Theorem \ref{theorem0},
including both non-zero limit cycles and $x=0$.
We recall that the set of the coefficients $\{A,B\}$ from the theorem forms an ET-system with accuracy one on $[0,T)$, and therefore Proposition \ref{lemma1} is applicable.

\subsection{Maximum multiplicity of non-zero limit cycles}
For the sake of brevity, in the following we will use the notation $x=x(t)$ to represent a non-zero limit cycle of equation \eqref{eq0}, with initial value $x(0)=x_0$. Also we define $\varphi(t):=-\frac{B(t)}{A(t)}$.
Note that equation \eqref{eq0} can be rewritten as
$\frac{dx}{dt}=A(t)x^{2}\left(x-\varphi(t)\right)$ for $t\in E\setminus\{t|A(t)=0\}$.
Thus, $x=\varphi(t)$ is the horizontal isocline of the equation.

We shall begin with the following auxiliary result.
\begin{lemma}\label{lemma2}
    For equation \eqref{eq0}, assume that the set of coefficients $\{A,B\}$ forms an ET-system with accuracy one on $[0,T)$, and satisfies $\bm{(D.2)}$ with $E=[0,T)$. If $x=x(t)$ is a non-zero limit cycle of the equation, then the following statements hold.
    \begin{itemize}
        \item[(i)] $x(t)-\varphi(t)$ has at most one zero in each connected component of $\{t\in(0,T)|A(t)\not= 0\}$.
        Furthermore, all these zeros are simple  if they exist, and their total number is either one or two.
        \item[(ii)] Each zero of $x(t)-\varphi(t)$ is a local extremum point of $x(t)$, and $x(t)$ has no other stationary point in $(0,T)$.
    \end{itemize}
\end{lemma}
\begin{proof}
    Denote by $V=\{t\in[0,T)|A(t)\not= 0\}$. By assumption and inequality \eqref{remeq} in Remark \ref{remark1}, we know that $\varphi'(t)$ has definite sign on $V$. In the following we prove the case $\varphi'(t)>0$, and the opposite case follows from a similar argument.

    (i) First, for each zero $t_{0}\in V$ of $x(t_0)-\varphi(t_0)$, we have
    \begin{equation}\label{xvarph}
        \begin{split}
            \big(x(t)-\varphi(t)\big)'\big|_{t=t_{0}}%&=A(t_{0})x^{3}(t_{0})+B(t_{0})x^{2}(t_{0})-\varphi'(t_{0})\\
                &=A(t_{0})x_{0}^{2}(t_{0})\left(x(t_{0})-\varphi(t_{0})\right)-\varphi'(t_{0})\\
                &=-\varphi'(t_{0})
                <0.
        \end{split}
    \end{equation}
%That is,  $(x(t)-\varphi(t))'$ takes the same sign at all the zeros of $x(t)-\varphi(t)$ in $\{t\in[0,T)|A(t)\not= 0\}$.
Hence, $x(t)-\varphi(t)$ has at most one zero in each connected component of $V$, which must be simple if it exists.

Since $\{A,B\}$ is an ET-system with accuracy one, $A(t)$ has at most two zeros in $(0,T)$. From the above argument, the number of positive zeros of $x(t)-\varphi(t)$ in $V$ is at most three. Next, we show by contradiction that this upper bound cannot be achieved. Actually, if $x(t)-\varphi(t)$ has exactly three positive zeros in $V$, namely $t_1<t_2<t_3$, then it follows from \eqref{xvarph} that $x(t)-\varphi(t)>0$ (resp. $<0$) on $[0,t_1)$ (resp. $(t_3,T)$). We get
\begin{align}\label{lemma2-eq1}
\varphi(0)< x(0)=x(T)\leq\varphi(T).
\end{align}
Furthermore, in this case $A(t)$ has two zeros $a$ and $b$, satisfying $t_1<a<t_2<b<t_3$.
%\begin{align*}
%  \begin{split}
%        x(t)-\varphi(t)
%        \left\{
%      \begin{aligned}
%            &>0 ,& t\in[0,t_1)\cup(a,t_2)\cup(b,t_3), \\
%            &<0 ,& t\in(t_1,a)\cup(t_2,b)\cup(t_3,T). \\
%        \end{aligned}
%      \right.
%    \end{split}
%\end{align*}
Note that $\varphi(t)$ is monotonically increasing on $[0,a)$, $(a,b)$ and $(b,T)$. This together with \eqref{remeq'} in Remark \ref{remeq} implies that
 \begin{align}\label{lemma2-eq2}
   \lim_{t\rightarrow a^{+}}\varphi(t)=\lim_{t\rightarrow b^{+}}\varphi(t)=-\infty\ \text{ and }\
   \lim_{t\rightarrow b^{-}}\varphi(t)=\lim_{t\rightarrow a^{-}}\varphi(t)=+\infty.
 \end{align}
Thus, according to \eqref{lemma2-eq1} and \eqref{lemma2-eq2}, there exists $\lambda\in (\varphi(0),\varphi(T))$ such that $\varphi(t)-\lambda=-\frac{B(t)+\lambda A(t)}{A(t)}$ has a zero in each of $(0,a)$, $(a,b)$ and $(b,T)$. This contradicts the assumption that $\{A, B\}$ forms an ET-system with accuracy one on $[0,T)$.
Consequently, $x(t)-\varphi(t)$ has at most two positive zeros in $V$.

Finally, since $x(t)$ is a non-zero limit cycle, there exists $t_{0}\in (0,T)$ such that $x'(t_0)=0$, which yields
\begin{align}\label{lemma2-eq3}
  A(t_{0})x(t_{0})+B(t_{0})=\frac{x'(t_{0})}{x^{2}(t_{0})}=0.
\end{align}
 As characterization $\bm{(D.2)}$ ensures that $A(t)$ and $B(t)$ have no common zeros in $[0,T)$, we get $A(t_{0})\neq0$ and therefore $x(t_0)-\varphi(t_0)=0$. Hence, $x(t)-\varphi(t)$ has at least one zero in $\{t\in[0,T)|A(t)\not= 0\}$. This completes the proof of statement (i).



(ii)
 It is clear from \eqref{lemma2-eq3} and the following analysis that any stationary point of $x(t)$ in $(0,T)$ must be the zero of $x(t)-\varphi(t)$ in $V$. Conversely, for each positive zero $t_{0}\in V$ of $x(t)-\varphi(t)$, we have $x'(t_0)=0$ and
\begin{equation}
    \begin{split}
        x''(t_{0})&=\left[A(t)x^{2}(t)\left(x(t)-\varphi(t)\right)\right]'\big|_{t=t_0}\\
        &=A(t_{0})x^{2}(t_{0})\left(x'(t_{0})-\varphi'(t_{0})\right)\\
        &=-A(t_{0})x^{2}(t_{0})\varphi'(t_{0})\not=0.
    \end{split}
\end{equation}
Hence, $t=t_{0}$ is a local extremum point of $x(t)$.
\end{proof}

By Proposition \ref{lemma1}, Lemma \ref{lemma2}, and in addition, the uniqueness criterion mentioned in Section 1 and established in \cite[Theorem A] {AGG}, we are able to give the following characterization for the multiplicity and stability of non-zero limit cycles of equation \eqref{eq0}.
%极限环最大重数的定理
\begin{proposition}\label{multiplicity of non-zero limit cycle}
    For equation \eqref{eq0}, assume that the set of coefficients $\{A,B\}$ forms an ET-system with accuracy one on $[0,T)$.
    Then, one of the following statements holds.
    \begin{itemize}
        \item[(i)] The set $\{A,B\}$ satisfies $\bm{(D.1)}$ with $E=[0,T)$, and equation \eqref{eq0} has at most one non-zero limit cycle.
        Moreover, if this limit cycle exists, it is hyperbolic.
        \item[(ii)] The set $\{A,B\}$ satisfies $\bm{(D.2)}$ with $E=[0,T)$, and the multiplicity of each non-zero limit cycle of equation \eqref{eq0} is at most two.
        Moreover, if a non-hyperbolic limit cycle exists, then it must be lower-stable and upper-unstable (resp. lower-unstable and upper-stable) when $A'(t)B(t)-A(t)B'(t)>0$ (resp. $<0$).
    \end{itemize}
\end{proposition}
Before starting the proof of Proposition \ref{multiplicity of non-zero limit cycle},
we stress that statement (i) with $A(t)$ and $B(t)$ being linearly independent is already established in \cite[Theorem A] {AGG}.
Also, the statement is trivial when $A(t)$ and $B(t)$ is linearly dependent. In fact, if $\lambda A(t)+\mu B(t) \equiv 0$ for certain $(\lambda,\mu)\neq(0,0)$, then equation \eqref{eq0} can be written as
\begin{align*}
  \frac{dx}{dt}=B(t)\left(-\frac{\mu}{\lambda}x^{3}+x^{2}\right) \ \
  \left(\text{resp. } \frac{dx}{dt}=A(t)\left(x^{3}-\frac{\lambda}{\mu}x^{2}\right)\right)
  %&\text{when } \lambda\not=0 \ (\text{resp. } \mu\not=0).
\end{align*}
when $\lambda\not=0$ (resp. $\mu\not=0$). Therefore, the equation is integrable, which only yields either a center or a unique and hyperbolic non-zero limit cycle.


%Statement (ii) extends \cite[Theorem 3.1] {YHL} to equation \eqref{eq0} with more general coefficients, removing the restriction to periodicity.
The proof of statement (ii) is quite long, but essentially consists of four analogous parts, each dealing with an independent case. Here we provide an outline.
In the first step, we divide the argument for the non-zero limit cycle $x=x(t)$ into two cases according to Lemma \ref{lemma2}:
\begin{itemize}
  \item $x(t)-\varphi(t)$ has one zero in $(0,T)$ (i.e. $x(t)$ has one extremum point in $(0,T)$);
  \item $x(t)-\varphi(t)$ has two zeros in $(0,T)$ (i.e. $x(t)$ has two extremum points in $(0,T)$).
\end{itemize}
Then, due to the assumption that $A(t)$ has either one or two simple zero(s) in
$(0,T)$, each of the above cases is further subdivided into two subcases. All these four subcases will be verified one by one, using the formula in Proposition \ref{YHLproposition} and the approach developed from \cite[Theorem 3.1] {YHL}.
%which applies to equation \eqref{eq0} with more general coefficients, removing the restriction to periodicity.

