Now, we present the proof of Proposition \ref{multiplicity of non-zero limit cycle}.
\begin{proof}[Proof of Proposition \ref{multiplicity of non-zero limit cycle}]
First, from assumption and Proposition \ref{lemma1}, the set of coefficients $\{A,B\}$ satisfies either $\bm{(D.1)}$ or $\bm{(D.2)}$, with $E=[0,T)$. Therefore it is sufficient to verify the assertion on the limit cycles of equation \eqref{eq0} in each statement.

    (i) By the above discussion, the validity of statement (i) is already known and here we omit the proof.

    (ii) Taking change of variable $x\mapsto -x$ if necessary, we may restrict our consideration to the case $A'(t)B(t)-A(t)B'(t)>0$, i.e., the function $\varphi(t)=-\frac{B(t)}{A(t)}$ is strictly increasing in each connected component of $\{t\in[0,T)|A(t)\not=0\}$.
    %In the following, we focus on the case $A'(t)B(t)-A(t)B'(t)>0$, i.e., the function $\varphi(t)=-\frac{B(t)}{A(t)}$ is strictly increasing in each connected component of $\{t\in[0,T)|A(t)\not=0\}$.
    %The case where $A'(t)B(t)-A(t)B'(t)<0$ follows taking into account the change of variable $x\mapsto -x$.

    We also exclude the cases where $A(t)$ has either no zeros or a double zero in $(0,T)$, because both are reduced to those in statement (i).
    Let $Z(A):=\{t\in(0,T)|A(t)=0, A'(t)\not=0\}$. Then, by assumption the set $Z(A)$ contains either one or two elements.

    Now assume that $x=x(t)$ is a non-zero limit cycle of equation \eqref{eq0} with initial value $x(0)=x_0$.
    As stated in the outline, and based on Lemma \ref{lemma2}, we divide the argument into two cases:
    $x(t)-\varphi(t)$ has exactly one zero in $(0,T)\backslash Z(A)$, and $x(t)-\varphi(t)$ has two zeros in $(0,T)\backslash Z(A)$.
    \vskip0.2cm

\noindent\textbf{ \textbf{Case 1}}: $x(t)-\varphi(t)$ has exactly one zero in $(0,T)\backslash Z(A)$ (i.e., $x(t)$ has exactly one extremum point), denoted by $t=t_{1}$.
    Clearly, $x(t)$ is strictly monotonic on $[0,t_1]$ and $[t_1,T]$, respectively.
    Let $h(t)=\int_{0}^{t}A(s)x^{2}(s)\,ds$.
    From Proposition \ref{YHLproposition}, if $x=x(t)$ is non-hyperbolic, then its multiplicity and stability can be determined by
\begin{equation}\label{express}
    \begin{split}
        P''(x_{0})&=-\frac{2}{x_{0}^{2}}\int_{0}^{T}\exp h(t)\,dx(t)\\
        &=-\frac{2}{x_{0}^{2}}\left(\int_{0}^{t_{1}}\exp h(t)\,dx(t)+\int_{t_1}^{T}\exp h(t)\,dx(t)\right)\\
        &=-\frac{2}{x_{0}^{2}}\left(\int_{x_{0}}^{x_{1}}\exp h(\tau_{1}(x))\,dx+\int_{x_{1}}^{x_{0}}\exp h(\tau_{2}(x))\,dx\right)\\
        &=-\frac{2}{x_{0}^{2}}\left(\int_{x_0}^{x_1}\left(\exp h(\tau_{1}(x))-\exp h(\tau_{2}(x))\right)\,dx\right),
    \end{split}
\end{equation}
where $x_{1}=x(t_{1})$, and $\tau_{1}$ and $\tau_{2}$ represent the inverse functions of $x|_{[0,t_{1}]}$ and $x|_{[t_{1},T]}$, respectively.
For convenience, we assume that $x_{0}<x_{1}$. The case $x_{0}>x_{1}$ can be handled analogously and is explained later at the end of Case 1.
Thus, we obtain that
\begin{equation}\label{eq11-1}
    \tau_{1}'|_{(x_{0},x_{1})}>0,\ \ \tau_{2}'|_{(x_{0},x_{1})}<0,\ \ \tau_{1}(x_{1})=\tau_{2}(x_{1})=t_{1},\ \ \tau_{1}(x_{0})=0,\ \ \tau_{2}(x_{0})=T.
\end{equation}

Next, we determine the sign of $P''(x_{0})$ by \eqref{express}. This can be done once the sign of the function
\begin{equation*}
    W(s):=h(\tau_{1}(s))-h(\tau_{2}(s))=\int_{\tau_{2}(s)}^{\tau_{1}(s)}A(t)x^2(t)dt
\end{equation*}
is clarified on $(x_{0},x_{1})$.
Note that we have $W(x_{0})=W(x_{1})=0$ by Proposition \ref{YHLproposition} and \eqref{eq11-1}.
Thus, the problem is reduced to analyzing the first-order derivative $W'(s)$.
Clearly, $W'(s)$ is continuous on $(x_{0},x_{1})$, and we get
\begin{equation*}
    \begin{split}
        W'(s)&=A\left(\tau_{1}(s)\right)x^2\left(\tau_{1}(s)\right)\tau_{1}'(s)-A\left(\tau_{2}(s)\right)x^2\left(\tau_{2}(s)\right)\tau_{2}'(s)\\
        &=\frac{A\left(\tau_{1}(s)\right)}{A\left(\tau_{1}(s)\right)x\left(\tau_{1}(s)\right)+B\left((\tau_{1}(s))\right)}-\frac{A\left(\tau_{2}(s)\right)}{A\left(\tau_{2}(s)\right)x\left(\tau_{2}(s)\right)+B\left((\tau_{2}(s))\right)}.
    \end{split}
\end{equation*}
Recall that $Z(A)$ is the set of the simple zeros of $A(t)$ in $(0,T)$.
%, and $x_{*}=\min\{x(t)|t\in Z(A)\}$ and $x^{*}=\max\{x(t)|t\in Z(A)\}$.
%Observe that $a\in (t_{1},t_{2})$ and $b\in(t_{2},T)$.
For $s\in (x_{0},x_{1})\setminus\{x(t)|t\in Z(A)\}$, we obtain
\begin{equation}\label{eq011}
    W'(s)=\frac{1}{x(\tau_{1}(s))-\varphi(\tau_{1}(s))}-\frac{1}{x(\tau_{2}(s))-\varphi(\tau_{2}(s))}.
\end{equation}
Moreover, since $x\circ\tau_{1}=x\circ\tau_{2}=\text{id}$, we can write \eqref{eq011} as
\begin{equation}\label{case1W'}
    W'(s)=\frac{\varphi(\tau_{1}(s))-\varphi(\tau_{2}(s))}{\left(x(\tau_{1}(s))-\varphi(\tau_{1}(s))\right)\left(x(\tau_{2}(s))-\varphi(\tau_{2}(s))\right)}.
\end{equation}
The following discussion is subdivided into two subcases:

