%  x'(t_{1})-\varphi'(t_{1})=-\varphi'(t_{1})<0.
%\end{align*}
%We have that $(x-\varphi)\circ\tau_1>0$ and $(x-\varphi)\circ\tau_2<0$ on $(x(a),x_1)$. See Fig. \ref{figure1}(A) for an illustration. Hence, it follows from %\eqref{eq011} that $W'(s)>0$ for $s\in(x(a), x_{1})$.
