%This together with $W(x_{0})=W(x_{1})=0$ implies that $W(s)<0$ for $s\in(x_{0},x_{1})$.
We mainly focus on the case $a>t_{1}$, as illustrated in Fig. \ref{figure1}(A).
For the symmetric case $a<t_{1}$, the same argument applies and the same conclusion follows.
It is claer that $x(t)-\varphi(t)$ is continuous and does not vanish on $(0,T)\backslash\{t_{1},a\}$.
Since $x(t_{1})-\varphi(t_{1})=0$ and $x'(t_{1})-\varphi'(t_{1})=-\varphi'(t_{1})<0$,
it follows that
\begin{align*}
\begin{split}
x(t)-\varphi(t)
\left\{
      \begin{aligned}
            &>0 ,& t\in(0,t_{1}), \\
            &<0 ,& t\in(t_{1},a). \\
        \end{aligned}
      \right.
\end{split}
\end{align*}
Moreover, since $\varphi(t)$ is increasing, $\lim_{t\rightarrow a^{+}}\varphi(t)=-\infty$. We get that
$$x(t)-\varphi(t)>0,\indent t\in(a,T).$$
Thus, by the definition of $\tau_{1}$ and $\tau_{2}$, these yield
\begin{equation}\label{eq121}
   x\left(\tau_{1}\left(s\right)\right)-\varphi\left(\tau_{1}\left(s\right)\right)>0,\indent s\in (x_{0},x_{1}),
\end{equation}
and
\begin{equation}\label{eq131}
    \begin{split}
        x\left(\tau_{2}\left(s\right)\right)-\varphi\left(\tau_{2}\left(s\right)\right)\left\{
      \begin{aligned}
            &>0 ,& s\in(x_{0},x(a)), \\
            &<0 ,& s\in(x(a),x_{1}). \\
        \end{aligned}
      \right.
    \end{split}
\end{equation}
We obtain by \eqref{eq011}, \eqref{eq121} and \eqref{eq131} that $W'(s)>0$ for $s\in(x(a), x_{1})$.
On the other hand, note that the expression in \eqref{case1W'} is well-defined on $(x_{0},x(a))$.
Also, by the monotonicity of $\varphi$, $\tau_{1}$, and $\tau_{2}$, one can easily verify that $\varphi\circ\tau_{1}-\varphi\circ\tau_{2}$ is strictly increasing on $(x_{0},x(a))$.
Therefore, $W'(s)$ has at most one sign change in $(x_{0},x_1)$.
Combining $W(x_{0})=W(x_{1})=0$, we get $W(s)<0$ for $s\in(x_{0},x_{1})$.

\noindent\textbf{ \textbf{Subcase 1.2}}: $Z(A)$ is a two-element set $\{a,b\}$ with $a<b$. See Fig. \ref{figure1}(B) for an illustration.
First, since $\varphi(t)$ is increasing,  $\lim_{t\rightarrow a^{+}}\varphi(t)=-\infty$ and $\lim_{t\rightarrow b^{-}}\varphi(t)=+\infty$. Therefore the unique zero $t_1$ of $x(t)-\varphi(t)$ must lie in the interval $(a,b)$.
Similar to the argument in Subcase 1.1, $x(t)-\varphi(t)$ is continuous and does not vanish on $(0,T)/\{a,t_{1},b\}$.
Recall that $x'(t_{1})-\varphi'(t_{1})=-\varphi'(t_{1})<0$.
We obtain that
\begin{align*}
\begin{split}
x(t)-\varphi(t)
\left\{
      \begin{aligned}
            &>0 ,& t\in(a,t_{1}), \\
            &<0 ,& t\in(t_{1},b). \\
        \end{aligned}
      \right.
\end{split}
\end{align*}
Moreover, the monotonicity of $\varphi$ also implies that $\lim_{t\rightarrow a^{-}}\varphi(t)=+\infty$ and $\lim_{t\rightarrow b^{+}}\varphi(t)=-\infty$. This yields
\begin{align*}
\begin{split}
x(t)-\varphi(t)
\left\{
      \begin{aligned}
            &<0 ,& t\in(0,a), \\
            &>0 ,& t\in(b,T). \\
        \end{aligned}
      \right.
\end{split}
\end{align*}
Hence, if we set $x_{*}=\min\{x(a),x(b)\}$ and $x^{*}=\max\{x(a),x(b)\}$, then from the definition of $\tau_{1}$ and $\tau_{2}$, the following inequalities hold.
\begin{equation}\label{eq231}
    \begin{split}
        x(\tau_{1}(s))-\varphi(\tau_{1}(s))\left\{
      \begin{aligned}
            &<0 ,& s\in(x_{0},x_{*}), \\
            &>0 ,& s\in(x^{*},x_{1}), \\
        \end{aligned}
      \right.
    \end{split}
\end{equation}
and
\begin{equation}\label{eq232}
    \begin{split}
        x(\tau_{2}(s))-\varphi(\tau_{2}(s))\left\{
      \begin{aligned}
            &>0 ,& s\in(x_{0},x_{*}), \\
            &<0 ,& s\in(x^{*},x_{1}). \\
        \end{aligned}
      \right.
    \end{split}
\end{equation}

%If $x_{*}=x^{*}$, it follows from \eqref{eq011}, \eqref{eq231} and \eqref{eq232} that $W'(s)<0$ for $s\in(x_{0}, x_{*})$, and $W'(s)>0$ for $s\in(x_{*},x_{1})$.
%Combining $W(x_{0})=W(x_{1})=0$, we conclude that $W(s)<0$ in $(x_{0},x_{1})$.

Now according to \eqref{eq231} and \eqref{eq232}, we have that $W'(s)<0$ for $s\in(x_{0}, x_{*})$ and $W'(s)>0$ for $s\in(x^{*},x_{1})$.
We also emphasize that the expression in \eqref{case1W'} is well-defined on $(x_*,x^*)$. Moreover, the monotonicity of $\varphi$, $\tau_{1}$, and $\tau_{2}$ ensures that $\varphi\circ\tau_{1}-\varphi\circ\tau_{2}$ is increasing on $(x_{*},x^*)$.
As a consequence, $W'(s)$ can change sign at most once in $(x_{0},x_{1})$.
Taking into account $W(x_{0})=W(x_{1})=0$, we conclude that $W(s)<0$ for $s\in(x_{0},x_{1})$.
