\noindent\textbf{ \textbf{Case 2}}: $x(t)-\varphi(t)$ has two different zeros in $(0,T)\backslash Z(A)$ (i.e., $x(t)$ has two extremum points), denoted by $t=t_{1}$ and $t=t_{2}$ with $t_{1}<t_{2}$. In this case, $x(t)$ is strictly monotonic on $[0,t_1]$, $[t_1,t_2]$ and $[t_2,T]$, respectively.
Again using Proposition \ref{YHLproposition}, if $x=x(t)$ is non-hyperbolic, then $h(T)=0$. Furthermore, the multiplicity and stability of $x=x(t)$ are given by
\begin{equation}\label{eq22-3}
    \begin{split}
        P&''(x_{0})\\
        &=-\frac{2}{x_{0}^{2}}\int_{0}^{T}\exp h(t)dx(t)\\
        &=-\frac{2}{x_{0}^{2}}\left(\int_{0}^{t_{1}}\exp h(t)dx(t)+\int_{t_1}^{t_{2}}\exp h(t)dx(t)+\int_{t_{2}}^{T}\exp h(t)dx(t)\right)\\
        &=-\frac{2}{x_{0}^{2}}\left(\int_{x_{0}}^{x_{1}}\exp h(\tau_{1}(x))dx+\int_{x_{1}}^{x_{2}}\exp h(\tau_{2}(x))dx+\int_{x_{2}}^{x_{0}}\exp h(\tau_{3}(x))dx\right),
    \end{split}
\end{equation}
where $x_{1}=x(t_{1})$, $x_{2}=x(t_{2})$, and $\tau_{1}$, $\tau_{2}$, $\tau_{3}$ represent the inverse functions of $x|_{[0,t_{1}]}$, $x|_{[t_{1},t_{2}]}$ and $x|_{[t_{2},T]}$, respectively.

Analogously to Case 1, we mainly consider the case $x_{2}<x_{0}<x_{1}$, and give a brief explanation for the opposite case $x_{2}>x_{0}>x_{1}$ in the end.
First, to simplify the expression in \eqref{eq22-3}, we introduce a function
\begin{equation}
    \begin{split}
        \tau_{0}(x)=
        \left\{
      \begin{aligned}
            &\tau_{3}(x),&  x\in [x_{2},x_{0}),\\
            &\tau_{1}(x),&  x\in [x_{0},x_{1}].\\
        \end{aligned}
      \right.
    \end{split}
    \end{equation}
It is clear that $\tau_0(x)$ is continuous on $[x_{2},x_{0})\cup(x_{0},x_{1}]$ and satisfies
\begin{align}\label{eq22-1}
  \lim_{x\rightarrow x_0^+}\tau_0(x)=\tau_1(x_0)=0,\ \ \
    \lim_{x\rightarrow x_0^-}\tau_0(x)=\tau_3(x_0)=T.
\end{align}
Moreover, we have
\begin{align}\label{eq22-2}
    &\tau_{0}'|_{(x_{2},x_{0})\cup(x_{0},x_{1})}>0,\  \tau_{2}'|_{(x_{2},x_{1})}<0,\  \tau_{0}(x_{1})=\tau_{2}(x_{1})=t_{1},\  \tau_{0}(x_{2})=\tau_{2}(x_{2})=t_{2}.
\end{align}

By the definition of $\tau_0$, \eqref{eq22-3} is reduced to
\begin{equation}\label{express1}
    P''(x_{0})=-\frac{2}{x_{0}^{2}}\left(\int_{x_2}^{x_1}\left(\exp h(\tau_{0}(x))-\exp h(\tau_{2}(x))\right)dx\right).
\end{equation}
The next step is to determine the sign of $P''(x_{0})$. For this purpose, we consider an auxiliary function
\begin{equation*}\label{eq22-4}
    W(s):=h(\tau_{0}(s))-h(\tau_{2}(s))=\int_{\tau_{2}(s)}^{\tau_{0}(s)}A(t)x^2(t)dt.
\end{equation*}
It is easy to know from \eqref{eq22-1} that
\begin{equation*}
    \lim_{s\rightarrow x_{0}^{-}}W(s)-\lim_{s\rightarrow x_{0}^{+}}W(s)=\int_{\tau_{2}(x_{0})}^{T}A(t)x^2(t)dt-\int_{\tau_{2}(x_{0})}^{0}A(t)x^2(t)dt=h(T)=0.
\end{equation*}
Thus, $W(s)$ is continuous on $(x_{2},x_{1})$ and differentiable on $(x_{2},x_{1})/\{x_{0}\}$. In addition, note that $W(x_{2})=W(x_{1})=0$ by \eqref{eq22-2}.
The problem becomes analyzing the sign of $W'(s)$. Clearly, $W'(s)$ is continuous on $(x_{2},x_{1})/\{x_{0}\}$, and one has
\begin{equation*}
    \begin{split}
        W'(s)&=A(\tau_{0}(s))x^2(\tau_{0}(s))\tau_{0}'(s)-A(\tau_{2}(s))x^2(\tau_{2}(s))\tau_{2}'(s)\\
        &=\frac{A(\tau_{0}(s))}{A(\tau_{0}(s))x(\tau_{0}(s))+B((\tau_{0}(s)))}-\frac{A(\tau_{2}(s))}{A(\tau_{2}(s))x(\tau_{2}(s))+B((\tau_{2}(s)))}.
    \end{split}
\end{equation*}
Recall that $Z(A)$ is the set of the simple zeros of $A(t)$ in $(0,T)$.
For $s\in (x_{2},x_{1})\setminus\big(\{x_{0}\}\cup \{x(t)|t\in Z(A)\}\big)$, we obtain
\begin{equation}\label{eq11}
    W'(s)=\frac{1}{x(\tau_{0}(s))-\varphi(\tau_{0}(s))}-\frac{1}{x(\tau_{2}(s))-\varphi(\tau_{2}(s))}.
\end{equation}
Since $x\circ\tau_{0}=x\circ\tau_{0}=\text{id}$, \eqref{eq11} can be written as
\begin{equation}\label{case2W'}
    W'(s)=\frac{\varphi(\tau_{0}(s))-\varphi(\tau_{2}(s))}{\left(x(\tau_{0}(s))-\varphi(\tau_{0}(s))\right)\left(x(\tau_{2}(s))-\varphi(\tau_{2}(s))\right)}.
\end{equation}
Then, the following discussion is subdivided into two subcases:

