\noindent\textbf{ \textbf{Subcase 2.1}}: $Z(A)$ is a one-element set $\{a\}$.
See Fig. \ref{figure2}(A) for an illustration.
According to statement (i) of Lemma \ref{lemma2}, the two zeros of $x(t)-\varphi(t)$ must be located in the intervals $(0,a)$ and $(a,T)$, respectively.
Thus, $0<t_{1}<a<t_{2}<T$. We know that $x(t)-\varphi(t)$ is continuous and does not vanish on $(0,T)\setminus\{a,t_{1},t_{2}\}$.
Since $x(t_{i})-\varphi(t_{i})=0$ and $x'(t_{i})-\varphi'(t_{i})=-\varphi'(t_{1})<0$ for $i=1,2$,
it follows that
\begin{align*}
\begin{split}
x(t)-\varphi(t)
\left\{
      \begin{aligned}
            &>0 ,& t\in(0,t_{1})\cup(a,t_2), \\
            &<0 ,& t\in(t_{1},a)\cup(t_2,T). \\
        \end{aligned}
      \right.
\end{split}
\end{align*}
This together with the monotonicity of $\tau_{0}$ and $\tau_{2}$ yields
\begin{equation}\label{eq421}
    \begin{split}
        x(\tau_{0}(s))-\varphi(\tau_{0}(s))\left\{
      \begin{aligned}
            &<0 ,& s\in(x_{2},x_{0}), \\
            &>0 ,& s\in(x_{0},x_{1}). \\
        \end{aligned}
      \right.
    \end{split}
\end{equation}
and
\begin{equation}\label{eq431}
    \begin{split}
        x(\tau_{2}(s))-\varphi(\tau_{2}(s))\left\{
      \begin{aligned}
            &>0 ,& s\in(x_{2},x(a)), \\
            &<0 ,& s\in(x(a),x_{1}). \\
        \end{aligned}
      \right.
    \end{split}
\end{equation}

%If $x(a)=x_{0}$, it follows from \eqref{eq11}, \eqref{eq421}, and \eqref{eq431} that $W'(s)<0$ for $s\in(x_{2},x_{0})$ and $W'(s)>0$ for $s\in(x_{0}, x_{1})$.
%Since $W(x_{2})=W(x_{1})=0$, this implies that $W(s)<0$ for $s\in(x_{2},x_{1})$.

Now define $x_{*}=\min\{x(a),x_{0}\}$ and $x^{*}=\max\{x(a),x_{0}\}$. It follows from \eqref{eq11}, \eqref{eq421} and \eqref{eq431} that $W'(s)<0$ for $s\in(x_2,x_*)$ and $W'(s)>0$ for $s\in(x^*,x_1)$.
On the other hand, note that the expression in \eqref{case2W'} applies on $(x_{*},x^{*})$. Also, by the monotonicity of $\varphi$, $\tau_{0}$ and $\tau_{2}$,
one can verify that $\varphi\circ\tau_{0}-\varphi\circ\tau_{2}$ is increasing on $(x_{*},x^{*})$.
Therefore, $W'(s)$ has at most one sign change in $(x_{*},x^{*})$, and by its continuity on $(x_{2},x_{1})\setminus\{x_{0}\}$ the same holds in $(x_{2},x_{1})$.
Combining $W(x_{0})=W(x_{1})=0$, we obtain that $W(s)<0$ in $(x_{2},x_{1})$.

\noindent\textbf{ \textbf{Subcase 2.2}}: $Z(A)$ is a two-element set $\{a,b\}$ with $a<b$.
From statement (i) of Lemma again, the zeros $t_1$ and $t_2$ of $x(t)-\varphi(t)$ lie in two distinct intervals among $(0,a)$, $(a,b)$, and $(b,T)$.
Moreover, due to $\lim_{t\rightarrow a^{+}}\varphi(t)=-\infty$ and $\lim_{t\rightarrow b^{-}}\varphi(t)=+\infty$,
one of $t_1$ and $t_2$ must belong to the interval $(a,b)$.
For these reasons, we assume without loss of generality that $0<t_{1}<a<t_{2}<b<T$, as depicted in Fig. \ref{figure2}(B).
The same conclusion for the symmetric case $0<a<t_{1}<b<t_{2}<T$ follows in exactly the same way.

Clearly, $x(t)-\varphi(t)$ is continuous and does not vanish on $ (0,T)\setminus\{t_{1},a,t_{2},b\}$.
Since $x(t_{i})-\varphi(t_{i})=0$ and $x'(t_{i})-\varphi'(t_{i})=-\varphi'(t_{i})<0$ for $i=1,2$, we have
\begin{align*}
\begin{split}
x(t)-\varphi(t)
\left\{
      \begin{aligned}
            &>0 ,& t\in(0,t_{1})\cup(a,t_2), \\
            &<0 ,& t\in(t_{1},a)\cup(t_2,b). \\
        \end{aligned}
      \right.
\end{split}
\end{align*}
Moreover, observe that $\lim_{t\rightarrow b^{+}}\varphi(t)=-\infty$. Therefore $x(t)-\varphi(t)>0$ for $t\in(b,T)$.
Taking into account the monotonicity of $\tau_{0}$ and $\tau_{2}$, these yield
\begin{equation}\label{eq521}
    \begin{split}
        x(\tau_{0}(s))-\varphi(\tau_{0}(s))\left\{
      \begin{aligned}
            &<0 , &s\in(x_{2},x(b)), \\
            &>0 , &s\in (x(b),x_{0})\cup(x_{0},x_{1}), \\
        \end{aligned}
      \right.
    \end{split}
\end{equation}
and
\begin{equation}\label{eq531}
    \begin{split}
        x(\tau_{2}(s))-\varphi(\tau_{2}(s))\left\{
      \begin{aligned}
            &>0 ,& s\in(x_{2},x(a)), \\
            &<0 ,& s\in(x(a),x_{1}). \\
        \end{aligned}
      \right.
    \end{split}
\end{equation}

%If $x_{*}=x^{*}$, from \eqref{eq11}, \eqref{eq521}, and \eqref{eq531}, we obtain $W'(s)<0$ for $s\in(x_{2},x_{*})$ and $W'(s)>0$ for $s\in(x_{*},x_{0})\cup (x_{0}, x_{1})$. Since $W(s)$ is continuous in $(x_{2},x_{1})$ and satisfies $W(x_{2})=W(x_{1})=0$, it follows that $W(s)<0$ for $s\in(x_{2},x_{1})$.

Now let $x_{*}=\min\{x(a),x(b)\}$ and $x^{*}=\max\{x(a),x(b)\}$.
%If $x_{*}<x^{*}$ and $x_{0}\not\in(x_{*},x^{*})$,
If $x_{0}\not\in(x_{*},x^{*})$, then
from \eqref{eq11}, \eqref{eq521} and \eqref{eq531}, we get $W'(s)<0$ for $s\in(x_{2},x_{*})$ and $W'(s)>0$ for $s\in(x^{*}, x_{1})\setminus\{x_{0}\}$.
Moreover, note that $W'(s)$ is continuous on $(x_{*},x^{*})$ and the expression in \eqref{case2W'} applies. Also, the monotonicity of $\varphi$, $\tau_{0}$ and $\tau_{2}$ ensures that $\varphi\circ\tau_{0}-\varphi\circ\tau_{2}$ is increasing on $(x_{*},x^{*})$.
Therefore, $W'(s)$ can change sign at most once in $(x_{*},x^{*})$, and by its continuity on $(x_{2},x_{1})\setminus\{x_{0}\}$ the same is true in $(x_{2},x_{1})$.
Combining $W(x_{2})=W(x_{1})=0$, we obtain that $W(s)<0$ in $(x_{2},x_{1})$.

If $x_{0}\in(x_{*},x^{*})$, then \eqref{eq11}, \eqref{eq521} and \eqref{eq531} indicate that $W'(s)<0$ for $s\in(x_{2},x_{*})$ and $W'(s)>0$ for $s\in(x^{*}, x_{1})$.
It remains to consider the sign of $W'(s)$ on $(x_*,x^*)\setminus\{x_0\}$. To this end, we first know by \eqref{eq521} and \eqref{eq531} that the denominator of the expression in \eqref{case2W'} is always positive on $(x_{*}, x_{0})\cup(x_{0},x^{*})$. Next, we show that $\varphi\circ\tau_{0}-\varphi\circ\tau_{2}$ is increasing on the whole $(x_{*},x^{*})$. In fact, due to the monotonicity of $\varphi$, $\tau_{0}$ and $\tau_{2}$, the function $\varphi\circ\tau_{0}-\varphi\circ\tau_{2}$ is increasing on both $(x_{*}, x_{0})$ and $[x_{0},x^{*})$. Observe that
\begin{equation*}
    \lim_{s\rightarrow x_{0}^{-}}\varphi \left(\tau_{0}\left(s\right)\right)-\varphi\left(\tau_{2}\left(s\right)\right)=\lim_{s\rightarrow x_{0}^{-}}\varphi \left(\tau_{3}\left(s\right)\right)-\varphi\left(\tau_{2}\left(s\right)\right)=\varphi(T)-\varphi\left(\tau_{2}\left(x_{0}\right)\right),
\end{equation*}
and
\begin{equation*}
    \varphi \left(\tau_{0}\left(x_0\right)\right)-\varphi\left(\tau_{2}\left(x_0\right)\right)=\varphi(0)-\varphi\left(\tau_{2}\left(x_{0}\right)\right).
\end{equation*}
Thus, it is sufficient to prove $\varphi(0)\geq \varphi(T)$. Here we assume for a contradiction that $\varphi(0)< \varphi(T)$.
Then, again using
\begin{align*}
  \lim_{t\rightarrow a^{+}}\varphi(t)=\lim_{t\rightarrow b^{+}}\varphi(t)=-\infty,\indent
  \lim_{t\rightarrow a^{-}}\varphi(t)=\lim_{t\rightarrow b^{-}}\varphi(t)=+\infty,
\end{align*}
there exists $\lambda\in (\varphi(0),\varphi(T))$ such that $\varphi(t)-\lambda=-\frac{\lambda A(t)+B(t)}{A(t)}$ has three zeros located in $(0,a)$, $(a,b)$, and $(b,T)$, respectively.
This contradicts the assumption that $\{A,B\}$ is an ET-system with accuracy one on $[0,T)$.
Hence, $\varphi(0)\geq \varphi(T)$ holds and therefore $\varphi\circ\tau_{0}-\varphi\circ\tau_{2}$ is increasing on $(x_{*},x^{*})$. As a consequence, $W'(s)$ can change sign at most once in $(x_*,x^*)\setminus\{x_0\}$, and by its continuity on $(x_2,x_1)\setminus\{x_0\}$ the same is true in $(x_2,x_1)$. Taking into account $W(x_{0})=W(x_{1})=0$, we get that $W(s)<0$ in $(x_{2},x_{1})$ .
\vskip0.2cm

According to the analyses in Subcase 2.1 and Subcase 2.2, we finally get by \eqref{express} that $P''(x_{0})>0$.
 We emphasize that in the omitted case $x_{2}>x_{0}>x_{1}$, a similar argument yields $W(s)>0$ for $s\in(x_{1},x_{0})$. Then, by \eqref{express} and noting the orientation of the integral (from $x_0$ to $x_1$), $P''(x_0)>0$ remains valid.
In summary, the conclusion of the statement holds for Case 2.

The proof is finished.
\end{proof}

\subsection{The Lyapunov constants of solution $x=0$}
%Next we study the stability of the orbit $x=0$ of the equation \eqref{eq0}.
This subsection studies the local dynamics of the closed solution $x=0$ of equation \eqref{eq0}. For this purpose, let $x=x(t,x_0)$ be the solution of equation \eqref{eq0} with initial condition $x(0,x_0)=x_0$. It is clear that $x=x(t,x_0)$ is well-defined on $[0,T]$ for all $x_0$ in a small neighbourhood of zero. Moreover, due to the smoothness of the equation in variable $x$, $x(t,x_0)$ can be expanded into a power series as:
\begin{equation*}
    x(t,x_{0})=x_{0}+\sum_{i=2}^{+\infty}a_{i}(t)x_{0}^{i},\indent t\in[0,1].
\end{equation*}
Then, the displacement function $d(x_0)$ of the equation near $x_0=0$ is given by
\begin{equation*}
    d(x_{0}):=x(T,x_{0})-x_{0}=\sum_{i=2}^{+\infty}V_{i}x_{0}^{i},\indent V_{i}=a_{i}(T).
\end{equation*}
For each $i\in\mathbb{N}_{\geq 2}$, $V_i$ is called the \textit{$i$-th Lyapunov constant} of the closed solution $x=0$ (see for instance \cite{YHL,rotated2,rotated3,AGG}).
We stress that when $V_i$ is the first non-zero Lyapunov constant, the solution $x=0$ forms a limit cycle with multiplicity $i$, and its stability is determined by the sign of $V_i$.

For equation \eqref{eq0}, a straightforward calculation or the direct application of the result in \cite{AL1987} yields
\begin{equation}\label{eq3.2}
    \begin{split}
        V_{2}&=\int_{0}^{T}B(t)dt,\\
        V_{3}&=\int_{0}^{T}A(t)dt, \text{ if }V_{2}=0,\\
        V_{4}&=\int_{0}^{T}A(t)\int_{0}^{t}B(s)dsdt, \text{ if } V_{2}=V_{3}=0.
    \end{split}
\end{equation}
Then, we have the following result.

\begin{proposition}\label{Lyapunov constants}
    Assume that the set of coefficients $\{A,B\}$ of equation \eqref{eq0} forms an ET-system with accuracy one on the interval $[0,T)$.
    Then, one of the following statements holds.
    \begin{itemize}
        \item[(i)] The set $\{A,B\}$ satisfies $\bm{(D.1)}$ with $E=[0,T)$, and $x=0$ is a center (resp. the unique limit cycle) if the Lyapunov constants $V_{2}=V_{3}=0$ (resp. $V_2=0$ and $V_3\neq0$).
        \item[(ii)] The set $\{A,B\}$ satisfies $\bm{(D.2)}$ with $E=[0,T)$, and $x=0$ is a limit cycle with multiplicity at most four.
        Moreover, if the Lyapunov constants $V_{2}=V_{3}=0$ and $A'(t)B(t)-A(t)B'(t)>0$ (resp. $<0$), then $V_{4} > 0$ (resp. $< 0$).
    \end{itemize}
\end{proposition}
\begin{proof}
    According to the quasi-dichotomy in Proposition \ref{lemma1}, it is sufficient to prove the assertion for $x=0$ in each statement.

    (i) We begin by showing that $x=0$ is a center if $V_{2}=V_{3}=0$.
        In this case, we have $\int_{0}^{T}A(t)\,dt=\int_{0}^{T}B(t)\,dt=0$ from \eqref{eq3.2}.
        Then, for $(\lambda,\mu)\neq(0,0)$ given in $\bm{(D.1)}$, the function $\lambda A(t)+\mu B(t)$ simultaneously does not change sign on $[0,T)$ and satisfies
        \begin{align*}
            \int_{0}^{T}\big(\lambda A(t)+\mu B(t)\big)\,dt=0.
        \end{align*}
        This implies that $\lambda A(t)+\mu B(t)\equiv 0$. Therefore, equation \eqref{eq0} becomes either $\frac{dx}{dt}=B(t)\left(-\frac{\mu}{\lambda}x^{3}+x^{2}\right)$ when $\lambda\not=0$, or $\frac{dx}{dt}=A(t)\left(x^{3}-\frac{\lambda}{\mu}x^{2}\right)$ when $\mu\not=0$.
        In both cases all the solutions of the equation are closed.
        Consequently, $x=0$ is a center if $V_{2}=V_{3}=0$.

        To prove that $x=0$ is the unique limit cycle when $V_2=0$ and $V_3\neq0$, we divide the argument into the following two cases.

    \noindent{ Case 1}: $\lambda=0$. We have $B(t)\geq 0$ (or $\leq 0$).
    Since $V_{2}=0$, it follows from \eqref{eq3.2} that $B(t)\equiv 0$.
    Thus, equation \eqref{eq0} is reduced to $\dot{x}=A(t)x^{3}$, which clearly has no limit cycles in the region $x\not=0$.

    \noindent{ Case 2}: $\lambda\not=0$.
    Equation \eqref{eq0} can be written as
    \begin{equation}\label{890}
        \frac{dx}{dt}=-\frac{\mu}{\lambda}B(t)x^{2}(x-\lambda)+\frac{1}{\lambda}\left(\lambda A(t)+\mu B(t)\right)x^{3},
    \end{equation}
    where $\frac{1}{\lambda}\left(\lambda A(t)+\mu B(t)\right)x^{3}\geq0$ (or $\leq0$) on both regions $x>0$ and $x<0$.
    %By \eqref{eq3.2} and integrating $\lambda A(t)+\mu B(t)$ over $[0,T]$, we have
    %\begin{equation*}
    %    \int_{0}^{T}\big(\lambda A(t)+\mu B(t)\big)\,dt=\lambda V_{3}+\mu V_{2}=\lambda V_{3} \neq 0.
    %\end{equation*}
    %Thus, $\lambda A(t)+\mu B(t)$ does not vanish on $[0,T]$.
    Note that $\int_{0}^{T} B(t)\,dt=V_2=0$. Thus, $x=0$ is a center of the equation
\begin{equation}\label{098}
    \frac{dx}{dt}=-\frac{\mu}{\lambda}B(t)x^{2}(x-\lambda).
\end{equation}
Comparing equation \eqref{890} with \eqref{098}, we know that equation \eqref{eq0} has no limit cycles in the region $x\not=0$. Statement (i) is verified.



    (ii) We only need to determine the Lyapunov constant $V_4$ of $x=0$ in the case $V_2=V_3=0$. Furthermore, taking the change of variable $x\rightarrow -x$ if necessary, we may suppose without loss of generality that $A'(t)B(t)-A(t)B'(t)>0$ on $[0,T)$. In the following we show that $V_4>0$.

    To this end, denote by $\mathcal{V}_{2}(t)=\int_{0}^{t}B(s)\,ds$ and $\mathcal{V}_{3}(t)=\int_{0}^{t}A(s)\,ds$. We introduce two auxiliary functions
    \begin{align}\label{def1}
      f(t)=\mu_{1}A(t)-\mu_{2}B(t),\indent G(t)=\lambda_{1}\mathcal{V}_{3}(t)-\lambda_{2}\mathcal{V}_{2}(t),
    \end{align}
    where $\mu_1, \mu_2, \lambda_1, \lambda_2\in\mathbb R$ are parameters to be chosen later. It is easy to get by \eqref{eq3.2} that
    \begin{equation}\label{ert'}
        \mathcal{V}_{2}(0)=\mathcal{V}_{2}(T)=V_{2}=0,\indent \mathcal{V}_{3}(0)=\mathcal{V}_{3}(T)=V_{3}=0,
    \end{equation}
    and
    \begin{equation*}\label{ert}
        V_{4}=\int_{0}^{T}\mathcal{V}_{2}(t)\,d\mathcal{V}_{3}(t)=-\int_{0}^{T}\mathcal{V}_{3}(t)\,d\mathcal{V}_{2}(t)=-\int_{0}^{T}B(t)\int_{0}^{t}A(s)\,dsdt.
    \end{equation*}
    Then, one has
    \begin{equation*}
    \begin{split}
        \int_{0}^{T}f(t)G(t)dt=&\int_{0}^{T}\left(\mu_{1}A(t)-\mu_{2}B(t)\right)\left(\lambda_{1}V_{3}(t)-\lambda_{2}V_{2}(t)\right)dt\\
        =&\int_{0}^{T}\left(\mu_{1}A(t)-\mu_{2}B(t)\right)\int_{0}^{t}\left(\lambda_{1}A(s)-\lambda_{2}B(s)\right)dsdt\\
        =&\frac{1}{2}\mu_{1}\lambda_{1} V_{3}^{2}+\frac{1}{2}\mu_{2}\lambda_{2} V_{2}^{2}-\mu_{1}\lambda_{2}V_{4}+\mu_{2}\lambda_{1}V_{4}\\
        =&(\mu_{2}\lambda_{1}-\mu_{1}\lambda_{2})V_{4}.
    \end{split}
\end{equation*}
Therefore, our argument is reduced to showing that $(\mu_{2}\lambda_{1}-\mu_{1}\lambda_{2})\int_{0}^{T}f(t)G(t)dt>0$ holds for an appropriate choice of $\mu_1, \mu_2, \lambda_1, \lambda_2$.


    Now let us begin by taking $\mu_{1}=B(0)$ and $\mu_{2}=A(0)$. We have
    \begin{align}\label{eq3.23}
      f(0)=0,\indent f'(0)=A'(0)B(0)-A(0)B'(0)> 0.
    \end{align}
    Then, $f$ is a non-trivial linear combination of $A$ and $B$. Moreover, since $\int_{0}^{T}f(t)\,dt=\mu_{1}V_{3}-\mu_{2}V_{2}=0$, there exists $t_{0}\in(0,T)$ such that $f(t_{0})=0$. According to the assumption that $\{A,B\}$ forms an ET-system with accuracy one on $[0,T)$, $f(t)$ has exactly two zeros $t=0$ and $t=t_{0}$ in the interval, which are both simple.
    Taking into account \eqref{eq3.23} again, we get
    \begin{equation}\label{eq3.21}
    \begin{split}
       f(t)\left\{
      \begin{aligned}
            &>0 , &t\in(0,t_{0}), \\
            &<0 , &t\in (t_{0},T). \\
        \end{aligned}
      \right.
    \end{split}
\end{equation}

    Next, set $\lambda_{1}=\mathcal{V}_{2}(t_{0})$ and $\lambda_{2}=\mathcal{V}_{3}(t_{0})$.
    It follows from \eqref{def1} and \eqref{ert'} that $G(0)=G(t_{0})=G(T)=0$. Since $G'(t)=\lambda_{1}A(t)-\lambda_{2}B(t)$, it has at most two zeros in $[0,T)$, analogous to $f(t)$. Thus, $t=0$, $t=t_{0}$ and $t=T$ are the only three zeros of $G$, and they are all simple. Observe that
    \begin{equation*}
    G'(0)=\lambda_1A(0)-\lambda_2B(0)
    =\int_{0}^{t_{0}}B(s)A(0)-A(s)B(0)\,ds=-\int_{0}^{t_{0}}f(s)\,ds<0.
    \end{equation*}
    This yields
    \begin{equation}\label{eq3.22}
    \begin{split}
       G(t)\left\{
      \begin{aligned}
            &<0 , &t\in(0,t_{0}), \\
            &>0 , &t\in (t_{0},T). \\
        \end{aligned}
      \right.
    \end{split}
    \end{equation}

    Finally, utilizing \eqref{eq3.21} and \eqref{eq3.22}, we get that $\int_{0}^{T}f(t)G(t)dt<0$. Moreover, the inequality \eqref{eq3.21} also implies that
    \begin{equation*}
        \mu_{2}\lambda_{1}-\mu_{1}\lambda_{2}=-\int_{0}^{t_{0}}\mu_{1}A(s)-\mu_{2}B(s)ds=-\int_{0}^{t_{0}}f(s)\,ds<0.
    \end{equation*}
    Consequently, $(\mu_{2}\lambda_{1}-\mu_{1}\lambda_{2})\int_{0}^{T}f(t)G(t)dt>0$ holds, which immediately leads to $V_4>0$. Statement (ii) follows.

    The proof is finished.
\end{proof}

\section{Maximum number of limit cycles of equation \eqref{eq0}}
The goal of this section is to prove Theorem \ref{theorem0}, utilizing Proposition \ref{multiplicity of non-zero limit cycle}, Proposition \ref{Lyapunov constants} and the theory of rotated equations. We again emphasize that the set of coefficients $\{A,B\}$ of equation \eqref{eq0} in the theorem forms an ET-system with accuracy one on $[0,T)$. Then according to statement (i) of Proposition \ref{multiplicity of non-zero limit cycle}, it is sufficient to consider the case where $\{A,B\}$ satisfies $\bm{(D.2)}$ but not $\bm{(D.1)}$, with $E=[0,T)$. Furthermore, by performing the change of variable $x\rightarrow -x$ if necessary, we may assume without loss of generality that $A'(t)B(t)-A(t)B'(t)>0$ on $[0,T)$. In summary, we only need to focus on equation \eqref{eq0} under the assumption of Theorem \ref{theorem0} with the following additional hypothesis:
\begin{itemize}
    \item[$\bm{(H)}$] $A'(t)B(t)-A(t)B'(t)>0$ on $[0,T)$, and $\bm{(D.1)}$ with $E=[0,T)$ is not satisfied.
\end{itemize}

%As mentioned in Section 2, for equation \eqref{eq0} with $A,B\in\text{span}(\mathcal{F})$, Proposition \ref{lemma1} is applicable.
%Consequently, both Proposition \ref{multiplicity of non-zero limit cycle} and Proposition \ref{Lyapunov constants} hold.
%According to statement (i) of Proposition \ref{multiplicity of non-zero limit cycle}, if $\bm{(D.1)}$ holds, then equation \eqref{eq0} with $A(t)$, %$B(t)\in\text{span}(\mathcal{F})$ has at most one non-zero limit cycle.
%Thus, we only need to analyze the case where $\bm{(D.1)}$ does not hold, while $\bm{(D.2)}$ does.
%In this case, we can assume without loss of generality that $A'(t)B(t)-A(t)B'(t)>0$ in $[0,T)$.
%For the opposite case, we perform the change of variable $x\rightarrow -x$, reducing it to the case we are concerned with.
%In summary, we only need to focus on equation \eqref{eq0} under the following hypothesis:
%\begin{itemize}
%    \item[$\bm{(H)}$] $A,B\in\text{span}(\mathcal{F})$, $A'(t)B(t)-A(t)B'(t)>0$ in $[0,T)$, and statement $\bm{(D.1)}$ is invalid.
%\end{itemize}

In what follows we divide the argument into several steps.
It is clear that the coefficients $A,B$ of equation \eqref{eq0} in Theorem \ref{theorem0} can be written as
\begin{align}\label{A-B}
  A=\lambda_{0}f_{0}+\lambda_{1}f_{1}+\lambda_{2}f_{2},\indent
  B=\mu_{0}f_{0}+\mu_{1}f_{1}+\mu_{2}f_{2},
\end{align}
where $f_0,f_1,f_2$ are defined in the theorem and $\lambda_{0},\lambda_{1},\lambda_{2},\mu_{0},\mu_{1},\mu_{2}\in\mathbb R$. Thus, equation \eqref{eq0} becomes
\begin{equation}\label{equation1}
    \begin{split}
        \frac{dx}{dt}%=A(t)x^3+B(t)x^2
        =(\lambda_{0}f_{0}+\lambda_{1}f_{1}+\lambda_{2}f_{2})x^{3}+(\mu_{0}f_{0}+\mu_{1}f_{1}+\mu_{2}f_{2})x^{2}.
    \end{split}
\end{equation}
Let $\bm{\eta}=(\lambda_{0},\lambda_{1},\lambda_{2},\mu_{0},\mu_{1},\mu_{2})\in\mathbb{R}^{6}$ be the parameter vector associated with the equation.
Let $\mathcal{L}_{H}$ and $\mathcal{L}_{1}$ be the sets of $\bm\eta$ given by
\begin{align*}
\begin{split}
    &\mathcal{L}_{H}=\left\{\left.\bm{\eta}\in\mathbb{R}^{6}\right|\{A,B\} \text{ satisfies $\bm{(H)}$}\right\},\\
    &\mathcal{L}_{1}=\left\{\left.\bm{\eta}\in\mathbb{R}^{6}\right|\{ A,B\} \text{ satisfies } \bm{(D.1)} \text{ with } E=[0,T)\right\}.
\end{split}
\end{align*}
In the first step, we present the following characterization for $\mathcal L_H$, which will be useful later when applying the theory of rotated equations.



\begin{lemma}\label{LHopen}
    $\mathcal{L}_{H}$ is an open set in $\mathbb{R}^{6}$. Moreover, its boundary $\partial\mathcal{L}_{H}\subseteq\mathcal{L}_{1}$.
\end{lemma}
\begin{proof}
    Let $A$ and $B$ be given in \eqref{A-B}. To verify the assertion, we additionally introduce two sets
\begin{align*}
    &\mathcal{L}_{2}^{+}=\left\{\bm{\eta}\in\mathbb{R}^{6}\left|\ A'(t)B(t)-A(t)B'(t)>0 \text{ on } [0,T)\right.\right\},\\   &\mathcal{L}_{2}^{-}=\left\{\bm{\eta}\in\mathbb{R}^{6}\left|\ A'(t)B(t)-A(t)B'(t)<0 \text{ on } [0,T)\right.\right\}.
\end{align*}
Clearly, $\mathcal{L}_{2}^{+}\cup\mathcal{L}_{2}^{-}=\left\{\left.\bm{\eta}\in\mathbb{R}^{6}\right|\{A,B\} \text{ satisfies } \bm{(D.2)}\text{ with } E=[0,T)\right\}$. It follows from Proposition \ref{lemma1} that $\mathbb{R}^{6}=\mathcal{L}_{1}\cup \mathcal{L}_{2}^{+}\cup\mathcal{L}_{2}^{-}$. Also, by definition we have $\mathcal{L}_{H}=\mathcal{L}_{1}^{c}\cap\mathcal{L}_{2}^{+}$, where the superscript
``$c$'' denotes the complement of a set.

We first claim that $\mathcal{L}_{1}$ is closed in $\mathbb{R}^{6}$. Denote by $A_{\bm\eta}(t)$ and $B_{\bm\eta}(t)$ the functions $A$ and $B$ associated with the parameter vector $\bm\eta$, respectively.
It is easy to see that
$$\mathcal{L}_{1}=\left\{\bm{\eta}\in\mathbb{R}^{6}\left|\ \exists (\lambda,\mu)\in \mathbb{S}^{1} \text{ s.t. } \lambda A_{\bm\eta}(t)+\mu B_{\bm\eta}(t)\geq 0 \text{ on } [0,T)\right.\right\}.$$
Suppose that $\bm{\eta}_{0}$ is a limit point of $\mathcal{L}_{1}$. Then there exists a sequence $\{\bm{\eta}_{n}\}_{n=1}^{+\infty}\subseteq \mathcal{L}_{1}$ such that $\bm{\eta}_{n}\rightarrow \bm{\eta}_{0}$ as $n\rightarrow +\infty$.
    For any $t\in[0,T)$, we have $A_{\bm{\eta}_{n}}(t)\rightarrow A_{\bm{\eta}_{0}}(t)$ and $B_{\bm{\eta}_{n}}(t)\rightarrow B_{\bm{\eta}_{0}}(t)$ as $n\rightarrow +\infty$.
    In addition, note that each $\bm{\eta}_{n}$ admits a corresponding pair of parameters $(\lambda_{n}, \mu_{n})\in \mathbb{S}^{1}$, satisfying $\lambda_{n}A_{\bm{\eta}_{n}}(t)+\mu_{n}B_{\bm{\eta}_{n}}(t)\geq 0$ on $[0,T)$.
    Due to the compactness of $\mathbb{S}^{1}$, the sequence $\{(\lambda_{n}, \mu_{n})\}_{n=1}^{+\infty}$ has a convergent subsequence $\{(\lambda_{n_{i}}, \mu_{n_{i}})\}_{i=1}^{+\infty}$ that converges to a point $(\lambda_{0},\mu_{0})\in\mathbb{S}^{1}$.
    Thus, we have $\lambda_{n_{i}}A_{\bm{\eta}_{n_{i}}}(t)+\mu_{n_{i}}B_{\bm{\eta}_{n_{i}}}(t)\rightarrow \lambda_{0}A_{\bm{\eta}_{0}}(t)+\mu_{0}B_{\bm{\eta}_{0}}(t)$ as $i\rightarrow +\infty$.
    This implies that
$\lambda_{0}A_{\bm{\eta}_{0}}(t)+\mu_{0}B_{\bm{\eta}_{0}}(t)\geq 0$ on $[0,T)$, and therefore $\bm{\eta}_{0}\in \mathcal{L}_{1}$.
    Hence, $\mathcal{L}_{1}$ is an closed set in $\mathbb{R}^{6}$.

    Next, we show that $\partial\mathcal{L}_{H}\subseteq \mathcal{L}_{1}$.
    Observe that $\partial\mathcal{L}_{H}=\big(\partial\mathcal{L}_{H}\cap \overline{\mathcal{L}_{2}^{-}}\big)\cup \big(\partial\mathcal{L}_{H}\cap (\overline{\mathcal{L}_{2}^{-}})^{c}\big)$,
    where the notation `` $\overline{\cdot}$ '' represents the closure of a set.
    Thus, on the one hand,
    \begin{equation*}
        \partial\mathcal{L}_{H}\cap \overline{\mathcal{L}_{2}^{-}}\subseteq \overline{\mathcal{L}_{H}}\cap \overline{\mathcal{L}_{2}^{-}}\subseteq \overline{\mathcal{L}_{2}^{+}}\cap \overline{\mathcal{L}_{2}^{-}}
        =\left\{\bm{\eta}\left|A_{\bm{\eta}}'(t)B_{\bm{\eta}}(t)-A_{\bm{\eta}}(t)B_{\bm{\eta}}'(t)\equiv 0\right.\right\}\subseteq \mathcal{L}_{1}.
    \end{equation*}
On the other hand,
suppose that $\bm{\eta}\in \partial\mathcal{L}_{H}\cap (\overline{\mathcal{L}_{2}^{-}})^{c}$. Then there exists $\varepsilon_{0}>0$ such that for any $\varepsilon\in(0,\varepsilon_{0})$, the $\varepsilon$-neighborhood of $\bm\eta$ satisfies
%$U_{\varepsilon}(\bm{\eta})\cap\mathcal{L}_{H}\not= \emptyset$ and
$U_{\varepsilon}(\bm{\eta})\subset (\overline{\mathcal{L}_{2}^{-}})^c$.
Recall that $\mathbb{R}^{6}=\mathcal{L}_{1}\cup \mathcal{L}_{2}^{+}\cup\mathcal{L}_{2}^{-}$ and $\mathcal{L}_{H}=\mathcal{L}_{1}^{c}\cap\mathcal{L}_{2}^{+}$.
One has
$$U_{\varepsilon}(\bm{\eta})
\subseteq\mathcal{L}_{1}\cup\mathcal{L}_{2}^{+}=\mathcal{L}_{1}\cup\mathcal{L}_{H}.$$
%and therefore $$\big(U_{\varepsilon}(\bm{\eta})\cap\mathcal L_1\big)\cup\big(U_{\varepsilon}(\bm{\eta})\cap\mathcal L_H\big)
%=U_{\varepsilon}(\bm{\eta})\cap\big(\mathcal{L}_{1}\cup\mathcal{L}_{H}\big)
%=U_{\varepsilon}(\bm{\eta})\cap\big(\mathcal{L}_{1}\cup\mathcal{L}_{2}^{+}\big)=U_{\varepsilon}(\bm{\eta}),$$
%where the first equality follows from  $\mathcal{L}_{H}=\mathcal{L}_{1}^{c}\cap\mathcal{L}_{2}^{+}$.
Since $\bm{\eta}$ is a boundary point of $\mathcal{L}_{H}$ but not an interior point,
$U_{\varepsilon}(\bm{\eta})\cap\mathcal{L}_{1}\not= \emptyset$ always holds.
By the arbitrariness of $\varepsilon$ and the closedness of $\mathcal{L}_{1}$, we get $\bm{\eta}\in \mathcal{L}_{1}$, which yields that $\partial\mathcal{L}_{H}\cap (\overline{\mathcal{L}_{2}^{-}})^{c}\subseteq\mathcal L_1$.
Consequently, $\partial\mathcal{L}_{H}\subseteq \mathcal{L}_{1}$.

%Finally, to verify that $\mathcal{L}_{H}$ is open, it is sufficient to note that  $$\partial\mathcal{L}_{H}\cap\mathcal{L}_{H}\subseteq\mathcal{L}_{1}\cap\big(\mathcal{L}_{1}^{c}\cap\mathcal{L}_{2}^{+}\big)=\emptyset.$$ The proof is finished.
The above argument also indicates that
$$\partial\mathcal{L}_{H}\cap\mathcal{L}_{H}\subseteq\mathcal{L}_{1}\cap\big(\mathcal{L}_{1}^{c}\cap\mathcal{L}_{2}^{+}\big)=\emptyset.$$
Thus, $\mathcal{L}_{H}$ is an open set and the proof is finished.
\end{proof}

