We are ready to prove Theorem \ref{app1}, Theorem \ref{main theorem1} and Theorem \ref{main theorem}.
\begin{proof}[Proof of Theorem \ref{app1}]
Applying Theorem \ref{theorem0}, the assertion is true once $\{1,\sin t,\cos t\}$ forms an ET-system on $[0,2\pi)$.
This is clear because for any $(\lambda_{1},\lambda_{2},\lambda_{3})\neq(0,0,0)$,
\begin{align*}
\lambda_{1}+\lambda_{2}\sin t+\lambda_{3}\cos t=
  \left\{
      \begin{aligned}
            &\lambda_{1}+\sqrt{\lambda^{2}_{2}+\lambda^{2}_{3}}\sin \left(t+\arctan\frac{\lambda_{3}}{\lambda_{2}}\right) ,& \text{if }\lambda_2\neq0, \\
            &\lambda_{1}+\lambda_{3}\cos t ,& \text{if } \lambda_2=0, \\
        \end{aligned}
      \right.
\end{align*}
which has at most two zeros (counted with multiplicity) on $[0,2\pi)$. In addition, this upper bound is sharp when $|\lambda_{1}|\leq \sqrt{\lambda^{2}_{2}+\lambda^{2}_{3}}$.
\end{proof}

\begin{proof}[Proof of Theorem \ref{main theorem1}]
    By Theorem \ref{theorem0}, it is sufficient to show that $\{1,t,t^{2}\}$ forms an ET-system on $[0,1)$. This is trivial and also follows from Lemma \ref{KS1} and the equality $2W_{1}(t)=2W_{1,t}(t)=W_{1,t,t^{2}}(t)=2$.
\end{proof}

    \begin{proof}[Proof of Theorem \ref{main theorem}]
    Due to the time-rescaling $t\mapsto t^{\frac{1}{m_0+1}}$ and the arbitrariness of the parameters $a_{i}$ and $b_{i}$ with $i=0,1,2$,
    the assertion for equation \eqref{main equation1} can be verified by studying the following equation
    \begin{equation*}\label{40}
        \frac{dx}{dt}=\left(a_{0}+a_{1}t^{\alpha}+a_{2}t^{\beta}\right)x^{3}+\left(b_{0}+b_{1}t^{\alpha}+b_{2}t^{\beta}\right)x^{2},\indent t\in [0,1],
    \end{equation*}
    where $\alpha=\frac{m_{1}-m_{0}}{m_{0}+1}>0$ and $\beta=\frac{m_{2}-m_{0}}{m_{0}+1}>0$.
    Furthermore, taking the change of variable $t\rightarrow 1-t$ and absorbing the signs into the parameters, the above equation becomes
        \begin{equation}\label{41}
        \begin{split}
        \frac{dx}{dt}=&\left(a_{0}+a_{1}(1-t)^{\alpha}+a_{2}(1-t)^{\beta}\right)x^{3}\\&+
        \left(b_{0}+b_{1}(1-t)^{\alpha}+b_{2}(1-t)^{\beta}\right)x^{2},\indent t\in [0,1].
        \end{split}
    \end{equation}

    It is clear that the coefficients of equation \eqref{41} are generated by $1$, $(1-t)^{\alpha}$ and $(1-t)^{\beta}$.
In addition, for $t\in[0,1)$ a direct calculation yields
    \begin{align*}
        \begin{split}
            &W_{1}(t)=1,\\
            &W_{1,(1-t)^{\alpha}}(t)=\alpha (1-t)^{\alpha}>0,\\
            &W_{1,(1-t)^{\alpha},(1-t)^{\beta}}(t)=\alpha\beta(1-t)^{\alpha+\beta-3}>0.
        \end{split}
    \end{align*}
    Thus, we know by Lemma \ref{KS1} that the set $\{1,(1-t)^{\alpha},(1-t)^{\beta}\}$ forms an ECT-system on $[0,1)$, and therefore is naturally an ET-system on $[0,1)$.
    According to Theorem \ref{theorem0}, equation \eqref{41} has at most three limit cycles (including $x=0$), and this upper bound is sharp. The assertion follows.
\end{proof}


