\section{Newton-Hensel lifting}
\label{sec:lifting}

Lifting techniques are classical methods that can be found, for example, in~\cite{heintz2000deformation, giusti2001grobner, schost2003computing} (see also the references therein). 

In this section, the notations $\x$ and $\e$ represent the sets of variables $(x_1, \dots, x_n)$ and $(u_1, \dots, u_m)$, respectively. The ideal $\langle \e \rangle$ in the polynomial ring $\K[\e]$ is generated by $u_1, \dots, u_m$. 
For a positive integer $\delta$, let  
\[
\langle \e \rangle^{\delta} := \langle u_1^{t_1} \cdots u_m^{t_m} \mid t_1 + \cdots + t_m \geq \delta+1 \rangle \subset \K[\e]
\]  
denote the ideal in $\K[\e]$ generated by all monomials of degree at least $\delta+1$. If $p$ is a polynomial in $\K[\e]$ or a power series in $\K[[\e]]$, then $p \mod \langle \e \rangle^\delta$ refers to the part of $p$ containing terms of degree up to $\delta$.
The rest of this section is devoted to proving the following Proposition. 

\begin{proposition} \label{prop:newton}
Let $\h = (p_1, \dots, p_n)$ be a sequence of polynomials in $\K[\x, \e]$, and let $\balpha = (\alpha_1, \dots, \alpha_m) \in \Kbar{}^m$ be a solution of $P(\x, 0, \dots, 0) = 0$. Assume that the Jacobian matrix of $\h(\x, 0, \dots, 0)$ with respect to $\x$ is full rank at $\balpha$. 

Then there exists a unique vector of power series $\v = (v_1, \dots, v_n)$ in $\Kbar[[\e]]$ such that  
\begin{equation}\label{eq:satis}
\v(0, \dots, 0) = \balpha \quad \text{and} \quad p_1(\v, \e) = \cdots = p_n(\v, \e) = 0.
\end{equation}  

Furthermore, the vector of power series $\v$ can be truncated to an arbitrary degree $\delta$ using the ${\sf Lifting}$ algorithm, such that  
\[
\v^{(\lceil \log_2(\delta) \rceil)} = \v \mod \langle \e \rangle^\delta,
\]
where $\v^{(\lceil \log_2(\delta) \rceil)}$ is the output of the ${\sf Lifting}$ algorithm, which takes $\h$, $\balpha$, and $\delta$ as input. The complexity of computing this truncation is  
\[
\softO((nL + n^4){\mathcal{M}}(\delta, m))
\]
operations in $\K$, where $L$ is the length of a straight-line program computing $\h$.  
\end{proposition}


\begin{algorithm}[h] 	 
\caption{${\sf Lifting}(\h, \balpha, \delta)$}
\label{alg:lift}

\begin{flushleft}
{\bf Input:}
\begin{itemize}
  \item A sequence of polynomials $\h = (p_1, \dots, p_n)$ in $\K[\x, \e]^n$, where $\x = (x_1, \dots, x_n)$ and $\e = (u_1, \dots, u_m)$.
  \item A point $\balpha = (\alpha_1, \dots, \alpha_n) \in \Kbar{}^n$.
  \item A positive integer $\delta$.
\end{itemize}

{\bf Assumptions:}
\begin{itemize}
  \item $\balpha$ is a root of $\h(\x, 0, \dots, 0)$.
  \item The Jacobian matrix of $\h(\x, 0, \dots, 0)$ with respect to $\x$ has full rank at $\balpha$.
\end{itemize}

{\bf Output:} A vector that truncates $\balpha$ in $\K[[\e]]$ with precision $\delta$.
\end{flushleft}

\begin{enumerate}
\item Initialize $\v^{(0)} = \balpha$.

\item Compute the Jacobian matrix $\jac$ of $\h$ with respect to $\x$.

\item For $k = 1$ to $\lceil \log_2(\delta) \rceil$, do:
  \begin{enumerate}
    \item Update:
    \[
    \v^{(k)} = 
    \begin{pmatrix}
    v^{(k-1)}_1 \\ \vdots \\ v^{(k-1)}_n
    \end{pmatrix} 
    - \left(\jac(\v^{(k-1)}, \e)\right)^{-1} 
    \begin{pmatrix}
    p_1(\v^{(k-1)}, \e) \\ \vdots \\ p_n(\v^{(k-1)}, \e)
    \end{pmatrix}.
    \]
  \end{enumerate}
\item Return $\v^{(\lceil \log_2(\delta) \rceil)}$.
\end{enumerate}
\end{algorithm}


\begin{example}
Let us consider the polynomials $$\h = (p_1, p_2)= (x_1 + x_2 - u_1 - 2 , x_1^2 + x_2^2 - u_2 - 10)$$ in $\K[x_1, x_2, u_1, u_2]$. The point $(-1, 3)$ is a root of the system $$p_1(x_1, x_2, 0, 0) = p_2(x_1, x_2, 0, 0) = 0.$$ The Jacobian matrix of $(p_1(x_1, x_2, 0, 0), p_2(x_1, x_2, 0, 0))$ with respect to $(x_1, x_2)$ is  
\[
\begin{pmatrix} 
1 & 1 \\ 
2x_1 & 2x_2 
\end{pmatrix},
\]
which has full rank at $(-1, 3)$.

 The power series  
\[
v_1 = -1 + \frac{3}{4}u_1 - \frac{1}{8}u_2 + \frac{5}{64}u_1^2 - \frac{1}{64}u_1u_2 + \frac{1}{256}u_2^2 + \langle u_1, u_2 \rangle^2
\]
and  
\[
v_2 = 3 + \frac{1}{4}u_1 + \frac{1}{8}u_2 - \frac{5}{64}u_1^2 + \frac{1}{64}u_1u_2 - \frac{1}{256}u_2^2 + \langle u_1, u_2 \rangle^2
\]
in $\K[[u_1, u_2]]$ satisfy the following: $v_1(0, 0) = -1, \ v_2(0, 0) = 3, \ \text{and}$
\[
 \ p_1(v_1, v_2, u_1, u_2) = p_2(v_1, v_2, u_1, u_2) = 0.
\]
\end{example}


\subsection{The existence of power series solutions}
We first prove that the sequence $\left(\v^{(k)}\right)_{k \geq 0}$ is well-defined. To do so, we establish the following claims:

\begin{lemma}\label{lemma:convergent} Let $\jac$ denote the Jacobian matrix of $\h$ with respect to $\x$. Then, for any integer $k \in \mathbb{Z}_{\geq 0}$, 
\begin{itemize}
    \item[$(${\bf a}$)$] the determinant of $\jac$ at $\v^{(k)}$ is invertible in $\K[\e]/\langle \e \rangle$ and
    \item[$(${\bf b}$)$] $p_i(\v^{(k)}, \e) = 0 \mod \langle \e \rangle^{2^k}$ for all $i = 1, \dots, n$.
\end{itemize}
\end{lemma}

            \begin{proof}
We prove these claims by induction on $k$. Base Case ($k = 0$):
For $k = 0$, since $\v^{(0)} = \balpha$, the claims follow directly from the assumptions: 
 $\balpha$ is a root of $\h(\x, 0, \dots, 0)$ and  the Jacobian matrix of $\h(\x, 0, \dots, 0)$ with respect to $\x$ has full rank at $\balpha$.  

Assume that $(${\bf a}$)$ and $(${\bf b}$)$ hold for some $k \geq 0$. We will show that they also hold for $k+1$.  First, from the update rule,
\begin{equation} \label{eq:jac_update}
\v^{(k+1)} - \v^{(k)} = -\jac(\v^{(k)}, \e)^{-1}
\begin{pmatrix}
p_1(\v^{(k)}, \e) \\
\vdots \\
p_n(\v^{(k)}, \e)
\end{pmatrix}.
\end{equation}
Using the induction hypothesis for $k$, we can deduce that
\begin{equation} \label{eq:convergencu_step}
\v^{(k+1)} - \v^{(k)} = 0 \mod \langle \e \rangle^{2^k}.
\end{equation}

\paragraph*{Proof of $(${\bf a}$)$ for $k+1$:}
Let $J$ denote the determinant of $\jac$, the Jacobian matrix of $\h$ with respect to $\x$. Using the Taylor expansion:
\begin{multline*}
J(\v^{(k+1)}, \e) = J(\v^{(k)}, \e) + \sum_{i=1}^n \frac{\partial J}{\partial x_i}(\v^{(k)}, \e) (\v^{(k+1)} - \v^{(k)}) \\
\mod \langle \v^{(k+1)} - \v^{(k)} \rangle^2,
\end{multline*}
where $\langle \v^{(k+1)} - \v^{(k)} \rangle$ is the ideal in $\Kbar(\e)$ generated by the components of $\v^{(k+1)} - \v^{(k)}$. 

By the induction hypothesis for $k$, we know $J(\v^{(k)}, \e)$ is non-zero in $\K[\e]/\langle \e \rangle$. Additionally, from \eqref{eq:convergencu_step}, $\v^{(k+1)} - \v^{(k)} = 0 \mod \langle \e \rangle$. Therefore, $J(\v^{(k+1)}, \e) \neq 0 \mod \langle \e \rangle$, proving $(${\bf a}$)$ for $k+1$.


\paragraph*{Proof of $(${\bf b}$)$ for $k+1$:}
Multiplying both sides of \eqref{eq:jac_update} by the gradient of $p_i$ with respect to $\x$, we obtain:
\[
\left(\frac{\partial p_i}{\partial x_1}, \dots, \frac{\partial p_i}{\partial x_n} \right) 
\left(\v^{(k+1)} - \v^{(k)}\right)^T = -p_i(\v^{(k)}, \e).
\]

Using the Taylor expansion of $p_i$ between $\v^{(k+1)}$ and $\v^{(k)}$, we have
\begin{multline*}
p_i(\v^{(k+1)}, \e) = p_i(\v^{(k)}, \e) + \sum_{j=1}^n 
\frac{\partial p_i}{\partial x_j}(\v^{(k)}, \e)(\v^{(k+1)} - \v^{(k)}) \\
\mod \langle \v^{(k+1)} - \v^{(k)} \rangle^2.
\end{multline*}

Combining these two facts, we conclude:
\[
p_i(\v^{(k+1)}, \e) = 0 \mod \langle \v^{(k+1)} - \v^{(k)} \rangle.
\]
Finally, together with \eqref{eq:convergencu_step}, this implies that
\[
p_i(\v^{(k+1)}, \e) = 0 \mod \langle \e \rangle^{2^{k+1}}.
\]
Thus, $(${\bf b}$)$ holds for $k+1$.
\end{proof}

Let us conclude the existence of the vector of power series $\v$ in $\Kbar[[\e]]^n$ that satisfies~\eqref{eq:satis}. As shown in~\eqref{eq:convergencu_step}, the equation 
\[
\v^{(k+1)} - \v^{(k)} = 0 \mod \langle \e \rangle^{2^k}
\]
holds for any $k \in \ZZ_{\ge 0}$. Thus, for any $i = 1, \dots, n$, the sequence of functions $\left(v_i^{(k)}\right)_{k \in \ZZ_{\ge 0}}$ converges to a power series $v_i$ in $\K[[\e]]$. 

Furthermore, by Lemma~\ref{lemma:convergent}$(${\bf b}$)$, we have:
\[
p_i(\v^{(k)}, \e) = 0 \mod \langle \e \rangle^{2^k}, \quad \text{for } i = 1, \dots, n \text{ and all } k \in \ZZ_{\ge 0}.
\]
This implies that $p_i(\v, \e) = 0$ in $\Kbar[[\e]]$ for all $i = 1, \dots, n$. 

Finally, the relation in~\eqref{eq:convergencu_step} also ensures that:
\[
\v(0, \dots, 0) = \balpha.
\]
This completes the proof of the existence of the vector $\v$ of power series.


