As the diagrams illustrate, to encode the quadrant $\mathbb{N}^2$, it suffices to construct an infinite staircase by alternately taking steps along the first axis (via ${_xR}$) and the second axis (via ${R_y}$). The remaining points in the quadrant $\mathbb{N}^2$ are then generated by applying associativity. This idea forms a key component in our definition of the tiling formulas $\phi^{}_\mathcal{W}$ as well as in our proof of Lemma~\ref{lm:tiling}.
\end{Remark}

\begin{Remark}\label{rm:pastlooking}
    We abbreviate 
        \[
            \varphi\hookrightarrow\psi\mathrel{:=}\neg(\varphi\circ\neg\psi),
        \]
    and
        \[
        \psi\hookleftarrow\varphi\mathrel{:=}\neg(\neg\psi\circ\varphi).
        \]
    %`$\neg({{\circ}\neg})$' by `$\hookrightarrow$' and `$\neg({\neg {\circ}})$' by `$\hookleftarrow$'. 
    It is then readily verified that, given a model $\mathbb{M}=(X,R,V)$, the semantics of `$\hookrightarrow$' and `$\hookleftarrow$' come down to the following:
    \begin{align*}
        &\mathbb{M}, x\Vdash \varphi\hookrightarrow\psi && \text{iff} && \text{for all $y,z\in X$ such that } Rxyz: &&\text{if } \mathbb{M}, y\Vdash \varphi, \\
        & && && &&\text{then }\mathbb{M}, z\Vdash \psi.
    \end{align*}
    \begin{align*}
        &\mathbb{M}, x\Vdash \psi\hookleftarrow\varphi && \text{iff} && \text{for all $y,z\in X$ such that } Rxyz: &&\text{if } \mathbb{M}, z\Vdash \varphi, \\
        & && && &&\text{then }\mathbb{M}, y \Vdash \psi.
    \end{align*}
    Additionally, we define a unary operator `$\Box$' as
    \begin{align*}
        \Box\varphi\mathrel{:=} (\top\hookrightarrow  \varphi)\land (\varphi\hookleftarrow\top)\land ([\top\hookrightarrow\varphi]\hookleftarrow\top),
    \end{align*}    
    and write $Sxy$, or $xS y$, if there are $a,b$ such that
    \begin{itemize}
        \item $Rxay$; or
        \item $Rxya$; or
        \item $Rx(ay)b$.\footnote{Recall Definition~\ref{def:associativeframe}: $Rx(ay)b$ is short for $\exists z\in X (Rxzb \text{ and } Rzay)$.
        %Notation is well-defined by associativity of $R$. More generally, by associativity, we can simply write $(x_1,\hdots, x_n)Rx$ for a tuple $(x_1,\hdots, x_n)$, as the order and multiplicity matters (contra [multi]sets) but the parentheses don't.
        }
    \end{itemize} 
    Observe that 
    \begin{align*}
        &\mathbb{M}, x\Vdash \Box\varphi && \text{iff} && \text{for all $y\in X$ such that } xS y: \mathbb{M}, y\Vdash \varphi,
    \end{align*}
    and note that, due to associativity, the relation $S$ is \textit{transitive}: if $xS yS z$, then $xS z$.%\footnote{This seems important, because this is what makes our defined modality $\Box$ somewhat `global'.}

    For intuition, consider the case where $(X,R)$ is a semilattice; i.e., $Rxyz$ iff $x=y\cdot z$ for $\cdot:X\times X\to X$ a function that is
    \begin{itemize}\itemsep.2cm
        \item commutative: $x\cdot y=y\cdot x$,
        \item associative: $(x\cdot y)\cdot z=x\cdot(y\cdot z)$,
        \item idempotent: $x\cdot x=x$.
    \end{itemize}
    Then $S\subseteq X^2$ is simply the partial order $\geq$ on $X$ defined by the semilattice operation,
    \begin{align*}
        &x\geq y && \text{:iff} && x=x\cdot y,\footnotemark
    \intertext{and $\Box$ the `past-looking' boxed modality}
        &\mathbb{M}, x\Vdash \Box\varphi&&  \text{iff}&& \text{for all $y\leq x:$ $\mathbb{M}, y\Vdash \varphi$.}
    \end{align*}
\end{Remark}\footnotetext{Here, we have construed `$\cdot$' as a join-semilattice, though it could just as well have been treated as a meet-semilattice. We opted for the former to align with our later focus on $(\mathcal{P}(\mathbb{N}), \cup)$, which, perhaps, is more immediately viewed as a join-semilattice.}    
With this, we now define the tiling formulas.
\begin{Definition}[Tiling formulas]   
    Let $\mathcal{W}$ be a finite set of tiles. Given a tile $t\in\mathcal{W}$, denote the sets of tiles that match to the right and upward, respectively, by
    \[
        R(t)=\{t'\in \mathcal{W}\mid t_r=t'_l\}\quad \text{and} \quad U(t)=\{t'\in \mathcal{W}\mid t_u=t'_d\}.\footnotemark
    \]\footnotetext{Recall, cf. Definition~\ref{def:WangTiles}, that for a tile $t$, its edge colours are denoted by \( t_u \) (up), \( t_d \) (down), \( t_l \) (left), and \( t_r \) (right).}
For each tile $t\in \mathcal{W}$, we introduce a propositional letter $\mathtt{t}$ and, by an abuse of notation, identify the tile $t\in \mathcal{W}$ with the conjunction of literals
    \begin{align}
        t\mathrel{:=}\mathtt{t}\land \bigwedge_{t\neq t'\in \mathcal{W}}\neg \mathtt{t'}. \label{eq:tile}
    \end{align}
    By a further abuse, we define formulas corresponding to the sets of tiles that match to the right and upward, respectively, by
    \begin{align}
            \mathtt{R}(t)\mathrel{:=}\bigvee_{t'\in R(t)}t' \quad \text{and} \quad \mathtt{U}(t)\mathrel{:=}\bigvee_{t'\in U(t)}t'.\label{eq:rightandup}
    \end{align}
    Additionally, we introduce propositional letters to encode the quadrant $\mathbb{N}^2$ as well as properties of the coordinate components in pairs $(m,n) \in \mathbb{N}^2$:
    \begin{itemize}
        \item $\mathtt{x_e}$, to encode that the first component $m$ is even, i.e., $m=2m'$.
        \item $\mathtt{x_o}$, to encode that the first component $m$ is odd, i.e., $m=2m'+1$.
        \item $\mathtt{y_e}$, to encode that the second component $n$ is even, i.e., $n=2n'$.
        \item $\mathtt{y_o}$, to encode that the second component $n$ is odd, i.e., $n=2n'+1$.
        \item $\mathtt{x'}$, used in encoding that the first component $m$ is the successor of $m-1$. 
        \item $\mathtt{y'}$, used in encoding that the second component $n$ is the successor of $n-1$. 
    \end{itemize}
Using these propositional letters, we define the formulas:
    \begin{align*}
        %& (\alpha)&&x_e\circ y_e\\
        %& (\alpha)&&\big[x_e\land \neg x_o\land \neg x'\land H(\neg y_e\land\neg y_o\land \neg y')\big]\circ\big[y_e\land \neg y_o\land \neg y'\land H (\neg x_e\land \neg x_o\land \neg x')\big]\\
        &(\alpha_1) && \Box\left(\mathtt{x_e}\to [\mathtt{x'}\circ \mathtt{x_o}]\right)\\
        %&(\beta_1) && H.x_e\to [x_o\land \neg x_e\land \neg x']\circ [x'\land \neg x_e\land \neg x_o]\\
        &(\alpha_2) && \Box\left(\mathtt{x_o}\to [\mathtt{x'}\circ \mathtt{x_e}]\right)\\
        %&(\beta_2) && H.x_o\to  [x_e\land \neg x_o\land \neg x']\circ [x'\land \neg x_e\land \neg x_o]\\
        &(\alpha_3) && \Box\left(\mathtt{y_e}\to [\mathtt{y_o}\circ \mathtt{y'}]\right)\\
        %&(\beta_3) && H.y_e\to [y_o\land \neg y_e\land \neg y']\circ [y'\land \neg y_e\land \neg y_o]\\
        &(\alpha_4) && \Box\left(\mathtt{y_o}\to [\mathtt{y_e}\circ \mathtt{y'}]\right)\\
        %&(\beta_4) && H.y_o\to [y_e\land \neg y_o\land \neg y']\circ [y'\land \neg y_e\land \neg y_o]\\
        &(\beta_1) && \Box\left( \Biggl[\bigvee_{\mathtt{a},\mathtt{b}\in \{\mathtt{e},\mathtt{o}\}} \mathtt{x_a} \circ \mathtt{y_b}\Biggr]\to \bigvee_{t\in \mathcal{W}}t\right)\\
        &(\beta_2) && \Box\bigwedge_{\mathtt{a},\mathtt{b}\in \{\mathtt{e},\mathtt{o}\}}\Biggl( \mathtt{x_a} \circ \mathtt{y_b}\to \bigwedge_{(\mathtt{a'},\mathtt{b'})\neq (\mathtt{a},\mathtt{b})}\neg ( \mathtt{x_{a'}}\circ \mathtt{y_{b'}})\Biggr)\\
        &(\gamma_1^h) && \Box\bigwedge_{t\in \mathcal{W}}\biggl(\Bigl[\mathtt{x_e}\circ \mathtt{y_e}\land t\Bigr] \to\Bigl[ \mathtt{x'} \hookrightarrow \bigl(\mathtt{x_e}\circ \mathtt{y_e}\lor[\mathtt{x_o}\circ \mathtt{y_e}\land \mathtt{R}(t)]\bigr)\Bigr]\biggr)\\
        &(\gamma_1^v) && \Box\bigwedge_{t\in \mathcal{W}}\biggl(\Bigl[\mathtt{x_e}\circ \mathtt{y_e}\land t\Bigr] \to\Bigl[ \bigl(\mathtt{x_e}\circ \mathtt{y_e}\lor[\mathtt{x_e}\circ \mathtt{y_o}\land \mathtt{U}(t)]\bigr) \hookleftarrow \mathtt{y'}  \Bigr]\biggr)\\
        &(\gamma_2^h) && \Box\bigwedge_{t\in \mathcal{W}}\biggl(\Bigl[\mathtt{x_e}\circ \mathtt{y_o}\land t\Bigr] \to\Bigl[ \mathtt{x'} \hookrightarrow \bigl(\mathtt{x_e}\circ \mathtt{y_o}\lor[\mathtt{x_o}\circ \mathtt{y_o}\land \mathtt{R}(t)]\bigr)\Bigr]\biggr)\\
        &(\gamma_2^v) && \Box\bigwedge_{t\in \mathcal{W}}\biggl(\Bigl[\mathtt{x_e}\circ \mathtt{y_o}\land t\Bigr] \to\Bigl[ \bigl(\mathtt{x_e}\circ \mathtt{y_o}\lor[\mathtt{x_e}\circ \mathtt{y_e}\land \mathtt{U}(t)]\bigr) \hookleftarrow \mathtt{y'}  \Bigr]\biggr)\\
        &(\gamma_3^h) && \Box\bigwedge_{t\in \mathcal{W}}\biggl(\Bigl[\mathtt{x_o}\circ \mathtt{y_e}\land t\Bigr] \to\Bigl[ \mathtt{x'} \hookrightarrow \bigl(\mathtt{x_o}\circ \mathtt{y_e}\lor[\mathtt{x_e}\circ \mathtt{y_e}\land \mathtt{R}(t)]\bigr)\Bigr]\biggr)\\
        &(\gamma_3^v) && \Box\bigwedge_{t\in \mathcal{W}}\biggl(\Bigl[\mathtt{x_o}\circ \mathtt{y_e}\land t\Bigr] \to\Bigl[ \bigl(\mathtt{x_o}\circ \mathtt{y_e}\lor[\mathtt{x_o}\circ \mathtt{y_o}\land \mathtt{U}(t)]\bigr) \hookleftarrow \mathtt{y'}  \Bigr]\biggr)\\
        &(\gamma_4^h) && \Box\bigwedge_{t\in \mathcal{W}}\biggl(\Bigl[\mathtt{x_o}\circ \mathtt{y_o}\land t\Bigr] \to\Bigl[ \mathtt{x'} \hookrightarrow \bigl(\mathtt{x_o}\circ \mathtt{y_o}\lor[\mathtt{x_e}\circ \mathtt{y_o}\land \mathtt{R}(t)]\bigr)\Bigr]\biggr)\\
        &(\gamma_4^v) && \Box\bigwedge_{t\in \mathcal{W}}\biggl(\Bigl[\mathtt{x_o}\circ \mathtt{y_o}\land t\Bigr] \to\Bigl[ \bigl(\mathtt{x_o}\circ \mathtt{y_o}\lor[\mathtt{x_o}\circ \mathtt{y_e}\land \mathtt{U}(t)]\bigr) \hookleftarrow \mathtt{y'}  \Bigr]\biggr)
        % &(\delta_0) && \Box\left(\bigwedge_{a,b\in \{e,o\}}\Biggl[ x_a \circ y_b\to \bigwedge_{(a',b')\neq (a,b)}\neg ( x_{a'}\circ y_{b'})\Biggr]\right)\\
        %  &(\delta_1) && \Box\biggl(\Bigl[x_e\circ y_e\Bigr] \to \Bigl[\left( y' \hookrightarrow [x_e\circ y_e\lor x_e\circ y_o]\right)\land \left(x' \hookrightarrow [x_e\circ y_e\lor x_o\circ y_e]\right)\Bigr]\biggr)\\
        %  &(\delta_2) && \Box\biggl(\Bigl[x_e\circ y_o\Bigr] \to \Bigl[\left( y' \hookrightarrow [x_e\circ y_o\lor x_e\circ y_e]\right)\land \left(x' \hookrightarrow [x_e\circ y_o\lor x_o\circ y_o]\right)\Bigr]\biggr)\\
        %  &(\delta_3) && \Box\biggl(\Bigl[x_o\circ y_e\Bigr] \to \Bigl[\left( y' \hookrightarrow [x_o\circ y_e\lor x_o\circ y_o]\right)\land \left(x' \hookrightarrow [x_o\circ y_e\lor x_e\circ y_e]\right)\Bigr]\biggr)\\
        %  &(\delta_4) && \Box\biggl(\Bigl[x_o\circ y_o\Bigr] \to \Bigl[\left( y' \hookrightarrow [x_o\circ y_o\lor x_o\circ y_e]\right)\land \left(x' \hookrightarrow [x_o\circ y_o\lor x_e\circ y_o]\right)\Bigr]\biggr)\footnotemark\\
        % &(\gamma_1) && \Box\bigwedge_{\{u_i, r_j\}\subseteq t\in \mathcal{W}}\biggl(\Bigl[x_e\circ y_e\land u_i\land r_j\Bigr] \to \Bigl[\left( y' \hookrightarrow [x_e\circ y_o\to d_i]\right)\land \left(x' \hookrightarrow [x_o\circ y_e\to l_j]\right)\Bigr]\biggr)\\
        % &(\gamma_2) && \Box\bigwedge_{\{u_i, r_j\}\subseteq t\in \mathcal{W}}\biggl(\Bigl[x_e\circ y_o\land u_i\land r_j\Bigr] \to \Bigl[\left( y' \hookrightarrow [x_e\circ y_e\to d_i]\right)\land \left( x' \hookrightarrow [x_o\circ y_o\to l_j]\right)\Bigr]\biggr)\\
        % &(\gamma_3) && \Box\bigwedge_{\{u_i, r_j\}\subseteq t\in \mathcal{W}}\biggl(\Bigl[x_o\circ y_e\land u_i\land r_j\Bigr] \to \Bigl[\left( y' \hookrightarrow [x_o\circ y_o\to d_i]\right)\land \left(x' \hookrightarrow [x_e\circ y_e\to l_j]\right)\Bigr]\biggr)\\
        % &(\gamma_4) && \Box\bigwedge_{\{u_i, r_j\}\subseteq t\in \mathcal{W}}\biggl(\Bigl[x_o\circ y_o\land u_i\land r_j\Bigr] \to \Bigl[\left( y' \hookrightarrow [x_o\circ y_e\to d_i]\right)\land \left( x' \hookrightarrow [x_e\circ y_o\to l_j]\right)\Bigr]\biggr)
    \end{align*}
    Finally, we let
    \[
        \phi^{}_\mathcal{W} \mathrel{:=} \neg\left(\mathtt{x_e}\circ \mathtt{y_e}\land \bigwedge\alpha_i\land \bigwedge\beta_i\land \bigwedge(\gamma_i^h\land \gamma_i^v)\right).
    \]
\end{Definition}
Clearly, the construction of the tiling formula $\phi^{}_\mathcal{W}$ from a finite set of tiles $\mathcal{W}$ is computable. It therefore only remains to prove the tiling lemmas, Lemma~\ref{lm:tiling} and~\ref{lm:tilingpowerset}, which we now proceed to do. 

\begin{proof}[Proof of Lemma~\ref{lm:tiling}]
    By contraposition, suppose that $\phi^{}_\mathcal{W}$ is not valid in the least associative normal modal logic, i.e., $\phi^{}_\mathcal{W}\notin\mathbf{AK}_2$ (or algebraically, $\mathsf{BSg}\nvDash \phi^{}_\mathcal{W}\approx \top$). We are then to show that $\mathcal{W}$ tiles $\mathbb{N}^2$.

    By canonicity it follows that there is some associative model $\mathbb{M}=(X,R,V)$ and point $z\in X$ such that
        \[
            \mathbb{M}, z\nVdash \phi^{}_\mathcal{W}, 
        \]
    i.e., 
        \[
            \mathbb{M}, z\Vdash \mathtt{x_e}\circ \mathtt{y_e}\land \bigwedge\alpha_i\land \bigwedge\beta_i\land \bigwedge(\gamma_i^h\land \gamma_i^v).
        \]
Using this, we prove that $\mathcal{W}$ tiles $\mathbb{N}^2$. Before proceeding, we outline the structure of the proof. 

\paragraph{\textit{Outline.}} We will begin by identifying elements of $\mathbb{M}$
\[ x_0,x_{1}, x_{2}, \hdots;\quad y_0,y_{1}, y_{2}, \hdots;\quad x_0',x_{1}', x_{2}', \hdots; \quad y_0',y_{1}', y_{2}', \hdots,
\]
which we, in turn, will use to identify what we will call \textit{staircase points}:
\[ p_{1,1}, p_{2,1}, p_{2,2}, p_{3,2}\hdots, p_{k,k}, p_{k+1,k}, \hdots
\]
These are so named because they form a staircase in that they will satisfy:\footnote{Recall that the infix `$x{R}yz$' is synonymous with the prefix `$Rxyz$'.}
\[
    p_{k,k}\,{R}\, x_{k}\, y_{k} \quad \text{and}\quad  p_{k+1,k}\,{R} \,x_{k+1} \,y_{k},
\]
along with
\[
    p_{k,k}\,{R} \,x_{k+1}' \,p_{k+1,k} \quad \text{and} \quad p_{k+1,k}\,{R} \,p_{k+1,k+1} \,y_{k+1}'.
\]
From the staircase, we find a full grid of elements $p_{m,n} \in \mathbb{M}$ for all $(m,n) \in \mathbb{N}\times \mathbb{N}$. Lastly, by associating each point in the quadrant $(m,n) \in \mathbb{N}\times \mathbb{N}$ with the corresponding grid point $p_{m,n} \in \mathbb{M}$, we can define the tiling $\tau:\mathbb{N}\times \mathbb{N}\to \mathcal{W}$ according to which tile formula $t \in \mathcal{W}$ is satisfied at $p_{m,n}$, i.e., $\mathbb{M},  p_{m,n} \Vdash t$. 
\\\\
Returning to the proof, we begin by locating the points $(x_i)_{i\geq 0},(y_i)_{i\geq 0}$ within $\mathbb{M}$---which, loosely speaking, may be thought of as the first and second axis---along with auxiliary points $(x_i')_{i> 0}, (y_i')_{i>0}$ encoding how $x_{i+1}$ and $y_{i+1}$ are successors of $x_{i}$ and $y_{i}$, respectively. Specifically, we use that $z \Vdash  \mathtt{x_e}\circ \mathtt{y_e}\land \bigwedge \alpha_i$ and show by induction that for all $i\geq 0$: 
    \begin{enumerate}
        \item $z\,{R}\,x_0\,y_0$,
        \item $x_i\,{R}\,x_{i+1}'\, x_{i+1}$,
        \item $y_i\,{R} \,y_{i+1} \,y_{i+1}'$, 
        \item\label{itm:primes} $x_{i+1}'\Vdash \mathtt{x'}$ and $y_{i+1}'\Vdash \mathtt{y'}$,
        \item $zSx_i, zSy_i, zSx_{i+1}', zSy_{i+1}'$,
        \item\label{itm:even} If $i$ is even: $x_i\Vdash \mathtt{x_e}$ and $y_i\Vdash \mathtt{y_e}$,
        \item\label{itm:odd} If $i$ is odd: $x_i\Vdash \mathtt{x_o}$ and $y_i\Vdash \mathtt{y_o}$.
    \end{enumerate}
For the base case, since $z\Vdash \mathtt{x_e}\circ \mathtt{y_e}$, there exist points $x_0,y_0\in \mathbb{M}$ such that  $zRx_0y_0$, $x_0\Vdash \mathtt{x_e}$, and $y_0\Vdash \mathtt{y_e}$.

For the induction step, suppose the induction hypothesis holds for some $n\geq 0$. We treat the case of $n$ even; the case where $n$ is odd is analogous. By induction hypothesis, we have $x_n\Vdash \mathtt{x_e}$, $y_n\Vdash \mathtt{y_e}$, $zSx_n,$ and $zSy_n$. Hence, since $z\Vdash \alpha_1\land \alpha_3$, there exist points $x_{n+1}', x_{n+1}, y_{n+1}, y_{n+1}'\in \mathbb{M}$ such that 
\[
    x_n{R} x_{n+1}' x_{n+1}\quad \text{and}\quad y_n{R} y_{n+1} y_{n+1}'
\]
 as well as
\[
    x_{n+1}'\Vdash \mathtt{x'}, \qquad x_{n+1}\Vdash \mathtt{x_o}, \qquad y_{n+1}\Vdash \mathtt{y_o}, \qquad y_{n+1}'\Vdash \mathtt{y'}.
\]
Thus, items 1-4 and 6-7 are met. For item 5, simply recall that $S$ is transitive in the presence of associativity (cf. Remark~\ref{rm:pastlooking}), thereby completing the induction.
\\\\
Next, also by an induction, we show that there are staircase points 
\[
    p_{1,1}, p_{2, 1}, \hdots, p_{k,k}, p_{k+1,k}, \hdots
\]
such that 
\begin{align*}
    &p_{1,1}\,{R} \,x_{2}' \,p_{2,1}, && p_{2,1}\,{R} \, p_{2,2} \,y_{2}', && p_{2,2}\,{R} \,x_{3}' \,p_{3,2}, && p_{3,2}\,{R} \, p_{3,3} \,y_{3}',\hdots \\
    &p_{k,k}\,{R} \,x_{k+1}' \,p_{k+1,k}, && p_{k+1,k}\,{R} \, p_{k+1,k+1} \,y_{k+1}', &&\hdots,
\end{align*}
while also demonstrating that for all $k>1$,
\begin{align}
    &p_{k,k}\,{R} \, x_{k} \, y_{k} && \text{and} && p_{k+1,k}\,{R} \,x_{k+1}\, y_{k}, \label{eq:stair1} \\
    &z\,S\,p_{k,k} && \text{and} && z\,S\,p_{k+1,k}. \label{eq:stair2}
\end{align}
For the base case, using that $zRx_0y_0$, $x_0Rx_{1}'x_{1}$, and $y_0Ry_{1} y_{1}'$, it follows by associativity that there is a point $p_{1,1}$ such that
\[
    z\,{R}\, (x_{1}' \,p_{1,1})\,y_{1}' \quad \text{ so }\quad z\,S\,p_{1,1}, \quad \text{and}\quad p_{1,1}\,{R}\,x_{1}\,y_{1}.
\]
Further, $x_1$ witnesses $p_{1,1}R(x_{2}' x_{2})y_1$ because $x_{1}R x_{2}'x_{2}$, hence, by associativity, 
\[
    p_{1,1}\,R\,x_{2}' \,(x_{2}\,y_1),
\]
which means that there is a point $p_{2,1}$ such that
    \[
        p_{1,1}\,R\, x_2' \, p_{2,1} \quad \text{and}\quad p_{2,1}\,R\, x_2 \,y_1,
    \]
As we have already shown that $z\,S\,p_{1,1}$ and the former implies that $p_{1,1}\,S\,p_{2,1}$, transitivity of $S$ gives us $z\,S\,p_{2,1}$, completing the base case. 

The inductive step has two cases depending on whether we assume the claim up to $p_{k,k}\,{R} \,x_{k+1}' \,p_{k+1,k}$ or up to $p_{k+1,k}\,{R} \, p_{k+1,k+1} \,y_{k+1}'$. We treat the former. That is, we must show that there is some $p_{k+1,k+1}$ such that 
\[
    p_{k+1,k}\,{R} \, p_{k+1,k+1} \,y_{k+1}',\quad p_{k+1,k+1}\,{R} \, x_{k+1} \, y_{k+1}, \quad \text{and}\quad  z\,S\,p_{k+1,k+1}. 
\]
By assumption, we have $p_{k+1,k}\, R\,x_{k+1}\,y_k$, so $y_k$ witnesses $p_{k+1,k}\,R\,x_{k+1} (y_{k+1}y_{k+1}')$ because $y_{k}R y_{k+1}y_{k+1}'$, so by associativity,
\[
    p_{k+1,k}\,R\,(x_{k+1}\, y_{k+1})\,y_{k+1}'.
\]
This means that there is a point $p_{k+1,k+1}$ such that
    \[
        p_{k+1,k}\,R\, p_{k+1,k+1} \, y_{k+1}' \quad \text{and}\quad p_{k+1,k+1}\,R\, x_{k+1}\, y_{k+1},
    \]
which---since $z\,S\,p_{k+1,k}\,S\,p_{k+1,k+1}$ implies $z\,S\,p_{k+1,k+1}$---completes the induction and establishes the staircase. 
\\\\
To generate the full grid, we need points $p_{m,n}\in \mathbb{M}$ for all $m,n\geq 1$ such that 
\begin{align}
    z\, S\, p_{m,n}, \quad p_{m,n}\, R\, x_{m+1}'\, p_{m+1, n}, \quad p_{m,n}\, R\, p_{m, n+1}\, y_{n+1}'.\label{eq:gridproperties}
\end{align}
We already have these points along the staircase, hence, by repeatedly applying associativity as noted in Remark~\ref{rm:AssociativityandTiling}, we get the remaining points as illustrated in Figure~\ref{fig:staircase}.

