That is, for the points $p_{m,n}$ thus obtained, we have  
\[
     p_{m,n}\, R\, x_{m+1}'\, p_{m+1, n} \quad \text{and}\quad p_{m,n}\, R\, p_{m, n+1}\, y_{n+1}'.
\]
Furthermore, $zSp_{m,n}$ holds by transitivity of $S$, since $zSp_{1,1}$ and, for all $p_{m,n}$, we clearly have 
\[
    p_{m,n}\, S\, p_{m+1,n} \quad \text{and} \quad p_{m,n}\, S\, p_{m,n+1}.
\]

As a consequence of $zSp_{m,n}$ along with $z\Vdash \beta_1$ and the identification in~\eqref{eq:tile} of $t\in\mathcal{W}$ with the conjunction of literals, we have that $\tau:\mathbb{N}^2\to \mathcal{W}$ defined by
    \[
        (m,n)\mapsto  t\in \mathcal{W} \text{ such that }p_{m, n} \Vdash t
    \]
is well-defined as a function, provided that all $p_{m,n}\Vdash \bigvee_{\mathtt{a},\mathtt{b}\in \{\mathtt{e},\mathtt{o}\}} \mathtt{x_a} \circ \mathtt{y_b}$. In fact, to show that $\tau$ defines a tiling, we will need something stronger than this proviso, namely that for all $p_{m,n}$,
 \begin{align*}
     &\text{If $m$ and $n$ are even: } && p_{m,n}\Vdash \mathtt{x_e}\circ \mathtt{y_e}\land \bigwedge_{(\mathtt{a'},\mathtt{b'})\neq (\mathtt{e},\mathtt{e})}\neg ( \mathtt{x_{a'}}\circ \mathtt{y_{b'}}),\\
    &\text{If $m$ is even and $n$ is odd: } && p_{m,n} \Vdash \mathtt{x_e}\circ \mathtt{y_o}\land \bigwedge_{(\mathtt{a'},\mathtt{b'})\neq (\mathtt{e},\mathtt{o})}\neg ( \mathtt{x_{a'}}\circ \mathtt{y_{b'}}),\\
    &\text{If $m$ is odd and $n$ is even: } && p_{m,n} \Vdash \mathtt{x_o}\circ \mathtt{y_e}\land \bigwedge_{(\mathtt{a'},\mathtt{b'})\neq (\mathtt{o},\mathtt{e})}\neg ( \mathtt{x_{a'}}\circ \mathtt{y_{b'}}),\\
    &\text{If $m$ and $n$ are odd: } && p_{m,n} \Vdash \mathtt{x_o}\circ \mathtt{y_o}\land \bigwedge_{(\mathtt{a'},\mathtt{b'})\neq (\mathtt{o},\mathtt{o})}\neg ( \mathtt{x_{a'}}\circ \mathtt{y_{b'}}).
 \end{align*}
We show this by an induction, using the staircase as our base case. For the staircase points, this follows immediately: \eqref{eq:stair1}, together with item~\ref{itm:even} and~\ref{itm:odd}, imply the first conjunct; the second then follows from \eqref{eq:stair2} and that $z\Vdash \beta_2$.

For the inductive step, we show that if the claim holds for both $p_{m',n'}$ and $p_{m'+1,n'+1}$, then it also holds for $p_{m',n'+1}$ and $p_{m'+1,n'}$. As noted, this will, in particular, entail that $\tau$ is well-defined as a function. To complete the proof, as part of the same argument, we also show that $\tau$ satisfies the tiling conditions: 
\[
    \tau(m',n')_r = \tau(m'+1,n')_l \quad \text{and} \quad \tau(m',n')_u = \tau(m',n'+1)_d.
\]
By our definition of $\tau$ and the formulas $t, \mathtt{R}(t),$ and $\mathtt{U}(t)$ (cf.~\eqref{eq:tile} and~\eqref{eq:rightandup}), this means showing that
\[
    \text{if }p_{m',n'}\Vdash t \text{ then } p_{m'+1,n'}\Vdash \mathtt{R}(t) \quad \text{and} \quad 
    \text{if }p_{m',n'}\Vdash t \text{ then } p_{m',n'+1}\Vdash \mathtt{U}(t).
\]
There are four cases to consider, corresponding to the parities of $m'$ and $n'$. Since the cases are analogous, we only cover the case where $m'$ and $n'$ are even and show that the claim follows for $p_{m',n'+1}$. Assume, then, that the claim holds for $m'=2m$ and $n'=2n$; that is,
\[
    p_{2m,2n}\Vdash \mathtt{x_e}\circ \mathtt{y_e}\land \bigwedge_{(\mathtt{a'},\mathtt{b'})\neq (\mathtt{e},\mathtt{e})}\neg ( \mathtt{x_{a'}}\circ \mathtt{y_{b'}})
\]
and
\[ 
    p_{2m+1,2n+1}\Vdash \mathtt{x_o}\circ \mathtt{y_o}\land \bigwedge_{(\mathtt{a'},\mathtt{b'})\neq (\mathtt{o},\mathtt{o})}\neg ( \mathtt{x_{a'}}\circ \mathtt{y_{b'}}).
\]
Then, as mentioned, $zSp_{2m,2n}$, $p_{2m,2n}\Vdash \mathtt{x_e}\circ \mathtt{y_e}$, and $z\Vdash \beta_1$, jointly imply that $p_{2m,2n}\Vdash t$ for some $t\in \mathcal{W}$. So to complete the proof of this tiling lemma, we show that not only
\[
    p_{2m,2n+1} \Vdash \mathtt{x_e}\circ \mathtt{y_o}\land \bigwedge_{(\mathtt{a'},\mathtt{b'})\neq (\mathtt{e},\mathtt{o})}\neg ( \mathtt{x_{a'}}\circ \mathtt{y_{b'}})
\]
but also
\[
    p_{2m,2n+1} \Vdash\mathtt{U}(t).
\]
Since we have (a) $z\Vdash \gamma_1^v$, (b) $zSp_{2m,2n}$ , (c) $p_{2m,2n}\Vdash \mathtt{x_e}\circ \mathtt{y_e}\land t$, (d) $p_{2m,2n}\,R \,p_{2m, 2n+1}\,y_{2n+1}'$ (by \eqref{eq:gridproperties}), and (e) $y_{2n+1}'\Vdash \mathtt{y'}$ (by item~\ref{itm:primes}), we get that
\[
    p_{2m, 2n+1}\Vdash \mathtt{x_e}\circ \mathtt{y_e}\lor[\mathtt{x_e}\circ \mathtt{y_o}\land \mathtt{U}(t)].
\]
It follows that $p_{2m, 2n+1}\Vdash t'$ for some $t'\in \mathcal{W}$. Hence, if we had $p_{2m, 2n+1}\Vdash \mathtt{x_e}\circ \mathtt{y_e}$, then (a') $z\Vdash \gamma_1^h$, (b') $zSp_{2m,2n+1}$, (c') $p_{2m,2n+1}\Vdash \mathtt{x_e}\circ \mathtt{y_e}\land t'$, (d') $p_{2m,2n+1}\,R \,x_{2m+1}'\,p_{2m+1, 2n+1}$, and (e') $x_{2m+1}'\Vdash \mathtt{x'}$, would jointly imply that
\[
    p_{2m+1, 2n+1}\Vdash \mathtt{x_e}\circ \mathtt{y_e}\lor \mathtt{x_o}\circ \mathtt{y_e},
\]
which is a contradiction, as we have by assumption that
\[
    p_{2m+1,2n+1}\Vdash \mathtt{x_o}\circ \mathtt{y_o}\land \bigwedge_{(\mathtt{a'},\mathtt{b'})\neq (\mathtt{o},\mathtt{o})}\neg ( \mathtt{x_{a'}}\circ \mathtt{y_{b'}}).
\]
Thus, $p_{2m, 2n+1}\nVdash \mathtt{x_e}\circ \mathtt{y_e}$, so $p_{2m, 2n+1}\Vdash \mathtt{x_e}\circ \mathtt{y_o}\land \mathtt{U}(t)$, whence the remaining 
\[
    p_{2m, 2n+1} \Vdash \bigwedge_{(\mathtt{a'},\mathtt{b'})\neq (\mathtt{e},\mathtt{o})}\neg ( \mathtt{x_{a'}}\circ \mathtt{y_{b'}})
\]
follows from $z\Vdash \beta_2$ and $zSp_{2m, 2n+1}$, finalizing our proof.
\end{proof}

We continue with the proof of the other  tiling lemma.

\begin{proof}[Proof of Lemma~\ref{lm:tilingpowerset}]
    Suppose, contrapositively, that $\tau:\mathbb{N}^2\to \mathcal{W}$ is a tiling. We have to show that $\phi^{}_\mathcal{W}$ is refuted by $(\mathcal{P}(\mathbb{N}), \cup)$, i.e., $\phi^{}_\mathcal{W}\notin \mathrm{Log}(\mathcal{P}(\mathbb{N}),\cup)$ (or algebraically, $(\mathcal{P}(\mathbb{N}), \cup)^+\nvDash \phi^{}_\mathcal{W}\approx \top$).

    To this end, write $2\mathbb{N}=\{2n\mid n\in \mathbb{N}\}$ for the even numbers and $2\mathbb{N}+1=\{2n+1\mid n\in \mathbb{N}\}$ for the odd numbers, and define a valuation $V$ as follows:    
\begin{align*}
        V(\mathtt{x_e})&=\{X\subseteq 2\mathbb{N}\mid |2\mathbb{N}\setminus X| \text{ is even}\},\\
        V(\mathtt{x_o})&=\{X\subseteq 2\mathbb{N}\mid |2\mathbb{N}\setminus X| \text{ is odd}\},\\
        V(\mathtt{y_e})&=\{X\subseteq 2\mathbb{N}+1\mid |(2\mathbb{N}+1)\setminus X| \text{ is even}\},\\
        V(\mathtt{y_o})&=\{X\subseteq 2\mathbb{N}+1\mid |(2\mathbb{N}+1)\setminus X| \text{ is odd}\},\\
        V(\mathtt{x'})&=\{\{n\}\mid n\in 2\mathbb{N}\},\\
        V(\mathtt{y'})&=\{\{n\}\mid n\in (2\mathbb{N}+1)\},\\
        V(\mathtt{t})&=\{X\cup Y\mid X\in (V(\mathtt{x_e})\cup V(\mathtt{x_o})), Y\in (V(\mathtt{y_e})\cup V(\mathtt{y_o})),\\
        &\qquad\qquad\qquad\tau(|2\mathbb{N}\setminus X|,|(2\mathbb{N}+1)\setminus Y|)=t\}.
\end{align*}
We proceed showing that
    \begin{align*}
        (\mathcal{P}(\mathbb{N}), \cup, V), \mathbb{N}\nVdash \phi^{}_\mathcal{W},
    \end{align*}
i.e.,
    \begin{align*}
        (\mathcal{P}(\mathbb{N}), \cup, V), \mathbb{N}\Vdash \mathtt{x_e}\circ \mathtt{y_e}\land \bigwedge\alpha_i\land \bigwedge\beta_i\land \bigwedge(\gamma_i^h\land \gamma_i^v).
    \end{align*}
First off, observe that $2\mathbb{N}\Vdash \mathtt{x_e}$ and $2\mathbb{N}+1\Vdash \mathtt{y_e}$, hence
\[
    \mathbb{N}=2\mathbb{N}\cup (2\mathbb{N}+1)\Vdash \mathtt{x_e}\circ \mathtt{y_e}.
\]

\textbf{Alphas ($\boldsymbol{\alpha_i}$).} Second, to see that $\mathbb{N}$ also satisfies the $\alpha$'s, note that if some $X\Vdash \mathtt{x_e}$, then by definition $X\subseteq 2\mathbb{N}$ such that $|2\mathbb{N}\setminus X|$ is even. In particular, there are even numbers $2n\in X$, and for these, we have $\{2n\}\Vdash \mathtt{x'}$ and $|2\mathbb{N}\setminus(X\setminus\{2n\})|$ is odd, hence
    \begin{align*}
        X=\{2n\}\cup (X\setminus \{2n\}) \Vdash \mathtt{x'}\circ \mathtt{x_o},
    \end{align*}
as required. 
A fortiori, $\mathbb{N}\Vdash \alpha_1$. $\mathbb{N}\Vdash \alpha_2\land \alpha_3\land \alpha_4$ is proven analogously.
%$X$ is the set of even naturals but for some (potentially empty) initial sequence of even numbers  
%\\\\
%\textbf{Beta ($\boldsymbol{\beta}$):} $\mathbb{N}\Vdash\beta$ is an easy consequence of the following observations: (1) the decomposition of a $Z\subseteq \mathbb{N}$ into $X\cup Y=Z$ for $X\in (V(x_o)\cup V(x_e)), Y\in (V(y_o)\cup V(y_e))$ is unique when it exists; and (2) $V(x_e)\cap V(x_o)=V(y_e)\cap V(y_o)=\varnothing$.
% for all $X\in V(x_e), X'\in V(x_o), Y\in V(y_e), Y'\in V(y_o)$:
%     \begin{align*}
%         X\neq X', \qquad Y\neq Y', \qquad X\cap Y=X\cap Y'=X'\cap Y=X'\cap Y'=\varnothing.
%     \end{align*}

\textbf{Betas ($\boldsymbol{\beta_i}$).} Note that the decomposition of a $Z\subseteq \mathbb{N}$ into $X\cup Y=Z$ for $X\in (V(\mathtt{x_e})\cup V(\mathtt{x_o})), Y\in (V(\mathtt{y_e})\cup V(\mathtt{y_o}))$ is unique when it exists. So since $\tau:\mathbb{N}^2\to \mathcal{W}$ in particular is a function, we get that $\mathbb{N}\Vdash\beta_1$; and since $V(\mathtt{x_e}), V(\mathtt{x_o}), V(\mathtt{y_e}), V(\mathtt{y_o})$ are pairwise disjoint, we also have $\mathbb{N}\Vdash \beta_2$.

\textbf{Gammas ($\boldsymbol{\gamma_i}$).} In proving that $\mathbb{N}\Vdash\gamma_1^h\land \gamma_1^v\land \cdots \land \gamma_4^h\land \gamma_4^v$, we only cover the first conjunct, as the others are proven analogously. Accordingly, suppose $Z\Vdash \mathtt{x_e}\circ \mathtt{y_e}\land t$ for some tile $t$, and let $Z'\subseteq \mathbb{N}$ and $n\in 2\mathbb{N}$ be arbitrary such that $Z= \{n\}\cup Z'$. For the purpose of demonstrating that $\mathbb{N}\Vdash\gamma_1^h$, we must show that
    \[
        Z'\Vdash \mathtt{x_e}\circ \mathtt{y_e}\lor[\mathtt{x_o}\circ \mathtt{y_e}\land \mathtt{R}(t)].
    \]
If $n\in Z'$, then $Z'=Z\Vdash \mathtt{x_e}\circ \mathtt{y_e}$, as required. \\
If $n\notin Z'$, we use that $Z\Vdash \mathtt{x_e}\circ \mathtt{y_e}$ implies that $Z=X\cup Y$ for some $X\in V(\mathtt{x_e})$ and $Y\in V(\mathtt{y_e})$. Since $Z\ni n$ is even, it follows that $n\in X$, whence
    \[
        Z'=(X\setminus \{n\})\cup Y\Vdash \mathtt{x_o}\circ \mathtt{y_e}.
    \]
Further, using that $Z\Vdash t$, so $X\cup Y=Z\Vdash \mathtt{t}$, which means that $ \tau(|2\mathbb{N}\setminus X|, |(2\mathbb{N}+1)\setminus Y|)=t$, we get that
\begin{align*}
    \tau(|2\mathbb{N}\setminus (X\setminus\{n\})|, |(2\mathbb{N}+1)\setminus Y|)=\tau(|2\mathbb{N}\setminus X|+1, |(2\mathbb{N}+1)\setminus Y|\in R(t),
\end{align*}
