		\includegraphics[width=0.9\linewidth]{square_corner.pdf}
		\caption{Topological corner modes of square grid-like frame, where the modes are quadruply degenerate at frequency $\beta_{t}^{(1)}$, and are localized at the corners.}
		\label{Fig_s_c}
	\end{figure}

	By comparing the formulae~\eqref{eq5_1} and \eqref{eq5_2} with the existence condition of topological edge states in the continuous beam structure \citep{SUN2025105935}, we conclude: the set of frequencies of the higher-order topological corner states of a square grid-like frame with length parameters $(l_{1},l_{2})$ is exactly the same as that of the topological edge states of a continuous beam structure with length parameters $(l_{1},l_{2})$.

	\subsection{Edge states in square frames}
	From Eq.~\eqref{eq5_5}, every eigenvalue $\lambda^\mathrm{square}$ of the dynamical matrix $H^\mathrm{square}$ of the square grid-like frame can be obtained by adding two eigenvalues $\lambda^\mathrm{beam}$ of the dynamical matrices $H^\mathrm{beam}$ of two continuous beams with the same structural parameters. Now, as an edge state of the 2D structure must come from the tensor product of two 1D states---an \emph{edge} state along one direction and a \emph{bulk} state along another direction, the eigenvalue $\lambda^\mathrm{square}_\mathrm{edge}$ of matrix $H^\mathrm{square}$ corresponding to an edge state of the square frame must equal the sum of the eigenvalue $\lambda^\mathrm{beam}_\mathrm{edge}$ of matrix $H^\mathrm{beam}$ corresponding to an edge state, and the eigenvalue $\lambda^\mathrm{beam}_\mathrm{bulk}$ of matrix $H^\mathrm{beam}$ corresponding to a bulk state. We have
	\begin{equation}
		\label{eq5_6}
		\lambda^\mathrm{beam}_\mathrm{edge}=\left[\frac{B(\beta l_1)}{A(\beta l_1)}+\frac{B(\beta l_2)}{A(\beta l_2)}\right]+0,
	\end{equation}
	and
	\begin{equation}
		\label{eq5_7}
		\lambda^\mathrm{beam}_\mathrm{bulk}=\left[\frac{B(\beta l_1)}{A(\beta l_1)}+\frac{B(\beta l_2)}{A(\beta l_2)}\right]\pm \left\lvert\frac{C(\beta l_1)}{A(\beta l_1)} + \frac{C(\beta l_2)}{A(\beta l_2)} \exp{(\mathrm{i}k_{x(y)}L)}\right\rvert,
	\end{equation}
	where $k_{x(y)}L\in(-\pi,\pi]$; thus, we obtain
	\begin{equation}
		\label{eq5_8}
		\lambda^\mathrm{square}_\mathrm{edge}=2\left[\frac{B(\beta l_1)}{A(\beta l_1)}+\frac{B(\beta l_2)}{A(\beta l_2)}\right]\pm \left\lvert\frac{C(\beta l_1)}{A(\beta l_1)} + \frac{C(\beta l_2)}{A(\beta l_2)} \exp{(\mathrm{i}k_{x(y)}L)}\right\rvert.
	\end{equation}
	In order for the dynamical equation $H^{\mathrm{square}} \lvert \theta \rangle = 0$ of the square frame to have an edge-state solution, it holds that $\lambda^\mathrm{square}_\mathrm{edge}=0$, that is, the frequency $\beta$ of the edge state should satisfy
	\begin{equation}
		\label{eq5_10}
		2\left[\frac{B(\beta l_1)}{A(\beta l_1)}+\frac{B(\beta l_2)}{A(\beta l_2)}\right]=\pm \left\lvert\frac{C(\beta l_1)}{A(\beta l_1)} + \frac{C(\beta l_2)}{A(\beta l_2)} \exp{(\mathrm{i}k_{x(y)}L)}\right\rvert;
	\end{equation}
	moreover, the topological nontriviality condition for the 1D dynamical matrix $H^\mathrm{square}$ should apply: for $\beta$ satisfying Eq.~\eqref{eq5_10}, if and only if
	\begin{equation}
		\label{eq5_10a}
		\left \lvert \frac{C(\beta l_1)}{A(\beta l_1)} \right \rvert < \left \lvert\frac{C(\beta l_2)}{A(\beta l_2)} \right \rvert,
	\end{equation} edge states exist at frequencies $\beta$.

	For any specific $\beta$, when the sign on the right-hand side of Eq.~\eqref{eq5_8} is fixed and taken to be either plus or minus, the eigenvalue $\lambda^\mathrm{square}_\mathrm{edge}$ is monotonic with respect to $k_{x(y)}L$ in the range $k_{x(y)}L\in[0,\pi]$, and the lower and upper bounds of  $\lambda^\mathrm{square}_\mathrm{edge}$ are reached at $k_{x(y)}L=0$ or $\pi$, represented by orange and blue solid curves as shown in Fig.~\ref{Fig_5_2}(a). The frequencies $\beta$ that satisfy Eq.~\eqref{eq5_10} correspond to the intervals bounded by intersections of adjacent blue and orange curves with axis $\lambda=0$, within the ranges $(\beta_0^{(n-1)},\beta_t^{(n)})$ and $(\beta_t^{(n)},\beta_0^{(n)})$; however, edge states only exist in part of these intervals, indicated by yellow line segments in Fig.~\ref{Fig_5_2}(a), where the two functions $[C(\beta l_1)A(\beta l_2) \pm C(\beta l_2)A(\beta l_1)]$ corresponding to the blue and orange dotted curves take opposite signs, rendering the condition~\eqref{eq5_10a} true. Finally, the edge modes of the square grid-like frame in intervals $(0,\beta_t^{(1)})$ and $(\beta_t^{(1)},\beta_0^{(1)})$ are shown in Fig.~\ref{Fig_s_e}, where the deformations of beams are localized at the edges of square frames. The above conclusions are verified.
	\begin{figure}[tb!]
		\centering
		\includegraphics[width=0.9\linewidth]{square_edge.pdf}
		\caption{Edge modes of the square grid-like frame. (a)--(b) Edge states at $k_{x(y)}L=0$, $k_{x(y)}L=\pi$ in the interval $(\beta_0^{(0)},\beta_t^{(1)})$ in Fig.~\ref{Fig_5_2}. (c)--(d) Edge states at $k_{x(y)}L=\pi$, $k_{x(y)}L=0$ in the interval $(\beta_t^{(1)},\beta_0^{(1)})$ in Fig.~\ref{Fig_5_2}.}
		\label{Fig_s_e}
	\end{figure}

	The existence of edge states in a square grid-like frame is investigated theoretically below: as we will see, there exists a set of continuous $\beta$ satisfying Eq.~\eqref{eq5_10} in every interval $(\beta_0^{(n-1)},\beta_t^{(n)})$ and $(\beta_t^{(n)},\beta_0^{(n)})$. Meanwhile, when $\left \lvert \frac{C(\beta_t l_1)}{A(\beta_t l_1)} \right \rvert \neq\left \lvert\frac{C(\beta_t l_2)}{A(\beta_t l_2)} \right \rvert$, topological corner states must lie within bandgaps of edge states, that is, the frequencies of corner states are not inside the frequency range of edge states. To this end, we let
	\begin{equation}
		\label{eq5_11}
		f(\beta)=\left\lvert\frac{C(\beta l_1)}{A(\beta l_1)} + \frac{C(\beta l_2)}{A(\beta l_2)} \exp{(\mathrm{i}k_{x(y)}L)}\right\rvert^2 - 4\left[\frac{B(\beta l_1)}{A(\beta l_1)} + \frac{B(\beta l_2)}{A(\beta l_2)}\right]^2.
	\end{equation}
	The solution set of $f(\beta)=0$ is the frequency range where edge states may exist (see Eq.~\eqref{eq5_10}). Now consider $f(\beta_t^{(n)})$. First note that Eq.~\eqref{eq5_1} holds at the frequencies $\beta_t$ of the corner states, which implies that the second term of $f(\beta_t^{(n)})$ is zero. Next, when $\left \lvert \frac{C(\beta_t l_1)}{A(\beta_t l_1)} \right \rvert \neq\left \lvert\frac{C(\beta_t l_2)}{A(\beta_t l_2)} \right \rvert$, we have
		\[
		\left\lvert\frac{C(\beta_t l_1)}{A(\beta_t l_1)} + \frac{C(\beta_t l_2)}{A(\beta_t l_2)} \exp{(\mathrm{i}k_{x(y)}L)}\right\rvert \ge \Biggl\lvert \left\lvert \frac{C(\beta_t l_1)}{A(\beta_t l_1)} \right\rvert - \left\lvert \frac{C(\beta_t l_2)}{A(\beta_t l_2)} \right\rvert \Biggr\rvert > 0.
		\]
	Therefore, for $\beta=\beta_t^{(n)}$,
		\[ f(\beta_t^{(n)}) > 0, \]
	and Eq.~\eqref{eq5_10} never holds. It is concluded that as long as $\left \lvert \frac{C(\beta_t l_1)}{A(\beta_t l_1)} \right \rvert \neq\left \lvert\frac{C(\beta_t l_2)}{A(\beta_t l_2)} \right \rvert$, the frequencies of corner states do not coincide with edge states. On the other aspect, when $\beta\rightarrow\beta_0^{(n)}$ (i.e., $A(\beta l_{1})\rightarrow 0^\pm$ or $A(\beta l_{2})\rightarrow 0^\pm$), in the light of the identity $C^2(\beta l)-B^2(\beta l)=-2\sinh(\beta l)\sin(\beta l)\cdot A(\beta l)$, it holds that
	\[
	f(\beta)=-3\left[\frac{B(\beta l_{1(2)})}{A(\beta l_{1(2)})}\right]^2+O[(\beta-\beta^{(n)}_0)^{-1}]\rightarrow -\infty;
	\]
	we note that the order of the first term is $(\beta - \beta_0^{(n)})^{-2}$, and thus $f(\beta)$ tends to negative infinity on both sides of $\beta_0^{(n)}$. In terms of this result and the condition $f(\beta_t^{(n)})>0$, there must exist a set of continuous $\beta$ satisfying Eq.~\eqref{eq5_10} in each interval $(\beta_0^{(n-1)},\beta_t^{(n)})$ and $(\beta_t^{(n)},\beta_0^{(n)})$. The above conclusions are verified by Fig.~\ref{Fig_5_2}(a), where a blue and an orange solid curve exist between each dark blue dashed curve and the neighboring pink or green vertical line. On the axis $\lambda=0$, the intervals between adjacent blue and orange solid curves within every $(\beta_0^{(n-1)},\beta_t^{(n)})$ and $(\beta_t^{(n)},\beta_0^{(n)})$ represent the frequency ranges of candidate edge states, that is, $\beta$ satisfying Eq.~\eqref{eq5_10}.

	\subsection{Bulk states in square frames}\label{secSquareBulk}
	The eigenvalue $\lambda^\mathrm{square}_\mathrm{bulk}$ of matrix $H^\mathrm{square}$ corresponding to any bulk state of the square grid-like frame, equals the sum of two eigenvalues $\lambda^\mathrm{beam}_\mathrm{bulk}$ of matrix $H^\mathrm{beam}$ corresponding to bulk states of the continuous beam in the two orthogonal directions. It follows from Eq.~\eqref{eq5_7} that
	\begin{equation}
		\label{eq5_12}
		\lambda^\mathrm{square}_\mathrm{bulk} = 2\left[\frac{B(\beta l_1)}{A(\beta l_1)}+\frac{B(\beta l_2)}{A(\beta l_2)}\right] \pm \left\lvert\frac{C(\beta l_1)}{A(\beta l_1)} + \frac{C(\beta l_2)}{A(\beta l_2)} \exp{(\mathrm{i}k_{x}L)}\right\rvert \pm \left\lvert\frac{C(\beta l_1)}{A(\beta l_1)} + \frac{C(\beta l_2)}{A(\beta l_2)} \exp{(\mathrm{i}k_{y}L)}\right\rvert.
	\end{equation}
	For a specific $\beta$, the set of eigenvalues $\lambda^\mathrm{square}_\mathrm{bulk}$ is the union of three clusters, denoted as top, middle and bottom, given by the expressions
	{\small
		\begin{align}
			\label{eq5_13}
			\lambda^\mathrm{square}_\mathrm{bulk(top)} &= 2\left[\frac{B(\beta l_1)}{A(\beta l_1)}+\frac{B(\beta l_2)}{A(\beta l_2)}\right] + \left\lvert\frac{C(\beta l_1)}{A(\beta l_1)} + \frac{C(\beta l_2)}{A(\beta l_2)} \exp{(\mathrm{i}k_{x}L)}\right\rvert + \left\lvert\frac{C(\beta l_1)}{A(\beta l_1)} + \frac{C(\beta l_2)}{A(\beta l_2)} \exp{(\mathrm{i}k_{y}L)}\right\rvert, \\
			\label{eq5_14}
			\lambda^\mathrm{square}_\mathrm{bulk(middle)} &= 2\left[\frac{B(\beta l_1)}{A(\beta l_1)}+\frac{B(\beta l_2)}{A(\beta l_2)}\right] + \left\lvert\frac{C(\beta l_1)}{A(\beta l_1)} + \frac{C(\beta l_2)}{A(\beta l_2)} \exp{(\mathrm{i}k_{x(y)}L)}\right\rvert - \left\lvert\frac{C(\beta l_1)}{A(\beta l_1)} + \frac{C(\beta l_2)}{A(\beta l_2)} \exp{(\mathrm{i}k_{y(x)}L)}\right\rvert, \\
			\label{eq5_15}
			\lambda^\mathrm{square}_\mathrm{bulk(bottom)} &= 2\left[\frac{B(\beta l_1)}{A(\beta l_1)}+\frac{B(\beta l_2)}{A(\beta l_2)}\right] - \left\lvert\frac{C(\beta l_1)}{A(\beta l_1)} + \frac{C(\beta l_2)}{A(\beta l_2)} \exp{(\mathrm{i}k_{x}L)}\right\rvert - \left\lvert\frac{C(\beta l_1)}{A(\beta l_1)} + \frac{C(\beta l_2)}{A(\beta l_2)} \exp{(\mathrm{i}k_{y}L)}\right\rvert.
		\end{align}
	}In order for the dynamical equation \eqref{eq5_9} of square frames to have solutions, $\lambda^\mathrm{square}_\mathrm{bulk}=0$ needs to be satisfied, which corresponds to the bulk states of square grid-like frames. As shown in Fig.~\ref{Fig_5_2}(b), the frequency ranges of bulk states satisfying $\lambda^\mathrm{square}_\mathrm{bulk(top)}=0$ or $\lambda^\mathrm{square}_\mathrm{bulk(bottom)}=0$ correspond to the set of points on the horizontal axis that lie between two neighboring black dashed curves, and the frequency ranges of bulk states that satisfy $\lambda^\mathrm{square}_\mathrm{bulk(middle)}=0$ correspond to the set of points between two neighboring purple dashed curves. It is interesting to note that the set of eigenvalues $\lambda^{\mathrm{square}}_{\mathrm{bulk(top)}}$ corresponding to Eq.~\eqref{eq5_13} has exactly the same range as given by the expression
	\begin{equation}	\label{eq5_13add}
		2\left[\frac{B(\beta l_1)}{A(\beta l_1)}+\frac{B(\beta l_2)}{A(\beta l_2)}\right] + 2\left\lvert\frac{C(\beta l_1)}{A(\beta l_1)} + \frac{C(\beta l_2)}{A(\beta l_2)} \exp{(\mathrm{i}kL)}\right\rvert;
	\end{equation}
	the set of eigenvalues $\lambda^{\mathrm{square}}_{\mathrm{bulk(bottom)}}$ corresponding to Eq.~\eqref{eq5_15} has exactly the same range as given by the expression
	\begin{equation}	\label{eq5_14add}
		2\left[\frac{B(\beta l_1)}{A(\beta l_1)}+\frac{B(\beta l_2)}{A(\beta l_2)}\right] - 2\left\lvert\frac{C(\beta l_1)}{A(\beta l_1)} + \frac{C(\beta l_2)}{A(\beta l_2)} \exp{(\mathrm{i}kL)}\right\rvert.
	\end{equation}
	By comparing the expressions~\eqref{eq5_13add} and \eqref{eq5_14add} with Eq.~\eqref{eq5_7}, it is concluded that part of the bulk bands of the square frame, that is, the bulk frequency ranges pertaining to the ``top'' and ``bottom'' clusters ($\lambda^\mathrm{square}_\mathrm{bulk(top)} = 0$ or $\lambda^\mathrm{square}_\mathrm{bulk(bottom)} = 0$), is identical to the frequency ranges of bulk bands of the continuous beam structure \citep{SUN2025105935}. Meanwhile, the frequency ranges of bulk states satisfying $\lambda^\mathrm{square}_\mathrm{bulk(middle)}=0$ (the ``middle'' cluster) must contain all the frequencies of corner states $\beta_t$, since the range of Eq.~\eqref{eq5_14} always includes the value $\lambda^\mathrm{square}_\mathrm{bulk(middle)}=2\left[\frac{B(\beta l_1)}{A(\beta l_1)}+\frac{B(\beta l_2)}{A(\beta l_2)}\right]+0=\lambda^\mathrm{square}_\mathrm{corner}$. This conclusion is also drawn from Fig.~\ref{Fig_5_2}(b), where the dark blue dashed curves are always immersed in the shaded regions between adjacent purple dashed curves.

	\section{Topological kagome grid-like frames}
	In this section, we introduce the kagome frame structure and analyze its (first-order and higher-order) topological properties. The kagome frame structure consists of beam segments with alternating lengths $l_1$ and $l_2$ along each of the three directions; as shown in Fig.~\ref{Fig_5_3}(a), the structure contains two different types of equilateral triangles formed by beam segments, one pointing upwards with side length $l_1$, and the other pointing downwards with side length $l_2$. The unit cell is taken to include the upward-pointing triangle, whose three rigid joints lie at sublattices A, B and C, respectively. Therefore, the lengths of intracell beam segments are $l_1$, and the lengths of intercell beam segments $l_2$. The whole structure contains $N(N+1)/2$ unit cells in total, where $N$ is the number of unit cells along each side. All the exterior ends of the outermost beam segments are clamped ends. Each unit cell is labeled by $(m, n)$, so that the position vector of the cell is $\boldsymbol{r} = mL \boldsymbol{e}_1 + nL \boldsymbol{e}_2$ (where $L=l_1+l_2$ is the lattice constant, and $\boldsymbol{e}_1$, $\boldsymbol{e}_2$ are unit vectors along lattice directions, depicted in Fig.~\ref{Fig_5_3}(a)). This section investigates the existence of edge states and higher-order topological corner states of the kagome frame, and determines the eigenfrequencies of the corner states, edge states, and bulk states in the frequency spectrum.

	We first take a unit cell of the kagome frame and perform a Bloch-wave analysis, through which the dynamical equation is obtained as
	\begin{equation}	\label{eq5_15add}
		H^{\text{kagome}}_{\text{Bloch}} \lvert \theta \rangle=0,
	\end{equation}
	where $\lvert\theta\rangle = (\theta_\mathrm{A}, \theta_\mathrm{B}, \theta_\mathrm{C})^T$ denotes the rotation angles at the three rigid joints in one unit cell, and the Bloch dynamical matrix is
	\begin{equation}
		\label{eq5_16_add1}
		\small
		H^{\text{kagome}}_{\text{Bloch}} =
		\begin{bmatrix}
			2\sum\limits_{i=1}^2 \frac{B(\beta l_i)}{A(\beta l_i)} & -\frac{C(\beta l_1)}{A(\beta l_1)} - \frac{C(\beta l_2)}{A(\beta l_2)} \mathrm{e}^{-\mathrm{i}k_xL} &
			-\frac{C(\beta l_1)}{A(\beta l_1)} - \frac{C(\beta l_2)}{A(\beta l_2)} \mathrm{e}^{\mathrm{i}(-\frac{1}{2}k_x-\frac{\sqrt{3}}{2}k_y)L}
			\\
			-\frac{C(\beta l_1)}{A(\beta l_1)} - \frac{C(\beta l_2)}{A(\beta l_2)} \mathrm{e}^{\mathrm{i}k_xL} & 2\sum\limits_{i=1}^2 \frac{B(\beta l_i)}{A(\beta l_i)}
			&  -\frac{C(\beta l_1)}{A(\beta l_1)} - \frac{C(\beta l_2)}{A(\beta l_2)} \mathrm{e}^{\mathrm{i}(\frac{1}{2}k_x-\frac{\sqrt{3}}{2}k_y)L} \\
			-\frac{C(\beta l_1)}{A(\beta l_1)} - \frac{C(\beta l_2)}{A(\beta l_2)} \mathrm{e}^{\mathrm{i}(\frac{1}{2}k_x+\frac{\sqrt{3}}{2}k_y)L} &
			-\frac{C(\beta l_1)}{A(\beta l_1)} - \frac{C(\beta l_2)}{A(\beta l_2)} \mathrm{e}^{\mathrm{i}(-\frac{1}{2}k_x+\frac{\sqrt{3}}{2}k_y)L} &  2\sum\limits_{i=1}^2 \frac{B(\beta l_i)}{A(\beta l_i)}
		\end{bmatrix};
	\end{equation}
	or, in another form,
	\begin{equation}
		\label{eq5_16_add2}
		\small
		H^{\text{kagome}}_{\text{Bloch}} =
		\begin{bmatrix}
			\displaystyle 2\sum\limits_{i=1}^2 \frac{B(\beta l_i)}{A(\beta l_i)} & \displaystyle -\frac{C(\beta l_1)}{A(\beta l_1)} - \frac{C(\beta l_2)}{A(\beta l_2)} \mathrm{e}^{-\mathrm{i}k_1L} & \displaystyle -\frac{C(\beta l_1)}{A(\beta l_1)} - \frac{C(\beta l_2)}{A(\beta l_2)} \mathrm{e}^{-\mathrm{i}k_2L}
			\\[9pt]
			\displaystyle -\frac{C(\beta l_1)}{A(\beta l_1)} - \frac{C(\beta l_2)}{A(\beta l_2)} \mathrm{e}^{\mathrm{i}k_1L} & \displaystyle 2\sum\limits_{i=1}^2 \frac{B(\beta l_i)}{A(\beta l_i)} & \displaystyle -\frac{C(\beta l_1)}{A(\beta l_1)} - \frac{C(\beta l_2)}{A(\beta l_2)} \mathrm{e}^{\mathrm{i}(k_1-k_2)L}
			\\[9pt]
			\displaystyle -\frac{C(\beta l_1)}{A(\beta l_1)} - \frac{C(\beta l_2)}{A(\beta l_2)} \mathrm{e}^{\mathrm{i}k_2 L} & \displaystyle -\frac{C(\beta l_1)}{A(\beta l_1)} - \frac{C(\beta l_2)}{A(\beta l_2)} \mathrm{e}^{\mathrm{i}(k_2-k_1)L} & \displaystyle 2\sum\limits_{i=1}^2 \frac{B(\beta l_i)}{A(\beta l_i)}
		\end{bmatrix}.
	\end{equation}
	Here $k_1 = \boldsymbol{k} \cdot \boldsymbol{e}_1 = k_x$, and $k_2 = \boldsymbol{k} \cdot \boldsymbol{e}_2 = (1/2)k_x + (\sqrt{3}/2)k_y$. $k_1L$ denotes the phase difference between the joint rotational angles of the two neighboring unit cells on the same sublattice along the direction $\boldsymbol{e}_1$, and $k_2L$ denotes the phase difference along $\boldsymbol{e}_2$.

	Similarly, for a finite-sized kagome grid-like frame, the dynamical matrix is denoted as $H^{\text{kagome}}$, whose main-diagonal elements are $2\sum\limits_{i=1}^2 \frac{B(\beta l_i)}{A(\beta l_i)}$, and off-diagonal elements are $-\frac{C(\beta l_1)}{A(\beta l_1)}$ or $-\frac{C(\beta l_2)}{A(\beta l_2)}$ depending on the length of the beam segment corresponding to the entry position.

	\subsection{Higher-order topological corner states in kagome frames}
	Since the kagome lattice has generalized chiral symmetry \citep{kagome} (after the main-diagonal elements of the matrix $H_{\mathrm{Bloch}}^{\mathrm{kagome}}$ become identically zero by subtracting a scalar matrix), the frequencies of topological corner states in a finite kagome grid-like frame with fixed-end boundaries must satisfy
	\begin{equation}
		\label{eq5_16}
		2 \left[\frac{B(\beta_t l_1)}{A(\beta_t l_1)}+\frac{B(\beta_t l_2)}{A(\beta_t l_2)}\right] = 0.
	\end{equation}
	The above criterion can also be derived directly using an elementary approach, detailed in paragraphs that follow. Meanwhile, if and only if 
	\begin{equation}
		\label{eq5_17}
		\left \lvert\frac{C(\beta_t l_1)}{A(\beta_t l_1)}\right \rvert<\left \lvert\frac{C(\beta_t l_2)}{A(\beta_t l_2)}\right \rvert,
	\end{equation}
	topological corner states exist at $\beta_t$. Take an example kagome frame with $l_1=40\,\mathrm{mm}$, $l_2=50\,\mathrm{mm}$, whose eigenfrequency spectrum is depicted in Fig.~\ref{Fig_5_4}. The frequencies of topological corner states are marked with red arrows in Fig.~\ref{Fig_5_4}. As shown in Fig.~\ref{Fig_5_4}(b), the ordinates of the blue and orange dotted curves have opposite signs at frequencies $\beta_t^{(1)}$, $\beta_t^{(3)}$ and $\beta_t^{(5)}$, and hence the condition~\eqref{eq5_17} is satisfied. Although certain frequencies of topological corner states may lie within bulk bands, for example $\beta_t^{(1)}$, the topological corner states still exist. The corner modes obtained theoretically are shown in Fig.~\ref{Fig_k_c}.
