\begin{definition}
    \emph{Weak weak Kőnig's lemma} ($\mathsf{WWKL}$) is the following statement: for every tree $T \subseteq 2^{<\mathbb{N}}$ such that $\lim_n \frac{|\{ \sigma \in 2^n : \sigma \in T \}|}{2^n} >0$, there exists a path $f \in 2^\mathbb{N}$ through $T$.
\end{definition}

\begin{theorem}[\cite{Kucera1985} (p. 248). See \cite{DzhafarovMummert22} (Cor. 9.11.3)]
    $\mathsf{RCA}_0 \vdash \mathsf{WWKL} \leftrightarrow \forall X \ \exists Y \ Y$ is $1$-random over $X$.
\end{theorem}

\begin{definition}
    Recall that $A \subseteq^*B$ means that $A \setminus B$ is finite. The \emph{cohesive principle} ($\mathsf{COH}$) is the following statement: for every sequence $\langle R_i : i \in \omega \rangle$ of elements of $2^\omega$, there exists an infinite set $S \subseteq \omega$ such that, for each $i$, either $S \subseteq^* R_i$ or $S \subseteq^* \overline{R_i}$.
\end{definition}

\begin{theorem}[\cite{JockuschStephan93} (Thm. 2.1). See \cite{DzhafarovMummert22} (Thm. 8.4.13)] \label{JockuschStephen}
    $\mathsf{RCA}_0 \vdash \mathsf{COH} \leftrightarrow \forall X \ \exists Y \ Y' \gg X'$.
\end{theorem}

\begin{definition}
    The \emph{omitting partial types principle} ($\mathsf{OPT}$) is the following statement: for every complete theory $T$ and every listing $\langle \Gamma_i : i \in \omega \rangle$ of partial types of $T$, there exists a model $\mathcal{B}$ of $T$ omitting all nonprincipal $\Gamma_i$.
\end{definition}

\begin{theorem}[\cite{HirschfeldtShoreSlaman2009} (Thm. 5.7). See \cite{DzhafarovMummert22} (Thm. 9.10.12)]
   $\mathsf{RCA}_0 \vdash \mathsf{OPT} \leftrightarrow \forall X \ \exists Y \ Y$ is hyperimmune over $X$.
\end{theorem}

\begin{definition}
    For a theory $T$, a \emph{subenumeration} of the types of $T$ is a listing $\langle \Gamma_i : i \in \omega \rangle$ of partial types of $T$ such that, for each type $\Gamma$ of $T$, there is an $i$ such that $\Gamma$ and $\Gamma_i$ are equivalent. The \emph{atomic model theorem with subenumerable types} ($\mathsf{AST}$) is the following statement: for every complete theory $T$ and every subenumeration $\langle \Gamma_i : i \in \omega \rangle$ of the types of $T$, there exists an atomic model $\mathcal{B} \models T$.
\end{definition}

\begin{theorem}[\cite{HirschfeldtShoreSlaman2009} (Thm. 6.3). See \cite{DzhafarovMummert22} (Thm. 9.10.15)]
   $\mathsf{RCA}_0 \vdash \mathsf{AST} \leftrightarrow \forall X \ \exists Y \ Y \ngeq_\text{\emph{T}} X$.
\end{theorem}

\begin{definition}
    \emph{Rainbow Ramsey's theorem for pairs and two colors} ($\mathsf{RRT}^2_2$) is the following statement: for every $c : [\mathbb{N}]^2 \to \mathbb{N}$ such that $|c^{-1}(z)| \leq 2$ for each $z \in \mathbb{N}$, there exists an infinite set $R$ such that $c$ is injective on $[R]^2$.
\end{definition}

\begin{theorem}[Joseph S. Miller, unpublished. See \cite{DzhafarovMummert22} (Thm. 9.4.13)]
    $\mathsf{RCA}_0 \vdash \mathsf{RRT}^2_2 \leftrightarrow \forall X \ \exists Y \ Y \text{ is DNC over } X'$. 
\end{theorem}

\begin{definition}
    The \emph{sequential thin set theorem for singletons with finite errors} ($\mathsf{Seq}^*(\mathsf{TS}^1)$) is the following statement: for every sequence $\langle f_i : i \in \omega \rangle$ of functions $\mathbb{N} \to \mathbb{N}$, there exists an infinite set $H \subseteq \mathbb{N}$ such that, for each $i$, there is some $H_i =^* H$ with $f(H_i) \neq \mathbb{N}$.
\end{definition}

\begin{theorem}[\cite{Patey2016} (Lems. 6.1 and 6.2). See \cite{patey_lowness_avoidance} (Ex. 10.1.2)] \label{Patey16}
    $\mathsf{RCA}_0 \vdash \mathsf{Seq}^*(\mathsf{TS}^1) \leftrightarrow \forall X \ \exists Y \ Y' \text{ is DNC over } X'$.
\end{theorem}

\begin{definition}
    Say that a set $H \subseteq \mathbb{N}$ is \emph{homogeneous} for a string $\sigma \in 2^{< \mathbb{N}}$ if there exists some $c < 2$ such that, for all $i \in H$ with $i < |\sigma|$, we have $\sigma(i) = c$. We say that $H$ is \emph{homogeneous} for a tree $T \subseteq 2^{< \mathbb{N}}$ if the subtree $\{ \sigma \in T : H \text{ is homogeneous for } \sigma \}$ is infinite. \emph{Ramsey-type weak weak Kőnig's lemma} ($\mathsf{RWWKL}$) is the following statement: for every tree $T \subseteq 2^{< \mathbb{N}}$ such that $\lim_n \frac{|\{ \sigma \in 2^n : \sigma \in T \}|}{2^n} > 0$, there exists a set $H$ that is homogeneous for $T$.
\end{definition}

\begin{theorem}[\cite{BienvenuPateyShafer2017} (Thm. 3.4)]
    $\mathsf{RCA}_0 \vdash \mathsf{RWWKL} \leftrightarrow \forall X \ \exists Y \ Y \text{ is DNC over } X$.
\end{theorem}

\begin{definition}
    Say that a family of sets  $\vec{X} = \langle X_i : i \in \omega \rangle$ is \emph{non-trivial} if $X_i \neq \emptyset$ for some $i$. Say that $\vec{X}$ has the \emph{finite intersection property} if, for every nonempty finite set $F \subseteq \omega$, $\bigcap_{i \in F} X \neq \emptyset$. The \emph{finite intersection principle} ($\mathsf{FIP}$) is the following statement: for every nontrivial family of sets $\vec{X}$, there exists a subfamily $\vec{Y} \subseteq \vec{X}$ satisfying the finite intersection property that is maximal with respect to having this property.
\end{definition}

\begin{theorem}[\cite{CholakDowneyIgusa2017} (Thm. 1.6). See \cite{DzhafarovMummert22} (Thm. 9.10.23)]
    $\mathsf{RCA}_0 \vdash \mathsf{FIP} \leftrightarrow \forall X \ \exists Y \ Y$ is $1$-generic over $X$.
\end{theorem}

\section{Logical relationships between these principles}
\label{logrel}

In this section, we list all known implications and nonimplications between the principles listed above and provide a proof for one new implication. We also list all open questions regarding the logical relationships between these principles.

We write $\mathsf{P} \geqslant_\omega \mathsf{Q}$ if every $\omega$-model satisfying $\mathsf{P}$ also satisfies $\mathsf{Q}$. The following implications and nonimplications appear in the literature.
\begin{theorem}$ $
    \begin{enumerate}
        \item $\mathsf{RCA}_0 \vdash \mathsf{ACA} \to \mathsf{WKL}$ \emph{\cite{Friedman75}};
        \item $\mathsf{RCA}_0 \vdash \mathsf{ACA} \to \mathsf{RRT}^2_2$ \emph{\cite{Specker1971}, \cite{CsimaMileta2009}};
        \item $\mathsf{RCA}_0 \vdash \mathsf{ACA} \to \mathsf{COH}$ \emph{\cite{Specker1971}, [Jockusch and Lempp, unpublished], \cite{Mileti2004}};
        \item $\mathsf{RCA}_0 \vdash \mathsf{ACA} \to \mathsf{FIP}$ \emph{\cite{DzhafarovMummert2013}};
        \item $\mathsf{RCA}_0 \vdash \mathsf{WKL} \to \mathsf{WWKL}$ and $\mathsf{WWKL} \ngeqslant_\omega \mathsf{WKL}$ \emph{\cite{YuSimpson1990}};
        \item $\mathsf{RCA}_0 \vdash \mathsf{WWKL} \to  \mathsf{RWWKL}$ and $\mathsf{RWWKL} \ngeqslant_\omega \mathsf{WWKL}$ \emph{\cite{GiustoSimpson2000}, \cite{ASKHLS}, \cite{FloodTowsner2016}};
        \item $\mathsf{RCA}_0 \vdash \mathsf{RWWKL} \to \mathsf{AST}$ \emph{\cite{HirschfeldtShoreSlaman2009}, \cite{BienvenuPateyShafer2017}};
        \item $\mathsf{RCA}_0 \vdash \mathsf{RRT^2_2} \to \mathsf{RWWKL}$ and $\mathsf{RWWKL} \ngeqslant_\omega \mathsf{RRT}^2_2$ \emph{[Joseph S. Miller, unpublished], \cite{FloodTowsner2016}};
        \item $\mathsf{RCA}_0 \vdash \mathsf{COH} \to \mathsf{Seq}^*(\mathsf{TS}^1)$ and $\mathsf{Seq}^*(\mathsf{TS}^1) \ngeqslant_\omega \mathsf{COH}$ \emph{\cite{Patey2016}};
        \item $\mathsf{RCA}_0 \vdash \mathsf{COH} \to \mathsf{OPT}$ \emph{\cite{HirschfeldtShoreSlaman2009}};
        \item $\mathsf{RCA}_0 \vdash \mathsf{RRT}^2_2 \to \mathsf{OPT}$ \emph{\cite{CsimaMileta2009}, \cite{HirschfeldtShoreSlaman2009}};
        \item $\mathsf{RCA}_0 \vdash \mathsf{RRT^2_2} \to \mathsf{Seq}^*(\mathsf{TS}^1)$ \emph{\cite{Patey2016}};
        \item $\mathsf{RCA}_0 \vdash \mathsf{Seq}^*(\mathsf{TS}^1) \to \mathsf{AST}$ \emph{\cite{Patey2016}};
        \item $\mathsf{RCA}_0 \vdash \mathsf{FIP} \to \mathsf{OPT}$ and $\mathsf{OPT} \ngeqslant_\omega \mathsf{FIP}$ \emph{\cite{Sacks1963}, \cite{MillerMartin1968}, \cite{HirschfeldtShoreSlaman2009}, \cite{DzhafarovMummert2013}, \cite{CholakDowneyIgusa2017}};
        \item $\mathsf{RCA}_0 \vdash \mathsf{OPT} \to \mathsf{AST}$ \emph{\cite{HirschfeldtShoreSlaman2009}};
        \item $\mathsf{WKL} \ngeqslant_\omega \mathsf{Seq}^*(\mathsf{TS}^1)$ \emph{\cite{JockuschSoare72}};
        \item $\mathsf{WKL} \ngeqslant_\omega \mathsf{OPT}$ \emph{\cite{HirschfeldtShoreSlaman2009}};
        \item $\mathsf{RRT}^2_2 \ngeqslant_\omega \mathsf{WWKL}$ \emph{\cite{CsimaMileta2009}, \cite{Liu2015}};
        \item $\mathsf{COH} \ngeqslant_\omega \mathsf{RWWKL}$ \emph{\cite{HJKLS}, \cite{BienvenuPateyShafer2017}};
        \item $\mathsf{FIP} \ngeqslant_\omega \mathsf{COH}$ \emph{\cite{HirschfeldtShore2007}, \cite{HirschfeldtShoreSlaman2009}, \cite{DzhafarovMummert2013}};
        \item $\mathsf{FIP} \ngeqslant_\omega \mathsf{RWWKL}$ \emph{\cite{HirschfeldtShore2007}, \cite{Conidis2008}, \cite{HirschfeldtShoreSlaman2009}, \cite{DzhafarovMummert2013}, \cite{BienvenuPateyShafer2017}};
        \item $\mathsf{OPT} \ngeqslant_\omega \mathsf{Seq}^*(\mathsf{TS}^1)$  \emph{\cite{HirschfeldtShoreSlaman2009}, \cite{Patey2016}};
        \item $\mathsf{RCA}_0 \ngeqslant_\omega \mathsf{AST}$ \emph{\cite{HirschfeldtShoreSlaman2009}}.
    \end{enumerate}
\end{theorem}

We simultaneously strengthen Parts (10) and (11) above as follows.

\begin{proposition}
    $\mathsf{RCA}_0 \vdash \mathsf{Seq}^*(\mathsf{TS}^1) \to \mathsf{OPT}$.
\end{proposition}

\begin{proof}
    We gently modify the proof of Corollary 5.9 given in \cite{HirschfeldtShoreSlaman2009}. Let $s^e_n$ be the least $s$ such that $\Phi_e \upharpoonright (n +1)[s] \downarrow$, if one exists. For each $e$, we have $s_n^e \leq s_{n+1}^e$. Assume without loss of generality that $\Phi_e(n) \leq s_n^e$. Inductively define $r_0^e := s_0^e$ and $r_{n+1}^e := s^e_{\sum_{i=0}^n r_i^e}$. Define $R_n^e := \sum_{i = 0}^n r_i^e$.

    For each $e$, define $f_e : \mathbb{N} \to \mathbb{N}$ as 
    $$f_e(x):=
    \begin{cases}
        0 & 0 \leq x < R_0^e \\
        0 & R_0^e \leq x < R_1^e \\
        1 & R_1^e \leq x < R_2^e \\
        0 & R_2^e \leq x < R_3^e \\
        1 & R_3^e \leq x < R_4^e \\
        2 & R_4^e \leq x < R_5^e \\
        0 & R_5^e \leq x < R_6^e \\
        1 & R_6^e \leq x < R_7^e \\
        2 & R_7^e \leq x < R_8^e \\
        3 & R_8^e \leq x < R_9^e \\
        \vdots & \quad \quad \ \ \ \vdots
    \end{cases}$$
    if $\Phi_e$ is total and as
    $$f_e(x) :=
    \begin{cases}
        0 & 0 \leq x < R_0^e \\
        0 & R_0^e \leq x < R_1^e \\
        1 & R_1^e \leq x < R_2^e \\
        0 & R_2^e \leq x < R_3^e \\
        1 & R_3^e \leq x < R_4^e \\
        2 & R_4^e \leq x < R_5^e \\
        \vdots & \quad \quad \ \ \ \vdots \\
        0 & R_{n-1}^e \leq x
    \end{cases}
    $$
    if $n$ is the least number such that $r^e_n$ is undefined. The sequence $\langle f_e : e \in \omega \rangle$ is computable. Let $H$ be a $\mathsf{Seq}^*(\mathsf{TS}^1)$-solution to $\langle f_e : e \in \omega \rangle$. Let $g$ be the $H$-computable function defined by letting $g(n)$ be the least $m$ such that the sequence giving the characteristic function of $H$ has at least $n$ zeroes and at least $n$ ones among its first $m$ bits. We claim that $g$ is not dominated by any total computable function. Let $\Phi_e$ be total. Since $H$ is a $\mathsf{Seq}^*(\mathsf{TS}^1)$-solution to $\langle f_e : e \in \omega \rangle$, there exists some $k \in \mathbb{N}$ and some $H_0 =^* H$ such that $k \notin f_e(H_0)$. By the definition of $f_e$, for any $m$, we can find $y > x > m$ such that $x, y \in H$, there is no element of $H$ strictly between $x$ and $y$, and for some $n$ we have $x < \sum_{i=0}^n r_i^e$ and $y \geq \sum_{i=0}^{n+1} r_i^e$. Then $g(x) > y > r_{n+1}^e = s^e_{\sum_{i=0}^n r_i^e} \geq s_x^e \geq \Phi_e(x)$. Taking $m$ large enough, we see that $\Phi_e$ does not dominate $g$, which means that $H$ is hyperimmune.
\end{proof}


These implications and nonimplications leave open only the following questions about these principles.

\begin{question}$ $
    \begin{enumerate}
        \item Does $\mathsf{RCA}_0 \vdash \mathsf{RRT}^2_2 \to \mathsf{COH}$?
        \item Does $\mathsf{RCA}_0 \vdash \mathsf{RRT}^2_2 \to \mathsf{FIP}$?
        \item Does $\mathsf{RCA}_0 \vdash \mathsf{COH} \to \mathsf{FIP}$?
        \item Does $\mathsf{RCA}_0 \vdash \mathsf{Seq}^*(\mathsf{TS}^1) \to \mathsf{FIP}$?
        \item Does $\mathsf{RCA}_0 \vdash \mathsf{FIP} \to \mathsf{Seq}^*(\mathsf{TS}^1)$?
        \item Do any of the above possible implications hold over $\omega$-models?
    \end{enumerate}
\end{question}

\section{Iterated jumps of \texorpdfstring{$\mathsf{AST}$}{AST}, \texorpdfstring{$\mathsf{DNR}$}{DNR}, 
\texorpdfstring{$\mathsf{WWKL}$}{WWKL}, and \texorpdfstring{$\mathsf{WKL}$}{WKL}} 
\label{iterjumpssection}

\begin{definition} Fix $m \in \omega$.
    \begin{enumerate}
        \item Let $\mathsf{AST}^{(m)}$ denote the following statement: $\forall X \ \exists Y \ Y^{(m)} \nleq_\text{T} X^{(m)}$.
        \item Let $\mathsf{DNR}^{(m)}$ denote the following statement: $\forall X \ \exists Y \ Y^{(m)} \ \text{DNC over } X^{(m)}$.
        \item Let $\mathsf{WWKL}^{(m)}$ denote the following statement: $\forall X \ \exists Y \ Y^{(m)} \text{ computes a $1$-random over } X^{(m)}$.
        \item Let $\mathsf{WKL}^{(m)}$ denote the following statement: $\forall X \ \exists Y \ Y^{(m)} \gg X^{(m)}$.
    \end{enumerate}    
\end{definition}
We include the word ``computes'' in the definition of $\mathsf{WWKL}^{(m)}$ since \emph{computing} a $1$-random is a property of degrees (whereas \emph{being} a $1$-random is a property of sets). We are already aquatinted with these principles in the case where $m = 0$:
\begin{itemize}
    \item $\mathsf{AST}^{(0)} \equiv_{\mathsf{RCA}_0} \mathsf{AST}$,
    \item $\mathsf{DNR}^{(0)} \equiv_{\mathsf{RCA}_0} \mathsf{RWWKL}$,
    \item $\mathsf{WWKL}^{(0)} \equiv_{\mathsf{RCA}_0} \mathsf{WWKL}$,
    \item $\mathsf{WKL}^{(0)} \equiv_{\mathsf{RCA}_0} \mathsf{WKL}$.
\end{itemize}
Additionally, we have seen two of these principles in the case where $m = 1$:
\begin{itemize}
    \item $\mathsf{DNR}^{(1)} \equiv_{\mathsf{RCA}_0} \mathsf{Seq}^*(\mathsf{TS})$,
    \item $\mathsf{WKL}^{(1)} \equiv_{\mathsf{RCA}_0} \mathsf{COH}$.
\end{itemize}
By Post's theorem, $\mathsf{AST}^{(m)}$ asserts that, for every $\Delta^0_{m+1}$-approximation of a complete theory and every $\Delta^0_{m+1}$-approximation of a subenumeration of its types, there exists a $\Delta^0_{m+1}$-approximation of an atomic model of the theory. $\mathsf{DNR}^{(m)}$, $\mathsf{WWKL}^{(m)}$, and $\mathsf{WKL}^{(m)}$ have similar interpretations.

The halting set is of PA degree. By \cite{MartinLof66}, every set that is of PA degree computes a $1$-random. By \cite{GiustoSimpson2000}, every $1$-random computes a DNC function. Every DNC set is in particular noncomputable. Since all of these results relativize, the following implications hold.

\begin{proposition}
    Let $m \in \mathbb{N}$. We have
    \begin{itemize}
        \item $\mathsf{RCA}_0 \vdash \mathsf{ACA} \to \mathsf{WKL}^{(m)}$,
        \item $\mathsf{RCA}_0 \vdash \mathsf{WKL}^{(m)} \to \mathsf{WWKL}^{(m)}$,
        \item $\mathsf{RCA}_0 \vdash \mathsf{WWKL}^{(m)} \to \mathsf{DNR}^{(m)}$, and
        \item $\mathsf{RCA}_0 \vdash \mathsf{DNR}^{(m)} \to \mathsf{AST}^{(m)}$.
    \end{itemize}
\end{proposition}

Since $Y \leq_\text{T} X$ implies $Y' \leq_\text{T} X'$, the following implication also holds.

\begin{proposition} Let $m < n$. We have $\mathsf{RCA}_0 \vdash \mathsf{AST}^{(n)} \to \mathsf{AST}^{(m)}$.
\end{proposition}

The following separations complete our understanding of the logical relationships between these principles, which are summarized above in Figure \ref{fig:iterjumps}.

\begin{theorem} \label{DNRvWKL}
    Let $m \in \mathbb{N}$. We have $\mathsf{WWKL}^{(m)} \ngeqslant_\omega \mathsf{WKL}^{(m)}$
\end{theorem}

\begin{theorem} \label{DNRvWWKL}
    Let $m \in \mathbb{N}$. We have $\mathsf{DNR}^{(m)} \ngeqslant_\omega \mathsf{WWKL}^{(m)}$.
\end{theorem}

\begin{theorem}
\label{WKLvAST}
    Let $m < n$. We have $\mathsf{WKL}^{(m)} \ngeqslant_\omega \mathsf{AST}^{(n)}$.
\end{theorem}

\begin{theorem}
\label{WKLvDNR}
    Let $m < n$. We have $\mathsf{WKL}^{(n)} \ngeqslant_\omega \mathsf{DNR}^{(m)}$.
\end{theorem}

\section{Proofs of separations}
\label{proofssection}

\subsection{Proof that \texorpdfstring{$\mathsf{WWKL}^{(m)} \ngeqslant_\omega \mathsf{WKL}^{(m)}$}{WWKL(m)⩾̸ω WKL(m)}}

The following four degree-theoretic facts (the first two of which must be used in their relativized forms) can be directly combined to prove this separation.

\begin{theorem}[\cite{MartinLof66} (p. 605). See \cite{DzhafarovMummert22} (Cor. 9.4.7)] \label{kuceratheorem}
    For any $D$, there exists a $\Pi^0_1(D)$ class every element of which is $1$-random over $D$.
\end{theorem}

\begin{theorem}[Cone avoidance basis theorem; \cite{JockuschSoare72} (Thm. 2.5). See \cite{DzhafarovMummert22} (Thm. 2.8.23)] \label{coneavoidancebasistheorem}
    For any $D$, any $C \nleq_\text{T} D$, and any $\Pi^0_1(D)$ class $\mathcal{C}$, there exists a $G \in \mathcal{C}$ such that $C \nleq_\text{T} G$.  
\end{theorem}

Recall that $X$ is \emph{$m$-random} over $D$ if $X$ is $1$-random over $D^{(m)}$.

\begin{theorem}[Folklore. See \cite{DzhafarovMummert22} (Thm. 9.4.18)] \label{folklore}
    Let $X$ be an $m$-random set. There exists an Turing ideal $\mathcal{S}$ with the following properties.
    \begin{enumerate}
        \item Every set in $\mathcal{S}$ is $X$-computable.
        \item For each $Y \in \mathcal{S}$, there is a $Y^* \in \mathcal{S}$ which is $m$-random relative to $Y$.
    \end{enumerate}
\end{theorem}

\begin{theorem}[\cite{Stephan2006} (p. 344). See \cite{DzhafarovMummert22} (Thm. 9.11.5)] \label{stephanstheorem}
    If $X$ is PA over $\emptyset^{(m)}$ and $X$ is $(m+1)$-random, then $X \geq_\text{T} \emptyset^{(m+1)}$.
\end{theorem}

\begin{proof}[Proof of Theorem \ref{DNRvWKL}]
    By Theorems \ref{kuceratheorem} and \ref{coneavoidancebasistheorem}, there exists a $G$ that is $1$-random over $\emptyset^{(m)}$  (i.e., that is $(m+1)$-random) but which does not compute $\emptyset^{(m+1)}$. Let $\mathcal{S}$ be the Turing ideal guaranteed by Theorem 3.3 with $X$ taken to be $G$. Since, for each $Y^*$, $(Y^*)^{(m)}$ computes $Y^*$, this $\mathcal{S}$ is the second-order part of an $\omega$-model $\mathcal{S}$ of $\mathsf{WWKL}^{(m)}$ in which every set is $G$-computable. By Theorem \ref{stephanstheorem}, $G$ is not PA over $\emptyset^{(m)}$, which, since every set in $\mathcal{S}$ is computable in $G$, implies that $\mathcal{S}$ does not satisfy $\mathsf{WKL}^{(m)}$.
\end{proof}

\subsection{Proof that \texorpdfstring{$\mathsf{WKL}^{(m)} \ngeqslant_\omega \mathsf{AST}^{(n)}$}{WKL(m)⩾̸ω AST(n)} for \texorpdfstring{$m < n$}{m<n}}

Our proofs of the remaining three separations leverage the following abstract framework, which was first isolated in \cite{patey:tel-01888675}, but the idea underlying which had previously appeared in \cite{lst}.

An \emph{instance-solution problem} is a function $\mathsf{P} : \mathcal{P}(\omega) \to \mathcal{P}(\mathcal{P}(\omega))$. We refer to sets $X \in \mathcal{P}(\omega)$ as \emph{instances of $\mathsf{P}$} and sets $Y \in \mathsf{P}(X)$ as \emph{solutions to $X$}. Any mathematical principle of the form ``for all...there exists...'' can be regarded as an instance-solution problem in a natural way.

\begin{definition}
    A class $\mathcal{W} \subseteq 2^\omega$ is called a \emph{weakness property} if it is downward closed under Turing reduction. An instance-solution problem $\mathsf{P}$ is said to \emph{preserve} a weakness property $\mathcal{W}$ if, for every $Z \in \mathcal{W}$ and every $Z$-computable instance $X \in \mathcal{W}$, there is a solution $Y$ to $X$ such that $Z \oplus Y \in \mathcal{W}$.
\end{definition}

\begin{lemma}[\cite{patey:tel-01888675} (Lem. 3.4.2). See \cite{DzhafarovMummert22} (Thm. 4.6.13)] \label{separation-thm}
    Let $\mathsf{P}$ and $\mathsf{Q}$ be instance-solution problems and $\mathcal{W}$ be a weakness property. If $\mathsf{P}$ preserves $\mathcal{W}$ and $\mathsf{Q}$ does not, then $\mathsf{P} \ngeqslant_\omega \mathsf{Q}$.
\end{lemma}

To prove Theorem \ref{WKLvAST}, we combine the low basis theorem, which states that there exists a set of PA degree whose jump is as weak as possible, with Friedberg's jump inversion theorem.

\begin{theorem}[Low basis theorem; \cite{JockuschSoare72} (Thm. 2.1). See \cite{DzhafarovMummert22} (Thm. 2.8.18)]
    For any $D$, there exists a $G$ such that $G \gg D$ and $G' \equiv_\text{\emph{T}} D'$.
\end{theorem}

\begin{theorem}[Jump inversion theorem; \cite{Friedberg57} (p. 159). See \cite{Soare16} (Thm. 6.4.4)]
    For any $D$ and any $A \geq_\text{\emph{T}} D'$, there exists a $G \geq_\text{\emph{T}} D$ such that $G' \equiv_\text{\emph{T}} A$.
\end{theorem}

\begin{proof}[Proof of Theorem \ref{WKLvAST}]
    Let $\mathcal{W} = \{ S : S^{(n)} \not\gg \emptyset^{(n)} \}$. By definition, $\mathsf{WKL}^{(n)}$ does not preserve $\mathcal{W}$. Therefore, by Lemma \ref{separation-thm}, it will suffice to prove that $\mathsf{WKL}^{(m)}$ preserves $\mathcal{W}$. Let $Z \in \mathcal{W}$ and $X \leq_\text{T} Z$. We must find a $\mathsf{WKL}^{(m)}$-solution $Y$ to $X$ such that $Z \oplus Y \in \mathcal{W}$. By the low basis theorem, there exists some $G \gg Z^{(m)}$ such that $G' \equiv_\text{T} Z^{(m+1)}$. Using Friedberg's jump inversion theorem $m$ times (relativized to each of $Z^{(m-1)}, Z^{(m-2)}, \dots Z$ in that order), we can find a $Y \geq_\text{T} Z$ such that $Y^{(m)} \equiv_\text{T} G$. Since $G \gg Z^{(m)}$ and $Z^{(m)} \geq_\text{T} X^{(m)}$, we have $Y^{(m)} \gg X^{(m)}$, as needed. Additionally, since $Y \geq_\text{T}$ and $Y^{(m+1)} \equiv_\text{T} Z^{(m+1)}$, we have $(Z \oplus Y)^{(n)} \equiv_\text{T} Y^{(n)} \equiv_\text{T} Z^{(n)}$. Since $Z^{(n)} \not\gg \emptyset^{(n)}$, it follows that $Y^{(n)} \not\gg \emptyset^{(n)}$, as needed.
\end{proof}

\subsection{Proof that \texorpdfstring{$\mathsf{DNR}^{(m)} \ngeqslant_\omega \mathsf{WWKL}^{(m)}$}{DNR(m)⩾̸ω WWKL(m)}}

Recall that a function $f : \omega \to \omega$ is called DNC if $\Phi_e(e) \downarrow$ implies that $f(e) \neq \Phi_e(e)$. A Turing degree is called DNC if it computes a DNC function, and both of these definitions relativize to an arbitrary degree $D$ in the usual way. In \cite{KhanMiller17}, Khan and Miller provide a proof of $\mathsf{DNR} \ngeqslant_\omega \mathsf{WWKL}$ that, unlike \cite{ASKHLS}'s original proof, uses Patey's separation framework. Both \cite{KhanMiller17}'s proof and the original actually do more than separate $\mathsf{DNR}$ from $\mathsf{WWKL}$; they separate $\mathsf{DNR}$ from, for any computable function $h$, a principle called $h\text{-}\mathsf{DNR}$.

\begin{definition}
    For any computable function $h : \omega \to \omega$, we say that a function $g$ is $h\text{-DNC}$ over $D$ if $g$ is $\text{DNC}$ over $D$ and $g(x) < h(x)$ for all $x$. We say that a degree $G$ is $h\text{-DNC}$ over $D$ if $G$ computes a function that is $h\text{-DNC}$ over $D$.
\end{definition}

\begin{definition}
    For any computable function $h: \omega \to \omega$, let $h\text{-}\mathsf{DNR}^{(m)}$ denote the following statement: $\forall X \ \exists Y \ Y^{(m)} \ h\text{-DNC over} \ X^{(m)}$.
\end{definition}

\begin{theorem}[\cite{ASKHLS} (Thm. 1.4)]
    Let $h(x) = 2^x$. We have $\mathsf{RCA}_0 \vdash \mathsf{WWKL} \to h\text{-}\mathsf{DNR}$.
\end{theorem}

Thus, in order to separate a given principle from $\mathsf{WWKL}$, it suffices to separate the principle from $h\text{-}\mathsf{DNR}$ (in the special case where $h(x) = 2^x$). In light of Patey's framework, the following theorem separates $\mathsf{DNR}$ from $h\text{-}\mathsf{DNR}$ and thus from $\mathsf{WWKL}$.

\begin{theorem}[\cite{KhanMiller17} (Thm. 3.7)]
    For any computable function $h$ and any $Z$ such that $Z$ is not $h\text{-DNC}$, there exists a $G$ such that $Z \oplus G$ is not $h\text{-DNC}$ and $G$ is $\text{DNC}$. 
\end{theorem}

The two theorems above immediately relativize as follows.

\begin{theorem}[\cite{ASKHLS} (Thm. 1.4)]
\label{WWKLtohDNR}
    Let $h(x) = 2^x$. We have $\mathsf{RCA}_0 \vdash \mathsf{WWKL}^{(m)} \to h\text{-}\mathsf{DNR}^{(m)}$.
\end{theorem}

\begin{theorem}[\cite{KhanMiller17} (Thm. 3.7)]
\label{KMsepRelativized}
    For any computable function $h$, any $D$, and any $Z$ such that $Z$ is not $h\text{-DNC}$ over $D$, there exists a $G$ such that $Z \oplus G$ is not $h\text{-DNC}$ over $D$ and $G$ is $\text{DNC}$ over $D$. 
\end{theorem}

In order to prove our separation, we generalize the theorem above to the $m$th jump.

\begin{theorem}
\label{KMmthjumpgen}
    For any computable function $h$, any $D$, and any $Z$ such that $Z^{(m)}$ is not $h\text{-DNC}$ over $D^{(m)}$, there exists a $G$ such that $(Z \oplus G)^{(m)}$ is not $h\text{-DNC}$ over $D^{(m)}$ and $G^{(m)}$ is $\text{DNC}$ over $D^{(m)}$. 
\end{theorem}

If it were true that $(Z \oplus G)^{(m)} \equiv_\text{T} Z^{(m)} \oplus G^{(m)}$ for all $Z$ and $G$, then Theorem \ref{KMmthjumpgen} would follow immediately from Theorem \ref{KMsepRelativized}. However, this is not the case, so a bit more work is required.

\begin{proof}[Proof of Theorem \ref{KMmthjumpgen}]
    We prove this by induction on $m$. The base case is precisely Theorem \ref{KMsepRelativized}. In the inductive case, assume that, for every $D$ and every $Z$ with $Z^{(m-1)}$ not $h$-DNC over $D^{(m-1)}$, there exists some $G$ such that $(Z \oplus G)^{(m-1)}$ is not $h$-DNC over $D$ and $G^m$ is DNC over $D$. For simplicity, we will prove the inductive step in the case where $D = \emptyset$; the argument easily relativizes. Fix any $Z$ with $Z^{(m)}$ not $h$-DNC over $\emptyset^{(m)}$. By the inductive hypothesis (take with $D = \emptyset'$ and $Z = Z'$), there exists some $G_0$ such that $(Z' \oplus G_0)^{(m-1)}$ is not $h$-DNC over $\emptyset^{(m)}$ and $G_0$ is DNC over $\emptyset^{(m)}$. To produce the requisite $G$, we will use a forcing notion that will appear twice more in this paper and is suitable for producing sets that are computationally weak (in some sense) but whose jumps compute some fixed object. Our conditions are pairs $(g,k)$ where $g \subseteq \omega^2 \to 2$ is a finite partial function and $k \in \omega$, and the interpretation $[g,k]$ of a condition is the class of all partial functions $h \subseteq \omega^2 \to 2$ such that
    \begin{itemize}
        \item $g \subseteq h$, and
        \item for all $(x,y) \in \text{dom}(h) \setminus \text{dom}(g)$, if $x < k$, then $h(x,y) = G_0 (x)$.
    \end{itemize}
    If $(h, \ell)$ is a condition such that $h \in [g,k]$ and $\ell \geq k$, we say that $(h, \ell)$ extends $(g,k)$ and we denote this $(h, \ell) \leqslant (g,k)$. Every filter $\mathcal{F}$ for this notion of forcing induces a function $f_\mathcal{F} := \bigcup \{ g : (g,k) \in \mathcal{F} \}$, and, if $\mathcal{F}$ is sufficiently generic, then $f_\mathcal{F}$ is total and $\lim_x f_\mathcal{F}(x,y) = G_0$, which implies that $f'_\mathcal{F} \geq_\text{T} G_0$ and thus that $f_\mathcal{F}^{(m)} \geq_\text{T} G_0^{(m-1)}$ is DNC over $\emptyset^{(m)}$. Thus, all that remains to show is that $(Z \oplus f_\mathcal{F})^{(m)}$ is not $h$-DNC over $\emptyset^{(m)}$.

    \begin{definition}
    \label{forcingquestion}
        Fix a condition $(g,k)$ and a $\Sigma^0_i(Z)$ formula $\varphi(f) \equiv \exists x \psi(f,x)$ (where $\psi(f,x)$ is a $\Pi^0_{i-1}(Z)$ formula).
        \begin{enumerate}
            \item If $i = 1$, let $(g,k) \ {?}{\vdash} \ \varphi(f)$ hold if there is some $x$ and some $(h,\ell) \leqslant (g,k)$ such that $\psi(g,x)$ holds.
            \item If $i > 1$, let $(g,k) \ {?}{\vdash} \ \varphi(f)$ hold if there is some $x$ and some $(h,\ell) \leqslant (g,k)$ such that $(h,\ell) \ {?}{\nvdash} \neg \psi(h,x)$.
        \end{enumerate}
        For a $\Pi^0_i(Z)$ formula $\varphi(f)$, define $(g,k) \ {?}{\vdash} \ \varphi(f)$ to hold if $(g,k) \ {?}{\nvdash} \ \neg \varphi(f)$.
    \end{definition}
    The statement $(g,k) \ {?}{\vdash} \ \varphi(g)$ is $\Sigma^0_i(Z \oplus G_0)$ (or, equivalently, $\Sigma^0_1((Z \oplus G_0)^{(i-1)})$). By definition, for any $(g,k)$ and any $\varphi(f)$, either $(g,k) \ {?}{\vdash} \ \varphi(f)$ holds or $(g,k) \ {?}{\vdash} \ \neg \varphi(f)$ holds. Thus, this ``forcing question'' is a complexity-preserving completion of the forcing relation. It bears the following further relationship to the forcing relation.

    \begin{claim} Let $\varphi(f)$ be a $\Sigma^0_i$ formula.
        \begin{enumerate}
            \item \label{claim part 1} If $(g,k) \ {?}{\vdash} \ \varphi(f)$, then there is an extension $(h, \ell) \succeq (g,k)$ forcing $\varphi(f)$.
            \item \label{claim part 2} If $(g,k) \ {?}{\nvdash} \ \varphi(f)$, then $(g,k)$ forces $\neg \varphi(f)$.
        \end{enumerate}
    \end{claim}
    \begin{proof}[Proof of Claim]
    We prove parts (1) and (2) simultaneously by induction on $i$. In the base case, assume that $\varphi(f) \equiv \exists x \psi(f,x)$ where $\psi$ is $\Delta^0_0(Z)$. Towards proving part (1), assume that $(g,k) \ {?}{\vdash} \varphi(f)$. Take $x_0$ and $(h_0, \ell_0) \leqslant (g,k)$ to witness this fact. The condition $(h_0, \ell_0)$ forces $\varphi(f)$, as needed. Towards proving part (2), assume that $(g,k)$ does not force $\neg \varphi(f)$. By the definition of forcing, there exists some $(h,\ell) \leqslant (g,k)$ and some $x$ such that $\psi(h,k)$ holds. By the definition of ${?}{\vdash}$, it follows that $(g,k) \ {?}{\vdash} \ \varphi(f)$, as needed.

    In the inductive case, let $i > 1$ and assume that $\varphi(f) \equiv \exists x \psi(f,x)$, where $\psi$ is $\Pi^0_{i-1}(Z)$. Towards proving part (1), assume that $(g,k) \ {?}{\vdash} \ \varphi(f)$. Take $x_0$ and $(h_0, \ell_0) \leqslant (g,k)$ to witness this fact. By part (2) of the inductive hypothesis, $(h_0, \ell_0)$ forces $\varphi(f)$, as needed. Towards proving part (2), assume that $(g,k) \ {?}{\nvdash} \ \varphi(f)$. By the definition of the forcing question, it follows that, for every $x$ and every $(h_0,\ell_0) \leqslant (g,k)$, we have $(h_0,\ell_0) \ {?}{\nvdash} \psi(f,x)$. By the induction hypothesis, it follows that, for every $x$ and every $(h_0,\ell_0) \leqslant (g,k)$, there is some $(h,\ell) \leqslant (h_0, \ell_0)$ forcing $\neg \psi(f,x)$. Therefore, for each sufficiently generic filter $\mathcal{F}$ containing $(g,k)$ and each $x$, there is some $(h, \ell) \in \mathcal{F}$ forcing $\neg \psi(f, x)$. Thus, $(g,k)$ forces $\neg \varphi(f)$.
    \end{proof}

    To ensure that $\Phi_e^{(Z \oplus f)^{(m)}}$ is not an $h$-DNC function over $\emptyset^{(m)}$, we must find, for each condition $(g,k)$ and each index $e$, an extension $(h, \ell) \leqslant (g,k)$ forcing, for some $x$, either $\Phi_e^{(Z \oplus f)^{(m)}} (x) \uparrow$, $\Phi_e^{(Z \oplus f)^{(m)}} (x) \downarrow = v$ for some $v \geq h(x)$, or $\Phi_e^{(Z \oplus f)^{(m)}}(x) \downarrow = \Phi_x^{\emptyset^{(m)}}(x)$. Fix a condition $(g,k)$, and define $$\mathcal{U} := \{ (x,v) \in \omega^2 : (g,k) \ {?}{\vdash} \ \varphi(f) \},$$ where $\varphi(f)$ is some $\Sigma^0_{m+1}(Z)$ formula asserting that $\Phi_e^{(Z \oplus f)^{(m)}}(x) \downarrow = v$. Since the innermost quantifier in the predicate defining $\mathcal{U}$ only quantifies over finitely much information about $G_0$, the set $\mathcal{U}$ is $\Sigma^0_1((Z' \oplus G_0)^{(m-1)})$. There are three cases:
    \begin{itemize}
        \item Case 1a: There is some $x$ such that $(x, \Phi_x^{\emptyset^{(m)}}) \in \mathcal{U}$. In this case, by part (1) of our Claim, we can find an extension $(h, \ell) \leqslant (g,k)$ forcing $\Phi_e^{(Z \oplus f)^{(m)}}(x) \downarrow = \Phi_x^{\emptyset^{(m)}}(x)$.
        \item Case 1b: There is some $x$ and some $v \geq h(x)$ such that $(x, v) \in \mathcal{U}$. In this case, by part (1) of our Claim, we can find an extension $(h, \ell) \leqslant (g,k)$ forcing $\Phi_e^{(Z \oplus f)^{(m)}}(x) \downarrow = v$.
        \item Case 2: There is some $x$ such that, for each $v \in \omega$, $(x, v) \notin \mathcal{U}$. In this case, by part (2) of our Claim, $(g,k)$ itself forces $\Phi_e^{(Z \oplus f)^{(m)}}(x) \uparrow$.
        \item Case 3: Neither of the above holds. In this case, define $\mathcal{U}_0$ to be the set of pairs $(x,v)$ such that $(x,v) \in \mathcal{U}$ and $(x,w) \notin \mathcal{U}$ for all $w < v$. This $\mathcal{U}_0$ is computable in $\mathcal{U}$, and is therefore $\Sigma^0_1((Z' \oplus G_0)^{(m-1)})$. This $\mathcal{U}_0$ is also the graph of a function that is $h$-DNC over $\emptyset^{(m)}$, contradicting our assumption that $(Z' \oplus G_0)^{(m-1)}$ is not $h$-DNC over $\emptyset^{(m)}$.
    \end{itemize}
\end{proof}

\begin{proof}[Proof of Theorem \ref{DNRvWWKL}]
    Let $h(x) = 2^x$ and $\mathcal{W} = \{ S : S^{(m)} \text{ is not $h$-DNC over } \emptyset^{(m)} \}$. By Theorem \ref{WWKLtohDNR}, $\mathsf{WWKL}^{(m)}$ does not preserve $\mathcal{W}$. So, by Lemma \ref{separation-thm}, it will suffice to prove that $\mathsf{DNR}^{(m)}$ preserves $\mathcal{W}$. Let $Z \in \mathcal{W}$ and $X \leq_\text{T} Z$. We must find a $\mathsf{DNR}^{(m)}$-solution $Y$ to $X$ such that $Z \oplus Y \in \mathcal{W}$. By Theorem \ref{KMmthjumpgen}, there exists some $Y$ such that $Y^{(m)}$ is DNC over $X^{(m)}$ but $(X \oplus Y)^{(m)}$ is not $h$-DNC over $\emptyset^{(m)}$, as needed.
\end{proof}

\subsection{Proof that \texorpdfstring{$\mathsf{WKL}^{(n)} \ngeqslant \mathsf{DNR}^{(m)}$}{WKL(n)⩾̸ω DNR(m)} for \texorpdfstring{$m < n$}{m < n}}

To prove Theorem \ref{WKLvDNR}, we generalize a certain antithesis to the low basis theorem identified by Levy Patey. While the low basis theorem asserts the existence of a set of PA degree whose jump is as weak as possible, the following theorem asserts the existence of a set not even of DNC degree whose jump is arbitrarily strong.

\begin{theorem}[\cite{patey_lowness_avoidance} (Ex. 5.8.6)]
    For any $D$ and any $A$, there exists a set $G \geq_\text{\emph{T}} D$ such that $G$ is not DNC over $D$ and $G' \geq_\text{\emph{T}} A$.
\end{theorem}

A slightly more relativized version of this theorem, which is implicit in \cite{patey_lowness_avoidance}, asserts that we can find a $G$ that is still not of DNC degree even when combined with some fixed set that is also not of DNC degree.

\begin{theorem}[\cite{patey_lowness_avoidance} (Ex. 5.8.6)] \label{antithesis}
    For any $D$, any $A$, and any $Z$ not DNC over $D$, there exists a $G$ such that $(Z \oplus G)$ is not DNC over $D$ and $G' \geq_\text{\emph{T}} A$.
\end{theorem}

In order to prove Theorem \ref{WKLvDNR}, we generalize the above to the $m$th jump.

\begin{theorem} \label{mthjumpgeneralization}
    For any $D$, any $Z$ such that $Z^{(m)}$ is not DNC over $D^{(m)}$, and any $A$, there exists a $G$ such that $(Z \oplus G)^{(m)}$ is not DNC over $D^{(m)}$ and $G^{(m+1)} \geq_\text{\emph{T}} A$.
\end{theorem}

\begin{proof}
    We prove this by induction on $m$. The base case is precisely Theorem \ref{antithesis}. Since Theorem \ref{antithesis} only appears as an exercise in \cite{patey_lowness_avoidance}, we include a proof here. For simplicity, assume that $D = \emptyset$. (The proof easily relativizes.) Take any $Z$ not DNC over $\emptyset$ and any $A$. To construct the $G$ that we need, we will use a notion of forcing identical to that used in our proof of \ref{KMmthjumpgen}, but with $G_0$ replaced with $A$. Namely, our conditions are pairs $(g,k)$, where $g \subseteq \omega^2 \to 2$ is a finite partial function and $k \in \omega$. The interpretation $[g,k]$ of a condition is the class of all partial functions $h \subseteq \omega^2 \to 2$ such that
    \begin{itemize}
        \item $g \subseteq h$,
        \item for all $(x,y) \in \text{dom}(h) \setminus \text{dom}(g)$, if $x < k$, then $h(x,y) = A(x)$.
    \end{itemize}
    If $(h,\ell)$ is a condition such that $h \in [g,k]$ and $\ell \geq k$, we say that $(h,\ell)$ extends $(g,k)$, and we denote this $(h, \ell) \leqslant (g,k)$. Every filter $\mathcal{F}$ for this notion of forcing induces a function $f_\mathcal{F} := \bigcup \{ g : (g,k) \in \mathcal{F} \}$. If $\mathcal{F}$ is sufficiently generic, then $f_\mathcal{F}$ is total and $\lim_x f_\mathcal{F}(x,y) = A$, which implies, by the limit lemma, that $f'_\mathcal{F} \geq_\text{T} A$. Thus, all that remains to show is that $Z \oplus f_\mathcal{F}$ is not DNC. To do this, for each condition $(g,k)$ and each index $e$, we must find an extension $(h,\ell) \geqslant (g,k)$ forcing either $\Phi_e^{Z \oplus f}(x) \uparrow$ or $\Phi_e^{Z \oplus f}(x)$ for some $x$. (This ensures that $\Phi_e^{Z \oplus f}$ is not a DNC function.) Fix a condition $(g,k)$, and define $$\mathcal{U} := \{ (x,v) \in \omega^2 : \exists (h, \ell) \leqslant (g,k) \ \Phi_e^{Z \oplus h}(x)\downarrow = v\}.$$
    Note that $\mathcal{U}$ is $\Sigma^0_1(Z)$. There are three cases:
    \begin{itemize}
        \item Case 1: There is some $x$ such that $(x, \Phi_x(x)) \in \mathcal{U}$. In this case, take $(h, \ell) \leqslant (g,k)$ to be an extension witnessing that $(x, \Phi_x(x)) \in \mathcal{U}$. This $(h,\ell)$ is an extension forcing $\Phi_e^{Z \oplus f}(x) \downarrow = \Phi_x(x)$.
        \item Case 2: There is some $x$ such that, for each $v \in \omega$, $(x,v) \in \mathcal{U}$. In this case, $(g,k)$ itself forces $\Phi_e^{Z \oplus f}(x) \uparrow$.
        \item Case 3: Neither of the above holds. In this case, define $\mathcal{U}_0$ to be the set of pairs $(x,v)$ such that $(x,v) \in \mathcal{U}$ and $(x,w) \notin \mathcal{U}$ for all $w < v$. This $\mathcal{U}_0$ is computable in $\mathcal{U}$, and is therefore $\Sigma^0_1(Z)$, since our definition of $\mathcal{U}$ only uses the first $k$ bits of $A$. This $\mathcal{U}_0$ is also the graph of a DNC function, contradicting our assumption that $Z$ is not DNC.
    \end{itemize}

    In the inductive case, assume that, for every $D$, every $Z$ with $Z^{(m-1)}$ not DNC over $D^{(m-1)}$, and every $A$, there exists a $G$ such that $(Z \oplus G)^{(m-1)}$ is not DNC over $D^{(m-1)}$ and $G^{(m)} \geq_\text{T} A$. As above, we will prove the inductive step in the case where $D = \emptyset$, and the argument easily relativizes. Fix any $Z$ with $Z^{(m)}$ not DNC over $\emptyset^{(m)}$ and any $A$. By the inductive hypothesis (taken with $D = \emptyset'$ and $Z = Z'$), there exists some $G_0$ such that $(Z' \oplus G_0)^{(m-1)}$ is not DNC over $\emptyset^{(m)}$ and $G_0^{(m)} \geq_\text{T} A$. To produce the requisite $G$, we will use our favorite notion of forcing a third time, as promised. Our conditions are pairs $(g,k)$ where $g \subseteq \omega^2 \to 2$ is a finite partial function and $k \in \omega$, and the interpretation $[g,k]$ of a condition is the class of all partial functions $h \subseteq \omega^2 \to 2$ such that
    \begin{itemize}
        \item $g \subseteq h$,
        \item for all $(x,y) \in \text{dom}(h) \setminus \text{dom}(g)$, if $x < k$, then $h(x,y) = G_0(x)$.
    \end{itemize}
    If $(h,\ell)$ is a condition such that $h \in [g,k]$ and $\ell \geq k$, we say that $(h, \ell)$ extends $(g,k)$, and we denote this $(h, \ell) \leqslant (g,k)$. As above, every filter $\mathcal{F}$ for this notion of forcing induces a function $f_\mathcal{F} := \bigcup \{ g : (g,k) \in \mathcal{F} \}$, and if $\mathcal{F}$ is sufficiently generic, then $f_\mathcal{F}$ is total and $\lim_x f_\mathcal{F}(x,y) = G_0$, which implies that $f_\mathcal{F}' \geq_\text{T} G_0$ and thus that $f_\mathcal{F}^{(m+1)} \geq_\text{T} G_0^{(m)} \geq_\text{T} A$. Thus, all that remains to show is that $(Z \oplus f_\mathcal{F})^{(m)}$ is not DNC over $\emptyset^{(m)}$. Define the forcing question ${?}{\vdash}$ exactly as in Definition \ref{forcingquestion}.

    For each condition $(g,k)$ and each index $e$, we must find an extension $(h, \ell) \leqslant (g,k)$ forcing either $\Phi_e^{(Z \oplus f)^{(m)}}(x) \uparrow$ or $\Phi_e^{(Z \oplus f)^{(m)}}(x) \downarrow = \Phi_x^{\emptyset^{(m)}}(x)$ for some $x$. (This ensures that $\Phi_e^{(Z \oplus f)^{(m)}}$ is not an $\emptyset^{(m)}$-DNC function.) Fix a condition $(g,k)$, and define $$\mathcal{U}:= \{ (x, v) \in \omega^2 : (g,k) \ {?}{\vdash} \ \varphi(f)\},$$ where $\varphi(f)$ is some $\Sigma^0_{m+1}(Z)$ formula asserting that $\Phi_e^{(Z \oplus f)^{(m)}}(x) \downarrow = v$. Since the innermost quantifier in the predicate defining $\mathcal{U}$ only quantifies over finitely much information about $G_0$, we have that $\mathcal{U}$ is $\Sigma^0_{1}((Z' \oplus G_0)^{(m-1)})$. There are three cases:
    \begin{itemize}
        \item Case 1: There is some $x$ such that $(x, \Phi_x^{\emptyset^{(m)}}(x)) \in \mathcal{U}$. In this case, by part (1) of our Claim, we can find an extension $(h, \ell) \leqslant (g,k)$ forcing $\Phi_e^{(Z \oplus f)^{(m)}}(x) \downarrow = \Phi_x^{\emptyset^{(m)}}(x)$.
        \item Case 2: There is some $x$ such that, for each $v \in \omega$, $(x,v) \notin \mathcal{U}$. In this case, by part (2) of our Claim, $(g,k)$ itself forces $\Phi_e^{(Z \oplus f)^{(m)}}(x) \uparrow$.
        \item Case 3: Neither of the above holds. In this case, define $\mathcal{U}_0$ to be the set of pairs $(x,v)$ such that $(x,v) \in \mathcal{U}$ and $(x,w) \notin \mathcal{U}$ for all $w < v$. This $\mathcal{U}_0$ is computable in $\mathcal{U}$, and is therefore $\Sigma^0_1((Z \oplus G_0)^{(m-1)})$. This $\mathcal{U}_0$ is also the graph of a $\emptyset^{(m)}$-DNC function, contradicting our assumption that $(Z' \oplus G_0)^{(m-1)}$ is not DNC over $\emptyset^{(m)}$.
    \end{itemize}
\end{proof}

\begin{proof}[Proof of Theorem \ref{WKLvDNR}]
    Let $\mathcal{W} = \{ S : S^{(m)} \text{ is not DNC over } \emptyset^{(m)} \}$. By definition, $\mathsf{DNR}^{(m)}$ does not preserve $\mathcal{W}$. So, by Lemma \ref{separation-thm}, it will suffice to prove that $\mathsf{WKL}^{(n)}$ preserves $\mathcal{W}$. Let $Z \in \mathcal{W}$ and $X \leq_\text{T} Z$. We must find a $\mathsf{WKL}^{(n)}$-solution $Y$ to $X$ such that $Z \oplus Y \in \mathcal{W}$. By Theorem \ref{mthjumpgeneralization}, there exists some $Y$ such that $Y^{(m+1)} \gg X^{(n)}$ but $(X \oplus Y)^{(m)}$ is not DNC over $\emptyset^{(m)}$. Since $Y^{(m+1)} \gg X^{(n)}$, we have $Y^{(n)} \gg X^{(n)}$, as needed.
\end{proof}

