\begin{figure}[tb]
    \centering
    \includegraphics[width=1.0\linewidth]{Fig4.pdf}
    \caption{This diagram presents the difference between the lowest energy band and the 2nd lowest energy band $\varepsilon_2 - \varepsilon_1/J$ as a heatmap over the momentum space defined by $k_x,k_y \in [-\pi ,\pi]$. The arrowed trajectory indicates a representative path within the reduced Brillouin zone(BZ).}
