\section{Spin-Wave Approximation}
\label{appex:DerivationofHamiltonian}

This appendix gives a brief derivation of the Hamiltonian Eq.~(\ref{rawmodelequation}) to the matrix form in Eq.~(\ref{modelequation}).  
By employing the spin-wave approximation given in Eqs.~(\ref{spinwaveapprox1})-(\ref{spinwaveapprox3}) and by using the Fourier transformation $b_{\nu \bm{R}} = (1 / N_{\text{CF}})^{-1/2} \sum_{\bm{k} \in \Lambda} e^{i(\bm{k}\cdot(\bm{R} + \bm{\delta_\nu}))} b_{\nu \bm{k}}$, the exchange term in the Hamiltonian, Eq.~(\ref{modelequation}), can be rewritten as
\begin{align}
&\sum_{\nu,\bm{R}}\sum_{\mu,\bm{R}^{\prime}}J_{\bm{R},\bm{R}^{\prime}}^{\nu \mu} \bm{S}_{\nu \bm{R}} \cdot \bm{S}_{\mu \bm{R}^{\prime}} \notag \\
    &= S_0\sum_{\bm{k} \in \Lambda} \bigg[3J(b_{1 \bm{k}}^{\dagger}b_{1 \bm{k}} + b_{2 \bm{k}}^{\dagger}b_{2 \bm{k}} + b_{3 \bm{k}}^{\dagger}b_{3 \bm{k}} + b_{4 \bm{k}}^{\dagger}b_{4 \bm{k}}) - J_2(b_{3 \bm{k}}^{\dagger}b_{3 \bm{k}} + b_{4 \bm{k}}^{\dagger}b_{4 \bm{k}}) - J_1(b_{1 \bm{k}}^{\dagger}b_{1 \bm{k}} + b_{2 \bm{k}}^{\dagger}b_{2 \bm{k}}) \notag \\
    & \quad + J\bigg(e^{i\bm{k} \cdot \bm{\delta_x}} b_{4 \bm{k}}^{\dagger}b_{2,- \bm{k}}^{\dagger} + e^{-i\bm{k} \cdot \bm{\delta_x}} b_{4 \bm{k}}b_{2,- \bm{k}} + e^{i\bm{k} \cdot \bm{\delta_x}} b_{3 \bm{k}}^{\dagger}b_{1,- \bm{k}}^{\dagger} + e^{-i\bm{k} \cdot \bm{\delta_x}} b_{3 \bm{k}}b_{1,- \bm{k}} + e^{-i\bm{k} \cdot \bm{\delta_x}} b_{1 \bm{k}}b_{3,- \bm{k}} + e^{i\bm{k} \cdot \bm{\delta_x}} b_{1 \bm{k}}^{\dagger}b_{3,- \bm{k}}^{\dagger} \notag \\
    & \quad \quad+e^{-i\bm{k} \cdot \bm{\delta_x}} b_{2 \bm{k}}b_{4,- \bm{k}} + e^{i\bm{k} \cdot \bm{\delta_x}} b_{2 \bm{k}}^{\dagger}b_{4,- \bm{k}}^{\dagger} + e^{-i\bm{k} \cdot \bm{\delta_y}} b_{2 \bm{k}}b_{3,- \bm{k}} + e^{i\bm{k} \cdot \bm{\delta_y}} b_{2 \bm{k}}^{\dagger}b_{3,- \bm{k}}^{\dagger} + e^{i\bm{k} \cdot \bm{\delta_y}} b_{4 \bm{k}}^{\dagger}b_{1,- \bm{k}}^{\dagger} + e^{-i\bm{k} \cdot \bm{\delta_y}} b_{4 \bm{k}}b_{1,- \bm{k}}\bigg) \notag \\
    & \quad + J_2(e^{i\bm{k} \cdot \bm{\delta_y}} b_{3 \bm{k}}^{\dagger}b_{4 \bm{k}} + e^{-i\bm{k} \cdot \bm{\delta_y}} b_{3\bm{k}}b_{4\bm{k}}^{\dagger}) + J_1(e^{-i\bm{k} \cdot \bm{\delta_y}} b_{2 \bm{k}}^{\dagger}b_{1 \bm{k}} + e^{-i\bm{k} \cdot \bm{\delta_y}} b_{2\bm{k}}b_{1\bm{k}}^{\dagger})\bigg] .
\end{align}
This term is represented by the $8\times 8$ matrix on the basis ${\bm \Psi}=(b_{1{\bm k}},b_{2{\bm k}},b_{3{\bm k}},b_{4{\bm k}},b_{1-{\bm k}}^\dagger,b_{2-{\bm k}}^\dagger,b_{3-{\bm k}}^\dagger,b_{4-{\bm k}}^\dagger)$ as 
\begin{align}
M_{\bm{k}}^{\rm ex} = 
\begin{pmatrix}
3J - J_1 & J_1e^{i k_y a} & 0 & 0 & 0 & 0 & 2J\cos k_x a & Je^{- i k_y a}\\
J_1e^{-i k_y a} & 3J - J_1 & 0 & 0 & 0 & 0 & Je^{ i k_y a} & 2J\cos k_x a \\ 
0 & 0 & 3J - J_2 & J_2e^{i k_y a} & 2J\cos k_x a & Je^{- i k_y a} & 0 & 0\\
0 & 0 & J_2e^{-i k_y} & 3J - J_2 & Je^{i k_y a} & 2J\cos k_xa & 0 & 0\\
0 & 0 & 2J\cos k_x a & Je^{- i k_y a} & 3J - J_1 & J_1e^{i k_y a} & 0 & 0 \\
0 & 0 & Je^{ i k_y a} & 2J\cos k_x a & J_1e^{-i k_y a} & 3J - J_1 & 0 & 0\\
2J\cos k_x a & Je^{- i k_y a} & 0 & 0 & 0 & 0 & 3J - J_2 & J_2e^{i k_y a}\\       
Je^{i k_y a} & 2J\cos k_x a & 0 & 0 & 0 & 0 & J_2e^{-i k_y a} & 3J - J_2 
\end{pmatrix} .
\end{align}
In a similar way, the anisotropy term is represented with a diagonal matrix as
\begin{align}
M_{\bm k}^{\rm ani} = {\rm diga} \, (2K_1,2K_1,2K_2,2K_2,2K_1,2K_1,2K_2,2K_2).
\end{align}
The matrix in Eq.~\eqref{modelequation} is given as $M_{\bm k} = M_{\bm k}^{\rm ex}+M_{\bm k}^{\rm ani}$.

\section{Retarded Green's functions}
\label{app:retarded}

In this Appendix, we introduce the retarded Green's functions for both the NM and the CF.
The retarded spin susceptibility of the NM is defined as
\begin{align}
    \chi^{R}(\bm{q},t) = \frac{i\theta(t)}{\hbar N_{\rm NM}} \langle [s_{\bm{q}}^+(t),s_{\bm{q}}^{-}(0)]\rangle,
\end{align}
where $N_{\rm NM}$ is the number of conduction electrons. Similarly, the retarded magnon propagator in the CF for the sublattice $\nu$ is defined as
\begin{align}
\label{definitionofRetarded}
    G^{R}_{\nu\nu}(\bm{k},t) = -\frac{i}{\hbar}\langle [S_{\nu \bm{k}}^+(t),S_{\nu \bm{k}}^{-}(0)] \rangle .
\end{align}
Using the Holstein-Primakoff transformation and employing the linear spin-wave approximation, we obtain the magnon retarded Green's function as
\begin{align}
\label{retardedgreenfunction2}
G_{\nu\nu}^{R}(\bm{k},\omega) = 
\left\{ \begin{array}{ll}
\displaystyle{-\sum_{j = 1}^8 \frac{2S_0 \sigma_j|(T_{\bm{k}})_{\nu j}|^2}{\hbar \omega - \sigma_j \varepsilon_{\bm{k},j} + i \delta},} & (\nu = 1,2), \\
\displaystyle{\sum_{j = 1}^8 \frac{2S_0 \sigma_j|(T_{\bm{k}})_{\nu j}|^2}{\hbar \omega + \sigma_j \varepsilon_{\bm{k},j} + i \delta},} & (\nu = 3,4), \end{array} \right.
\end{align}
where $\sigma_j = \pm 1$ corresponds to the particle or hole branch of the Nambu basis and $\delta$ is a positive infinitesimal. 
For detailed derivations, see Appendix. ~\ref{appex:DerivationofGreenFunction}.
To take into account the Gilbert damping phenomenologically, we replace $\delta$ with $\alpha \hbar \omega$ hereafter, where $\alpha$ is the Gilbert damping constant.

\section{Lesser Green's functions}
\label{app:lesser}

In this Appendix, we summarize the detailed calculation of the lesser Green's function of the CF.
We define the lesser component of Green's function as
\begin{align}
\label{chilesser}
\chi^{<}(\bm{q},t) &= -\frac{i\theta(t)}{\hbar N_{\rm NM}} \langle s_{\bm{q}}^{-}(0)s_{\bm{q}}^+(t) \rangle,\\
\label{Glesser}    
G^{<}_{\nu\nu}(\bm{k},t) &= \frac{i}{\hbar}\langle S_{\nu \bm{k}}^{-}(0) S_{\nu \bm{k}}^+(t) \rangle .
\end{align}
When the CF and NM are decoupled and they are in thermal equilibrium with the temperatures, $T_{\rm CF}$ and $T_{\rm NM}$, the lesser component can be related to the retarded component through the fluctuation-dissipation theorem as~\cite{Stefanucci2013}
\begin{align}
\label{KMSlesserRetarded}
G^{<}_{\nu \nu}(\bm{k},\omega) &=2i\delta f(\hbar \omega,T_{\rm CF}) \text{Im}\, [G^{R}_{\nu\nu}(\bm{k},\omega)], \\
\chi^{<}(\bm{q},\omega) &= 2if(\hbar \omega,T_{\rm NM}) \text{Im}\, [\chi^{R}(\bm{q},\omega)],
\label{KMSlesserRetarded2}
\end{align} 
where $f(\epsilon,T)=(e^{\epsilon/k_{\rm B}T}-1)^{-1}$ is the Bose distribution function.
These expressions will be used for formulating the spin current induced by the SSE in Sec.~\ref{SSE}.

For the setup of spin pumping, we set $T_{\rm NM} = T_{\rm CF}$, while the Green's function is calculated by second-order perturbation with respect to $V(t)$.
The retarded component is unchanged under second-order perturbation, while the lesser Green's function is evaluated as~\cite{kato19}
\begin{align}\label{secondorderlessergreen}
\delta G^{<}_{\nu \nu} (\bm{k},\Omega) &= G^{R}_{\nu \nu}(\bm{k},\Omega)\Sigma_{\nu}(\bm{k},\Omega)G^{A}_{\nu \nu}(\bm{k},\Omega)  ,
\end{align}
where $\Sigma_{\nu}(\bm{k},\Omega)$ is the self-energy due to the microwave defined as
\begin{align}
    \Sigma_{\nu}(\bm{k},\Omega) = \left\{ \begin{array}{ll} \displaystyle{-i\frac{2 \mathcal{D}^2}{\hbar} \delta_{\bm{k},\bm{0}}\delta(\omega - \Omega),} & (\nu = 1,2), \\
    \displaystyle{-i\frac{2 \mathcal{D}^2}{\hbar} \delta_{\bm{k},\bm{0}}\delta(\omega + \Omega),} & (\nu = 3,4),\end{array} \right. 
\end{align}
The lesser component is rewritten as

\begin{align}\label{second2}
\delta G^{<}_{\nu \nu}(\bm{k},\omega) &= 
\Sigma_{\nu}(\bm{k},\Omega)R_{\nu}(\bm{k},\omega), \\
R_{\nu}(\bm{k},\omega) & =
     4S_0^2\bigg[\bigg( \sum_{j =1}^8\frac{\sigma_j  |(T_{\bm{k}})_{\nu j}|^2(\hbar \omega - \sigma_j \varepsilon_{\bm{k},j})}{(\hbar \omega - \sigma_j \varepsilon_{\bm{k},j})^2 + (\alpha \hbar \omega)^2} \bigg)^2 
     + \bigg( \sum_{j =1}^8\frac{\sigma_j  |(T_{\bm{k}})_{\nu j}|^2\alpha \hbar \omega}{(\hbar \omega - \sigma_j \varepsilon_{\bm{k},j})^2 + (\alpha \hbar \omega)^2} \bigg)^2\bigg] .\label{second2R}
\end{align}

\section{Detailed Derivation of the Spin Current}\label{appex:derivationofSpinCurrent}

Here, we derive the spin current Eq.~(\ref{spincurrent}).
The spin current is calculated using the Keldysh formalism as~\cite{Bruus,kato19} 
\begin{align}
\langle I_S(t) \rangle 
&= \text{Im}\,\bigg[ \sum_{\nu \bm{R}}J_{\nu {\bm R},{\bm r}} \bigg\langle S_{\nu \bm{R}}(\tau_1)s_{\bm r}^-(\tau_2) \exp\bigg(-\frac{i}{\hbar}\int_C d\tau H_{\text{int}}(\tau) \bigg)\bigg\rangle_0\bigg] \notag \\
&= -\frac{2}{\hbar} \, \text{Re}\,\bigg[ \sum_{\nu \bm{R}} \sum_{\nu^{\prime} \bm{R}^{\prime}} J_{\nu {\bm R},{\bm r}} J_{\nu^{\prime} {\bm R}^{\prime}, {\bm r}'}^{\ast} \int_C d\tau \, \bigg\langle \mathcal{T} S_{\nu \bm{R}}(\tau_1) s_{{\bm r}}^-(\tau_2) S_{\nu^{\prime} \bm{R}^{\prime}}^- s_{{\bm r}'}^+(\tau)\bigg\rangle_0\bigg] ,
\end{align}
where $A(\tau) = e^{\tau H_0/\hbar} A e^{-\tau H_0/\hbar}$ describes the imaginary-time evolution under the Hamiltonian $H_0 = H_{\rm CF} + H_{\rm NM}$, $\langle \cdots \rangle$ indicates the thermal average under $H_0$, $\tau_1 = (t,+)$ and $\tau_2 = (t,-)$ indicate the times on the Keldysh contour, and $\int_C d\tau$ represents the integral with respect to the time $\tau$ on the Keldysh contour.
Using Eq.~\eqref{randave}, 
\begin{align}
\langle I_S\rangle &= -2\hbar \,\text{Re}\,\bigg[ \sum_{\nu \bm{R}} \sum_{\bm{k} ,\bm{q}} \frac{|J|^2}{N_{\rm CF}N_{\rm NM}} \int_C d\tau \, G_{\nu \nu} (\bm{q},\tau_1,\tau) \chi(\bm{k},\tau,\tau_2)\bigg] \notag \\
&= -2\hbar\sum_{\bm{k} ,\bm{q}}  \sum_{\nu}\,\text{Re}\, \bigg[  \sum_{\nu \bm{R}}  \frac{|J_{\nu j}|^2}{N_{\rm CF}N_{\rm NM}}\int_{-\infty}^{\infty} \frac{d\omega}{2\pi} \, \bigg(\chi^{<}(\bm{k},\omega)G_{\nu \nu}^{R,(a)}(\bm{q},\omega) + \chi^{A}(\bm{k},\omega) G_{\nu \nu}^{<,(a)}(\bm{q},\omega)\bigg)\bigg],
\end{align}
where $G_{\nu \nu} (\bm{q},\tau_1,\tau)$ and $\chi(\bm{k},\tau,\tau_2)$ are the nonequilibrium Green's functions for the CF and NM, respectively, and the Langreth rule~\cite{Stefanucci2013} has been applied in the second equation.
Finally, substituting the general expression of the fluctuation-dissipation theorem, Eqs.~\eqref{KMSlesserRetarded} and \eqref{KMSlesserRetarded2}, we obtain the anticipated expression, Eq.~(\ref{spincurrent}).

\section{Retarded Green's Function}\label{appex:DerivationofGreenFunction}

In this appendix, we derive the explicit form for the retarded Green's function for the CF, $G_{\nu\nu}^R(\bm{k},\omega)$.
Let us first consider the case of $\nu = 1,2$.
The retarded Green's function is then calculated as
\begin{align}
\label{retardedgreensfunction}
G_{\nu\nu}^R(\bm{k},t) &= -i \frac{2S_0}{\hbar} \theta(t) \langle[b_{\nu \bm{k}}(t),b_{\nu \bm{k}}^{\dagger}(0)] \rangle \notag \\ 
&= -i \frac{2S_0}{\hbar} \theta(t) \bigg \langle \bigg[ \sum_{j = 1}^8(T_{\bm{k}})_{\nu j }\Phi_j(t),\sum_{i = 1}^8(T_{\bm{k}}^{\ast})_{\nu i}(\Phi^{\dagger T})_i\bigg]\bigg \rangle \notag \\
&= -i \frac{2S_0}{\hbar} \theta(t) \sum_{j = 1}^8 \sigma_j|(T_{\bm{k}})_{\nu j}|^2e^{-i\sigma_j\varepsilon_{\bm{k},j}t/\hbar } .
\end{align}
Here, we have introduced the Bogoliubov transformation, $b_{\nu \bm{k}} = \sum_{j=1}^8(T_{\bm{k}})_{\nu j}\Phi_j$ with new bosonic creation and annihilation operators, ${\bm \Psi}=(a_{1{\bm k}},a_{2{\bm k}},a_{3{\bm k}},a_{4{\bm k}},a_{1-{\bm k}}^\dagger,a_{2-{\bm k}}^\dagger,a_{3-{\bm k}}^\dagger,a_{4-{\bm k}}^\dagger)$.
By the Fourier transformation, we obtain
\begin{align}
  G_{\nu\nu}^R(\bm{k},\omega) &= 2S_0 \sum_{j = 1}^8 \frac{\sigma_j|(T_{\bm{k}})_{\nu j}|^2}{\hbar \omega - \sigma_j \varepsilon_{\bm{k},j} + i \alpha \hbar \omega},
\end{align}  
where $\delta$ is replaced by $\alpha \hbar\omega$ to take into account the Gilbert damping phenomenologically.
In a similar way, we can obtain the retarded Green's function also for $\nu = 3,4$.

For comparison, we also derive the retarded Green's function of the FI defined as
\begin{align}
    G^R(\bm{k},t) &= -i\frac{2S_0}{\hbar} \theta(t) \langle [ b_{\bm k}(t),b_{\bm k}^\dagger(0)] \rangle.
\end{align}
We note that the Hamiltonian of the FI is written in the quadratic form as $H_{\rm FI} = \sum_{{\bm k}} \epsilon_{\bm k} b_{\bm k}^\dagger b_{\bm k}$ with  $\varepsilon_{\bm{k}} = JS_0a^2 |\bm{k}|^2$, where $J$ is the exchange interaction in the bulk FI, $S_0$ is the amplitude of the localized spin, and $a$ is the lattice spacing.
Then, the retarded Green's function is calculated as
\begin{align}
G^R(\bm{k},t) &= -\frac{2S_0}{\hbar} e^{-i\varepsilon_{\bm{k}}t/\hbar} \quad \rightarrow \quad
G^R(\bm{k},\omega) = \frac{2S_0}{\hbar \omega - \varepsilon_{\bm{k}} + i \alpha \hbar \omega} ,
\end{align}
where the positive infinitesimal $\delta$ is replaced with $\alpha \omega$.
Substituting $\text{Im}\, [G^R(\bm{k},\omega)]$ of the above expression and Eq.~\eqref{BoseLinearTemperature} into Eq.~\eqref{spincurrent}, we obtain Eq.~\eqref{ferromagneticspinseebeck}.

\section{Spin Current in the Altermagnet(AM)/NM Junction}

We provide a brief calculation for the spin current generated by SSE in the bilayer system AM/NM and show that no spin current is generated. 
By employing Eq.~\eqref{SSEspincurrent} and by using the Bogoliubov transformation with a paraunitary matrix \cite{Cui2023} 
\begin{align}
    T_{\bm{k}} = 
    \begin{pmatrix}
        u_{\bm{k}} & v_{\bm{k}}^{\ast}\\
        v_{\bm{k}} & u_{\bm{k}}^{\ast}
    \end{pmatrix}
\end{align}
Since the sum in Eq.~\eqref{SSEspincurrent} is taken over the BZ $\bm{k} \in \Lambda$, Eq.~\eqref{SSEspincurrent} reads
\begin{align}
    I_{S,{\rm AM}}^{\rm SSE} &\propto \sum_{\bm{k \in \Lambda}}\sum_{j =A,B}\frac{\varepsilon_{\bm{k},j}^2}{ \sinh^2(\beta \varepsilon_{\bm{k},j}/2)}\bigg(|(T_{\bm{k}})_{A j}|^2 -  |(T_{\bm{k}})_{B j}|^2\bigg) \notag \\
    &= \sum_{\bm{k \in \Lambda}} \frac{\varepsilon_{\bm{k},A}^2}{ \sinh^2(\beta \varepsilon_{\bm{k},A}/2)}\bigg(|u_{\bm{k}}|^2 - |v_{\bm{k}}|^2\bigg) - \frac{\varepsilon_{\bm{k},B}^2}{ \sinh^2(\beta \varepsilon_{\bm{k},B}/2)} \bigg(|u_{\bm{k}}^{\ast}|^2 - |v_{\bm{k}}^{\ast}|^2 \bigg) \notag \\
    & = \sum_{\bm{k} \in \Lambda} \bigg[\frac{\varepsilon_{\bm{k},A}^2}{ \sinh^2(\beta \varepsilon_{\bm{k},A}/2)} - \frac{\varepsilon_{\bm{k},B}^2}{ \sinh^2(\beta \varepsilon_{\bm{k},B}/2)}\bigg]\bigg(|u_{\bm{k}}|^2 - |v_{\bm{k}}|^2\bigg) \notag \\
    & = \sum_{\bm{k} \in \Lambda} \bigg(\frac{\varepsilon_{\bm{k},A}^2}{ \sinh^2(\beta \varepsilon_{\bm{k},A}/2)} - \frac{\varepsilon_{\bm{k},B}^2}{ \sinh^2(\beta \varepsilon_{\bm{k},B}/2)}\bigg) = 0
\end{align}
where the last line shows that the spin current depends only on the geometry of the band structure in $\bm{k}$-space.
By a similar calculation for spin pumping, we can also show that no spin current is generated by the external microwave in the absence of the magnetic field.
