\section{Proofs of Main Results}


\subsection{Proof of Theorem \ref{theo_charact}}
\textbf{Part (A)}. Suppose that $\phi_{\theta}(Y^T,X^T)$ is absolutely integrable under DGP $(\theta,\omega)$. Then, by the law of iterated expectations, we have
\begin{align*}
    \mathbb{E}_{\theta,\omega}[\phi_{\theta}(Y^T,X^T)]&=\mathbb{E}_{\theta,\omega}\left[\mathbb{E}_{\theta,\omega}[\phi_{\theta}(Y^T,X^T)\,|\, Y^{T-1},X^{T-1},A]\right]\\
    &=\mathbb{E}_{\theta,\omega}\left[\int \phi_{\theta}(Y^{T-1},y_T,X^{T-1},x_T)f_{\theta}(y_T\,|\, Y_{t-1},x_T,A)g(x_T\,|\, Y^{T-1},X^{T-1},A)\mathrm{d}y_T\mathrm{d}x_T \right]\\
    &=\mathbb{E}_{\theta,\omega}\left[\int \phi_{\theta}(Y^{T-1},y_T,X^{T-1},x_T)f_{\theta}(y_T\,|\, Y_{T-1},x_T,A)\mathrm{d}y_T\right],	
\end{align*}
for any arbitrary $x_T$ value, where the last equality follows from \eqref{eq_phi_feedback_robust} for $s=T$. By successive applications of the law of iterated expectations and \eqref{eq_phi_feedback_robust} for $s=T-1,...,2$, we get
\begin{align*}
    \mathbb{E}_{\theta,\omega}[\phi_{\theta}(Y^T,X^T)]
    &=\mathbb{E}_{\theta,\omega}\left[\int \phi_{\theta}(Y_{0},y^{1:T},X_{1},x^{2:T})\prod_{t=2}^T f_{\theta}(y_{t}\,|\, y_{t-1},x_{t},A)f_{\theta}(y_{1}\,|\, Y_{0},X_{1},A)\mathrm{d}y^{1:T}\right]
\end{align*}
for any collection of regressor values $x^{2:T}$. Finally, using \eqref{eq_phi_hetero_robust} implies $\mathbb{E}_{\theta,\omega}[\phi_{\theta}(Y^T,X^T)]=0$.  \\

\noindent \textbf{Part (B).}
Suppose that, for all $\omega\in\Omega$ such that $\mathbb{E}_{\theta,\omega}\left[\abs{\phi_{\theta}(Y^T,X^T)}\right]<\infty$ we have $\mathbb{E}_{\theta,\omega}[\phi_{\theta}(Y^T,X^T)]=0$. Let $\eta\mapsto \omega_{\eta}$ denote a smooth path such that $\omega_{\eta^*}=\omega^*$ at some $\eta^*$. By (B)(ii), there exists a $\kappa$-ball around $\eta^*$, $B_{\kappa}(\eta^*)$,  such that for all $\eta \in B_{\kappa}(\eta^*)$, $\mathbb{E}_{\theta,\omega_{\eta}}\left[\abs{\phi_{\theta}(Y^T,X^T)}\right]<\infty$ and thus $\mathbb{E}_{\theta,\omega_{\eta}}[\phi_{\theta}(Y^T,X^T)]=0$. Next, by (B)(i) and (B)(ii), we can apply Lemma 5.4 in \cite{newey1994large}, and conclude that $\eta \mapsto \mathbb{E}_{\theta,\omega_{\eta}}\left[\phi_{\theta}(Y^T,X^T)\right]$ is differentiable at $\eta^{*}$ with derivative $\mathbb{E}_{\theta,\omega^*}[\phi_{\theta}(Y^T,X^T)S^{\eta}(Y^T,X^T)']$ where $S^{\eta}(Y^T,X^T)$ denotes the score at $\eta^*$. Hence, since $\mathbb{E}_{\theta,\omega_{\eta}}[\phi_{\theta}(Y^T,X^T)]=0$ for all $\eta \in B_{\kappa}(\eta^*)$, we have $\mathbb{E}_{\theta,\omega^*}[\phi_{\theta}(Y^T,X^T)S^{\eta}(Y^T,X^T)']=0$. Moreover, by differentiability in quadratic mean, $S^{\eta}$ is square-integrable under DGP $(\theta,\omega^*)$. Claim (B) then follows from Lemma \ref{lem_moment_perp_score}. 

\begin{lemma} \label{lem_moment_perp_score}
 Suppose that $\mathbb{E}_{\theta,\omega^{*}}[\norm{\phi_{\theta}(Y^T,X^T)}^2]<\infty$ and $\mathbb{E}_{\theta,\omega^*}[\phi_{\theta}(Y^T,X^T)S^{\eta}(Y^T,X^T)']=0$ for all score functions $S^{\eta}$ of smooth parametric submodels. Then (\ref{eq_phi_hetero_robust})-(\ref{eq_phi_feedback_robust}) hold. 
\end{lemma}

\begin{proof}
Let $\ell(\theta,\omega_{\eta}| y^T,x^{T})$ denote a smooth parametric submodel where $\omega_{\eta}=(g_{\eta},\pi_{\eta},\nu_{\eta})$ and  $\omega_{\eta^*}=\omega^*$. We have $(T+1)$ types of scores associated with submodels: one associated with the initial condition density, $\nu_{\eta}$, one associated with the heterogeneity distribution, $\pi_{\eta}$, and $T-1$ scores associated with the feedback processes for $X_2,\ldots,X_T$, $g_{\eta}$. We begin with the heterogeneity component, which yields scores of the form: 

$$S^{\eta,\pi}(y^T,x^T)=\frac{\int \nabla_{\eta}\ln \pi^*(a\,|\, y_0,x_1) p^*(y^{1:T},x^{2:T},a)\mathrm{d}a}{\int p^*(y^T,x^T,a)da},$$
where 
\begin{align*}
    &p^*(y^T,x^T,a)=\prod_{t=1}^Tf_{\theta}(y_{t}\,|\, y_{t-1},x_{t},a)\prod_{t=2}^Tg^*(x_{t}\,|\, y^{t-1},x^{t-1},a)\pi^*(a\,|\, y_{0},x_{1}),
\end{align*}
and $ \nabla_{\eta}\ln \pi^*$ denotes the score of the submodel $\eta\mapsto \pi_{\eta}$ at $\omega^*$.\\
Next we consider the scores for the $(T-1)$ feedback components:
$$S^{\eta,g,t}(y^T,x^T)=\frac{\int \nabla_{\eta}\ln g^*(x_t\,|\, y^{t-1},x^{t-1},a) p^*(y^T,x^T,a)\mathrm{d}a}{\int p^*(y^T,x^T,a)da},\quad t=2,...,T.$$
Finally, for the initial condition, the scores take the form:
$$S^{\eta,\nu}(y^T,x^T)=\nabla_{\eta}\ln \nu^*(y_0,x_1).$$
Let $S^\eta(y^T,x^T)=\left(S^{\eta,\pi}(y^T,x^T),S^{\eta,g,2}(y^T,x^T),\ldots,S^{\eta,g,T}(y^T,x^T),S^{\eta,\nu}(y^T,x^T)\right)'$. Without loss of generality, suppose $\phi_{\theta}$ is scalar. By assumption, we have
\begin{align} \label{tauperp_hetero}
    0&=\mathbb{E}_{\theta,\omega^*}\left[\phi_{\theta}\left(Y^T,X^T\right)S^{\eta,\pi}(Y^T,X^T)\right] \\
    &=\int \phi_{\theta}(y^T,x^T)\nabla_{\eta}\ln \pi^*(a\,|\, y_0,x_1) p^*(y^T,x^T,a)\nu^*(y_0,x_1)\mathrm{d}a\mathrm{d}y^T\mathrm{d}x^T,  \notag
\end{align}
and, for $ t=2,\ldots,T$,
\begin{align} \label{tauperp_feedback}
    0&=\mathbb{E}_{\theta,\omega^*}\left[\phi_{\theta}(Y^T,X^T)S^{\eta, g,t}(Y^T,X^T)\right] \\
    &=\int \phi_{\theta}(y^T,x^T)\nabla_{\eta}\ln g^*(x_t\,|\, y^{t-1},x^{t-1},a) p^*(y^T,x^T,a)\nu^*(y_0,x_1)\mathrm{d}a\mathrm{d}y^T\mathrm{d}x^T, \notag
\end{align}
and 
\begin{align} \label{tauperp_initcond}
    0&=\mathbb{E}_{\theta,\omega^*}\left[\phi_{\theta}(Y^T,X^T)S^{\eta,\nu}(Y^T,X^T)\right] \\
    &=\int \phi_{\theta}(y^T,x^T) \nabla_{\eta}\ln \nu^*(y_0,x_1)  p^*(y^T,x^T,a)\nu^*(y_0,x_1)\mathrm{d}a\mathrm{d}y^T\mathrm{d}x^T. \notag
\end{align}
Note that equation \eqref{tauperp_feedback} for $t=T$, after integrating over $y_T$, coincides with:
\begin{align*}
    0&=\int \nabla_{\eta}\ln g^*(x_T\,|\, y^{T-1},x^{T-1},a)\mathbb{E}_{\theta,\omega^*}\left[\phi_{\theta}(Y^T,X^T)|Y^{T-1}=y^{T-1},X^T=x^T,A=a\right] \\
    &\quad \times \prod_{t=1}^{T-1}f_{\theta}(y_{t}\,|\, y_{t-1},x_{t},a)\prod_{t=2}^Tg^*(x_{t}\,|\, y^{t-1},x^{t-1},a)\pi^*(a\,|\, y_{0},x_{1})\nu^*(y_0,x_1)\mathrm{d}a \mathrm{d}y^{T-1}\mathrm{d}x^T.
\end{align*}
Now, since $\nabla_{\eta}\ln g^*(x_T\,|\, y^{T-1},x^{T-1},a)$ is unrestricted except for the fact that it has zero mean conditional on $(y^{T-1},x^{T-1},a)$ and is square-integrable, we can specifically choose
\begin{align*}
    \nabla_{\eta}\ln g^*(x_T\,|\, y^{T-1},x^{T-1},a)&=\mathbb{E}_{\theta,\omega^*}\left[\phi_{\theta}(Y^T,X^T)|Y^{T-1}=y^{T-1},X^T=x^T,A=a\right] \\
    &\quad -\mathbb{E}_{\theta,\omega^*}\left[\phi_{\theta}(Y^T,X^T)|Y^{T-1}=y^{T-1},X^{T-1}=x^{T-1},A=a\right],
\end{align*}
in which case \eqref{tauperp_feedback} (for $t=T$) evaluates to (for $\mathbb{V}_{\theta,\omega^*}$ the variance under $(\theta,\omega^*)$):
\begin{align*}
    \int \mathbb{V}_{\theta,\omega^*}\left(\mathbb{E}_{\theta,\omega^*}\left[\phi_{\theta}(Y^T,X^T)|Y^{T-1}=y^{T-1},X^T=x^T,A=a\right]|Y^{T-1}=y^{T-1},X^{T-1}=x^{T-1},A=a \right) \\
    \times \prod_{t=1}^{T-1}f_{\theta}(y_{t}\,|\, y_{t-1},x_{t},a)\prod_{t=2}^Tg^*(x_{t}\,|\, y^{t-1},x^{t-1},a)\pi^*(a\,|\, y_{0},x_{1})\nu^*(y_0,x_1)\mathrm{d}a\mathrm{d}y^{T-1}\mathrm{d}x^T=0,
\end{align*}
which holds if, and only if, $\mathbb{E}_{\theta,\omega^*}\left[\phi_{\theta}(Y^T,X^T)|Y^{T-1}=y^{T-1},X^T=x^T,A=a\right]$ does not depend on $x_T$.  Conversely, if $\mathbb{E}_{\theta,\omega^*}\left[\phi_{\theta}(Y^T,X^T)|Y^{T-1}=y^{T-1},X^T=x^T,A=a\right]$ does not depend on $x_T$, it is clear that  equation \eqref{tauperp_feedback} for $t=T$ is satisfied since the elements $\nabla_{\eta}\ln g^*(x_T\,|\, y^{T-1},x^{T-1},a)$ have zero mean conditional on $(y^{T-1},x^{T-1},a)$. Therefore,  \eqref{tauperp_feedback} for $t=T$ is equivalent to the requirement that $\mathbb{E}_{\theta,\omega^*}\left[\phi_{\theta}(Y^T,X^T)|Y^{T-1}=y^{T-1},X^T=x^T,A=a\right]$ does not depend on $x_T$.\\
Next, consider \eqref{tauperp_feedback} for $t=T-1$. Exploiting the result above, we can integrate over $y_{T-1:T}$ and $x_T$ to get:
\begin{align*}
    0&=\int \nabla_{\eta}\ln g^*(x_{T-1}\,|\, y^{T-2},x^{T-2},a)\mathbb{E}_{\theta,\omega^*}\left[\phi_{\theta}(Y^T,X^T)|Y^{T-2}=y^{T-2},X^{T-1}=x^{T-1},A=a\right] \\
    &\quad \times \prod_{t=1}^{T-2}f_{\theta}(y_{t}\,|\, y_{t-1},x_{t},a)\prod_{t=2}^{T-1}g^*(x_{t}\,|\, y^{t-1},x^{t-1},a)\pi^*(a\,|\, y_{0},x_{1})\nu^*(y_0,x_1)\mathrm{d}a\mathrm{d}y^{T-2}\mathrm{d}x^{T-1}.
\end{align*}
Observe that the lack of restrictions on $\nabla_{\eta}\ln g^*(x_{T-1}\,|\, y^{T-2},x^{T-2},a)$, besides it being mean zero conditional on $(y^{T-2},x^{T-2},a)$ and being square-integrable, implies, by a logic analogous to that used for the $t=T$ case, that \eqref{tauperp_feedback} for $t=T-1$ is equivalent to the requirement that
\begin{align*}&\mathbb{E}_{\theta,\omega^*}\left[\phi_{\theta}(Y^T,X^T)|Y^{T-1}=y^{T-1},X^{T-1}=x^{T-1},A=a\right]\\&\quad =\int \phi_{\theta}(y^T,x^T)\prod_{t=T-1}^{T}f_{\theta}(y_{t}\,|\, y_{t-1},x_{t},a)\mathrm{d}y^{T-1:T}\end{align*}
does not depend on $x^{T-1:T}$. By inductive reasoning, we conclude that, for all $s=2,\ldots,T$,
\begin{align} \label{tauperp_feedback_bis}
        \int  \phi_{\theta}(y^T,x^T)\prod_{t=s}^Tf_{\theta}(y_{t}\,|\, y_{t-1},x_{t},a)\mathrm{d}y^{s:T} \text{ does not depend on }x^{s:T}.
\end{align}
That is, $\phi_{\theta}$ satisfies \eqref{eq_phi_feedback_robust}.\\
Next, consider equation \eqref{tauperp_hetero}. Using the results immediately above we get, after integrating over $y^{1:T}$ and $x^{2:T}$:
\begin{align*}
\int \nabla_{\eta}\ln \pi^*(a\,|\, y_0,x_1)\mathbb{E}_{\theta,\omega^*}\left[\phi_{\theta}(Y^T,X^T)|Y_0=y_0,X_1=x_1,A=a\right] \pi^*(a\,|\, y_0,x_1)\nu^*(y_0,x_1)\mathrm{d}a\mathrm{d}y_{0}\mathrm{d}x_{1}=0, 
\end{align*}
and since $\nabla_{\eta}\ln \pi^*(a\,|\, y_0,x_1)$ is unrestricted (beyond having zero mean conditional on $(y_0,x_1)$ and being square-integrable), choosing specifically
\begin{align*}
    \nabla_{\eta}\ln \pi^*(a\,|\, y_0,x_1)&=\mathbb{E}_{\theta,\omega^*}\left[\phi_{\theta}(Y^T,X^T)|Y_0=y_0,X_1=x_1,A=a\right]\\&\quad-\mathbb{E}_{\theta,\omega^*}\left[\phi_{\theta}(Y^T,X^T)|Y_0=y_0,X_1=x_1\right]
\end{align*}
implies that
\begin{align*}
&\int \mathbb{V}_{\theta,\omega^*}\left(\mathbb{E}_{\theta,\omega^*}\left[\phi_{\theta}(Y^T,X^T)|Y_0=y_0,X_1=x_1,A=a\right]|Y_0=y_0,X_1=x_1\right)\\
&\quad\quad\quad  \times\pi^*(a\,|\, y_0,x_1)\nu^*(y_0,x_1)\mathrm{d}a\mathrm{d}y_{0}\mathrm{d}x_{1}=0. 
\end{align*}
Thus, $\mathbb{E}_{\theta,\omega^*}\left[\phi_{\theta}(Y^T,X^T)|Y_0=y_0,X_1=x_1,A=a\right]$ does not depend on $a$. 
Conversely, if $\mathbb{E}_{\theta,\omega^*}\left[\phi_{\theta}(Y^T,X^T)|Y_0=y_0,X_1=x_1,A=a\right]$ does not depend on $a$, then \eqref{tauperp_hetero} also holds since $\nabla_{\eta}\ln \pi^*(a\,|\, y_0,x_1)$ has mean-zero conditional on $(y_0,x_1)$. We therefore conclude that \eqref{tauperp_hetero} is equivalent to
\begin{align*}
    &\mathbb{E}_{\theta,\omega^*}\left[\phi_{\theta}(Y^T,X^T)|Y_0=y_0,X_1=x_1,A=a\right] \\
    &=\int \phi_{\theta}(y^T,x^T)\prod_{t=1}^Tf_{\theta}(y_{t}\,|\, y_{t-1},x_{t},a)\prod_{t=2}^Tg^*(x_{t}\,|\, y^{t-1},x^{t-1},a)\mathrm{d}y^{1:T}\mathrm{d}x^{2:T} \\
    &=\int \phi_{\theta}(y^T,x^T)\prod_{t=1}^Tf_{\theta}(y_{t}\,|\, y_{t-1},x_{t},a)\mathrm{d}y^{1:T} \text{ (by \eqref{tauperp_feedback_bis} for $s=2$)}
\end{align*}
is a constant independent of $a$.  Hence, we can write
\begin{align}\label{tauperp_hetero_bis}
        \int \phi_{\theta}(y^T,x^T)\prod_{t=1}^Tf_{\theta}(y_{t}\,|\, y_{t-1},x_{t},a)\mathrm{d}y^{1:T}=\mathbb{E}_{\theta,\omega^*}\left[\phi_{\theta}(Y^T,X^T)|Y_0=y_0,X_1=x_1\right].
\end{align}
Next, we also note that \eqref{tauperp_initcond} can simply be rewritten as:
\begin{align*}
    0=\int \mathbb{E}_{\theta,\omega^*}\left[\phi_{\theta}(Y^T,X^T)|Y_0=y_0,X_1=x_1\right] \nabla_{\eta}\ln \nu^*(y_0,x_1) \nu^*(y_0,x_1)\mathrm{d}y_0\mathrm{d}x_1.
\end{align*}
Since $\nabla_{\eta}\ln \nu^*(y_0,x_1)$ is unrestricted besides being mean-zero and square-integrable, a similar reasoning to before implies that  \eqref{tauperp_initcond} is equivalent to $\mathbb{E}_{\theta,\omega^*}\left[\phi_{\theta}(Y^T,X^T)|Y_0=y_0,X_1=x_1\right]=\mathbb{E}_{\theta,\omega^*}\left[\phi_{\theta}(Y^T,X^T)\right]=0$. This result in combination with \eqref{tauperp_hetero_bis} implies that $\phi_{\theta}$ satisfies \eqref{eq_phi_hetero_robust}. 

\end{proof}

\subsection{Proof of Corollary \ref{coro_charact}}

   Assume \eqref{eq_phi_coro}. Then, since $\sum_{t=1}^{T-1}\psi_{\theta,t}(y^t,x^{t},a)$ does not depend on $x_T$, (\ref{eq_phi_feedback_robust}) holds for $s=T$. Next, integrating (\ref{eq_phi_coro}) with respect to $f_{\theta}(y_{T-1}\,|\, y_{T-2},x_{T-1},a)$ implies that
   \begin{align*}
       \int \phi_{\theta}(y^T,x^T) f_{\theta}(y_T\,|\, y_{T-1},x_{T-1},a)f_{\theta}(y_{T-1}\,|\, y_{T-2},x_{T-1},a)\mathrm{d}y^{T-1:T}=\sum_{t=1}^{T-2}\psi_{\theta,t}(y^t,x^{t},a),
   \end{align*}
   where we have used the fact that $\mathbb{E}\left[\psi_{\theta,T-1}(Y^{T-1},X^{T-1},A)\,|\,Y^{T-2},X^{T-1},A\right]=0$.  In particular, this implies  \eqref{eq_phi_feedback_robust} for $s=T-1$. Further integrating with respect to $f_{\theta}(y_{T-2}\,|\, y_{T-3},x_{T-2},a)$ then yields
    \begin{align*}
       \int  \phi_{\theta}(y^T,x^T)\prod_{t=T-2}^Tf_{\theta}(y_{t}\,|\, y_{t-1},x_{t},a)\mathrm{d}y^{T-2:T}=\sum_{t=1}^{T-3}\psi_{\theta,t}(y^t,x^{t},a),
   \end{align*}
   since $\mathbb{E}\left[\psi_{\theta,T-2}(Y^{T-2},X^{T-2},A)\,|\,Y^{T-3},X^{T-2},A\right]=0$. This implies (\ref{eq_phi_feedback_robust}) for $s=T-2$. Continuing this reasoning, we easily conclude that for $s=2,\ldots,T$,
      \begin{align*}
       \int  \phi_{\theta}(y^T,x^T)\prod_{t=s}^Tf_{\theta}(y_{t}\,|\, y_{t-1},x_{t},a)\mathrm{d}y^{s:T}=\sum_{t=1}^{s-1}\psi_{\theta,t}(y^t,x^{t},a),
   \end{align*}
   implying (\ref{eq_phi_feedback_robust}) for $s=2,\ldots,T$. Finally, since $\mathbb{E}\left[\psi_{\theta,1}(Y_0,Y_{1},X_{1},A)\,|\,Y_0,X_{1},A\right]=0$, integrating the identity 
   \begin{align*}
       \int  \phi_{\theta}(y^T,x^T)\prod_{t=2}^Tf_{\theta}(y_{t}\,|\, y_{t-1},x_{t},a)\mathrm{d}y^{2:T}=\psi_{\theta,1}(y_0,y_{1},x_{1},a)
   \end{align*}
   with respect to $f_{\theta}(y_{1}\,|\, y_{0},x_{1},a)$ yields (\ref{eq_phi_hetero_robust}). \\

 \noindent Conversely, suppose that (\ref{eq_phi_hetero_robust}) and \eqref{eq_phi_feedback_robust} hold. Equation \eqref{eq_phi_feedback_robust} for $s=T$ implies that we can write:
   \begin{align}
		&\int  \phi_{\theta}(y^T,x^T)f_{\theta}(y_{T}\,|\, y_{T-1},x_{T},a)\mathrm{d}y_{T}=\overline{\phi}_{\theta,T-1}\left(y^{T-1},x^{T-1},a\right),
\end{align}
for some function $\overline{\phi}_{\theta,T-1}\left(y^{T-1},x^{T-1},a\right)$ that does not depend on $x_T$. Then, \eqref{eq_phi_feedback_robust} for $s=T-1$ entails that:
\begin{align*}
    \mathbb{E}\left[\overline{\phi}_{\theta,T-1}\left(Y^{T-1},X^{T-1},A\right)\,|\,Y^{T-2},X^{T-1},A\right]=\overline{\phi}_{\theta,T-2}(Y^{T-2},X^{T-2},A)
\end{align*}
for some function $\overline{\phi}_{\theta,T-2}(Y^{T-2},X^{T-2},A)$ that does not depend on $X^{T-1:T}$. Equivalently, we can write:
\begin{align*}
    \overline{\phi}_{\theta,T-1}(Y^{T-1},X^{T-1},A)=\overline{\phi}_{\theta,T-2}(Y^{T-2},X^{T-2},A)+\psi_{\theta,T-1}(Y^{T-1},X^{T-1},A),
\end{align*}
with $\mathbb{E}\left[\psi_{\theta,T-1}(Y^{T-1},X^{T-1},A)\,|\,Y^{T-2},X^{T-1},A\right]=0$. Next, \eqref{eq_phi_feedback_robust} for $s=T-2$ implies that: 
\begin{align*}
    \overline{\phi}_{\theta,T-2}(Y^{T-2},X^{T-2},A)=\overline{\phi}_{\theta,T-3}(Y^{T-3},X^{T-3},A)+\psi_{\theta,T-2}(Y^{T-2},X^{T-2},A),
\end{align*}
for some function $\overline{\phi}_{\theta,T-3}(Y^{T-3},X^{T-3},A)$ that does not depend on $X^{T-2:T}$, with $\mathbb{E}\left[\psi_{\theta,T-2}(Y^{T-2},X^{T-2},A)\,|\,Y^{T-3},X^{T-2},A\right]=0$. Continuing this argument based on restriction \eqref{eq_phi_feedback_robust}, we conclude that, for $s=2,\ldots,T-1$,
\begin{align*}
    \overline{\phi}_{\theta,s}(Y^{s},X^{s},A)=\overline{\phi}_{\theta,s-1}(Y^{s-1},X^{s-1},A)+\psi_{\theta,s}(Y^{s},X^{s},A),
\end{align*}
such that  $\mathbb{E}\left[\psi_{\theta,s}(Y^{s},X^{s},A)\,|\,Y^{s-1},X^{s},A\right]=0$. Furthermore,  
\begin{align*}
    \overline{\phi}_{\theta,1}(Y_0,Y_{1},X_{1},A)=\psi_{\theta,1}(Y_0,Y_{1},X_{1},A),
\end{align*}
with $\mathbb{E}\left[\psi_{\theta,1}(Y_0,Y_{1},X_{1},A)\,|\,Y_0,X_1,A\right]=0$ by (\ref{eq_phi_hetero_robust}). Collecting terms, we have shown that 
   \begin{align*}
		&\int  \phi_{\theta}(y^T,x^T)f_{\theta}(y_{T}\,|\, y_{T-1},x_{T},a)\mathrm{d}y_{T}=\overline{\phi}_{\theta,T-1}(y^{T-1},x^{T-1},a)=\sum_{t=1}^{T-1} \psi_{\theta,t}(y^{t},x^{t},a),
\end{align*}
with the property that $\mathbb{E}\left[\psi_{\theta,t}(Y^{t},X^{t},A)\,|\,Y^{t-1},X^t,A\right]=0$ for $t=1,\ldots,T-1$. This coincides with \eqref{eq_phi_coro}.

