\section{Supplementary Lemma}\label{app: supplementary_lemmata}

\begin{lemma} \label{lemma_unique}
Let $T\geq 2$ and suppose that $\varphi_{\theta}^{1}(Y^T,X^T),\varphi_{\theta}^{2}(Y^T,X^T)$ are two $L\times 1$ square-integrable moment functions under $(\theta_0,\omega_{0})$ verifying \eqref{eq_varphi} as well as \eqref{eq_aveff} and \eqref{eq_aveff_feedback_robust} of Theorem \ref{theo_charact_aveff}. Then, $\Pi(\varphi_{\theta_0}^{1}(Y^T,X^T)\,|\,\mathcal{T}_{\theta_0,\omega_0,L})=\Pi(\varphi_{\theta_0}^{2}(Y^T,X^T)\,|\,\mathcal{T}_{\theta_0,\omega_0,L})$.
%satisfy the regularity conditions of Theorem \ref{theo_charact_aveff} and \eqref{eq_aveff}
%almost surely for any feedback process, $g\in\mathcal{G}$, distribution of heterogeneity, $\pi\in\Pi$, and distribution of initial conditions, $\nu\in\mathcal{N}$. 
\end{lemma}

\begin{proof}
    By assumption, $\phi_{\theta}\left(Y^{T},X^{T}\right)=\varphi_{\theta}^{1}(Y^T,X^T)-\varphi_{\theta}^{2}(Y^T,X^T)\in \mathcal{T}_{\theta_0,\omega_0,L}^{\perp}$ since it satisfies the conditions \eqref{eq_phi_hetero_robust}-\eqref{eq_phi_feedback_robust} of Theorem \ref{theo_charact}. Then, we can write
    \begin{align*}
        \varphi_{\theta}^{1}(Y^T,X^T)&=\varphi_{\theta}^{2}(Y^T,X^T)+\phi_{\theta}\left(Y_{0},Y^{T},X^{T}\right) \\
        &=\mu(\theta,\omega)+\Pi(\varphi_{\theta_0}^{2}(Y^T,X^T)\,|\,\mathcal{T}_{\theta_0,\omega_0,L})+\Pi(\varphi_{\theta_0}^{2}(Y^T,X^T)\,|\,\mathcal{T}_{\theta_0,\omega_0,L}^{\perp})+\phi_{\theta}\left(Y_{0},Y^{T},X^{T}\right).
    \end{align*}
    By linearity of $\mathcal{T}_{\theta_0,\omega_0,L}^{\perp}$, $\Pi(\varphi_{\theta_0}^{2}(Y^T,X^T)\,|\,\mathcal{T}_{\theta_0,\omega_0,L}^{\perp})+\phi_{\theta}\left(Y_{0},Y^{T},X^{T}\right)\in \mathcal{T}_{\theta_0,\omega_0,L}^{\perp}$. Therefore, standard properties of Hilbert spaces imply that $\Pi(\varphi_{\theta_0}^{1}(Y^T,X^T)\,|\,\mathcal{T}_{\theta_0,\omega_0,L})=\Pi(\varphi_{\theta_0}^{2}(Y^T,X^T)\,|\,\mathcal{T}_{\theta_0,\omega_0,L})$.
\end{proof}

\section{Calculations supporting the MPH results presented in main text}\label{app: MPH_derivations}



\subsection{Some useful distributional properties of the MPH model}

Our derivations of the results presented in the main text for the MPH model exploit a number of its special distributional properties.
Variants of these properties feature in prior work, for example that
of \cite{hahn1994efficiency} and \cite{Ridder_Woutersen_EM2003}. Our analysis requires these known implications of the MPH as well as several (apparently) new ones, specific to the feedback case. This section of the supplemental appendix derives and presents the needed preliminary results.

Recall the definitions $\rho_{\theta}\left(z_{t}\right)=\Lambda_{\alpha}\left(y_{t}\right)\exp\left(\gamma y_{t-1}+x_{t}'\beta\right)$
for $z_{t}=\left(y_{t-1},y_{t},x_{t}'\right)'$ and $P_{t}=\rho_{\theta}\left(Z_{t}\right)$
for $t=1,\ldots,T$ with $P_{t}=p_{t}=\rho_{\theta}\left(z_{t}\right)$ denoting -- when the context
is clear -- a \emph{specific} value of the random variable $P_{t}$. Unless there is a risk of confusion we omit the dependence of $P_t$ on $\theta$. The period $t$ conditional survival function equals
\begin{align}
\Pr\left(\left.Y_{t}>y_{t}\right|y^{t-1},x^{t},a\right)=S_{\theta}\left(\left.y_{t}\right|y^{t-1},x^{t},a\right) & =\exp\left(-\Lambda_{\alpha}\left(y_{t}\right)\exp\left(\gamma y_{t-1}+x_{t}'\beta+a\right)\right)\nonumber \\
 & =\exp\left(-\rho_{\theta}\left(z_{t}\right)e^{a}\right),\label{eq: mph_conditional_survival_function_y_t}
\end{align}
for $t=1,\ldots,T$. Using monotonicity of the integrated baseline
hazard and (\ref{eq: mph_conditional_survival_function_y_t}) we have
\begin{align}
\Pr\left(\left.P_{t}>p_{t}\right|y^{t-1},x^{t},a\right)= & \Pr\left(\left.Y_{t}>\Lambda_{\alpha}^{-1}\left(p_{t}\exp\left(-\gamma y_{t-1}-x_{t}'\beta\right)\right)\right|y^{t-1},x^{t},a\right)\nonumber \\
= & \exp\left(-\Lambda_{\alpha}\left(\Lambda_{\alpha}^{-1}\left(p_{t}\exp\left(-\gamma y_{t-1}-x_{t}'\beta\right)\right)\right)\exp\left(\gamma y_{t-1}+x_{t}'\beta+a\right)\right)\nonumber \\
= & \exp\left(-p_{t}e^{a}\right).\label{eq: mph_conditional_survival_function_rho_t}
\end{align}
Observe that (\ref{eq: mph_conditional_survival_function_rho_t})
is the survival function for an exponential random variable with rate
parameter $e^{a}$. Since the mapping from $y_{t}\rightarrow p_{t}$
is invertible we therefore have that
\[
\left.P_{t}\right|P^{t-1},X^{t},A\sim\mathrm{Exponential}\left(e^{A}\right),\ t=1,\ldots,T,
\]
and also that
\[
f\left(\left.x^{2:T},p^{1:T}\right|y_{0},x_{1},a\right)=\exp\left(Ta-\left(\sum_{t=1}^{T}p_{t}\right)e^{a}\right)\prod_{t=2}^{T}\widetilde{g}\left(\left.x_{t}\right|y_{0},p^{1:t-1},x^{t-1},a\right),
\]
where $\widetilde{g}\left(\left.x_{t}\right|y_{0},p^{1:t-1},x^{t-1},a\right)=g\left(\left.x_{t}\right|y_{0},y^{1:t-1},x^{t-1},a\right)$
for $p_{t}=\rho_{\theta}\left(z_{t}\right)$ and $t=1,\ldots,T$.
Integrating over $x^{2:T}$ gives the following lemma.
\begin{lemma}
\textsc{(Exponential Structure of the MPH Model)} \label{lem: P1_PT_are_exponential}For
the MPH model defined by Example \ref{ex: mph_intro} we have, for $t=1,\ldots,T$,
that (i) $\left.P_{t}\right|P^{t-1},X^{t},A\sim\mathrm{Exponential}\left(e^{A}\right)$
 and (ii) $\left.P_{t}\right|Y_{0},X_{1},A\overset{ind}{\sim}\mathrm{Exponential}\left(e^{A}\right)$. 
\end{lemma}
Our characterization of the set of FHR moments for the MPH model uses
a particular one-to-one transformation of $P^T$.
We next derive the properties of this transformation. Let $P_{t}\overset{ind}{\sim}\mathrm{Gamma}(\alpha_{t},\beta)$
for $t=1,\ldots,T$ and consider the bijective forward orthogonal
transformation $V^T=G\left(P^T\right)$:
\begin{align*}
V_{t} & =\frac{P_{t}}{\sum_{s=t}^{T}P_{s}},\ t=1,\ldots,T-1\\
V_{T} & =\sum_{t=1}^{T}P_{t},
\end{align*}
with an inverse given by $P^T=G^{-1}\left(V^T\right)$:
\begin{align*}
P_{1} & =V_{1}V_{T}\\
P_{t} & =\prod_{s=1}^{t-1}(1-V_{s})V_{t}V_{T},\ t=2,\ldots,T-1\\
P_{T} & =\prod_{s=1}^{T-1}(1-V_{s})V_{T}.
\end{align*}
By the change-of-variable formula, 
\begin{align*}
f_{V}(V_{1},V_{2},\ldots,V_{T}) & =f_{P_{1}}\left(V_{1}V_{T}\right)\prod_{t=2}^{T-1}f_{P_{t}}\left(\prod_{s=1}^{t-1}(1-V_{s})V_{t}V_{T}\right)f_{P_{T}}\left(\prod_{s=1}^{T-1}(1-V_{s})V_{T}\right)\left|\det\left(\dv{G^{-1}(V^T)}{V^T}\right)\right|.
\end{align*}
We shall show that: 
\begin{align}
V_{T}\sim & \mathrm{Gamma}\left(\sum_{t=1}^{T}\alpha_{t},\beta\right),\label{eq: gamma_beta_claim}\\
V_{t}\sim & \mathrm{Beta}\left(\alpha_{t},\sum_{s=t+1}^{T}\alpha_{s}\right),\quad t=1,\ldots,T-1,\nonumber 
\end{align}
with $(V_{1},V_{2},\ldots,V_{T-1},V_{T})$ additionally mutually independent
of one other. 

To this end, let $J^{(T)}(V_{1},\ldots,V_{T})=\det\left[\dv{G^{-1}(V^T)}{V^T}\right]$. In Subsection \ref{app: detailed calculations} we establish that:
\begin{equation} \label{eq: det_for_rho_tilde_rho_bar_change_of_variables}
    J^{(T)}(V_{1},\ldots,V_{T}) = V_{T}^{T-1}\prod_{s=1}^{T-2}(1-V_{s})^{T-(s+1)}.
\end{equation}


Applying the change-of-variables formula then yields, as we show in Subsection \ref{app: detailed calculations},
\begin{align}\label{eq: density_of_rho_tilde_rho_bar}
     f_{V}\left(V_{1},V_{2},\ldots,V_{T}\right) = & \frac{\beta^{\sum_{t=1}^{T}\alpha_{t}}}{\Gamma\left(\sum_{t=1}^{T}\alpha_{t}\right)}V_{T}^{\sum_{t=1}^{T}\alpha_{t}-1}e^{-\beta V_{T}}\\
    & \times\prod_{t=1}^{T-1}\frac{\Gamma\left(\sum_{s=t}^{T}\alpha_{s}\right)}{\Gamma\left(\alpha_{t}\right)\Gamma\left(\sum_{s=t+1}^{T}\alpha_{s}\right)}V_{t}^{\alpha_{t}-1}(1-V_{t})^{\sum_{s=t+1}^{T}\alpha_{s}-1},
\end{align}
from which claim \eqref{eq: gamma_beta_claim} immediately follows. This result, in combination
with Lemma \ref{lem: P1_PT_are_exponential} above gives, for $\widetilde{P}_{t}$
for $t=1,\ldots,T-1$ and $\overline{P}$ as defined in the main text,
the following lemma.
\begin{lemma}
\textsc{(``Helmert Transformation'' for the MPH Model) }\label{lem: helmert_tranformation_MPH} For
the MPH model defined by Example \ref{ex: mph_intro} we have, conditional on $Y_{0},X_{1}$
and $A$, (i)
\begin{align*}
\widetilde{P}_{t} & \sim\mathrm{Beta}\left(1,T-t\right),\quad t=1,\ldots,T-1,\\
\overline{P} & \sim\mathrm{Gamma}\left(T,e^{A}\right),
\end{align*}
with (ii) $(\widetilde{P}_{1},\widetilde{P}_{2},\ldots,\widetilde{P}_{T-1},\overline{P})$
additionally mutually independent of one another.
\end{lemma}

\subsection{Proof of Lemma \ref{lem_moment_charac_MPH}}
Recall the bijective transformation between $(y_{1},\ldots,y_{T})$
and $(p_{1},\ldots,p_{T})$ given by 
\begin{align*}
p_{t}=\Lambda_{\alpha}(y_{t})e^{\gamma y_{t-1}+x_{t}'\beta},\quad t=1,\ldots,T,
\end{align*}
as well as the second (bijective) transformation between $(p_{1},\ldots,p_{T})$
and $(\widetilde{p}_{1},\ldots,\widetilde{p}_{T-1},\overline{p})$
given by 
\begin{align*}
\widetilde{p}_{t} & =\frac{p_{t}}{\sum_{s=t}^{T}p_{s}},\quad t=1,\ldots,T-1,\\
\overline{p} & =\sum_{t=1}^{T}p_{t}.
\end{align*}
The distribution of $\left(P_{1},\ldots,P_{T}\right)$ is stated in
Lemma \ref{lem: P1_PT_are_exponential} and that of $(\widetilde{P}_{1},\ldots,\widetilde{P}_{T-1},\overline{P})$
in Lemma \ref{lem: helmert_tranformation_MPH}.

From these two bijections we get the following two equivalent representations
of $\phi_{\theta}$: 
\begin{align}
\xi_{\theta}(y_{0},p^{T},x^{T})= & \phi_{\theta}\left(y_{0},\Lambda_{\alpha}^{-1}(p_{1}\exp(-\gamma y_{0}-x_{1}'\beta)),\right.\notag \\
& \left.\ldots,\Lambda_{\alpha}^{-1}(p_{T}\exp(-\gamma y_{T-1}-x_{T}'\beta)),x^{T}\right)\label{eq: phi_in_terms_of_rho}\\
\psi_{\theta}(y_{0},\widetilde{p}^{T-1},\overline{p},x^{T})= & \xi_{\theta}(y_{0},\widetilde{p}_{1}\overline{p},(1-\widetilde{p}_{1})\widetilde{p}_{2}\overline{p},\ldots,\prod_{s=1}^{T-2}(1-\widetilde{p}_{s})\widetilde{p}_{T-1}\overline{p},\prod_{s=1}^{T-1}(1-\widetilde{p}_{s})\overline{p},x^{T}).\label{eq: phi_in_terms_rho_tilde_bar}
\end{align}

In the present context, condition (\ref{eq_phi_feedback_robust})
of Theorem \ref{theo_charact} for $s=T$ corresponds to a requirement on (\ref{eq: phi_in_terms_of_rho})
of
\begin{align*}
\int_{0}^{+\infty}\xi_{\theta}(y_{0},p^{T},x^{T})e^{a}e^{-e^{a}p_{T}}\mathrm{d}p_{T}\text{ does not depend on }x_{T},
\end{align*}
where we have used the change of variable, $p_{T}=\Lambda_{\alpha}\left(y_{T}\right)\exp\left(\gamma y_{T-1}+x_{T}'\beta\right)$
(see Lemma \ref{lem: P1_PT_are_exponential}). This implies that $\mathcal{L}[p_{T}\mapsto\xi_{\theta}(y_{0},p^{T-1},p_{T},x^{T-1},x_{T})][e^{a}]=\mathcal{L}[p_{T}\mapsto\xi_{\theta}(y_{0},p^{T-1},p_{T},x^{T-1},\widetilde{x}_{T})][e^{a}]$
for any $\widetilde{x}_{T}$, where ${\cal{L}}$ denotes the Laplace transform operator. By the uniqueness of the Laplace transform,
it follows that $\xi_{\theta}(y_{0},p^{T-1},p_{T},x^{T-1},x_{T})=\xi_{\theta}(y_{0},p^{T-1},p_{T},x^{T-1},\widetilde{x}_{T})$,
meaning that $\xi_{\theta}$ does not depend on $x_{T}$. Hereafter we therefore suppress the dependence of $\phi_{\theta},\xi_{\theta},\psi_{\theta}$
on $x_{T}$. 

Next, consider the decomposition 
\begin{align*}
 & \psi_{\theta}(Y_{0},\widetilde{P}^{T-1},\overline{P},X^{T-1})=\\
 & \left(\psi_{\theta}(Y_{0},\widetilde{P}^{T-1},\overline{P},X^{T-1})-\mathbb{E}\left[\left.\psi_{\theta}(Y_{0},\widetilde{P}^{T-1},\overline{P},X^{T-1})\right|Y_{0},\widetilde{P}^{T-2},\overline{P},X^{T-1}\right]\right)\\
 & +\left(\mathbb{E}\left[\left.\psi_{\theta}(Y_{0},\widetilde{P}^{T-1},\overline{P},X^{T-1})\right|Y_{0},\widetilde{P}^{T-2},\overline{P},X^{T-1}\right]-\mathbb{E}\left[\left.\psi_{\theta}(Y_{0},\widetilde{P}^{T-1},\overline{P},X^{T-1})\right|Y_{0},\widetilde{P}^{T-3},\overline{P},X^{T-2}\right]\right)\\
 & +\left(\mathbb{E}\left[\left.\psi_{\theta}(Y_{0},\widetilde{P}^{T-1},\overline{P},X^{T-1})\right|Y_{0},\widetilde{P}^{T-3},\overline{P},X^{T-2}\right]-\mathbb{E}\left[\left.\psi_{\theta}(Y_{0},\widetilde{P}^{T-1},\overline{P},X^{T-1})\right|Y_{0},\widetilde{P}^{T-4},\overline{P},X^{T-3}\right]\right)\\
 & \vdots\\
 & +\mathbb{E}\left[\left.\psi_{\theta}(Y_{0},\widetilde{P}^{T-1},\overline{P},X^{T-1})\right|Y_{0},\widetilde{P}_{1},\overline{P},X^{2}\right],
\end{align*}
or, succinctly, 
\begin{align*}
\psi_{\theta}(Y_{0},\widetilde{P}^{T-1},\overline{P},X^{T-1})=\sum_{t=1}^{T-2}\psi_{\theta,t}(Y_{0},\widetilde{P}^{t},\overline{P},X^{t+1})+\psi_{\theta,T-1}(Y_{0},\widetilde{P}^{T-1},\overline{P},X^{T-1}),
\end{align*}
where 
\begin{align*}
\psi_{\theta,T-1}(Y_{0},\widetilde{P}^{T-1},\overline{P},X^{T-1}) & =\psi_{\theta}(Y_{0},\widetilde{P}^{T-1},\overline{P},X^{T-1})-\mathbb{E}\left[\left.\psi_{\theta}(Y_{0},\widetilde{P}^{T-1},\overline{P},X^{T-1})\right|Y_{0},\widetilde{P}^{T-2},\overline{P},X^{T-1}\right],
\end{align*}
for all $t=2,\ldots,T-2$,
\begin{multline*}
\psi_{\theta,t}\left(Y_{0},\widetilde{P}^{t},\overline{P},X^{t+1}\right)\\
=\mathbb{E}\left[\left.\psi_{\theta}(Y_{0},\widetilde{P}^{T-1},\overline{P},X^{T-1})\right|Y_{0},\widetilde{P}^{t},\overline{P},X^{t+1}\right]-\mathbb{E}\left[\left.\psi_{\theta}(Y_{0},\widetilde{P}^{T-1},\overline{P},X^{T-1})\right|Y_{0},\widetilde{P}^{t-1},\overline{P},X^{t}\right],
\end{multline*}
 and 
\begin{align*}
\psi_{\theta,1}(Y_{0},\widetilde{P}_{1},\overline{P},X^{2}) & =\mathbb{E}\left[\left.\psi_{\theta}(Y_{0},\widetilde{P}^{T-1},\overline{P},X^{T-1})\right|Y_{0},\widetilde{P}_{1},\overline{P},X^{2}\right].
\end{align*}
The law of iterated expectations readily implies
that: 
\begin{align*}
 & \mathbb{E}\left[\left.\psi_{\theta,T-1}(Y_{0},\widetilde{P}^{T-1},\overline{P},X^{T-1})\right|Y_{0},\widetilde{P}^{T-2},\overline{P},X^{T-1}\right]=0,\\
 & \mathbb{E}\left[\left.\psi_{\theta,t}(Y_{0},\widetilde{P}^{t},\overline{P},X^{t+1})\right|Y_{0},\widetilde{P}^{t-1},\overline{P},X^{t}\right]=0,\quad t=2,\ldots,T-2.
\end{align*}
It only remains to show that (i) for all $t=1,\ldots,T-1$, $\psi_{\theta,t}(Y_{0},\widetilde{P}^{t},\overline{P},X^{t+1})$
does not depend on $X_{t+1}$ and (ii) 
\begin{align*}
\mathbb{E}\left[\left.\psi_{\theta}(Y_{0},\widetilde{P}^{T-1},\overline{P},X^{T-1})\right|Y_{0},\overline{P},X_{1}\right]=0.
\end{align*}
We start by establishing (i). To that end, fix any $s\in\{2,\ldots,T-1\}$.
By Theorem \ref{theo_charact} equation (\ref{eq_phi_feedback_robust}),
we have 
\begin{align*}
\int_{0}^{\infty}\xi_{\theta}(y_{0},p^{T},x^{T-1})e^{a}e^{-e^{a}\sum_{t=s}^{T}p_{t}}\mathrm{d}p^{s:T}\text{ does not depend on }x^{s:T},
\end{align*}
using the change of variables, $p_{t}=\Lambda_{\alpha}\left(y_{t}\right)\exp\left(\gamma y_{t-1}+x_{t}'\beta\right)$
for $t=s,\ldots,T$. Next, recall that $\widetilde{p}_{t}=\frac{p_{t}}{\sum_{k=t}^{T}p_{k}},\quad t=s,\ldots,T-1$,
and introduce $\overline{p}_{s}=\sum_{k=s}^{T}p_{k}$. By Lemma \ref{lem: helmert_tranformation_MPH}
and a second change of variables, the previous condition is equivalent
to 
\begin{align*}
\int_{0}^{\infty}\Upsilon_{\theta}(y_{0},p^{s-1},\overline{p}_{s},x^{T-1})\frac{e^{(T-s+1)a}}{\Gamma(T-s+1)}\left(\overline{p}_{s}\right)^{T-s}e^{-e^{a}\overline{p}_{s}}\mathrm{d}\overline{p}_{s}\text{ does not depend on }x^{s:T},
\end{align*}
where 
\begin{align*}
\Upsilon_{\theta}(y_{0},p^{s-1},\overline{p}_{s},x^{T-1}) & =\int_{0}^{1}\xi_{\theta}(y_{0},p^{s-1},\widetilde{p}_{s}\overline{p}_{s},(1-\widetilde{p}_{s})\widetilde{p}_{s+1}\overline{p}_{s},\ldots,\prod_{k=s}^{T-2}(1-\widetilde{p}_{k})\widetilde{p}_{T-1}\overline{p}_{s},\prod_{k=s}^{T-1}(1-\widetilde{p}_{k})\overline{p}_{s},x^{T-1})\\
 & \times\prod_{t=s}^{T-1}\frac{\Gamma(T-t+1)}{\Gamma(T-t)}(1-\widetilde{p}_{t})^{T-t-1}\mathrm{d}\widetilde{p}^{s:T-1}.
\end{align*}
Hence, 
\begin{align*}
\mathcal{L}[\overline{p}_{s}\mapsto\left(\overline{p}_{s}\right)^{T-s}\Upsilon_{\theta}(y_{0},p^{s-1},\overline{p}_{s},x^{s-1},x^{s:T-1})][e^{a}]=\mathcal{L}[\overline{p}_{s}\mapsto\left(\overline{p}_{s}\right)^{T-s}\Upsilon_{\theta}(y_{0},p^{s-1},\overline{p}_{s},x^{s-1},\widetilde{x}^{s:T-1})][e^{a}],
\end{align*}
for any possible values $\widetilde{x}^{s:T-1}$. By uniqueness of the
Laplace transform, we conclude that $\Upsilon_{\theta}$ does not
depend on $x^{s:T-1}$. Since there is a bijective transformation
between $(p^{s-1},\overline{p}_{s})$ and $(\widetilde{p}^{s-1},\overline{p})$
given by $\widetilde{p}_{t}=\frac{p_{t}}{\sum_{k=t}^{s-1}p_{k}+\overline{p}_{s}},\quad t=1,\ldots,s-1$,
and $\overline{p}=\sum_{k=1}^{s-1}p_{k}+\overline{p}_{s}$, we have: 
\begin{align*}
\Upsilon_{\theta}(y_{0},p^{s-1},\overline{p}_{s},x^{T-1}) & =\int_{0}^{1}\psi_{\theta}(y_{0},\widetilde{p}^{T-1},\overline{p},x^{T-1})\prod_{t=s}^{T-1}\frac{\Gamma(T-t+1)}{\Gamma(T-t)}(1-\widetilde{p}_{t})^{T-t-1}\mathrm{d}\widetilde{p}^{s:T-1}\\
 & =\mathbb{E}\left[\left.\psi_{\theta}(Y_{0},\widetilde{P}^{T-1},\overline{P},X^{T-1})\right|Y_{0}=y_{0},\widetilde{P}^{s-1}=\widetilde{p}^{s-1},\overline{P}=\overline{p},X^{s}=x^{s}\right],
\end{align*}
which does not depend on $x^{s:T-1}$. The second equality follows from the fact that the ``forward orthogonal transforms'' $\widetilde{P}^{s:T-1}$ are independent of $\widetilde{P}^{s-1},\overline{P},X^{s}$ by part (i) of Lemma \ref{lem: P1_PT_are_exponential} and Lemma \ref{lem: helmert_tranformation_MPH}. This shows that, for $s\in\{3,\ldots,T-1\}$,
\begin{multline*}
\psi_{\theta,s-1}(Y_{0},\widetilde{P}^{s-1},\overline{P},X^{s})\\
=\mathbb{E}\left[\left.\psi_{\theta}(Y_{0},\widetilde{P}^{T-1},\overline{P},X^{T-1})\right|Y_{0},\widetilde{P}^{s-1},\overline{P},X^{s}\right]-\mathbb{E}\left[\left.\psi_{\theta}(Y_{0},\widetilde{P}^{T-1},\overline{P},X^{T-1})\right|Y_{0},\widetilde{P}^{s-2},\overline{P},X^{s-1}\right]
\end{multline*}
does not depend on $X^{s:T}$, and that, for $s=2$ 
\begin{align*}
\psi_{\theta,1}(Y_{0},\widetilde{P}_{1},\overline{P},X^{2})=\mathbb{E}\left[\left.\psi_{\theta}(Y_{0},\widetilde{P}^{T-1},\overline{P},X^{T-1})\right|Y_{0},\widetilde{P}_{1},\overline{P},X^{2}\right]
\end{align*}
does not depend on $X^{2:T}$. This proves (i). 

Finally, by Theorem \ref{theo_charact} equation (\ref{eq_phi_hetero_robust}),
we have 
\begin{align*}
\int_{0}^{\infty}\xi_{\theta}(y_{0},p^{T},x^{T-1})e^{a}e^{-e^{a}\sum_{t=1}^{T}p_{t}}\mathrm{d}p^{T}=0,
\end{align*}
where we have once more used the transformation $p_{t}=\Lambda_{\alpha}\left(y_{t}\right)\exp\left(\gamma y_{t-1}+x_{t}'\beta\right)$
for $t=1,\ldots,T$. Consider now, $\widetilde{p}_{t}=\frac{p_{t}}{\sum_{k=t}^{T}p_{k}},\quad t=1,\ldots,T-1$
and $\overline{p}=\sum_{k=1}^{T}p_{k}$. By Lemma \ref{lem: helmert_tranformation_MPH}
and a second change of variables, the previous condition is equivalent
to 
\begin{align*}
\int_{0}^{\infty}\Upsilon_{\theta}(y_{0},\overline{p},x^{T-1})\frac{e^{Ta}}{\Gamma(T)}\overline{p}^{T-1}e^{-e^{a}\overline{p}}\mathrm{d}\overline{p}=0,
\end{align*}
where now $\Upsilon_{\theta}(y_{0},\overline{p},x^{T-1})=\left(\int_{0}^{1}\psi_{\theta}(y_{0},\widetilde{p}^{T-1},\overline{p},x^{T-1})\prod_{t=1}^{T-1}\frac{\Gamma(T-t+1)}{\Gamma(T-t)}(1-\widetilde{p}_{t})^{T-t-1}\mathrm{d}\widetilde{p}^{T-1}\right)$.
Hence, 
\begin{align*}
\mathcal{L}[\overline{p}\mapsto\overline{p}^{T-1}\Upsilon_{\theta}(y_0,\overline{p},x^{T-1})][e^{a}]=0,
\end{align*}
which by uniqueness of the Laplace transform implies that 
\begin{align*}
0=\Upsilon_{\theta}(Y_0,\overline{P},X^{T-1})=\mathbb{E}\left[\left.\psi_{\theta}(Y_{0},\widetilde{P}^{T-1},\overline{P},X^{T-1})\right|Y_{0},\overline{P},X_{1}\right],
\end{align*}
where the second equality is again a consequence of Lemma \ref{lem: helmert_tranformation_MPH}. This establishes (ii) which finally yields the desired representation.  \\



