\subsection{Semiparametric efficiency bounds for the MPH model}

Here we present our semiparametric efficiency bound derivations for the MPH model. Our calculations exploit Lemma \ref{lem_moment_charac_MPH} and Theorem \ref{theo_eff} of the main text. In order to compute the efficient score for the MPH using equation \eqref{eq_effscore} in the main text, the following lemma is useful.
\begin{lemma}  \label{proj_lemma_MPH}
\textsc{(MPH Projection)}
    For any $L\times 1$ mean-zero random vector $\varphi_{\theta}(Y^{T},X^T)$ such that $\mathbb{E}\left[\norm{\varphi_{\theta}(Y^{T},X^T)}^2\right]<\infty$, we have
    \begin{align*}
        \Pi(\varphi_{\theta}(Y^{T},X^T)|\mathcal{T}_{\theta,\omega,L}^{\perp})&=\sum_{t=1}^{T-1}\varphi_{\theta,t}^{\perp}(Y_0,\widetilde{P}^{t},\overline{P},X^{t}),
    \end{align*}
    with
    \begin{multline*}
        \varphi_{\theta,t}^{\perp}(Y_0,\widetilde{P}^{t},\overline{P},X^{t}) = \mathbb{E}\left[\varphi_{\theta}(Y^{T},X^T)|Y_0,\widetilde{P}^{t},\overline{P},X^{t}\right] 
        -\mathbb{E}\left[\varphi_{\theta}(Y^{T},X^T)|Y_0,\widetilde{P}^{t-1},\overline{P},X^{t}\right].
    \end{multline*}
\end{lemma}
\begin{proof}
First, we note that by iterated expectations,
\begin{align*}
    \mathbb{E}\left[\varphi_{\theta,t}^{\perp}(Y_0,\widetilde{P}^{t},\overline{P},X^{t})|Y_0,\widetilde{P}^{t-1},\overline{P},X^{t}\right]=0.
\end{align*}
Thus, Lemma \ref{lem_moment_charac_MPH} and Theorem \ref{theo_eff} imply that $\sum_{t=1}^{T-1}\varphi_{\theta,t}^{\perp}(Y_0,\widetilde{P}^{t},\overline{P},X^{t})$
is an element of $\mathcal{T}_{\theta,\omega,L}^{\perp}$. Next fix $s,t\in\{1,\ldots,T-1\}$ and consider any function $\psi_{\theta,s}(Y_0,\widetilde{P}^{s},\overline{P},X^{s})\in \mathcal{T}_{\theta,\omega,L}^{\perp}$ such that
\begin{align*}
    \mathbb{E}\left[\psi_{\theta,s}(Y_0,\widetilde{P}^{s},\overline{P},X^{s})|Y_0,\widetilde{P}^{s-1},\overline{P},X^{s}\right]=0.
\end{align*}
Observe that if $s>t$
\begin{align*}
    &\mathbb{E}\left[\varphi_{\theta,t}^{\perp}(Y_0,\widetilde{P}^{t},\overline{P},X^{t})'\psi_{\theta,s}(Y_0,\widetilde{P}^{s},\overline{P},X^{s})\right] \\
    &= \mathbb{E}\left[\varphi_{\theta,t}^{\perp}(Y_0,\widetilde{P}^{t},\overline{P},X^{t})' \mathbb{E}\left[\psi_{\theta,s}(Y_0,\widetilde{P}^{s},\overline{P},X^{s})|Y_0,\widetilde{P}^{s-1},\overline{P},X^{s}\right]\right] \\
    &=0.
\end{align*}
Symmetrically, if $t>s$, 
\begin{align*}
    \mathbb{E}\left[\varphi_{\theta,t}^{\perp}(Y_0,\widetilde{P}^{t},\overline{P},X^{t})'\psi_{\theta,s}(Y_0,\widetilde{P}^{s},\overline{P},X^{s})\right]=0,
\end{align*}
since by construction $\mathbb{E}\left[\varphi_{\theta,t}^{\perp}(Y_0,\widetilde{P}^{t},\overline{P},X^{t})|Y_0,\widetilde{P}^{t-1},\overline{P},X^{t}\right]=0$. Using these observations we can show:
\begin{align*}
    \mathbb{E}&\left[\left(\varphi_{\theta}(Y^{T},X^T) -\sum_{t=1}^{T-1}\varphi_{\theta,t}^{\perp}(Y_0,\widetilde{P}^{t},\overline{P},X^{t})\right)'\psi_{\theta,s}\left( 
    Y_0,\widetilde{P}^{s},\overline{P},X^{s}\right)\right] \\
    =&\mathbb{E}\left[\left(\varphi_{\theta}(Y^{T},X^T)-\varphi_{\theta,s}^{\perp}(Y_0,\widetilde{P}^{s},\overline{P},X^{s})\right)'\psi_{\theta,s}\left(Y_0,\widetilde{P}^{s},\overline{P},X^{s}\right)\right] \\
     =&\mathbb{E}\left[\left(\varphi_{\theta}(Y^{T},X^T)-\mathbb{E}\left[\varphi_{\theta}(Y^{T},X^T)|Y_0,\widetilde{P}^{s},\overline{P},X^{s}\right]\right)'\psi_{\theta,s}\left(Y_0,\widetilde{P}^{s},\overline{P},X^{s}\right)\right] \\
     &+\mathbb{E}\left[\mathbb{E}\left[\varphi_{\theta}(Y^{T},X^T)|Y_0,\widetilde{P}^{s-1},\overline{P},X^{s}\right]'\psi_{\theta,s}\left(Y_0,\widetilde{P}^{s},\overline{P},X^{s}\right)\right] \\
     =&0,
\end{align*}
where the second equality uses the definition of $\varphi_{\theta,t}^{\perp}(Y_0,\widetilde{P}^{t},\overline{P},X^{t})$ given in the statement of the Lemma and where the last line follows from iterated expectations and the fact that $\mathbb{E}\left[\psi_{\theta,s}(Y_0,\widetilde{P}^{s},\overline{P},X^{s})|Y_0,\widetilde{P}^{s-1},\overline{P},X^{s}\right]=0$.
Since by Lemma \ref{lem_moment_charac_MPH} and Theorem \ref{theo_eff}, any function of $\mathcal{T}_{\theta,\omega,L}^{\perp}$ is of the form:
\begin{align*}
    \psi_{\theta}(Y_{0},\widetilde{P}^{T-1},\overline{P},X^{T-1})=\sum_{t=1}^{T-1}\psi_{\theta,t}(Y_0,\widetilde{P}^{t},\overline{P},X^{t}),
\end{align*}
with $ \mathbb{E}\left[\left.\psi_{\theta,t}(Y_{0},\widetilde{P}^{t},\overline{P},X^{t})\right|Y_{0},\widetilde{P}^{t-1},\overline{P},X^{t}\right]=0, \quad t=1,\ldots,T-1$, these calculations show that 
\begin{align*}
        &\mathbb{E}\left[\left(\varphi_{\theta}(Y^{T},X^T)-\sum_{t=1}^{T-1}\varphi_{\theta,t}^{\perp}(Y_0,\widetilde{P}^{t},\overline{P},X^{t})\right)\psi_{\theta}(Y_{0},\widetilde{P}^{T-1},\overline{P},X^{T-1})\right]=0.
\end{align*}
By the Projection Theorem (e.g Theorem 11.1 in \cite{van2000asymptotic}) we conclude that, 
\begin{align*}
     \Pi(\varphi_{\theta}(Y_0,Y^{T},X^T)|\mathcal{T}_{\theta,\omega,L}^{\perp})&=\sum_{t=1}^{T-1}\varphi_{\theta,t}^{\perp}(Y_0,\widetilde{P}^{t},\overline{P},X^{t}),
\end{align*}
as claimed.
\end{proof}
\subsubsection{MPH efficient score under feedback}
We can use Lemma \ref{proj_lemma_MPH} to derive an explicit expression of the efficient score for $\theta=\left(\alpha,\beta',\gamma\right)'$. Given the historical and continued importance of the MPH model, the required calculations, although involved and tedious, are presented in detail here.

Recall the form the integrated likelihood for the semiparametric panel data model with feedback presented in equation (\ref{eq: feedback_complete_data_likelihood}) of the main text. The form of the parametric period $t$ panel data model equals, in the MPH setting,
\begin{equation*}
    f_{\theta}(y_t|x_t,y_{t-1},a)=\lambda_{\alpha}\left(y_{t}\right)\exp\left(\gamma y_{t-1}+x_{t}'\beta+a\right)\exp\left(-\rho_{\theta}\left(z_{t}\right)e^a\right).
\end{equation*}
Further recall the notation: $P_t= \rho_{\theta}\left(Z_{t}\right)=\Lambda_{\alpha}\left(Y_{t}\right)e^{\gamma Y_{t-1}+X_{t}'\beta}$ (when evaluated at population value $\theta=\theta_0$). The (submodel) score for $\theta$ equals
 \begin{align*}
     S^{\theta}(Y^T,X^T) = \mathbb{E}\left[\sum_{t=1}^T \frac{\partial \ln f_{\theta}(Y_t\,|\, Y_{t-1},X_t,A)}{\partial \theta}\,|\, Y^T,X^T\right].
 \end{align*}
By Theorem \ref{theo_eff} and Lemma \ref{proj_lemma_MPH} the efficient score, when $T=2$, equals
\begin{align} \label{eq: eff_score_MPH_feedback_general_T=2}
        \phi_{\theta}^{\rm eff}(Y^2,X^2)=\mathbb{E}\left[S^{\theta}(Y^2,X^2)\,|\,Y_{0},\widetilde{P}_{1},\overline{P},X_{1}\right]-\mathbb{E}\left[S^{\theta}(Y^2,X^2)\,|\,Y_{0},\overline{P},X_{1}\right],    
\end{align}
while, in the general $T\geq 2$ case, it equals
\begin{align*}
    \phi_{\theta}^{\rm eff}(Y^T,X^T)&=\sum_{t=1}^{T-1}\phi_{\theta,t}^{\rm eff, \perp}(Y_0,\widetilde{P}^{1:t},\overline{P},X^{1:t}), 
\end{align*}
with, for $t=1,\ldots,T-1$,
\begin{multline}
    \phi_{\theta,t}^{\rm eff, \perp}(Y_0,\widetilde{P}^{1:t},\overline{P},X^{1:t}) \\
    = \mathbb{E}\left[S^{\theta}(Y^T,X^T)|Y_0,\widetilde{P}^{1:t},\overline{P},X^{1:t}\right]-\mathbb{E}\left[S^{\theta}(Y^T,X^T)|Y_0,\widetilde{P}^{1:t-1},\overline{P},X^{1:t}\right].
\end{multline}
In what follows we focus on the $T=2$ special case for simplicity (and because it is this case we study in the numerical experiments reported in Section \ref{sec: mph_deep_dive} of the main text). The calculations proceed by evaluating -- and simplifying as far as appears to be feasible -- equation \eqref{eq: eff_score_MPH_feedback_general_T=2} above.
We do this separately for $\beta$, $\gamma$ and $\alpha$. Our efficient score expression for $\beta$ holds for any baseline hazard, those we present for $\gamma$ and $\alpha$ assume that the baseline hazard takes the Weibull form: $\lambda_{\alpha}(y_t)=\alpha y_{t}^{\alpha-1}$. The calculations presented below can be adapted to study semiparametric efficiency bounds under other maintained baseline hazard assumptions.

\textbf{The efficient score for $\beta$: } The (submodel) score for $\beta$, recalling the notation re-established immediately above, equals:
\begin{align}
		S^{\beta}(Y^T,X^T)&=\mathbb{E}\left[\sum_{t=1}^T \frac{\partial \ln f_{\theta}(Y_t\,|\, Y_{t-1},X_t,A)}{\partial \beta}\,|\, Y^T,X^T\right] \label{eq: submodel_beta_score_MPH} \\
		&=\mathbb{E}\left[\sum_{t=1}^T X_{t}\left(1-P_t e^{a}\right)\,|\,Y^T,X^T\right] \notag \\
  &=\sum_{t=1}^T X_t-\sum_{t=1}^T X_tP_t\mathbb{E}\left[e^{A}\,|\, Y^T,X^T\right], \notag
\end{align}
which, when $T=2$, coincides with
\begin{align*}
		S^{\beta}(Y^2,X^2)&= X_{1}+X_{2}-\left(X_1P_1+X_2P_2\right)\mathbb{E}\left[e^{A}\,|\, Y^2,X^2\right].
\end{align*}
Reparameterizing in terms of $\widetilde{P}_1$ and $\overline{P}$ yields the equivalent expression
\begin{align*}
		S^{\beta}(Y^2,X^2)&= X_{1}+X_{2}-\left(X_1\widetilde{P}_1\overline{P}+X_2(1-\widetilde{P}_1)\overline{P}\right)\mathbb{E}\left[e^{A}\,|\, Y_0,\widetilde{P}_1,\overline{P},X^2\right].
\end{align*}
The efficient score for $\beta$, from equation \eqref{eq: eff_score_MPH_feedback_general_T=2} above, equals
\begin{align}
   \phi_{\theta}^{\rm eff,\beta}(Y^2,X^2)=\mathbb{E}\left[S^{\beta}(Y^2,X^2)|Y_0,\widetilde{P}_1,\overline{P},X_1\right]-\mathbb{E}\left[S^{\beta}(Y^2,X^2)|Y_0,\overline{P},X_1\right].\label{eq: efficient_score_beta_general_T=2}
\end{align}
We evaluate the two expectations to the right of the equality above in sequence. First,
\begin{align*}
    &\mathbb{E}\left[S^{\beta}(Y^2,X^2)|Y_0,\widetilde{P}_1,\overline{P},X_1\right]\\
    &=X_{1}+\mathbb{E}\left[X_{2}|Y_0,\widetilde{P}_1,\overline{P},X_1\right]-X_1\widetilde{P}_1\overline{P}\mathbb{E}\left[e^{A}\,|\, Y_0,\overline{P},X_1\right]-(1-\widetilde{P}_1)\overline{P}\mathbb{E}\left[X_2e^{A}\,|\, Y_0,\widetilde{P}_1,\overline{P},X_1\right].
\end{align*}
Second, and making use of Lemma \ref{lem: helmert_tranformation_MPH} when evaluating expectations over $\widetilde{P}_1$,
\begin{align*}
    &\mathbb{E}\left[S^{\beta}(Y^2,X^2)|Y_0,\overline{P},X_1\right]\\
    &=X_{1}+\mathbb{E}\left[X_{2}|Y_0,\overline{P},X_1\right]-X_1\overline{P}\mathbb{E}\left[\widetilde{P}_1e^{A}\,|\, Y_0,\overline{P},X_1\right]-\overline{P}\mathbb{E}\left[X_2(1-\widetilde{P}_1)e^{A}\,|\, Y_0,\overline{P},X_1\right] \\
    &=X_{1}+\mathbb{E}\left[X_{2}|Y_0,\overline{P},X_1\right]-\frac{1}{2}X_1\overline{P}\mathbb{E}\left[e^{A}\,|\, Y_0,\overline{P},X_1\right]-\overline{P}\mathbb{E}\left[X_2(1-\widetilde{P}_1)e^{A}\,|\, Y_0,\overline{P},X_1\right]. 
\end{align*}
Collecting terms we get an efficient score for $\beta$ of
\begin{align*}
    \phi_{\theta}^{\rm eff,\beta}(Y^2,X^2)&=-X_1\left(\widetilde{P}_1-\frac{1}{2}\right)\overline{P}\mathbb{E}\left[e^{A}\,|\, Y_0,\overline{P},X_1\right] \\
    &+\mathbb{E}\left[X_{2}|Y_0,\widetilde{P}_1,\overline{P},X_1\right]-\mathbb{E}\left[X_{2}|Y_0,\overline{P},X_1\right] \\
    &-\left((1-\widetilde{P}_1)\mathbb{E}\left[X_2e^{A}\,|\, Y_0,\widetilde{P}_1,\overline{P},X_1\right]-\mathbb{E}\left[X_2(1-\widetilde{P}_1)e^{A}\,|\, Y_0,\overline{P},X_1\right]\right)\overline{P},
\end{align*}
or more concisely
\begin{align}
    \phi_{\theta}^{\rm eff,\beta}(Y^2,X^2)=&-X_1\left(\widetilde{P}_1-\frac{1}{2}\right)\overline{P}\mathbb{E}\left[e^{A}\,|\, Y_0,\overline{P},X_1\right] \notag \\
    &+\mathbb{E}\left[X_{2}\left(1-(1-\widetilde{P}_1)\overline{P}e^{A}\right)|Y_0,\widetilde{P}_1,\overline{P},X_1\right] \notag \\
    &-\mathbb{E}\left[X_{2}\left(1-(1-\widetilde{P}_1)\overline{P}e^{A}\right)|Y_0,\overline{P},X_1\right],\label{eq: efficient_score_beta_specific_T=2}
\end{align}
as claimed in Section \ref{sec: mph_deep_dive}.

\textbf{The efficient score for $\gamma$: } The (submodel) score for $\gamma$ equals:
	\begin{align*}
		S^{\gamma}(Y^T,X^T)&=\mathbb{E}\left[\sum_{t=1}^T \frac{\partial \ln f_{\theta}(Y_t\,|\, Y_{t-1},X_t,A)}{\partial \gamma}\,|\, Y^T,X^T\right]	\\
		&=\mathbb{E}\left[\sum_{t=1}^T Y_{t-1}\left(1-P_t e^{a}\right)\,|\,Y^T,X^T\right] \\
  &=\sum_{t=1}^T Y_{t-1}-\sum_{t=1}^T Y_{t-1}P_t\mathbb{E}\left[e^{A}\,|\, Y^T,X^T\right],
	\end{align*}
which, when $T=2$, coincides with
\begin{align*}
		S^{\gamma}(Y^2,X^2)&= Y_{0}+Y_{1}-\left(Y_0P_1+Y_1P_2\right)\mathbb{E}\left[e^{A}\,|\, Y^2,X^2\right],
\end{align*}
 or, after reparameterization in terms of $(\widetilde{P}_1,\overline{P})$, with
 \begin{align*}
		S^{\gamma}(Y^2,X^2)&= Y_{0}+Y_{1}-\left(Y_0\widetilde{P}_1\overline{P}+Y_1(1-\widetilde{P}_1)\overline{P}\right)\mathbb{E}\left[e^{A}\,|\, Y_0,\widetilde{P}_1,\overline{P},X^2\right].
\end{align*}
The efficient score for $\gamma$, from equation \eqref{eq: eff_score_MPH_feedback_general_T=2} above, equals
\begin{align}
     \phi_{\theta}^{\rm eff,\gamma}(Y^2,X^2)=\mathbb{E}\left[S^{\gamma}(Y^2,X^2)|Y_0,\widetilde{P}_1,\overline{P},X_1\right]-\mathbb{E}\left[S^{\gamma}(Y^2,X^2)|Y_0,\overline{P},X_1\right]\label{eq: efficient_score_gamma_general_T=2},
\end{align}
where evaluate the first expectation to the right of equality as
\begin{align*}
    \mathbb{E}\left[S^{\gamma}(Y^2,X^2)|Y_0,\widetilde{P}_1,\overline{P},X_1\right]&=Y_{0}+Y_{1}-\left(Y_0\widetilde{P}_1\overline{P}+Y_1(1-\widetilde{P}_1)\overline{P}\right)\mathbb{E}\left[e^{A}\,|\, Y_0,\widetilde{P}_1,\overline{P},X_1\right] \\
    &=Y_{0}+Y_{1}-\left(Y_0\widetilde{P}_1\overline{P}+Y_1(1-\widetilde{P}_1)\overline{P}\right)\mathbb{E}\left[e^{A}\,|\, Y_0,\overline{P},X_1\right], 
\end{align*}
using the fact that $\widetilde{P}_1\perp (A,\overline{P})|X_0,Y_1$ (see Lemma \ref{lem: helmert_tranformation_MPH} above). 

In order to evaluate the second expectation entering the efficient score for $\gamma$ we consider the special case of a Weibull baseline hazard: $\Lambda_{\alpha}(y_t)=y_t^{\alpha}$, $\lambda_{\alpha}(y_t)=\alpha y_t^{\alpha-1}$. This hazard implies the convenient relation $Y_1=P_1^{\frac{1}{\alpha}}e^{-X_1'\frac{\beta}{\alpha}-\frac{\gamma}{\alpha}Y_0}=\widetilde{P}_1^{\frac{1}{\alpha}}\overline{P}^{\frac{1}{\alpha}}e^{-X_1'\frac{\beta}{\alpha}-\frac{\gamma}{\alpha}Y_0}$. This allows us to use Lemma \ref{lem: helmert_tranformation_MPH} to evaluate the expectation:
\begin{align*}
    \mathbb{E}\left[Y_1|Y_0,\overline{P},X_1\right]&=e^{-X_1'\frac{\beta}{\alpha}-\frac{\gamma}{\alpha}Y_0}\mathbb{E}\left[\widetilde{P}_1^{\frac{1}{\alpha}}|Y_0,\overline{P},X_1\right]\overline{P}^{\frac{1}{\alpha}} \\
    &=\frac{\alpha}{1+\alpha}e^{-X_1'\frac{\beta}{\alpha}-\frac{\gamma}{\alpha}Y_0} \overline{P}^{\frac{1}{\alpha}},
\end{align*}
where we have used the fact that $\widetilde{P}_1\sim U[0,1]=\mathrm{Beta}\left(1,1\right)$. Proceeding in the same general way we also get
\begin{align*}
    \mathbb{E}\left[Y_1(1-\widetilde{P}_1)|Y_0,\overline{P},X_1\right]&=e^{-X_1'\frac{\beta}{\alpha}-\frac{\gamma}{\alpha}Y_0}\mathbb{E}\left[\widetilde{P}_1^{\frac{1}{\alpha}}(1-\widetilde{P}_1)|Y_0,\overline{P},X_1\right]\overline{P}^{\frac{1}{\alpha}} \\
    &=\left(\frac{\alpha}{1+\alpha}-\frac{\alpha}{1+2\alpha}\right)e^{-X_1'\frac{\beta}{\alpha}-\frac{\gamma}{\alpha}Y_0} \overline{P}^{\frac{1}{\alpha}}.
\end{align*}
Using these two results we evaluate the second expectation in equation \eqref{eq: efficient_score_gamma_general_T=2} as:
\begin{align*}
    \mathbb{E}\left[S^{\gamma}(Y^2,X^2)|Y_0,\overline{P},X_1\right]&=Y_{0}+\mathbb{E}\left[Y_1|Y_0,\overline{P},X_1\right] \\
    &-\left(Y_0\mathbb{E}\left[\widetilde{P}_1|Y_0,\overline{P},X_1\right]+\mathbb{E}\left[Y_1(1-\widetilde{P}_1)|Y_0,\overline{P},X_1\right]\right)\overline{P}\mathbb{E}\left[e^{A}\,|\, Y_0,\overline{P},X_1\right] \\
    &=Y_{0}+\frac{\alpha}{1+\alpha}e^{-X_1'\frac{\beta}{\alpha}-\frac{\gamma}{\alpha}Y_0} \overline{P}^{\frac{1}{\alpha}} \\
    &-\left(Y_0\frac{1}{2}+\left(\frac{\alpha}{1+\alpha}-\frac{\alpha}{1+2\alpha}\right)e^{-X_1'\frac{\beta}{\alpha}-\frac{\gamma}{\alpha}Y_0} \overline{P}^{\frac{1}{\alpha}}\right)\overline{P}\mathbb{E}\left[e^{A}\,|\, Y_0,\overline{P},X_1\right]. 
\end{align*}
Collecting terms yields an efficient score for $\gamma$ of:
\begin{multline}
    \phi_{\theta}^{\rm eff,\gamma}(Y^2,X^2)(\widetilde{P}_1,\overline{P},X_1)=Y_1-\frac{\alpha}{1+\alpha}e^{-X_1'\frac{\beta}{\alpha}-\frac{\gamma}{\alpha}Y_0} \overline{P}^{\frac{1}{\alpha}}  \\
    -\left(Y_0\left(\widetilde{P}_1-\frac{1}{2}\right)+\left(Y_1(1-\widetilde{P}_1)-\left(\frac{\alpha}{1+\alpha}-\frac{\alpha}{1+2\alpha}\right)e^{-X_1'\frac{\beta}{\alpha}-\frac{\gamma}{\alpha}Y_0} \overline{P}^{\frac{1}{\alpha}}\right)\right)\\
    \times \overline{P}\mathbb{E}\left[e^{A}\,|\, Y_0,\overline{P},X_1\right].\label{eq: efficient_score_gamma_specific_T=2}
\end{multline}
This expression does not appear in the main text.

\textbf{The efficient score for $\alpha$: } 
%The calculations for $\phi_{\alpha}^{\rm eff}(\widetilde{P}_1,\overline{P},X_1)$ are gnarly. This might be a good time to grab a cup of coffee if you aspire to follow along.
The (submodel) score for $\alpha$ equals:
	\begin{align*}
		S^{\alpha}(Y^T,X^T)&=\mathbb{E}\left[\sum_{t=1}^T \frac{\partial \ln f_{\theta}(Y_t\,|\, Y_{t-1},X_t,A)}{\partial \alpha}\,|\, Y^T,X^T\right]	\\
		&=\mathbb{E}\left[\sum_{t=1}^T \pdv{\ln \lambda_{\alpha}(Y_t)
        }{\alpha}-\pdv{\ln \Lambda_{\alpha}(Y_t)
        }{\alpha}P_te^{A}\,|\,Y^T,X^T \right] \\
        &=\sum_{t=1}^T \pdv{\ln\lambda_{\alpha}(Y_t)
        }{\alpha}-\sum_{t=1}^T\pdv{\ln\Lambda_{\alpha}(Y_t)
        }{\alpha}P_t\mathbb{E}\left[e^{A}\,|\,Y^T,X^T \right],
\end{align*}
which, when $T=2$, equals (after reparameterization in terms of $\widetilde{P}_1,\overline{P}$):
	\begin{align*}
		S^{\alpha}(Y^2,X^2)&=\pdv{\ln \lambda_{\alpha}(Y_1)
        }{\alpha}+\pdv{\ln \lambda_{\alpha}(Y_2)
        }{\alpha}\\
        &-\left( \pdv{\ln\Lambda_{\alpha}(Y_1)
        }{\alpha}\widetilde{P}_1+\pdv{\ln\Lambda_{\alpha}(Y_2)
        }{\alpha}\times(1-\widetilde{P}_1)\right)\overline{P}\mathbb{E}\left[e^{A}\,|\,Y_0,\widetilde{P}_1,\overline{P},X_1,X_2 \right],
\end{align*}
and the efficient score for $\alpha$, from equation \eqref{eq: eff_score_MPH_feedback_general_T=2} above, equals
\begin{align}
    \phi_{\theta}^{\rm eff,\alpha}(Y^2,X^2)=\mathbb{E}\left[S^{\alpha}(Y^2,X^2)|Y_0,\widetilde{P}_1,\overline{P},X_1\right]-\mathbb{E}\left[S^{\alpha}(Y^2,X^2)|Y_0,\overline{P},X_1\right].\label{eq: efficient_score_alpha_general_T=2}
\end{align}

To make further progress we again consider the Weibull baseline hazard case; implying $\ln \Lambda_{\alpha}(Y_t)=\alpha \ln Y_t$ and $\ln \lambda_{\alpha}(Y_t)=\ln \alpha +(\alpha-1)\ln Y_t$. This yields
\begin{align*}
    \pdv{\ln \Lambda_{\alpha}(Y_t)}{\alpha}&=\ln Y_t \\
        \pdv{\ln \lambda_{\alpha}(Y_t)}{\alpha}&=\frac{1}{\alpha}+\ln Y_t.
\end{align*}
In the parameterization $\widetilde{P_1}, \overline{P}$, with 
$Y_1=P_1^{\frac{1}{\alpha}}e^{-X_1'\frac{\beta}{\alpha}-\frac{\gamma}{\alpha}Y_0}=\widetilde{P}_1^{\frac{1}{\alpha}}\overline{P}^{\frac{1}{\alpha}}e^{-X_1'\frac{\beta}{\alpha}-\frac{\gamma}{\alpha}Y_0}$ and $Y_2=(1-\widetilde{P}_1)^{\frac{1}{\alpha}}\overline{P}^{\frac{1}{\alpha}}e^{-X_1'\frac{\beta}{\alpha}-\frac{\gamma}{\alpha}Y_0}$ we have
\begin{align*}
    \pdv{\ln \Lambda_{\alpha}(Y_1)}{\alpha}&=\ln Y_1= -\frac{1}{\alpha}\left(X_1'\beta+\gamma Y_0\right)+\frac{1}{\alpha}\ln \widetilde{P}_1+\frac{1}{\alpha}\ln \overline{P} \\
    \pdv{\ln \Lambda_{\alpha}(Y_2)}{\alpha}&=\ln Y_2= -\frac{1}{\alpha}\left(X_2'\beta+\gamma Y_1\right)+\frac{1}{\alpha}\ln (1-\widetilde{P}_1)+\frac{1}{\alpha}\ln \overline{P} \\
    &=-\frac{1}{\alpha}\left(X_2'\beta+\gamma \widetilde{P}_1^{\frac{1}{\alpha}}\overline{P}^{\frac{1}{\alpha}}e^{-X_1'\frac{\beta}{\alpha}-\frac{\gamma}{\alpha}Y_0}\right)+\frac{1}{\alpha}\ln (1-\widetilde{P}_1)+\frac{1}{\alpha}\ln \overline{P},
\end{align*}
and 
\begin{align*}
    \pdv{\ln \lambda_{\alpha}(Y_1)}{\alpha}&=\frac{1}{\alpha} -\frac{1}{\alpha}\left(X_1'\beta+\gamma Y_0\right)+\frac{1}{\alpha}\ln \widetilde{P}_1+\frac{1}{\alpha}\ln \overline{P} \\
    \pdv{\ln \lambda_{\alpha}(Y_2)}{\alpha}&=\frac{1}{\alpha}-\frac{1}{\alpha}\left(X_2'\beta+\gamma \widetilde{P}_1^{\frac{1}{\alpha}}\overline{P}^{\frac{1}{\alpha}}e^{-X_1'\frac{\beta}{\alpha}-\frac{\gamma}{\alpha}Y_0}\right)+\frac{1}{\alpha}\ln (1-\widetilde{P}_1)+\frac{1}{\alpha}\ln \overline{P}.
\end{align*}
The following implications of Lemma \ref{lem: helmert_tranformation_MPH} are useful for the calculations which follow: $\widetilde{P}_1\perp \overline{P}|Y_0,X_1$ with $\widetilde{P}_1\sim U[0,1]$ and hence, by the properties of the uniform distribution, $-\ln \widetilde{P}_1\sim \mathrm{Exp}\left(1\right)$. Using these facts we evaluate the following four expectations:
 \begin{align*}
     &\mathbb{E}\left[-\ln(1-\widetilde{P}_1)|Y_0,\overline{P},X_1\right]=\mathbb{E}\left[-\ln (1-\widetilde{P}_1)|Y_0,X_1\right]=\mathbb{E}\left[-\ln \widetilde{P}_1|Y_0,X_1\right]=+1 \\
     &\mathbb{E}\left[\widetilde{P}_1^{\frac{1}{\alpha}}|Y_0,\overline{P},X_1\right]=\frac{\alpha}{\alpha+1} \\
     &\mathbb{E}\left[\widetilde{P}_1^{\frac{1}{\alpha}}(1-\widetilde{P}_1)|Y_0,\overline{P},X_1\right]= \left(\frac{\alpha}{1+\alpha}-\frac{\alpha}{1+2\alpha}\right)\\
    &\mathbb{E}\left[\ln \widetilde{P}_1 \widetilde{P}_1|Y_0,\overline{P},X_1\right]=-\frac{1}{4}.
\end{align*}
Using these calculations we can then evaluate the various conditional expectations in the efficient score expression. We start with
\begin{align*}
    \mathbb{E}\left[\pdv{\ln \lambda_{\alpha}(Y_1)}{\alpha}|Y_0,\widetilde{P}_1,\overline{P},X_1\right]&=\frac{1}{\alpha} -\frac{1}{\alpha}\left(X_1'\beta+\gamma Y_0\right)+\frac{1}{\alpha}\ln \widetilde{P}_1+\frac{1}{\alpha}\ln \overline{P},
\end{align*}
and 
\begin{align*}
    \mathbb{E}\left[\pdv{\ln \lambda_{\alpha}(Y_1)}{\alpha}|Y_0,\overline{P},X_1\right]&=\frac{1}{\alpha} -\frac{1}{\alpha}\left(X_1'\beta+\gamma Y_0\right)-\frac{1}{\alpha}\mathbb{E}\left[-\ln \widetilde{P}_1|Y_0,\overline{P},X_1\right]+\frac{1}{\alpha}\ln \overline{P} \\
    &=-\frac{1}{\alpha}\left(X_1'\beta+\gamma Y_0\right)+\frac{1}{\alpha}\ln \overline{P},
\end{align*}
which together give
\begin{align*}
   \mathbb{E}\left[\pdv{\ln \lambda_{\alpha}(Y_1)}{\alpha}|Y_0,\widetilde{P}_1,\overline{P},X_1\right]- \mathbb{E}\left[\pdv{\ln \lambda_{\alpha}(Y_1)}{\alpha}|Y_0,\overline{P},X_1\right]=\frac{1}{\alpha}+\frac{1}{\alpha}\ln \widetilde{P}_1.
\end{align*}

Second we evaluate
\begin{align*}
    \mathbb{E}\left[\pdv{\ln \lambda_{\alpha}(Y_2)}{\alpha}|Y_0,\widetilde{P}_1,\overline{P},X_1\right]=&\frac{1}{\alpha}-\frac{1}{\alpha}\left( \mathbb{E}\left[X_2|Y_0,\widetilde{P}_1,\overline{P},X_1\right]'\beta+\gamma \widetilde{P}_1^{\frac{1}{\alpha}}\overline{P}^{\frac{1}{\alpha}}e^{-X_1'\frac{\beta}{\alpha}-\frac{\gamma}{\alpha}Y_0}\right)\\
    &+\frac{1}{\alpha}\ln (1-\widetilde{P}_1)+\frac{1}{\alpha}\ln \overline{P},
\end{align*}
and 
\begin{align*}
    \mathbb{E}\left[\pdv{\ln \lambda_{\alpha}(Y_2)}{\alpha}|Y_0,\overline{P},X_1\right]&=\frac{1}{\alpha}-\frac{1}{\alpha}\left( \mathbb{E}\left[X_2|Y_0,\overline{P},X_1\right]'\beta+\gamma  \mathbb{E}\left[\widetilde{P}_1^{\frac{1}{\alpha}}|Y_0,\overline{P},X_1\right]\overline{P}^{\frac{1}{\alpha}}e^{-X_1'\frac{\beta}{\alpha}-\frac{\gamma}{\alpha}Y_0}\right)\\
    &-\frac{1}{\alpha} \mathbb{E}\left[-\ln (1-\widetilde{P}_1)|Y_0,\overline{P},X_1\right]+\frac{1}{\alpha}\ln \overline{P} \\
    &=-\frac{1}{\alpha}\left( \mathbb{E}\left[X_2|Y_0,\overline{P},X_1\right]'\beta+\gamma  \frac{\alpha}{1+\alpha}\overline{P}^{\frac{1}{\alpha}}e^{-X_1'\frac{\beta}{\alpha}-\frac{\gamma}{\alpha}Y_0}\right)+\frac{1}{\alpha}\ln \overline{P},
\end{align*}
which together yield:
\begin{multline*}
     \mathbb{E}\left[\pdv{\ln \lambda_{\alpha}(Y_2)}{\alpha}|Y_0,\widetilde{P}_1,\overline{P},X_1\right]-\mathbb{E}\left[\pdv{\ln \lambda_{\alpha}(Y_2)}{\alpha}|Y_0,\overline{P},X_1\right]\\
     =\frac{1}{\alpha}-\frac{1}{\alpha}\left(\mathbb{E}\left[X_2|Y_0,\widetilde{P}_1,\overline{P},X_1\right]-\mathbb{E}\left[X_2|Y_0,\overline{P},X_1\right]\right)'\beta \\
    -\frac{\gamma}{\alpha} \left(\widetilde{P}_1^{\frac{1}{\alpha}}-\frac{\alpha}{1+\alpha}\right) \overline{P}^{\frac{1}{\alpha}}e^{-X_1'\frac{\beta}{\alpha}-\frac{\gamma}{\alpha}Y_0}+\frac{1}{\alpha}\ln (1-\widetilde{P}_1).
\end{multline*}
Collecting the results so far, we have that the first part of the efficient score, equation \eqref{eq: efficient_score_alpha_general_T=2}, equal to:
\begin{multline*}
    \frac{2}{\alpha}+\frac{1}{\alpha}\ln \widetilde{P}_1+\frac{1}{\alpha}\ln (1-\widetilde{P}_1)-\frac{\gamma}{\alpha} \left(\widetilde{P}_1^{\frac{1}{\alpha}}-\frac{\alpha}{1+\alpha}\right) \overline{P}^{\frac{1}{\alpha}}e^{-X_1'\frac{\beta}{\alpha}-\frac{\gamma}{\alpha}Y_0}\\
    -\frac{1}{\alpha}\left(\mathbb{E}\left[X_2|Y_0,\widetilde{P}_1,\overline{P},X_1\right]-\mathbb{E}\left[X_2|Y_0,\overline{P},X_1\right]\right)'\beta.
\end{multline*}

To find the form of the second part of the efficient score we need to evaluate several additional conditional expectations. We begin with the pair of conditional expectations, using the expression for $\pdv{\ln\Lambda_{\alpha}(Y_1)}{\alpha}$ presented above,
\begin{align*}
    &\mathbb{E}\left[\pdv{\ln\Lambda_{\alpha}(Y_1)
        }{\alpha}\widetilde{P}_1\overline{P}\mathbb{E}\left[e^{A}\,|\,Y_0,\widetilde{P}_1,\overline{P},X^2 \right]|Y_0,\widetilde{P}_1,\overline{P},X_1\right] \\
        &= \mathbb{E}\left[\left(-\frac{1}{\alpha}\left(X_1'\beta+\gamma Y_0\right)+\frac{1}{\alpha}\ln \widetilde{P}_1+\frac{1}{\alpha}\ln \overline{P}\right)\widetilde{P}_1\overline{P}\mathbb{E}\left[e^{A}\,|\,Y_0,\widetilde{P}_1,\overline{P},X^2 \right]|Y_0,\widetilde{P}_1,\overline{P},X_1\right] \\
        &=\left(-\frac{1}{\alpha}\left(X_1'\beta+\gamma Y_0\right)\widetilde{P}_1\overline{P}+\frac{1}{\alpha}\ln \widetilde{P}_1\widetilde{P}_1\overline{P}+\frac{1}{\alpha}\widetilde{P}_1\overline{P}\ln \overline{P}\right)\mathbb{E}\left[e^{A}\,|\,Y_0,\overline{P},X_1\right],
\end{align*}
and also
\begin{align*}
    &\mathbb{E}\left[\pdv{\ln\Lambda_{\alpha}(Y_1)
        }{\alpha}\widetilde{P}_1\overline{P}\mathbb{E}\left[e^{A}\,|\,Y_0,\widetilde{P}_1,\overline{P},X^2 \right]|Y_0,\overline{P},X_1\right] \\
        &=-\frac{1}{\alpha}\left(X_1'\beta+\gamma Y_0\right)\mathbb{E}\left[\widetilde{P}_1e^{A}\,|\,Y_0,\overline{P},X_1\right]\overline{P}+\frac{1}{\alpha}\mathbb{E}\left[\ln \widetilde{P}_1\widetilde{P}_1e^{A}\,|\,Y_0,\overline{P},X_1\right]\overline{P}\\
        &+\frac{1}{\alpha}\mathbb{E}\left[\widetilde{P}_1e^{A}\,|\,Y_0,\overline{P},X_1\right]\overline{P}\ln \overline{P} \\
        &=\left(-\frac{1}{\alpha}\left(X_1'\beta+\gamma Y_0\right)\frac{1}{2}\overline{P}-\frac{1}{\alpha}\frac{1}{4}\overline{P}+\frac{1}{\alpha}\frac{1}{2}\overline{P}\ln \overline{P}\right)\mathbb{E}\left[e^{A}\,|\,Y_0,\overline{P},X_1\right].
\end{align*}
Together this yields a difference of expectations equal to
\begin{multline*}
   \mathbb{E}\left[\pdv{\ln\Lambda_{\alpha}(Y_1)
        }{\alpha}\widetilde{P}_1\overline{P}\mathbb{E}\left[e^{A}\,|\,Y_0,\widetilde{P}_1,\overline{P},X^2 \right]|Y_0,\widetilde{P}_1,\overline{P},X_1\right]\\
        -\mathbb{E}\left[\pdv{\ln\Lambda_{\alpha}(Y_1)
        }{\alpha}\widetilde{P}_1\overline{P}\mathbb{E}\left[e^{A}\,|\,Y_0,\widetilde{P}_1,\overline{P},X^2 \right]|Y_0,\overline{P},X_1\right]\\
        =\left(-\frac{1}{\alpha}\left(X_1'\beta+\gamma Y_0\right)\left(\widetilde{P}_1-\frac{1}{2}\right)+\frac{1}{\alpha}\left(\ln \widetilde{P}_1\widetilde{P}_1+\frac{1}{4}\right)+\frac{1}{\alpha}\left(\widetilde{P}_1-\frac{1}{2}\right)\ln \overline{P}\right) \\
        \times \overline{P}\mathbb{E}\left[e^{A}\,|\,Y_0,\overline{P},X_1\right].
\end{multline*}
Next we evaluate, using the expression for $\pdv{\ln\Lambda_{\alpha}(Y_2)}{\alpha}$ given earlier,
\begin{align*}
    \mathbb{E} & \left[\pdv{\ln\Lambda_{\alpha}(Y_2)
        }{\alpha}\times (1-\widetilde{P}_1)\overline{P}\mathbb{E}\left[e^{A}\,|\,Y_0,\widetilde{P}_1,\overline{P},X^2 \right]|Y_0,\widetilde{P}_1,\overline{P},X_1\right] \\
        =& \mathbb{E}\left[\left(-\frac{1}{\alpha}\left(X_2'\beta+\gamma \widetilde{P}_1^{\frac{1}{\alpha}}\overline{P}^{\frac{1}{\alpha}}e^{-X_1'\frac{\beta}{\alpha}-\frac{\gamma}{\alpha}Y_0}\right)+\frac{1}{\alpha}\ln (1-\widetilde{P}_1)+\frac{1}{\alpha}\ln \overline{P}\right)(1-\widetilde{P}_1)\overline{P} \right. \\
        &\left. \times \mathbb{E}\left[e^{A}\,|\,Y_0,\widetilde{P}_1,\overline{P},X^2 \right]|Y_0,\widetilde{P}_1,\overline{P},X_1\right] \\
        =&-\frac{1}{\alpha}\mathbb{E}\left[X_2e^{A}\,|\,Y_0,\widetilde{P}_1,\overline{P},X_1 \right]'\beta(1-\widetilde{P}_1)\overline{P}\\
        &-\frac{\gamma}{\alpha} \widetilde{P}_1^{\frac{1}{\alpha}}\overline{P}^{\frac{1}{\alpha}}e^{-X_1'\frac{\beta}{\alpha}-\frac{\gamma}{\alpha}Y_0}(1-\widetilde{P}_1)\overline{P} \mathbb{E}\left[e^{A}\,|\,Y_0,\overline{P},X_1 \right] \\
        &+\frac{1}{\alpha}\ln (1-\widetilde{P}_1)(1-\widetilde{P}_1)\overline{P}\mathbb{E}\left[e^{A}\,|\,Y_0,\overline{P},X_1 \right] \\
        &+\frac{1}{\alpha}(1-\widetilde{P}_1)\overline{P}\ln \overline{P}\mathbb{E}\left[e^{A}\,|\,Y_0,\overline{P},X_1 \right].
\end{align*}
We also require:
\begin{align*}
    &\mathbb{E}\left[\pdv{\ln\Lambda_{\alpha}(Y_2)
        }{\alpha}\times (1-\widetilde{P}_1)\overline{P}\mathbb{E}\left[e^{A}\,|\,Y_0,\widetilde{P}_1,\overline{P},X^2 \right]|Y_0,\overline{P},X_1\right] \\
        =&-\frac{1}{\alpha}\mathbb{E}\left[(1-\widetilde{P}_1)X_2e^{A}\,|\,Y_0,\overline{P},X_1 \right]'\beta\overline{P}\\
        &-\frac{\gamma}{\alpha} \overline{P}^{\frac{1}{\alpha}}e^{-X_1'\frac{\beta}{\alpha}-\frac{\gamma}{\alpha}Y_0}\overline{P} \mathbb{E}\left[\widetilde{P}_1^{\frac{1}{\alpha}}(1-\widetilde{P}_1)e^{A}\,|\,Y_0,\widetilde{P}_1,\overline{P},X_1 \right] \\
        &+\frac{1}{\alpha}\overline{P}\mathbb{E}\left[\ln (1-\widetilde{P}_1)(1-\widetilde{P}_1)e^{A}\,|\,Y_0,\overline{P},X_1 \right] \\
        &+\frac{1}{\alpha}\overline{P}\ln \overline{P}\mathbb{E}\left[(1-\widetilde{P}_1)e^{A}\,|\,Y_0,\overline{P},X_1 \right],
\end{align*}
which, after further simplification using Lemma \ref{lem: helmert_tranformation_MPH}, equals
\begin{align*}
    &\mathbb{E}\left[\pdv{\ln\Lambda_{\alpha}(Y_2)
        }{\alpha}\times (1-\widetilde{P}_1)\overline{P}\mathbb{E}\left[e^{A}\,|\,Y_0,\widetilde{P}_1,\overline{P},X^2 \right]|Y_0,\overline{P},X_1\right] \\
        =&-\frac{1}{\alpha}\mathbb{E}\left[(1-\widetilde{P}_1)X_2e^{A}\,|\,Y_0,\overline{P},X_1 \right]'\beta\overline{P}\\
        &-\frac{\gamma}{\alpha} \overline{P}^{\frac{1}{\alpha}}e^{-X_1'\frac{\beta}{\alpha}-\frac{\gamma}{\alpha}Y_0}\overline{P} \left(\frac{\alpha}{1+\alpha}-\frac{\alpha}{1+2\alpha}\right)\mathbb{E}\left[e^{A}\,|\,Y_0,\overline{P},X_1 \right] \\
        &-\frac{1}{\alpha}\frac{1}{4}\overline{P}\mathbb{E}\left[e^{A}\,|\,Y_0,\overline{P},X_1 \right] \\
        &+\frac{1}{\alpha}\frac{1}{2}\overline{P}\ln \overline{P}\mathbb{E}\left[e^{A}\,|\,Y_0,\overline{P},X_1 \right].
\end{align*}
Putting these last two expectation evaluations together yields a difference of:
\begin{align*}
    &\mathbb{E}\left[\pdv{\ln\Lambda_{\alpha}(Y_2)
        }{\alpha}\times (1-\widetilde{P}_1)\overline{P}\mathbb{E}\left[e^{A}\,|\,Y_0,\widetilde{P}_1,\overline{P},X^2 \right]|Y_0,\widetilde{P}_1,\overline{P},X_1\right]\\
        &-\mathbb{E}\left[\pdv{\ln\Lambda_{\alpha}(Y_2)
        }{\alpha}\times (1-\widetilde{P}_1)\overline{P}\mathbb{E}\left[e^{A}\,|\,Y_0,\widetilde{P}_1,\overline{P},X^2 \right]|Y_0,\overline{P},X_1\right] \\
        =& -\frac{1}{\alpha}\left((1-\widetilde{P}_1)\mathbb{E}\left[X_2e^{A}\,|\,Y_0,\widetilde{P}_1,\overline{P},X_1 \right]-\mathbb{E}\left[(1-\widetilde{P}_1)X_2e^{A}\,|\,Y_0,\overline{P},X_1 \right]\right)'\beta\overline{P}\\
        &-\frac{\gamma}{\alpha} e^{-X_1'\frac{\beta}{\alpha}-\frac{\gamma}{\alpha}Y_0}\left(\widetilde{P}_1^{\frac{1}{\alpha}}(1-\widetilde{P}_1)-\left(\frac{\alpha}{1+\alpha}-\frac{\alpha}{1+2\alpha}\right)\right)\overline{P}^{\frac{1}{\alpha}}\overline{P} \mathbb{E}\left[e^{A}\,|\,Y_0,\overline{P},X_1 \right] \\
        &+\frac{1}{\alpha}\left(\ln (1-\widetilde{P}_1)(1-\widetilde{P}_1)+\frac{1}{4}\right)\overline{P}\mathbb{E}\left[e^{A}\,|\,Y_0,\overline{P},X_1 \right] \\
        &+\frac{1}{\alpha}\left((1-\widetilde{P}_1)-\frac{1}{2}\right)\overline{P}\ln \overline{P}\mathbb{E}\left[e^{A}\,|\,Y_0,\overline{P},X_1 \right].
\end{align*}
Hence the second component of the efficient score is given by (minus):
\begin{align*}
    &-\frac{1}{\alpha}\left(X_1'\beta+\gamma Y_0\right)\left(\widetilde{P}_1-\frac{1}{2}\right)\overline{P}\mathbb{E}\left[e^{A}\,|\,Y_0,\overline{P},X_1\right]\\
    &+\frac{1}{\alpha}\left(\ln \widetilde{P}_1\widetilde{P}_1+\frac{1}{4}\right)\overline{P}\mathbb{E}\left[e^{A}\,|\,Y_0,\overline{P},X_1\right]\\
    &+\frac{1}{\alpha}\left(\widetilde{P}_1-\frac{1}{2}\right)\ln \overline{P}\overline{P}\mathbb{E}\left[e^{A}\,|\,Y_0,\overline{P},X_1\right] \\
    &+\frac{1}{\alpha}\left((1-\widetilde{P}_1)-\frac{1}{2}\right)\overline{P}\ln \overline{P}\mathbb{E}\left[e^{A}\,|\,Y_0,\overline{P},X_1 \right] \\
    &+\frac{1}{\alpha}\left(\ln (1-\widetilde{P}_1)(1-\widetilde{P}_1)+\frac{1}{4}\right)\overline{P}\mathbb{E}\left[e^{A}\,|\,Y_0,\overline{P},X_1 \right] \\
    &-\frac{\gamma}{\alpha} e^{-X_1'\frac{\beta}{\alpha}-\frac{\gamma}{\alpha}Y_0}\left(\widetilde{P}_1^{\frac{1}{\alpha}}(1-\widetilde{P}_1)-\left(\frac{\alpha}{1+\alpha}-\frac{\alpha}{1+2\alpha}\right)\right)\overline{P}^{\frac{1}{\alpha}}\overline{P} \mathbb{E}\left[e^{A}\,|\,Y_0,\overline{P},X_1 \right] \\
    &-\frac{1}{\alpha}\left((1-\widetilde{P}_1)\mathbb{E}\left[X_2e^{A}\,|\,Y_0,\widetilde{P}_1,\overline{P},X_1 \right]-\mathbb{E}\left[(1-\widetilde{P}_1)X_2e^{A}\,|\,Y_0,\overline{P},X_1 \right]\right)'\beta\overline{P},
\end{align*}
which, after some manipulation, simplifies to
\begin{align*}
    &-\frac{1}{\alpha}\left(X_1'\beta+\gamma Y_0\right)\left(\widetilde{P}_1-\frac{1}{2}\right)\overline{P}\mathbb{E}\left[e^{A}\,|\,Y_0,\overline{P},X_1\right]\\
    &+\frac{1}{\alpha}\left(\ln \widetilde{P}_1\widetilde{P}_1+\frac{1}{4}\right)\overline{P}\mathbb{E}\left[e^{A}\,|\,Y_0,\overline{P},X_1\right]\\
    &+\frac{1}{\alpha}\left(\ln (1-\widetilde{P}_1)(1-\widetilde{P}_1)+\frac{1}{4}\right)\overline{P}\mathbb{E}\left[e^{A}\,|\,Y_0,\overline{P},X_1 \right] \\
    &-\frac{\gamma}{\alpha} e^{-X_1'\frac{\beta}{\alpha}-\frac{\gamma}{\alpha}Y_0}\left(\widetilde{P}_1^{\frac{1}{\alpha}}(1-\widetilde{P}_1)-\left(\frac{\alpha}{1+\alpha}-\frac{\alpha}{1+2\alpha}\right)\right)\overline{P}^{\frac{1}{\alpha}}\overline{P} \mathbb{E}\left[e^{A}\,|\,Y_0,\overline{P},X_1 \right] \\
    &-\frac{1}{\alpha}\left((1-\widetilde{P}_1)\mathbb{E}\left[X_2e^{A}\,|\,Y_0,\widetilde{P}_1,\overline{P},X_1 \right]-\mathbb{E}\left[(1-\widetilde{P}_1)X_2e^{A}\,|\,Y_0,\overline{P},X_1 \right]\right)'\beta\overline{P}.
\end{align*}
We want minus of the former to form the effcient score, so (and also collecting terms)
\begin{align*}
    &+\frac{1}{\alpha}\left(X_1'\beta+\gamma Y_0\right)\left(\widetilde{P}_1-\frac{1}{2}\right)\overline{P}\mathbb{E}\left[e^{A}\,|\,Y_0,\overline{P},X_1\right]\\
    &-\frac{1}{\alpha}\left(\ln \widetilde{P}_1\widetilde{P}_1+\frac{1}{4}+\ln (1-\widetilde{P}_1)(1-\widetilde{P}_1)+\frac{1}{4}\right)\overline{P}\mathbb{E}\left[e^{A}\,|\,Y_0,\overline{P},X_1\right]\\
    &+\frac{\gamma}{\alpha} e^{-X_1'\frac{\beta}{\alpha}-\frac{\gamma}{\alpha}Y_0}\left(\widetilde{P}_1^{\frac{1}{\alpha}}(1-\widetilde{P}_1)-\left(\frac{\alpha}{1+\alpha}-\frac{\alpha}{1+2\alpha}\right)\right)\overline{P}^{\frac{1}{\alpha}}\overline{P} \mathbb{E}\left[e^{A}\,|\,Y_0,\overline{P},X_1 \right] \\
    &+\frac{1}{\alpha}\left((1-\widetilde{P}_1)\mathbb{E}\left[X_2e^{A}\,|\,Y_0,\widetilde{P}_1,\overline{P},X_1 \right]-\mathbb{E}\left[(1-\widetilde{P}_1)X_2e^{A}\,|\,Y_0,\overline{P},X_1 \right]\right)'\beta\overline{P}.
\end{align*}

Putting everything together, the efficient score for $\alpha$ equals:
\begin{align*}
    \phi_{\theta}^{\rm eff,\alpha}(Y^2,X^2)&=    \frac{2}{\alpha}+\frac{1}{\alpha}\ln \widetilde{P}_1+\frac{1}{\alpha}\ln (1-\widetilde{P}_1)-\frac{\gamma}{\alpha} \left(\widetilde{P}_1^{\frac{1}{\alpha}}-\frac{\alpha}{1+\alpha}\right) \overline{P}^{\frac{1}{\alpha}}e^{-X_1'\frac{\beta}{\alpha}-\frac{\gamma}{\alpha}Y_0}\\
    &-\frac{1}{\alpha}\left(\mathbb{E}\left[X_2|Y_0,X_1,\widetilde{P}_1,\overline{P}\right]-\mathbb{E}\left[X_2|Y_0,X_1,\overline{P}\right]\right)'\beta \\
        &+\frac{1}{\alpha}\left(X_1'\beta+\gamma Y_0\right)\left(\widetilde{P}_1-\frac{1}{2}\right)\overline{P}\mathbb{E}\left[e^{A}\,|\,Y_0,\overline{P},X_1\right]\\
    &-\frac{1}{\alpha}\left(\ln \widetilde{P}_1\widetilde{P}_1+\frac{1}{4}+\ln (1-\widetilde{P}_1)(1-\widetilde{P}_1)+\frac{1}{4}\right)\overline{P}\mathbb{E}\left[e^{A}\,|\,Y_0,\overline{P},X_1\right]\\
    &+\frac{\gamma}{\alpha} e^{-X_1'\frac{\beta}{\alpha}-\frac{\gamma}{\alpha}Y_0}\left(\widetilde{P}_1^{\frac{1}{\alpha}}(1-\widetilde{P}_1)-\left(\frac{\alpha}{1+\alpha}-\frac{\alpha}{1+2\alpha}\right)\right)\overline{P}^{\frac{1}{\alpha}}\overline{P} \mathbb{E}\left[e^{A}\,|\,Y_0,\overline{P},X_1 \right] \\
    &+\frac{1}{\alpha}\left((1-\widetilde{P}_1)\mathbb{E}\left[X_2e^{A}\,|\,Y_0,\widetilde{P}_1,\overline{P},X_1 \right]-\mathbb{E}\left[(1-\widetilde{P}_1)X_2e^{A}\,|\,Y_0,\overline{P},X_1 \right]\right)'\beta\overline{P}.
\end{align*}
Close inspection of the expression above indicates that it includes linear combinations of the efficient scores for $\beta$ and $\gamma$ as components. This observation, as well as simplification and rearrangement, gives a final expression of:
\begin{align}
    \phi_{\theta}^{\rm eff,\alpha}(Y^2,X^2) =&  \frac{1}{\alpha}\left(  2+\ln \widetilde{P}_1+\ln (1-\widetilde{P}_1)\right) \notag \\
    &-\frac{1}{\alpha}\left(\widetilde{P}_1\ln \widetilde{P}_1+(1-\widetilde{P}_1)\ln (1-\widetilde{P}_1)+\frac{1}{2}\right)\overline{P}\mathbb{E}\left[e^{A}\,|\,Y_0,\overline{P},X_1\right] \notag \\
    &-\phi_{\theta}^{\rm eff,\beta}(Y^2,X^2)'\frac{\beta}{\alpha}-\phi_{\theta}^{\rm eff,\gamma}(Y^2,X^2)\frac{\gamma}{\alpha}.\label{eq: efficient_score_alpha_specific_T=2}
\end{align}
Like its counterpart for $\gamma$ this expression does note appear in the main text.
\subsubsection{MPH efficient score without feedback (i.e., under strict exogeneity)}
\cite{hahn1994efficiency} derived the SEB for the MPH hazards model with $T=2$ and strictly exogenous regressors. His analysis did not include lagged duration dependence, as ours does. For completeness, we sketch the derivation of the efficient scores for $\alpha$, $\beta$ and $\gamma$ under strict exogeneity here. Details can be filled in along the lines of our derivation for the scores with feedback and/or by studying the rigorous analysis in \cite{hahn1994efficiency}. 

By direct analogy, the efficient score when $T=2$ under strict exogeneity equals
\begin{align*}
        \phi_{\theta}^{\rm eff,SE}(Y^2,X^2)=\mathbb{E}\left[S^{\theta}(Y^2,X^2)\,|\,Y_{0},\widetilde{P}_{1},\overline{P},X^2\right]-\mathbb{E}\left[S^{\theta}(Y^2,X^2)\,|\,Y_{0},\overline{P},X^2\right].    
\end{align*}
It follows that the expressions for the scores are the same as those derived above under feedback except that each expectation now conditions on all ``leads and lags" of the strictly exogenous covariates.

This yields an efficient score for $\beta$ of
\begin{align}
     \phi_{\theta}^{\rm eff,SE,\beta}(Y^2,X^2)&=\left(X_2-X_1\right)\left(\widetilde{P}_1-\frac{1}{2}\right)\overline{P}\mathbb{E}\left[e^{A}\,|\, Y_0,\overline{P},X^2\right]. \label{eq: efficient_score_beta_specific_T=2_strictexo}
\end{align}
This expression is identical to the one found by \cite{hahn1994efficiency}.

Maintaining the Weibull baseline hazard assumption, the efficient score for $\gamma$ equals:
\begin{multline}
    \phi_{\theta}^{\rm eff,SE,\gamma}(Y^2,X^2)=Y_1-\frac{\alpha}{1+\alpha}e^{-X_1'\frac{\beta}{\alpha}-\frac{\gamma}{\alpha}Y_0} \overline{P}^{\frac{1}{\alpha}}  \\
    -\left(Y_0\left(\widetilde{P}_1-\frac{1}{2}\right)+\left(Y_1(1-\widetilde{P}_1)-\left(\frac{\alpha}{1+\alpha}-\frac{\alpha}{1+2\alpha}\right)e^{-X_1'\frac{\beta}{\alpha}-\frac{\gamma}{\alpha}Y_0} \overline{P}^{\frac{1}{\alpha}}\right)\right) \\
    \times \overline{P}\mathbb{E}\left[e^{A}\,|\, Y_0,\overline{P},X^2\right]. \label{eq: efficient_score_gamma_specific_T=2_strictexo}
\end{multline}
The analysis of \cite{hahn1994efficiency} did not accomodate lagged duration dependence. The expression above is therefore new.

Finally, the efficient score for $\alpha$ equals:
\begin{align} \label{eq: efficient_score_alpha_specific_T=2_strictexo}
    \phi_{\theta}^{\rm eff,SE,\alpha}(Y^2,X^2)=&  \frac{1}{\alpha}\left(  2+\ln \widetilde{P}_1+\ln (1-\widetilde{P}_1)\right)  \\
    &-\frac{1}{\alpha}\left(\widetilde{P}_1\ln \widetilde{P}_1+(1-\widetilde{P}_1)\ln (1-\widetilde{P}_1)+\frac{1}{2}\right)\overline{P}\mathbb{E}\left[e^{A}\,|\,Y_0,\overline{P},X^2\right] \notag\\
    &- \phi_{\theta}^{\rm eff,SE,\beta}(Y^2,X^2)'\frac{\beta}{\alpha}- \phi_{\theta}^{\rm eff,SE,\gamma}(Y^2,X^2)\frac{\gamma}{\alpha}. \notag 
\end{align}
This expression coincides exactly with the one given in Lemma 3 of \cite{hahn1994efficiency} except that his formulation maintains the additional \emph{a priori} restriction $\gamma=0$. Setting $\gamma=0$ in the expression above yields Hahn's expression.

\subsubsection{MPH efficient score for average effects}
 Lemma \ref{proj_lemma_MPH} can also be used to derive expressions for the efficient score of average effects $\mu(\theta,\omega)$. \\

\noindent \textbf{Average structural hazard.} Consider first the ASH $\overline{\lambda}(y_{t}|x_t,y_{t-1})$ defined in \eqref{WMPH_ashf}. In the main text, we showed that $\varphi_{\theta}(Y^T,X^T)=\lambda_{\alpha}(y_{t})e^{x_{t}'\beta+\gamma y_{t-1}}\frac{T-1}{\overline{P}}$ is an identifying FHR moment function for $\overline{\lambda}(y_{t}|x_t,y_{t-1})$. Applying Lemma \ref{proj_lemma_MPH} yields the projection
\begin{align*}
        \Pi(\varphi_{\theta}(Y^{T},X^T)|\mathcal{T}_{\theta,\omega,L}^{\perp})=\sum_{t=1}^{T-1}\varphi_{\theta,t}^{\perp}(Y_0,\widetilde{P}^{t},\overline{P},X^{t})=0,
\end{align*}
since, for all $ t\in \{1,\ldots,T-1\}$, 
\begin{align*}
        \varphi_{\theta,t}^{\perp}(Y_0,\widetilde{P}^{t},\overline{P},X^{t}) &=\mathbb{E}\left[\varphi_{\theta}(Y^{T},X^T)|Y_0,\widetilde{P}^{t},\overline{P},X^{t}\right] -\mathbb{E}\left[\varphi_{\theta}(Y^{T},X^T)|Y_0,\widetilde{P}^{t-1},\overline{P},X^{t}\right] \\
        &=\lambda_{\alpha}(y_{t})e^{x_{t}'\beta+\gamma y_{t-1}}\frac{T-1}{\overline{P}}-\lambda_{\alpha}(y_{t})e^{x_{t}'\beta+\gamma y_{t-1}}\frac{T-1}{\overline{P}} \\
        &=0.
\end{align*}
This verifies the claim in Section \ref{sec: mph_deep_dive}. Recalling from Section \ref{subsec: efficiency} that the efficient score is given by ${\varphi}^{\rm eff}_{\theta,\omega}(Y^T,X^T)=\varphi_{\theta}(Y^T,X^T)-\Pi(\varphi_{\theta}(Y^T,X^T)\,|\,\mathcal{T}_{\theta,\omega,L}^{\perp})$, we conclude that the efficient score for the ASH is
\begin{align*}
    {\varphi}^{\rm eff}_{\theta,\omega}(Y^T,X^T)= \lambda_{\alpha}(y_{t})e^{x_{t}'\beta+\gamma y_{t-1}}\frac{T-1}{\overline{P}}.
\end{align*}

\noindent \textbf{Average structural function.} As a second example, consider the ASF $\mu(x_t,y_{t-1})$ defined in \eqref{WMPH_asf}. Under a Weibull baseline hazard, it takes the form
\begin{align*}
    \mu(x_t,y_{t-1})=\Gamma\left(1+\frac{1}{\alpha}\right)\exp(-x_t'\frac{\beta}{\alpha}-\frac{\gamma}{\alpha}y_{t-1})\mathbb{E}\left[\exp(-\frac{a}{\alpha})\right].
\end{align*}
In view of \eqref{eq: gamma_moments}, one candidate identifying moment function is 
\begin{align*}
    \varphi_{\theta}(Y^T,X^T) = \exp(-x_t'\frac{\beta}{\alpha}-\frac{\gamma}{\alpha}y_{t-1})\frac{\Gamma\left(1+\frac{1}{\alpha}\right)\Gamma(T)}{\Gamma(T+\frac{1}{\alpha})}\overline{P}^{\frac{1}{\alpha}}.
\end{align*}
Applying Lemma \ref{proj_lemma_MPH}, we again get $\Pi(\varphi_{\theta}(Y^{T},X^T)|\mathcal{T}_{\theta,\omega,L}^{\perp})=0$, which implies that the efficient score for the ASF is given by
\begin{align} \label{eq: eff_score_weibull_ASF}
    {\varphi}^{\rm eff}_{\theta,\omega}(Y^T,X^T) = \exp(-x_t'\frac{\beta}{\alpha}-\frac{\gamma}{\alpha}y_{t-1})\frac{\Gamma\left(1+\frac{1}{\alpha}\right)\Gamma(T)}{\Gamma(T+\frac{1}{\alpha})}\overline{P}^{\frac{1}{\alpha}}.
\end{align}
Alternatively, based on \eqref{eq: rho_is_exponential}, one could for example consider the FHR moment function 
\begin{align*}
    \varphi^{2}_{\theta_0}(Y^T,X^T) = \Gamma\left(1+\frac{1}{\alpha}\right)\exp(-x_t'\frac{\beta}{\alpha}-\frac{\gamma}{\alpha}y_{t-1})P_{1}^{\frac{1}{\alpha}},
\end{align*}
noting that $\mathbb{E}\left[P_{1}^{\frac{1}{\alpha}}|Y_{0},X_{1},A\right] = \mathbb{E}\left[\exp(-\frac{a}{\alpha})\right]$. For this choice, the identity $P_{1}=\widetilde{P}_{1}\overline{P}$ and an application of Lemma \ref{proj_lemma_MPH} yields
\begin{align*}
    \Pi(\varphi_{\theta}^{2}(Y^{T},X^T)|\mathcal{T}_{\theta,\omega,L}^{\perp}) &=  \Gamma\left(1+\frac{1}{\alpha}\right)\exp(-x_t'\frac{\beta}{\alpha}-\frac{\gamma}{\alpha}y_{t-1})\left(\widetilde{P}_{1}^{\frac{1}{\alpha}}\overline{P}^{\frac{1}{\alpha}} -\mathbb{E}\left[\widetilde{P}_{1}^{\frac{1}{\alpha}}|Y_0,\overline{P},X^{1}\right]\overline{P}^{\frac{1}{\alpha}}\right) \\
    &=\Gamma\left(1+\frac{1}{\alpha}\right)\exp(-x_t'\frac{\beta}{\alpha}-\frac{\gamma}{\alpha}y_{t-1})\left(\widetilde{P}_{1}^{\frac{1}{\alpha}}\overline{P}^{\frac{1}{\alpha}} -\frac{\Gamma\left(1+\frac{1}{\alpha}\right)\Gamma(T)}{\Gamma(T+\frac{1}{\alpha})}\overline{P}^{\frac{1}{\alpha}}\right) \\
    &=\varphi_{\theta}^{2}(Y^{T},X^T) - \Gamma\left(1+\frac{1}{\alpha}\right)\exp(-x_t'\frac{\beta}{\alpha}-\frac{\gamma}{\alpha}y_{t-1})\frac{\Gamma\left(1+\frac{1}{\alpha}\right)\Gamma(T)}{\Gamma(T+\frac{1}{\alpha})}\overline{P}^{\frac{1}{\alpha}},
\end{align*}
where the second equality leverages the distributional properties reported in Lemma \eqref{lem: helmert_tranformation_MPH}. The projection residual would then deliver the same expression of the efficient score as \eqref{eq: eff_score_weibull_ASF}. This aligns with the result discussed in Section \ref{subsec: efficiency} that the efficient score for average effects is invariant to the specific choice of $\varphi_{\theta}$.

\subsection{Detailed calculations}\label{app: detailed calculations}




\textbf{Derivation of equation \eqref{eq: det_for_rho_tilde_rho_bar_change_of_variables}:} 
Using the inverse mapping defined in Appendix \ref{app: MPH_derivations} we can write the (determinant of the) Jacobian of the mapping from $\mathbf{V}$ back into $\mathbf{P}$ as:
\begin{align*}
J^{(T)}(V_{1},\ldots,V_{T})=\left|\begin{smallmatrix}V_{T} & 0 & 0 & \ldots & 0 & V_{1}\\
-V_{2}V_{T} & (1-V_{1})V_{T} & 0 & 0 & \ldots & (1-V_{1})V_{2}\\
-(1-V_{2})V_{3}V_{T} & -(1-V_{1})V_{3}V_{T} & (1-V_{1})(1-V_{2})V_{T} & 0 & \ldots & (1-V_{1})(1-V_{2})V_{3}\\
\vdots & \vdots & \vdots & \vdots & \ddots & \vdots\\
-\prod_{s=2}^{T-2}(1-V_{s})V_{T-1}V_{T} & \ldots & \ldots & \prod_{s=1}^{T-2}(1-V_{s})V_{T} &  & \prod_{s=1}^{T-2}(1-V_{s})V_{T-1}\\
-\prod_{s=2}^{T-1}(1-V_{s})V_{T} & \ldots & \ldots & -\prod_{s=1}^{T-2}(1-V_{s})V_{T} &  & \prod_{s=1}^{T-1}(1-V_{s})
\end{smallmatrix}\right|
\end{align*}
A Laplace (co-factor) expansion along the first row gives 
\begin{align*}
J^{(T)}(V_{1},\ldots,V_{T}) & =V_{T}\left|\begin{smallmatrix}(1-V_{1})V_{T} & 0 & 0 & \ldots & (1-V_{1})V_{2}\\
-(1-V_{1})V_{3}V_{T} & (1-V_{1})(1-V_{2})V_{T} & 0 & \ldots & (1-V_{1})(1-V_{2})V_{3}\\
\vdots & \vdots & \vdots & \ddots & \vdots\\
-(1-V_{1})\prod_{s=3}^{T-2}(1-V_{s})V_{T-1}V_{T} & \ldots & \prod_{s=1}^{T-2}(1-V_{s})V_{T} &  & \prod_{s=1}^{T-2}(1-V_{s})V_{T-1}\\
-(1-V_{1})\prod_{s=3}^{T-1}(1-V_{s})V_{T} & \ldots & -\prod_{s=1}^{T-2}(1-V_{s})V_{T} &  & \prod_{s=1}^{T-1}(1-V_{s})
\end{smallmatrix}\right|\\
 & +(-1)^{T+1}V_{1}\left|\begin{smallmatrix}-V_{2}V_{T} & (1-V_{1})V_{T} & 0 & 0\\
-(1-V_{2})V_{3}V_{T} & -(1-V_{1})V_{3}V_{T} & (1-V_{1})(1-V_{2})V_{T} & 0\\
\vdots & \vdots & \vdots & \vdots\\
-\prod_{s=2}^{T-2}(1-V_{s})V_{T-1}V_{T} & \ldots & \ldots & \prod_{s=1}^{T-2}(1-V_{s})V_{T}\\
-\prod_{s=2}^{T-1}(1-V_{s})V_{T} & \ldots & \ldots & -\prod_{s=1}^{T-2}(1-V_{s})V_{T}
\end{smallmatrix}\right|
\end{align*}
and further factorizing common factors across columns yields 
\begin{align*}
J^{(T)}(V_{1},\ldots,V_{T}) & =V_{T}(1-V_{1})^{T-1}\left|\begin{smallmatrix}V_{T} & 0 & 0 & \ldots & V_{2}\\
-V_{3}V_{T} & (1-V_{2})V_{T} & 0 & \ldots & (1-V_{2})V_{3}\\
\vdots & \vdots & \vdots & \ddots & \vdots\\
-\prod_{s=3}^{T-2}(1-V_{s})V_{T-1}V_{T} & \ldots & \prod_{s=2}^{T-2}(1-V_{s})V_{T} &  & \prod_{s=2}^{T-2}(1-V_{s})V_{T-1}\\
-\prod_{s=3}^{T-1}(1-V_{s})V_{T} & \ldots & -\prod_{s=2}^{T-2}(1-V_{s})V_{T} &  & \prod_{s=2}^{T-1}(1-V_{s})
\end{smallmatrix}\right|\\
\\
 & +(-1)^{T}V_{1}(1-V_{1})^{T-2}V_{T}\left|\begin{smallmatrix}V_{2} & V_{T} & 0 & 0\\
(1-V_{2})V_{3} & -V_{3}V_{T} & (1-V_{2})V_{T} & 0\\
\vdots & \vdots & \vdots & \vdots\\
\prod_{s=2}^{T-2}(1-V_{s})V_{T-1} & \ldots & \ldots & \prod_{s=2}^{T-2}(1-V_{s})V_{T}\\
\prod_{s=2}^{T-1}(1-V_{s}) & \ldots & \ldots & -\prod_{s=2}^{T-2}(1-V_{s})V_{T}
\end{smallmatrix}\right|.
\end{align*}
Observe that the matrices involved in the first and second determinants
have the same set of columns. More specifically, the second matrix
can be obtained by swapping $\floor*{\frac{T}{2}}$ pairs of columns
in the first matrix, implying that the determinant of the second matrix
is $(-1)^{\floor*{\frac{T}{2}}}$ that of the first matrix. 

Next observe that the first determinant has exactly the same structure
as $J^{(T)}(V_{1},\ldots,V_{T})$, except that it involves $T-1$
variables instead of $T$ variables, namely $(V_{2},\ldots,V_{T})$
instead of $(V_{1},\ldots,V_{T})$. More precisely, this determinant
coincides with $J^{(T-1)}(V_{2},\ldots,V_{T})$. 

Together, these observations imply that: 
\begin{align*}
J^{(T)}(V_{1},\ldots,V_{T}) & =V_{T}(1-V_{1})^{T-1}J^{(T-1)}(V_{2},\ldots,V_{T})+(-1)^{T+\floor*{\frac{T}{2}}}V_{1}(1-V_{1})^{T-2}V_{T}J^{(T-1)}(V_{2},\ldots,V_{T})\\
 & =(1-V_{1})^{T-2}V_{T}J^{(T-1)}(V_{2},\ldots,V_{T})\\
 & =(1-V_{1})^{T-2}V_{T}(1-V_{2})^{T-3}V_{T}J^{(T-2)}(V_{3},\ldots,V_{T})\\
 & =(1-V_{1})^{T-2}V_{T}(1-V_{2})^{T-3}V_{T}\times\ldots\times(1-V_{T-2})V_{T}J^{(2)}(V_{T-1},V_{T})\\
 & =(1-V_{1})^{T-2}V_{T}(1-V_{2})^{T-3}V_{T}\times\ldots\times(1-V_{T-2})V_{T}V_{T}\\
 & =V_{T}^{T-1}\prod_{s=1}^{T-2}(1-V_{s})^{T-(s+1)},
\end{align*}
which coincides with \eqref{eq: det_for_rho_tilde_rho_bar_change_of_variables} as required.

\textbf{Derivation of equation \eqref{eq: density_of_rho_tilde_rho_bar}}
The change-of-variables formula, in conjunction with the determinant given in \eqref{eq: det_for_rho_tilde_rho_bar_change_of_variables}, yields   
\begin{align*}
f_{V}(V_{1},V_{2},\ldots,V_{T})= & f_{P_{1}}\left(V_{1}V_{T}\right)\prod_{t=2}^{T-1}f_{P_{t}}\left(\prod_{s=1}^{t-1}(1-V_{s})V_{t}V_{T}\right)f_{P_{T}}\left(\prod_{s=1}^{t-1}(1-V_{s})V_{T}\right)\abs{\det\left[\dv{G^{-1}(\mathbf{V})}{\mathbf{V}}\right]}\\
= & \frac{\beta^{\alpha_{1}}}{\Gamma(\alpha_{1})}(V_{1}V_{T})^{\alpha_{1}-1}e^{-\beta V_{1}V_{T}}\\
 & \times\prod_{t=2}^{T-1}\frac{\beta^{\alpha_{t}}}{\Gamma(\alpha_{t})}\left(\prod_{s=1}^{t-1}(1-V_{s})V_{t}V_{T}\right)^{\alpha_{t}-1}e^{-\beta\prod_{s=1}^{t-1}(1-V_{s})V_{t}V_{T}}\\
 & \times\frac{\beta^{\alpha_{T}}}{\Gamma(\alpha_{T})}\left(\prod_{s=1}^{T-1}(1-V_{s})V_{T}\right)^{\alpha_{t}-1}e^{-\beta\prod_{s=1}^{T-1}(1-V_{s})V_{T}}\\
 & \times V_{T}^{T-1}\prod_{s=1}^{T-2}(1-V_{s})^{T-(s+1)}\\
= & \frac{\beta^{\sum_{t=1}^{T}\alpha_{t}}}{\Gamma(\alpha_{T})}V_{T}^{\sum_{t=1}^{T}\alpha_{t}-1}e^{-\beta V_{T}}\\
 & \times\frac{1}{\Gamma(\alpha_{1})}V_{1}^{\alpha_{1}-1}(1-V_{1})^{\sum_{t=2}^{T}\alpha_{t}-(T-1)+(T-(1+1))}\\
 & \times\frac{1}{\Gamma(\alpha_{2})}V_{2}^{\alpha_{2}-1}(1-V_{2})^{\sum_{t=3}^{T}\alpha_{t}-(T-2)+(T-(2+1))}\\
 & \vdots\\
 & \times\frac{1}{\Gamma(\alpha_{T-1})}V_{T-1}^{\alpha_{T-1}-1}(1-V_{T-1})^{\sum_{t=T-1}^{T}\alpha_{t}-(T-(T-1))}\\
= & \frac{\beta^{\sum_{t=1}^{T}\alpha_{t}}}{\Gamma\left(\sum_{t=1}^{T}\alpha_{t}\right)}V_{T}^{\sum_{t=1}^{T}\alpha_{t}-1}e^{-\beta V_{T}}\\
 & \times\prod_{t=1}^{T-1}\frac{\Gamma\left(\sum_{s=t}^{T}\alpha_{s}\right)}{\Gamma\left(\alpha_{t}\right)\Gamma\left(\sum_{s=t+1}^{T}\alpha_{s}\right)}V_{t}^{\alpha_{t}-1}(1-V_{t})^{\sum_{s=t+1}^{T}\alpha_{s}-1},
\end{align*}
where the simplification on the penultimate equality follows from:
\begin{align*}
V_{T}=\sum_{t=1}^{T}P_{t}=V_{1}V_{T}+\prod_{s=1}^{t-1}(1-V_{s})V_{t}V_{T}+\prod_{s=1}^{T-1}(1-V_{s})V_{T}.
\end{align*}
This corresponds to equation \eqref{eq: density_of_rho_tilde_rho_bar} as needed.

