\section{Additional details for the numerical experiments} \label{app: numericalexperiment_details}

In this section we again omit the dependence on $\theta$ in $P_{\theta}$ and related quantities. 

\begin{lemma} \label{lem: nofeedback_MPH} 
Consider the
MPH model defined by Example \ref{ex: mph_intro} with $T=2$. If there is no feedback, then (i) $\overline{P},X_2, \widetilde{P}_1$ are independent conditional on $Y_0,X_1,A$, and (ii) $\widetilde{P}_1$ is independent of $X_2, \overline{P},A,Y_{0},X_{1}$. If in addition $X_{2}$ is independent of $A$ conditional on $Y_0,X_1$, then (iii) $\overline{P},X_2, \widetilde{P}_1$ are independent conditional on $Y_0,X_1$
\end{lemma}
\begin{proof}
     If there is no feedback, \eqref{eq: no_feedback_restriction} and Lemma \ref{lem: helmert_tranformation_MPH}  imply that the joint density of $(\overline{P},X_{2},\widetilde{P}_1)$ conditional on $(Y_0,X_1,A)$ is given by
     \begin{align*}
         f(\overline{p},x_{2},\widetilde{p}_1|y_{0},x_{1},a)=\overline{p} \exp\left(2a-\overline{p}e^{a}\right)\mathds{1}\{\overline{p}>0\}g(x_2|y_0,x_1,a)\mathds{1}\left\{\widetilde{p}_1\in (0,1)\right\},
     \end{align*}
     which establishes (i). This also proves that $\widetilde{P}_1\perp A,Y_0,X_1$ and hence (ii). If $X_{2}$ is independent of $A$ conditional on $Y_0,X_1$, $g(x_2|y_0,x_1,a)=g(x_2|y_0,x_1)$ whereupon the form of the above joint density imply (iii).
\end{proof}


\noindent \textbf{Locally efficient score}. 
The working model in our numerical experiment is $\widetilde{\omega}=(\widetilde{g},\widetilde{\pi})$ where
$\widetilde{g}$ is a $\text{Bernoulli}(p)$ and $\widetilde{\pi}(v) = \frac{1}{v} \mathds{1}\{v > 0\}$ where $V= \exp(A)$. Since $\overline{P}|Y_{0},X_{1},V \sim\mathrm{Gamma}\left(T,V\right)$ by Lemma \eqref{lem: helmert_tranformation_MPH}, it follows from Bayes rule that $V|Y_0,\overline{P},X_1\sim \mathrm{Gamma}\left(T,\overline{P}\right)$. Therefore, $\mathbb{E}_{\theta,\widetilde{\omega}}\left[V\,|\, Y_0,\overline{P},X_1\right]=\frac{T}{\overline{P}}$.  In view of \eqref{eq: efficient_score_beta_specific_T=2},  the locally efficient score for $\beta$ under $\widetilde{\omega}$ is
\begin{align}
    \widetilde{\phi}_{\theta,\widetilde{\omega}}^{\rm eff,\beta}(Y^2,X^2)&=-X_1\left(\widetilde{P}_1-\frac{1}{2}\right)\overline{P}\mathbb{E}_{\theta,\widetilde{\omega}}\left[V\,|\, Y_0,\overline{P},X_1\right]  \notag \\
    &+\mathbb{E}_{\theta,\widetilde{\omega}}\left[X_{2}|Y_0,\widetilde{P}_1,\overline{P},X_1\right] -\mathbb{E}_{\theta,\widetilde{\omega}}\left[X_{2}(1-\widetilde{P}_1)\overline{P}V|Y_0,\widetilde{P}_1,\overline{P},X_1\right] \notag\\
    &-\mathbb{E}_{\theta,\widetilde{\omega}}\left[X_{2}|Y_0,\overline{P},X_1\right]+\mathbb{E}_{\theta,\widetilde{\omega}}\left[X_{2}(1-\widetilde{P}_1)\overline{P}V|Y_0,\overline{P},X_1\right] \notag\\
    &=-X_1\left(\widetilde{P}_1-\frac{1}{2}\right)\overline{P}\mathbb{E}_{\theta,\widetilde{\omega}}\left[V\,|\, Y_0,\overline{P},X_1\right] \notag\\
    &+\mathbb{E}_{\theta,\widetilde{\omega}}\left[X_{2}|Y_0,X_1\right] -(1-\widetilde{P}_1)\overline{P}\mathbb{E}_{\theta,\widetilde{\omega}}\left[X_{2}|Y_0,X_1\right]\mathbb{E}_{\theta,\widetilde{\omega}}\left[V|Y_0,\overline{P},X_1\right] \notag \\
    &-\mathbb{E}_{\theta,\widetilde{\omega}}\left[X_{2}|Y_0,X_1\right]+\overline{P}\mathbb{E}_{\theta,\widetilde{\omega}}\left[X_{2}|Y_0,X_1\right]\mathbb{E}_{\theta,\widetilde{\omega}}\left[(1-\widetilde{P}_1)\right] \mathbb{E}_{\theta,\widetilde{\omega}}\left[V|Y_0,\overline{P},X_1\right] \notag \\
    &=\left(p-X_1\right)\left(\widetilde{P}_1-\frac{1}{2}\right)T,  \label{eq: loceff_score_beta_T=2}
\end{align}
where the second equality follows from  the implications of Lemma \ref{lem: nofeedback_MPH}, and the third equality uses $\mathbb{E}_{\theta,\widetilde{\omega}}\left[V\,|\, Y_0,\overline{P},X_1\right]=\frac{T}{\overline{P}}$, $\mathbb{E}_{\theta,\widetilde{\omega}}\left[\widetilde{P}_1\right]=\frac{1}{2}$ by Lemma \ref{lem: helmert_tranformation_MPH}, and the definition of $\widetilde{g}$. For the remaining components of the efficient score, we use once more, $\mathbb{E}_{\theta,\widetilde{\omega}}\left[V\,|\, Y_0,\overline{P},X_1\right]=\frac{T}{\overline{P}}$ and obtain
\begin{align} 
    \widetilde{\phi}_{\theta,\widetilde{\omega}}^{\rm eff,\gamma}(Y^2,X^2)&=Y_1-\frac{\alpha}{1+\alpha}e^{-X_1'\frac{\beta}{\alpha}-\frac{\gamma}{\alpha}Y_0} \overline{P}^{\frac{1}{\alpha}}  \notag \\
    &-\left(Y_0\left(\widetilde{P}_1-\frac{1}{2}\right)+\left(Y_1(1-\widetilde{P}_1)-\left(\frac{\alpha}{1+\alpha}-\frac{\alpha}{1+2\alpha}\right)e^{-X_1'\frac{\beta}{\alpha}-\frac{\gamma}{\alpha}Y_0} \overline{P}^{\frac{1}{\alpha}}\right)\right)T \label{eq: loceff_score_gamma_T=2}
\end{align}
from \eqref{eq: efficient_score_gamma_specific_T=2}, and finally
\begin{align}
    \widetilde{\phi}_{\theta,\widetilde{\omega}}^{\rm eff,\alpha}(Y^2,X^2) =&  \frac{1}{\alpha}\left(  2+\ln \widetilde{P}_1+\ln (1-\widetilde{P}_1)\right) \notag \\
    &-\frac{1}{\alpha}\left(\widetilde{P}_1\ln \widetilde{P}_1+(1-\widetilde{P}_1)\ln (1-\widetilde{P}_1)+\frac{1}{2}\right)T  \notag \\
    &- \widetilde{\phi}_{\beta,\widetilde{\omega}}^{\rm eff}(Y^2,X^2)'\frac{\beta}{\alpha}- \widetilde{\phi}_{\gamma,\widetilde{\omega}}^{\rm eff}(Y^2,X^2)\frac{\gamma}{\alpha} \label{eq: loceff_score_alpha_T=2}
\end{align}
from \eqref{eq: efficient_score_alpha_specific_T=2}. \\

