\noindent \textbf{Computation of efficient scores.} In the absence of feedback, Lemma \ref{lem: nofeedback_MPH} and Lemma \ref{lem: helmert_tranformation_MPH} imply that \eqref{eq: efficient_score_beta_specific_T=2} simplifies to
\begin{align}
    \phi_{\theta}^{\rm eff,\beta}(Y^2,X^2)=\left(\widetilde{P}_1-\frac{1}{2}\right)\overline{P}\left(\mathbb{E}\left[X_{2}V|Y_0,\overline{P},X_1\right]-X_1\mathbb{E}\left[V\,|\, Y_0,\overline{P},X_1\right]\right) \label{eq: efficient_score_beta_specific_T=2_nofeedback}
\end{align}
where $V= \exp(A)$. As a result, the efficient score for $\alpha$ in  \eqref{eq: efficient_score_alpha_specific_T=2} also simplifies. On the other hand, the  efficient score for $\gamma$ in \eqref{eq: efficient_score_gamma_specific_T=2} remains unchanged. %The efficient scores for $\gamma$ and $\alpha$ in \eqref{eq: efficient_score_gamma_specific_T=2} and \eqref{eq: efficient_score_alpha_specific_T=2} remain unchanged. \
 To compute the efficient score, we must evaluate two quantities: $\mathbb{E}\left[X_2 V \,|\,Y_0,\overline{P},X_1\right]$ and $\mathbb{E}\left[V\,|\,Y_0,\overline{P},X_1\right]$.  In both numerical experiments $V\sim \text{Gamma}(\kappa_0,\lambda_0)$ where $\kappa_0=\lambda_0=5$. Given that $\overline{P}|Y_{0},X_{1},V \sim\mathrm{Gamma}\left(T,V\right)$ by Lemma \ref{lem: helmert_tranformation_MPH}, Bayes rule implies that $V|Y_0,\overline{P},X_1\sim \mathrm{Gamma}\left(T+\kappa_0,\overline{P}+\lambda_0\right)$ and hence $\mathbb{E}\left[V\,|\, Y_0,\overline{P},X_1\right]=\frac{T+\kappa_0}{\overline{P}+\lambda_0}$. Furthermore, the success probability for $X_2$ in Experiment (A) is $p(Y_0,Y_1,X_1,V)=1-\exp(-\tau_{A}(Y_{0},X_{1},Y_{1})V)$ with $\tau_{A}(Y_{0},X_{1},Y_{1})=Y_{0}+X_{1}$. Using this specification, we derive:
\begin{align*}
    \mathbb{E}\left[X_2V\,|\, Y_0,\overline{P},X_1\right]= \frac{T+\kappa_0}{\left(\lambda_0+\overline{P}\right)} - (T+\kappa_0)\frac{\left(\lambda_0+\overline{P}\right)^{T+\kappa_0}}{\left(\lambda_0+\overline{P}+\tau_{A}(Y_{0},X_{1},Y_{1})\right)^{T+\kappa_0+1}},
\end{align*}
and 
\begin{align*}
    \mathbb{E}\left[e^{A}|Y_0,X_1,X_2,\overline{P}\right]&=X_2 \frac{w_1}{w_1-w_2}\frac{T+\kappa_0}{(\lambda_0+\overline{P})}+\left((1-X_2)-X_2\frac{w_2}{w_1-w_2}\right)\frac{T+\kappa_0}{(\lambda_0+\overline{P}+\tau_{A}(Y_{0},X_{1},Y_{1}))},
\end{align*}
for $w_1=\frac{\overline{P}^{T-1}\lambda_0^{\kappa_0}}{\Gamma(T)\Gamma(\kappa_0)}\frac{\Gamma(T+\kappa_0)}{\left(\lambda_0+\overline{P}\right)^{T+\kappa_0}}$, $w_2=\frac{\overline{P}^{T-1}\lambda_0^{\kappa_0}}{\Gamma(T)\Gamma(\kappa_0)}\frac{\Gamma(T+\kappa_0)}{\left(\lambda_0+\overline{P}+\tau_{A}(Y_{0},X_{1},Y_{1})\right)^{T+\kappa_0}}$. This last expression enables us to compute the efficient score under strict exogeneity given in \eqref{eq: efficient_score_beta_specific_T=2_strictexo}-\eqref{eq: efficient_score_gamma_specific_T=2_strictexo}-\eqref{eq: efficient_score_alpha_specific_T=2_strictexo} for Experiment (A). \\
\indent Equations \eqref{eq: efficient_score_beta_specific_T=2}–\eqref{eq: efficient_score_gamma_specific_T=2}–\eqref{eq: efficient_score_alpha_specific_T=2} reveal that, in the presence of feedback, computing the efficient score requires evaluating the following four conditional expectations: $ \mathbb{E}\left[X_{2}|Y_0,\widetilde{P}_1,\overline{P},X_1\right]$, $\mathbb{E}\left[X_{2}|Y_0,\overline{P},X_1\right]$, $ \mathbb{E}\left[X_{2}V|Y_0,\widetilde{P}_1,\overline{P},X_1\right]$, $ \mathbb{E}\left[X_{2}(1-\widetilde{P}_1)V|Y_0,\widetilde{P}_1,\overline{P},X_1\right]$. In Experiment (B), the success probability for $X_2$ is  $p(Y_0,Y_1,X_1,V)=1-\exp(-\tau_{B}(Y_{0},X_{1},Y_{1})V)$ with $\tau_{B}(Y_{0},X_{1},Y_{1})=Y_{0}+X_{1}+Y_{1}$. Under this specification, we obtain the following expressions:
\begin{align*}
    \mathbb{E}\left[X_2|Y_0,X_1,\widetilde{P}_1,\overline{P}\right]
    &=1-\frac{\left(\lambda_0+\overline{P}\right)^{T+\kappa_0}}{\left(\lambda_0+\overline{P}+\tau_{B}(Y_{0},X_{1},Y_{1}) \right)^{T+\kappa_0}} \\
    \mathbb{E}\left[X_2|Y_0,X_1,\overline{P}\right]
    &=1-\left(\lambda_0+\overline{P}\right)^{T+\kappa_0}\times \frac{1}{C_1^{(T+\kappa_0)}} \times {}_2F_1\left(T+\kappa_0, \alpha; 1+ \alpha; -\frac{C_2}{C_1}\right) \\
    \mathbb{E}\left[X_2V\,|\, Y_0,\widetilde{P}_1,\overline{P},X_1\right]
    &=\frac{T+\kappa_0}{\lambda_0+\overline{P}}-(T+\kappa_0)\frac{\left(\lambda_0+\overline{P}\right)^{T+\kappa_0}}{\left(\lambda_0+\overline{P}+\tau_{B}(Y_{0},X_{1},Y_{1})  \right)^{T+\kappa_0+1}},
\end{align*}
and 
\begin{align*}
    &\mathbb{E}\left[X_2(1-\widetilde{P}_1)V\,|\, Y_0,\overline{P},X_1\right] \\
    &=\frac{1}{2}\frac{T+\kappa_0}{\lambda_0+\overline{P}} -(T+\kappa_0)\left(\lambda_0+\overline{P}\right)^{T+\kappa_0}\times \\
    &\frac{1}{C_1^{(T+\kappa_0+1)}}\left({}_2F_1\left(T+\kappa_0+1, \alpha; 1+ \alpha; -\frac{C_2}{C_1}\right)-\frac{1}{2}\times {}_2F_1\left(T+\kappa_0+1,2\alpha; 1+ 2\alpha; -\frac{C_2}{C_1}\right)\right),
\end{align*}
where we use the shorthands $C_1=\lambda_0+\overline{P}+Y_0+X_1,C_2=\overline{P}^{\frac{1}{\alpha}}e^{-X_1'\frac{\beta}{\alpha}-\frac{\gamma}{\alpha}Y_0}$, and ${}_2F_1\left(a, b; c; z\right)$ denotes the hypergeometric function
\begin{align*}
    {}_2F_1\left(a, b; c; z\right) = \frac{\Gamma(c)}{\Gamma(b)\Gamma(c-b)}\int_{0}^1 \frac{t^{b-1}(1-t)^{c-b-1}}{(1-zt)^a}dt.
\end{align*}

\section{Nonlinear regression: derivation of equation \eqref{eq_tobeshown}}

Let $\psi_{\theta}(y_0,y_1,x_1,a)$ denote a moment function satisfying \eqref{eq_psi_zeromean}. Following Corollary \ref{coro_charact}, we search for functions $\phi_{\theta}$ satisfying equation \eqref{eq_phi_coro}, i.e.,
	\begin{align*}&\int_{-\infty}^{+\infty}\phi_{\theta}(y_0,y_1,y_2,x_1,x_2)\exp\left(-\frac{1}{2\sigma^2}(y_2-m_{\beta}(y_1,x_2,a))\right)^2dy_2=\psi_{\theta}(y_0,y_1,x_1,a),
    \end{align*}
    which is a convolution equation. Thus, if we let $\tau = m_{\beta}(y_1,x_2,a)$, an application of the Convolution Theorem yields
    \begin{align*}
        \mathcal{F}\left[\phi_{\theta}(y_0,y_1,.,x_1,x_1)\right][s]\exp(-\frac{\sigma^2}{2}s^2)= \mathcal{F}\left[\psi_{\theta}(y_0,y_1,x_1,m_{\beta}^{-1}(y_1,x_2,\tau))\right][s],
    \end{align*}
    where $\mathcal{F}\left[g\right][s]=\int_{-\infty}^{+\infty}g(z)\exp(\boldsymbol{i}zs)dz$ denotes the Fourier transform operator, and we have used that the characteristic function of a $\mathcal{N}(0,\sigma^2)$ is given by $s\mapsto \exp(-\frac{\sigma^2}{2}s^2)$. More explicitly, we have
    \begin{align*}
        &\int_{-\infty}^{+\infty} \phi_{\theta}(y_0,y_1,y_2,x_1,x_2)\exp(\boldsymbol{i}s y_2)dy_2 \\
        &= \int_{-\infty}^{+\infty} \psi_{\theta}(y_0,y_1,x_1,m_{\beta}^{-1}(y_1,x_2,\tau)) \exp(\boldsymbol{i}s \tau+\frac{\sigma^2}{2}s^2)d\tau  \\
        &=\int_{-\infty}^{+\infty} \psi_{\theta}(y_0,y_1,x_1,a)\pdv{m_{\beta}(y_1,x_2,a)}{a} \exp(\boldsymbol{i}s m_{\beta}(y_1,x_2,a)+\frac{\sigma^2}{2}s^2)da,
    \end{align*}
    where we have used the change in variables $a\mapsto \tau=m_{\beta}(y_1,x_2,a)$.\\
However, the inverse problem may not have solutions since the inverse Fourier transform
	\begin{align*}
    \frac{1}{2\pi}\int_{-\infty}^{+\infty} \exp(-\boldsymbol{i}s y_2)\left[\int_{-\infty}^{+\infty} \psi_{\theta}(y_0,y_1,x_1,a)\pdv{m_{\beta}(y_1,x_2,a)}{a} \exp(\boldsymbol{i}s m_{\beta}(y_1,x_2,a)+\frac{\sigma^2}{2}s^2)da \right]ds
    \end{align*}
    may not be well-defined. To address this issue, our strategy is to regularize the problem, and compute the regularized inverse 
	\begin{align*}
        &\phi_{\theta}^{\lambda}(y_0,y_1,y_2,x_1,x_2)\\
		&=\frac{1}{2\pi}\int_{-\infty}^{+\infty} \lambda \kappa(\lambda s) \exp(-\boldsymbol{i}s y_2)\left[\int_{-\infty}^{+\infty} \psi_{\theta}(y_0,y_1,x_1,a)\pdv{m_{\beta}(y_1,x_2,a)}{a} \exp(\boldsymbol{i}s m_{\beta}(y_1,x_2,a)+\frac{\sigma^2}{2}s^2)da \right]ds\\
		&=\int_{-\infty}^{+\infty}\psi_{\theta}(y_0,y_1,x_1,a)\pdv{m_{\beta}(y_1,x_2,a)}{a}\left[\frac{1}{2\pi}\int_{-\infty}^{+\infty} \lambda \kappa(\lambda s)\exp\left(\boldsymbol{i}s (m_{\beta}(y_1,x_2,a)-y_2)+\frac{1}{2}\sigma^2s^2\right)ds\right]da\\
		&=\int_{-\infty}^{+\infty} \psi_{\theta}(y_0,y_1,x_1,a)\frac{\partial m_{\beta}(y_1,x_2,a)}{\partial a}K_{\lambda}\left(\frac{m_{\beta}(y_1,x_2,a)-y_2}{\lambda}\right)da,
    \end{align*}
	which is always well-defined (under suitable conditions so that the integrals can be interchanged). This is similar to the strategy used in kernel nonparametric deconvolution (\citealp{stefanski1990deconvolving}).




	The expectation of this regularized inverse is
\begin{align*}
    &\mathbb{E}\left[\phi_{\theta}^{\lambda}(Y_{0},Y_{1},Y_{2},X_{1},X_{2})\,|\, Y_{0},X_{1}\right]\\
    &=	\mathbb{E}\left[\int_{-\infty}^{+\infty} \psi_{\theta}(Y_{0},Y_{1},X_{1},a)\frac{\partial m_{\beta}(Y_{1},X_{2},a)}{\partial a}K_{\lambda}\left(\frac{m_{\beta}(Y_{1},X_{2},a)-Y_{2}}{\lambda}\right)da\,|\, Y_{0},X_{1}\right]\\
    &=\frac{1}{2\pi}\int_{-\infty}^{+\infty} \lambda\kappa(\lambda s)\int_{-\infty}^{+\infty} \mathbb{E}\bigg[\psi_{\theta}(Y_{0},Y_{1},X_{1},a)\frac{\partial m_{\beta}(Y_{1},X_{2},a)}{\partial a}\\
    &\quad \times\exp\left(\lambda \boldsymbol{i}s \frac{m_{\beta}(Y_{1},X_{2},a)-Y_{2}}{\lambda}+\frac{1}{2}\sigma^2s^2\right)\,|\, Y_{0},X_{1}\bigg]dads\\
    &=\frac{1}{2\pi}\int_{-\infty}^{+\infty} \lambda \kappa(\lambda s) \int_{-\infty}^{+\infty} \mathbb{E}\bigg[\psi_{\theta}(Y_{0},Y_{1},X_{1},a)\frac{\partial m_{\beta}(Y_{1},X_{2},a)}{\partial a}\\
    &\quad \times\exp\left(\lambda \boldsymbol{i}s \frac{m_{\beta}(Y_{1},X_{2},a)-\varepsilon_{i2}-m_{\beta}(Y_{1},X_{2},A)}{\lambda}+\frac{1}{2}\sigma^2s^2\right)\,|\, Y_{0},X_{1}\bigg]dads\\
    &= \int_{-\infty}^{+\infty} \mathbb{E}\bigg[\psi_{\theta}(Y_{0},Y_{1},X_{1},a)\frac{\partial m_{\beta}(Y_{1},X_{2},a)}{\partial a}\\
    &\quad \times\frac{1}{2\pi }\int_{-\infty}^{+\infty} \lambda \kappa(\lambda s)\exp\left( \boldsymbol{i}s (m_{\beta}(Y_{1},X_{2},a)-m_{\beta}(Y_{1},X_{2},A))\right)ds\,|\, Y_{0},X_{1}\bigg]da \\
    &= \int_{-\infty}^{+\infty} \mathbb{E}\bigg[\psi_{\theta}(Y_{0},Y_{1},X_{1},a)\frac{\partial m_{\beta}(Y_{1},X_{2},a)}{\partial a}\\
    &\quad \times\frac{1}{2\pi }\int_{-\infty}^{+\infty} \kappa(u)\exp\left( \boldsymbol{i}\frac{u}{\lambda} (m_{\beta}(Y_{1},X_{2},a)-m_{\beta}(Y_{1},X_{2},A))\right)du\,|\, Y_{0},X_{1}\bigg]da.
\end{align*}
Since $\abs{\kappa(u)\exp\left( \boldsymbol{i}\frac{u}{\lambda} (m_{\beta}(Y_{1},X_{2},a)-m_{\beta}(Y_{1},X_{2},A)\right)}\leq \abs{\kappa(u)}$ and by assumption $\abs{\kappa(u)}$ is integrable, the dominated convergence theorem implies
\begin{align*}
    &\lim_{\lambda \to 0}\mathbb{E}\left[\phi_{\theta}^{\lambda}(Y_{0},Y_{1},Y_{2},X_{1},X_{2})\,|\, Y_{0},X_{1}\right] \\
    &= \int_{-\infty}^{+\infty} \mathbb{E}\left[\psi_{\theta}(Y_{0},Y_{1},X_{1},a)\frac{\partial m_{\beta}(Y_{1},X_{2},a)}{\partial a}\delta(m_{\beta}(Y_{1},X_{2},a)-m_{\beta}(Y_{1},X_{2},A))\,|\, Y_{0},X_{1}\right]da,
\end{align*}
where $\delta(\cdot)$ denotes Dirac's delta. Finally, since by assumption $a\mapsto m_{\beta}(y_1,x_2,a)$ is strictly increasing we have
\begin{align*}
    &\lim_{\lambda \to 0}\mathbb{E}\left[\phi_{\theta}^{\lambda}(Y_{0},Y_{1},Y_{2},X_{1},X_{2})\,|\, Y_{0},X_{1}\right] \\
    &= \int_{-\infty}^{+\infty} \mathbb{E}\left[\psi_{\theta}(Y_{0},Y_{1},X_{1},a)\delta(a-A)\,|\, Y_{0},X_{1}\right]da \\
    &= \mathbb{E}\left[\int_{-\infty}^{+\infty} \psi_{\theta}(Y_{0},Y_{1},X_{1},a)\delta(a-A)da \,|\, Y_{0},X_{1}\right] \\
    &= \mathbb{E}\left[\psi_{\theta}(Y_{0},Y_{1},X_{1},A)\,|\, Y_{0},X_{1}\right] \\
    &=0,
\end{align*} 
where the first line follows from the composition property with the Dirac delta.
