\section{General Notations and Assumptions} \label{sec:assumptions}

In this section, we collect the assumptions that are required throughout the paper. In each statement we shall explicitly list the needed assumptions. To ease the reader, we adopt similar notations as in \cite{AR17}.
% Given an energy $E:[0,T]\times \R^d \to \R$ differentiable in the space variable, we are interesting in finding curves $u:[0,T]\to\R^d$ such that the following condition is satisfied:
% \begin{equation}\label{eq:crit_point_evol}
%     \nabla E_t(u(t)) = 0 \quad \mbox{for a.e. } t\in [0,T].
% \end{equation}
We set our analysis on a metric space $(\Xx, d)$. We first state the basic structure that we need on $(\Xx, d)$.
\begin{assumption} \label{ass:metric_space}
    The space $(\Xx, d)$ is a locally compact metric space.
\end{assumption}



We make the following assumptions on the time-varying energy $E\colon [0,T]\times \Xx \to \R$ that drives the evolution.

\begin{assumption}\label{ass:reg_E}
    The function $E\colon [0,T]\times \Xx \to \R$ is continuous. Moreover, it is differentiable in the first variable, for every $t\in [0,T]$ and for every $x\in \Xx$, and the derivative $\partial_t E_\cdot \colon [0,T]\times \Xx\to \R$ is continuous.
    Finally, for every $t\in[0,T]$ and $x\in\Xx$ we consider the slope
    \begin{equation*}
        |\partial E_t|(x) \coloneqq 
        \limsup_{x'\to x} \frac{\big( E_t(x) - E_t(x') \big)^+}{d(x,x')},
    \end{equation*}
    and we assume that $|\partial E_\cdot|\colon [0,T]\times \Xx \to \R$ is a continuous function.
\end{assumption}
\begin{remark}\label{rmk:slope_strong_upper_gradient}
    Under the continuity assumption and using local compactness, the slope coincides with the local Lipschitz constant
    \begin{equation*}
        \limsup_{x'\to x} \frac{\big| E_t(x) - E_t(x') \big|}{d(x,x')}.
    \end{equation*}
    As the local Lipschitz constant is a strong upper gradient (as defined in~\cite[Def. 1.2.1]{greenbook}), under the preceding assumption, the slope is as well.
\end{remark}


\begin{assumption}\label{ass:der_time}
    There exist positive constants $C_1,C_2>0$  such that
    \begin{equation*}
        |\partial_t E_t(x)| \leq C_1 E_t(x) + C_2
    \end{equation*}
    for every $(t,x)\in [0,T]\times \Xx$.
\end{assumption}

From \cref{ass:der_time} it follows that $E_t(x)\geq -C_2/C_1$ for every $(t,x)\in [0,T]\times \Xx$, i.e., $E\colon[0,T] \times \Xx\to \R$ is bounded from below. Without loss of generality, we will assume throughout the paper that $E$ is non-negative.

\begin{assumption}\label{ass:unif_coerc}
    We set $G\colon \Xx\to \R$ as  $G(x)\coloneqq \sup_{t\in[0,T]} |E_t(x)|$ for every $x\in\Xx$, and we require that $G$ is coercive.  Namely, the sublevel sets $\{x \in \Xx \mid G(x)\leq C\}$ are compact in $\Xx$ for every $C\in \mathbb{R}$.
\end{assumption}


\begin{remark}\label{rmk:coerc_Et}
    From \cref{ass:reg_E,ass:unif_coerc,ass:der_time} it follows that $E_t:\Xx\to\R$ is uniformly coercive in the time variable. Indeed, if we consider the set $\{x\in\Xx \mid E_t(x)\leq C\}$ for $C\geq0$, then from \cref{ass:der_time} and the Gr\"onwall Lemma we get
    $E_s(x)\leq (C+C_2|s-t|)e^{C_1|s-t|}$ for every $s\in[0,T]$ and for every $x\in\Xx$ satisfying $E_t(x)\leq C$.
    Hence, for every $t\in[0,T]$ we deduce the inclusion
    \begin{equation*}
        \{x\in\Xx \mid  E_t(x)\leq C\} \subset
        \left\{
        x\in\Xx \mid G(x)\leq (C+C_2T)e^{C_1T}
        \right\},
    \end{equation*}
    where the larger set (which does not depend on $t$) is compact by \cref{ass:unif_coerc}.
\end{remark}

\begin{assumption} \label{ass:conn_comp}
    For every $t\in [0,T]$, the set $\Crit_t:=\{x\in \Xx \mid |\partial E_t|(x) =0\}$ can be expressed as the disjoint union of well-separated compacts, each of them being path-connected with rectifiable paths.
    Moreover, for every path-connected component $\Crit_t' \subset \Crit_t$, $E_t\colon \Xx\to\R$ is constant on $\Crit_t'$.
\end{assumption}

\begin{remark}
    We recall that in general the constancy of $E_t$ on the connected components of $\Crit_t$ may fail (see \cite{W35}).
    However, this property is implied, e.g., by the fact that any two points in a connected component can be joined by a path $\eta \in AC([0,1],\Xx)$ (see \cite[Section~1.1]{greenbook} for this notion) such that $|\partial E_t|\big( \eta(s) \big) =0$ for every $s \in [0,1]$.
    Moreover, also from \cref{ass:PL+time_der_slope} below, it follows that $E_t$ is constant on the path-connected components of $\Crit_t$ (see \cref{rmk:constant_components}).
\end{remark}


\begin{assumption} \label{ass:PL+time_der_slope}
%    We require that, for every $t\in [0,T]$, the local Polyak-Lojasiewicz condition holds, i.e., for every $x\in \Xx$ such that $|\partial E_t | (x)=0$ there exists $\theta\in (0,1)$, $C>0$ and a neighborhood $U\ni x$ such that
%    \begin{equation*}
%        |E_t(x')-E_t(x)|^\theta\leq C |\partial E_t |(x')
%    \end{equation*}
%    for every $x'\in U$.
    We require that, for every $t\in [0,T]$ and for every $x \in \Xx$ with $|\partial E_t|(x)=0$ there exists a neighborhood $U\ni x$ and a function $\varepsilon_x\colon[0,+\infty)\to [0,+\infty)$ such that
    \begin{equation} \label{eq:liminf_ineq_relaxed}
        E_t(x') - E_t(x) \geq - \varepsilon_x\big( d(x,x') \big) |\partial E_t|(x')
    \end{equation}
    for every $x'\in U$, where $\varepsilon_x(0) = \lim_{s\to 0^+} \varepsilon_x(s) = 0$.\\
    Moreover, we assume that for a fixed $u \in \Xx$, the function $t \mapsto |\partial E_t|(x)$ is Lipschitz continuous on $[0, T]$, locally uniformly w.r.t. $x$.
\end{assumption}

\begin{remark}
    We report that the inequality \eqref{eq:liminf_ineq_relaxed} in \cref{ass:PL+time_der_slope} is a reformulation of the more classical condition
    \begin{equation*}
        \liminf_{x'\to x} \frac{E_t(x') - E_t(x)}{|\partial E_t|(x')} \geq 0
    \end{equation*}
    required for those $x$ such that $|\partial E_t|(x)=0$ (see, e.g., \cite[Assumption~E4]{AR17} and\cite[Assumption~F4]{Scilla_2018}), under the hypothesis of \emph{isolated critical points}.
    In our setting, the ratio written above is not suitable, as it is not defined whenever $x$ lies in the interior of the set where $|\partial E_t|$ vanishes.
\end{remark}

\begin{remark} \label{rmk:constant_components}
    From \cref{ass:reg_E,ass:PL+time_der_slope} it follows that for every path-connected component $\Crit_t' \subset \Crit_t$, $E_t\colon \Xx\to\R$ is constant on $\Crit_t'$.
    To see this, we show that, for every $c\in \R$, we have that both $A_c\coloneqq \{x \in \Crit_t' \mid  E_{t}  (x) \geq c \}$ and $\bar A_c \coloneqq\{x \in \Crit_t' \mid  E_{t}  (x) < c \}$ are open in the topology induced by $(\Xx,d)$ on $\Crit_t'$.
    On the one hand, let $x \in A_c$, then by virtue of \cref{ass:PL+time_der_slope}, there exists an open ball $B_\rho(x)$ such that  $E_{t} (x')\geq E_{t} (x) \geq c$ for every $x' \in \Crit_t'\cap B_\rho(x)$ (here we combined \cref{eq:liminf_ineq_relaxed} with the fact that $x'$ is a critical point).
    On the other hand, if $x \in \bar A_c$, then by continuity of $E_t$ we deduce the existence of an open ball $B_\rho(x)$ such that $ E_{t}  (x')< c$ for every $x' \in \Crit_t'\cap B_\rho(x)$.
    Since $\Crit_t' = A_c \cup \bar A_c$ for every $c\in\R$, we deduce that either $\Crit_t' = A_c$ and $\bar A_c= \emptyset$, or $\Crit_t' = \bar A_c$ and $ A_c= \emptyset$.
    Therefore, we have that, for every $x\in \Crit_t'$, $E_t(x) = \sup\{c\in\R\mid A_c \neq \emptyset\}$.
\end{remark}

It turns out that the time derivative $\partial_t E_t$ is constant on the connected components of critical points, for every but at most countably many exceptional instants $t\in [0,T]$ (see \cref{lemma:time_derivative_factors}). However, to show that, we need to strengthen the condition formulated in \cref{eq:liminf_ineq_relaxed}.

{
\renewcommand{\theassumption}{6'}
\begin{assumption} \label{ass:strengthening_6}
        We require that, for every $t\in [0,T]$ and for every $x \in \Xx$ with $|\partial E_t|(x)=0$ there exists a neighborhood $U\ni x$ and a function $\varepsilon_x\colon[0,+\infty)\to [0,+\infty)$ such that
    \begin{equation} \label{eq:liminf_ineq_stronger}
        |E_t(x') - E_t(x)| \leq  \varepsilon_x\big( d(x,x') \big) |\partial E_t|(x')
    \end{equation}
    for every $x'\in U$, where $\varepsilon_x(0) = \lim_{s\to 0^+} \varepsilon_x(s) = 0$.\\
    Moreover, we assume that the function $t \mapsto |\partial E_t|(x)$ is Lipschitz continuous on $[0, T]$, locally uniformly with respect to $x \in \Xx$.
\end{assumption}
\addtocounter{assumption}{-1}
}

\begin{remark}
    We observe that the inequality \eqref{eq:liminf_ineq_stronger} and its one-sided version \eqref{eq:liminf_ineq_relaxed} hold if $E_t$ complies with the local Polyak-{\L}ojasiewicz condition and if $|\partial E_t|$ is continuous (as prescribed in \cref{ass:reg_E}).
\end{remark}

The next hypothesis will be used in the last part of the paper.

\begin{assumption} \label{ass:path+Lipsch}
    $(X,d)$ is a path space, i.e.,
    \begin{equation*}
        d(x,x') = \inf\left\{
        \int_0^1 |\dot \eta (s)| \diff s \, \mid \,
        \eta \in AC([0,1],\Xx), \, \eta(0)=x, \, \eta(1)=x'
        \right\}.
    \end{equation*}
    Moreover, we require that $|\partial E_t| \colon \Xx \to \R$ Lipschitz continuous, uniformly as $t$ varies in $[0,T]$, i.e., there exists $L>0$ such that 
    \begin{equation*}
        \big| |\partial E_t|(x) - |\partial E_t|(x') \big| \leq L\, d(x,x')
    \end{equation*}
    for every $t\in[0,T]$  and every $x, x' \in \mathbb{X}$.
\end{assumption}
\begin{remark}\label{rmk:lipschitz_tau_relation}
    In \cref{subsec:elaborate_mms,subsec:elaborate_BDF2}, we describe discrete minimizing schemes with a step size $\tau$. Whenever we work with \cref{ass:path+Lipsch}, we will assume that $\tau \leq \frac{1}{L}$, where $L$ is the Lipschitz constant assumed in \cref{ass:path+Lipsch}.
\end{remark}


Finally, we need the following assumption on the time derivative of the driving energy for proving that the measure involved in the energy balance is purely atomic.
Before proceeding, we introduce the quotient space $\X$ as follows:
\begin{equation}\label{eq:def_quot_space}
    \X \coloneqq \big([0,T]\times \Xx \big)/\sim,
\end{equation}
where $\sim$ is the equivalence relation on $[0,T]\times\Xx$ given by
\begin{equation}\label{eq:def_equiv_rel}
    \begin{split}
        (t_1,x_1)\sim (t_2,x_2) \iff &
        t_1=t_2 \mbox{ and $x_1,x_2$ belong to the same} \\ & \mbox{path-connected component of }\{x \in \Xx \mid |\partial E_{t_1}|(x) = 0\}.
    \end{split}
\end{equation}
We equip the space $\X$ with the quotient topology, and we denote with $q\colon [0,T] \times \Xx \to\X$ the quotient map. 
We recall that the quotient topology on $\X$ is the strongest that makes the mapping $q$ continuous.
Finally, we use the notation $[(t,x)]$ to describe the elements of $\X$, i.e., the equivalence classes induced by the relation \eqref{eq:def_equiv_rel}. 

\begin{assumption} \label{ass:t_der_quotient}
    For every $[(s,x)] \in \X$ we have that $\partial_t E_s(x_1) = \partial_t E_s(x_2)$, for every $(s,x_1),(s,x_2)\in \X$. Hence, we can define $\partial_t \hat E\colon \X\to \R$ as $\partial_t \hat E\big( [(s,x)] \big)\coloneqq \partial_t E_s(x)$ for every $[(s,x)] \in \X$. Furthermore, we require that $\partial_t \hat E$ is continuous.
\end{assumption}

\begin{remark}
    In the case the set $\{x\in \Xx \mid |\partial E_t|(x) =0\}$ consists of isolated points for every $t\in [0,T]$, then \cref{ass:t_der_quotient} is implied by \cref{ass:reg_E}, as the quotient space $\X$ is homeomorphic to $[0,T]\times \Xx$.
\end{remark}







\section{Discrete quasistatic evolutions: axiomatic construction} \label{sec:quasist_constr}

In this section, we detail the properties that a family of piecewise constant curves should satisfy to be employed to retrieve (through a limiting argument) the solutions of \cref{eq:crit_point_evol}.
We begin by introducing the curves that we use in our construction.

\begin{definition}[Discrete quasi\-static evolution]\label{def:discr_evol}
    Let us assume \cref{ass:metric_space,ass:reg_E}.
    Here, we fix a family of mappings $\bar{\omega}_t\colon \Xx \to \Xx$ indexed by $t \in [0, T]$, which we call the \emph{transition rule}.
    Given $\delta>0$ and an initial state $x_0\in \Xx$ such that $|\partial E_0|(x_0)=0$, we construct a discrete quasistatic evolution $\eta^\delta\colon [0, T] \to \Xx$ as follows:
    \begin{itemize}
        \item We define $M\coloneqq \lfloor T/\delta \rfloor$ (or $M\coloneqq T/\delta - 1$, if $T/\delta$ is integer).
        \item We set $w_0 = x_0$.
        % \item For $i=1,\ldots,M$, for $t\in [i\delta, (i+1)\delta)$ (or $t\in [i\delta,T]$ in case $i=M$), we set $\eta^\delta(t)=\bar \omega_{i\delta}\big(\eta^\delta((i-1)\delta)\big)$.
        \item For $i=1,\ldots,M$, we assign $w_{i} = \bar \omega_{i\delta}(w_{i-1})$.
        \item For $i=0,\ldots,M$, for $t\in [i\delta, (i+1)\delta)$ (or $t\in [i\delta,T]$ in case $i=M$), we set $\eta^\delta(t)=w_i$.
    \end{itemize}
    We also introduce
    \begin{equation} \label{eq:def_J_delta}
        J^\delta\coloneqq \{ i\delta \mid i=1,\ldots,M \}.
    \end{equation}
\end{definition}
We observe that in \cref{def:discr_evol} we have not specified any rule for deriving  $\bar \omega_{t}$.
One of the main contributions of the present paper is to provide a list of axioms that such a scheme should satisfy to be used for the construction---through a limiting argument---of a balanced viscosity quasistatic solution (see \cite{AR17} for this notion).

In our arguments, the identities on the energy balance shall play a pivotal role.
Given $\delta>0$ and a discrete quasistatic evolution $\eta^\delta \colon [0,T]\to \Xx$ constructed according to \cref{def:discr_evol}, we define the function $\E_\cdot(\eta^\delta) \colon [0,T]\to\R$ as
\begin{equation}\label{eq:def_evolving_energ}
    t \mapsto \E_t(\eta^\delta)\coloneqq E_t(\eta^\delta(t))
\end{equation}
for every $t\in [0,T]$.
We observe that, owing to \cref{ass:reg_E}, the following limits exist:
\begin{align*}
    \E_t^+(\eta^\delta)\coloneqq \lim_{\tau\to t^+}  \E_\tau(\eta^\delta) = \lim_{\tau\to t^+}  E_\tau(\eta^\delta(\tau)), \\
    \E_t^-(\eta^\delta)\coloneqq \lim_{\tau\to t^-}  \E_\tau(\eta^\delta) = \lim_{\tau\to t^-}  E_\tau(\eta^\delta(\tau))
\end{align*}
for every $t\in (0,T)$.
Moreover, we define a priori $\E_0^-(\eta^\delta):= \E_0(\eta^\delta)$ and $\E_T^+(\eta^\delta):= \E_T(\eta^\delta)$.
We observe that by construction $\E_\cdot (\eta^\delta)$ is \emph{continuous from the right}.

\subsection{Energy balance}
In this part, we state the first axiom and we establish an energy balance for the discrete quasi\-static evolutions that fulfill it.
Moreover, we show at which extent the energy balance is preserved when we let $\delta$ tend to $0$.

\begin{axiom}\label{ax:decreasing}
    Let the family of mappings $\bar{\omega}_t\colon \Xx \to \Xx$ indexed by $t \in [0, T]$ be the transition rule as in \cref{def:discr_evol}.
    Then, we require that for every $x \in \Xx$ and for every $t \in [0, T]$, we have that $E_t\big(\bar \omega_t(x)\big) \leq E_t(x)$.
\end{axiom}
We define the non-negative Radon measure $\mu^\delta \in \mathcal{M}([0,T])$ as follows:
\begin{equation}\label{eq:def_mu_delta}
    \mu^\delta(B) \coloneqq \sum_{t\in J^\delta \cap B}
    \Big[  \E_{t}^-(\eta^\delta) -
        \E_{t}^+(\eta^\delta) \Big]
\end{equation}
for every Borel set $B\subset[0,T]$.
On one hand, owing to \cref{ax:decreasing}, we observe that
\begin{equation} \label{eq:meas_point}
    \mu^\delta(\{ t \}) = \E_{t}^-(\eta^\delta) -
    \E_{t}^+(\eta^\delta) \geq 0
\end{equation}
for every $t\in J^\delta$ (i.e., $t=i\delta$ with $i=1,\ldots,M$). On the other hand, $\mu(\{ t \})=0$ if $t\not \in J^\delta$.


We are now in position of establishing the energy balance identity for discrete quasistatic evolutions.

\begin{lemma}\label{prop:energy_balance}
    Let us assume \cref{ass:metric_space,ass:reg_E}. 
    Given $\delta>0$, let $\eta^\delta \colon [0,T]\to \Xx$ be a discrete quasistatic evolution constructed according to \cref{def:discr_evol}.
    Then, if \cref{ax:decreasing} is satisfied, for every $0\leq t_1 \leq t_2 \leq T$ the following identity holds:
    \begin{equation}\label{eq:ener_bal}
        \E_{t_2}^+( \eta^\delta) -
        \E_{t_1}^-( \eta^\delta) =
        \int_{t_1}^{t_2} \partial_t E_\tau \big(\eta^\delta(\tau)\big) \diff \tau - \mu^\delta([t_1,t_2]),
    \end{equation}
    where the non-negative measure $\mu^\delta$ is defined as in \cref{eq:def_mu_delta}.
\end{lemma}
\begin{proof}
    Owing \cref{ass:reg_E} and recalling that $\eta^\delta$ is by construction piecewise constant, it follows that the function $t\mapsto \E_t(\eta^\delta)$ is of class $C^1$ on the interval $\big((i-1)\delta,i\delta\big)$ for every $i=1,\ldots,M$ (as well as on the very last piece $\big(M\delta,T\big)$).
    With an algebraic manipulation, we write
    \begin{equation}\label{eq:decomp_sum}
        \begin{split}
            \E_{t_2}^+(\eta^\delta) - \E_{t_1}^-(\eta^\delta) & =
            \Big( \E_{t_1}^+(\eta^\delta) - \E_{t_1}^- (\eta^\delta) \Big)
            +
            \Big( \E_{i_1\delta}^-(\eta^\delta) - \E_{t_1}^+ (\eta^\delta) \Big)                         \\& \quad 
            + \sum_{j=1}^{\ell} \Big( \E_{i_j\delta}^+(\eta^\delta) - \E_{i_j\delta}^- (\eta^\delta) \Big) 
            %\\& \quad 
            + \sum_{j=1}^{\ell-1}
            \Big( \E_{i_{j+1}\delta}^-(\eta^\delta) - \E_{i_j\delta}^+ (\eta^\delta) \Big)
            \\& \quad 
            + \Big( \E_{t_2}^-(\eta^\delta) - \E_{i_\ell \delta}^+ (\eta^\delta) \Big)
            +
            \Big( \E_{t_2}^+(\eta^\delta) - \E_{t_2}^- (\eta^\delta) \Big),
        \end{split}
    \end{equation}
    where $\{i_1<\ldots< i_\ell\}=J^\delta \cap (t_1,t_2)$. Using the Fundamental Theorem of Calculus and the measure $\mu^\delta$ defined in \cref{eq:def_mu_delta}, we rephrase \cref{eq:decomp_sum} as
    \begin{equation*}
        \begin{split}
            \E_{t_2}^+(\eta^\delta) - \E_{t_1}^-(\eta^\delta) & = -\mu^\delta(\{ t_1 \}) + \int_{t_1}^{i_1\delta} \partial_t E_\tau \big(\eta^\delta(\tau) \big) \diff \tau +
            \sum_{j=1}^{\ell}  -\mu^\delta(\{ i_j\delta \})
            \\& \qquad 
             +
            \sum_{j=1}^{\ell-1} \int_{i_j\delta}^{i_{i+1}\delta} \partial_t E_\tau \big(\eta^\delta(\tau)\big) \diff \tau 
            %\\& \quad 
            +
            \int_{i_\ell\delta}^{t_2} \partial_t E_\tau \big(\eta^\delta(\tau)\big) \diff \tau
            -\mu^\delta(\{ t_2 \}),
        \end{split}
    \end{equation*}
    which yields \cref{eq:ener_bal}.
\end{proof}

\begin{remark} \label{rmk:ener_bal_variants}
    In some circumstances, it can be useful to employ slight variations of \cref{eq:ener_bal}. For example, when dealing with the difference of the right limits $\E^+_{t_2}(\eta^\delta) - \E^+_{t_1}(\eta^\delta)$, we observe that
    \begin{equation*}
        \E^+_{t_2}(\eta^\delta) - \E^+_{t_1}(\eta^\delta) = \E^+_{t_2}(\eta^\delta) - \E^-_{t_1}(\eta^\delta) + \mu^\delta(\{t_1\}),
    \end{equation*}
    yielding
    \begin{equation*}
        \E_{t_2}^+( \eta^\delta) -
        \E_{t_1}^+( \eta^\delta) =
        \int_{t_1}^{t_2} \partial_t E_\tau \big(\eta^\delta(\tau)\big) \diff \tau - \mu^\delta((t_1,t_2])
    \end{equation*}
    for every $0 \leq t_1 \leq t_2 \leq T$. Similarly, we also have
    \begin{equation*}
        \E_{t_2}^-( \eta^\delta) -
        \E_{t_1}^-( \eta^\delta) =
        \int_{t_1}^{t_2} \partial_t E_\tau \big(\eta^\delta(\tau)\big) \diff \tau - \mu^\delta([t_1,t_2)),
    \end{equation*}
    and
    \begin{equation*}
        \E_{t_2}^-( \eta^\delta) -
        \E_{t_1}^+( \eta^\delta) =
        \int_{t_1}^{t_2} \partial_t E_\tau \big(\eta^\delta(\tau) \big) \diff \tau - \mu^\delta((t_1,t_2)).
    \end{equation*}
\end{remark}

We are now interested in studying the family $(\E_\cdot(\eta^{\delta_n}))_{n\geq 1}$ when $\delta_n\to 0$ as $n\to\infty$, under the hypothesis that the discrete quasistatic evolutions $(\eta^{\delta_n})_n$ are constructed using the same initial state $x_0\in \Xx$.
We begin by proving a boundedness result.

\begin{lemma}\label{lem:bound_energ_evol}
    Let us assume \cref{ass:metric_space,ass:reg_E,ass:der_time}.
    For every $\delta>0$, let $\eta^\delta \colon [0,T]\to \Xx$ be a discrete quasistatic evolution constructed according to \cref{def:discr_evol} and starting from $x_0\in \Xx$.
    Then, if \cref{ax:decreasing} is satisfied, we have
    \begin{equation} \label{eq:bound_energ_evol}
        \sup_{t\in[0,T]} \E_t(\eta^\delta) \leq E_0(x_0)e^{C_1(T+1)} +C_2 \frac{e^{C_1(T+1)}-1}{C_1},
    \end{equation}
    where $C_1,C_2>0$ are the constants that appear in \cref{ass:der_time}. In particular, the estimate is independent of $\delta$.
\end{lemma}
\begin{proof}
    Let us consider $t\in[0,\delta)$. Since $\eta^\delta$ is constant on this interval, we have that  $\E_\cdot (\eta^{\delta})$ is $C^1$ in $[0, \delta)$.
    Then, by virtue of \cref{ass:der_time} we compute
    \begin{equation} \label{eq:der_energ_evolv}
        \left| \frac{\mathrm{d}}{\mathrm{d}t} \E_t(\eta^\delta) \right| =  \left| \partial_t E_t(x_0) \right| \leq C_1 E_t(x_0) + C_2 =
        C_1\E_t(\eta^\delta) + C_2,
    \end{equation}
    which yields
    \begin{equation}\label{eq:est_2_energ_evolv}
        \sup_{t\in[0,\delta)} \E_t(\eta^\delta) \leq \left( \E_0(\eta^\delta) + \delta C_2 \right) e^{\delta C_1},
    \end{equation}
    where we applied the Gr\"onwall inequality. Moreover, repeating the same argument on the interval $[\delta,2\delta)$, we deduce that
    \begin{equation}\label{eq:est_1_energ_evolv}
        \sup_{t\in[\delta,2\delta)} \E_t(\eta^\delta) \leq \left( \E_\delta(\eta^\delta) + \delta C_2 \right) e^{\delta C_1}.
    \end{equation}
    However, recalling \cref{def:discr_evol} and \cref{eq:def_evolving_energ}, in virtue of \cref{ax:decreasing}, we have that
    \begin{equation*}
        \sup_{t\in[0,\delta)} \E_t(\eta^\delta) \geq \E^-_\delta(\eta^\delta) \geq \E^+_\delta(\eta^\delta) = \E_\delta(\eta^\delta),
    \end{equation*}
    that, together with \cref{eq:est_1_energ_evolv,eq:est_2_energ_evolv}, implies
    \begin{equation*}
        \begin{split}
            \sup_{t\in[0,2\delta)} \E_t(\eta^\delta) & \leq  \left( \sup_{t\in[0,\delta)} \E_t(\eta^\delta) + C_2\delta \right) e^{C_1\delta} 
            %\\ & 
            \leq \E_0(\eta^\delta)e^{2\delta C_1} + \delta C_2 \sum_{j=1}^2 e^{j\delta C_1}.
        \end{split}
    \end{equation*}
    With an inductive argument, it follows that
    \begin{equation*}
        \sup_{t\in[0,T]} \E_t(\eta^\delta) \leq \E_0(\eta^\delta)e^{(M +1) \delta C_1 } + \delta C_2 \sum_{j=1}^{M+1} e^{j\delta C_1},
    \end{equation*}
    where $M$ is the integer defined in \cref{def:discr_evol}.  
    By simple algebraic manipulation and basic properties of the exponential functions, we conclude for~\eqref{eq:bound_energ_evol}.
\end{proof}

The boundedness of the energy along discrete quasistatic evolutions implies that the trajectories themselves are uniformly bounded, as we shall see below.

\begin{lemma}\label{lem:bound_traj}
    Let us assume \cref{ass:metric_space,ass:reg_E,ass:der_time,ass:unif_coerc}.
    For every $\delta>0$, let $\eta^\delta\colon [0,T]\to \Xx$ be a discrete quasistatic evolution constructed according to \cref{def:discr_evol} and starting from $x_0\in \Xx$.  
    If \cref{ax:decreasing} is satisfied, there exists a compact set $K \subset \Xx$ such that $\eta^\delta(t)\in K$ for every $t\in [0,T]$ and every $\delta >0$.
\end{lemma}
\begin{proof}
    From \cref{lem:bound_energ_evol} it follows that there exists $K_1> 0$ independent of $\delta$ such that
    \begin{equation*}  %\label{eq:energ_in_time}
        \sup_{t\in [0,T]} \E_t(\eta^\delta) =
        \sup_{t\in [0,T]} E_t(\eta^\delta(t)) \leq K_1,
    \end{equation*}
    yielding $E_t(\eta^\delta(t)) \leq K_1$ for every $t\in [0,T]$.
    Owing to \cref{rmk:coerc_Et}  and of \cref{ass:unif_coerc}, we deduce the thesis.
    %To conclude, it suffices to show that there exists $K_2>0$ independent of $\delta$ such that 
    %\begin{equation} \label{eq:coercivity_goal}
    %    G(u^\delta(t)) = \sup_{\tau\in [0,T]} E_\tau(u^\delta(t)) \leq K_2
    %\end{equation}
    %for every $t\in [0,T]$, where $G:\R^d\to\R$ is the coercive function provided by Assumption~\ref{ass:unif_coerc}. Using Assumption~\ref{ass:der_time} and the Gr\"onwall Lemma, we obtain 
    %\begin{equation*}
    %    E_\tau(u^\delta(t)) \leq (K_1 + C_2|\tau-t|)e^{C_1|\tau-t|}
    %\end{equation*}
    %for every $t,\tau \in [0,T]$. This proves \eqref{eq:coercivity_goal}.
\end{proof}


In the next result we study the variation of the functions $t\mapsto \E_t(\eta^\delta)$ as we vary the parameter $\delta$.

\begin{lemma}\label{lem:bound_var}
    Let us assume \cref{ass:metric_space,ass:reg_E,ass:der_time,ass:unif_coerc}.
    For every $\delta>0$, let $\eta^\delta \colon [0,T]\to \Xx$ be a discrete quasistatic evolution constructed according to \cref{def:discr_evol} and starting from $u_0\in \Xx$. 
    Let us consider the function $\E_\cdot(\eta^\delta) \colon [0,T]\to\R$ defined in \cref{eq:def_evolving_energ}. Then, if \cref{ax:decreasing} is satisfied, there exists $K>0$ independent of $\delta$ such that
    \begin{equation}\label{eq:bound_variation}
         \sup_{\mathcal{P}} \, \sum_{j=1}^m|\E_{s_{j+1}}(\eta^\delta)-\E_{s_{j}}(\eta^\delta)| \leq  K,
    \end{equation}
     where the supremum is taken over the family of finite partitions $\mathcal{P}=\{0=s_1<s_2<\ldots<s_m=T \}$ of $[0,T]$.
\end{lemma}
\begin{proof}
Let $m \in \mathbb{N}$ and let $\mathcal{P} = \{ 0 = s_{1} < s_{2}  < \ldots < s_{m} = T\}$ be a partition of~$[0, T]$.
Recalling that $\E_\cdot(\eta^\delta)$ is continuous from the right,  for every $j = 1, \ldots, m-1$ we have that
    \begin{equation} \label{eq:ener_bal_op_cl}
        \begin{split}
            \E_{s_{j+1}}(u^\delta)-\E_{s_{j}}(u^\delta) 
            & =  \E_{s_{j+1}}^+(\eta^\delta)-\E_{s_{j}}^-(\eta^\delta) + \E_{s_{j}}^-(\eta^\delta) - \E_{s_{j}}^+(\eta^\delta) \\
            & = \int_{s_j}^{s_{j+1}} \partial_t E_\tau \big( \eta^\delta(\tau) \big) \diff \tau - \mu^\delta([s_j,s_{j+1}]) + \mu^\delta(\{ s_j \}) \\
            & = \int_{s_j}^{s_{j+1}} \partial_t E_\tau \big( \eta^\delta(\tau) \big) \diff \tau - \mu^\delta((s_j,s_{j+1}]),
        \end{split}
    \end{equation}
    for every $s_j<s_{j+1}$.
    Since $\mu^\delta$ is a non-negative measure, we deduce that
    \begin{equation} \label{eq:bound_var_1}
        \sum_{j=1}^m|\E_{s_{j+1}}(\eta^\delta)-\E_{s_{j}}(\eta^\delta)| \leq
        \int_0^T \left| \partial_t E_\tau\big( \eta^\delta(\tau) \big) \right| \diff \tau + \mu^\delta([0,T]).
    \end{equation}
    We further observe that, in virtue of \cref{ass:der_time} and \cref{lem:bound_energ_evol}, we have
    \begin{equation} \label{eq:bound_var_2}
        \left| \partial_t E_\tau\big( \eta^\delta(\tau) \big) \right| \leq  C_1 \E_\tau(\eta^\delta) + C_2  \leq K_1
    \end{equation}
    for every $\tau\in [0,T]$, where $K_1$ is a constant that does not depend on $\delta$.
    Moreover, from \cref{prop:energy_balance} it descends that
    \begin{equation*}
        \mu^\delta([0,T]) = \E_0(\eta^\delta) - \E_T(\eta^\delta) + \int_0^T\partial_t E_\tau\big(\eta^\delta(\tau)\big) \diff \tau,
    \end{equation*}
    and, combining the last identity with \cref{eq:bound_var_2} and with \cref{prop:energy_balance}, we obtain
    \begin{equation} \label{eq:bound_var_3}
        \mu^\delta([0,T]) \leq K_2,
    \end{equation}
    where, once again, $K_2>0$ does not depend on $\delta$. Finally, combining \cref{eq:bound_var_1,eq:bound_var_2,eq:bound_var_3}, we deduce the bound in \cref{eq:bound_variation}.
\end{proof}



We are now in position for establishing a result analogue to \cite[Proposition~5.2]{AR17}.

\begin{proposition}\label{prop:limit_energies}
    Let us assume \cref{ass:metric_space,ass:reg_E,ass:der_time,ass:unif_coerc}.
    Given a non-negative decreasing sequence $(\delta_n)_n$ such that $\delta_n\to 0$ as $n\to\infty$, let $\eta^{\delta_n} \colon [0,T]\to\Xx$ be discrete quasistatic evolutions constructed according to \cref{def:discr_evol} and starting from $x_0\in \Xx$. Then, if \cref{ax:decreasing} is satisfied, there exist a positive Radon measure $\bar \mu \in \mathcal{M}([0,T])$, and functions $\bar \E \in BV([0,T],\R)$ and $\mathcal{D}\in L^\infty([0,T],\R)$ such that, up to a subsequence, for $n\to \infty$ we have
    \begin{equation}\label{eq:convergences}
        \begin{split}
             & \mu^{\delta_n}\weak^* \bar \mu \quad \mbox{in }\mathcal M([0,T]),                  \\
             & \lim_{n\to\infty} \E_t(\eta^{\delta_n}) = \bar\E_t \quad \mbox{for every } t\in[0,T], \\
             & \mathcal{D}^{\delta_n} \weak^* \mathcal{D} \quad \mbox{in } L^\infty([0,T],\R),
        \end{split}
    \end{equation}
    where we introduced the notation $t\mapsto \mathcal{D}^{\delta_n}(t)\coloneqq \partial_t E_t\big( \eta^{\delta_n}(t) \big)$.
    Moreover, if we use $\bar \E^+_t, \bar \E^-_t$ to denote, respectively, the right and the left limits of $\bar \E$ at the instant $t\in[0,T]$ (here we set $\bar \E^-_0 \coloneqq \bar \E_0$ and $\bar \E^+_T \coloneqq \bar \E_T$), then we have that
    \begin{equation} \label{eq:ener_bal_limit}
        \bar \E^+_{t_2} - \bar \E^-_{t_1} = \int_{t_1}^{t_2} \mathcal{D}(\tau) \diff \tau - \bar \mu([t_1,t_2])
    \end{equation}
    for every $0\leq t_1\leq t_2 \leq T$.
    %In addition, $\bar \E$ is continuous from the right.
\end{proposition}
\begin{proof}
    For every $n\geq1$, we define $\F^{\delta_n}\colon [0,T]\to\R$ as
    \begin{equation} \label{eq:def_F_ancill}
        \F^{\delta_n}_t \coloneqq \E_t(\eta^{\delta_n})- \int_0^t \mathcal{D}^{\delta_n}(\tau) \diff \tau
    \end{equation}
    for every $t\in [0,T]$.
    We observe that the functions $\F^{\delta_n}$ are non-increasing. Indeed, given $0\leq t_1 \leq t_2 \leq T$ we have that
    \begin{equation*}
        \begin{split}
            \F_{t_2}^{\delta_n} - \F_{t_1}^{\delta_n} & =
            \E_{t_2}^+(\eta^{\delta_n}) - \E_{t_1}^+(\eta^{\delta_n})
            - \int_{t_1}^{t_2} \mathcal{D}^{\delta_n}(\tau)\diff \tau %\\& 
            = -\mu^{\delta_n}((t_1,t_2]) \leq 0,
        \end{split}
    \end{equation*}
    where we used \cref{rmk:ener_bal_variants}.
    Moreover, the sequence $(\F^{\delta_n})_n$ is uniformly bounded, owing to \cref{eq:bound_var_2} and \cref{lem:bound_energ_evol}. By Helly's Selection Theorem, it follows that up to a subsequence, $(\F^{\delta_n})_n$ is pointwise convergent to a non-increasing function $\bar \F$ at every point $t\in [0,T]$. In addition, using again the estimate in \cref{eq:bound_var_2}, it follows that the sequence $(\mathcal{D}^{\delta_n})_n$ is pre-compact in the weak-$*$ topology of $L^\infty$, while the measures $(\mu^{\delta_n})_n$ are pre-compact in the weak-$*$ topology of $M([0,T])$.
    These  observations establish the first and the third convergences in \eqref{eq:convergences}, along a proper and not relabelled subsequence. Finally, by passing to the limit in \cref{eq:def_F_ancill}, we get the pointwise convergence of the energy stated in \eqref{eq:convergences}.
    To prove the energy balance for $\bar \E$, we argue as in \cite{AR17}. Namely, given $0< t_1\leq t_2 < T$, we compute
    \begin{equation}\label{eq:portmant_inf}
        \begin{split}
            \bar \mu ([t_1,t_2]) & =
            \lim_{k\to\infty}
            \bar \mu((t_1-1/k, t_2+1/k))  \leq
            \lim_{k\to\infty}
            \liminf_{n\to\infty} \mu^{\delta_n}((t_1-1/k, t_2+1/k))                                            \\
                                 & \leq
            \lim_{k\to\infty}
            \liminf_{n\to\infty} \mu^{\delta_n}((t_1-1/k, t_2+1/k])                                            \\
            %        & = \lim_{k\to\infty}        \liminf_{n\to\infty}       \left( \E_{t_1-1/k}^+(u^{\delta_n}) -        \E_{t_2+1/k}^+(u^{\delta_n}) + \int_{t_1-1/k}^{t_2+1/k}\mathcal{D}^{\delta_n}(\tau)\diff \tau \right)\\        
                                 & = \lim_{k\to\infty}
            \left( \bar\E_{t_1-1/k} -
            \bar\E_{t_2+1/k} + \int_{t_1-1/k}^{t_2+1/k}\mathcal{D}^{\delta_n}(\tau)\diff \tau \right)             \\
                                 & =\bar\E_{t_1}^- -\bar\E_{t_2}^+ + \int_{t_1}^{t_2}\mathcal{D}(\tau)\diff \tau.
        \end{split}
    \end{equation}
    Moreover, we have
    \begin{equation}
        \label{eq:portmant_sup}
        \begin{split}
            \bar \mu ([t_1,t_2]) & =
            \lim_{k\to\infty}
            \bar \mu([t_1-1/k, t_2+1/k])  \geq
            \lim_{k\to\infty}
            \limsup_{n\to\infty} \mu^{\delta_n}([t_1-1/k, t_2+1/k])                                            \\
                                 & \geq
            \lim_{k\to\infty}
            \limsup_{n\to\infty} \mu^{\delta_n}((t_1-1/k, t_2+1/k])                                            \\
            %        & = \lim_{k\to\infty}        \liminf_{n\to\infty}       \left( \E_{t_1-1/k}^+(u^{\delta_n}) -        \E_{t_2+1/k}^+(u^{\delta_n}) + \int_{t_1-1/k}^{t_2+1/k}\mathcal{D}^{\delta_n}(\tau)\diff \tau \right)\\        
                                 & = \lim_{k\to\infty}
            \left( \bar\E_{t_1-1/k} -
