In the next corollary we report some further properties of the limiting function $\bar \E$ constructed above.

\begin{corollary} \label{cor:reg_limit_ener}
    Under the same assumptions and notations as in \cref{prop:limit_energies}, we deduce that the function $\bar \E \colon [0,T]\to \R$ is of bounded variation, that its distributional derivative satisfies $d\bar\E = \mathcal{D L}^1 -\bar \mu$, and that
    \begin{equation*}
        \bar \E_t^+ - \bar \E_t^- = - \bar \mu(\{t\})  \qquad \text{for every $t \in [0, T]$}. 
    \end{equation*}
    Finally, the discontinuity points of $\bar \E$ (i.e., the atoms of $\bar \mu$) are at most countably many.
\end{corollary}
\begin{proof}
    The proof directly descends from \eqref{eq:portmant_inf} and \eqref{eq:portmant_sup}.
\end{proof}



\subsection{Limiting construction of quasi\-static evolutions}
In this part, we show how we can obtain quasi\-static evolutions using a family of curves $(\eta^\delta)_{\delta}$ constructed according to \cref{def:discr_evol}.
We introduce below the second axiom.

\begin{axiom}\label{ax:gradient}
    Let the family of mappings $\bar{\omega}_t\colon \Xx \to \Xx$ indexed by $t \in [0, T]$ be the transition rule as in \cref{def:discr_evol}.
    Then, we require that for every $x \in \Xx$ and for every $t \in [0, T]$, we have that $|\partial E_t|\big(\bar \omega_t(x)\big) = 0$.
\end{axiom}

%\begin{remark}\label{rmk:ax_grad}
%    We stress the fact that the precise behavior of the function $\delta\mapsto\epsilon_\delta$ near $0$ is not playing any role in our analysis.
%\end{remark}

In the next result, we show that the curves $\eta^{\delta}$ are somehow close to be made of critical points, even for $t\not\in J^\delta$.
More precisely, we provide an estimate uniform in $\delta$ for the magnitude of $|\partial E_t|$ along $\eta^\delta$.

\begin{lemma}\label{lem:est_grad_ener}
    Let us assume \cref{ass:metric_space,ass:reg_E,ass:der_time,ass:unif_coerc}.
    For every $\delta>0$, let $\eta^\delta \colon [0,T]\to \R^d$ be a discrete quasistatic evolution constructed according to \cref{def:discr_evol} and starting from $x_0\in \Xx$.
    Then, if \cref{ax:decreasing,ax:gradient} are satisfied, for every $\e>0$ there exists  $\bar \delta >0$ such that for every $\delta \in (0,  \bar \delta]$
    \begin{equation*}
        \sup_{t\in [0,T]} |\partial E_t| \big( \eta^\delta(t) \big) \leq \e.
    \end{equation*}
\end{lemma}
\begin{proof}
    Recalling the definition of $J^\delta$ in \cref{eq:def_J_delta}, we observe that the set $J^\delta \cup \{0\}=\{i\delta\mid i=0,\ldots,M\}$ is  a $\delta$-net for the interval $[0,T]$. In virtue of \cref{lem:bound_traj}  and of \cref{ass:unif_coerc}, there exists a compact set $K\subset \Xx$ such that $\eta^\delta(t)\in K$ for every $t\in[0,T]$ and for every $\delta>0$.
    Moreover, owing to \cref{ass:reg_E}, it descends that the space-gradient $|\partial E_\cdot|\colon  [0,T]\times \Xx \to \R$ is uniformly continuous when restricted to $[0,T]\times K$, and we denote with $\xi:[0,T]\times [0,\mathrm{diam}(K)]\to \R_+$ a modulus of continuity. We recall that $\xi$ is a function non-decreasing in each argument and that satisfies $\xi(0,0)=\lim_{(s,r)\to(0^+,0^+)}\xi(s,r) =0$.
    Let us fix $t\in [0,T]$. Then, there exists $\hat i\in \{0,\ldots,M\}$ such that $\hat i \delta\leq t<(\hat i + 1)\delta$. By \cref{ax:gradient} and recalling that $\eta^\delta$ is piecewise constant, we observe that $|\partial E_{\hat i \delta}| \big(\eta^\delta(t)\big)=0 $. Therefore, we have that
    \begin{equation*}
        |\partial E_{t}| \big(\eta^\delta(t)\big) \leq |\partial E_{\hat i \delta}| \big(\eta^\delta(t)\big) + \left|
        |\partial E_{t}| \big(\eta^\delta(t)\big) - |\partial E_{\hat i \delta}| \big(\eta^\delta(t)\big) \right|
        %\leq \epsilon_\delta + \xi(t-\hat i\delta, 0 ) 
        \leq \xi(\delta,0),
    \end{equation*}
    and this concludes the proof.
\end{proof}

\begin{remark}\label{rmk:almost_critic}
    A similar result is reported in \cite[Notation~5.3]{AR17} for the class of curves obtained by solving a properly rescaled gradient flow.
    However, in the construction in \cite{AR17}, it is possible to prove that the set of instants where the gradients converge to $0$ has \emph{full Lebesgue measure}, but not that it is the whole interval $[0,T]$.
\end{remark}

Before proceeding, we recall the definition of the quotient space $\X$ given in \cref{eq:def_quot_space}:
\begin{equation*}
    \X \coloneqq \big([0,T]\times \Xx \big)/\sim,
\end{equation*}
where $\sim$ is the equivalence relation on $[0,T]\times\Xx$ given by (cf.~\cref{eq:def_equiv_rel})
\begin{equation*}
    \begin{split}
        (t_1,x_1)\sim (t_2,x_2) \iff &
        t_1=t_2 \mbox{ and $x_1,x_2$ belong to the same} \\ & \mbox{path-connected component of }\{x \in \Xx \mid |\partial E_{t_1}|(x) = 0\}.
    \end{split}
\end{equation*}
The space $\X$ is equipped with the quotient topology.  We denote with $q\colon [0,T] \times \Xx \to\X$ the quotient map, and we use the notation $[(t,x)]$ to describe the elements of $\X$, i.e., the equivalence classes induced by \eqref{eq:def_equiv_rel}. We will often denote by $\hat{x}$ an element $[(t, x)]$ of~$\X$.

\begin{lemma}\label{lem:q_space_haus}
Let us assume \cref{ass:metric_space,ass:conn_comp}. Then, the quotient space $\X$ defined in \eqref{eq:def_quot_space} with the relation \eqref{eq:def_equiv_rel} is a Hausdorff space, i.e., for every $\hat{x}_{1}, \hat{x}_{2}\in \X$ with $\hat{x}_{1} \neq \hat{x}_{2}$ there exist two disjoint open sets $U_1,U_2 \subset \X$ such that  $\hat{x}_{1}\in U_1$ and $\hat{x}_{2}\in U_2$.
\end{lemma}

\begin{proof}
    For every $ \hat{x} = [(t,x)] \in\X$, let us introduce the set $A\coloneqq \{w\in\Xx \mid (t,w)\sim (t,x)\}$, which satisfies either $A=\{x\}$ in the case $|\partial E_t|(x)\neq 0$, or, if $|\partial E_t|(x)=0$, $A$ does coincide with the path-connected component containing $x$ of the critical points of $E_t$.
    Moreover, from \cref{ass:conn_comp} it descends that $A$ is compact.
    Then, observing that  $q^{-1} ( \hat{x} )  = \{t\} \times A$, we deduce the thesis by applying \cite[Theorem~8.11 and Exercise~8.13.(l)]{Kos}, and recalling that $[0,T]\times\Xx$ is a Hausdorff space.
\end{proof}

We observe that \cref{lem:q_space_haus} implies the uniqueness of the limit for every converging sequence in $\X$.
