Furthermore, we notice that the energy $E\colon [0,T]\times\Xx \to\R$ can be defined also on the quotient space $\X$. Namely, given $\hat x = [(t,x)]\in\X$, we set
\begin{equation} \label{eq:energy_hat}
    \hat E(\hat x) = \hat E\big( [(t,x)] \big)\coloneqq  E_{t} (x).
\end{equation}
Let us show that this definition does not depend on the representative of the class. Indeed, if $|\partial E_t|(x)\neq 0$, we have that $[(t,x)] = \{(t,x)\}$. Otherwise, if  $|\partial E_t|(x) = 0$, let us consider another element of the same class $(t,x')\in[(t,x)]$ (i.e., in the same path-connected component of the set of critical points), and we observe that $ E_{t} ( x) = E_{t} (x')$ by virtue of \cref{ass:conn_comp}. 
This shows that $\hat E\colon \X\to\R$ is well-defined, and we have that $E=\hat E \circ q$.
The last identity (together with the continuity of $E$) implies that $\hat E \colon \X\to\R$ is continuous as well (see the \textit{universal property of quotients} \cite[Theorem~5.2]{Kos}).

In the next fundamental axiom, we state a property for the limits of the sequences $\left(\eta^{\delta_n}(t_1^n)\right)_n,\left(\eta^{\delta_n}(t_2^n)\right)_n$ when $t_1^n, t_2^n\to t$ as $n\to\infty$.
In the limiting construction, this axiom plays the same role as \cite[Lemma~5.1]{AR17}.

\begin{axiom}\label{ax:limits_traject}
    Given a non-negative decreasing sequence $(\delta_n)_n$ such that $\delta_n\to 0$ as $n\to\infty$, let $\eta^{\delta_n}\colon [0,T]\to\Xx$ be discrete quasistatic evolutions constructed according to \cref{def:discr_evol} and starting from $x_0\in \Xx$. Let us further assume that along $\left(\eta^{\delta_n}\right)_n$ the convergences reported in~\eqref{eq:convergences} hold.
    For every $t\in [0,T]$, let us consider sequences $(t_1^n)_n,(t_2^n)_n\subset[0,T]$ and $x_{1}, x_{2} \in \Xx$ such that $t_1^n,t_2^n\to t$ as $n\to\infty$ with $t_1^n\leq t_2^n$ for every $n$, and such that $\eta^{\delta_n}(t_1^n)\to x_1$ and $\eta^{\delta_n}(t_2^n)\to x_2$ as $n\to\infty$.
    If $x_1$ and $x_2$ belong to \emph{different path-connected components} of the set $\{x\in \Xx \mid |\partial E_t|(x) = 0\}$, then there exists $c>0$ such that
    \begin{equation*}
        \bar \mu(\{t\}) \geq c, \qquad E_t( x_1 ) - E_t( x_2 )\geq c.
    \end{equation*}
\end{axiom}

\begin{remark}
    If compared to \cref{ax:decreasing,ax:gradient}, we notice that \cref{ax:limits_traject} sounds intrinsically different and less elegant, as it does not directly involve the transition rules $( \bar{\omega}_t )_{t\in [0,T]}$, but it is rather formulated in terms of the subsequence constructed in \cref{prop:limit_energies}.
    We shall devote \cref{sec:actions_abstract} to amend this point: We formulate \cref{ax:action_triangular_time_stable}, we show that \cref{ax:decreasing,ax:gradient,ax:action_triangular_time_stable} imply \cref{ax:limits_traject} (see \cref{lemma:action_implies_traj}), and finally in \cref{def:generated_by_curves} we describe a class of transition rules that comply with \cref{ax:action_triangular_time_stable} (see \cref{lemma:good_curves_fulfill_continuous_triangular_inequality}). Examples of such transition rules are provided in \cref{sec:examples_of_evolution_rules}. 
\end{remark}

\begin{remark}\label{rmk:crit_limits}
    Using the same notations as in \cref{ax:limits_traject}, the points $x_1,x_2$ are automatically critical points.
    Indeed, from the construction of $\eta^{\delta_n}$ and from \cref{lem:est_grad_ener}, it follows that
    \begin{equation*}
        \lim_{n\to\infty} \sup_{s\in[0,T]}|\partial  E_s| \big(\eta^{\delta_n}(s) \big)=0.
    \end{equation*}
    Hence, from the continuity of $|\partial E_\cdot|\colon [0,T]\times\Xx\to \R$, we conclude that $|\partial E_t|(x_1)=0$. The argument for $x_2$ is exactly the same.
\end{remark}

\begin{remark}\label{rmk:discont_points}
    The previous axiom is particularly meaningful for the instants $t\in[0,T]$ such that $\bar \mu(\{t\}) =0$. Indeed, in this case we conclude that the points $x_1,x_2\in \Xx$ obtained as above must belong to the same path-connected component of $\{x\in \Xx \mid |\partial E_t| (x) = 0\}$. In particular, in  case that the critical points of $E_t$ are isolated (as assumed in \cite{AR17}), it descends that $x_1=x_2$.
\end{remark}


