From this discussion, we are now in a position to distill the essential properties of the gradient flow
that allow for a proof of \cref{ax:action_triangular_time_stable}.
As those properties are satisfied by a range of transition rules ---whether they are discrete or additionally incorporate momentum---, the application of the resulting framework is not limited to the gradient flow.
To allow for a unified exposition of such actions, we consider curves in the phase space.
As a guide to the formal proof, \cref{fig:proof_shortcut_candidate_curve} should be
understood as a schematic representation of this phase space. \\
In the following, we denote $(a, b] \cap \Ii$ and $[a, b] \cap \Ii$ as $(a, b]_{\Ii}$ and $[a, b]_{\Ii}$, respectively, whenever
$\Ii \in \{\R, \Z\}$ and $a, b \in \Ii$.
\begin{definition}\label{def:generated_by_curves}
    An action $c_t$ is \emph{generated by curves} if there exists an index set
    ${\Ii \in \{\Z, \R\}}$, a \emph{phase space} $\Pp$ equipped with a metric $d_{\Pp}$ and functions
    \begin{equation*}
        \begin{array}{rlrlrlrl}
            \Gamma: &  & \Pp \times \Pp                                          & \, &  & \rightarrow & \, & 2^{\{ \gamma: [a, b]_\Ii \rightarrow \Pp \mid a < b \in \Ii\}} \\
                    &  & (p_1, p_2)                                              &    &  & \mapsto     &    & \Gamma(p_1, p_2),                                              \\
            i:      &  & \Xx                                                     &    &  & \rightarrow &    & \Pp,                                                           \\ [0.3em]
            \Cost:  &  & \Pp \times [0, T]                                            &    &  & \rightarrow &    & [0, +\infty)                                                   \\
                    &  & (p, t)                                                  &    &  & \mapsto     &    & \Cost_t(p),                                                    \\
        \end{array}
    \end{equation*}
     such that  for every $\gamma \in \Gamma(p_1, p_2)$ it holds $\gamma(a) = p_1$ and $\gamma(b) = p_2$, $i$ is a closed immersion, $\Cost$ is continuous, and $c_t \colon \Xx \times \Xx \to [0, \infty)$ is given as
    \begin{equation} \label{eq:action_infimum}
    \begin{split}
        & c_t(x_1, x_2) = \mathfrak{c}_{t} (i(x_{1}), i(x_{2}))\qquad \text{for $x_{1}, x_{2} \in \Xx$},\\
        & \mathfrak{c}_{t} (p_{1}, p_{2}) := \inf_{\gamma \in \Gamma(p_{1}, p_{2})} \int_{(a, b]_\Ii} \Cost_t(\gamma_s) \diff \nu(s) \qquad \text{for $p_{1}, p_{2} \in \Pp$},\\
        \end{split}
    \end{equation}
    where $\nu$ is the Lebesgue measure if $\Ii = \R$ and the counting measure if $\Ii = \mathbb{Z}$.
    We call the value of $\Gamma$ the \emph{set of admissible curves} for $p_1,p_2 \in \Pp$, and the value of $\Cost$ the \emph{price}
    % and we write $c_t(p_1, p_2) \coloneqq \inf_{\gamma \in \Gamma(p_1, p_2)} \int_{(a, b]_\Ii} \Cost_t(\gamma_s) \diff\nu(s)$
    for $p \in \Pp$ and $t\in [0,T]$. \\
    Moreover, we require that the following properties hold:
    \begin{properties}
        \item \label{prop:curve_restriction} Restrictions, concatenations and shifts of admissible curves are again admissible curves.
        In other words, for $p_1, p_2, p_3 \in \Pp$ and $a \leq s \leq b \in \Ii$, the following holds:
        \begin{itemize}
            \item \emph{Restrictions:} For all $\gamma \in \Gamma(p_1, p_3)$ such that $\dom(\gamma) = [a, b]_\Ii$ and $\gamma(s) = p_2$, we have that $\gamma|_{[a, s]_\Ii} \in \Gamma(p_1, p_2)$ and $\gamma|_{[s, b]_\Ii} \in \Gamma(p_2, p_3)$.
            \item \emph{ Concatenations:} For all $\gamma \in \Gamma(p_1, p_2)$ and $\gamma' \in \Gamma(p_2, p_3)$ such that $\dom(\gamma) = [a, s]_\Ii$ and $\dom(\gamma') = [s, b]_\Ii$, we have that $\gamma \cup \gamma' \in \Gamma(p_1, p_3)$,
                  where $\gamma \cup \gamma': [a, b]_\Ii \rightarrow \Pp$ is defined as
                  \begin{equation*}
                      \gamma \cup \gamma'(s) \coloneqq
                      \begin{cases}
                          \gamma(s)  & \text{if } s \in [a, s]_\Ii, \\
                          \gamma'(s) & \text{if } s \in (s, b]_\Ii.
                      \end{cases}
                  \end{equation*}
            \item \emph{Shifts:} For all $\gamma \in \Gamma(p_1, p_2)$ such that $\dom(\gamma) = [a, b]$ and all $r \in \Ii$, we have that $\gamma'\colon  [a - r, b - r] \rightarrow \Pp$ with $\gamma'(t) = \gamma(t + r)$ is in $\Gamma(p_1, p_2)$.
        \end{itemize}
        \item\label{prop:cost_nonzero} For $p \in \Pp$, $\Cost_t(p)=0$ if and only if there exists $x \in \Xx$ such that $i(x) = p$ and
        $ |\partial E_t|(x) = 0$.
        \item\label{prop:no_cost_in_within_conn_component}
        For $x_1 , x_2 \in \Xx$ with $x_1\neq x_2$, $c_t(x_1, x_2) = 0$ if and only if $i(x_1)$ and $i(x_2)$
        lie in the same connected component of $\{p \in \Pp \mid \Cost_t(p) = 0\}$.
        \item\label{prop:curves_coercive} For all $K \subseteq \Pp$ compact, there exists some $K' \subseteq \Pp$ compact
        such that for all $p_1, p_2 \in K$ and all $\varepsilon > 0$,
        there exists $\gamma \colon [a, b]_\Ii \rightarrow \Pp$,  $\gamma \in \Gamma(p_1, p_2)$ such that $\im(\gamma) \subseteq K'$ and 
        \begin{equation*}
            \int_{(a, b]_\Ii} \Cost_t\big(\gamma(s)\big) \diff\nu(s) \leq  \mathfrak{c}_t  (p_1, p_2) + \varepsilon.
        \end{equation*}
        This means that for points $p_1, p_2 \in K$, we may take the infimum in \cref{eq:action_infimum}
        over only those admissible curves whose image lies in $K'$.
        \item\label{prop:cheap_fuel_cheap_action} For all $K \subseteq \Pp$ compact and $\varepsilon > 0$, there exists some $L, P > 0$ such that for all $p_1, p_2 \in K$
        such that $\Cost_t(p_1) \leq P$, $\Cost_t(p_2) \leq P$, and $d_\Pp(p_1, p_2) \leq L$, we have that $ \Cc_t  (p_1, p_2) \leq \varepsilon$.
        Informally, this means that the value of the action is small between two points which are close to each other and where $\Cost_t$ is small.
    \end{properties}
\end{definition}

\begin{remark}
    Notice that in what follows, the expressions of the functions appearing in~\cref{def:generated_by_curves} will be energy-dependent.
\end{remark}


\subsection{Examples of transition rules} \label{sec:examples_of_evolution_rules}
Before we show how the abstract \cref{def:generated_by_curves} relates to \cref{ax:action_triangular_time_stable},
we present some examples of actions---and the corresponding transition rules---that are generated by curves.
The fact that those actions indeed satisfy the required properties is contained in \cref{lemma:gradient_flow_summary_lemma,lemma:MMS_summary_lemma,lemma:BDF2_summary_lemma}, whose proofs are postponed to \cref{sec:examples_of_evolution_rules_elaborate}.
\subsubsection{The gradient flow}
\newcommand{\GFprime}{^{^{_{F'}}}}
\newcommand{\ruleGF}{\bar{\omega}\GF}
\newcommand{\SpeedGF}{\Speed\GF}
\newcommand{\PriceGF}{\Price\GF}
\newcommand{\CostGF}{\Cost\GF}
\newcommand{\PpGF}{\Pp\GF}
\newcommand{\OLCostGF}{\bar{\Cost}\GF}
\newcommand{\cGFprime}{c\GFprime}
\begin{definition} \label{def:gradient_flow_evolution_rule}
    A \emph{transition rule of the gradient flow} is a transition rule $\ruleGF_t\colon \Xx\to \Xx$ for which there
    exists, for each $x \in \Xx$, a curve  $\phi \in AC([0, \infty) , \Xx)$ and a sequence $(s_k)_{k\geq 1}$ with $s_k\nearrow+\infty$ as $k\to\infty$ such that
    $\phi(0) = x$, $\lim_{k \to \infty} d\left( \phi(s_k), \ruleGF_t(x) \right) = 0$, and, for all $s \in [0, \infty)$,
    \begin{equation*}
        E_t(x) - E_t(\phi(s)) = \frac12 \int_0^s  |\partial E_t|^{2}\big(\phi(\sigma ) \big)  + |\dot{\phi}( \sigma  )|^2 \diff  \sigma.
    \end{equation*}
    The \emph{action of the gradient flow} is the action $\cGF_t$ given by
    \begin{equation}\label{eq:def_gradient_flow_action}
        \cGF_t(x_1,x_2):= \inf\left\{
        \frac{1}{2}\int_a^b \left(  |\partial E_t|^{2} \big(\phi(s)\big) 
        + |\dot \phi (s)|^2\right) \diff s \;\middle|\;
        \substack{a < b \in \R \\ \phi \in AC([a,b],\Xx) \\ \phi(a) = x_1, \phi(b) = x_2}
        \right\}.
    \end{equation}
\end{definition}
\begin{proposition} \label{lemma:gradient_flow_summary_lemma}
    Let us assume \cref{ass:unif_coerc,ass:metric_space,ass:reg_E,ass:path+Lipsch,ass:conn_comp,ass:path+Lipsch}. A transition rule $\ruleGF_t$ of the gradient flow is
    compatible---as defined in \cref{def:action}---with the action $\cGF_t$ of the gradient flow.
    Furthermore, the action $\cGF_t$ is generated by curves as per \cref{def:generated_by_curves},
    where $\Ii = \R$ and where we use the following definitions:
    \begin{align}
        \PpGF                     & \coloneqq \Xx \times \R^+ \text{, where } d_{\PpGF}\big((x_1, v_1), (x_2, v_2)\big) = d(x_1, x_2) + |v_1 - v_2|           \label{eq:def_phase_space_gf} \\
        i\GF (x)                       & \coloneqq (x, 0)                                                                                                \label{eq:embedding_gf}       \\
        \Gamma(p_1, p_2)          & \coloneqq \left\{ \gamma \colon [a, b] \rightarrow \PpGF \,\middle|\, \substack{a < b \in \R, \gamma(a) = p_1,\, \gamma(b) = p_2,                              \\ \gamma_x \in AC([a, b]; \Xx),\, |\dot{\gamma}_x| \equiv  \gamma_v \text{a.e.}}\right\} \label{eq:gamma_gradient_flow}\\
        \CostGF_t\big((x, v)\big) & \coloneqq  \frac{1}{2}  |\partial E_t|^{2}  (x)  + \frac{1}{2} v^2 \label{eq:def_cost_gf}\\
         \Cc^{F}_{t} (p_{1}, p_{2}) & \coloneqq \inf_{\gamma \in \Gamma (p_{1}, p_{2})} \int_{a}^{b} \CostGF_{t} (\gamma(s)) \diff s \,. \label{eq:action-lift-GF}
    \end{align}
    Here, for every interval $I \subseteq \R$, we denote the components of a curve $\gamma\colon I \to \PpGF$ by $\gamma_x\colon I \to \Xx$ and $\gamma_v\colon I \to \R^+$.
\end{proposition}
\subsubsection{The minimizing movement scheme}
\newcommand{\MMS}{^{^{_M}}}
\newcommand{\superscriptleft}[2]{%
    \mathllap{\raisebox{0.35ex}{$^{#1}$}\!\!}#2%
}
\newcommand{\raisedTau}[1]{\superscriptleft{\tau}{#1}}
\newcommand{\ruleM}{\superscriptleft{\tau}{\bar{\omega}\MMS}}
\newcommand{\SpeedM}{\Speed\MMS}
\newcommand{\PriceM}[1][\tau]{\superscriptleft{#1}{\Price\MMS}}
\newcommand{\CostM}[1][\tau]{\superscriptleft{#1}{\Cost}\MMS}
\newcommand{\PpM}{\Pp\MMS}
\newcommand{\OLCostM}[1][\tau]{\superscriptleft{#1}{\bar{\Cost}}\MMS}
\newcommand{\cM}[1][\tau]{\superscriptleft{#1}{c}\MMS}
\newcommand{\cMg}[1][\tau]{\superscriptleft{#1}{\mathfrak{c}}\MMS}
\newcommand{\EM}{\raisedTau{E}\MMS}
\newcommand{\ttau}{_{t,\tau}}
\newcommand{\vx}{\underline{x}}
\begin{definition}\label{def:evolution_rule_MMS}
    For $\tau > 0$, $x \in \Xx$ and $t \in [0, T]$, a \emph{minimizing movement scheme sequence starting at point $x$ at time $t$}
    is a sequence $(u_s)_{s \in \NN}$ in $\Xx$
    such that $u_0 = x$, and,
    for all $s \in \NN$,
    \begin{equation*}
        u_{s+1} \in \argmin_{y \in \Xx} \left\{  E_t(y) + \frac{1}{2\tau} d(y, u_s)^2 \right\}.
    \end{equation*}
    A \emph{transition rule of the minimizing movement scheme} is a transition rule $\ruleM_t \colon \Xx\to \Xx$
    for which there exists, for each $x \in \Xx$ and $t \in [0, T]$, a minimizing movement scheme sequence $(u_s)_{s \in \NN}$ in $\Xx$ starting at point $x$ at time $t$
    such that $\ruleM_t(x)$ is a cluster point of $(u_s)_{s \in \NN}$.
    The \emph{action of the minimizing movement scheme} is the function  $\cM_t \colon \Xx \times \Xx \to [0, \infty)$ given by
    \begin{align}\label{eq:action_infimum_MMS}
        \cM_t(x_1,x_2):= \inf\left\{
        \sum_{s=a}^b E_t(u_s) - E\ttau\MMS(u_s) + \frac{1}{2\tau} d(u_{s+1}, u_s)^2
        \;\middle|\;
        \substack{a \leq b \in \Z, \\ (u_s)_{s \in [a, b]_\Z}, \\ u_a = x_1, u_b = x_2}
        \right\},
    \end{align}
    where we set $u_{b+1} = u_b = x_{2}$ and
    \begin{equation}\label{eq:def_E_MMS}
        E\ttau\MMS(x) := \inf_{y \in \Xx} \left\{ E_t(y) + \frac{1}{2\tau} d(x, y)^2 \right\}.
    \end{equation}
\end{definition}

We mention that in \cite[Definition~5.14]{Scilla_2018} the authors introduced an action for the minimizing movement scheme in Euclidean setting which is fully compatible with \cref{eq:action_infimum_MMS,eq:def_E_MMS}.

\begin{proposition} \label{lemma:MMS_summary_lemma}
    Let us assume \cref{ass:metric_space,ass:reg_E,ass:unif_coerc,ass:der_time,ass:conn_comp,ass:path+Lipsch}. For $\tau > 0$, a transition rule $\ruleM_t$ of the minimizing movement scheme is compatible---as defined in \cref{def:action}---with the action $\cM_t$ of the minimizing movement scheme.\\    
     Moreover, if $\tau \leq \frac{1}{L}$,
    the  map $\cM_t\colon \Xx \times \Xx \to [0, \infty)$ is an action generated by curves as per \cref{def:generated_by_curves},
    where $ \mathbb{I} = \Z$ and where we use the following definitions:
    \begin{align}
        \PpM              & \coloneqq \Xx \times \Xx \text{, where } d_{\PpM}(\vx, \vx') = \frac{1}{2} \left(d(x_0, x'_0) + d(x_1, x'_1)\right) \label{eq:def_phase_space_mms} \\
         i\MMS (x) & \coloneqq  (x, x)                                                                                      \label{def:embedding_MMS}        \\
        \Gamma(\vx, \vx') & \coloneqq \left\{ \gamma\colon  [a, b]_\Z \to \PpM \,\middle|\, \substack{a < b \in \Z,\, \gamma(a) = \vx, \gamma(b) = \vx',                                    \\\gamma_1(s) = \gamma_0(s + 1) \text{ for } s \in [a, b-1]_\Z}\right\} \label{eq:def_GammaM}\\
        \CostM_t(\vx)     & \coloneqq E_t(x_0) - E_{t, \tau}\MMS(x_0) + \frac{1}{2\tau} d(x_0, x_1)^2,\label{eq:CostM_def}\\
         \cMg_{t} (\underline{x}, \underline{x}') & \coloneqq \inf_{\gamma \in \Gamma (\underline{x}, \underline{x}')} \, \sum_{s=a+1}^{b} \CostM_{t} (\gamma(s)), \label{eq:extended-cost-MMS}
    \end{align}
    where $E_{t, \tau}\MMS$ is defined as in \cref{eq:def_E_MMS}. Here, for every $I\subseteq \Z$ we denote the components of a curve $\gamma\colon I  \to \PpM$ by $\gamma_0$ and $\gamma_1$, and we denote the components of points $\vx, \vx' \in \PpM = \Xx \times \Xx$ by $(x_0, x_1) \coloneqq \vx$ and $(x'_0, x'_1) \coloneqq \vx'$.
\end{proposition}
\subsubsection{The BDF2 method for the gradient flow}
\newcommand{\BDF}{^{^{_B}}}
\newcommand{\ruleB}{\superscriptleft{\tau}{\bar{\omega}\BDF}}
\newcommand{\SpeedB}{\Speed\BDF}
\newcommand{\PriceB}{\raisedTau{\Price\BDF}}
\newcommand{\CostB}{\raisedTau{\Cost}\BDF}
\newcommand{\PpB}{\Pp\BDF}
\newcommand{\OLCostB}{\raisedTau{\bar{\Cost}}\BDF}
\newcommand{\cB}{\raisedTau{c}\BDF}
\newcommand{\cBg}{\raisedTau{\mathfrak{c}}\BDF}
\newcommand{\EB}{\raisedTau{E}\BDF}
\begin{definition}\label{def:evolution_rule_BDF2}
    For $\tau > 0$, $x \in \Xx$ and $t \in [0, T]$, a \emph{BDF2 discretization sequence starting at point $x$ at time $t$} is a sequence $(u_s)_{s \in \NN}$ in $\Xx$
    such that $u_0 = x$ and,
    for all $s \in \NN$,
    \begin{equation*}
        u_{s+1} \in \argmin_{y \in \Xx} \left\{  E_t(y) + \frac{1}{\tau} d(y, u_s)^2 - \frac{1}{4\tau} d(y, u_{s-1})^2\right\},
    \end{equation*}
    where we set $u_{-1} = x$.  A \emph{transition rule of the BDF2 discretization} is a transition rule $\ruleB_t \colon \Xx\to \Xx$ for which there exists, for each $x \in \Xx$ and $t \in [0, T]$, a BDF2 discretization sequence $(u_s)_{s \in \NN}$ in $\Xx$ starting at point $x$ at time $t$
    such that $\ruleB_t(x)$ is a cluster point of $(u_s)_{s \in \NN}$.
    The \emph{action of the BDF2 discretization} is the map $\cB_t \colon \Xx \times \Xx \to [0, \infty)$ given by
    \begin{equation}\label{eq:action_infimum_BDF2}
    \begin{split}
        \cB_t(x_1,x_2)\coloneqq 
        \inf\left\{
        \sum_{s=a}^{b+1} \right.
        \bigg( &
        E_t(u_s) - E\BDF_{t, \tau}(u_s, u_{s-1}) + \frac{1}{2\tau} d(u_{s+1}, u_s)^2  \\
        & + \frac{1}{2\tau} d(u_{s}, u_{s-1})^2 - \frac{1}{4\tau} d(u_{s+1}, u_{s-1})^2 \bigg)
        %\mathlarger{\sum_{s=a}^{b+1}} \left(  \begin{array}{c}
        %        E_t(u_s) - E\BDF_{t, \tau}(u_s, u_{s-1}) + \frac{1}{2\tau} d(u_{s+1}, u_s)^2 \vspace{0.2em} \\
         %       + \frac{1}{2\tau} d(u_{s}, u_{s-1})^2 - \frac{1}{4\tau} d(u_{s+1}, u_{s-1})^2
         %   \end{array}
        %\right)
        \left. \;\middle|\;
        \substack{a \leq b \in \Z, \\ (u_s)_{s \in [a, b]_\Z}, \\ u_a = x_1, u_b = x_2}
        \right\},
        \end{split}
    \end{equation}
    where where we set $u_{a-1} = x_1$, $u_{b+1} = u_{b+2} = x_2$ and
    \begin{equation}\label{eq:def_E_BDF}
        E\BDF_{t, \tau}(x, x') := \inf_{y \in \Xx} \left\{ E_t(y) + \frac{1}{\tau} d(y, x)^2 - \frac{1}{4\tau} d(y, x')^2 \right\}.
    \end{equation}
\end{definition}

To the best of our knowledge, the action for the BDF2 scheme provided by \cref{eq:action_infimum_BDF2,eq:def_E_BDF} is completely original.

\begin{proposition} \label{lemma:BDF2_summary_lemma}
    Let us sassume \cref{ass:metric_space,ass:reg_E,ass:unif_coerc,ass:der_time,ass:conn_comp,ass:path+Lipsch}. For $\tau > 0$, a transition rule $\ruleB_t$ of the BDF2 discretization is compatible---as defined in \cref{def:action}---with the action $\cB_t$ of the BDF2 discretization.\\    
    Moreover, for every $\tau \leq \frac{1}{L}$,
    the map $\cB_t \colon \Xx \times \Xx \to [0, \infty)$ is an action generated by curves as per \cref{def:generated_by_curves},
    where $ \mathbb{I} = \Z$ and where we use the following definitions:
    \begin{align}
         \PpB              & \coloneqq \Xx \times \Xx \times \Xx \text{, where } d_{\PpB}(\vx, \vx') = \frac{1}{3} \sum_{i=-1}^{1} d(x_i, x'_i)                                              \label{eq:def_phase_space_BDF} \\
         i^{B} (x)             & \coloneqq  (x, x, x)                                                                                                                          \label{eq:embedding_BDF}              \\
        \Gamma(\vx, \vx') & := \left\{ \gamma \colon [a, b]_\Z \to  \PpB  \,\middle|\, \substack{a < b \in \Z,\, \gamma(a) = \vx, \gamma(b) = \vx',                                                                                \\\gamma_1(s-1) = \gamma_0(s) = \gamma_{-1}(s+1) \text{ for } s \in [a+1, b-1]_\Z}\right\} \label{eq:def_GammaB} \\
        \CostB_t(\vx)     & := E_t(x_0) - E\BDF_{t, \tau}(x_0, x_{-1}) + \frac{1}{2\tau} \left(d(x_0, x_1)^2 + d(x_{-1}, x_0)^2\right) - \frac{1}{4\tau}d(x_{-1}, x_{1})^2,\label{eq:def_costB}\\
        \cBg_{t} ( \vx, \vx') & \coloneqq \inf_{\gamma \in \Gamma (\underline{x}, \underline{x}')} \, \sum_{s = a+1}^{b} \CostB_{t} (\gamma(s)), \label{eq:extendded-cost-BDF} 
    \end{align}
    where $E\BDF_{t, \tau}$ is defined as in \cref{eq:def_E_BDF}. Here, for every $I\subseteq \Z$, we denote the components of a curve $\gamma\colon I \to \PpB$ by $\gamma_{-1}$, $\gamma_0$ and $\gamma_1$, and we denote the components of points $\vx, \vx' \in \PpB = \Xx \times \Xx \times \Xx$ by $(x_{-1}, x_0, x_1) \coloneqq \vx$ and $(x'_{-1}, x'_0, x'_1) \coloneqq \vx'$.
\end{proposition}
\subsection{A rigorous proof of \texorpdfstring{\cref{ax:action_triangular_time_stable}}{Axiom \ref{ax:action_triangular_time_stable}}}
With those examples in mind, we now show that actions generated by curves fulfill \cref{ax:action_triangular_time_stable}.
We postpone the proof of the following ancillary lemma to the end of this section.
\begin{lemma}\label{lemma:triangular_inequ_on_P}
    Let $c_t \colon \Xx \times \Xx \to [0, \infty)$ be an action generated by curves as per \cref{def:generated_by_curves} and let $\Cc_{t} \colon \Pp \times \Pp \to [0, \infty)$ be the map defined in \eqref{eq:action_infimum}.
    Then, $\Cc_t$ and $c_{t}$ fulfill the triangular inequality,
    i.e., for every $p_1, p_2, p_3 \in \Pp$, every $x_{1}, x_{2}, x_{3} \in \Xx$, and every $t \in [0, T]$ we have
    \begin{equation*}
        \Cc_t(p_1, p_3) \leq \Cc_t(p_1, p_2) + \Cc_t(p_2, p_3) \qquad \text{and} \qquad c_{t} (x_{1}, x_{3}) \leq c_{t} (x_{1}, x_{2}) + c_{t} (x_{2}, x_{3})\,.
    \end{equation*}
\end{lemma}
We are now ready to prove the key lemma of this section.
\begin{lemma}\label{lemma:good_curves_fulfill_continuous_triangular_inequality}
    Let us assume \cref{ass:metric_space,ass:reg_E,ass:der_time,ass:unif_coerc,ass:conn_comp}. If a transition rule $\bar{\omega}_{t}$ is compatible with an action $c_{t}$ generated by curves, then \cref{ax:action_triangular_time_stable} holds.
\end{lemma}
\begin{proof}
    We follow the idea outlined on pages~\pageref{part:start_of_informal_proof}--\pageref{part:end_of_informal_proof}
    and illustrated in \cref{fig:proof_shortcut_candidate_curve}.
    In the first part of the proof, we obtain a $\Delta>0$ as demanded by \cref{ax:action_triangular_time_stable}.
    In the second part, we confirm that with such a choice of $\Delta>0$ and for any $x_1, \dots, x_n$,
    $t_1, \dots, t_n$ as in \cref{ax:action_triangular_time_stable}, \cref{eq:triangular_inequality} is indeed fulfilled. \\
    Let $\varepsilon, C >0$, $t \in [0, T]$ and $K \subseteq \Xx$ compact be given as in \cref{ax:action_triangular_time_stable}.
    We first notice that $i(K)$ is compact, as $i$ is continuous.  Hence, we may find a compact set $K' \subseteq \Pp$ related to $i(K)$ as prescribed by \cref{prop:curves_coercive}. 
    By \cref{prop:cost_nonzero} and \cref{ass:conn_comp}, since $i$ is a closed immersion, the connected components of $\{ p \in K' \mid \Cost_t(p) = 0\}$ are well-separated,
    and hence there are only finitely many of them.
    We enumerate those connected components as $\Crit_1, \dots, \Crit_m$ and use
    \cref{prop:cheap_fuel_cheap_action} to choose $L, \Pcheap > 0$ such that for
    all $p_1, p_2 \in K'$ with $\Cost_t(p_1) \leq \Pcheap$, $\Cost_t(p_2) \leq \Pcheap$ and $ d_{\Pp}  (p_1, p_2) \leq L$, we have that
    \begin{equation}
         \Cc_t ( p_{1}, p_{2}) \leq \frac{\varepsilon}{6(m+1)}. \label{eq:cheap_fuel_cheap_action}
    \end{equation}
    For $r > 0$, we write $\underline{\Crit}_r := \bigcup_{j=1}^m B_r(\Crit_j)$,  where $B_{r} (\Crit_{j}) \coloneqq \{ p \in \Pp \mid d_{\Pp} (p, \Crit_{j}) <r \}$.
    By the continuity of $\Cost$ and the compactness of $K'$,
    $\sup_{p \in \overline{(\underline{\Crit}_r)}} \Cost_t(p) \rightarrow 0$ as $r \rightarrow 0$.
    Thus, we can choose $0 < r < L$ such that $\sup_{p \in \overline{(\underline{\Crit}_r)}} \Cost_t(p) \leq \Pcheap$. Moreover, by further reducing $r$ if needed, we can assume that $\overline{B_r(\Crit_j)}\cap \overline{B_r(\Crit_{j'})} = \emptyset$ whenever $j\neq j'$.
    Using a similar argument, we see that
    \begin{equation*}
        \inf_{p \in K' \setminus \underline{\Crit}_r} \Cost_t(p) > 0.
    \end{equation*}
    Even more, we can choose some $\Delta''$ such that
    \begin{equation}\label{eq:P_exp}
        \Delta_{\Cost} \coloneqq \inf_{\substack{ p  \in K' \setminus \underline{\Crit}_r \\ t' \in [t - \Delta'', t + \Delta'']}} \Cost_{t'}( p ) > 0.
    \end{equation}
    Using continuity one last time, we can choose some $\Delta'>0$ such that for all $p \in K'$ and $t' \in [t - \Delta', t + \Delta']$,
    we have that
    \begin{equation}\label{eq:delta_prime}
        |\Cost_{t'}(p) - \Cost_t(p)| \leq \varepsilon_{\Cost} :=  \frac{\varepsilon}{3} \cdot \left(\frac{C + \frac{\varepsilon}{3}}{\Delta_{\Cost}} + 2(m+1)\right)^{-1}.
    \end{equation}
    We claim that $\Delta \coloneqq \min \{ \Delta', \Delta'' \}$ is the $\Delta>0$ desired by \cref{ax:action_triangular_time_stable}.\\
    To prove this, we fix points $x_1, \dots, x_n \in K$ and instants $t_1, \dots, t_n \in [t -  \Delta  , t +  \Delta  ]$
    such that $\sum_{i=1}^{n-1} c_{t_i}(x_i, x_{i+1}) \leq C$.
    We first choose $\gamma_i \in \Gamma \big( i(x_i), i(x_{i+1}) \big)$ according to \cref{prop:curves_coercive}
    such that $\im(\gamma_i) \subseteq K'$  and
    \begin{equation} \label{eq:choice_of_curve}
        \int_{(a_i, b_i]_\Ii} \Cost_{t_i}(\gamma_i(s)) \diff \nu(s) \leq c_{t_i}(x_i, x_{i+1}) + \frac{\varepsilon}{3n},
    \end{equation}
    where $a_i < b_i \in  \mathbb{I} $  are such that $\dom(\gamma_i) = [a_i, b_i]_{ \mathbb{I}}$.
    We set $IS := \{(i, s) \mid i \in \{1, \dots, n\}, s \in [a_i, b_i]_\Ii\}$ and
    \begin{align*}
        IS_{\mathrm{cheap}} := \left\{(i, s) \in IS \;\middle|\;\gamma_i(s) \in \overline{(\underline{\Crit}_r)} \right\}.
    \end{align*}
    Note that for all $i$, $\{s \in \mathbb{I} \mid (i, s) \in IS_{\mathrm{cheap}}\}$ is closed
    and that for all $(i, s) \in IS \backslash IS_{c}$, we have by \cref{eq:P_exp} that
    \begin{equation}\label{eq:cost_is_high_in_non_cheap}
        \Cost_{t_i}(\gamma_i(s)) \geq \Delta_{\Cost}.
    \end{equation}
    For the ease of notation, we use the lexicographic order on the pairs $(i, s) \in IS$,
    where
    $(i, s) < (j, s')$ if $i < j$ or if $i = j$ and $s < s'$.
    For $(i, s) \in IS_{\mathrm{cheap}}$, we also set $J(i, s)$ to be the unique index $j\in \{1, \ldots, m \}$ such that $\gamma_i(s) \in B_r(\Crit_j)$.\\
    As a next step, we inductively define breakpoints, which we will eventually use to get an upper bound
    on $c_t(x_1, x_2)$ by repeatedly using the triangular inequality.
    We start by setting
    \begin{equation} \label{eq:breakpoint_initial}
        (i_{\mathrm{out}}^0, s_{\mathrm{out}}^0) := \begin{cases}
            \max\{(i, s) \in IS_{\mathrm{cheap}} \mid J(i, s) = J(1, a_1)\} & \text{if } (1, a_1) \in IS_{\mathrm{cheap}}, \\
            (1, a_1)                                               & \text{otherwise},
        \end{cases}
    \end{equation}
    and inductively set, for each $k$
    \begin{align*}
        (i_{\mathrm{in}}^{k+1}, s_{\mathrm{in}}^{k+1})   & \coloneqq \min\{(i, s) \in IS_{\mathrm{cheap}} \mid (i, s) > (i_{\mathrm{out}}^{k}, s_{\mathrm{out}}^{k})\}, \\
        (i_{\mathrm{out}}^{k+1}, s_{\mathrm{out}}^{k+1}) & := \max\{(i, s) \in IS_{\mathrm{cheap}} \mid J(i, s) = J(i_{\mathrm{in}}^k, s_{\mathrm{in}}^k)\}.
    \end{align*}
    We terminate this scheme at step $d$ if there is no possible choice for $(i_{\mathrm{in}}^{d+1}, s_{\mathrm{in}}^{d+1})$.
    Formally, we set $(i_{\mathrm{in}}^{d+1}, s_{\mathrm{in}}^{d+1}) = (n, b_n)$ and $(i_{\mathrm{in}}^0, s_{\mathrm{in}}^0) = (1, a_1)$.
    The resulting breakpoints have the following properties:
    \begin{enumerate}
        \item $d \leq m$ (where $m$ is the number of components $\Crit_1,\ldots,\Crit_m$).
        \item $(i_{\mathrm{out}}^k, s_{\mathrm{out}}^k) \in IS_{\mathrm{cheap}}$ and $(i_{\mathrm{in}}^{k}, s_{\mathrm{in}}^{k}) \in IS_{\mathrm{cheap}}$
              for all $1 \leq k \leq d$.
        \item $J(i_{\mathrm{in}}^k, s_{\mathrm{in}}^k) = J(i_{\mathrm{out}}^k, s_{\mathrm{out}}^k)$ for all $1 \leq k \leq d$.
        \item For all $(i_{\mathrm{out}}^k, s_{\mathrm{out}}^k) < (i, s) < (i_{\mathrm{in}}^{k+1}, s_{\mathrm{in}}^{k+1})$, we have that
              $(i, s) \notin IS_{\mathrm{cheap}}$.\label{item:between_breakpoints_not_cheap}
    \end{enumerate}
    We set, for $0 \leq k \leq d+1$, $p_{\mathrm{in}}^k := \gamma_{i_{\mathrm{in}}^k}(s_{\mathrm{in}}^k)$ and $p_{\mathrm{out}}^k := \gamma_{i_{\mathrm{out}}^k}(s_{\mathrm{out}}^k)$.
    In the rest of this proof, we first estimate $ \Cc_t  (p_{\mathrm{out}}^k, p_{\mathrm{in}}^{k+1})$, then $ \Cc_t  (p_{\mathrm{in}}^k, p_{\mathrm{out}}^k)$,
    and then we combine those estimates using the triangular inequality to get an upper bound on $c_t(x_1, x_n)$.\\
    \textbf{Estimating $ \Cc_t  (p_{\mathrm{out}}^k, p_{\mathrm{in}}^{k+1})$:}
    We set, for $1 \leq i \leq n-1$ and $0 \leq k \leq d$,
    \begin{align*}
        S_{\mathrm{exp}}^{i,k}            & := \{s \in (a_i, b_i]_\Ii \mid (i_{\mathrm{out}}^k, s_{\mathrm{out}}^k) < (i, s) < (i_{\mathrm{in}}^{k+1}, s_{\mathrm{in}}^{k+1})\}        \\
        \bar{S}_{\mathrm{exp}}^{i,k} & := \{s \in (a_i, b_i]_\Ii \mid (i_{\mathrm{out}}^k, s_{\mathrm{out}}^k) \leq (i, s) \leq (i_{\mathrm{in}}^{k+1}, s_{\mathrm{in}}^{k+1})\},
    \end{align*}
    where some of the $S_{\mathrm{exp}}^{i,k}$ and $\bar{S}_{\mathrm{exp}}^{i,k}$ might be empty.
    By item~\ref{item:between_breakpoints_not_cheap} above and \cref{eq:cost_is_high_in_non_cheap},
    we see that for all $1 \leq i \leq n-1$,  $0 \leq k \leq d$ and $s \in S_{\mathrm{exp}}^{i,k}$, we have that
    $\Cost_{t_i}(\gamma_i(s)) \geq \Delta_{\Cost}$. Thus, we have
    \begin{align*}
        C + \frac{\varepsilon}{3}
         & \geq \sum_{i=0}^{n-1} \int_{(a_i, b_i]_\Ii} \Cost_{t_i}(\gamma_i(s)) \diff \nu(s)
        \geq \sum_{k=0}^{d} \sum_{i=i_{\mathrm{out}}^k}^{ i_{\mathrm{in}}^{k+1}} \int_{S_{\mathrm{exp}}^{i, k}} \Cost_{t_i}(\gamma_i(s)) \diff \nu(s) \\
         & \geq \sum_{k=0}^{d} \sum_{i=i_{\mathrm{out}}^k}^{ i_{\mathrm{in}}^{k+1}} \int_{S_{\mathrm{exp}}^{i, k}} \Delta_{\Cost} \diff \nu(s)
        = \Delta_{\Cost} \cdot \sum_{k=0}^{d} \sum_{i=i_{\mathrm{out}}^k}^{ i_{\mathrm{in}}^{k+1}} \nu(S_{\mathrm{exp}}^{i, k}).
    \end{align*}
    From the chain of inequalities above and the fact that for a fixed $0 \leq k \leq d$, we have that $\sum_{i=i_{\mathrm{out}}^k}^{i_{\mathrm{in}}^{k+1}} \nu(\overline{S}_{\mathrm{exp}}^{i,k}) - \nu(S_{\mathrm{exp}}^{i,k}) \leq 2$,we get
    \begin{equation} \label{eq:cost_estimate}
        \begin{split}
            \varepsilon_{\Cost} \cdot \left(\sum_{k=0}^{d} \sum_{i=i_{\mathrm{out}}^k}^{i_{\mathrm{in}}^{k+1}} \nu(\overline{S}_{\mathrm{exp}}^{i, k})\right)
             & \leq \varepsilon_{\Cost} \cdot \left(\sum_{k=0}^{d} \left( \sum_{i=i_{\mathrm{out}}^k}^{i_{\mathrm{in}}^{k+1}} \nu(S_{\mathrm{exp}}^{i, k}) + 2\right)\right) \\
             & \leq \varepsilon_{\Cost} \cdot \left(\frac{C + \frac{\varepsilon}{3}}{\Delta_{\Cost}} + 2(m+1)\right) = \frac{\varepsilon}{3}.
        \end{split}\end{equation}
    With this estimate, we have that
    \begin{align*}
             & \sum_{k=0}^{d} \Cc_t (p_{\mathrm{out}}^k, p_{\mathrm{in}}^{k+1})
        \leq \sum_{k=0}^{d}\left( \sum_{i=i_{\mathrm{out}}^k}^{i_{\mathrm{in}}^{k+1}} \int_{\overline{S}_{\mathrm{exp}}^{i, k}} \Cost_{t}(\gamma_i(s)) \diff \nu(s)\right)                                                                                                                                                                                 \\
        \leq & \sum_{i=1}^{n-1} \underbrace{\int_{(a_i, b_i]_\Ii} \Cost_{t_i}(\gamma_i(s)) \diff \nu(s)}_{\leq \frac{\varepsilon}{3n} +  c_{t_{i}}  (x_i, x_{i+1}) \text{ by~\eqref{eq:choice_of_curve}}}
        + \underbrace{\sum_{k=0}^{d}\left(\sum_{i=i_{\mathrm{out}}^k}^{i_{\mathrm{in}}^{k+1}} \int_{\overline{S}_{\mathrm{exp}}^{i, k}} \underbrace{|\Cost_{t_i}(\gamma_i(s)) - \Cost_{t}(\gamma_i(s))|}_{\leq \varepsilon_{\Cost} \text{ by~\eqref{eq:delta_prime}}}\diff\nu(s)\right)}_{\leq \frac{\varepsilon}{3} \text{ by~\eqref{eq:cost_estimate}}} \\
         \leq   & \frac{\varepsilon}{3} + \sum_{i=1}^{n-1} c_{t_i}(x_i, x_{i+1}) + \frac{\varepsilon}{3} =\sum_{i=1}^{n-1}  c_{t_{i}} (x_i, x_{i+1}) + \frac{2\varepsilon}{3}.
    \end{align*}
    \textbf{Estimating $ \Cc_t (p_{\mathrm{in}}^k, p_{\mathrm{out}}^{k})$:}
    We fix $0 \leq k \leq d$. If $k=0$,
    we only consider the case where  $p_{\mathrm{in}}^0 \neq p_{\mathrm{out}}^0$, and we are thus in the
    first case of \cref{eq:breakpoint_initial}, i.e., $i_{\mathrm{in}}^k, s_{\mathrm{in}}^k \in IS_{\mathrm{cheap}}$.
    If $p_{\mathrm{in}}^0 = p_{\mathrm{out}}^0$, we may simply ignore this term in the triangular inequality at the end.
    We set $j := J(i_{\mathrm{in}}^k, s_{\mathrm{in}}^k) = J(i_{\mathrm{out}}^k, s_{\mathrm{out}}^k)$.
    We can choose $\overline{p}_{\mathrm{in}}^k, \overline{p}_{\mathrm{out}}^k \in \Crit_j$ such that
    \begin{equation*}
        d_{\Pp}  (\overline{p}_{\mathrm{in}}^k, p_{\mathrm{in}}^k) \leq r \leq L \quad \text{and} \quad  d_{\Pp} (\overline{p}_{\mathrm{out}}^k, p_{\mathrm{out}}^k) \leq r \leq L,
    \end{equation*}
    so that we can use \cref{eq:cheap_fuel_cheap_action} to see that
    \begin{equation*}
        \Cc_t (\overline{p}_{\mathrm{in}}^k, p_{\mathrm{in}}^k) \leq  \frac{\varepsilon}{6(m+1)} \quad \text{and} \quad  \Cc_t (\overline{p}_{\mathrm{out}}^k, p_{\mathrm{out}}^k) \leq  \frac{\varepsilon}{6(m+1)}.
    \end{equation*}
    Using the triangular inequality and \cref{prop:no_cost_in_within_conn_component}, we have that
    \begin{equation*}
        \Cc_t (p_{\mathrm{in}}^k, p_{\mathrm{out}}^k) \leq \Cc_t (p_{\mathrm{in}}^k, \overline{p}_{\mathrm{in}}^k) +  \Cc_t  (\overline{p}_{\mathrm{in}}^k, \overline{p}_{\mathrm{out}}^k) +  \Cc_t  (\overline{p}_{\mathrm{out}}^k, p_{\mathrm{out}}^k) \leq \frac{\varepsilon}{3(m+1)}.
    \end{equation*}
    \textbf{Conclusion:}
    Since $(i_{\mathrm{in}}^{d+1}, s_{\mathrm{in}}^{d+1}) = (n, b_n)$ and $(i_{\mathrm{in}}^0, s_{\mathrm{in}}^0) = (1, a_1)$, we have that
    \begin{align*}
        c_t(x_1, x_n) & \leq \sum_{k=0}^{d}  \Cc_t (p_{\mathrm{in}}^k, p_{\mathrm{out}}^{k}) + \sum_{k=0}^{d}  \Cc_t (p_{\mathrm{out}}^k, p_{\mathrm{in}}^{k+1})                                                            \\
                      & \leq (m+1) \frac{\varepsilon}{3(m+1)} + \sum_{i=1}^{n-1}  c_{t_{i}}  (x_i, x_{i+1}) + \frac{2\varepsilon}{3} = \sum_{i=1}^{n-1}  c_{t_{i}}  (x_i, x_{i+1}) + \varepsilon.
    \end{align*}
    The fact that for $x, x' \in \Crit \coloneqq \{y \in \Xx \mid |\partial_t E_t|(y) = 0\}$,  $c_t(x, x') = 0$ if and only if $x$ and $x'$ belong to the same path-connected components of $\Crit$
    follows from \cref{prop:no_cost_in_within_conn_component} together with \cref{prop:cost_nonzero}.
\end{proof}
To end this section, we proof the ancillary lemma \cref{lemma:triangular_inequ_on_P}.
\begin{proof}[Proof of \cref{lemma:triangular_inequ_on_P}]
    Let $c_t$ be an action generated by curves as per \cref{def:generated_by_curves}.
    We fix $p_1, p_2, p_3 \in \Pp$ and $\varepsilon > 0$.
    We choose $\gamma^{(i)} \in \Gamma(p_i, p_{i+1})$ for $i \in \{1, 2\}$ such that
    \begin{equation}\label{eq:gamma_i_choice}
        \Cc_t (p_i, p_{i+1}) + \frac{\varepsilon}{2} \geq \int_{(a_i, b_i]_\Ii} \Cost_t\big(\gamma^{(i)}(s)\big) \diff \nu(s),
    \end{equation}
    where $a_i < b_i \in  \mathbb{I}$ are  such that $\dom(\gamma^{(i)}) = [a_i, b_i]_\Ii$.  
    In particular, $\gamma^{(i)}(a_i) = x_i$, $\gamma^{(i)}(b_i) = x_{i+1}$ and $\gamma^{(1)}(b_1) = \gamma^{(2)}(a_2)$.
    We set $\underline{\gamma}^{(2)}$ to be the curve $\gamma^{(2)}$ reparametrized to $[b_1, b_2 + b_1 - a_2]_\Ii$, i.e,
    $\underline{\gamma}^{(2)}(s) = \gamma^{(2)}(s + b_1 - a_2)$. By \cref{prop:curve_restriction},
    $\underline{\gamma}^{(2)} \in \Gamma(p_2, p_3)$ and likewise,
    the  concatenation $\gamma^{(1)} \cup \underline{\gamma}^{(2)}$ as defined in \cref{prop:curve_restriction} is in $\Gamma(p_1, p_3)$.
    We have that
    \begin{align*}
        \Cc_t (p_1, p_3) & \leq \int_{(a_1, b_2 + b_1 - a_2]_\Ii} \Cost_t\big(\gamma^{(1)} \cup \underline{\gamma}^{(2)}(s)\big) \diff \nu(s)                          \\
                      & \leq \int_{(a_1, b_1]_\Ii} \Cost_t\big(\gamma^{(1)}(s)\big) \diff \nu(s) + \int_{(a_2, b_2]_\Ii} \Cost_t\big(\gamma^{(2)}(s)\big) \diff \nu(s) \\
                      & \leq  \Cc_t  (p_1, p_2) +  \Cc_t (p_2, p_3) + \varepsilon.
    \end{align*}
    Since $\varepsilon > 0$ was arbitrary, we have that $\Cc_t$ fulfills the triangular inequality. The triangle inequality for $c_{t}$ follows by definition of~$c_{t}$ in~\eqref{eq:action_infimum}.
\end{proof}
