\section{Structure of the measure in the energy balance}

In this part, we seek to establish that the non-negative measure $\bar \mu$ appearing in the energy balance in \cref{thm:main_result_complete} is purely atomic. 
Under suitable extra assumptions, this fact is expected, as it has already been observed for quasi\-static evolutions in finite-dimensional Hilbert spaces constructed with limiting arguments (see, e.g., \cite{AR17, Scilla_2018,minotti2018viscous}).
In this section, we adapt to our setting the arguments developed in \cite[Section~5.1]{Scilla_2018}. 


We observe that, by virtue of \cref{ass:t_der_quotient}, we can rewrite  the energy balance for the quasi\-static evolution $\hat \eta\colon [0,T]\to\X$ as follows:
\begin{equation} \label{eq:energy_balance_quotient}
            \hat E\big(\hat\eta^+(t)\big) - \hat E\big(\hat\eta^-(s)\big) = \int_s^t \partial_t \hat E \big(\hat\eta(\tau)\big) \diff \tau - \bar \mu([s, t]).
\end{equation}
Moreover, we introduce the non-increasing function $f\colon [0,T] \to \R$ as
\begin{equation} \label{eq:def_ancill_funct_mu}
    f(t) \coloneqq \hat E\big( \hat \eta(t) \big) - \int_0^t \partial_t \hat E \big(\hat\eta(\tau)\big) \diff \tau,
\end{equation}
and we use the notation $f_+(t) \coloneqq \lim_{s\to t^+} f(s)$. We observe right away that
\begin{equation*}
    f_+(t) = \lim_{s\to t^+} \left(\hat E\big(\hat \eta(s) \big) - \int_0^s \partial_t \hat E \big(\hat\eta(\tau)\big) \diff \tau \right) = \hat E(\hat \eta^+(t)\big) - \int_0^t \partial_t \hat E \big(\hat\eta(\tau)\big) \diff\tau.
\end{equation*}

\begin{proposition} \label{prop:dini_der}
    Let us assume \cref{ass:conn_comp,ass:der_time,ass:metric_space,ass:path+Lipsch,ass:PL+time_der_slope,ass:reg_E,ass:unif_coerc,ass:t_der_quotient}.
    Let  $f\colon [0,T] \to \R$ be defined as in \cref{eq:def_ancill_funct_mu}. Then, for every $t\in [0,T)$, we have that
    \begin{equation*}
        D_+ f_+(t) \coloneqq \liminf_{h\to 0^+} 
        \frac{f_+(t+h)-f_+(t)}{h} \geq 0,
    \end{equation*}
    i.e., the Dini lower right derivative of $f_+$ is non-negative.
\end{proposition}

\begin{proof}
    For every $s\in [0,T]$, let us take $x_{s}\in \Xx$ such that $(s,x_{s})\in \hat \eta^+(s)$.
    Then, we fix $t\in [0,T)$ and we observe that
    \begin{equation*}
        \begin{split}
            f_+(t+h)-f_+(t) &=
            \hat E\big(\eta^+(t+h)\big) - \hat E\big(\eta^+(t)\big)
            - \int_t^{t+h} \partial_t \hat E \big(\hat\eta(\tau)\big) \diff \tau \\
            &= E_{t+h}(x_{t+h}) - E_t(x_t) - \int_t^{t+h} \partial_t \hat E \big(\hat\eta(\tau)\big) \diff \tau \\
            & = E_{t}(x_{t+h}) - E_t(x_t)
            + \int_t^{t+h} \left( 
            \partial_t E_\tau(x_{t+h})
            - \partial_t \hat E \big(\hat\eta(\tau)\big) 
            \right) \diff \tau
        \end{split}
    \end{equation*}
    for every $h>0$.
    Moreover, the expression in the intergal can be rewritten as follows:
    \begin{equation} \label{eq:app_int_term_identity}
        \begin{split}
            \partial_t E_\tau(x_{t+h})
            - \partial_t \hat E \big(\hat\eta(\tau)\big) &=
            \partial_t \hat E\big( [(\tau,x_{t+h})] \big)
            - \partial_t \hat E \big(\hat\eta(\tau)\big) \\
            & = \left( \partial_t \hat E\big( [(\tau,x_{t+h})] \big)
            -   \partial_t \hat E\big( \hat \eta^+(t+h) \big) \right) \\
            &\qquad +
            \left( \partial_t \hat E\big( \hat \eta^+(t+h) \big) 
            - \partial_t \hat E\big( \hat \eta^+(t) \big) \right) \\ 
            &\qquad +
            \left( \partial_t \hat E\big( \hat \eta^+(t) \big) 
            - \partial_t \hat E \big(\hat\eta(\tau)\big) \right).
        \end{split}
    \end{equation}
    Since $[(\tau,x_{t+h})] \to_{\X} [(t+h,x_{t+h})] = \hat \eta(t+h)$ as $\tau\to t+h$, it follows that the time derivative $\partial_t \hat E\big( [(\tau,x_{t+h})] \big) \to \partial_t \hat E\big( \hat \eta^+(t+h) \big)$ as $\tau\to t+h$, owing to \cref{ass:t_der_quotient}.
    Moreover, recalling that $\tau\in [t,t+h]$, that $\hat \eta^+$ is right-continuous and that $\hat \eta^+(\tau)\to_\X \hat \eta^+(t)$ as $\tau\to t^+$, by virtue of \cref{eq:app_int_term_identity} and \cref{ass:t_der_quotient}, we conclude that
    \begin{equation*}
        \int_t^{t+h} \left( 
            \partial_t E_\tau(x_{t+h})
            - \partial_t \hat E \big(\hat\eta(\tau)\big) 
            \right) \diff \tau = o(h),
    \end{equation*}
    yielding the identity
    \begin{equation} \label{eq:app_liminf_equiv}
        \liminf_{h\to 0^+} 
        \frac{f_+(t+h)-f_+(t)}{h} =
        \liminf_{h\to 0^+} 
        \frac{E_{t}(x_{t+h}) - E_t(x_t)}{h}.
    \end{equation}
    Before proceeding, we need to carefully choose the representative $(t,y)$ of $\hat \eta^+(t)$, and to replace $(t,x_t)$ if necessary.
    Indeed, let us firs consider $h_n\searrow 0$ as $n\to\infty$ such that
    \begin{equation} \label{eq:app_liminf_subseq}
        \liminf_{h\to 0^+} 
        \frac{E_{t}(x_{t+h}) - E_t(x_t)}{h}
        = \lim_{n\to\infty} \frac{E_{t}(x_{t+h_n}) - E_t(x_t)}{h_n},
    \end{equation}
    and such that there exits $x'\in \Xx$ for which $d(x_{t+h_n}, x')\to 0$ as $n\to\infty$. We recall that it is possible to find such a sequence by virtue of \cref{rmk:compactness_limit_traj}.
    Moreover, since $[(t+ h_n, x_{t+h_n})]= \hat \eta ^+(t+h_n) \to_\X \hat\eta^+(t)$ as $n\to\infty$, we deduce that $(t,x')\in \hat\eta^+(t)$.
    Hence, since $[(t,x')] = \hat\eta^+(t) = [(t,x_t)]$, from \cref{eq:app_liminf_equiv,eq:app_liminf_subseq} we obtain that
    \begin{equation} \label{eq:app_liminf_new_rep}
        \liminf_{h\to 0^+} 
        \frac{f_+(t+h)-f_+(t)}{h} =
        \lim_{n\to\infty} \frac{E_{t}(x_{t+h_n}) - E_t(x')}{h_n},
    \end{equation}
    where we used the fact that $E_t(x_t) = E_t(x')$, ensured by \cref{ass:conn_comp}.
    Then, we note that if $E_{t}(x_{t+h_n}) = E_t(x')$ for infinitely many $n\in \NN$, then the thesis follows immediately. Therefore, we assume that $E_{t}(x_{t+h_n}) \neq E_t(x')$ for $n$ large enough.
    From this fact, since $d(x_{t+h_n}, x')\to 0$ as $n\to \infty$ and since the connected components of critical points are assumed to be well-separated (see again \cref{ass:conn_comp}), it follows that eventually $|\partial E_{t}|(x_{t+h_n}) \neq 0$.
    Hence, we compute
    \begin{equation*}
            \frac{E_{t}(x_{t+h_n}) - E_t(x')}{h_n} =
            \frac{E_{t}(x_{t+h_n}) - E_t(x')}{|\partial E_{t}|(x_{t+h_n})} \frac{|\partial E_{t}|(x_{t+h_n})}{h_n}  \geq -\varepsilon_{x'}\big(  d(x_{t+h_n},x') \big) L,
    \end{equation*}
    where we used \cref{ass:PL+time_der_slope}, together with the fact that $|\partial E_{t+h_n}|(x_{t+h_n})=0$, due to $[(t+h_n,x_{t+h_n})]=\hat \eta^+(t+h_n)$.
    Hence, by taking the limit in the last inequality, we finally deduce that
    \begin{equation*}
        \liminf_{h\to 0^+} 
        \frac{f_+(t+h)-f_+(t)}{h} =
        \lim_{n\to\infty} \frac{E_{t}(x_{t+h_n}) - E_t(x')}{h_n} \geq 0
    \end{equation*}
    and we conclude the proof.
\end{proof}

We report below a well-known sufficient condition for monotonicity of continuous functions.

\begin{lemma} \label{lem:monotn_Dini}
    Let $g\colon [a,b] \to \R$ be continuous and such that the Dini upper right derivative of $g$ satisfies
    \begin{equation*}
        D^+g'(t) \coloneqq  \limsup_{h\to 0^+} 
        \frac{g(t+h)-g(t)}{h} \geq 0
    \end{equation*}
    for every $t\in (a,b)$. Then, $g$ is non-decreasing on $(a,b)$.
\end{lemma}
\begin{proof}
    See, e.g., \cite[Lemma~5.2]{Scilla_2018}.
\end{proof}

Now, we show that the non-negative measure $\bar \mu$ appearing in the energy balance in \cref{thm:main_result_complete} is purely atomic. 
Since we already took care of the peculiarity of our setting in \cref{prop:dini_der}, we report the the arguments in the next proof follows the lines of \cite[Theorem~5.4]{Scilla_2018}.
We detail the proof for the sake of completeness.

\begin{proposition}\label{prop:mu_atomic}
    Let us assume \cref{ass:conn_comp,ass:der_time,ass:metric_space,ass:path+Lipsch,ass:PL+time_der_slope,ass:reg_E,ass:unif_coerc,ass:t_der_quotient}.
    Let $\bar \mu$ be the non-negative measure appearing in the energy balance in \cref{thm:traj_convergence}. Then, we have that $\mathrm{supp}\, \mu = J$, where $J$ is the jump set of the limiting trajectory $\hat\eta\colon [0,T]\to \X$.
\end{proposition}

\begin{proof}
    We consider the non-increasing function $f\colon [0,T]\to \R$ defined as in \cref{eq:def_ancill_funct_mu}, and, owing to \cref{thm:traj_convergence} and to the enhanced energy balance in \cref{eq:energy_balance_quotient}, we observe that the distributional derivative of $f$ satisfies $\bar \mu = -df$, and we recall $\bar \mu$ is a positive measure.
    To see that $\mathrm{supp}\, \bar \mu = J$, we introduce the non-increasing function
    \begin{equation*}
        f^J(t) \coloneqq \sum_{s\in [0,t]}\big( f_+(s) - f_-(s) \big),
    \end{equation*}
    and we observe that it is right-continuous. Moreover, the set of dicontinuity points for $f^J$ is exactly $J$, and the distributional derivative satisfies $d(f^J) = (df)^J$, where  $(df)^J$ denotes the jump part of the measure $df$. Then, we observe that $\bar \mu = -df \geq -d(f^J) \eqqcolon \bar \mu^J$.
    In addition, recalling that $ f^J(t)-f^J(t+h) \geq 0$ for every $h\geq 0$, we have that
    \begin{equation} \label{eq:dini_specific}
        \liminf_{h\to 0} 
        \frac{(f_+-f^J)(t+h)-(f_+-f^J)(t)}{h} \geq
        \liminf_{h\to 0} 
        \frac{f_+(t+h) - f_+(t)}{h} \geq 0.
    \end{equation}
    We further notice that the function $f_+-f^J$ is continuous. Indeed, on the one hand, both $f_+$ and $f^J$ are right-continuous. 
    On the other hand, we have $\lim_{h\to 0^+} f_+(t-h) = f_-(t)$ and
    \begin{equation*}
        \lim_{h\to 0^+} f^J(t-h) = \sum_{s\in [0,t)}\big( f_+(s) - f_-(s) \big) = f^J(t) - \big( f_+(t) - f_-(t) \big)
    \end{equation*}
    for every $t\in(0,T]$, which combined provide the left-continuity of $f_+-f^J$.
    Hence, by using \cref{eq:dini_specific} and \cref{lem:monotn_Dini}, we deduce that $f_+-f^J$ is non-decreasing.
    Therefore, from the inequality $f_+(t)-f^J(t)\geq f_+(0)-f^J(0)$, recalling that $f^J(t) = - \bar \mu^J([0,t])$ and that $f_+(0)-f^J(0)=f_-(t)$, we obtain that 
    \begin{equation*}
        \hat E\big(\hat\eta^+(t)\big) + \bar \mu^J ([0, t]) \geq \hat E\big(\hat\eta^-(0)\big) + \int_0^t \partial_t \hat E \big(\hat\eta(\tau)\big) \diff \tau 
    \end{equation*}
    for every $t\in [0,T]$.
    Recalling that $\bar \mu^J, \bar \mu$ are positive, from the last inequality and from the balance in \cref{eq:energy_balance_quotient} we deduce that $\bar \mu^J \geq \bar \mu$. Since by construction $\bar \mu \geq \bar \mu^J$, this shows that $\bar \mu = \bar \mu^J$ and concludes the proof.
\end{proof}





\section{Gradient flow vs.~minimizing movement scheme actions}
%{Relation between the action corresponding to the gradient descent and the action corresponding to the minimizing movement scheme}
In this section, we relate the actions $\cB_t$ and $\cM_t$, corresponding to the gradient descent and to the minimizing movement scheme, respectively.
From here on, we fix a time $t \in [0, T]$ and consequently drop the subscript $t$ from the notation:
We concern ourselves with two actions $\cB$ and $\cM$
and an energy functional $E$ on $\Xx$.
We begin by relating $\CostGF$ and $\CostM$, the instantaneous costs  of the gradient flow and of the minimizing movement scheme, respectively.
\begin{lemma}\label{lemma:instanteneous_cost_relation}
    Let us assume \cref{ass:conn_comp,ass:der_time,ass:metric_space,ass:path+Lipsch,ass:PL+time_der_slope,ass:reg_E,ass:unif_coerc}. Furthermore, let us assume that $L < \frac{1}\tau$, where $L$ is the Lipschitz constant of $|\partial E|$. Then, setting $\varepsilon_L \coloneqq L \cdot \tau$, we have that, for every $x \in \Xx$,
    \begin{equation}\label{eq:app2:relation_between_instantaneous_cost}
        (1 - \varepsilon_L) \CostM\big(i(x)\big) \leq \tau \CostGF\big(i(x)\big) \leq (1 + \varepsilon_L) \CostM\big(i(x)\big).
    \end{equation}
\end{lemma}
\begin{proof}
    We start with the first inequality in \eqref{eq:app2:relation_between_instantaneous_cost}.
    To this end, we fix $x \in \Xx$, pick $x' \in \Xx$ and $\varepsilon > 0$, and set $\underline{d} \coloneqq d(x, x')$. We use \cref{ass:metric_space} to choose an absolutely continuous curve $\gamma\colon [0, \underline{d} + \varepsilon] \to \Xx$ such that $\dot \gamma \equiv 1$, $\gamma(0) = x$ and $\gamma(\underline{d} + \varepsilon) = x'$.
    Since $|\partial E|$ is a strong upper gradient---see \cref{rmk:slope_strong_upper_gradient}---we have
    \begin{align*}
        E(x) - E(x') - \frac{1}{2\tau} \underline{d}^2 &\leq \int_0^{\underline{d}+\varepsilon}|\partial E|(\gamma(s)) \diff s - \frac{1}{2\tau} \underline{d}^2
        \leq \int_0^{\underline{d} + \varepsilon} \big(|\partial E|(x) + L s\big) \diff s - \frac{1}{2\tau} \underline{d}^2 \\
        &\leq (\underline{d} + \varepsilon) |\partial E|(x) + \frac{1}{2}L(\underline{d} + \varepsilon)^2 - \frac{1}{2\tau} \underline{d}^2.
    \end{align*}
    Taking $\varepsilon \to 0$, we get
    \begin{equation}\label{eq:app2:bound_over_energy_diff}
        E(x) - E(x') - \frac{1}{2\tau} \underline{d}^2 \leq \underline{d} |\partial E|(x) + L\frac{1}{2}\underline{d}^2 - \frac{1}{2\tau} \underline{d}^2 = \underline{d} |\partial E|(x) - \frac{1}{2\tau} (1 - \varepsilon_L)  \underline{d}^2.
    \end{equation}
    The right hand side above is a quadratic equation whose maximum is attained at $\underline{d} = \tau|\partial E|(x) \frac{1}{(1 - \varepsilon_L)}$; substituting this choice of $\underline{d}$ into \cref{eq:app2:bound_over_energy_diff} gives
    \begin{equation*}\label{eq:app2:uniform_bound_over_energy_diff}
        E(x) - E(x') - \frac{1}{2\tau} \underline{d}^2 \leq {\tau} \frac{1}{1 - \varepsilon_L} \frac{1}{2} |\partial E|(x)^2
    \end{equation*}
    As $\CostM\big(i(x)\big)$ is the supremum of the left hand side of the above equation over all $x' \in \Xx$, we have
    \begin{equation*}
        \CostM\big(i(x)\big) \leq {\tau} \frac{1}{1 - \varepsilon_L} \frac{1}{2} |\partial E|(x)^2 = {\tau} \frac{1}{1 - \varepsilon_L} \CostGF(i(x)), 
    \end{equation*}
    which finishes the proof of the first inequality.\\
    For the second inequality in \eqref{eq:app2:relation_between_instantaneous_cost}, we start by letting $\gamma\colon [0, \infty) \to \Xx$ be a curve of maximum slope such that $\gamma(0)=x$, which in particular implies that the following equation holds for all $s \geq 0$:
    \begin{equation}\label{eq:gamma_max_slope}
        E(x) - E\big(\gamma(s)\big) = \int_0^s |\partial E|\big(\gamma(r)\big)|\dot \gamma| \diff r;
    \end{equation}
    such a curve of maximum slope exists by \cref{rmk:slope_strong_upper_gradient} and \cite[Prop.~2.2.3, Theorem~2.3.3]{greenbook}.
    For $s > 0$, we set $l_s \coloneqq \int_0^s |\dot \gamma(\sigma) | \diff \sigma$ and we define $l_\infty \coloneqq \int_0^\infty |\dot \gamma(\sigma) | \diff \sigma$.
    Note that, as $\gamma$ is a curve of maximum slope, in addition to \cref{eq:gamma_max_slope}, the following holds for almost all $s > 0$:
    \begin{equation*}
        |\dot \gamma|(s) = |\partial E|(\gamma(s)) \leq |\partial E|(x) - L \int_0^s |\dot \gamma|(r) \diff r.
    \end{equation*}
    Using Grönwall's lemma, we deduce from the above that $|\dot \gamma|(s) \geq |\partial E|(x) e^{-L s}$,
    and thus that
    \begin{equation}\label{eq:l_infty}
        l_\infty \geq \frac{1}{L} |\partial E|(x).
    \end{equation}
    As a next step, we reparametrize $\gamma$ to obtain a curve $\widetilde{\gamma}\colon [0, l_\infty] \to \Xx$ such that $\widetilde{\gamma}(0) = x$,
    $\dot{\widetilde{\gamma}}(s) \equiv 1$ and such that \cref{eq:gamma_gradient_flow} holds for $\widetilde{\gamma}$
    in place of $\gamma$.
    We calculate, for $s \in [0, l_\infty]$,
    \begin{align*}
        \CostM\big(i(x)\big) &\geq E(x) - E\big(\widetilde{\gamma}(s)) - \frac{1}{2\tau} d\big(x, \widetilde{\gamma}(s)\big)^2 = \int_0^s |\partial E|\big(\widetilde{\gamma}(r)\big) \diff r - \frac{1}{2\tau} d\big(x, \widetilde{\gamma}(s)\big)^2 \\
        &\geq \int_0^s \left(|\partial E|(x) - L r\right) \diff r - \frac{1}{2\tau} s^2 = s |\partial E|(x) - \frac{1}{2}L s^2 - \frac{1}{2\tau} s^2 \\
        &= s |\partial E|(x) - \frac{1}{2} \left(L + \frac{1}{\tau}\right) s^2.
    \end{align*}
    Evaluating the above at $s^\star \coloneqq \frac{|\partial E|(x)}{L + \frac{1}{\tau}}$---justified by \cref{eq:l_infty}--- gives
    \begin{align*}
        \CostM\big(i(x)\big) &\geq \frac{1}{2} |\partial E|(x)^2 \tau \frac{1}{1 + \varepsilon_L} = \tau \CostGF\big(i(x)\big) \frac{1}{1 + \varepsilon_L},
    \end{align*}
    which finishes the proof of the second inequality.
\end{proof}
As a next step, we show that we can bound the cost of a single step of the minimizing movement scheme
by the cost of the gradient descent action, as long as step is small enough.
\begin{lemma}\label{lemma:estimate_one_step_of_mms_by_gf}
    Let us assume \cref{ass:conn_comp,ass:der_time,ass:metric_space,ass:path+Lipsch,ass:PL+time_der_slope,ass:reg_E,ass:unif_coerc}. Furthermore, let us assume that $L < \frac{1}\tau$, where $L$ is the Lipschitz constant of $|\partial E|$. Then, setting $\varepsilon_L \coloneqq L \cdot \tau$, we have, for each $x, x' \in \Xx$ such that $d(x, x') \leq \tau \cdot |\partial E|(x)$,
    \begin{equation}\label{eq:app2:bound_of_single_step_with_error}
        \begin{split}
            (1 - \varepsilon_L) \CostM\big((x, x')\big) &\leq 2 \cGF(x, x')  + |\partial E|(x) \big(\tau |\partial E|(x) - d(x, x')\big) \\
            &\leq 2 \cGF(x, x') + 2 \tau \CostGF\big(i(x)\big).
        \end{split}
    \end{equation}
    In particular, if $d(x, x') = \tau |\partial E|(x)$, the above inequality reduces to
    \begin{equation}\label{eq:app2:bound_of_single_step_without_error}
        (1 - \varepsilon_L) \CostM\big((x, x')\big) \leq 2 \cGF(x, x').
    \end{equation}
\end{lemma}
\begin{proof}
    Both the second inequality in~\eqref{eq:app2:bound_of_single_step_with_error} and~\eqref{eq:app2:bound_of_single_step_without_error} follow immediatly. In the rest of this proof, we concern ourselves the first inequality in~\eqref{eq:app2:bound_of_single_step_with_error}.
    Under the above assumptions, we have, using \cref{lemma:instanteneous_cost_relation}:
    \begin{equation}\label{eq:action_estimation_1}
        \begin{split}
            (1 - \varepsilon_L) \CostM\big((x, x')\big) &= (1 - \varepsilon_L) \bigg( \CostM\big(i(x)\big) + \frac{1}{2\tau} d(x, x')^2\bigg) \\
            &\leq \tau \CostGF\big(i(x)\big) + \frac{1}{2\tau}\tau^2|\partial E|(x)^2 = 2\tau\CostGF\big(i(x)\big).
        \end{split}
    \end{equation}
    On the other hand, we can bound $\cGF(x, x')$ from below: By virtue of \cref{lemma:equivalent_minimization} it suffices to find a lower bound for $\int_0^s |\partial E|(\gamma(\sigma)) \diff \sigma$, uniformly over $s > 0$ and all absolutely continuous curves $\gamma\colon [0, s] \to \Xx$ such that $\dot \gamma \equiv 1$, $\gamma(0) = x$ and $\gamma(s) = x'$. Let such $s$ and $\gamma$ be given. We note that $s \geq d(x, x') \eqqcolon \underline{d}$ and write
    \begin{equation*}
        \begin{split}
            \int_0^s |\partial E|(\gamma(\sigma)) \diff \sigma &\geq \int_0^{\underline{d}} |\partial E|(\gamma(\sigma)) \diff \sigma  \geq \underline{d} |\partial E|(x) - \frac{1}{2} L \underline{d}^2 \\
            &\geq \frac{1}{2} |\partial E|(x) \underline{d} = \frac{1}{2} \tau |\partial E|(x)^2 - \frac{1}{2} |\partial E|(x) \big(\tau |\partial E|(x) - \underline{d}\big).
        \end{split}
    \end{equation*}
    Taking the infimum over $\gamma$ in the inequality above, we obtain
    \begin{equation}\label{eq:action_estimation_2}
        \cGF(x, x') \geq \tau \CostGF\big(i(x)\big) - \frac{1}{2} |\partial E|(x) \big(\tau |\partial E|(x) - \underline{d}\big).
    \end{equation}
    Combining \cref{eq:action_estimation_1,eq:action_estimation_2} gives
    \begin{align*}
        (1 - \varepsilon_L) \CostM\big((x, x')\big) &\leq 2 \cGF(x, x') + |\partial E|(x) \big(\tau |\partial E|(x) - \underline{d}\big)
    \end{align*}
    as required.
\end{proof}
We continue by proving a inverse relation to \cref{lemma:estimate_one_step_of_mms_by_gf}:
\begin{lemma}\label{lemma:estimate_gf_by_one_step_of_mms}
    Let us assume \cref{ass:conn_comp,ass:der_time,ass:metric_space,ass:path+Lipsch,ass:PL+time_der_slope,ass:reg_E,ass:unif_coerc}. Furthermore, let us assume that $L < \frac{1}\tau$, where $L$ is the Lipschitz constant of $|\partial E|$. Then, setting $\varepsilon_L \coloneqq L \cdot \tau$, we have, for every $x, x' \in \Xx$:
    \begin{equation*}
        \cGF(x, x') \leq 4 \frac{1 + \varepsilon_L}{1 - \varepsilon_L} \,\CostM\big((x, x')\big)
    \end{equation*}
\end{lemma}
\begin{proof}
    The proof is similar to the first part of the proof of \cref{lemma:instanteneous_cost_relation}.
    We show the inequality by choosing, for an arbitrary $\varepsilon > 0$, as a competitor for the infimum in \cref{eq:equivalent_minimization_2}
    an absolutely continuous curve $\gamma\colon [0, \underline{d} + \varepsilon] \to \Xx$ such that $\dot \gamma \equiv 1$, $\gamma(0) = x$ and $\gamma(\underline{d} + \varepsilon) = x'$; the existence of such a curve is guaranteed by \cref{ass:metric_space}.
    With this choice, we have, setting $\underline{d} \coloneqq d(x, x')$:
    \begin{equation*}
        \cGF(x, x') \leq \int_0^{\underline{d}+\varepsilon} |\partial E|\big(\gamma(s)\big) \diff s 
        \leq (\underline{d} + \varepsilon) |\partial E|(x) + \frac{1}{2}L (\underline{d} + \varepsilon)^2.
    \end{equation*}
    Taking the limit $\varepsilon \to 0$, we get
    \begin{equation}\label{eq:gradient_cost_crude_estimate}
        \cGF(x, x') \leq \underline{d}|\partial E|(x) + \frac{1}{2}L \underline{d}^2 = \underline{d}|\partial E|(x) + \frac{1}{2\tau} \underline{d}^2 - \frac{1}{2\tau} ( 1 - \varepsilon_L)  \underline{d}^2.
    \end{equation}
    If $\underline{d} \leq \frac{2\tau}{1 - \varepsilon_L} |\partial E|(x)$, we use \cref{lemma:instanteneous_cost_relation} to reduce the above to
    \begin{align*}
        \cGF(x, x') &\leq \frac{2\tau}{1 - \varepsilon_L}|\partial E|^2(x) + \frac{1}{2\tau} \underline{d}^2 = \frac{4}{1 - \varepsilon_L}\tau \CostGF(i(x)) + \frac{1}{2\tau} \underline{d}^2 \\
        &\leq  4 \frac{1 + \varepsilon_L}{1 - \varepsilon_L}\, \CostM\big(i(x)\big) + \frac{1}{2\tau} \underline{d}^2 \leq 4 \frac{1 + \varepsilon_L}{1 - \varepsilon_L} \,\CostM\big((x, x')\big).
    \end{align*}
    On the other hand, if $\underline{d} >  \frac{2\tau}{1 - \varepsilon_L} |\partial E|(x)$, 
    \cref{eq:gradient_cost_crude_estimate} also gives
    \begin{align*}
        \cGF(x, x') &\leq \underline{d}|\partial E|(x) + \frac{1}{2\tau} \underline{d}^2 - \frac{1}{2\tau} ( 1 - \varepsilon_L)   \frac{2\tau}{1 - \varepsilon_L} |\partial E|(x) \underline{d}  \\
        &= \frac{1}{2\tau} \underline{d}^2 \leq \CostM\big((x, x')\big) \leq 4 \frac{1 + \varepsilon_L}{1 - \varepsilon_L} \, \CostM\big((x, x')\big).
    \end{align*}
\end{proof}
We are now in position to prove a relation between the actions $\cB$ and $\cM$.
\begin{lemma}
    Let us assume \cref{ass:conn_comp,ass:der_time,ass:metric_space,ass:path+Lipsch,ass:PL+time_der_slope,ass:reg_E,ass:unif_coerc}. Furthermore, let us assume that $L < \frac{1}\tau$, where $L$ is the Lipschitz constant of $|\partial E|$. Then, setting $\varepsilon_L \coloneqq L \cdot \tau$, we have, for any $x \neq x' \in \Xx$
    \begin{equation}\label{eq:app2:relation_of_actions}
        \frac{1-\varepsilon_L}{4(1+\varepsilon_L)} \cGF(x, x') \leq \cM(x, x') - \CostM\big(i(x)\big) \leq \frac{2}{1-\varepsilon_L} \cGF(x, x') + \frac{2 \tau R}{1-\varepsilon_L},
    \end{equation}
    where $R \coloneqq \sup_{x'' \in K_\Xx}\CostGF\big(i(x'')\big)$, $K \subseteq \PpGF$ is a chosen compact such that \cref{prop:curves_coercive} for $\cGF$ is fulfilled for $K$, and $K_\Xx$ denotes the projection of $K$ onto $\Xx$.
\end{lemma}
\begin{proof}
    We start with the first inequality. By taking the infimum, it suffices to show that for all competitors $\gamma \in \Gamma\MMS\big(i(x), i(x')\big)$,
    we have that
    \begin{equation}\label{eq:app2:upper_bound_costGF_proof}
        \frac{1-\varepsilon_L}{4(1+\varepsilon_L)} \cGF(x, x') \leq \sum_{j=a+1}^{b} \CostM\big(\gamma(j)\big) - \CostM\big(i(x)\big) = \sum_{j=a+1}^{b-1} \CostM\big(\gamma(j)\big),
    \end{equation}
    where $a < b \in \Z$ are chosen such that $\dom(\gamma) = [a, b]_\Z$; for the second equality above, note that necessarily $\gamma(b) = i(x')$. However,~\eqref{eq:app2:upper_bound_costGF_proof} follows by repeatedly applying \cref{lemma:estimate_gf_by_one_step_of_mms}, using the triangular inequality on $\cGF$ and noting that $\gamma_2(j) = \gamma_1(j+1)$ for all $j \in [a, b-1]_\Z$ and that $\gamma_1(a+1) = x$, $\gamma_2(b-1) = x'$. \\
    We now turn to the second inequality in~\eqref{eq:app2:relation_of_actions}, which is a little more intricate to prove. We start by picking some $\varepsilon > 0$ and a curve $\gamma \in \Gamma\GF\big(i(x), i(x')\big)$ such that
    $\int_a^b\CostGF\big(\gamma(s)\big) \diff s \leq \cGF(x, x') + \varepsilon$,
    where $a < b \in \R$ are such that $\dom(\gamma) = [a, b]_\R$, and such that $\im(\gamma) \subseteq K$---\cref{prop:curves_coercive} guarantees that we can indeed pick such a curve. In the rest of this proof, we will choose appriate control points along the curve $\gamma$ to repeatedly apply \cref{lemma:estimate_one_step_of_mms_by_gf} to the segments of $\gamma$. \\
    Recalling the indexing conventions on $\gamma$ introduced in \cref{lemma:gradient_flow_summary_lemma}, we pick some arbitrary $\varepsilon' > 0$ and iteratively choose controlpoints
    $a=t_1 < \dots < t_n \in [a, b]$ such that---setting $y_i \coloneqq \gamma_x(t_i)$---$d(y_i, y_{i+1}) = \max\{\tau |\partial E|(y_i), \varepsilon'\}$ for $1 \leq i < n$ and such that $d(y_n, x') \leq \tau |\partial E|(y_n)$. Denoting the length of $\gamma_x$ by $l$, we have that $n \leq \frac{l}{\varepsilon'}$. For each $1 \leq i < n$, if 
    $\tau |\partial E|(y_i) \leq \varepsilon'$, we can use \cref{lemma:instanteneous_cost_relation} to see that
    \begin{align*}
        (1 - \varepsilon_L) \, \CostM\big((y_i, y_{i+1})\big) &\leq \tau \CostGF\big(i(y_i)\big) + \frac{1-\varepsilon_L}{2 \tau} \varepsilon'^2 = \frac{1}{2\tau}\big(\tau|\partial E|(y_i)\big)^2 + \frac{1-\varepsilon_L}{2 \tau} \varepsilon'^2 \\
        &\leq \frac{1}{2\tau} \varepsilon'^2 + \frac{1}{2\tau} \varepsilon'^2 = \frac{1}{\tau} \varepsilon'^2.
    \end{align*}
    On the other hand, if $\tau |\partial E|(y_i) \geq \varepsilon'$, we can use \cref{lemma:estimate_one_step_of_mms_by_gf} to see that $(1 - \varepsilon_L) \, \CostM\big((y_i, y_{i+1})\big) \leq 2 \cGF(y_i, y_{i+1})$. Thus, either way,
    \begin{equation*}
        (1 - \varepsilon_L) \, \CostM\big((y_i, y_{i+1})\big) \leq 2 \cGF(y_i, y_{i+1}) + \frac{1}{\tau} \varepsilon'^2 \leq 2 \int_{t_i}^{t_{i+1}} \CostGF\big(\gamma(s)\big) \diff s + \frac{1}{\tau} \varepsilon'^2;
    \end{equation*}
    furthermore, also using \cref{lemma:estimate_one_step_of_mms_by_gf}, we also have that
    \begin{equation*}
        (1 - \varepsilon_L) \, \CostM\big((y_n, x')\big) \leq 2 \cGF(x, x') + 2 \tau \CostGF\big(i(x)\big) \leq 2 \int_{t_n}^{b} \CostGF\big(\gamma(s)\big) \diff s + 2 \tau \CostGF\big(i(x)\big).
    \end{equation*}
    Using the curve $\big(i(x), (y_1, y_2), (y_2, y_3), \dots, (y_{n-1}, y_n), (y_n, x'), i(x')\big) \in \Gamma\MMS\big(i(x), i(x')\big)$ as a competitor for the infimum in $\cM(x, x')$, we finally get
    \begin{align*}
        \cM(x, x') &\leq \sum_{i=1}^{n-1} \CostM\big((y_i, y_{i+1})\big) + \CostM\big((y_n, x')\big) + \CostM\big(i(x')\big) \\
        &\begin{aligned}
            \leq \frac{1}{1 - \varepsilon_L}\bigg(2 \sum_{i=1}^{n-1} \int_{t_i}^{t_{i+1}} \CostGF\big(\gamma(s)\big) \diff s + (n-1) \frac{1}{\tau} \varepsilon'^2 + &\\
            2 \int_{t_n}^{b} \CostGF\big(\gamma(s)\big) \diff s + 2 \tau \CostGF\big(i(x)\big)&\bigg) + \CostM\big(i(x')\big)
        \end{aligned} \\
        &\leq \frac{1}{1 - \varepsilon_L}\bigg( 2 \int_a^b \CostGF\big(\gamma(s)\big) \diff s + \frac{l \varepsilon'}{\tau} + 2\tau R\bigg) + \CostM\big(i(x')\big) \\
        &\leq \frac{2}{1-\varepsilon_L}\cGF(x, x') + \varepsilon + \frac{l \varepsilon'}{\tau} + \frac{2 \tau R}{1-\varepsilon_L} + \CostM\big(i(x')\big).
    \end{align*}
    As both $\varepsilon > 0$ and $\varepsilon' > 0$ were arbitrary, we can take the limit $\varepsilon \to 0$ and $\varepsilon' \to 0$ in the above inequality to obtain the thesis.
\end{proof}

