\section{Modular symbols for Rankin-Selberg convolutions}

In this section, we define the modular symbols to provide a cohomological interpretation of the Rankin-Selberg integrals for $\GL_n\times\GL_n$. 



\subsection{Rankin-Selberg integrals}





Let $\psi_{\R}:\R\to\C^{\times}$ be the unitary character defined by $x\mapsto \mathrm{e}^{2\pi\mathrm{i}x}$. Fix a nontrivial additive character of $\rk\backslash\A$ as the composition
\begin{equation}
	\psi:\rk\backslash\A\xrightarrow{\mathrm{Tr}_{\rk/\BQ}}\BQ\backslash\A_{\BQ}\to\BQ\backslash\A_{\BQ}/\widehat{\Z}=\R/\Z\xrightarrow{\psi_{\R}}\C^{\times},
\end{equation}
where $\mathbb{A}_{\BQ}$ is the adele ring of $\BQ$; $\mathrm{Tr}_{\rk/\BQ}$ is the trace map; and $\widehat{\Z}$ is the profinite completion of $\Z$. This further induces an automorphic character
\begin{equation}\label{psin}
	\begin{aligned}
		\psi_n:\RN_n(\A)\times\RN_n(\A)&\to\C^{\times},\\
		\left([x_{i,j}]_{1\leq i,j\leq n},[x'_{i,j}]_{1\leq i,j\leq n}\right)&\mapsto\psi\left(\sum_{i=1}^{n-1}(x_{i,i+1}-x_{i,i+1}')\right).
	\end{aligned}
\end{equation}
When no confusion occurs, we identify a character of a group as the complex vector space $\C$ equipped with the corresponding action of the group.

On $\A$ we choose the self-dual measure with respect to $\psi$ so that $\rk\backslash\A$ has total volume $1$. For each place $v$, we fix a Haar measure $\mathrm{d}x_v$ on $\rk_v$ such that
\begin{itemize}
    \item $\CO_v$ has volume $1$ if $v$ is non-archimedean, where $\CO_v$ denotes the ring of integers of $\rk_v$; and
    \item the product of all the measures $\{\mathrm{d}x_v\}_v$ equals the self-dual Haar measure on $\mathbb{A}$.
\end{itemize}
The Haar measure on $\RN_n(\A)$ (resp. $\RN_n(\rk_v)$) is fixed to be the product of the Haar measures on $\A$ (resp. $\rk_v$). 

We define the global Whittaker functional
\begin{equation}
	\lambda_{\Pi}\in\mathrm{Hom}_{\RN_n(\A)\times\RN_n(\A)}(\Pi,\psi_n),
\end{equation}
for $\Pi$ by integrals
\[
f\mapsto\int_{\RN_n(\rk)\backslash\RN_n(\A)\times\RN_n(\rk)\backslash\RN_n(\A)}f(u)\overline{\psi_n}(u)\mathrm{d}u.
\]
The uniqueness of Whittaker models provides a factorization
\[
\begin{aligned}
	\lambda_{\Pi}&=\otimes_v'\lambda_{\Pi,v}=\lambda_{\Pi,\mathrm{f}}\otimes\lambda_{\Pi,\infty},&\,&\lambda_{\Pi,\mathrm{f}}:=\otimes_{v\nmid\infty}'\lambda_{\Pi,v},\ \lambda_{\Pi,\infty}:=\otimes_{v|\infty}\lambda_{\Pi,v},
\end{aligned}
\]
where
\[
\begin{aligned}
	\lambda_{\Pi,v}&\in\mathrm{Hom}_{\RN_n(\rk_v)\times\RN_n(\rk_v)}(\Pi_v,\psi_{n,v}).
\end{aligned}
\]

For each place $v$, we choose the multiplicative measure
\[
\frac{\mathrm{d}x_v}{|x|_v}\cdot\zeta_v(1)
\]
on  $\RZ_n(\rk_v)=\rk_v^{\times}$, where
\[
\zeta_v(1):=\begin{cases}
    (1-q_v^{-1})^{-1},&\text{if }v\text{ is non-archimedean},\\
    \pi^{-1},&\text{if }v\text{ is (complex) archimedean},
\end{cases}
\]
and $q_v$ is the cardinality of the residue field for $\rk_v$ when $v$ is non-archimedean. The measure of $\RZ_n(\A)=\A^{\times}$ is fixed to be the product of measures of $\rk_v^{\times}$. Let $\mathfrak{M}_{n,v}$ be the one-dimensional space of invariant measures on $\GL_n(\rk_v)$. When $v$ is non-archimedean, it has a distinguished element with respect to which $\GL_n(\CO_v)$ has total volume $1$. We denote by $\mathfrak{M}_n$ the one-dimensional space of invariant measures on $\GL_n(\A)$. Write
\[
\mathfrak{M}_n=\otimes_v'\mathfrak{M}_{n,v}=\mathfrak{M}_{n,\infty}\otimes\mathfrak{M}_{n,\mathrm{f}},\qquad\mathfrak{M}_{n,\mathrm{f}}:=\otimes_{v\nmid\infty}'\mathfrak{M}_{n,v},\ \mathfrak{M}_{n,\infty}:=\otimes_{v|\infty}\mathfrak{M}_{n,v},
\]
where the restricted tensor product is defined with respect to those distinguished elements of $\mathfrak{M}_{n,v}$. For each $\mathrm{d}g\in\mathfrak{M}_n$ or $\mathfrak{M}_{n,v}$, we write $\overline{\mathrm{d}}g$ for various quotient measures induced by $\mathrm{d}g$ whose meaning will be clear from the integral.

For $\phi\in \Pi$, $\varphi\in I_{\eta,\chi}$ and $\mathrm{d}g\in\mathfrak{M}_n$, the global Rankin-Selberg integral is defined by
\begin{equation}\label{globalRS}
	\RZ(s,\phi,\varphi;\chi,\mathrm{d}g):=\int_{\RZ_n(\A)\GL_n(\rk)\backslash\GL_n(\A)}\phi(g)\RE(g;\varphi_s)\overline{\mathrm{d}}g.
\end{equation}
It converges absolutely when $\mathrm{Re}(s)$ is sufficiently large and has a meromorphic continuation to the whole complex plane in $s$. When $\mathrm{Re}(s)$ is sufficiently large, \eqref{globalRS} unfolds as
\[
\RZ(s,\phi,\varphi;\chi,\mathrm{d}g)=\int_{\RZ_n(\A)\RN_n(\A)\backslash\GL_n(\A)}\lambda_{\Pi}(g.\phi)\varphi_s(g)\overline{\mathrm{d}}g.
\] 
Therefore, for decomposable data, the global Rankin-Selberg integral admits an Euler product factorization into the local Rankin-Selberg integrals
\begin{equation}\label{localRS}
	\RZ_v(s,\phi_v,\varphi_v;\chi_v,\mathrm{d}g):=\int_{\RZ_n(\rk_v)\RN_n(\rk_v)\backslash\GL_n(\rk_v)}\lambda_{\Pi,v}(g.\phi_v)\varphi_{s,v}(g)\overline{\mathrm{d}}g
\end{equation}
for $\phi_v\in\Pi_v$, $\varphi_v\in I_{\eta_v,\chi_v}$, $\mathrm{d}g\in\mathfrak{M}_{n,v}$. We further define the normalized local Rankin-Selberg integrals
\begin{equation}\label{normalizedRS}
	\RZ^{\circ}_v(s,\phi_v,\varphi_v;\chi_v,\mathrm{d}g):=\frac{\RL(s,\omega_{\Pi_v}\chi_v^n)}{\RL(s,\Pi_v\times\chi_v)}\cdot\RZ_v(s,\phi_v,\varphi_v;\chi_v,\mathrm{d}g).
\end{equation}
By \cite{JS1} and \cite{DX} (see also \cite[Proposition 3.2]{local}), the normalized local Rankin-Selberg integral is holomorphic at $s=0$ and yields a nonzero linear functional
\begin{equation}\label{functionalRS}
	\RZ^{\circ}_{\Pi_v,\chi_v}\in\mathrm{Hom}_{\GL_n(\rk_v)}\left(\Pi_v\otimes\chi_v\otimes\mathfrak{M}_{n,v},\C\right).
\end{equation}
Denote
\[
\RZ^{\circ}_{\Pi_{\infty},\chi_{\infty}}:=\bigotimes_{v|\infty}\RZ^{\circ}_{\Pi_v,\chi_v},\qquad \RZ^{\circ}_{\Pi_{\mathrm{f}},\chi_{\mathrm{f}}}:=\bigotimes_{v\nmid\infty}\RZ^{\circ}_{\Pi_v,\chi_v}.
\]



\subsection{Definition of modular symbols}

For each archimedean place $v$, let $\mathfrak{O}_{n,v}$ be the one-dimensional space of $\GL_n(\rk_v)$-invariant sections of the orientation line bundle of $\R_+^{\times}\backslash\GL_n(\rk_v)/K_{n,v}$ with complex coefficients. Set
\[
\mathfrak{O}_{n,\infty}=\bigotimes_{v|\infty}\mathfrak{O}_{n,v},\qquad\mathfrak{M}^{\natural}_n:=\mathfrak{M}_{n,\mathrm{f}}\otimes\mathfrak{O}_{n,\infty}.
\]
Write for short
\[
\begin{aligned}
	\CH(\Pi,\chi)_{\mathrm{glob}}&:=\CH(\Pi)\otimes\CH(I_{\eta,\chi})\otimes\mathfrak{M}_n^{\natural},\\
	\CH(\Pi_{\infty},\chi_{\infty})&:=\CH(\Pi_{\infty})\otimes\CH(I_{\eta_{\infty},\chi_{\infty}})\otimes\mathfrak{O}_{n,\infty},\\
	\CH(\Pi_{\mathrm{f}},\chi_{\mathrm{f}})&:=\Pi_{\mathrm{f}}\otimes I_{\eta_{\mathrm{f}},\chi_{\mathrm{f}}}\otimes\mathfrak{M}_{n,\mathrm{f}},\\
	\CH(\Pi,\chi)_{\mathrm{loc}}&:=\CH(\Pi_{\infty},\chi_{\infty})\otimes\CH(\Pi_{\mathrm{f}},\chi_{\mathrm{f}}).
\end{aligned}
\]
The canonical maps \eqref{canpi} and \eqref{canI} induce a linear isomorphism
\begin{equation}
\iota_{\mathrm{can}}:\CH(\Pi,\chi)_{\mathrm{loc}}\to\CH(\Pi,\chi)_{\mathrm{glob}}.
\end{equation}

We say that the coefficient systems $F_{\mu},F_{\nu},F_{\eta,\chi}$ are balanced if
\begin{equation}\label{balanced}
	\mathrm{Hom}_{\GL_n(\rk\otimes_{\BQ}\C)}\left(F_{\mu}^{\vee}\otimes F_{\nu}^{\vee}\otimes F_{\eta,\chi}^{\vee},\C\right)\neq\{0\}.
\end{equation}
In this case, $\chi$ is called $(\mu,\nu)$-balanced and the set of such algebraic Hecke characters is denoted by $\RB(\mu,\nu)$. By \cite[Lemma 2.6]{local}, this is equivalent to \eqref{balance+} or \eqref{balance-} holds for all $v|\infty$ for $\mu,\nu,\chi$. Assume $\chi\in\RB(\mu,\nu)$ in the rest of the paper. With respect to certain explicit realizations of $F_{\mu},F_{\nu},F_{\eta,\chi}$, we define a balanced map
\begin{equation}
	\phi_{\mu,\nu,\chi}\in\mathrm{Hom}_{\GL_n(\rk\otimes_{\BQ}\C)}\left(F_{\mu}^{\vee}\otimes F_{\nu}^{\vee}\otimes F_{\eta,\chi}^{\vee},\C\right)=\left(F_{\mu}\otimes F_{\nu}\otimes F_{\eta,\chi}\right)^{\GL_n(\rk\otimes_{\BQ}\C)}
\end{equation}
as in \cite[Section 1.3]{local}. 

Note that pairing with the fundamental class yields a linear map (see \cite[Section 5.1]{Ma05} for more explanation)
\[
\int_{\CX_n}:\RH_{\mathrm{c}}^{d_n}(\CX_n,\C)\otimes\mathfrak{M}_n^{\natural}\to\C.
\]
Here
\[
d_n:=\dim \left(\GL_n(\rk_{\infty})/\widetilde{K}_{n,\infty}\right)=\frac{[\rk:\BQ]}{2}\cdot(n^2-1)=2b_n+c_n.
\]
We define the global modular symbol
\begin{equation}\label{globalmodularsymbol}
	\CP:=\CP_{\Pi,\chi}:\CH(\Pi,\chi)_{\mathrm{glob}}\to\C
\end{equation}
to be the composition of
\[
\begin{aligned}
	\CP_{\Pi,\chi}:\CH(\Pi,\chi)_{\mathrm{glob}}
	\xrightarrow{\iota_{\Pi}\otimes\mathrm{Eis}_{\eta,\chi}}&\RH^{b_n}(\CX_n,F_{\mu}^{\vee})\otimes\RH_{\mathrm{c}}^{b_n}(\CX_n,F_{\nu}^{\vee})\otimes\RH^{c_n}(\CX_n,F_{\eta,\chi}^{\vee})\otimes\mathfrak{M}_n^{\natural}\\
	\xrightarrow{\phi_{\mu,\nu,\chi}}\,&\RH_{\mathrm{c}}^{d_n}(\CX_n,\C)\otimes\mathfrak{M}_n^{\natural}\xrightarrow{\int_{\CX_n}}\C.
\end{aligned}
\]

On the other hand, we define the archimedean modular symbol
\begin{equation}\label{archimedeanmodularsymbol}
	\CP_{\infty}:=\CP_{\Pi_{\infty},\chi_{\infty}}:\CH(\Pi_{\infty},\chi_{\infty})\to\C
\end{equation}
to be the composition of
\[
\begin{aligned}
	\CP_{\Pi_{\infty},\chi_{\infty}}:&\,\CH(\Pi_{\infty},\chi_{\infty})\\
	\xrightarrow{\text{res}}&\,\RH_{\mathrm{ct}}^{d_n}\left(\RZ_n(\rk_{\infty})\backslash\GL_n(\rk_{\infty});F_{\mu}^{\vee}\otimes F_{\nu}^{\vee}\otimes F_{\eta,\chi}^{\vee}\otimes\Pi_{\infty}\otimes I_{\eta_{\infty},\chi_{\infty}}\right)\otimes\mathfrak{O}_{n,\infty}\\
	\xrightarrow{\phi_{\mu,\nu,\chi}\otimes\RZ^{\circ}_{\Pi_{\infty},\chi_{\infty}}}\,&\RH_{\mathrm{ct}}^{d_n}(\RZ_n(\rk_{\infty})\backslash\GL_n(\rk_{\infty}),\mathfrak{M}_{n,\infty}^{\ast})\otimes\mathfrak{O}_{n,\infty}=\C,
\end{aligned}
\]
where the first arrow is the restriction of cohomology. See \cite[Section 1.5]{local} for more details. Here and henceforth, a superscript `$\ast$' over a vector space indicates its dual.  We also have the non-archimedean normalized Rankin-Selberg period
\begin{equation}\label{nonarchimedeanmodularsymbol}
	\CP_{\mathrm{f}}:=\RZ^{\circ}_{\Pi_{\mathrm{f}},\chi_{\mathrm{f}}}:\CH(\Pi_{\mathrm{f}},\chi_{\mathrm{f}})\to\C.
\end{equation}

The global modular symbol is related to the archimedean modular symbol and the non-archimedean normalized Rankin-Selberg period by the following proposition. This is essentially due to the Euler product factorization of the Rankin-Selberg integrals. The proof is same as \cite[Proposition 7.2]{LLS} and will be omitted.

\begin{prp}
	We have the following commutative diagram
	\begin{equation}\label{frontback}
		\begin{CD}
			\CH(\Pi,\chi)_{\mathrm{loc}} @>\CP_{\infty}\otimes\CP_{\mathrm{f}}>>\C\\
			@V\iota_{\mathrm{can}}VV @VV\CL(\Pi,\chi)V\\
			\CH(\Pi,\chi)_{\mathrm{glob}}@>\CP>>\C,
		\end{CD}
	\end{equation}
    where the right vertical map is the multiplication by 
	\[
	\CL(\Pi,\chi):=\frac{\RL(0,\Pi\times\chi)}{\RL(0,\omega_{\Pi}\chi^n)}.
	\]
\end{prp}


\section{Special values of L-functions}

We are going to study the special values of L-functions through modular symbols and prove the main theorem.


\subsection{Some $\mathrm{Aut}(\C)$ actions}

We introduce the $\mathrm{Aut}(\C)$ actions on various representations.

\subsubsection{Finite dimensional representations}

For a dominant weight $\mu\in(\Z^n)^{\CE_{\rk}}$, we realize $F_{\mu}$ and its contragredient $F_{\mu}^{\vee}$ as the algebraic induction
\begin{equation}
	\label{algebraicinduction}
	F_{\mu}={^{\mathrm{alg}}\mathrm{Ind}^{\GL_n(\rk\otimes_{\BQ}\C)}_{\overline{\RB}_n(\rk\otimes_{\BQ}\C)}}\chi_{\mu},\qquad 	F_{\mu}^{\vee}={^{\mathrm{alg}}\mathrm{Ind}^{\GL_n(\rk\otimes_{\BQ}\C)}_{\RB_n(\rk\otimes_{\BQ}\C)}}\chi_{-\mu},
\end{equation}
where $\chi_{\mu}$ (resp. $\chi_{-\mu}$) is the algebraic character of $\RT_n(\rk\otimes_{\BQ}\C)$ corresponding to the weight $\mu$ (resp. $-\mu$). The highest weight vector $v_{\mu}\in(F_{\mu})^{\RN_n(\rk\otimes_{\BQ}\C)}$ and the lowest weight vector $v_{\mu}^{\vee}\in(F_{\mu}^{\vee})^{\overline{\RN}_n(\rk\otimes_{\BQ}\C)}$ are fixed such that $v_{\mu}(1_n)=v_{\mu}^{\vee}(1_n)=1$. The invariant pairing $\langle\cdot,\cdot\rangle:F_{\mu}\times F_{\mu}^{\vee}\to\C$ is normalized such that $\langle v_{\mu},v_{\mu}^{\vee}\rangle=1$. 

Let $\mathrm{Aut}(\C)$ acts on the space of algebraic functions on $\GL_n(\rk\otimes_{\BQ}\C)$ by
\[
({^{\sigma}f})(x):=\sigma(f(\sigma^{-1}(x))),\qquad x\in\GL_n(\rk\otimes_{\BQ}\C),
\]
where $\mathrm{Aut}(\C)$ acts on $\GL_n(\rk\otimes_{\BQ}\C)$ through its action on the second factor of $\rk\otimes_{\BQ}\C$. Using the above realizations for $F_{\mu}$ and $F_{\mu}^{\vee}$, this induces the $\sigma$-linear isomorphisms
\begin{equation}
\sigma:F_{\mu}\to F_{{^{\sigma}\mu}},\qquad \sigma:F^{\vee}_{\mu}\to F^{\vee}_{{^{\sigma}\mu}}
\end{equation}
for every $\sigma\in\mathrm{Aut}(\C)$, where
\[
	{^{\sigma}\mu}:=\{\mu^{\sigma^{-1}\circ\iota}\}_{\iota\in\CE_{\rk}}.
\]
This map also defines the $\sigma$-linear isomorphism for corresponding sheaves which further induces the $\sigma$-linear isomorphism for sheaf cohomology spaces. In particular we have the $\sigma$-linear isomorphism
\begin{equation}\label{sigmasheaf}
	\sigma:\RH^{b_n}(\CX_n,F_{\mu}^{\vee})\otimes\RH_{\mathrm{c}}^{b_n}(\CX_n,F_{\nu}^{\vee})\to\RH^{b_n}(\CX_n,F_{{^{\sigma}\mu}}^{\vee})\otimes\RH_{\mathrm{c}}^{b_n}(\CX_n,F_{{^{\sigma}\nu}}^{\vee}).
\end{equation}



\subsubsection{The representation $\Pi$}\label{sec:sigmapi}


Let $v$ be a non-archimedean place. We identify $\Pi_v$ with its Whittaker model $\CW(\Pi_v)$ by
\[
\Pi_v\xrightarrow{\sim}\CW(\Pi_v)\subset\mathrm{Ind}^{\GL_n(\rk_v)\times\GL_n(\rk_v)}_{\RN_n(\rk_v)\times\RN_n(\rk_v)}\psi_{n,v},\qquad\phi\mapsto\lambda_{\Pi_v}(g.\phi).
\]
For every $\sigma\in\mathrm{Aut}(\C)$, we have $\sigma$-linear isomorphism
\[
\sigma:\mathrm{Ind}^{\GL_n(\rk_v)\times\GL_n(\rk_v)}_{\RN_n(\rk_v)\times\RN_n(\rk_v)}\psi_{n,v}\to\mathrm{Ind}^{\GL_n(\rk_v)\times\GL_n(\rk_v)}_{\RN_n(\rk_v)\times\RN_n(\rk_v)}\psi_{n,v}
\]
defined as in \cite[Section 5.1]{LLS}, which further induces a $\sigma$-linear map
\[
\sigma:\CW(\Pi_v)\to\CW({^{\sigma}\Pi_v}):=\sigma(\CW(\Pi_v))\subset\mathrm{Ind}^{\GL_n(\rk_v)\times\GL_n(\rk_v)}_{\RN_n(\rk_v)\times\RN_n(\rk_v)}\psi_{n,v}.
\]
We then obtain a $\sigma$-linear isomorphism $\sigma:\Pi_v\to{^{\sigma}\Pi_v}$ and thereby
\begin{equation}\label{sigmapi}
	\sigma:\Pi_{\mathrm{f}}\to{^{\sigma}\Pi_{\mathrm{f}}}.
\end{equation}

We have the following lemma by \cite[Lemma 1.2]{G} (see also \cite[Theorem 3.13]{Clo} and \cite[Section 1.4.3]{GL}).

\begin{lemp}\label{lem5}
Let $\Sigma$ be a tamely isobaric irreducible smooth automorphic representation of $\GL_n(\A)$ which is regular algebraic with coefficient system $F_{\mu}$. Then for every $\sigma\in\mathrm{Aut}(\C)$, there is a unique (up to isomorphism) tamely isobaric irreducible smooth automorphic representation ${^{\sigma}\Sigma}$ of $\GL_n(\A)$ such that $({^{\sigma}\Sigma})_{\mathrm{f}}={^{\sigma}(\Sigma_{\mathrm{f}})}$. Moreover, ${^{\sigma}\Sigma}$ is regular algebraic with coefficient system $F_{^{\sigma}\mu}$.
\end{lemp}

For every $\sigma\in\mathrm{Aut}(\C)$, we define ${^{\sigma}\Pi}:={^{\sigma}\Sigma}\boxtimes{^{\sigma}\Sigma'}$, where ${^{\sigma}\Sigma}$ and ${^{\sigma}\Sigma'}$ are defined as in Lemma \ref{lem5}. In particular, $({^{\sigma}\Pi})_{\mathrm{f}}={^{\sigma}\Pi_{\mathrm{f}}}$ and ${^{\sigma}\Pi}$ is regular algebraic with coefficient system $F_{^{\sigma}\mu}\boxtimes F_{^{\sigma}\nu}$. The rationality field of $\Pi$, denoted by $\BQ(\Pi)$, is by definition the fixed field of the group of field automorphisms $\sigma\in\mathrm{Aut}(\C)$ such that ${}^\sigma\Pi \cong \Pi$. 

\subsubsection{The representation $I_{\eta,\chi}$}\label{sec:sigmachi}

For every algebraic Hecke character $\chi:\rk^{\times}\backslash\A^{\times}\to\C^{\times}$ and $\sigma\in\mathrm{Aut}(\C)$, there is a unique Hecke character ${^{\sigma}\chi}={^{\sigma}\chi_{\mathrm{f}}}\otimes{^{\sigma}\chi_{\infty}}$ with ${^{\sigma}\chi_{\mathrm{f}}}=\sigma\circ\chi_{\mathrm{f}}$. Moreover, 
\[
\{^{\sigma}\chi_{\iota}\}_{\iota\in\CE_{\rk}}=\{\chi_{\sigma^{-1}\circ\iota}\}_{\iota\in\CE_{\rk}},
\]
where we write
\[
\mathrm{d}{^{\sigma}\chi}:=\mathrm{d}{^{\sigma}\chi_{\infty}}:=\{^{\sigma}\chi_{\iota}\}_{\iota\in\CE_{\rk}}\in\Z^{\CE_{\rk}}.
\]
Note that ${^{\sigma}\eta}=\omega_{^{\sigma}\Pi}\cdot{^{\sigma}\chi^n}$. We have a $\sigma$-linear isomorphism
\begin{equation}\label{sigmaI}
\sigma:I_{\eta_{\mathrm{f}},\chi_{\mathrm{f}}}\to I_{{^{\sigma}\eta}_{\mathrm{f}},{^{\sigma}\chi}_{\mathrm{f}}},\qquad\varphi\mapsto\sigma\circ\varphi.
\end{equation}
Moreover, we have a factorization $I_{{^{\sigma}\eta},{^{\sigma}\chi}}=I_{{^{\sigma}\eta}_{\mathrm{f}},{^{\sigma}\chi}_{\mathrm{f}}}\otimes I_{{^{\sigma}\eta}_{\infty},{^{\sigma}\chi}_{\infty}}$. As in \eqref{sigmasheaf}, we also have the $\sigma$-linear isomorphisms
\[
\sigma:F_{\eta,\chi}^{\vee}\to F^{\vee}_{{^{\sigma}\eta},{^{\sigma}\chi}}\qquad\text{and}\qquad \sigma:\RH^{c_n}(\CX_n,F_{\eta,\chi}^{\vee})\to\RH^{c_n}(\CX_n,F^{\vee}_{{^{\sigma}\eta},{^{\sigma}\chi}}).
\]
In \cite{eisenstein}, we have defined the $\sigma$-linear isomorphisms
\[
\sigma:\CH(I_{\eta_{\infty},\chi_{\infty}})\to \CH(I_{{^{\sigma}\eta}_{\infty}{^{\sigma}\chi}_{\infty}})\qquad\text{and}\qquad\sigma:\CH(I_{\eta,\chi})\to\CH(I_{{^{\sigma}\eta},{^{\sigma}\chi}}),
\]
and proved that the diagram
\begin{equation}\label{diagrameis}
	\begin{CD}
		\CH(I_{\eta_{\infty},\chi_{\infty}})\otimes I_{\eta_{\mathrm{f}},\chi_{\mathrm{f}}} @>\iota_{\mathrm{can}}>> \CH(I_{\eta,\chi})@>\mathrm{Eis}_{\eta,\chi}>>\RH^{c_n}(\CX_n,F_{\eta,\chi}^{\vee})\\
		@V\sigma VV @V\sigma VV @VV\sigma V\\
		\CH(I_{{^{\sigma}\eta}_{\infty},{^{\sigma}\chi}_{\infty}})\otimes I_{{^{\sigma}\eta}_{\mathrm{f}},{^{\sigma}\chi}_{\mathrm{f}}} @>\iota_{\mathrm{can}}>>\CH(I_{{^{\sigma}\eta},{^{\sigma}\chi}}) @>\mathrm{Eis}_{{^{\sigma}\eta},{^{\sigma}\chi}}>>\RH^{c_n}(\CX_n,F^{\vee}_{{^{\sigma}\eta},{^{\sigma}\chi}})
	\end{CD}
\end{equation}
commutes.


\subsection{Non-archimedean period relations}
We say that an invariant measure $\mathrm{d}g\in\mathfrak{M}_{n,\mathrm{f}}$ on $\GL_n(\mathbb{A}_{\mathrm{f}})$ is rational if $\mathrm{d}g(K)\in\BQ$ for every open compact subgroup $K$ of $\GL_n(\mathbb{A}_{\mathrm{f}})$. All rational measures on $\GL_n(\mathbb{A}_{\mathrm{f}})$ form a rational structure of $\mathfrak{M}_{n,\mathrm{f}}$. For every $\sigma\in\mathrm{Aut}(\C)$, we define a $\sigma$-linear isomorphism
\begin{equation}\label{sigmaM}
	\sigma:\mathfrak{M}_{n,\mathrm{f}}\to\mathfrak{M}_{n,\mathrm{f}},
\end{equation}
with respect to its rational structure. From \eqref{sigmapi}, \eqref{sigmaI} and \eqref{sigmaM}, we obtain a $\sigma$-linear isomorphism
\begin{equation}
	\sigma:\CH(\Pi_{\mathrm{f}},\chi_{\mathrm{f}})\to\CH({^{\sigma}\Pi}_{\mathrm{f}},{^{\sigma}\chi_{\mathrm{f}}}).
\end{equation}

For each non-archimedean place $v$, denote by $\mathfrak{c}(\chi_v)$ and $\mathfrak{c}(\psi_v)$ the conductors of $\chi_v$ and $\psi_v$ respectively. Fix $y_v\in\rk_v^{\times}$ such that $\mathfrak{c}(\psi_v)=y_v\cdot\mathfrak{c}(\chi_v)$. Define the local Gauss sum by
\begin{equation}\label{localgauss}
\CG(\chi_v):=\CG(\chi_v,\psi_v):=\int_{\CO_v^{\times}}\chi_v(y_vx)^{-1}\cdot\psi_v(y_v x)\mathrm{d}x,
\end{equation}
where $\mathrm{d}x$ is the normalized Haar measure so that $\CO_{v}^{\times}$ has volume $1$. We note that above definition is independent of the choice of $y_v$. Define the Gauss sum of $\chi$ by
\begin{equation}\label{globalgauss}
\CG(\chi)=\prod_{v\nmid\infty}\CG(\chi_v).
\end{equation}
This is well defined since $\CG(\chi_v)=1$ for all but finitely many places $v\nmid\infty$.

For every $\sigma\in\mathrm{Aut}(\C)$, we define the linear functional
\[
{^{\sigma}\CP}_{\mathrm{f}}^{\circ}:=\CG({^{\sigma}\chi})^{\frac{n(n-1)}{2}}\cdot\CP_{{^{\sigma}\Pi_{\mathrm{f}}},{^{\sigma}\chi_{\mathrm{f}}}}:\CH({^{\sigma}\Pi_{\mathrm{f}}},{^{\sigma}\chi_{\mathrm{f}}})\to\C.
\]
When $\sigma$ is trivial, we simply write $\CP_{\mathrm{f}}^{\circ}$ for ${^{\sigma}\CP}_{\mathrm{f}}^{\circ}$. The non-archimedean period relation is the following commutative diagram
\begin{equation}
	\label{nonarchimedeanperioerelation}
	\begin{CD}
		\CH(\Pi_{\mathrm{f}},\chi_{\mathrm{f}}) @>\CP_{\mathrm{f}}^{\circ}>>\C\\
		@V\sigma VV @VV\sigma V\\
		\CH({^{\sigma}\Pi_{\mathrm{f}}},{^{\sigma}\chi_{\mathrm{f}}}) @>{^{\sigma}\CP}_{\mathrm{f}}^{\circ}>>\C,
	\end{CD}
\end{equation}
which can be obtained by the same proof of \cite[Proposition 5.1{\footnotemark[2]}, Proposition 7.4]{LLS} and we omit the straightforward computations. 
\footnotetext[2]{A corrigendum for \cite[Proposition 5.1]{LLS}: given a Haar measure on $\GL_{n-1}(\K)$ with $\K$ non-archimedean, one should take the quotient measure on $\RN_{n-1}(\K)\bs \GL_{n-1}(\K)$ by a rational measure on $\RN_{n-1}(\K)$ instead of the product of self-dual measures on $\K$.}


\subsection{Archimedean period relations}

Note that $\mathfrak{O}_{n,\infty}$ has a natural $\BQ$-rational structure and we obtain a $\sigma$-linear isomorphism
\begin{equation}\label{sigmao}
	\sigma:\mathfrak{O}_{n,\infty}\to\mathfrak{O}_{n,\infty}.
\end{equation}
We fix an orientation $\mathbf{o}_n$ of $\GL_n(\rk_{\infty})/\widetilde{K}_{n,\infty}$ which is a $\BQ$-rational generator of the one dimensional space $\mathfrak{O}_{n,\infty}$. 


%We take $\mathbf{o}_n$ to be a $\BQ$-rational generator of the one dimensional space $\mathfrak{O}_{n,\infty}$. 

Recall that $\dim\CH(\Pi_{\infty})=1$ and we are going to fix a generator $\kappa_{\mu,\nu}$ for this one dimensional space. We first consider the case $\mu=\nu=0_n$, where $0_n$ is the zero element of the abelian group $(\Z^n)^{\CE_{\rk}}$. Let $\chi_{\infty}^{\circ}=\prod_{v|\infty}\chi_v^{\circ}:\rk_{\infty}^{\times}\to\C^{\times}$ be the character such that
\[
\chi^{\circ}_v(x):=\begin{cases}
	\iota_v(x),\qquad \eta_{\iota_v}\geq\eta_{\overline{\iota}_v},\\
	\overline{\iota}_v(x),\qquad\eta_{\iota_v}\leq\eta_{\overline{\iota}_v},
\end{cases}
\]
for every archimedean place $v$ and every $x\in\rk_v^{\times}$. We take $\kappa_{0_n,0_n}$ such that
\[
\CP_{\infty}\left(\kappa_{0_n,0_n}\otimes\kappa_{\chi^{\circ n}_{\infty},\chi^{\circ}_{\infty}}\otimes\mathbf{o}_n\right)=1,
\]
where $\kappa_{\chi^{\circ n}_{\infty},\chi^{\circ}_{\infty}}\in\CH(I_{\chi^{\circ n}_{\infty},\chi^{\circ}_{\infty}})$ is the generator fixed as in \cite[Section 5.1]{eisenstein}. In general, we define $\kappa_{\mu,\nu}:=\jmath_{\mu,\nu}(\kappa_{0_n,0_n})$, where $\jmath_{\mu,\nu}:=\jmath_{\mu}\otimes\jmath_{\nu}$ is the translation map defined in \cite[Proposition 1.1]{local}. 

For every $\sigma\in\mathrm{Aut}(\C)$, with respect to above choice of generators, we define a $\sigma$-linear isomorphism
\begin{equation}
	\sigma:\CH(\Pi_{\infty})\to\CH({^{\sigma}\Pi_{\infty}})
\end{equation}
such that $\sigma(\kappa_{\mu,\nu})=\kappa_{{^{\sigma}\mu},{^{\sigma}\nu}}$. Define the normalized archimedean modular symbol
\[
{^{\sigma}\CP}_{\infty}^{\circ}:=\Omega_{\infty}({^{\sigma}\Pi},{^{\sigma}\chi})^{-1}\cdot\CP_{{^{\sigma}\Pi_{\infty}},{^{\sigma}\chi_{\infty}}}:\CH({^{\sigma}\Pi_{\infty}},{^{\sigma}\chi_{\infty}})\to\C,
\]
where the constant $\Omega_{\infty}({^{\sigma}\Pi},{^{\sigma}\chi})\in\C^{\times}$ is defined as in \eqref{omegainfty}. We simply write ${\CP}_{\infty}^{\circ}$ and omit $\sigma$ whenever it is trivial. The archimedean period relation is the following commutative diagram
\begin{equation}\label{archimedeanperiodrelation}
	\begin{CD}
		\CH(\Pi_{\infty},\chi_{\infty}) @>\CP_{\infty}^{\circ}>>\C\\
		@V\sigma VV @VV\sigma V\\
		\CH({^{\sigma}\Pi_{\infty}},{^{\sigma}\chi_{\infty}}) @>{^{\sigma}\CP}_{\infty}^{\circ}>>\C,
	\end{CD}
\end{equation}
which can be obtained directly from \cite[Theorem 1.6]{local} (see also \cite[Proposition 7.3]{LLS}).


\subsection{Global period relations}

We are now going to prove Theorem \ref{mainthm}. 

The same argument in \cite[Section 6]{LLS} shows that there is a family
\begin{equation}\label{whittakerperiod}
	\{\Omega(\Pi')\}_{\Pi'\in\{{^{\sigma}\Pi}\colon\sigma\in\mathrm{Aut}(\C)\}}\in\C^{\times},
\end{equation}
to be called the Whittaker period, such that the diagram
\begin{equation}\label{diagrampi}
	\begin{CD}
		\CH(\Pi_{\infty})\otimes\Pi_{\mathrm{f}} @>\iota_{\mathrm{can}}>> \CH(\Pi) @>\Omega(\Pi)^{-1}\cdot\iota_{\Pi}>>\RH^{b_n}(\CX_n,F_{\mu}^{\vee})\otimes\RH_{\mathrm{c}}^{b_n}(\CX_n,F_{\nu}^{\vee})\\
		@V\sigma VV @VV\sigma V @VV\sigma V\\
		\CH({^{\sigma}\Pi_{\infty}})\otimes{^{\sigma}\Pi_{\mathrm{f}}} @>\iota_{\mathrm{can}}>>\CH({^{\sigma}\Pi}) @>\Omega({^{\sigma}\Pi})^{-1}\cdot\iota_{{^{\sigma}\Pi}}>>\RH^{b_n}(\CX_n,F_{{^{\sigma}\mu}}^{\vee})\otimes\RH_{\mathrm{c}}^{b_n}(\CX_n,F_{{^{\sigma}\nu}}^{\vee}),
	\end{CD}
\end{equation}
commutes for every $\sigma\in\mathrm{Aut}(\C)$. Here the middle vertical arrow is defined such that the left square is commutative. 

%\begin{remarkp}
%The argument in \cite[Section 6]{LLS} for tamely isobaric representations generalizes directly to the situation here. We remark that the assumption of `holomorphic type' seems necessary in proving that (\cite[Proposition 6.2]{LLS})
%\[
%\mathrm{dim}_{\GL_n(\mathbb{A}_{\mathrm{f}})\times\GL_n(\A_{\mathrm{f}})}\left(\CH(\Pi),\RH^{b_n}(\CX_n,F_{\mu}^{\vee})\otimes\RH_{\mathrm{c}}^{b_n}(\CX_n,F_{\nu}^{\vee})\right)=1.
%\]
%See \cite[Proposition 1.6]{G} and \cite[Proposition 1.19, 1.21]{GL} for details.
%\end{remarkp}

For every $\sigma\in\mathrm{Aut}(\C)$, denote
\[
{^{\sigma}\CL}:=\frac{\RL(0,{^{\sigma}\Pi}\times{^{\sigma}\chi})}{\RL(0,\omega_{^{\sigma}\Pi}\cdot{^{\sigma}\chi}^n)\cdot\CG({^{\sigma}\chi})^{\frac{n(n-1)}{2}}\cdot\Omega_{\infty}({^{\sigma}\Pi},{^{\sigma}\chi})\cdot\Omega({^{\sigma}\Pi})}.
\]	
The symbol $\sigma$ will be omitted from the notation if it is trivial. We need to prove that 
\begin{equation}
	\label{thmsigma'}
\sigma(\CL)={^{\sigma}\CL},
\end{equation}
	which is \eqref{thmsigma}, from which \eqref{thmquotient} follows immediately.

	We form the following diagram
	\begin{equation}
		\label{diagram}
		\xymatrixrowsep{0.3in}
		\xymatrixcolsep{0.35in}
		\xymatrix{
			\mathcal{H}(\Pi,\chi)_{\mathrm{loc}} \ar[rd]^{\sigma} \ar[ddd]_{\iota_{\mathrm{can}}} \ar[rrr]^{  \CP^{ \circ}_{\mathrm{f}}\otimes  \CP^{ \circ}_{\infty} } 
			&&& \BC \ar^\sigma[rrd] \ar^{ \sigma}[rrd] \ar[ddd]^{\mathcal{L}}|!{[dll];[dr]}\hole & \\
			&\mathcal{H}({^{\sigma}\Pi},{^{\sigma}\chi})_{\mathrm{loc}}  \ar[ddd]_{\iota_{\mathrm{can}}}  \ar[rrrr]^(0.4){ {^{\sigma}\CP}^{\circ}_{\mathrm{f}}\otimes  {^{\sigma}\CP}^{ \circ}_{\infty} } 
			&&& & \BC  \ar[ddd]^{^{\sigma}\mathcal{L}}\\
			&&& & \\
			\mathcal{H}(\Pi,\chi)_{\mathrm{glob}} \ar[rd]_{\sigma} \ar[rrr]^(0.6){\Omega(\Pi)^{-1}\cdot\CP} |!{[ur];[dr]}\hole
			&& & \BC \ar[drr]^{\sigma}  & \\
			& 	\mathcal{H}({^{\sigma}\Pi},{^{\sigma}\chi})_{\mathrm{glob}}\ar[rrrr]^{\Omega({^{\sigma}\Pi})^{-1}\cdot{}^\sigma\CP} 
			&&& & \BC.
		}
	\end{equation}
	Then \eqref{thmsigma'} is the commutativity of the right square of \eqref{diagram}. It suffices to show the commutativity of other squares of the cubic diagram. The front and back squares are commutative by \eqref{frontback}. The left square commutes by the left square in \eqref{diagrameis} and \eqref{diagrampi}. The bottom square is commutative by \cite[Proposition 3.14]{Rag1} and the right  square in \eqref{diagrameis} and \eqref{diagrampi}. The top square is commutative by the non-archimedean period relation \eqref{nonarchimedeanperioerelation} and the archimedean period relation \eqref{archimedeanperiodrelation}. We therefore obtain \eqref{thmsigma'} and completes the proof of Theorem \ref{mainthm}.

\begin{comment}
We finally deduce a corollary from Theorem \ref{mainthm}, which is also obtained in \cite[Theorem]{R-imaginary}. Recall that $\rk$ contains a CM subfield. Denote the maximal CM subfield of $\rk$ by $\rk_1$, which is a totally imaginary quadratic extension of the maximal totally real subfield $\rk_0$ in $\rk$. We write $\rk_1:=\rk_0(\sqrt{D})$ for some totally negative $D\in\rk_0$ and set
\[
