\]
where $\RN_{\rk_0/\BQ}$ is the norm map.


\begin{corp}
    \label{corollary} 
    Keep the assumption for $\Pi$ as in Theorem \ref{mainthm} and assume that both $\chi$ and $\chi|\cdot|_{\A}$ are $(\mu,\nu)$-balanced. Then for any $\sigma\in\mathrm{Aut}(\C)$, we have
\begin{equation}
    \sigma\left((\mathrm{i}^{\frac{[\rk:\BQ]}{2}}\cdot\Delta_{\rk})^{n^2}\frac{\RL(0,\Pi\times\chi)}{\RL(0,\Pi\times\chi|\cdot|_{\A})}\right)=(\mathrm{i}^{\frac{[\rk:\BQ]}{2}}\cdot\Delta_{\rk})^{n^2}\frac{\RL(0,{^{\sigma}\Pi}\times{^{\sigma}\chi})}{\RL(0,{^{\sigma}\Pi}\times{^{\sigma}\chi}|\cdot|_{\A})}.
\end{equation}
\end{corp}	

\begin{proof}
    Denote $\mathbf{n}(\sigma)$ to be the cardinality of the set $\{v|\infty:\varepsilon_{^{\sigma}\Pi,v}=-\varepsilon_{\Pi,\chi,v}\}$. We need to show that
    	\begin{equation}\label{equality}
			(-1)^{\mathbf{n}(\sigma)}=\frac{\sigma(\Delta_{\rk})}{\Delta_{\rk}}.
		\end{equation}

		Assume $[\rk:\rk_1]=r_2$ and $[\rk_0:\BQ]=r_1$ with $[\rk:\BQ]=r_1r_2$. Denote $\mathcal{E}_{\rk_0}=\{\tau_1',\dots,\tau_{r_1}'\}$ for the set of field embeddings of $\rk_0$ and $\mathcal{E}_{\rk_1}=\{\tau_1,\overline{\tau}_1,\dots,\tau_{r_1},\overline{\tau}_{r_1}\}$ the set of field embeddings of $\rk_1$. We assume that $\{\tau_i,\overline{\tau}_i\}$ is the fiber of the restriction $\mathcal{E}_{\rk_1}\to\mathcal{E}_{\rk_0}$ over $\tau_i'$ with $\tau_i(\sqrt{D})=\sqrt{D}$ and $\overline{\tau}_i(\sqrt{D})=-\sqrt{D}$. Then
